[breakpoints.up('desktop')]: {\n            ...mobile, // Apply mobile styles by default for desktop breakpoints\n            ...(desktop == null\n              ? null\n              : {\n                  ...desktop,\n                }),\n          },\n        }),\n\n    ...(tablet == null\n      ? null\n      : {\n          [breakpoints.only('tablet')]: {\n            ...tablet,\n          },\n        }),\n\n    ...(desktop == null\n      ? null\n      : {\n          [breakpoints.up('desktop')]: {\n            ...desktop,\n          },\n        }),\n  };\n};\n\nconst fixJustifyContentIssue = (\n  styles:\n    | Partial<CSSProperties | Record<keyof CSSProperties, string | number>>\n    | undefined,\n) => {\n  // This is a workaround for a bug in the styling library\n  // that causes the `justifyContent` property to be invalid\n\n  if (styles == null) return null;\n  if ('justifyContent' in styles && styles.justifyContent != null) {\n    // i.e. var(--mui-components-overview-flexibleRemittanceRate-calculator-buttons-mobile-justifyContent, end)\n    const currentValueWithFallback = styles.justifyContent.toString();\n    const [, fallbackValueWithBracket] = currentValueWithFallback.split(',');\n    const fallbackValueWithBracketTrimmed = fallbackValueWithBracket\n      .replace(')', '')\n      .trim();\n    return {\n      ...styles,\n      justifyContent: fallbackValueWithBracketTrimmed,\n    } as typeof styles;\n  }\n\n  return styles;\n};\n\n/**\n * `customized` is a Higher-Order Component (HOC) that enriches a given component with customizations.\n * It allows you to apply platform-specific customizations to the component.\n *\n * @param component - The React functional component to be customized.\n * @param customizationProvider - A function that provides the customizations based on the platform.\n *\n * @returns A new component that includes the provided customizations.\n *\n * Note: When using this HOC with the `Typography` component, ensure that each customization breakpoint\n * is explicitly set for both mobile and desktop views to avoid layout issues.\n *\n * Example usage:\n *\n * ```tsx\n * const CustomizedTypography = customized(Typography (c) => c?.renewal?.cardTitle);\n *\n * <CustomizedTypography size='md'>\n *   Customized Text\n * </CustomizedTypography>\n * ```\n */\nexport const customized = <TProps extends object>(\n  component: FunctionComponent<TProps>,\n  customizationProvider: (\n    customizations: PlatformCustomization | undefined,\n  ) =>\n    | WithBreakpoints<\n        CSSProperties | Record<keyof CSSProperties, string | number>\n      >\n    | undefined,\n) => {\n  return styled(component)(({ theme }) => ({\n    ...customizeStyles(theme, customizationProvider),\n  }));\n};\n","import styled from '@emotion/styled';\nimport {\n  Accordion,\n  AccordionDetails,\n  AccordionSummary,\n  AccordionSummaryProps,\n  accordionClasses,\n  accordionSummaryClasses,\n} from '@mui/material';\n\nimport { Icons } from '../Icons';\nimport { customizeStyles } from '../customizeStyles';\n\nexport const AccordionRoot = styled(Accordion)(\n  ({ theme: { vars }, theme }) => ({\n    [`&.${accordionClasses.root}`]: {\n      borderBottom: `1px solid ${vars.components?.variables.colors?.grey300}`,\n      padding: vars.components?.variables.spacings.md,\n      width: '100%',\n\n      boxShadow: 'none',\n      margin: 0,\n\n      '&::before': {\n        display: 'none',\n      },\n\n      '&:last-of-type': {\n        border: 0,\n      },\n\n      ...customizeStyles(theme, (c) => c?.dropdown?.accordion),\n    },\n  }),\n);\n\nexport const AccordionTitle = styled((props: AccordionSummaryProps) => (\n  <AccordionSummary {...props} expandIcon={<Icons.ChevronRightIcon />} />\n))(({ theme }) => ({\n  fontFamily: theme.vars.components?.variables.typography?.desktop.family.body,\n\n  fontSize: theme.vars.components?.variables.typography?.desktop.size.md,\n  fontWeight:\n    theme.vars.components?.variables.typography?.desktop.weight?.strong,\n  lineHeight:\n    theme.vars.components?.variables.typography?.desktop.lineHeight.md,\n\n  display: 'flex',\n  alignItems: 'center',\n  gap: theme.vars.components?.variables.spacings.xl,\n\n  [theme.breakpoints.only('mobile')]: {\n    fontSize: theme.vars.components?.variables.typography?.mobile.size.md,\n    fontWeight:\n      theme.vars.components?.variables.typography?.mobile.weight?.strong,\n    lineHeight:\n      theme.vars.components?.variables.typography?.mobile.lineHeight.md,\n  },\n\n  [`&.${accordionSummaryClasses.root}`]: {\n    padding: 0,\n    minHeight: 'auto',\n  },\n\n  [`& > .${accordionSummaryClasses.content}`]: {\n    margin: '0',\n\n    [`&.${accordionSummaryClasses.expanded}`]: {\n      margin: '0',\n    },\n  },\n\n  [`& .${accordionSummaryClasses.expandIconWrapper}`]: {\n    transform: 'rotate(90deg)',\n\n    alignSelf: 'flex-start',\n    marginTop: 2,\n\n    '& svg': {\n      fill: theme.vars.components?.variables.colors?.grey900,\n    },\n\n    ...customizeStyles(theme, (c) => c?.dropdown?.summaryArrow?.default),\n\n    [`&.${accordionSummaryClasses.expanded}`]: {\n      transform: 'rotate(-90deg)',\n\n      ...customizeStyles(theme, (c) => c?.dropdown?.summaryArrow?.expanded),\n    },\n  },\n  ...customizeStyles(theme, (c) => c?.dropdown?.summary),\n}));\n\nexport const AccordionContent = styled(AccordionDetails)(({ theme }) => ({\n  fontSize: theme.vars.components?.variables.typography?.desktop.size.sm,\n  lineHeight:\n    theme.vars.components?.variables.typography?.desktop.lineHeight?.sm,\n  padding: 0,\n  paddingTop: theme.vars.components?.variables.spacings.md,\n\n  [theme.breakpoints.only('mobile')]: {\n    fontSize: theme.vars.components?.variables.typography?.mobile.size.sm,\n    lineHeight:\n      theme.vars.components?.variables.typography?.mobile.lineHeight?.sm,\n  },\n\n  ...customizeStyles(theme, (c) => c?.dropdown?.details),\n}));\n","import {\n  AccordionRoot,\n  AccordionContent,\n  AccordionTitle,\n} from './Accordion.styled';\n\nexport const Accordion = {\n  Root: AccordionRoot,\n  Title: AccordionTitle,\n  Content: AccordionContent,\n};\n","import {\n  createContext,\n  FunctionComponent,\n  PropsWithChildren,\n  useCallback,\n  useContext,\n  useState,\n} from 'react';\n\nexport type FeatureFlagId =\n  | 'new-entry-point'\n  | 'new-landing-page'\n  | 'sdd-collections';\n\nexport interface FeatureFlag {\n  id: FeatureFlagId;\n  label: string;\n  enabled: boolean;\n}\n\nconst featureFlags: FeatureFlag[] = [\n  {\n    id: 'new-entry-point',\n    label: 'New Entry Point',\n    enabled: false,\n  },\n  {\n    id: 'new-landing-page',\n    label: 'New Landing Page',\n    enabled: false,\n  },\n  {\n    id: 'sdd-collections',\n    label: 'SDD collection',\n    enabled: true,\n  },\n] as const;\n\nexport interface FeatureFlagsContextValue {\n  toggles: FeatureFlag[];\n  setToggle: (id: FeatureFlagId, enabled: boolean) => void;\n  isToggleEnabled: (id: FeatureFlagId | null) => boolean;\n}\n\nexport const FeatureFlagsContext = createContext<FeatureFlagsContextValue>(\n  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion\n  null!,\n);\n\nexport const FeatureFlagsProvider: FunctionComponent<PropsWithChildren> = ({\n  children,\n}) => {\n  const [toggles, setToggles] = useState<FeatureFlag[]>(featureFlags);\n\n  const setToggle = (id: FeatureFlagId, enabled: boolean) => {\n    const newToggles = toggles.map((toggle) =>\n      toggle.id === id ? { ...toggle, enabled } : toggle,\n    );\n    setToggles(newToggles);\n  };\n\n  const isToggleEnabled = useCallback(\n    (id: FeatureFlagId | null) => {\n      if (id == null) {\n        return false;\n      }\n\n      return toggles.find((toggle) => toggle.id === id)?.enabled ?? false;\n    },\n    [toggles],\n  );\n  return (\n    <FeatureFlagsContext.Provider\n      value={{\n        toggles,\n        setToggle,\n        isToggleEnabled,\n      }}\n    >\n      {children}\n    </FeatureFlagsContext.Provider>\n  );\n};\n\nexport const useFeatureFlags = () => {\n  return useContext(FeatureFlagsContext);\n};\n","import { ENVIRONMENT } from '@finmid/environment';\nimport { useFeatureFlags } from '@finmid/tiger-webapp/feature-flags';\nimport { lazy, Suspense } from 'react';\n\nconst LazyManager =\n  ENVIRONMENT === 'live'\n    ? () => null\n    : lazy(() => import('./OverridesManagerWithPlatformCheck'));\n\nexport const OverridesManager = () => {\n  const featureFlags = useFeatureFlags();\n\n  if (ENVIRONMENT === 'live' || ENVIRONMENT === 'test') {\n    return null;\n  }\n\n  if (featureFlags == null) {\n    return null;\n  }\n\n  return (\n    <Suspense fallback={null}>\n      <LazyManager />\n    </Suspense>\n  );\n};\n","import { ENVIRONMENT } from '@finmid/environment';\nimport {\n  CapitalPlusLogicalStatus,\n  ReviewStatus,\n} from '@finmid/tiger-webapp/shared';\nimport {\n  createContext,\n  FunctionComponent,\n  PropsWithChildren,\n  useCallback,\n  useContext,\n} from 'react';\nimport { useNavigate, useSearchParams } from 'react-router-dom';\nimport { useLocalStorage } from 'react-use';\n\nimport type dashboardSimulation from './dashboardSimulation.json';\n\nexport const colors = [\n  'primaryDefault',\n  'primaryAccent',\n  'secondaryDefault',\n  'secondaryAccent',\n] as const;\nexport type ColorsOverrides = (typeof colors)[number];\n\nexport const offersOverrideOptions = [\n  'no-override',\n  'multiple',\n  'single',\n  'expired',\n  'rejected',\n] as const;\nexport type OffersOverride = (typeof offersOverrideOptions)[number];\n\nexport const collectionMethodOptions = [\n  'no-override',\n  'DIRECT_DEBIT',\n  'PLATFORM_TRANSFER',\n  'PAY_BY_INVOICE',\n] as const;\nexport type CollectionMethodOverride = (typeof collectionMethodOptions)[number];\n\nexport interface Overrides {\n  environment: string;\n  platformId?: string;\n  name?: string;\n  websiteLogo?: string;\n  offers?: OffersOverride;\n  maxStatus?: CapitalPlusLogicalStatus;\n  collectionMethod?: CollectionMethodOverride;\n  soleProprietor?: boolean;\n\n  offerReviewStatus?: ReviewStatus;\n\n  experimentalTranslations?: boolean;\n\n  hasApprovedOnboarding?: true;\n\n  simulateEmbedding?: boolean;\n  simulatedDashboard?: typeof dashboardSimulation;\n\n  skip2FA?: boolean;\n\n  colors?: Partial<Record<ColorsOverrides, string>>;\n}\n\nexport interface ContextValue {\n  overrides?: Overrides;\n  setOverrides: (overrides?: Overrides, reload?: boolean) => void;\n}\n\nexport const OverridesContext = createContext<ContextValue>({\n  setOverrides: () => {},\n});\n\nexport const OverridesProvider: FunctionComponent<\n  PropsWithChildren<{ fixedOverrides?: Overrides }>\n> = ({ children, fixedOverrides }) => {\n  const [overrides, setOverrides] = useLocalStorage<Overrides>('overrides');\n  const navigate = useNavigate();\n\n  const updateOverrides = useCallback(\n    (newOverrides?: Overrides, reload = false) => {\n      setOverrides(newOverrides);\n      if (reload) {\n        navigate('/');\n        window.location.reload();\n      }\n    },\n    [navigate, setOverrides],\n  );\n\n  return (\n    <OverridesContext.Provider\n      value={{\n        overrides:\n          ENVIRONMENT === 'live' ? undefined : fixedOverrides ?? overrides,\n        setOverrides: updateOverrides,\n      }}\n    >\n      {children}\n    </OverridesContext.Provider>\n  );\n};\n\nexport const useOverrides = () => {\n  return useContext(OverridesContext);\n};\n\nexport const usePlatformFromUrlOverride = (): Overrides | null => {\n  const [searchParams] = useSearchParams();\n  const platformId = searchParams.get('platformId');\n\n  if (platformId == null) {\n    return null;\n  }\n\n  return {\n    environment: 'staging',\n    platformId,\n  };\n};\n","import type { CountryIso3Code } from '@finmid/countries';\nimport { fromEnvironment } from '@finmid/environment';\nimport { AispProviderType, AispScope } from '@finmid/tiger-webapp/queries';\nimport { ReviewStatus } from '@finmid/tiger-webapp/shared';\nimport { FunctionComponent, ReactElement } from 'react';\n\nimport { ToggleProps } from '../Toggle';\n\nimport { PlatformCustomization } from './PlatformCustomization';\n\nexport type CustomisationSlot = {\n  'copy.email': undefined;\n  'review.end': undefined;\n  'layout.header': undefined;\n  'more.questions': undefined;\n\n  'component.toggle': ToggleProps;\n\n  'embedded.header.back-button': undefined;\n  'expired.contactSupport': undefined;\n  'offer.header': undefined;\n  'offer.overview': undefined;\n  'dashboard.documents.contactsDisclaimer': undefined;\n  'dashboard.helpCenter.contactsDisclaimer': undefined;\n  'dashboard.helpCenter.faq.card.header': undefined;\n  'renewal.overview': undefined;\n  'renewal.hero.mobile': undefined;\n  'renewal.plan.footer.mobile': undefined;\n  'renewal.plan.faq.sectionTitle': undefined;\n  'renewal.plan.faq.cardHeader': undefined;\n  'renewal.plan.faq.cardDescription': undefined;\n  'feedbackWidget.successImage': undefined;\n  'feedbackPopup.successImage': undefined;\n  'plus.review': undefined;\n  'plus.rejected.image': undefined;\n  'plus.rejected.message': undefined;\n  'plus.secureBankConnection.FAQs.button': {\n    onClick: () => void;\n  };\n  'plus.connectingApps.feedbackSuccess': undefined;\n  'offer.rejected.image': undefined;\n  'faq.card.header': undefined;\n  'plus.bank.connectedIcon': undefined;\n  'overview.mobile.visual': undefined;\n  'shield.icon': undefined;\n  'verify.code.icon': undefined;\n  'soleProprietor.onItsWayVisual': undefined;\n  'soleProprietor.uploadDocument': undefined;\n  'soleProprietor.inReviewVisual': undefined;\n  'boostMyLimit.image': undefined;\n  'plus.capitalMaxUserResearch': undefined;\n  'expiredOffer.visual.request': undefined;\n  'expiredOffer.visual.thankyou': undefined;\n  'howItWorksMultiStep.visuals.confirmIdentity.image': undefined;\n  'howItWorksMultiStep.visuals.receiveYourFunds.image': undefined;\n  'howItWorksMultiStep.visuals.receiveYourFunds.text': undefined;\n  'offersPage.offer.typicallyUsedFor': undefined;\n  'faqs.introSection': undefined;\n  'review.payment.method': undefined;\n  'review.summary': undefined;\n  'review.summary.iban-accordion': undefined;\n  'review.useOfFunds': undefined;\n  'soleProprietor.uploadsDocs.documentsNeededExample': undefined;\n  'soleProprietor.uploadsDocs.documentsNeededModal': { onClose: () => void };\n  'review.line-item': {\n    title: string;\n    value: string | ReactElement;\n    details?: string;\n    notice?: ReactElement;\n  };\n\n  'whatsapp.floating-button': {\n    overStickyNavigation?: boolean;\n    withSpacerOnMobile?: boolean;\n    withNeedHelpMessage?: boolean;\n  };\n  'whatsapp.chat-container.close-button': undefined;\n  'getFunds.reviewStatusIcon': {\n    paymentReviewStatus: ReviewStatus;\n  };\n  'getFunds.statusText': {\n    paymentReviewStatus: ReviewStatus;\n    iban: string;\n  };\n  'getFunds.belowPaymentPlanButton': undefined;\n  'getFunds.paymentPlanButton': {\n    hasLatestCreditPaidOut: boolean;\n  };\n  'verifyPhone.button': undefined;\n  'faqs.categories.card.icon': undefined;\n\n  // Phone confirmation for skip2FA flow and SMS_WITH_IBAN_UPDATE flow.\n  // `mode` is optional for backward compatibility — defaults to `skip2FA`.\n  // `onIbanChange` / `onVerificationModeChange` are only used in\n  // `smsWithIbanUpdate` mode; the parent forwards the captured values to\n  // `accept-offer` so the BE branches + persists atomically.\n  'review.phoneConfirmation': {\n    mode?: 'skip2FA' | 'smsWithIbanUpdate';\n    phoneLastFour: string;\n    phoneChoice: 'confirm' | 'change';\n    onPhoneChoiceChange: (choice: 'confirm' | 'change') => void;\n    newPhone: string;\n    onNewPhoneChange: (phone: string) => void;\n    onNewPhoneVerified: (code: string) => void;\n    onIbanChange?: (iban: string | null) => void;\n    onVerificationModeChange?: (\n      mode: 'PLATFORM_PHONE' | 'BACKUP_PHONE_WITH_IBAN' | undefined,\n    ) => void;\n  };\n\n  // myPOS custom slots\n  'getFunds.custom': undefined;\n  'review.verifyIdentity': undefined;\n  'overview.routes': undefined;\n  'help.routes': undefined;\n  'review.routes': undefined;\n  'backToOffers.widget': { to: string };\n\n  // Signature flow\n  'signature.page': undefined;\n  'signature.phoneCard': { phoneLastFour: string };\n};\n\nexport interface PlatformSettings {\n  experiments?: {\n    businessAgeCallout?: CountryIso3Code[];\n    stripe?: boolean;\n    referralCode?: CountryIso3Code[];\n    connectingAppsFeedback?: CountryIso3Code[];\n    autoAcceptConsent?: boolean;\n    fullScreenModal?: boolean;\n    desktopConsentPopup?: boolean;\n    soleProprietorEnabled?: CountryIso3Code[];\n    whatsApp?: {\n      number: string;\n    };\n    changePhoneFlow?: boolean | CountryIso3Code[];\n    capitalMaxUserResearch?: CountryIso3Code[];\n    capitalPlusInReviewRoute?: string;\n  };\n  localization: LocalizationSettings;\n  resourcesPath: string;\n  feeDiscount?: number;\n  customization?: PlatformCustomization;\n  options?: {\n    onboarding?: {\n      apply?: {\n        minAmount?: number;\n        maxAmount?: number;\n      };\n    };\n  };\n  countryOptions?: PlatformSettingsCountryOptions;\n  embedding?: {\n    frameTargetOrigin?: string;\n    alwaysEmbed?: boolean;\n  };\n  slots?: Partial<CustomisationSlotComponents>;\n}\n\nexport type CustomisationSlotKey = keyof CustomisationSlot;\nexport type CustomisationSlotComponents = {\n  [key in CustomisationSlotKey]: CustomisationSlot[key] extends object\n    ? FunctionComponent<CustomisationSlot[key]>\n    : FunctionComponent;\n};\n\ntype PartialRecord<K extends keyof never, T> = {\n  [P in K]?: T;\n};\n\nexport type CountryOptionsRecord<T> = PartialRecord<CountryIso3Code, T>;\nexport type PlatformSettingsCountryOptions = CountryOptionsRecord<{\n  /**\n   * @default 'off'\n   */\n  aisp?:\n    | 'off'\n    | {\n        provider: AispProviderType;\n        /**\n         * Defines in which parts of the app AISP will be enabled\n         */\n        scopes: AispScope[];\n      };\n  platformName?: string;\n  logo?: string;\n}>;\n\nexport const defaultSettings: PlatformSettings = {\n  resourcesPath: '/',\n  localization: {\n    project: fromEnvironment('LOCIZE_PROJECT_ID'),\n  },\n};\n\nexport type LocalizationSettings = {\n  project: string;\n  allowedLocales?: string[];\n  allowCimode?: boolean;\n  defaultVariables?: LocalizationVariables;\n};\n\nexport type LocalizationVariables = {\n  platform?: string;\n  productName?: 'Capital' | string;\n  fullProductName?: string;\n  supportEmail?: string;\n};\n","import { formatISO } from 'date-fns/formatISO';\n\nconst sanitize = (input: string | number) => {\n  const value = input.toString();\n\n  if (\n    value.includes(',') ||\n    value.includes('\"') ||\n    value.includes('\\r') ||\n    value.includes('\\n')\n  ) {\n    return `\"${value.replace('\"', '\"\"')}\"`;\n  }\n\n  return value;\n};\n\nexport const downloadCsvFile = <T, K extends keyof T>(\n  headers: string[],\n  keys: K[],\n  items: T[],\n  options: {\n    fileName: string;\n    separator: ',' | ';';\n  },\n) => {\n  const { separator, fileName } = options;\n  let csv = headers.join(separator);\n\n  for (const item of items) {\n    const line = keys\n      .map((k) => {\n        const cell = item[k];\n\n        if (cell instanceof Date)\n          return formatISO(cell, { representation: 'date' });\n\n        return cell == null ? '' : String(cell);\n      })\n      .map(sanitize)\n      .join(separator);\n\n    csv += `\\r\\n${line}`;\n  }\n\n  downloadRawCsv(fileName, csv);\n};\n\nexport const downloadRawCsv = (fileName: string, rawCsv: string) => {\n  const link = document.createElement('a');\n  link.id = 'download-csv';\n  link.setAttribute(\n    'href',\n    'data:text/plain;charset=utf-8,' + encodeURIComponent(rawCsv),\n  );\n  link.setAttribute('download', fileName);\n  document.body.appendChild(link);\n  link.click();\n  document.body.removeChild(link);\n};\n","import { PlatformData } from '@finmid/api/internal/platform';\nimport { createContext } from 'react';\n\nconst emptyPlatform: PlatformData = {\n  id: '',\n  name: '',\n  fullName: '',\n  brandColors: ['', '', '', '', '', '', '', '', '', ''],\n  websiteLogo: '',\n  emailLogo: '',\n  cardLogo: '',\n  favicon: '',\n  authClientId: '',\n  primaryDomain: '',\n  authDomain: '',\n};\n\nexport const PlatformContext = createContext(emptyPlatform);\n\nexport const PlatformProvider = PlatformContext.Provider;\n","import { PlatformData } from '@finmid/api/internal/platform';\nimport { useContext } from 'react';\n\nimport { PlatformContext } from './PlatformContext';\n\nexport const usePlatform = (): PlatformData => {\n  const platform = useContext(PlatformContext);\n\n  return platform;\n};\n","import { MfaMethod } from '@finmid/distributor-types';\nimport { isBefore } from 'date-fns';\n\nexport type UnixTime = number;\n\nexport type UserType = 'SME_USER' | 'DISTRIBUTOR_USER' | 'FINMID_USER';\n\nexport type JwtObject = {\n  // expiration time\n  exp: UnixTime;\n\n  // issued at\n  iat: UnixTime;\n\n  // time when authentication occurred\n  auth_time: UnixTime;\n\n  // jwt id\n  jti: string;\n\n  // issuer, who created and signed the token\n  iss: string;\n\n  // audience, who or what this token is intended for\n  aud: string;\n\n  // subject, whom the token refers to\n  sub: string;\n\n  // type of token (\"Bearer\", for instance)\n  typ: string;\n\n  // authorized party (the party to which this token was issued)\n  azp: string;\n\n  // authentication context class\n  acr: string;\n\n  // session id\n  sid: string;\n\n  /**\n   * Properties from Keycloak\n   */\n  session_state: string;\n  realm_access: {\n    roles: string[];\n  };\n  resource_access: {\n    account: {\n      roles: string[];\n    };\n  };\n  scope: string;\n  email_verified: boolean;\n  name: string;\n  email: string;\n  preferred_username: string;\n  given_name: string;\n  family_name: string;\n\n  /**\n   * Our domain properties\n   */\n  f4d: {\n    sme_id: string;\n    user_type: UserType;\n    user_id: string;\n    distributor_id: string;\n    uboId?: string;\n    permissions: string[];\n    '2fa_method'?: MfaMethod;\n  };\n\n  onbId?: string;\n};\n\nexport const jwtDecode = (token: string): JwtObject | null => {\n  try {\n    const tokenString = atob(token.split('.')[1]);\n    return JSON.parse(decodeURIComponent(escape(tokenString)));\n  } catch {\n    return null;\n  }\n};\n\nexport const isTokenValid = (token: string | null): boolean => {\n  if (!token) {\n    return false;\n  }\n\n  const decodedToken: JwtObject | null = jwtDecode(token);\n\n  if (decodedToken) {\n    const expirationDate: Date = new Date(decodedToken.exp * 1000);\n    return isBefore(new Date(), expirationDate);\n  }\n\n  return false;\n};\n","import { KeyboardEvent } from 'react';\n\nexport const padLeft = (number: number, length = 2, leading = '0'): string =>\n  number.toString().padStart(length, leading);\n\nexport const getUserAgent = () => (navigator ? navigator.userAgent : null);\n\nexport const getUserPlatform = () => {\n  const userAgent = getUserAgent();\n  const PLATFORM_REGEX = /.*?\\((.*?)\\)/;\n\n  const match = userAgent?.match(PLATFORM_REGEX);\n\n  if (match) {\n    return match[1].split(';').slice(0, 2).join(';');\n  }\n\n  return null;\n};\n\nexport const emptyStringToNull = (value: string, originalValue: string) => {\n  if (typeof originalValue === 'string' && originalValue === '') {\n    return null;\n  }\n  return value;\n};\n\nexport const onEnter = (callback: () => void) => {\n  return (event: KeyboardEvent<HTMLElement>) => {\n    if (event.code === 'Enter') {\n      callback();\n    }\n  };\n};\n\nexport const setFavicon = (url?: string): boolean => {\n  const el = document.getElementById('favicon') as HTMLLinkElement | null;\n\n  if (url && el !== null) {\n    el.href = url;\n    return true;\n  }\n\n  return false;\n};\n\n/**\n * In Safari copy to clipboard should be done during the user's mouse or gesture event.\n * Awaiting a remote call during onClick will result in a failure.\n *\n * Please use Promise version to avoid that.\n */\nexport const copyTextToClipboard = async (\n  textProvider: (() => Promise<string>) | string,\n) => {\n  const valueProvider =\n    typeof textProvider === 'string'\n      ? () => new Promise<string>((r) => r(textProvider))\n      : textProvider;\n\n  if (typeof ClipboardItem && navigator.clipboard.write) {\n    // NOTE: Safari locks down the clipboard API to only work when triggered\n    //   by a direct user interaction. You can't use it async in a promise.\n    //   But! You can wrap the promise in a ClipboardItem, and give that to\n    //   the clipboard API.\n    //   Found this on https://developer.apple.com/forums/thread/691873\n    const text = new ClipboardItem({\n      'text/plain': valueProvider().then(\n        (text) => new Blob([text], { type: 'text/plain' }),\n      ),\n    });\n    await navigator.clipboard.write([text]);\n  } else {\n    // NOTE: Firefox has support for ClipboardItem and navigator.clipboard.write,\n    //   but those are behind `dom.events.asyncClipboard.clipboardItem` preference.\n    //   Good news is that other than Safari, Firefox does not care about\n    //   Clipboard API being used async in a Promise.\n    await valueProvider().then((text) => navigator.clipboard.writeText(text));\n  }\n};\n","export const countryToCapitalProvider = (country?: string) => {\n  switch (country) {\n    case 'ITA':\n      return 'MIR Ita Capital S.r.l.';\n    default:\n      return 'MIR Lux Capital S.a.r.l.';\n  }\n};\n","export const sanitizeString = (str: string) => {\n  return str.replace(/[/\\\\?%*:|<>&\"'`]/g, '');\n};\n","export type FlowType = 'CAPITAL_MAX' | 'SIGNATURE';\n\nexport interface FlowSettings {\n  flow: FlowType | null;\n  offerId: string | null;\n  useOfFunds: string[] | null;\n  useOfFundsComment: string | null;\n}\n\nconst FLOW_KEY = 'flow_settings';\n\nexport function storeFlowSettings() {\n  const urlParams = new URLSearchParams(window.location.search);\n  const flow = urlParams.get('f');\n\n  if (flow == null) {\n    window.sessionStorage.removeItem(FLOW_KEY);\n    return;\n  }\n\n  const settings: FlowSettings = {\n    flow: isValidFlow(flow) ? flow : null,\n    offerId: urlParams.get('offer_id'),\n    useOfFunds:\n      urlParams.get('use_of_funds')?.split(',').filter(Boolean) ?? null,\n    useOfFundsComment: urlParams.get('use_of_funds_comment'),\n  };\n\n  window.sessionStorage.setItem(FLOW_KEY, JSON.stringify(settings));\n}\n\nexport function getFlowSettings(): FlowSettings | null {\n  const raw = window.sessionStorage.getItem(FLOW_KEY);\n  if (raw == null) return null;\n\n  try {\n    return JSON.parse(raw) as FlowSettings;\n  } catch {\n    return null;\n  }\n}\n\nexport function clearFlowSettings() {\n  window.sessionStorage.removeItem(FLOW_KEY);\n}\n\nfunction isValidFlow(value: string): value is FlowType {\n  return value === 'CAPITAL_MAX' || value === 'SIGNATURE';\n}\n","export type LinkSettings = {\n  'onboarding.apply_page_skip': boolean;\n};\n\nconst defaultSettings: LinkSettings = {\n  'onboarding.apply_page_skip': false,\n};\n\ntype Codec<TValue> = {\n  parse: (value: string) => TValue;\n  serialize: (value: TValue) => string;\n};\n\nconst booleanCodec: Codec<boolean> = {\n  parse: (v) => v === 'true',\n  serialize: (v) => v.toString(),\n};\n\nconst codecs: {\n  [K in keyof LinkSettings]: Codec<LinkSettings[K]>;\n} = {\n  'onboarding.apply_page_skip': booleanCodec,\n};\n\nconst linkSettings: (keyof LinkSettings)[] = Object.keys(\n  defaultSettings,\n) as (keyof LinkSettings)[];\n\nexport function storeLinkSettings() {\n  const urlParams = new URLSearchParams(window.location.search);\n  linkSettings.forEach((param) => {\n    const value = urlParams.get(param);\n    if (value != null) {\n      window.sessionStorage.setItem(param, value);\n    } else {\n      window.sessionStorage.setItem(\n        param,\n        codecs[param].serialize(defaultSettings[param]),\n      );\n    }\n  });\n}\n\nexport function getLinkSetting<\n  TSetting extends keyof LinkSettings,\n  TValue extends LinkSettings[TSetting],\n>(setting: TSetting): TValue {\n  const serializedValue = window.sessionStorage.getItem(setting);\n  if (serializedValue == null) return defaultSettings[setting] as TValue;\n\n  return codecs[setting].parse(serializedValue) as TValue;\n}\n","const utmParams = [\n  'utm_source',\n  'utm_medium',\n  'utm_campaign',\n  'utm_content',\n  'utm_term',\n] as const;\n\nexport function storeUtmParams() {\n  const urlParams = new URLSearchParams(window.location.search);\n\n  utmParams.forEach((param) => {\n    const value = urlParams.get(param);\n    if (value != null) {\n      window.sessionStorage.setItem(param, value);\n    }\n  });\n}\n\nexport function getUtmParams() {\n  return utmParams.reduce((acc, param) => {\n    acc[param] = window.sessionStorage.getItem(param);\n    return acc;\n  }, {} as Record<(typeof utmParams)[number], string | null>);\n}\n\nexport function clearUtmParams() {\n  utmParams.forEach((param) => {\n    window.sessionStorage.removeItem(param);\n  });\n}\n","import { jwtDecode } from '@finmid/utils';\n\nimport { storeFlowSettings } from './flowSettings';\nimport { storeLinkSettings } from './linkSettings';\nimport { storeUtmParams } from './utmParams';\n\ninterface TokenValue {\n  distributorId: string;\n  businessId: string;\n  exp: number;\n  /**\n   * 2FA methods claim from the turnkey token.\n   * Set by the backend based on distributor + market configuration.\n   * - `[\"SMS\"]` or other non-empty array → standard 2FA is enabled\n   * - `[]` (empty array) → 2FA is disabled (skip 2FA flow)\n   * - `undefined` (old tokens) → treated as `[\"SMS\"]` (standard 2FA)\n   */\n  twoFactorAuthMethods?: string[];\n}\n\nexport interface TokenData {\n  token: string;\n  ignoreAction: boolean;\n  platformId: string;\n  businessId: string;\n  expirationDate: Date;\n  country?: string;\n  /**\n   * 2FA methods enabled for this business/market, extracted from the JWT token.\n   * - `undefined` or non-empty array → standard 2FA flow\n   * - empty array `[]` → 2FA disabled, use lightweight skip-2FA flow\n   */\n  twoFactorAuthMethods?: string[];\n}\n\nexport const tokenStorageKey = 'AUTH_TOKEN';\nexport const ignoreActionStorageKey = 'IGNORE_ACTION';\n\nexport function getToken(): TokenData | null {\n  const urlParams = new URLSearchParams(window.location.search);\n  const tokenFromUrl = urlParams.get('t') ?? urlParams.get('token');\n  const countryFromUrl = urlParams.get('c') ?? undefined;\n\n  // store country if exists\n  if (countryFromUrl) {\n    window.localStorage.setItem('countryOverride', countryFromUrl);\n  }\n\n  const tokenFromLocalStorage = window.localStorage.getItem(tokenStorageKey);\n  const token = tokenFromUrl ?? tokenFromLocalStorage ?? '';\n\n  const decodedToken = jwtDecode(token) as TokenValue | null;\n\n  if (decodedToken == null) return null;\n\n  window.localStorage.setItem(tokenStorageKey, token);\n\n  const expirationDate = new Date(decodedToken.exp * 1000);\n\n  if (expirationDate < new Date()) {\n    window.localStorage.removeItem(tokenStorageKey);\n  }\n\n  const ignoreActionFromUrl = urlParams.get('i') ?? urlParams.get('ignore');\n  const ignoreActionFromLocalStorage = window.localStorage.getItem(\n    ignoreActionStorageKey,\n  );\n  const ignoreAction = ignoreActionFromUrl ?? ignoreActionFromLocalStorage;\n  if (ignoreAction) {\n    window.localStorage.setItem(ignoreActionStorageKey, 'true');\n  }\n\n  storeUtmParams();\n  storeLinkSettings();\n  storeFlowSettings();\n\n  const value: TokenData = {\n    token,\n    businessId: decodedToken.businessId,\n    platformId: decodedToken.distributorId,\n    expirationDate,\n    ignoreAction: !!ignoreAction,\n    country: countryFromUrl,\n    twoFactorAuthMethods: decodedToken.twoFactorAuthMethods,\n  };\n\n  return value;\n}\n","import {\n  createContext,\n  FunctionComponent,\n  PropsWithChildren,\n  useContext,\n  useState,\n} from 'react';\n\nimport { getToken, TokenData } from './getToken';\n\n// eslint-disable-next-line @typescript-eslint/no-non-null-assertion\nexport const TokenContext = createContext<TokenData>(null!);\n\ninterface Props {\n  invalidElement: React.ReactElement;\n  defaultToken?: TokenData;\n}\n\nexport const TokenProvider: FunctionComponent<PropsWithChildren<Props>> = ({\n  children,\n  invalidElement,\n  defaultToken,\n}) => {\n  const [tokenValue] = useState(getToken() ?? defaultToken);\n\n  if (tokenValue == null) return invalidElement;\n\n  return (\n    <TokenContext.Provider value={tokenValue}>{children}</TokenContext.Provider>\n  );\n};\n\nexport const useTokenContext = () => {\n  return useContext(TokenContext);\n};\n\nexport const useNullableTokenContext = () => {\n  return useContext(TokenContext) as TokenData | null;\n};\n","import { ENVIRONMENT, fromEnvironment } from '@finmid/environment';\n\nimport { getToken } from '../TokenContext';\n\nimport { defaultSettings, PlatformSettings } from './PlatformSettings';\n\nfunction loadPlatformCss(environment: string, platformId: string) {\n  const linkElement = document.createElement('link');\n  linkElement.rel = 'stylesheet';\n  linkElement.type = 'text/css';\n  linkElement.href = `/${environment}/${platformId}/platform.css`;\n  document.head.appendChild(linkElement);\n}\n\nexport async function loadSettings(\n  environmentOverride?: string,\n  platformIdOverride?: string,\n): Promise<PlatformSettings> {\n  const environment =\n    environmentOverride ?? (ENVIRONMENT === 'live' ? 'live' : 'staging');\n  const token = getToken();\n\n  if (token == null) return defaultSettings;\n\n  const platformId = platformIdOverride ?? token.platformId;\n\n  const dynamicPlatform = await import(\n    `@/platforms/${environment}/${platformId}/index.tsx`\n  );\n  const settings = dynamicPlatform.default as PlatformSettings;\n\n  loadPlatformCss(environment, platformId);\n\n  return {\n    ...settings,\n    resourcesPath: `/${environment}/${platformId}/`,\n    localization: {\n      ...settings?.localization,\n      project:\n        settings?.localization?.project ?? fromEnvironment('LOCIZE_PROJECT_ID'),\n    },\n  };\n}\n","import { ENVIRONMENT } from '@finmid/environment';\nimport { useOverrides } from '@finmid/tiger-webapp/overrides-manager';\nimport {\n  createContext,\n  FunctionComponent,\n  PropsWithChildren,\n  useContext,\n  useEffect,\n} from 'react';\nimport { useAsync } from 'react-use';\n\nimport { defaultSettings, PlatformSettings } from './PlatformSettings';\nimport { loadSettings } from './loadSettings';\n\ninterface PlatformSettingsContextResult {\n  settings: PlatformSettings;\n}\n\n// eslint-disable-next-line @typescript-eslint/no-non-null-assertion\nexport const PlatformSettingsContext =\n  createContext<PlatformSettingsContextResult>({\n    settings: defaultSettings,\n  });\n\nexport const PlatformSettingsProvider: FunctionComponent<PropsWithChildren> = ({\n  children,\n}) => {\n  const { overrides } = useOverrides();\n\n  const { value: settings, error } = useAsync(\n    () => loadSettings(overrides?.environment, overrides?.platformId),\n    [overrides?.environment, overrides?.platformId],\n  );\n\n  useEffect(() => {\n    if (error != null && ENVIRONMENT !== 'live') {\n      console.log(\n        '%cNo code-based platform settings found',\n        'color: yellow; font-weight: bold;',\n      );\n    }\n  }, [error]);\n\n  return (\n    <PlatformSettingsContext.Provider\n      value={{\n        settings: settings ?? defaultSettings,\n      }}\n    >\n      {children}\n    </PlatformSettingsContext.Provider>\n  );\n};\n\nexport const StaticPlatformSettingsProvider: FunctionComponent<\n  PropsWithChildren<{\n    settings: PlatformSettings;\n    styles?: string;\n  }>\n> = ({ children, settings, styles }) => {\n  if (styles) {\n    loadStaticStyles(styles);\n  }\n\n  return (\n    <PlatformSettingsContext.Provider\n      value={{\n        settings: settings ?? defaultSettings,\n      }}\n    >\n      {children}\n    </PlatformSettingsContext.Provider>\n  );\n};\n\nfunction loadStaticStyles(styles: string) {\n  const styleElement = document.createElement('style');\n  styleElement.innerHTML = styles;\n  document.head.appendChild(styleElement);\n}\n\nexport const usePlatformSettings = () => {\n  return useContext(PlatformSettingsContext).settings;\n};\n","import { ComponentProps, ReactElement } from 'react';\n\nimport {\n  CustomisationSlotComponents,\n  CustomisationSlotKey,\n} from './PlatformSettings';\n\nimport { usePlatformSettings } from './';\n\ntype Props<\n  T extends CustomisationSlotKey,\n  P extends ComponentProps<CustomisationSlotComponents[T]>,\n> = {\n  slot: T;\n  props: P;\n  fallback?: ReactElement;\n};\n\nexport const CustomisationSlot = <\n  T extends CustomisationSlotKey,\n  P extends ComponentProps<CustomisationSlotComponents[T]>,\n>({\n  slot,\n  fallback,\n  props,\n}: Props<T, P>) => {\n  const { slots } = usePlatformSettings();\n\n  const Slot = slots?.[slot];\n\n  if (Slot == null) return fallback ?? null;\n\n  // eslint-disable-next-line @typescript-eslint/no-explicit-any\n  return <Slot {...(props as any)} />;\n};\n","import type { Theme } from '@emotion/react';\n\nexport const radius = ['sm', 'md', 'lg', 'pill', 'button'] as const;\n\nexport const spacings = ['xs', 'sm', 'md', 'lg', 'xl', 'xxl', 'xxxl'] as const;\n\nexport const typographySizes = ['xs', 'sm', 'md', 'lg', 'xl', 'xxl'] as const;\n\nexport const colors = [\n  'primaryDefault',\n  'primaryAccent',\n  'secondaryDefault',\n  'secondaryAccent',\n  'grey900',\n  'grey700',\n  'grey300',\n  'grey100',\n  'white',\n  'success',\n  'warning',\n  'error',\n] as const;\n\nexport const optionalColors = ['grey400', 'grey200', 'grey50'] as const;\n\nexport type Variables = {\n  colors: ColorVariables;\n  radius: RadiusVariables;\n  spacings: SpacingVariables;\n  typography: {\n    mobile: TypographyVariables;\n    desktop: TypographyVariables;\n  };\n};\n\nexport type ColorVariables = {\n  [key in (typeof colors)[number]]: string;\n} & {\n  [key in (typeof optionalColors)[number]]?: string;\n};\n\nexport type RadiusVariables = {\n  [key in (typeof radius)[number]]: number | string;\n};\n\nexport type SpacingVariables = {\n  [key in (typeof spacings)[number]]: number | string;\n};\n\nexport type TypographyVariables = {\n  family: TypographyFamilyVariables;\n  weight: TypographyWeightVariables;\n  size: TypographySizeVariables;\n  lineHeight: TypographyLineHeightVariables;\n};\n\ntype TypographyFamilyVariables = {\n  title: string;\n  body: string;\n};\n\ntype TypographyWeightVariables = {\n  default: string;\n  strong: string;\n};\n\ntype TypographySizeVariables = {\n  [key in (typeof typographySizes)[number]]: number | string;\n};\ntype KeysOfTypographySizeVariables = keyof TypographySizeVariables;\n\ntype TypographyLineHeightVariables = {\n  xs: string;\n  sm: string;\n  md: string;\n  lg: string;\n  xl: string;\n  xxl: string;\n};\n\nexport function typographySize(\n  { breakpoints, vars: { components } }: Pick<Theme, 'breakpoints' | 'vars'>,\n  size: KeysOfTypographySizeVariables,\n) {\n  return {\n    fontSize: components?.variables.typography.desktop.size[size],\n    lineHeight: components?.variables.typography.desktop.lineHeight[size],\n\n    [breakpoints.down('desktop')]: {\n      fontSize: components?.variables?.typography.mobile.size[size],\n      lineHeight: components?.variables?.typography.mobile.lineHeight[size],\n    },\n  };\n}\n","import { Keyframes } from '@emotion/react';\nimport { useCallback, useState } from 'react';\n\nexport const useAnimation = (keyframes: Keyframes, duration = 500) => {\n  const [isAnimationRunning, setIsAnimationRunning] = useState(false);\n\n  const animate = useCallback(() => {\n    setIsAnimationRunning(true);\n    setTimeout(() => {\n      setIsAnimationRunning(false);\n    }, duration);\n  }, [duration]);\n\n  return [\n    {\n      animation: isAnimationRunning\n        ? `${keyframes} ${duration}ms ease`\n        : undefined,\n    },\n    animate,\n  ] as const;\n};\n","import { useTheme } from '@emotion/react';\nimport { useMemo } from 'react';\n\nimport { PlatformCustomization } from './PlatformSettings';\n\nfunction readCssVariable<T extends string>(\n  variableName: string,\n  defaultValue: string | number,\n): T;\nfunction readCssVariable(\n  variableName: string,\n  defaultValue?: string | number,\n): string | null {\n  const cssVariableName = `--mui-components-${variableName.replace(\n    /\\./gi,\n    '-',\n  )}`;\n  const cssVariableValue = getComputedStyle(document.body).getPropertyValue(\n    cssVariableName,\n  );\n\n  const isEmpty = cssVariableValue == null || cssVariableValue.trim() === '';\n\n  return isEmpty ? defaultValue?.toString() ?? null : cssVariableValue;\n}\n\nexport const useCssVariable = <T extends string>(\n  variableName: string,\n  /**\n   * Customization provider is here to link the css variable to the customization in JSON in the code\n   */\n  customizationProvider: (\n    customizations: PlatformCustomization | undefined,\n  ) => T | string | number | undefined,\n  defaultValue?: T,\n): T => {\n  const {\n    vars: { components },\n  } = useTheme();\n\n  const customizationValue = customizationProvider(components);\n\n  return useMemo(() => {\n    const cssValue = readCssVariable<T>(\n      variableName,\n      defaultValue as string | number,\n    );\n    return cssValue;\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [variableName, defaultValue, customizationValue]);\n};\n","import { useCssVariable } from '../readCssVariable';\n\nexport const useBindingLanguage = () => {\n  const value = useCssVariable(\n    'review.terms.bindingLanaguage',\n    (c) => c?.review?.terms?.bindingLanaguage,\n    'en',\n  );\n\n  return value.toString();\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport { useMutation, useQueryClient } from '@tanstack/react-query';\nimport axios from 'axios';\n\nexport type StartAispConnectionResponse = {\n  connectionId?: string;\n  provider?: string;\n  finapiConnectionDetails?: {\n    webFormUrl: string;\n  };\n};\n\nexport type AispProviderType = 'FINAPI' | 'PLAID';\nexport type AispScope = 'ONBOARDING' | 'CAPITAL_MAX' | 'CAPITAL_SDD_PROOF';\nexport type AispConnectionPurpose =\n  | 'SDD_COLLECTION_BACKUP'\n  | 'SDD_CONNECTION_OFFER_FLOW';\n\ninterface Options {\n  token: string;\n  provider: AispProviderType;\n  purpose?: AispConnectionPurpose;\n}\n\ntype StartBusinessAispConnectionReponse<TProvider extends AispProviderType> = {\n  connectionId: string;\n  provider: TProvider;\n} & (TProvider extends 'FINAPI'\n  ? {\n      finapiConnectionDetails: {\n        webFormUrl: string;\n      };\n    }\n  : {\n      plaidConnectionDetails: {\n        plaidLinkToken: string;\n      };\n    });\n\nexport const usePostStartBusinessAispConnection = <\n  TProvider extends AispProviderType,\n>(\n  provider: TProvider,\n) => {\n  const queryClient = useQueryClient();\n\n  return useMutation({\n    mutationFn: async ({ token, purpose }: Options) => {\n      const response = await axios.post<\n        StartBusinessAispConnectionReponse<TProvider>\n      >(\n        `payables-financing/public/v1/businesses/aisp/connections`,\n        {\n          provider,\n          ...(purpose && { purpose }),\n        },\n        {\n          params: {\n            token,\n          },\n          baseURL: fromEnvironment('INTERNAL_API_BASE_URL'),\n          validateStatus: () => true,\n        },\n      );\n\n      return response.data;\n    },\n    onSuccess: () =>\n      queryClient.invalidateQueries({\n        queryKey: ['start-business-aisp-connection'],\n      }),\n  });\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport { useMutation } from '@tanstack/react-query';\nimport axios from 'axios';\n\ninterface PlaidFinalizeOptions {\n  token: string;\n  plaidToken: string;\n  connectionId: string;\n}\n\nexport const useFinalizePlaidConnection = () => {\n  return useMutation({\n    mutationFn: async ({\n      token,\n      plaidToken,\n      connectionId,\n    }: PlaidFinalizeOptions) =>\n      await axios.post<void>(\n        `payables-financing/public/v1/businesses/aisp/connections/${connectionId}/plaid-finalize`,\n        null,\n        {\n          params: { token, plaidToken },\n          baseURL: fromEnvironment('INTERNAL_API_BASE_URL'),\n          validateStatus: (status) => status >= 200 && status <= 300,\n        },\n      ),\n  });\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport { useQuery } from '@tanstack/react-query';\nimport axios from 'axios';\nimport { useEffect } from 'react';\n\nexport type AispConnectionState = 'PENDING' | 'READY' | 'ERROR';\n\ntype PreselectedCollectionAccount = {\n  aispAccountId: string;\n  ibanLastFour: string;\n};\n\nexport interface GetAispConnectionStatusResponse {\n  status: AispConnectionState;\n  bankName?: string;\n  bankLogoUrl?: string;\n  bic?: string;\n  preselectedCollectionAccount?: PreselectedCollectionAccount | null;\n}\n\nexport interface UsePollAispConnectionsOptions {\n  connectionId: string | undefined;\n  token: string;\n  enabled: boolean;\n  onSuccess: (response: {\n    status: AispConnectionState;\n    bankName?: string;\n    bankLogoUrl?: string;\n    bic?: string;\n    preselectedCollectionAccount?: PreselectedCollectionAccount | null;\n  }) => void;\n}\n\nexport const usePollAispConnections = ({\n  connectionId,\n  token,\n  enabled,\n  onSuccess,\n}: UsePollAispConnectionsOptions) => {\n  const query = useQuery({\n    queryKey: ['get-aisp-connection-status'],\n    queryFn: async () => {\n      const response = await axios.get<GetAispConnectionStatusResponse>(\n        `/payables-financing/public/v1/businesses/aisp/connections/${connectionId}/status`,\n        {\n          params: { token },\n          baseURL: fromEnvironment('INTERNAL_API_BASE_URL'),\n          validateStatus: (status) => status >= 200 && status <= 300,\n        },\n      );\n      return response.data;\n    },\n    enabled: enabled && connectionId != null,\n    refetchInterval: 1000,\n  });\n\n  useEffect(() => {\n    if (query.data && onSuccess) {\n      onSuccess(query.data);\n    }\n  }, [query.data, onSuccess]);\n\n  return query;\n};\n","export type DocumentType =\n  | 'CAPITAL_MAX'\n  | 'CSP_FINANCIAL_DOCUMENT'\n  | 'SOLE_PROPRIETOR'\n  | 'ONBOARDING';\n\nexport type DocumentAttachmentLevelOptions = {\n  // eslint-disable-next-line @typescript-eslint/no-empty-object-type\n  BUSINESS: {};\n  OFFER: {\n    offerGroupId: string;\n  };\n};\n\nexport type DocumentAttachmentLevel = keyof DocumentAttachmentLevelOptions;\n\nexport enum BusinessDocumentValidationResult {\n  PENDING = 'PENDING',\n  VALID = 'VALID',\n  INVALID = 'INVALID',\n}\n","import {\n  DocumentAttachmentLevel,\n  DocumentAttachmentLevelOptions,\n  DocumentType,\n} from './types';\n\nexport const useDocumentProps = <TLevel extends DocumentAttachmentLevel>(\n  level: TLevel,\n  documentType: DocumentType,\n  options: DocumentAttachmentLevelOptions[TLevel],\n) => ({\n  level: {\n    type: level,\n    options,\n  },\n  documentType,\n});\n","import { fromEnvironment } from '@finmid/environment';\nimport axios from 'axios';\n\nimport {\n  DocumentAttachmentLevelOptions,\n  DocumentType,\n  BusinessDocumentValidationResult,\n} from './types';\n\nconst INTERNAL_API_BASE_URL = fromEnvironment('INTERNAL_API_BASE_URL');\n\nexport interface BusinessDocument {\n  id: string;\n  name?: string;\n  extension?: string;\n  size: number;\n  createdAt: string;\n  validationResult?: BusinessDocumentValidationResult;\n}\n\nexport interface GetUploadedDocumentsResponse {\n  documents: BusinessDocument[];\n  isSubmitted: boolean;\n}\n\nconst getCspDocuments = async (\n  token: string,\n): Promise<GetUploadedDocumentsResponse> => {\n  const response = await axios.get<GetUploadedDocumentsResponse>(\n    '/payables-financing/public/v1/documents/csp',\n    {\n      params: { token },\n      baseURL: INTERNAL_API_BASE_URL,\n      validateStatus(status) {\n        return status == 200 || status == 404;\n      },\n    },\n  );\n\n  if (response.status === 404) {\n    return { documents: [], isSubmitted: false };\n  }\n\n  return response.data;\n};\n\nexport const getOfferDocuments = async (\n  token: string,\n  documentType: DocumentType,\n  { offerGroupId }: DocumentAttachmentLevelOptions['OFFER'],\n): Promise<GetUploadedDocumentsResponse> => {\n  if (documentType === 'CSP_FINANCIAL_DOCUMENT') {\n    return getCspDocuments(token);\n  }\n\n  if (offerGroupId == null) {\n    return { documents: [], isSubmitted: false };\n  }\n\n  const url = `/payables-financing/public/v2/businesses/documents/${documentType}/${offerGroupId}`;\n\n  const response = await axios.get<GetUploadedDocumentsResponse>(url, {\n    params: {\n      token,\n    },\n    baseURL: INTERNAL_API_BASE_URL,\n    validateStatus(status) {\n      return status == 200 || status == 404;\n    },\n  });\n\n  if (response.status === 404) {\n    return { documents: [], isSubmitted: false };\n  }\n\n  return response.data;\n};\n\nexport const getBusinessDocuments = async (\n  token: string,\n  documentType: DocumentType,\n): Promise<GetUploadedDocumentsResponse> => {\n  const url = `/payables-financing/public/v2/businesses/documents/${documentType}`;\n\n  const response = await axios.get<GetUploadedDocumentsResponse>(url, {\n    params: {\n      token,\n    },\n    baseURL: INTERNAL_API_BASE_URL,\n    validateStatus(status) {\n      return status == 200 || status == 404;\n    },\n  });\n\n  if (response.status === 404) {\n    return { documents: [], isSubmitted: false };\n  }\n\n  return response.data;\n};\n","import { useQuery } from '@tanstack/react-query';\nimport { useMemo } from 'react';\n\nimport {\n  getBusinessDocuments,\n  getOfferDocuments,\n  GetUploadedDocumentsResponse,\n} from './getUploadedDocuments';\nimport {\n  DocumentAttachmentLevel,\n  DocumentAttachmentLevelOptions,\n  DocumentType,\n} from './types';\n\ntype GetUploadedDocumentsOptions<TLevel extends DocumentAttachmentLevel> = {\n  level: {\n    type: TLevel;\n    options: DocumentAttachmentLevelOptions[TLevel];\n  };\n  token: string;\n  documentType: DocumentType;\n  refetchInterval?: number;\n};\n\nexport const documentsKeys = ['get-uploaded-files'] as const;\n\nexport const useGetUploadedDocuments = <\n  TLevel extends DocumentAttachmentLevel,\n>({\n  token,\n  level,\n  documentType,\n  refetchInterval,\n}: GetUploadedDocumentsOptions<TLevel>) => {\n  const {\n    query,\n    cacheKeys,\n    enabled,\n  }: {\n    query: () => Promise<GetUploadedDocumentsResponse>;\n    cacheKeys: string[];\n    enabled: boolean;\n  } = useMemo(() => {\n    if (level.type === 'OFFER') {\n      const options = level.options as DocumentAttachmentLevelOptions['OFFER'];\n\n      return {\n        query: () => getOfferDocuments(token, documentType, options),\n        cacheKeys: [options.offerGroupId],\n        enabled: options.offerGroupId !== '',\n      };\n    }\n\n    return {\n      query: () => getBusinessDocuments(token, documentType),\n      cacheKeys: [],\n      enabled: true,\n    };\n  }, [level.type, documentType]);\n\n  return useQuery({\n    queryKey: [...documentsKeys, level.type, documentType, ...cacheKeys],\n    queryFn: query,\n    refetchOnMount: false,\n    refetchOnWindowFocus: false,\n    enabled,\n    refetchInterval,\n  });\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport { useMutation, useQueryClient } from '@tanstack/react-query';\nimport axios from 'axios';\n\nimport { DocumentType } from './types';\nimport { documentsKeys } from './useGetUploadedDocuments';\n\ninterface FileDeleteParams {\n  token: string;\n  id: string;\n}\n\nexport const useFileDelete = (documentType?: DocumentType) => {\n  const queryClient = useQueryClient();\n\n  return useMutation({\n    mutationFn: async ({ token, id }: FileDeleteParams) => {\n      const url =\n        documentType === 'CSP_FINANCIAL_DOCUMENT'\n          ? `/payables-financing/public/v1/documents/csp/${id}`\n          : `/payables-financing/public/v2/businesses/documents/${id}`;\n\n      await axios.delete(url, {\n        params: { token },\n        baseURL: fromEnvironment('INTERNAL_API_BASE_URL'),\n      });\n    },\n    onSuccess: () => {\n      queryClient.invalidateQueries({ queryKey: documentsKeys });\n    },\n  });\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport axios from 'axios';\n\nimport {\n  DocumentAttachmentLevel,\n  DocumentAttachmentLevelOptions,\n  DocumentType,\n} from './types';\n\nconst INTERNAL_API_BASE_URL = fromEnvironment('INTERNAL_API_BASE_URL');\n\ntype FileSubmitParams<TLevel extends DocumentAttachmentLevel> = {\n  token: string;\n} & DocumentAttachmentLevelOptions[TLevel];\n\nexport type SubmitMutation<TLevel extends DocumentAttachmentLevel> = (\n  params: FileSubmitParams<TLevel>,\n) => Promise<void>;\n\nexport const postSubmitForBusiness =\n  (documentType: DocumentType): SubmitMutation<'BUSINESS'> =>\n  async ({ token }: FileSubmitParams<'BUSINESS'>) => {\n    await axios.post(\n      `/payables-financing/public/v2/businesses/documents/${documentType}/submit`,\n      undefined,\n      {\n        params: { token },\n        baseURL: INTERNAL_API_BASE_URL,\n      },\n    );\n  };\n\nexport const postSubmitForOffer =\n  (documentType: DocumentType): SubmitMutation<'OFFER'> =>\n  async ({ token, offerGroupId }: FileSubmitParams<'OFFER'>) => {\n    if (documentType === 'CSP_FINANCIAL_DOCUMENT') {\n      await axios.post(\n        '/payables-financing/public/v1/documents/csp/submit',\n        undefined,\n        {\n          params: { token },\n          baseURL: INTERNAL_API_BASE_URL,\n        },\n      );\n      return;\n    }\n\n    await axios.post(\n      `/payables-financing/public/v2/businesses/documents/${documentType}/${offerGroupId}/submit`,\n      undefined,\n      {\n        params: { token },\n        baseURL: INTERNAL_API_BASE_URL,\n      },\n    );\n  };\n","import { useMutation, useQueryClient } from '@tanstack/react-query';\nimport { useMemo } from 'react';\n\nimport {\n  postSubmitForBusiness,\n  postSubmitForOffer,\n  SubmitMutation,\n} from './postFileSubmit';\nimport { DocumentAttachmentLevel, DocumentType } from './types';\nimport { documentsKeys } from './useGetUploadedDocuments';\n\nexport const useFileSubmit = <TLevel extends DocumentAttachmentLevel>(\n  level: TLevel,\n  documentType: DocumentType,\n) => {\n  const queryClient = useQueryClient();\n\n  const submitMutation: SubmitMutation<TLevel> = useMemo(() => {\n    const result =\n      level === 'OFFER'\n        ? (postSubmitForOffer(documentType) as SubmitMutation<TLevel>)\n        : (postSubmitForBusiness(documentType) as SubmitMutation<TLevel>);\n\n    return result;\n  }, [level, documentType]);\n\n  return useMutation({\n    mutationFn: submitMutation,\n    onSuccess: () => {\n      queryClient.invalidateQueries({ queryKey: documentsKeys });\n    },\n  });\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport axios from 'axios';\n\nimport {\n  DocumentAttachmentLevel,\n  DocumentAttachmentLevelOptions,\n  DocumentType,\n} from './types';\n\ntype FileUploadParams<TLevel extends DocumentAttachmentLevel> = {\n  token: string;\n  files: Array<File>;\n} & DocumentAttachmentLevelOptions[TLevel];\n\nexport type FileUploadMutation<TLevel extends DocumentAttachmentLevel> = (\n  params: FileUploadParams<TLevel>,\n) => Promise<void>;\n\nconst INTERNAL_API_BASE_URL = fromEnvironment('INTERNAL_API_BASE_URL');\n\ninterface CspUploadResponse {\n  documentId: string;\n  uploadUrl: string;\n  uploadExpiry: string;\n}\n\nasync function uploadCspDocument(token: string, file: File): Promise<void> {\n  // Step 1: Get presigned upload URL\n  const { data } = await axios.post<CspUploadResponse>(\n    '/payables-financing/public/v1/documents/csp/uploads',\n    {\n      fileName: file.name,\n      fileSize: file.size,\n      fileType: file.type,\n    },\n    {\n      params: { token },\n      baseURL: INTERNAL_API_BASE_URL,\n    },\n  );\n\n  // Step 2: Upload file directly to presigned S3 URL\n  const response = await fetch(data.uploadUrl, {\n    method: 'PUT',\n    body: file,\n    headers: {\n      'Content-Type': file.type,\n    },\n  });\n\n  if (!response.ok) {\n    throw new Error(`S3 upload failed with status ${response.status}`);\n  }\n}\n\nexport const postUploadForBusiness =\n  (documentType: DocumentType): FileUploadMutation<'BUSINESS'> =>\n  async ({ token, files }: FileUploadParams<'BUSINESS'>) => {\n    const formData = new FormData();\n    formData.append('document', files[0], files[0].name);\n\n    const url = `/payables-financing/public/v2/businesses/documents/${documentType}`;\n\n    await axios.post(url, formData, {\n      params: { token },\n      baseURL: INTERNAL_API_BASE_URL,\n    });\n  };\n\nexport const postUploadForOffer =\n  (documentType: DocumentType): FileUploadMutation<'OFFER'> =>\n  async ({ token, files, offerGroupId }: FileUploadParams<'OFFER'>) => {\n    if (documentType === 'CSP_FINANCIAL_DOCUMENT') {\n      await uploadCspDocument(token, files[0]);\n      return;\n    }\n\n    const formData = new FormData();\n    formData.append('document', files[0], files[0].name);\n\n    const url = `/payables-financing/public/v2/businesses/documents/${documentType}/${offerGroupId}`;\n\n    await axios.post(url, formData, {\n      params: { token },\n      baseURL: INTERNAL_API_BASE_URL,\n    });\n  };\n","import { useMutation, useQueryClient } from '@tanstack/react-query';\nimport { useMemo } from 'react';\n\nimport {\n  FileUploadMutation,\n  postUploadForBusiness,\n  postUploadForOffer,\n} from './postFileUpload';\nimport { DocumentAttachmentLevel, DocumentType } from './types';\nimport { documentsKeys } from './useGetUploadedDocuments';\n\nexport const useFileUpload = <TLevel extends DocumentAttachmentLevel>(\n  level: TLevel,\n  documentType: DocumentType,\n) => {\n  const queryClient = useQueryClient();\n\n  const submitMutation: FileUploadMutation<TLevel> = useMemo(() => {\n    const result =\n      level === 'OFFER'\n        ? (postUploadForOffer(documentType) as FileUploadMutation<TLevel>)\n        : (postUploadForBusiness(documentType) as FileUploadMutation<TLevel>);\n\n    return result;\n  }, [level, documentType]);\n\n  return useMutation({\n    mutationFn: submitMutation,\n    onSuccess: () => {\n      queryClient.invalidateQueries({ queryKey: documentsKeys });\n    },\n  });\n};\n","export const shortLiving2FaTokenKey = 'shortLiving2FaToken';\n","import { fromEnvironment } from '@finmid/environment';\nimport { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';\nimport axios from 'axios';\nimport { addSeconds } from 'date-fns/addSeconds';\nimport { differenceInSeconds } from 'date-fns/differenceInSeconds';\n\nimport { shortLiving2FaTokenKey } from './constants';\n\nconst INTERNAL_API_BASE_URL = fromEnvironment('INTERNAL_API_BASE_URL');\nconst PUBLIC_API = `${INTERNAL_API_BASE_URL}/payables-financing/public`;\n\nexport const OFFER_ACCEPT_VERIFICATION_MODE = {\n  PLATFORM_PHONE: 'PLATFORM_PHONE',\n  BACKUP_PHONE_WITH_IBAN: 'BACKUP_PHONE_WITH_IBAN',\n} as const;\n\nexport type OfferAcceptVerificationMode =\n  (typeof OFFER_ACCEPT_VERIFICATION_MODE)[keyof typeof OFFER_ACCEPT_VERIFICATION_MODE];\n\ntype ChallengeOptions =\n  | {\n      type: 'OFFER_ACCEPT';\n      phone: string;\n      token: string;\n      locale: string;\n      iban?: string;\n      verificationMode?: OfferAcceptVerificationMode;\n    }\n  | {\n      type: 'BACKUP_PHONE_VERIFY';\n      phone: string;\n      token: string;\n      locale: string;\n    }\n  | { type: 'HISTORY_ACCESS'; token: string; locale: string };\n\nexport const useSecondsTillNext2FaChallenge = () => {\n  const { data: nextDate = new Date('2023-01-01') } = useQuery({\n    queryKey: ['next-2fa-date'],\n    queryFn: () => new Date('2023-01-01'),\n    refetchOnMount: false,\n    refetchOnReconnect: false,\n    refetchOnWindowFocus: false,\n  });\n\n  return Math.max(0, differenceInSeconds(nextDate, new Date()));\n};\n\nexport const useRequest2FaChallenge = (options: ChallengeOptions) => {\n  const { locale, token, type } = options;\n\n  const queryClient = useQueryClient();\n\n  const phone =\n    options.type === 'OFFER_ACCEPT' || options.type === 'BACKUP_PHONE_VERIFY'\n      ? options.phone\n      : undefined;\n\n  const iban = options.type === 'OFFER_ACCEPT' ? options.iban : undefined;\n  const verificationMode =\n    options.type === 'OFFER_ACCEPT' ? options.verificationMode : undefined;\n\n  const effectiveLocale = locale.startsWith('en-') ? 'en' : locale;\n\n  return useMutation({\n    mutationKey: ['trigger-2fa'],\n    mutationFn: () =>\n      axios.post<{ secondsUntilNextTry: number }>(\n        'v1/trigger-2fa',\n        {\n          locale: effectiveLocale,\n          phone,\n          type,\n          ...(iban !== undefined ? { iban } : {}),\n          ...(verificationMode !== undefined ? { verificationMode } : {}),\n        },\n        {\n          params: { token },\n          baseURL: PUBLIC_API,\n          validateStatus: () => true,\n        },\n      ),\n    onSuccess({ data }) {\n      const isError = 'code' in data;\n\n      if (!isError)\n        queryClient.setQueryData(\n          ['next-2fa-date'],\n          addSeconds(new Date(), Math.max(data.secondsUntilNextTry ?? 60, 15)),\n        );\n    },\n  });\n};\n\ntype Verify2FaOptions = { token: string };\ntype Verify2FaMutationFnBody = { type: 'HISTORY_ACCESS'; code: string };\n\nexport const useVerify2Fa = (options: Verify2FaOptions) => {\n  const { token } = options;\n\n  return useMutation({\n    mutationKey: ['verify-2fa'],\n    mutationFn: async ({ code, type }: Verify2FaMutationFnBody) => {\n      const response = await axios.post<{ token: string }>(\n        'v1/verify-2fa',\n        {\n          code,\n          type,\n        },\n        {\n          params: { token },\n          baseURL: PUBLIC_API,\n          validateStatus: (status) => status === 200 || status === 403,\n        },\n      );\n\n      return response.data.token;\n    },\n    onSuccess: (token) => {\n      if (token) {\n        localStorage.setItem(shortLiving2FaTokenKey, token);\n      }\n    },\n  });\n};\n\ninterface AcceptOfferOptions {\n  id: string;\n  token: string;\n  referralCode?: string;\n  useOfFunds?: {\n    values: string[];\n    comment?: string;\n  };\n  /**\n   * When true (2FA disabled via twoFactorAuthMethods=[]), the code\n   * parameter in the request body will be omitted.\n   * The backend determines this from the JWT token itself.\n   */\n  skip2FA?: boolean;\n}\n\ninterface AcceptOfferMutationInput {\n  code: string;\n  backupPhone?: string | null;\n  iban?: string | null;\n  verificationMode?: OfferAcceptVerificationMode;\n}\n\nconst composeUseOfFunds = (useOfFunds: AcceptOfferOptions['useOfFunds']) => {\n  if (useOfFunds == null) return undefined;\n\n  const commentInput = useOfFunds.comment?.trim();\n  const values = [...useOfFunds.values];\n\n  if (\n    commentInput != null &&\n    commentInput !== '' &&\n    !values.includes('OTHER')\n  ) {\n    values.push('OTHER');\n  }\n\n  const comment =\n    commentInput != null && commentInput !== ''\n      ? commentInput\n      : values.includes('OTHER')\n      ? '<empty>'\n      : undefined;\n\n  return {\n    values,\n    comment,\n  };\n};\n\nexport const useAcceptOffer = ({\n  id,\n  token,\n  referralCode,\n  useOfFunds,\n  skip2FA,\n}: AcceptOfferOptions) => {\n  const queryClient = useQueryClient();\n\n  return useMutation({\n    mutationKey: ['accept-offer'],\n    mutationFn: async (input: string | AcceptOfferMutationInput) => {\n      const normalized: AcceptOfferMutationInput =\n        typeof input === 'string' ? { code: input } : input;\n      const { code, backupPhone, iban, verificationMode } = normalized;\n\n      const response = await axios.post<{ code: string }>(\n        `v1/available-offers/${id}/accept`,\n        {\n          // When 2FA is disabled (skip2FA), BE still requires the field\n          // but accepts an empty string as a valid value.\n          code: skip2FA ? '' : code,\n          referralCode,\n          useOfFunds: composeUseOfFunds(useOfFunds),\n          ...(backupPhone !== undefined ? { backupPhone } : {}),\n          ...(iban !== undefined ? { iban } : {}),\n          ...(verificationMode !== undefined ? { verificationMode } : {}),\n        },\n        {\n          params: { token },\n          baseURL: PUBLIC_API,\n          validateStatus(status) {\n            return status >= 200 && status < 500;\n          },\n        },\n      );\n\n      if (response.status >= 200 && response.status < 300) return null;\n      if (response.status >= 400 && response.status < 500)\n        return response.data.code;\n\n      throw response.data;\n    },\n    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['offers'] }),\n  });\n};\n\ninterface UpdateBackupPhoneOptions {\n  token: string;\n}\n\nexport const useUpdateBackupPhone = ({ token }: UpdateBackupPhoneOptions) => {\n  return useMutation({\n    mutationKey: ['update-backup-phone'],\n    mutationFn: async ({\n      backupPhone,\n      code,\n    }: {\n      backupPhone: string | null;\n      code: string | null;\n    }) => {\n      const response = await axios.post<{\n        code?: string;\n        description?: string;\n      }>(\n        'v1/businesses/backup-phone',\n        { backupPhone, code },\n        {\n          params: { token },\n          baseURL: PUBLIC_API,\n          validateStatus(status) {\n            return status >= 200 && status < 500;\n          },\n        },\n      );\n\n      if (response.status >= 200 && response.status < 300) return null;\n      if (response.status >= 400 && response.status < 500) return response.data;\n\n      throw response.data;\n    },\n  });\n};\n\ninterface RequestOfferRenewalOptions {\n  token: string;\n}\n\nexport const useRequestOfferRenewal = ({\n  token,\n}: RequestOfferRenewalOptions) => {\n  return useMutation({\n    mutationKey: ['request-offer-renewal'],\n    mutationFn: async () => {\n      const response = await axios.post(\n        `v1/request-offer-renewal`,\n        {},\n        {\n          params: { token },\n          baseURL: PUBLIC_API,\n          validateStatus(status) {\n            return status >= 200 && status < 500;\n          },\n        },\n      );\n\n      if (response.status >= 200 && response.status < 300) return null;\n      if (response.status >= 400 && response.status < 500)\n        return response.data.code;\n\n      throw response.data;\n    },\n  });\n};\n\nexport const reportWrongPhoneNumber = async (token: string, phone: string) => {\n  try {\n    await axios.post(\n      'v1/report-wrong-phone-number',\n      { phone },\n      {\n        params: { token },\n        baseURL: PUBLIC_API,\n        validateStatus: () => true,\n      },\n    );\n  } catch {\n    // Silently ignore errors to ensure it doesn't affect business logic\n  }\n};\n\nexport const useRequestPhoneUpdate = (token: string) => {\n  return useMutation({\n    mutationKey: ['request-phone-number-update'],\n    mutationFn: (phone: string) =>\n      axios.post<{ secondsUntilNextTry: number }>(\n        'v1/businesses/request-phone-number-update',\n        {\n          newPhoneNumber: phone,\n        },\n        {\n          params: { token },\n          baseURL: PUBLIC_API,\n          validateStatus: () => true,\n        },\n      ),\n  });\n};\n","import {\n  OFFER_ACCEPT_VERIFICATION_MODE,\n  OfferAcceptVerificationMode,\n} from './publicApi';\n\ninterface Options {\n  errorCode: string;\n  t: (key: string, fallback: string) => string;\n  isSmsWithIbanUpdateMode: boolean;\n  verificationMode: OfferAcceptVerificationMode | undefined;\n}\n\nexport function getAcceptOfferErrorMessage({\n  errorCode,\n  t,\n  isSmsWithIbanUpdateMode,\n  verificationMode,\n}: Options): string {\n  switch (errorCode) {\n    case 'INVALID_CODE':\n    case 'INVALID_OTP':\n    case 'OTP_INVALID':\n      return t('codeInvalid', 'Invalid code. Please try again.');\n    case 'INVALID_IBAN':\n    case 'IBAN_ENDING_MISMATCH':\n    case 'BACKUP_IBAN_MISMATCH':\n    case 'BackupIbanMismatch':\n      return t(\n        'ibanLastFourMismatch',\n        'IBAN does not match our records. Please check it and try again.',\n      );\n    case 'INVALID_PHONE':\n    case 'INVALID_PHONE_ENDING':\n      return t(\n        'invalidPhoneNumber',\n        'Could not verify the phone number. Please check it and try again.',\n      );\n    case 'TWO_FA_DISABLED':\n      return t(\n        'twoFaDisabled',\n        'Verification is unavailable. Please refresh the page and try again.',\n      );\n    case 'MISSING_IBAN':\n      return t('ibanInvalid', 'Please enter a valid IBAN.');\n    case 'MISSING_BACKUP_PHONE':\n      return t('emptyPhone', 'Please enter a valid phone number.');\n    case 'MISSING_CODE':\n      return t('codeIncomplete', 'Please enter the full code.');\n    case 'MISSING_VERIFICATION_MODE':\n      return isSmsWithIbanUpdateMode\n        ? t(\n            'acceptUnavailable',\n            'Verification is unavailable. Please refresh the page and try again.',\n          )\n        : t('codeInvalid', 'Invalid code. Please try again.');\n    default:\n      return verificationMode ===\n        OFFER_ACCEPT_VERIFICATION_MODE.BACKUP_PHONE_WITH_IBAN\n        ? t(\n            'acceptVerificationFailed',\n            'We could not verify your phone number and IBAN. Please try again.',\n          )\n        : t('codeInvalid', 'Invalid code. Please try again.');\n  }\n}\n","import { fromEnvironment } from '@finmid/environment';\nimport { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';\nimport axios from 'axios';\n\nexport type ConsentState = 'ACTIVE' | 'MISSING' | 'REJECTED';\n\nexport interface GetConsentResponse {\n  state: ConsentState;\n}\n\ninterface PutConsentRequest {\n  token: string;\n  action: 'GRANT' | 'REVOKE';\n}\n\ninterface Options {\n  token: string;\n}\n\nexport const useGetConsent = ({ token }: Options) => {\n  return useQuery({\n    queryKey: ['consent'],\n    queryFn: async () => {\n      const response = await axios.get<GetConsentResponse>(\n        `/payables-financing/public/v1/consents`,\n        {\n          params: {\n            token,\n          },\n          baseURL: fromEnvironment('INTERNAL_API_BASE_URL'),\n          validateStatus: () => true,\n          transformResponse: (response, _, status) =>\n            status === 404 ? { state: 'MISSING' } : JSON.parse(response),\n        },\n      );\n\n      return response.data;\n    },\n  });\n};\n\nexport const usePutConsent = () => {\n  const queryClient = useQueryClient();\n\n  return useMutation({\n    mutationFn: async ({ token, action }: PutConsentRequest) => {\n      const response = await axios.put(\n        `/payables-financing/public/v1/consents`,\n        {\n          action,\n        },\n        {\n          params: {\n            token,\n          },\n          baseURL: fromEnvironment('INTERNAL_API_BASE_URL'),\n          validateStatus: () => true,\n        },\n      );\n\n      return response.data;\n    },\n    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['consent'] }),\n  });\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport { useMutation } from '@tanstack/react-query';\nimport axios from 'axios';\n\ninterface CreateSddMandateOptions {\n  token: string;\n  iban: string;\n  accountHolderName: string;\n}\n\nexport const useCreateSddMandate = () => {\n  return useMutation({\n    mutationFn: async ({\n      token,\n      iban,\n      accountHolderName,\n    }: CreateSddMandateOptions) => {\n      return await axios.post(\n        `/payables-financing/public/v1/businesses/bank-accounts/mandates`,\n        { iban, accountHolderName },\n        {\n          params: { token },\n          baseURL: fromEnvironment('INTERNAL_API_BASE_URL'),\n        },\n      );\n    },\n  });\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport { useOverrides } from '@finmid/tiger-webapp/overrides-manager';\nimport { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';\nimport axios from 'axios';\n\nexport interface GetFeedbackResponse {\n  missingTypes: QuestionType[];\n}\n\ntype PutFeedbackResponse = undefined | { code: string; description: string };\n\nexport type QuestionType =\n  | 'NPS'\n  | 'AMOUNT_OF_CAPITAL_SATISFACTION'\n  | 'OVERALL_EXPERIENCE'\n  | 'IMPROVE_OFFER_HIGHER_LIMIT'\n  | 'IMPROVE_OFFER_LOW_FEE'\n  | 'IMPROVE_OFFER_TRANSPARENT_FEE'\n  | 'IMPROVE_OFFER_UNNEEDED'\n  | 'IMPROVE_OFFER_LATER'\n  | 'IMPROVE_OFFER_OTHER'\n  | 'USE_OF_FUNDS'\n  | 'CAPITAL_MAX_DATA_SHARING';\n\ninterface Parameters {\n  rating?: number;\n  comment?: string;\n  type: QuestionType;\n}\n\ninterface Options {\n  token: string;\n  offerId: string;\n}\n\nexport const useGetFeedback = ({ offerId, token }: Options) => {\n  const { overrides } = useOverrides();\n  const simulatedDashboard = overrides?.simulatedDashboard;\n\n  return useQuery({\n    queryKey: [simulatedDashboard == null ? 'feedback' : 'simulatedFeedback'],\n    queryFn: async () => {\n      if (simulatedDashboard != null) {\n        return {\n          missingTypes: [],\n        } as GetFeedbackResponse;\n      }\n\n      const response = await axios.get<GetFeedbackResponse>(\n        `/payables-financing/public/v1/offers/${offerId}/feedback`,\n        {\n          params: {\n            token,\n          },\n          baseURL: fromEnvironment('INTERNAL_API_BASE_URL'),\n        },\n      );\n\n      return response.data;\n    },\n  });\n};\n\nexport const usePostFeedback = ({ token, offerId }: Options) => {\n  const queryClient = useQueryClient();\n\n  return useMutation({\n    mutationFn: async (body: Parameters) => {\n      const response = await axios.post<PutFeedbackResponse>(\n        `/payables-financing/public/v1/offers/${offerId}/feedback`,\n        body,\n        {\n          params: {\n            token,\n          },\n          baseURL: fromEnvironment('INTERNAL_API_BASE_URL'),\n        },\n      );\n\n      return response.data;\n    },\n    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['feedback'] }),\n  });\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport { useOverrides } from '@finmid/tiger-webapp/overrides-manager';\nimport { useQuery } from '@tanstack/react-query';\nimport axios from 'axios';\n\nexport interface GetContractResponse {\n  url: string;\n}\n\ninterface Options {\n  token: string;\n  offerId: string | null;\n  locale: string;\n  extension: 'pdf';\n}\n\nexport const useGetContract = ({\n  token,\n  offerId,\n  extension,\n  locale,\n}: Options) => {\n  const { overrides } = useOverrides();\n  const simulatedDashboard = overrides?.simulatedDashboard;\n\n  const effectiveLocale = locale.startsWith('en-') ? 'en' : locale;\n\n  return useQuery({\n    queryKey: [\n      simulatedDashboard == null ? 'contracts' : 'simulatedContracts',\n      offerId,\n      effectiveLocale,\n      extension,\n    ],\n    queryFn: async () => {\n      if (simulatedDashboard != null) {\n        return {\n          url: 'https://example.com',\n        } as GetContractResponse;\n      }\n\n      if (offerId == null) return null;\n\n      const response = await axios.get<GetContractResponse>(\n        '/payables-financing/public/v1/contracts',\n        {\n          params: {\n            token,\n            offerId,\n            extension,\n            locale: effectiveLocale,\n          },\n          baseURL: fromEnvironment('INTERNAL_API_BASE_URL'),\n        },\n      );\n\n      return response.data;\n    },\n  });\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport { useOverrides } from '@finmid/tiger-webapp/overrides-manager';\nimport { useQuery } from '@tanstack/react-query';\nimport axios from 'axios';\n\nimport { shortLiving2FaTokenKey } from './constants';\n\nexport interface GetCreditDocResponse {\n  url: string;\n}\n\ninterface GetCreditDocOptions {\n  token: string;\n  creditId: string;\n  document: 'capital-summary' | 'invoice';\n  enabled?: boolean;\n  skip2FA?: boolean;\n}\n\nexport const useGetCreditDoc = ({\n  token,\n  creditId,\n  document,\n  enabled,\n  skip2FA,\n}: GetCreditDocOptions) => {\n  const { overrides } = useOverrides();\n  const simulatedDashboard = overrides?.simulatedDashboard;\n\n  return useQuery({\n    queryKey: [\n      'credits',\n      creditId,\n      simulatedDashboard == null ? 'documents' : 'simulatedDocuments',\n      document,\n    ],\n    queryFn: async () => {\n      if (simulatedDashboard != null) {\n        return {\n          url: 'https://example.com',\n        } as GetCreditDocResponse;\n      }\n\n      const response = await axios.get<GetCreditDocResponse>(\n        `/payables-financing/public/v1/credits/${creditId}/docs/${document}`,\n        {\n          params: {\n            token,\n            twoFactorToken: skip2FA\n              ? undefined\n              : localStorage.getItem(shortLiving2FaTokenKey),\n          },\n          baseURL: fromEnvironment('INTERNAL_API_BASE_URL'),\n          validateStatus(status) {\n            return status == 200 || status == 404;\n          },\n        },\n      );\n\n      return response.data;\n    },\n    refetchOnMount: false,\n    refetchOnWindowFocus: false,\n    enabled,\n  });\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport { useOverrides } from '@finmid/tiger-webapp/overrides-manager';\nimport { useQuery, UseQueryResult } from '@tanstack/react-query';\nimport axios from 'axios';\n\nexport interface CreditID {\n  id: string;\n  acceptedAt: string;\n}\n\nexport interface GetCreditsResponse {\n  credits: CreditID[];\n}\n\ninterface GetCreditsOptions {\n  token: string;\n}\n\nexport const useGetCreditIds = ({\n  token,\n}: GetCreditsOptions): UseQueryResult<GetCreditsResponse, Error> => {\n  const { overrides } = useOverrides();\n  const simulatedDashboard = overrides?.simulatedDashboard;\n  const simulatedCreditIds = simulatedDashboard?.map((ch) => ch.credit.id);\n\n  return useQuery({\n    queryKey: [simulatedCreditIds == null ? 'credits' : 'simulatedCredits'],\n    queryFn: async () => {\n      if (simulatedCreditIds != null) {\n        return {\n          credits: simulatedCreditIds.map((id) => ({\n            id,\n            acceptedAt: new Date().toISOString(),\n          })),\n        };\n      }\n\n      const response = await axios.get<GetCreditsResponse>(\n        '/payables-financing/public/v1/credits',\n        {\n          params: {\n            token,\n          },\n          baseURL: fromEnvironment('INTERNAL_API_BASE_URL'),\n          validateStatus(status) {\n            return status == 200 || status == 404;\n          },\n        },\n      );\n\n      return response.data;\n    },\n    refetchOnMount: false,\n    refetchOnWindowFocus: false,\n  });\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport { ReviewStatus } from '@finmid/tiger-webapp/shared';\nimport type { Currency, Timestamp } from '@finmid/types';\nimport axios from 'axios';\n\nimport { shortLiving2FaTokenKey } from './constants';\nimport {\n  FinancingSetup,\n  RepaymentFrequency,\n  RepaymentType,\n} from './useGetOffers';\n\nexport interface PartialPayment {\n  amount: number;\n  receivedAt: string;\n}\n\nexport interface RepaymentHistoryItem {\n  id: string;\n  salesAmount: number; // Only in FLEXIBLE\n  repaymentAmount: number;\n  remainingAmount: number;\n  status: 'PENDING' | 'FAILED' | 'COMPLETED';\n  batchDate: Timestamp;\n  partialPayments?: PartialPayment[] | null;\n}\n\ninterface Payout {\n  amount: number;\n  fee: number;\n  paidOutAt: Timestamp;\n  totalExpectedRepayment: number;\n}\n\ntype CreditRepaymentMixin<TRepaymentType extends RepaymentType> =\n  TRepaymentType extends 'FIXED'\n    ? {\n        repaymentType: TRepaymentType;\n        repaymentFrequency: RepaymentFrequency;\n        repaymentAmount: number;\n      }\n    : TRepaymentType extends 'FLEXIBLE'\n    ? {\n        repaymentType: TRepaymentType;\n        repaymentPercentage: number;\n      }\n    : never;\n\ntype CreditBase = {\n  id: string;\n  offerId: string;\n  acceptedAt: Timestamp;\n  limit: number;\n  fee: number;\n  remainingAmount: number;\n  repaidAmount: number;\n  dueAt: Timestamp;\n  paidAt: Timestamp | null;\n  currency: Currency;\n  repaymentPeriodMonthsEstimation: number;\n  payout?: Payout | null;\n  status?:\n    | 'PENDING'\n    | 'PAID'\n    | 'REFINANCED'\n    | 'REJECTED'\n    | 'CANCELLED'\n    | 'DEFAULTED';\n  reviewStatus: ReviewStatus;\n};\n\nexport type TypedCredit<\n  TFinancingSetup extends FinancingSetup,\n  TRepaymentType extends RepaymentType,\n> = CreditBase &\n  CreditRepaymentMixin<TRepaymentType> & {\n    financingSetup: TFinancingSetup;\n  };\n\nexport type AcceptedCredit =\n  | TypedCredit<'CSP', 'FIXED'>\n  | TypedCredit<'CSP', 'FLEXIBLE'>\n  | TypedCredit<'MCA', 'FLEXIBLE'>;\n\nexport interface GetRepaymentHistoryResponse {\n  data: RepaymentHistoryItem[];\n  credit: AcceptedCredit;\n  business: {\n    legalName: string | null;\n  };\n}\n\ninterface Options {\n  creditId?: string | null;\n  token: string;\n  skip2FA?: boolean;\n}\n\nexport type GetRepaymentHistoryErrorType =\n  | '2FA_REQUIRED'\n  | 'NETWORK_ERROR'\n  | 'UNKNOWN_ERROR';\n\nexport interface GetRepaymentHistoryError {\n  error: GetRepaymentHistoryErrorType;\n}\n\nexport interface AuthenticationMissingError {\n  error: '2FA_REQUIRED';\n}\n\ntype GetRepaymentHistoryResult =\n  | GetRepaymentHistoryResponse\n  | GetRepaymentHistoryError;\ntype GetRepaymentHistory = Promise<GetRepaymentHistoryResult>;\n\nexport function isGetRepaymentHistoryError(\n  result: unknown,\n): result is GetRepaymentHistoryError {\n  return typeof result === 'object' && result != null && 'error' in result;\n}\n\nexport const getRepaymentHistory = async ({\n  token,\n  creditId,\n  skip2FA,\n}: Options): GetRepaymentHistory => {\n  if (!skip2FA) {\n    const twoFactorToken = localStorage.getItem(shortLiving2FaTokenKey);\n    if (!twoFactorToken) {\n      return {\n        error: '2FA_REQUIRED',\n      };\n    }\n  }\n\n  try {\n    const response = await axios.get<GetRepaymentHistoryResponse>(\n      `/payables-financing/public/v1/credits/${creditId}/repayment-history`,\n      {\n        params: {\n          token,\n          twoFactorToken: skip2FA\n            ? undefined\n            : localStorage.getItem(shortLiving2FaTokenKey),\n        },\n        baseURL: fromEnvironment('INTERNAL_API_BASE_URL'),\n        validateStatus: (status) => status >= 200 && status <= 300,\n      },\n    );\n\n    return response.data;\n  } catch (error) {\n    if (axios.isAxiosError(error) && error.response) {\n      if (error.response.status === 403) {\n        return { error: '2FA_REQUIRED' };\n      }\n      return {\n        error: error.response.data?.code ?? 'UNKNOWN_ERROR',\n      };\n    }\n    return {\n      error: 'NETWORK_ERROR',\n    };\n  }\n};\n","import { useOverrides } from '@finmid/tiger-webapp/overrides-manager';\nimport { useQueries, UseQueryResult } from '@tanstack/react-query';\n\nimport {\n  getRepaymentHistory,\n  GetRepaymentHistoryResponse,\n} from './useGetRepaymentHistory';\n\ninterface Options {\n  creditIds: string[];\n  tryCount: number;\n  token: string;\n  skip2FA?: boolean;\n}\n\nexport const useGetCredits = ({\n  creditIds,\n  tryCount,\n  token,\n  skip2FA,\n}: Options): UseQueryResult<GetRepaymentHistoryResponse | null, Error>[] => {\n  const { overrides } = useOverrides();\n  const simulatedDashboard = overrides?.simulatedDashboard;\n\n  return useQueries({\n    queries:\n      simulatedDashboard == null\n        ? creditIds.map((id) => ({\n            queryKey: ['repaymentHistory', tryCount, id],\n            queryFn: () =>\n              getRepaymentHistory({\n                token: token,\n                creditId: id,\n                skip2FA,\n              }),\n            retry: false,\n            refetchOnMount: tryCount === 0,\n            refetchOnWindowFocus: false,\n          }))\n        : simulatedDashboard.map((creditHistory, index) => ({\n            queryKey: ['repaymentHistorySimulation', tryCount, index],\n            queryFn: () =>\n              Promise.resolve(creditHistory as GetRepaymentHistoryResponse),\n            retry: false,\n            refetchOnMount: false,\n            refetchOnWindowFocus: false,\n          })),\n  });\n};\n","export interface ApiError<TCode extends string = string> {\n  code: TCode;\n  description: string;\n}\n\nexport const isApiError = <TCode extends string = string>(\n  data: unknown,\n): data is ApiError<TCode> => {\n  if (typeof data !== 'object' || data === null) return false;\n  if (typeof (data as Record<string, unknown>)['code'] !== 'string')\n    return false;\n\n  return true;\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport { queryOptions, useQuery } from '@tanstack/react-query';\nimport axios from 'axios';\n\nimport type { ActiveOffersResponse } from './useGetOffers/v3Types';\n\nconst INTERNAL_API_BASE_URL = fromEnvironment('INTERNAL_API_BASE_URL');\n\ninterface Options {\n  token: string;\n  enabled?: boolean;\n}\n\nexport const activeOffersQueryOptions = (token: string) =>\n  queryOptions({\n    queryKey: ['active-offers', token] as const,\n    queryFn: async (): Promise<ActiveOffersResponse> => {\n      const response = await axios.get<ActiveOffersResponse>(\n        '/payables-financing/public/v3/businesses/offers/active',\n        {\n          params: { token },\n          baseURL: INTERNAL_API_BASE_URL,\n          validateStatus(status) {\n            return status === 200 || status === 404;\n          },\n        },\n      );\n\n      if (response.status === 404) {\n        return { offerGroup: null };\n      }\n\n      return response.data;\n    },\n  });\n\nexport const useGetActiveOffers = ({ token, enabled = true }: Options) => {\n  return useQuery({\n    ...activeOffersQueryOptions(token),\n    enabled,\n    refetchOnMount: false,\n  });\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport { queryOptions, useQuery } from '@tanstack/react-query';\nimport axios from 'axios';\n\nimport type { BusinessNonPiiResponse } from './useGetOffers/v3Types';\n\nconst INTERNAL_API_BASE_URL = fromEnvironment('INTERNAL_API_BASE_URL');\n\ninterface Options {\n  token: string;\n  enabled?: boolean;\n}\n\nexport const businessNonPiiQueryOptions = (token: string) =>\n  queryOptions({\n    queryKey: ['business-non-pii', token] as const,\n    queryFn: async (): Promise<BusinessNonPiiResponse> => {\n      const response = await axios.get<BusinessNonPiiResponse>(\n        '/payables-financing/public/v1/businesses/non-pii',\n        {\n          params: { token },\n          baseURL: INTERNAL_API_BASE_URL,\n        },\n      );\n\n      return response.data;\n    },\n  });\n\nexport const useGetBusinessNonPii = ({ token, enabled = true }: Options) => {\n  return useQuery({\n    ...businessNonPiiQueryOptions(token),\n    enabled,\n    refetchOnMount: false,\n  });\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport { queryOptions, useQuery } from '@tanstack/react-query';\nimport axios from 'axios';\n\nimport type { CapitalMaxResponse } from './useGetOffers/v3Types';\n\nconst INTERNAL_API_BASE_URL = fromEnvironment('INTERNAL_API_BASE_URL');\n\ninterface Options {\n  token: string;\n  enabled?: boolean;\n}\n\nexport const capitalMaxQueryOptions = (token: string) =>\n  queryOptions({\n    queryKey: ['capital-max', token] as const,\n    queryFn: async (): Promise<CapitalMaxResponse | null> => {\n      const response = await axios.get<CapitalMaxResponse>(\n        '/payables-financing/public/v1/capital-max',\n        {\n          params: { token },\n          baseURL: INTERNAL_API_BASE_URL,\n          validateStatus(status) {\n            return status === 200 || status === 404;\n          },\n        },\n      );\n\n      if (response.status === 404) {\n        return null;\n      }\n\n      return response.data;\n    },\n  });\n\nexport const useGetCapitalMax = ({ token, enabled = true }: Options) => {\n  return useQuery({\n    ...capitalMaxQueryOptions(token),\n    enabled,\n    refetchOnMount: false,\n  });\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport { queryOptions, useQuery } from '@tanstack/react-query';\nimport axios from 'axios';\n\nimport type {\n  FundingApplicationsResponse,\n  FundingApplicationStatus,\n} from './useGetOffers/v3Types';\n\nconst INTERNAL_API_BASE_URL = fromEnvironment('INTERNAL_API_BASE_URL');\n\ninterface Options {\n  token: string;\n  status?: FundingApplicationStatus;\n  enabled?: boolean;\n}\n\nexport const fundingApplicationsQueryOptions = (token: string) =>\n  queryOptions({\n    queryKey: ['funding-applications', token] as const,\n    queryFn: async (): Promise<FundingApplicationsResponse> => {\n      const response = await axios.get<FundingApplicationsResponse>(\n        '/payables-financing/public/v1/fundings/applications',\n        {\n          params: { token },\n          baseURL: INTERNAL_API_BASE_URL,\n          validateStatus(status) {\n            return status === 200;\n          },\n        },\n      );\n\n      return response.data;\n    },\n  });\n\nexport const useGetFundingApplications = ({\n  token,\n  status,\n  enabled = true,\n}: Options) => {\n  return useQuery({\n    queryKey: ['funding-applications', token, status],\n    queryFn: async (): Promise<FundingApplicationsResponse> => {\n      const response = await axios.get<FundingApplicationsResponse>(\n        '/payables-financing/public/v1/fundings/applications',\n        {\n          params: {\n            token,\n            ...(status ? { status } : {}),\n          },\n          baseURL: INTERNAL_API_BASE_URL,\n          validateStatus(status) {\n            return status === 200;\n          },\n        },\n      );\n\n      return response.data;\n    },\n    enabled,\n    refetchOnMount: false,\n  });\n};\n","import type {\n  CapitalPlusLogicalStatus,\n  ReviewStatus,\n} from '@finmid/tiger-webapp/shared';\nimport type { Currency } from '@finmid/types';\n\nimport type {\n  Advance,\n  CapitalPlus,\n  FinancingSetup,\n  OfferGroup,\n  TypedOffer,\n  TypedOfferGroup,\n} from './types';\nimport type {\n  ActiveOffersResponse,\n  CapitalMaxResponse,\n  FundingApplication,\n  V3FixedOffer,\n  V3FlexibleOffer,\n  V3OfferGroup,\n} from './v3Types';\n\nfunction mapV3FlexibleOffer<T extends FinancingSetup>(\n  offer: V3FlexibleOffer,\n  financingSetup: T,\n  currentOutstandingAmount: number,\n): TypedOffer<T, 'FLEXIBLE'> {\n  const refinancingFee = offer.refinancingFee ?? 0;\n  return {\n    id: offer.id,\n    payoutAmount: offer.payoutAmount,\n    fee: offer.fee,\n    additionalFee: offer.additionalFee ?? 0,\n    refinancingFee,\n    estimatedPayoffMonths: offer.paymentEstimatedMonths,\n    paymentPercentage: offer.paymentPercentage,\n    repaymentType: 'FLEXIBLE',\n    financingSetup,\n    currentOutstandingAmount,\n    totalOutstandingAmount:\n      offer.payoutAmount +\n      offer.fee +\n      refinancingFee +\n      currentOutstandingAmount,\n  } as TypedOffer<T, 'FLEXIBLE'>;\n}\n\nfunction mapV3FixedOffer<T extends FinancingSetup>(\n  offer: V3FixedOffer,\n  financingSetup: T,\n  currentOutstandingAmount: number,\n): TypedOffer<T, 'FIXED'> {\n  const refinancingFee = offer.refinancingFee ?? 0;\n  return {\n    id: offer.id,\n    payoutAmount: offer.payoutAmount,\n    fee: offer.fee,\n    additionalFee: offer.additionalFee ?? 0,\n    refinancingFee,\n    estimatedPayoffMonths: offer.paymentEstimatedMonths,\n    repaymentAmount: offer.paymentAmount,\n    repaymentFrequency: offer.paymentFrequency,\n    repaymentType: 'FIXED',\n    financingSetup,\n    currentOutstandingAmount,\n    totalOutstandingAmount:\n      offer.payoutAmount +\n      offer.fee +\n      refinancingFee +\n      currentOutstandingAmount,\n  } as TypedOffer<T, 'FIXED'>;\n}\n\nexport function mapV3ToOfferGroup(\n  v3: V3OfferGroup,\n  currentOutstandingAmount = 0,\n): OfferGroup {\n  const financingSetup = v3.contract.financingSetup;\n  const collectionMethod = v3.payment.collectionMethod;\n\n  const hasFlexible =\n    Array.isArray(v3.flexibleOffers) && v3.flexibleOffers.length > 0;\n\n  if (hasFlexible) {\n    return {\n      id: v3.id,\n      financingSetup,\n      collectionMethod,\n      repaymentType: 'FLEXIBLE',\n      flexibleOffers: (v3.flexibleOffers ?? []).map((o) =>\n        mapV3FlexibleOffer(o, financingSetup, currentOutstandingAmount),\n      ),\n    } as TypedOfferGroup<typeof financingSetup, 'FLEXIBLE'> as OfferGroup;\n  }\n\n  return {\n    id: v3.id,\n    financingSetup,\n    collectionMethod,\n    repaymentType: 'FIXED',\n    fixedOffers: (v3.fixedOffers ?? []).map((o) =>\n      mapV3FixedOffer(o, financingSetup, currentOutstandingAmount),\n    ),\n  } as TypedOfferGroup<typeof financingSetup, 'FIXED'> as OfferGroup;\n}\n\nfunction mapFundingStatusToReviewStatus(app: FundingApplication): ReviewStatus {\n  switch (app.status) {\n    case 'CREATED':\n      return 'CREATED';\n    case 'IN_REVIEW':\n      return app.requiredActions.length > 0 ? 'DETAILS_REQUIRED' : 'IN_REVIEW';\n    case 'APPROVED':\n      return app.creditId != null ? 'PAYOUT_SUCCESSFUL' : 'IN_PAYOUT';\n    case 'REJECTED':\n      return 'REJECTED';\n  }\n}\n\nexport function mapFundingApplicationToAdvance(\n  app: FundingApplication,\n): Advance {\n  return {\n    id: app.creditId ?? '',\n    isPaidOut: app.status === 'APPROVED' && app.creditId != null,\n    reviewStatus: mapFundingStatusToReviewStatus(app),\n    offerGroupId: app.offerId,\n    financingSetup: undefined,\n    collectionMethod: undefined,\n  };\n}\n\nfunction deriveLogicalStatus(\n  response: CapitalMaxResponse,\n): CapitalPlusLogicalStatus {\n  const inReviewApp = response.applications.find(\n    (a) => a.status === 'IN_REVIEW',\n  );\n  if (inReviewApp) return 'IN_REVIEW';\n\n  if (response.canApply) return 'AVAILABLE';\n\n  const resolvedApp = response.applications.find(\n    (a) => a.status === 'APPROVED' || a.status === 'REJECTED',\n  );\n  if (resolvedApp) return 'FINALIZED';\n\n  return 'NOT_AVAILABLE';\n}\n\nfunction deriveGranularStatus(response: CapitalMaxResponse): string {\n  const inReviewApp = response.applications.find(\n    (a) => a.status === 'IN_REVIEW',\n  );\n  if (inReviewApp) {\n    const hasDocuments = inReviewApp.submissionTypes.includes('DOCUMENTS');\n    const hasBankConnection =\n      inReviewApp.submissionTypes.includes('AISP_CONNECTION');\n    if (hasBankConnection) return 'BANK_CONNECTED';\n    if (hasDocuments) return 'DOCS_SHARED';\n    return 'DOCS_SHARED';\n  }\n\n  const latestResolved = response.applications.find(\n    (a) => a.status === 'APPROVED' || a.status === 'REJECTED',\n  );\n  if (latestResolved) {\n    if (latestResolved.status === 'REJECTED') return 'LIMIT_WITHDRAWN';\n    if (response.canApply) return 'LIMIT_RAISED';\n    return 'LIMIT_UNCHANGED';\n  }\n\n  if (response.canApply) return 'AVAILABLE';\n\n  return 'NOT_AVAILABLE';\n}\n\nexport function mapCapitalMaxToCapitalPlus(\n  response: CapitalMaxResponse,\n): CapitalPlus {\n  return {\n    status: deriveGranularStatus(response) as CapitalPlus['status'],\n    logicalStatus: deriveLogicalStatus(response),\n    minRequestedLimit: response.requestableLimit?.min ?? 0,\n    maxRequestedLimit: response.requestableLimit?.max ?? 0,\n    feeEstimate: response.feeEstimate ?? null,\n  };\n}\n\nexport function pickLatestApplication(\n  apps: FundingApplication[],\n): FundingApplication | null {\n  if (apps.length === 0) return null;\n\n  const active = apps.find(\n    (a) => a.status === 'CREATED' || a.status === 'IN_REVIEW',\n  );\n  if (active) return active;\n\n  const approved = apps.find((a) => a.status === 'APPROVED');\n  if (approved) return approved;\n\n  return apps[0];\n}\n\nexport function extractCurrencyFromV3(\n  v3Response: ActiveOffersResponse | null,\n  fallback: Currency = 'EUR',\n): Currency {\n  return v3Response?.offerGroup?.currency ?? fallback;\n}\n","import type { CapitalPlus } from './types';\nimport type { GetOffersResponse } from './useGetOffers';\n\nexport const baseCapitalPlus: CapitalPlus = {\n  minRequestedLimit: 20000,\n  maxRequestedLimit: 60000,\n  logicalStatus: 'AVAILABLE',\n  status: 'AVAILABLE',\n  feeEstimate: { annualPercentageRate: 0.055 },\n};\n\nexport const multipleMcaOffers: GetOffersResponse = {\n  externalBusinessId: 'multiple-offer-external-business-id',\n  country: 'DEU',\n  maskedPayoutIban: '0101',\n  maskedCollectionIban: '0000',\n  currency: 'EUR',\n  offerGroup: {\n    id: 'multiple-offer-external-business-id',\n    flexibleOffers: [\n      {\n        id: 'ff24de72-ea21-4a56-92ca-e18d22dac4a6',\n        payoutAmount: 5000,\n        fee: 625,\n        paymentPercentage: 12,\n        estimatedPayoffMonths: 4,\n        currentOutstandingAmount: 999,\n        totalOutstandingAmount: 5625,\n        repaymentType: 'FLEXIBLE',\n        financingSetup: 'MCA',\n      },\n      {\n        id: '2e8a2fb9-c6af-4c32-a962-543a1bef9ccf',\n        payoutAmount: 7500,\n        fee: 937.5,\n        paymentPercentage: 13,\n        estimatedPayoffMonths: 6,\n        currentOutstandingAmount: 999,\n        totalOutstandingAmount: 8437.5,\n        repaymentType: 'FLEXIBLE',\n        financingSetup: 'MCA',\n      },\n      {\n        id: '1a06c409-a5e9-48a0-bfe6-c0074dce5fe4',\n        payoutAmount: 10000,\n        fee: 1250,\n        paymentPercentage: 10,\n        estimatedPayoffMonths: 9,\n        currentOutstandingAmount: 999,\n        totalOutstandingAmount: 11250,\n        repaymentType: 'FLEXIBLE',\n        financingSetup: 'MCA',\n      },\n      {\n        id: '9204bfe2-438f-4a52-af72-d9f24b3f2688',\n        payoutAmount: 15000,\n        fee: 1875,\n        paymentPercentage: 25,\n        estimatedPayoffMonths: 6,\n        currentOutstandingAmount: 999,\n        totalOutstandingAmount: 16875,\n        repaymentType: 'FLEXIBLE',\n        financingSetup: 'MCA',\n      },\n      {\n        id: '8b4387eb-f36f-40b4-a8b6-3134acbaf768',\n        payoutAmount: 15000,\n        fee: 1875,\n        paymentPercentage: 15,\n        estimatedPayoffMonths: 10,\n        currentOutstandingAmount: 999,\n        totalOutstandingAmount: 16875,\n        repaymentType: 'FLEXIBLE',\n        financingSetup: 'MCA',\n      },\n      {\n        id: '6010b4a8-f6ab-48d6-a87b-57d878fe73ee',\n        payoutAmount: 15000,\n        fee: 1875,\n        paymentPercentage: 12,\n        estimatedPayoffMonths: 12,\n        currentOutstandingAmount: 999,\n        totalOutstandingAmount: 16875,\n        repaymentType: 'FLEXIBLE',\n        financingSetup: 'MCA',\n      },\n      {\n        id: '8a3fced2-64e0-48de-94e2-fe678b463eab',\n        payoutAmount: 20000,\n        fee: 2500,\n        paymentPercentage: 27,\n        estimatedPayoffMonths: 8,\n        currentOutstandingAmount: 999,\n        totalOutstandingAmount: 22500,\n        repaymentType: 'FLEXIBLE',\n        financingSetup: 'MCA',\n      },\n      {\n        id: '1fb83e02-834d-4110-b48b-77c79e029145',\n        payoutAmount: 20000,\n        fee: 2500,\n        paymentPercentage: 20,\n        estimatedPayoffMonths: 10,\n        currentOutstandingAmount: 999,\n        totalOutstandingAmount: 22500,\n        repaymentType: 'FLEXIBLE',\n        financingSetup: 'MCA',\n      },\n      {\n        id: '155e0cf1-0ff8-42b2-b381-cc6c1329df6e',\n        payoutAmount: 20000,\n        fee: 2500,\n        paymentPercentage: 15,\n        estimatedPayoffMonths: 12,\n        currentOutstandingAmount: 999,\n        totalOutstandingAmount: 22500,\n        repaymentType: 'FLEXIBLE',\n        financingSetup: 'MCA',\n      },\n    ],\n    financingSetup: 'MCA',\n    repaymentType: 'FLEXIBLE',\n    collectionMethod: 'DIRECT_DEBIT',\n  },\n  capitalPlus: baseCapitalPlus,\n  latestCredit: null,\n};\n\nexport const expiredOffersResponse: GetOffersResponse = {\n  externalBusinessId: 'expired-external-business-id',\n  maskedPayoutIban: '0000',\n  maskedCollectionIban: '0000',\n  currency: 'EUR',\n  expired: true,\n  latestCredit: null,\n  country: 'DEU',\n  offerGroup: {\n    id: 'expired-offer-group',\n    flexibleOffers: [\n      {\n        id: 'expired-1',\n        fee: 100,\n        payoutAmount: 9999,\n        paymentPercentage: 10,\n        estimatedPayoffMonths: 10,\n        currentOutstandingAmount: 0,\n        totalOutstandingAmount: 0,\n        repaymentType: 'FLEXIBLE',\n        financingSetup: 'MCA',\n      },\n    ],\n    financingSetup: 'MCA',\n    repaymentType: 'FLEXIBLE',\n    collectionMethod: 'DIRECT_DEBIT',\n  },\n  stub: true,\n};\n\nexport const capitalPlusOfferWithdrawn: GetOffersResponse = {\n  externalBusinessId: 'offer-withdrawn',\n  maskedPayoutIban: '0000',\n  maskedCollectionIban: '0000',\n  currency: 'EUR',\n  country: 'DEU',\n  expired: true,\n  latestCredit: null,\n  offerGroup: {\n    id: 'offer-withdrawn',\n    flexibleOffers: [\n      {\n        id: 'expired-1',\n        fee: 100,\n        payoutAmount: 9999,\n        paymentPercentage: 10,\n        estimatedPayoffMonths: 10,\n        currentOutstandingAmount: 0,\n        totalOutstandingAmount: 0,\n        repaymentType: 'FLEXIBLE',\n        financingSetup: 'MCA',\n      },\n    ],\n    financingSetup: 'MCA',\n    repaymentType: 'FLEXIBLE',\n    collectionMethod: 'DIRECT_DEBIT',\n  },\n  stub: true,\n  capitalPlus: {\n    status: 'LIMIT_WITHDRAWN',\n    logicalStatus: 'FINALIZED',\n    maxRequestedLimit: 0,\n    minRequestedLimit: 0,\n    feeEstimate: null,\n  },\n};\n","import type {\n  FinancingSetup,\n  OfferGroup,\n  RepaymentType,\n  TypedOffer,\n  TypedOfferGroup,\n} from './types';\n\nexport const transformOfferGroup = (\n  offerGroup: OfferGroup | null,\n): OfferGroup | null => {\n  if (offerGroup == null) {\n    return null;\n  }\n\n  switch (offerGroup.financingSetup) {\n    case 'CSP':\n      // eslint-disable-next-line no-case-declarations\n      const repaymentType =\n        'flexibleOffers' in offerGroup && offerGroup.flexibleOffers.length > 0\n          ? 'FLEXIBLE'\n          : 'FIXED';\n\n      switch (repaymentType) {\n        case 'FIXED': // OfferGroupBase<\"CSP\", \"FIXED\">\n          // eslint-disable-next-line no-case-declarations\n          const fixedOfferGroup = offerGroup as TypedOfferGroup<'CSP', 'FIXED'>;\n          return {\n            ...fixedOfferGroup,\n            repaymentType,\n            fixedOffers: transformOffers(fixedOfferGroup.fixedOffers ?? [])(\n              'CSP',\n              'FIXED',\n            ),\n          };\n        case 'FLEXIBLE': // OfferGroupBase<\"CSP\", \"FLEXIBLE\">\n        default:\n          // eslint-disable-next-line no-case-declarations\n          const flexibleOfferGroup = offerGroup as TypedOfferGroup<\n            'CSP',\n            'FLEXIBLE'\n          >;\n          return {\n            ...flexibleOfferGroup,\n            repaymentType,\n            flexibleOffers: transformOffers(\n              flexibleOfferGroup.flexibleOffers ?? [],\n            )('CSP', 'FLEXIBLE'),\n          };\n      }\n    case 'MCA': // OfferGroupBase<\"MCA\", \"FLEXIBLE\">\n    default:\n      return {\n        ...offerGroup,\n        flexibleOffers: transformOffers(offerGroup.flexibleOffers ?? [])(\n          'MCA',\n          'FLEXIBLE',\n        ),\n      };\n  }\n};\n\nconst transformOffers =\n  <\n    TFinancingSetup extends FinancingSetup,\n    TRepaymentType extends RepaymentType,\n  >(\n    offers: TypedOffer<TFinancingSetup, TRepaymentType>[],\n  ) =>\n  (\n    financingSetup: TFinancingSetup,\n    type: TRepaymentType,\n  ): TypedOffer<TFinancingSetup, TRepaymentType>[] => {\n    return offers.map((offer) => {\n      return {\n        ...offer,\n        repaymentType: type,\n        financingSetup,\n      };\n    });\n  };\n","import { useOverrides } from '@finmid/tiger-webapp/overrides-manager';\n\nimport { baseCapitalPlus, multipleMcaOffers } from './mocks';\nimport type { TypedOfferGroup } from './types';\nimport type { GetOffersResponse } from './useGetOffers';\n\nexport const useSimulatedResponse = () => {\n  const { overrides } = useOverrides();\n  const overriddenOffers = overrides?.offers;\n  const simulatedDashboard = overrides?.simulatedDashboard;\n  const maxStatus = overrides?.maxStatus;\n  const overriddenCollectionMethod = overrides?.collectionMethod;\n  const overriddenReviewStatus = overrides?.offerReviewStatus;\n\n  const shouldShowSimulatedOffers =\n    simulatedDashboard != null ||\n    (overriddenOffers && overriddenOffers !== 'no-override') ||\n    (overriddenCollectionMethod &&\n      overriddenCollectionMethod !== 'no-override');\n\n  const baseOffers = multipleMcaOffers;\n  if (maxStatus) {\n    baseOffers.capitalPlus = {\n      ...baseCapitalPlus,\n      logicalStatus: maxStatus,\n    };\n  }\n  if (overriddenOffers === 'single') {\n    if (baseOffers.offerGroup == null) {\n      throw new Error('Offer group is null');\n    }\n\n    const offerGroup = baseOffers.offerGroup as TypedOfferGroup<\n      'MCA',\n      'FLEXIBLE'\n    >;\n\n    baseOffers.offerGroup = {\n      id: offerGroup.id,\n      financingSetup: 'MCA',\n      repaymentType: 'FLEXIBLE',\n      collectionMethod: 'DIRECT_DEBIT',\n      flexibleOffers: [\n        offerGroup.flexibleOffers[offerGroup.flexibleOffers.length - 1],\n      ],\n    };\n  }\n  if (overriddenOffers === 'expired') {\n    baseOffers.expired = true;\n  }\n  if (overriddenOffers === 'rejected') {\n    baseOffers.expired = true;\n    baseOffers.capitalPlus = {\n      status: 'LIMIT_WITHDRAWN',\n      logicalStatus: 'FINALIZED',\n      maxRequestedLimit: 0,\n      minRequestedLimit: 0,\n      feeEstimate: null,\n    };\n  }\n\n  // Apply collection method override if specified\n  if (\n    overriddenCollectionMethod &&\n    overriddenCollectionMethod !== 'no-override' &&\n    baseOffers.offerGroup\n  ) {\n    baseOffers.offerGroup = {\n      ...baseOffers.offerGroup,\n      collectionMethod: overriddenCollectionMethod,\n    };\n  }\n\n  if (overriddenReviewStatus && baseOffers.latestCredit != null) {\n    baseOffers.latestCredit.reviewStatus = overriddenReviewStatus;\n  }\n\n  const extraForDashboard = simulatedDashboard\n    ? { expired: false, latestCredit: {} }\n    : {};\n\n  const simulatedResponse = {\n    ...baseOffers,\n    ...extraForDashboard,\n  } as GetOffersResponse;\n\n  return { shouldShowSimulatedOffers, simulatedResponse };\n};\n","import { type countriesIso3Codes } from '@finmid/countries';\nimport { fromEnvironment } from '@finmid/environment';\nimport {\n  Overrides,\n  useOverrides,\n} from '@finmid/tiger-webapp/overrides-manager';\nimport { Currency, isApiError } from '@finmid/types';\nimport { useQuery, useQueryClient } from '@tanstack/react-query';\nimport axios from 'axios';\nimport posthog from 'posthog-js';\n\nimport { activeOffersQueryOptions } from '../useGetActiveOffers';\nimport { businessNonPiiQueryOptions } from '../useGetBusinessNonPii';\nimport { capitalMaxQueryOptions } from '../useGetCapitalMax';\nimport { fundingApplicationsQueryOptions } from '../useGetFundingApplications';\n\nimport {\n  extractCurrencyFromV3,\n  mapCapitalMaxToCapitalPlus,\n  mapFundingApplicationToAdvance,\n  mapV3ToOfferGroup,\n  pickLatestApplication,\n} from './adapters';\nimport { capitalPlusOfferWithdrawn, expiredOffersResponse } from './mocks';\nimport { transformOfferGroup } from './transformOfferGroup';\nimport { Advance, CapitalPlus, OfferGroup } from './types';\nimport { useSimulatedResponse } from './useSimulatedResponse';\n\nconst INTERNAL_API_BASE_URL = fromEnvironment('INTERNAL_API_BASE_URL');\n\nexport interface GetOffersResponse {\n  externalBusinessId: string;\n  maskedPayoutIban: string;\n  maskedCollectionIban: string;\n\n  country: (typeof countriesIso3Codes)[number];\n\n  offerGroup: OfferGroup | null;\n\n  latestCredit: Advance | null;\n  phoneLastFour?: string;\n  currency: Currency;\n  expired?: boolean;\n\n  capitalPlus?: CapitalPlus;\n\n  stub?: true;\n}\n\ninterface V2ExtractedData {\n  externalBusinessId: string;\n  maskedPayoutIban: string;\n  maskedCollectionIban: string;\n  country: (typeof countriesIso3Codes)[number];\n  phoneLastFour?: string;\n  currency: Currency;\n  v2CapitalPlus?: CapitalPlus;\n  v2OfferGroup: OfferGroup | null;\n  v2LatestCredit: Advance | null;\n  v2Expired?: boolean;\n}\n\ninterface BusinessFields {\n  externalBusinessId: string;\n  maskedPayoutIban: string;\n  maskedCollectionIban: string;\n  country: (typeof countriesIso3Codes)[number];\n  phoneLastFour?: string;\n  currency: Currency;\n}\n\ninterface Options {\n  token: string;\n  ignoreAction: boolean;\n  refetchOnWindowFocus?: boolean;\n  refetchInterval?: number;\n}\ntype GetOffersErrorCode = 'OFFER_EXPIRED' | 'CAPITAL_PLUS_OFFER_WITHDRAWN';\n\nexport const useGetOffers = ({\n  token,\n  ignoreAction,\n  refetchOnWindowFocus,\n  refetchInterval,\n}: Options) => {\n  const { overrides } = useOverrides();\n  const { shouldShowSimulatedOffers, simulatedResponse } =\n    useSimulatedResponse();\n  const queryClient = useQueryClient();\n\n  return useQuery({\n    queryKey: shouldShowSimulatedOffers ? ['simulatedOffers'] : ['offers'],\n    queryFn: async (): Promise<GetOffersResponse> => {\n      if (shouldShowSimulatedOffers)\n        return applyOfferOverrides(simulatedResponse, overrides);\n\n      const [\n        activeOffersResult,\n        applicationsResult,\n        capitalMaxResult,\n        nonPiiResult,\n        v2Result,\n      ] = await Promise.all([\n        queryClient\n          .fetchQuery(activeOffersQueryOptions(token))\n          .catch(() => null),\n        queryClient\n          .fetchQuery(fundingApplicationsQueryOptions(token))\n          .catch(() => null),\n        queryClient.fetchQuery(capitalMaxQueryOptions(token)).catch(() => null),\n        queryClient\n          .fetchQuery(businessNonPiiQueryOptions(token))\n          .catch(() => null),\n        fetchV2Full(token, ignoreAction).catch(\n          () => ({ type: 'error', response: expiredOffersResponse } as const),\n        ),\n      ]);\n\n      if (v2Result.type === 'error') {\n        return v2Result.response;\n      }\n\n      const v2Data = v2Result.data;\n\n      const businessFields: BusinessFields = nonPiiResult\n        ? {\n            externalBusinessId: nonPiiResult.externalId,\n            maskedPayoutIban: nonPiiResult.payoutAccountNumberEnding,\n            maskedCollectionIban: nonPiiResult.collectionAccountNumberEnding,\n            country:\n              nonPiiResult.country as (typeof countriesIso3Codes)[number],\n            currency: nonPiiResult.currency as Currency,\n            ...(nonPiiResult.phoneEnding != null\n              ? { phoneLastFour: nonPiiResult.phoneEnding }\n              : {}),\n          }\n        : {\n            externalBusinessId: v2Data.externalBusinessId,\n            maskedPayoutIban: v2Data.maskedPayoutIban,\n            maskedCollectionIban: v2Data.maskedCollectionIban,\n            country: v2Data.country,\n            currency: v2Data.currency,\n            ...(v2Data.phoneLastFour != null\n              ? { phoneLastFour: v2Data.phoneLastFour }\n              : {}),\n          };\n\n      const offerGroup =\n        activeOffersResult?.offerGroup != null\n          ? mapV3ToOfferGroup(\n              activeOffersResult.offerGroup,\n              activeOffersResult.context?.currentOutstandingAmount ?? 0,\n            )\n          : v2Data.v2OfferGroup;\n\n      const transformedOfferGroup = transformOfferGroup(offerGroup);\n\n      const latestApp =\n        applicationsResult != null\n          ? pickLatestApplication(applicationsResult.data)\n          : null;\n      const latestCredit = latestApp\n        ? {\n            ...mapFundingApplicationToAdvance(latestApp),\n            // v1 doesn't return financingSetup / collectionMethod — carry them over from v2\n            financingSetup: v2Data.v2LatestCredit?.financingSetup ?? undefined,\n            collectionMethod:\n              v2Data.v2LatestCredit?.collectionMethod ?? undefined,\n          }\n        : applicationsResult != null\n        ? null\n        : v2Data.v2LatestCredit;\n\n      const currency = extractCurrencyFromV3(\n        activeOffersResult,\n        businessFields.currency,\n      );\n\n      const expired =\n        v2Data.v2Expired ||\n        (transformedOfferGroup == null && latestCredit == null);\n\n      const capitalPlus = capitalMaxResult\n        ? mapCapitalMaxToCapitalPlus(capitalMaxResult)\n        : v2Data.v2CapitalPlus;\n\n      const data: GetOffersResponse = {\n        externalBusinessId: businessFields.externalBusinessId,\n        maskedPayoutIban: businessFields.maskedPayoutIban,\n        maskedCollectionIban: businessFields.maskedCollectionIban,\n        country: businessFields.country,\n        currency,\n        offerGroup: transformedOfferGroup,\n        latestCredit,\n        capitalPlus,\n        expired,\n        ...(businessFields.phoneLastFour != null\n          ? { phoneLastFour: businessFields.phoneLastFour }\n          : {}),\n        ...(expired ? { stub: true as const } : {}),\n      };\n\n      if (data.externalBusinessId != null) {\n        posthog.setPersonProperties(\n          {},\n          { externalBusinessId: data.externalBusinessId },\n        );\n      }\n\n      if (data.country != null) {\n        posthog.setPersonProperties({ country: data.country });\n      }\n\n      return applyOfferOverrides(data, overrides);\n    },\n    refetchOnWindowFocus: !!refetchOnWindowFocus,\n    refetchOnMount: false,\n    refetchInterval,\n  });\n};\n\ntype V2FetchResult =\n  | { type: 'success'; data: V2ExtractedData }\n  | { type: 'error'; response: GetOffersResponse };\n\nasync function fetchV2Full(\n  token: string,\n  ignoreAction: boolean,\n): Promise<V2FetchResult> {\n  const response = await axios.get<GetOffersResponse>(\n    '/payables-financing/public/v2/available-offers',\n    {\n      params: { token, ignoreAction },\n      baseURL: INTERNAL_API_BASE_URL,\n      validateStatus(status) {\n        return status == 200 || status == 404;\n      },\n    },\n  );\n\n  if (response.status == 404) {\n    const error = response.data;\n\n    if (isApiError<GetOffersErrorCode>(error)) {\n      switch (error.code) {\n        case 'OFFER_EXPIRED':\n          return { type: 'error', response: expiredOffersResponse };\n        case 'CAPITAL_PLUS_OFFER_WITHDRAWN':\n          return { type: 'error', response: capitalPlusOfferWithdrawn };\n      }\n    }\n\n    return { type: 'error', response: expiredOffersResponse };\n  }\n\n  return {\n    type: 'success',\n    data: {\n      externalBusinessId: response.data.externalBusinessId,\n      maskedPayoutIban: response.data.maskedPayoutIban,\n      maskedCollectionIban: response.data.maskedCollectionIban,\n      country: response.data.country,\n      phoneLastFour: response.data.phoneLastFour,\n      currency: response.data.currency,\n      v2CapitalPlus: response.data.capitalPlus,\n      v2OfferGroup: response.data.offerGroup,\n      v2LatestCredit: response.data.latestCredit,\n      v2Expired: response.data.expired,\n    },\n  };\n}\n\nconst applyOfferOverrides = (\n  offer: GetOffersResponse,\n  overrides?: Overrides,\n) => {\n  const maxStatus = overrides?.maxStatus;\n  const overriddenCollectionMethod = overrides?.collectionMethod;\n  const overriddenReviewStatus = overrides?.offerReviewStatus;\n\n  if (maxStatus) {\n    offer.capitalPlus = {\n      ...offer.capitalPlus,\n      logicalStatus: maxStatus,\n    } as CapitalPlus;\n  }\n  if (overriddenCollectionMethod) {\n    offer.offerGroup = {\n      ...offer.offerGroup,\n      collectionMethod: overriddenCollectionMethod,\n    } as OfferGroup;\n  }\n  if (overriddenReviewStatus) {\n    offer.latestCredit = {\n      ...offer.latestCredit,\n      reviewStatus: overriddenReviewStatus,\n    } as Advance;\n  }\n\n  return offer;\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport axios from 'axios';\n\nimport { PlatformData } from './types';\n\nconst BASE_URL = fromEnvironment('INTERNAL_API_BASE_URL');\nconst PLATFORM_API_BASE_URL = `${BASE_URL}/distributor-master-data/public/v1/`;\n\nconst getAxiosInstance = () =>\n  axios.create({\n    baseURL: PLATFORM_API_BASE_URL,\n  });\n\ntype PlatformApiResponse = Omit<PlatformData, 'supportEmail'> & {\n  supportEmailConfiguration?: {\n    defaultSupportEmail: string;\n    marketConfigurations: { market: string; supportEmail: string }[];\n  };\n};\n\nexport const platformApi = {\n  getPlatformData: async (platformDomain: string) => {\n    const api = getAxiosInstance();\n\n    const response = await api.get<PlatformApiResponse>('distributors', {\n      params: { domain: platformDomain },\n    });\n\n    return response;\n  },\n\n  getPlatformDataById: async (id: string) => {\n    const api = getAxiosInstance();\n\n    const response = await api.get<PlatformApiResponse>(`distributors/${id}`);\n\n    return response;\n  },\n};\n","import { PlatformData, platformApi } from '@finmid/api/internal/platform';\nimport { useSuspenseQuery } from '@tanstack/react-query';\nimport { useLocalStorage } from 'react-use';\n\nexport const useGetPlatformData = (id: string) => {\n  const [overrides] = useLocalStorage<{\n    platformId: string;\n    environment: string;\n    platformData?: PlatformData;\n  }>('overrides');\n\n  return useSuspenseQuery({\n    queryKey: ['platform', overrides?.platformId ?? id],\n    queryFn: async () => {\n      if (overrides?.platformData) {\n        return overrides?.platformData;\n      }\n\n      const { data } = await platformApi.getPlatformDataById(\n        overrides?.platformId ?? id,\n      );\n\n      return data;\n    },\n  });\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';\nimport axios from 'axios';\n\nexport type OnboardingState =\n  | 'NOT_FOUND'\n  | 'AVAILABLE'\n  | 'IN_PROGRESS'\n  | 'IN_REVIEW'\n  | 'REJECTED'\n  | 'APPROVED'\n  | 'EXPIRED';\n\nexport type GetOnboardingResponse =\n  | {\n      status: Exclude<OnboardingState, 'REJECTED'>;\n      id: string;\n    }\n  | {\n      status: Extract<OnboardingState, 'REJECTED'>;\n      id: string;\n      rejectionReason: string;\n    };\n\ntype PostSubmitOnboardingRequest = {\n  token: string;\n};\n\ninterface Options {\n  token: string;\n}\n\nexport const useGetOnboarding = ({ token }: Options) => {\n  return useQuery({\n    queryKey: ['onboarding'],\n    queryFn: async () => {\n      const response = await axios.get<GetOnboardingResponse>(\n        `/payables-financing/public/v1/onboardings/latest`,\n        {\n          params: {\n            token,\n          },\n          baseURL: fromEnvironment('INTERNAL_API_BASE_URL'),\n          validateStatus: () => true,\n          transformResponse: (response, _, status) =>\n            status === 404 ? { state: 'NOT_FOUND' } : JSON.parse(response),\n        },\n      );\n\n      return response.data;\n    },\n  });\n};\n\nexport const useSubmitOnboarding = () => {\n  const queryClient = useQueryClient();\n\n  return useMutation({\n    mutationFn: async ({ token }: PostSubmitOnboardingRequest) => {\n      const response = await axios.post<object>(\n        `/payables-financing/public/v1/onboardings/latest/submit`,\n        null,\n        {\n          params: {\n            token,\n          },\n          baseURL: fromEnvironment('INTERNAL_API_BASE_URL'),\n        },\n      );\n\n      return response;\n    },\n    onSuccess: () =>\n      queryClient.invalidateQueries({ queryKey: ['onboarding'] }),\n  });\n};\n","import { fromEnvironment } from '@finmid/environment';\nimport { useMutation, useQueryClient } from '@tanstack/react-query';\nimport axios from 'axios';\n\ninterface PostCapitalPlusRequestOptions {\n  token: string;\n  newLimit: number;\n}\n\nexport const usePostCapitalPlusRequest = () => {\n  const queryClient = useQueryClient();\n\n  return useMutation({\n    mutationFn: async ({ token, newLimit }: PostCapitalPlusRequestOptions) => {\n      return await axios.post(\n        `/payables-financing/public/v1/capital-plus/request`,\n        {\n          newLimit,\n        },\n        {\n          params: {\n            token,\n          },\n          baseURL: fromEnvironment('INTERNAL_API_BASE_URL'),\n          validateStatus(status) {\n            return status == 200 || status == 204;\n          },\n        },\n      );\n    },\n    onSuccess: () =>\n      queryClient.invalidateQueries({\n        queryKey: ['post-capital-plus-request'],\n      }),\n  });\n};\n","import type { CountryIso3Code } from '@finmid/countries';\nimport { useGetOffers } from '@finmid/tiger-webapp/queries';\nimport { useEffect } from 'react';\nimport { useLocalStorage } from 'react-use';\n\nimport { usePlatformSettings } from '../PlatformSettings';\nimport { useTokenContext } from '../TokenContext';\n\nconst servedTimeZones = {\n  'Europe/Amsterdam': 'NLD',\n  'Europe/Berlin': 'DEU',\n  'Europe/Brussels': 'BEL',\n  'Europe/Bucharest': 'ROU',\n  'Europe/Budapest': 'HUN',\n  'Europe/Copenhagen': 'DNK',\n  'Europe/Dublin': 'IRL',\n  'Europe/Helsinki': 'FIN',\n  'Europe/Lisbon': 'PRT',\n  'Europe/London': 'GBR',\n  'Europe/Luxembourg': 'LUX',\n  'Europe/Madrid': 'ESP',\n  'Europe/Oslo': 'NOR',\n  'Europe/Paris': 'FRA',\n  'Europe/Prague': 'CZE',\n  'Europe/Rome': 'ITA',\n  'Europe/Sofia': 'BGR',\n  'Europe/Stockholm': 'SWE',\n  'Europe/Vienna': 'AUT',\n  'Europe/Warsaw': 'POL',\n  'Europe/Zurich': 'CHE',\n} as const;\n\nexport const getCountryFromTimeZone = (defaultCountry: CountryIso3Code) => {\n  const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;\n\n  if (timeZone == null || timeZone.trim() === '') return defaultCountry;\n\n  return (\n    servedTimeZones[timeZone as keyof typeof servedTimeZones] ?? defaultCountry\n  );\n};\n\nconst params = new URLSearchParams(window.location.search);\nconst countryFromUrl = params.get('c') as CountryIso3Code | null;\n\nexport const useCountrySettings = () => {\n  const { countryOptions } = usePlatformSettings();\n\n  const { token, ignoreAction } = useTokenContext();\n  const { data } = useGetOffers({ token, ignoreAction });\n\n  const offerCountry = data?.country;\n\n  const [countryOverride = null, setCountryOverride, clearCountryOverride] =\n    useLocalStorage<CountryIso3Code>('countryOverride');\n\n  useEffect(() => {\n    if (countryFromUrl) setCountryOverride(countryFromUrl);\n  }, [setCountryOverride]);\n\n  useEffect(() => {\n    if (import.meta.env.DEV) {\n      // eslint-disable-next-line @typescript-eslint/ban-ts-comment\n      // @ts-ignore\n      window['setCountryOverride'] = setCountryOverride;\n      // eslint-disable-next-line @typescript-eslint/ban-ts-comment\n      // @ts-ignore\n      window['clearCountryOverride'] = clearCountryOverride;\n    }\n  }, [clearCountryOverride, setCountryOverride]);\n\n  const country: CountryIso3Code =\n    countryOverride ??\n    offerCountry ??\n    countryFromUrl ??\n    getCountryFromTimeZone('DEU');\n\n  const countrySettings = countryOptions?.[country] ?? null;\n\n  return {\n    countrySettings,\n    country,\n  };\n};\n","export type Country = {\n  name: string;\n  iso2code: string;\n  iso3code: string;\n  flag: string;\n};\n\nexport const countries = [\n  { name: 'Curaçao', iso2code: 'CW', iso3code: 'CUW', flag: '🇨🇼' },\n  { name: 'Germany', iso2code: 'DE', iso3code: 'DEU', flag: '🇩🇪' },\n  { name: 'Austria', iso2code: 'AT', iso3code