o3code: 'URY', flag: '🇺🇾' },\n  { name: 'Uzbekistan', iso2code: 'UZ', iso3code: 'UZB', flag: '🇺🇿' },\n  { name: 'Vanuatu', iso2code: 'VU', iso3code: 'VUT', flag: '🇻🇺' },\n  { name: 'Venezuela', iso2code: 'VE', iso3code: 'VEN', flag: '🇻🇪' },\n  { name: 'Viet Nam', iso2code: 'VN', iso3code: 'VNM', flag: '🇻🇳' },\n  {\n    name: 'Virgin Islands, British',\n    iso2code: 'VG',\n    iso3code: 'VGB',\n    flag: '🇻🇬',\n  },\n  { name: 'Virgin Islands, U.S.', iso2code: 'VI', iso3code: 'VIR', flag: '🇻🇮' },\n  { name: 'Wallis and Futuna', iso2code: 'WF', iso3code: 'WLF', flag: '🇼🇫' },\n  { name: 'Western Sahara', iso2code: 'EH', iso3code: 'ESH', flag: '🇪🇭' },\n  { name: 'Yemen', iso2code: 'YE', iso3code: 'YEM', flag: '🇾🇪' },\n  { name: 'Zambia', iso2code: 'ZM', iso3code: 'ZMB', flag: '🇿🇲' },\n  { name: 'Zimbabwe', iso2code: 'ZW', iso3code: 'ZWE', flag: '🇿🇼' },\n] as const;\n\n// prettier-ignore\nexport const countriesIso3Codes = [\n  \"CUW\", \"DEU\", \"AUT\", \"CHE\", \"AFG\", \"ALA\", \"ALB\", \"DZA\", \"ASM\", \"AND\",\n  \"AGO\", \"AIA\", \"ATA\", \"ATG\", \"ARG\", \"ARM\", \"ABW\", \"AUS\", \"AZE\", \"BHS\",\n  \"BHR\", \"BGD\", \"BRB\", \"BLR\", \"BEL\", \"BLZ\", \"BEN\", \"BMU\", \"BTN\", \"BOL\",\n  \"BIH\", \"BWA\", \"BVT\", \"BRA\", \"IOT\", \"BRN\", \"BGR\", \"BFA\", \"BDI\", \"KHM\",\n  \"CMR\", \"CAN\", \"CPV\", \"CYM\", \"CAF\", \"TCD\", \"CHL\", \"CHN\", \"CXR\", \"CCK\",\n  \"COL\", \"COM\", \"COG\", \"COD\", \"COK\", \"CRI\", \"CIV\", \"HRV\", \"CUB\", \"CYP\",\n  \"CZE\", \"DNK\", \"DJI\", \"DMA\", \"DOM\", \"ECU\", \"EGY\", \"SLV\", \"GNQ\", \"ERI\",\n  \"EST\", \"ETH\", \"FLK\", \"FRO\", \"FJI\", \"FIN\", \"FRA\", \"GUF\", \"PYF\", \"ATF\",\n  \"GAB\", \"GMB\", \"GEO\", \"GHA\", \"GIB\", \"GRC\", \"GRL\", \"GRD\", \"GLP\", \"GUM\",\n  \"GTM\", \"GGY\", \"GIN\", \"GNB\", \"GUY\", \"HTI\", \"HMD\", \"VAT\", \"HND\", \"HKG\",\n  \"HUN\", \"ISL\", \"IND\", \"IDN\", \"IRN\", \"IRQ\", \"IRL\", \"IMN\", \"ISR\", \"ITA\",\n  \"JAM\", \"JPN\", \"JEY\", \"JOR\", \"KAZ\", \"KEN\", \"KIR\", \"PRK\", \"KOR\", \"KWT\",\n  \"KGZ\", \"LAO\", \"LVA\", \"LBN\", \"LSO\", \"LBR\", \"LBY\", \"LIE\", \"LTU\", \"LUX\",\n  \"MAC\", \"MKD\", \"MDG\", \"MWI\", \"MYS\", \"MDV\", \"MLI\", \"MLT\", \"MHL\", \"MTQ\",\n  \"MRT\", \"MUS\", \"MYT\", \"MEX\", \"FSM\", \"MDA\", \"MCO\", \"MNG\", \"MSR\", \"MAR\",\n  \"MOZ\", \"MMR\", \"NAM\", \"NRU\", \"NPL\", \"NLD\", \"ANT\", \"NCL\", \"NZL\", \"NIC\",\n  \"NER\", \"NGA\", \"NIU\", \"NFK\", \"MNP\", \"NOR\", \"OMN\", \"PAK\", \"PLW\", \"PSE\",\n  \"PAN\", \"PNG\", \"PRY\", \"PER\", \"PHL\", \"PCN\", \"POL\", \"PRT\", \"PRI\", \"QAT\",\n  \"REU\", \"ROU\", \"RUS\", \"RWA\", \"SHN\", \"KNA\", \"LCA\", \"SPM\", \"VCT\", \"WSM\",\n  \"SMR\", \"STP\", \"SAU\", \"SEN\", \"SXM\", \"BES\", \"SSD\", \"SRB\", \"MAF\", \"BLM\",\n  \"MNE\", \"SYC\", \"SLE\", \"SGP\", \"SVK\", \"SVN\", \"SLB\", \"SOM\", \"ZAF\", \"SGS\",\n  \"ESP\", \"LKA\", \"SDN\", \"SUR\", \"SJM\", \"SWZ\", \"SWE\", \"SYR\", \"TWN\", \"TJK\",\n  \"TZA\", \"THA\", \"TLS\", \"TGO\", \"TKL\", \"TON\", \"TTO\", \"TUN\", \"TUR\", \"TKM\",\n  \"TCA\", \"TUV\", \"UGA\", \"UKR\", \"ARE\", \"GBR\", \"USA\", \"UMI\", \"URY\", \"UZB\",\n  \"VUT\", \"VEN\", \"VNM\", \"VGB\", \"VIR\", \"WLF\", \"ESH\", \"YEM\", \"ZMB\", \"ZWE\"\n] as const;\n\nexport type CountryIso3Code = (typeof countriesIso3Codes)[number];\nexport type CountryIso2Code = (typeof countries)[number]['iso2code'];\n\nexport const allowedCountriesIsoCode3 = countriesIso3Codes.filter(\n  (c) => c !== 'ANT',\n);\n\nexport type AllowedCountryIso3Code = (typeof allowedCountriesIsoCode3)[number];\n","import { countries, Country } from './countries';\n\n/**\n * Retrieves the country information based on the provided country code.\n *\n * @param code - The country code to search for. It can be either a 2-letter or 3-letter code.\n * @returns The country object that matches the provided code, or undefined if no match is found.\n */\nexport const getCountry = (code: string | null): Country | undefined => {\n  return countries.find((c) =>\n    code?.length === 3 ? c.iso3code === code : c.iso2code === code,\n  );\n};\n","import { getCountry } from '@finmid/countries';\nimport { ENVIRONMENT } from '@finmid/environment';\nimport { useGetOffers, useGetPlatformData } from '@finmid/tiger-webapp/queries';\nimport posthog from 'posthog-js';\nimport { useEffect } from 'react';\n\nimport { useTokenContext } from '../TokenContext';\n\nexport const useMerchantGroup = () => {\n  const { token, businessId, ignoreAction, platformId } = useTokenContext();\n  const { data: platformData } = useGetPlatformData(platformId);\n\n  const { data: offers } = useGetOffers({\n    token,\n    ignoreAction,\n  });\n\n  const externalBusinessId = offers?.externalBusinessId;\n  const country = offers?.country;\n  const platformName = platformData?.name;\n\n  useEffect(() => {\n    if (\n      externalBusinessId != null &&\n      country != null &&\n      platformName != null &&\n      ENVIRONMENT === 'live'\n    )\n      posthog.group('merchant', businessId, {\n        externalBusinessId,\n        country: getCountry(country)?.name,\n        platformName,\n      });\n  }, [businessId, externalBusinessId, country, platformName]);\n};\n","import { useGetOffers } from '@finmid/tiger-webapp/queries';\n\nimport { useTokenContext } from '../TokenContext';\n\nexport const useOfferStatus = () => {\n  const { token, ignoreAction } = useTokenContext();\n  const { data } = useGetOffers({ token, ignoreAction });\n\n  const hasCurrentCredit = data?.latestCredit != null;\n  const hasNewOffers = data?.offerGroup != null;\n  const lastOfferIsPaidOut = data?.latestCredit?.isPaidOut;\n\n  return {\n    hasCurrentCredit,\n    hasNewOffers,\n    lastOfferIsPaidOut,\n  };\n};\n","import { useTheme } from '@emotion/react';\nimport { useMediaQuery } from '@mui/material';\n\nexport const useResponsive = () => {\n  const { breakpoints } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n\n  return { isMobile };\n};\n","import { ENVIRONMENT } from '@finmid/environment';\nimport { useGetOffers, useGetPlatformData } from '@finmid/tiger-webapp/queries';\nimport posthog from 'posthog-js';\nimport { useEffect } from 'react';\n\nimport { useTokenContext } from '../TokenContext';\n\nexport const useSetPersonProperties = () => {\n  const { token, ignoreAction, platformId } = useTokenContext();\n  const { data: platformData } = useGetPlatformData(platformId);\n\n  const { data: offers } = useGetOffers({\n    token,\n    ignoreAction,\n  });\n\n  const externalBusinessId =\n    offers?.stub === true ? undefined : offers?.externalBusinessId;\n  const country = offers?.stub === true ? undefined : offers?.country;\n  const platformName = platformData?.name;\n\n  useEffect(() => {\n    if (\n      externalBusinessId != null &&\n      country != null &&\n      platformName != null &&\n      ENVIRONMENT === 'live'\n    )\n      posthog.setPersonProperties({\n        externalBusinessId,\n        country,\n        platformId,\n        platformName,\n      });\n  }, [externalBusinessId, country, platformName, platformId]);\n};\n","import { useMerchantGroup } from './useMerchantGroup';\nimport { useSetPersonProperties } from './useSetPersonProperties';\n\nexport const useSetPostHogData = () => {\n  useMerchantGroup();\n  useSetPersonProperties();\n};\n","import { SupportedLocales } from './formatters';\n\nexport const detectedLanguageConverter =\n  (allowedLngs: SupportedLocales) =>\n  (lng: string): string => {\n    if (Object.keys(allowedLngs).includes(lng)) {\n      return lng;\n    }\n\n    const localeOnly = lng.split('-')[0];\n    if (localeOnly in allowedLngs) {\n      return localeOnly;\n    }\n\n    const partial = Object.keys(allowedLngs).find((l) =>\n      l.startsWith(localeOnly),\n    );\n    if (partial) {\n      return partial;\n    }\n\n    console.warn(`Language ${lng} is not supported, falling back to en.`);\n    return 'en';\n  };\n","import { format as formatDate } from 'date-fns/format';\nimport { formatDistance } from 'date-fns/formatDistance';\nimport { formatRelative } from 'date-fns/formatRelative';\nimport { isDate } from 'date-fns/isDate';\nimport { Locale } from 'date-fns/types';\n\nimport { PluginFormatFunction } from './PluginFormatFunction';\n\nexport type DateFormat =\n  | 'date'\n  | 'dateAtTime'\n  | 'dateDots'\n  | 'shortDate'\n  | 'longDate'\n  | 'longDateTime'\n  | 'relativeDate'\n  | 'shortMonthYear'\n  | 'ago';\n\nexport type SupportedLocales = Record<string, Locale>;\n\ninterface Options {\n  variant: DateFormat;\n  supportedLocales: SupportedLocales;\n}\n\nconst formatter: PluginFormatFunction<Date, string, Options> = (\n  value,\n  lng,\n  options,\n) => {\n  const { variant, supportedLocales } = options;\n  const locale = supportedLocales[lng];\n\n  switch (variant) {\n    case 'date':\n      return formatDate(value, 'P', { locale });\n    case 'dateAtTime':\n      return formatDate(value, \"P ' @ ' H:mm\", { locale });\n    case 'shortDate':\n      return formatDate(value, 'PP', { locale });\n    case 'longDate':\n      return formatDate(value, 'PPPp', { locale });\n    case 'longDateTime':\n      return formatDate(value, 'PPP, HH:mm', { locale });\n    case 'shortMonthYear':\n      return formatDate(value, 'MMM y', { locale });\n    case 'relativeDate':\n      return formatRelative(value, new Date(), { locale });\n    case 'ago':\n      return formatDistance(value, new Date(), {\n        locale,\n        addSuffix: true,\n      });\n    default:\n      // eslint-disable-next-line no-console\n      console.error(\n        'Invalid date time format options, falling back to default',\n        options,\n      );\n      return formatDate(value, 'PPPp', { locale });\n  }\n};\n\nexport const dateFormatter: PluginFormatFunction = (value, lng, options) => {\n  if (isDate(value)) {\n    const dateVariant =\n      options.variant != null ? options.variant : { variant: 'long' };\n    return formatter(value as Date, lng ?? 'en', {\n      ...options,\n      ...dateVariant,\n    });\n  }\n\n  // eslint-disable-next-line no-console\n  console.error(\n    'Invalid date passed to format, falling back to default',\n    value,\n  );\n  return value;\n};\n","import type { i18n } from 'i18next';\n\nimport { dateFormatter, SupportedLocales } from './dateFormatters';\n\nexport const registerFormatters = (\n  i18next: i18n,\n  supportedLocales: SupportedLocales,\n) => {\n  i18next.services.formatter?.add('datetime', (value, lng, options) => {\n    return dateFormatter(value, lng, { ...options, supportedLocales });\n  });\n};\n","import { ENVIRONMENT } from '@finmid/environment';\nimport globalI18next, { FallbackLng, i18n, PostProcessorModule } from 'i18next';\nimport LanguageDetector, {\n  DetectorOptions,\n} from 'i18next-browser-languagedetector';\nimport Backend from 'i18next-locize-backend';\nimport { locizePlugin } from 'locize';\nimport { initReactI18next } from 'react-i18next';\n\nimport { SupportedLocales, registerFormatters } from './formatters';\n\ninterface Options {\n  locizeOptions?: LocizeOptions;\n\n  useSuspense?: boolean;\n  fallbackLng?: FallbackLng;\n  detectorOptions?: DetectorOptions;\n  debug?: boolean;\n  defaultVariables?: Record<string, string>;\n  postProcess?: PostProcessorModule;\n}\n\ninterface LocizeOptions {\n  projectId: string;\n  apiKey?: string;\n  referenceLng?: string;\n  enableInContextEditing?: boolean;\n  version?: 'latest' | 'experimental';\n}\n\nexport async function initializeTranslations(\n  {\n    locizeOptions,\n    // enable when we are using <Suspense />\n    useSuspense = false,\n    fallbackLng,\n    detectorOptions,\n    debug,\n    defaultVariables,\n    postProcess,\n  }: Options,\n  i18next: i18n = globalI18next,\n  supportedLocales: SupportedLocales,\n) {\n  if (locizeOptions != null) {\n    i18next.use(Backend);\n\n    if (locizeOptions.enableInContextEditing) i18next.use(locizePlugin);\n  }\n\n  await i18next\n    .use(postProcess || { type: '3rdParty', init: () => undefined })\n    .use(initReactI18next)\n    .use(LanguageDetector)\n    .init({\n      // Only on local machine, when app is not rendered in locize InContext editor frame\n      saveMissing: ENVIRONMENT === 'localhost' && window.parent === window,\n      debug,\n      fallbackLng: fallbackLng ?? {\n        de: ['de-DE'],\n        default: ['en'],\n      },\n      appendNamespaceToCIMode: true,\n\n      interpolation: {\n        // react already safes from xss => https://www.i18next.com/translation-function/interpolation#unescape\n        escapeValue: false,\n        defaultVariables: defaultVariables,\n      },\n\n      detection: detectorOptions,\n      backend: locizeOptions,\n\n      react: {\n        useSuspense,\n        bindI18n: 'languageChanged editorSaved',\n      },\n\n      postProcess: postProcess?.name,\n    });\n\n  registerFormatters(i18next, supportedLocales);\n\n  return i18next;\n}\n","export function formatList<T>(\n  t: (k: string, options?: { defaultValue: string }) => string,\n  items: T[],\n  type: 'or' | 'and',\n): (T | string)[] {\n  const result: (T | string)[] = [];\n\n  const { length } = items;\n\n  items.map((item, index) => {\n    result.push(item);\n\n    if (index === length - 1) {\n      // do nothing\n    } else if (index === length - 2) {\n      result.push(t('list.lastSeparator', { defaultValue: ',' }));\n      result.push(' ');\n      result.push(t(`list.${type}`, { defaultValue: type }));\n      result.push('\\xa0'); // non-breakable space\n    } else {\n      result.push(t('list.separator', { defaultValue: ',' }));\n      result.push(' ');\n    }\n\n    return null;\n  });\n\n  return result;\n}\n","import { fromEnvironment } from '@finmid/environment';\nimport type { Currency } from '@finmid/types';\nimport type SerializedCurrency from 'currency.js';\nimport { useCallback } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nconst MINIMUM_FRACTION_DIGITS = fromEnvironment(\n  'FORMAT_MONEY_DEFAULT_MINIMUM_FRACTION_DIGITS',\n  {\n    required: false,\n  },\n);\n\nconst defaultMoneyOptions = {\n  minimumFractionDigits:\n    MINIMUM_FRACTION_DIGITS == null\n      ? undefined\n      : Number(MINIMUM_FRACTION_DIGITS),\n};\n\nconst currencyOptionsOverrides: Partial<\n  Record<Currency, Intl.NumberFormatOptions>\n> = {\n  HUF: {\n    maximumFractionDigits: 0,\n  },\n};\n\nexport const useMoneyFormatter = () => {\n  const {\n    t,\n    ready,\n    i18n: { language },\n  } = useTranslation('formats');\n\n  return useCallback(\n    (\n      amount: number | SerializedCurrency,\n      currency: Currency,\n      options?: Intl.NumberFormatOptions,\n    ) => {\n      const actualAmount = typeof amount === 'number' ? amount : amount.value;\n\n      const currencyOptions = currencyOptionsOverrides[currency] ?? {};\n      const effectiveOptions = {\n        ...(options ?? defaultMoneyOptions),\n        ...currencyOptions,\n      };\n\n      return t('money', {\n        amount: actualAmount,\n        currency,\n        defaultValue: '{{ amount, currency }}',\n        ...effectiveOptions,\n      });\n    },\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n    [language, ready, t],\n  );\n};\n","import type { Currency, Timestamp } from '@finmid/types';\nimport type SerializedCurrency from 'currency.js';\nimport { useCallback } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { DateFormat } from './formatters/dateFormatters';\nimport { formatList } from './formatters/formatList';\nimport { useMoneyFormatter } from './formatters/useMoneyFormatter';\n\ntype Formats = {\n  ready: boolean;\n  /** Returns the currency symbol for a given currency code */\n  currencySymbol: (currency: Currency) => string | undefined;\n\n  /**\n   * Formats a monetary amount with the specified currency and formatting options\n   * @param amount - The amount to format (can be a number or SerializedCurrency)\n   * @param currency - The currency code to use for formatting\n   * @param options - Optional Intl.NumberFormat options for customizing the format\n   * @returns Formatted monetary string\n   */\n  money: (\n    amount: number | SerializedCurrency,\n    currency: Currency,\n    options?: Intl.NumberFormatOptions,\n  ) => string;\n\n  /**\n   * Formats a large number with appropriate separators and decimal places\n   * @param amount - The number to format\n   * @returns Formatted number string\n   */\n  formatNumber: (amount: number) => string;\n\n  /**\n   * Formats a decimal percentage with the specified number of fractional digits\n   * @param decimalPercent - The decimal percentage to format\n   * @param options - Optional Intl.NumberFormat options for customizing the format\n   * @returns Formatted percentage string\n   */\n  formatPercent: (\n    decimalPercent: number,\n    options?: Intl.NumberFormatOptions,\n  ) => string;\n\n  /**\n   * Formats an array of items into a list with appropriate conjunctions\n   * @param items - Array of items to format\n   * @param type - The type of conjunction to use ('or' or 'and')\n   * @returns Array containing the formatted list items and conjunctions\n   */\n  list: <T>(items: T[], type: 'or' | 'and') => (T | string)[];\n\n  /**\n   * Formats a position number and total into a string (e.g. \"1 of 10\")\n   * @param nth - The position number\n   * @param total - The total number of items\n   * @returns Formatted position string\n   */\n  nthOfTotal: (nth: number, total: number) => string;\n\n  /**\n   * Formats a number of months into a string (e.g. \"10 months\")\n   * @param months - The number of months to format\n   * @returns Formatted months string\n   */\n  months: (months: number) => string;\n\n  /**\n   * @deprecated This shouldn't be used, the format must be defined by the locale\n   */\n  dateAtTime: (dateOrTimestamp: Date | Timestamp) => string;\n\n  /**\n   * @deprecated This shouldn't be used, the format must be defined by the locale\n   */\n  dateDots: (dateOrTimestamp: Date | Timestamp) => string;\n} & Record<DateFormat, (date: Date | Timestamp) => string>;\n\nexport const useFormat = (): Formats => {\n  const {\n    t,\n    ready,\n    i18n: { language },\n  } = useTranslation('formats');\n\n  const money = useMoneyFormatter();\n\n  const formatNumber = useCallback(\n    (amount: number) => {\n      return t('number', {\n        amount,\n        defaultValue: '{{ amount, number }}',\n      });\n    },\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n    [language, ready, t],\n  );\n\n  const formatPercent = useCallback(\n    (decimalPercent: number, options?: Intl.NumberFormatOptions) => {\n      return t('percent', {\n        amount: decimalPercent,\n        ...options,\n        style: 'percent',\n        defaultValue: '{{ amount, number, percent }}',\n      });\n    },\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n    [language, ready, t],\n  );\n\n  const currencySymbol = (currency: Currency) =>\n    new Intl.NumberFormat(language, { style: 'currency', currency })\n      .formatToParts(1)\n      .find((x) => x.type === 'currency')?.value ?? currency;\n\n  const formatDate = useCallback(\n    (dateOrTimestamp: Date | Timestamp) => {\n      const date =\n        typeof dateOrTimestamp === 'string'\n          ? new Date(dateOrTimestamp)\n          : dateOrTimestamp;\n\n      return t('date', {\n        date,\n        variant: 'date',\n        defaultValue: '{{ date, datetime }}',\n      });\n    },\n    [t],\n  );\n\n  const dateAtTime = useCallback(\n    // This shouldn't be used, the format must be defined by the locale\n    (dateOrTimestamp: Date | Timestamp) => {\n      const date =\n        typeof dateOrTimestamp === 'string'\n          ? new Date(dateOrTimestamp)\n          : dateOrTimestamp;\n\n      return t('date', {\n        date,\n        variant: 'dateAtTime',\n        defaultValue: '{{ date, datetime }}',\n      }).replace(/[\"/\"]/g, '.');\n    },\n    [t],\n  );\n\n  const dateDots = useCallback(\n    // This shouldn't be used, the format must be defined by the locale\n    (dateOrTimestamp: Date | Timestamp) => {\n      const date =\n        typeof dateOrTimestamp === 'string'\n          ? new Date(dateOrTimestamp)\n          : dateOrTimestamp;\n\n      return t('date', {\n        date,\n        variant: 'date',\n        defaultValue: '{{ date, datetime }}',\n      }).replace(/[\"/\"]/g, '.');\n    },\n    [t],\n  );\n\n  const shortMonthYear = useCallback(\n    (dateOrTimestamp: Date | Timestamp) => {\n      const date =\n        typeof dateOrTimestamp === 'string'\n          ? new Date(dateOrTimestamp)\n          : dateOrTimestamp;\n\n      return t('date', {\n        date,\n        variant: 'shortMonthYear',\n        defaultValue: '{{ date, datetime }}',\n      });\n    },\n    [t],\n  );\n\n  const shortDate = useCallback(\n    (dateOrTimestamp: Date | Timestamp) => {\n      const date =\n        typeof dateOrTimestamp === 'string'\n          ? new Date(dateOrTimestamp)\n          : dateOrTimestamp;\n\n      return t('date', {\n        date,\n        variant: 'shortDate',\n        defaultValue: '{{ date, datetime }}',\n      });\n    },\n    [t],\n  );\n\n  const longDate = useCallback(\n    (dateOrTimestamp: Date | Timestamp) => {\n      const date =\n        typeof dateOrTimestamp === 'string'\n          ? new Date(dateOrTimestamp)\n          : dateOrTimestamp;\n\n      return t('date', {\n        date,\n        variant: 'longDate',\n        defaultValue: '{{ date, datetime }}',\n      });\n    },\n    [t],\n  );\n\n  const longDateTime = useCallback(\n    (dateOrTimestamp: Date | Timestamp) => {\n      const date =\n        typeof dateOrTimestamp === 'string'\n          ? new Date(dateOrTimestamp)\n          : dateOrTimestamp;\n\n      return t('date', {\n        date,\n        variant: 'longDateTime',\n        defaultValue: '{{ date, datetime }}',\n      });\n    },\n    [t],\n  );\n\n  const relativeDate = useCallback(\n    (dateOrTimestamp: Date | Timestamp) => {\n      const date =\n        typeof dateOrTimestamp === 'string'\n          ? new Date(dateOrTimestamp)\n          : dateOrTimestamp;\n\n      return t('date', {\n        date,\n        variant: 'relativeDate',\n        defaultValue: '{{ date, datetime }}',\n      });\n    },\n    [t],\n  );\n\n  const ago = useCallback(\n    (dateOrTimestamp: Date | Timestamp) => {\n      const date =\n        typeof dateOrTimestamp === 'string'\n          ? new Date(dateOrTimestamp)\n          : dateOrTimestamp;\n\n      return t('date', {\n        date,\n        variant: 'ago',\n        defaultValue: '{{ date, datetime }}',\n      });\n    },\n    [t],\n  );\n\n  const months = useCallback(\n    (months: number) =>\n      t('months', { count: months, defaultValue: '{{count}} months' }),\n    [t],\n  );\n\n  const list = useCallback(\n    <T>(items: T[], type: 'or' | 'and') => formatList(t, items, type),\n    [t],\n  );\n\n  const nthOfTotal = useCallback(\n    (nth: number, total: number) =>\n      t(`nthOfTotal`, { nth, total, defaultValue: '{{nth}} of {{total}}' }),\n    [t],\n  );\n\n  return {\n    currencySymbol,\n    money,\n    formatNumber,\n    formatPercent,\n    date: formatDate,\n    dateAtTime,\n    dateDots,\n    shortDate,\n    longDate,\n    longDateTime,\n    relativeDate,\n    shortMonthYear,\n    ago,\n    list,\n    nthOfTotal,\n    months,\n    ready,\n  };\n};\n","import type { CountryIso2Code } from '@finmid/countries';\nimport { Resource } from 'i18next';\nimport { useEffect, useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nexport type LanguageCode =\n  | 'en'\n  | 'da'\n  | 'fi'\n  | 'fr'\n  | 'pl'\n  | 'sv'\n  | 'de'\n  | 'lt'\n  | 'lv'\n  | 'cs'\n  | 'sl'\n  | 'el'\n  | 'sk'\n  | 'hu'\n  | 'hr'\n  | 'ro'\n  | 'et';\n\nexport interface LanguageOption {\n  selected: boolean;\n  selectLanguage: () => Promise<unknown>;\n  name: string;\n  languageCode: LanguageCode;\n  localeCode: CountryIso2Code;\n  localeAndLanguage: string;\n}\n\nconst languageNativeNameOverrides: Record<string, string> = {\n  'fr-FR': 'Français',\n};\n\nconst sortLanguagesByNativeName = (languages: LanguageOption[]) => {\n  return languages.sort((l1, l2) =>\n    l1.name === 'cimode' ? -1 : l1.name.localeCompare(l2.name),\n  );\n};\n\nexport const useLanguages = (\n  allowedLocales?: string[] | undefined,\n  includeCimode = false,\n) => {\n  const { i18n, ready } = useTranslation();\n\n  const [lngs, setLngs] = useState<Resource>({\n    en: { nativeName: 'English' },\n    'de-DE': { nativeName: 'Deutsch' },\n  });\n\n  useEffect(() => {\n    if (ready && i18n.services.backendConnector.backend.getLanguages)\n      i18n.services.backendConnector.backend.getLanguages(\n        (err: string, ret: Resource) => {\n          if (err) return; // TODO: handle err...\n          const resources = !allowedLocales\n            ? ret\n            : allowedLocales.reduce(\n                (acc, current) =>\n                  ret[current] == null\n                    ? acc\n                    : {\n                        ...acc,\n                        [current]: ret[current],\n                      },\n                {},\n              );\n\n          setLngs(resources);\n        },\n      );\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [ready]);\n\n  const languages = Object.keys(lngs).map<LanguageOption>((lng) => ({\n    selected: lng === i18n.resolvedLanguage,\n    selectLanguage: () => i18n.changeLanguage(lng),\n    name:\n      languageNativeNameOverrides[lng] ?? lngs[lng]['nativeName'].toString(),\n    languageCode: (lng.split('-')[0] ?? 'en') as LanguageCode,\n    localeCode: (lng.split('-')[1]?.toUpperCase() ?? 'GB') as CountryIso2Code,\n    localeAndLanguage: lng,\n  }));\n\n  if (includeCimode) {\n    languages.push({\n      name: 'cimode',\n      localeAndLanguage: 'cimode',\n      selected: i18n.language === 'cimode',\n      selectLanguage: async () => {\n        await i18n.changeLanguage('cimode');\n      },\n      languageCode: 'cimode' as 'en',\n      localeCode: 'cimode' as 'GB',\n    });\n  }\n\n  const selectedLanguage =\n    languages.find((l) => l.selected) ??\n    languages.find((l) => l.name === 'English');\n\n  const sortedLanguages = sortLanguagesByNativeName(languages);\n\n  return {\n    languages: sortedLanguages,\n    selectedLanguage,\n  };\n};\n","import { Offer, useGetOffers } from '@finmid/tiger-webapp/queries';\nimport { Currency } from '@finmid/types';\nimport posthog from 'posthog-js';\nimport { useCallback, useEffect } from 'react';\n\nimport { useTokenContext } from './TokenContext';\n\nexport const getLngFromLocale = (language: string) => {\n  return language.split('-')[0];\n};\n\nconst localeUnspecificMoney = (number: number, currency?: Currency | null) =>\n  new Intl.NumberFormat('de-DE', {\n    style: 'currency',\n    currency: currency ?? 'EUR',\n    maximumFractionDigits: 0,\n  }).format(number);\n\ninterface TrackingFlags {\n  capitalPlus?: true;\n  renewal?: true;\n}\n\nexport const useCapturePosthogViewed = (\n  event: string,\n  data?: {\n    offer?: Offer | null;\n  } & Record<string, unknown>,\n) => {\n  const capturePosthogEvent = useCapturePosthogEvent();\n  useEffect(() => {\n    capturePosthogEvent(event, data);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n};\n\nexport const useCapturePosthogEvent = () => {\n  const { token, ignoreAction } = useTokenContext();\n  const { data: availableOffersData } = useGetOffers({\n    token,\n    ignoreAction,\n  });\n\n  const capturePosthogEvent = useCallback(\n    (\n      event: string,\n      data?: {\n        /**\n         * This field is already captured in the offer object\n         */\n        limit?: never;\n\n        /**\n         * This field is already captured in the offer object\n         */\n        fee?: never;\n      } & {\n        offer?: Offer | null;\n        currency?: Currency | null;\n      } & Record<string, unknown>,\n    ) => {\n      const eventData = {\n        ...data,\n        country: availableOffersData?.country,\n        ...(data?.offer?.payoutAmount\n          ? {\n              limit: localeUnspecificMoney(\n                data.offer.payoutAmount,\n                data?.currency,\n              ),\n              fee: localeUnspecificMoney(data.offer.fee, data?.currency),\n            }\n          : null),\n      };\n      posthog.capture(event, eventData);\n    },\n    [availableOffersData],\n  );\n  return capturePosthogEvent;\n};\n\nexport const captureOfferEvent = (\n  event: string,\n  offer: Offer | null | undefined,\n  currency: Currency | null,\n  features?: TrackingFlags,\n  extraProperties?: Record<string, string>,\n) => {\n  posthog.capture(event, {\n    ...offer,\n    limit: localeUnspecificMoney(offer?.payoutAmount ?? 0, currency),\n    fee: localeUnspecificMoney(offer?.fee ?? 0, currency),\n    ...extraProperties,\n    features,\n  });\n};\n\nexport function humanReadableFileSize(bytes: number) {\n  let u = 0;\n  const s = 1024;\n  while (bytes >= s || -bytes >= s) {\n    bytes /= s;\n    u++;\n  }\n  return (u ? bytes.toFixed(1) + ' ' : bytes) + ' KMGTPEZY'[u] + 'B';\n}\n\nexport function formatRepaymentRate(rate?: number) {\n  if (rate === undefined) {\n    return undefined;\n  }\n\n  return `${rate.toFixed(1)}`.replace(/\\.0+$/, '');\n}\n\n/**\n * Calculates the CSS width for a given number of columns in a 12-column grid layout for desktop view.\n *\n * @param columns - The number of columns to span.\n * @returns The CSS width as a string, calculated based on the total width minus padding.\n *\n * Example usage:\n * ```typescript\n * {\n *   ...\n *   maxWidth: cssDesktopColumns(3); // \"calc((100% - 208px) / 12 * 3)\"\n * }\n * ```\n */\nexport function cssDesktopColumns(columns: number) {\n  const layoutPadding = 104;\n  return `calc((min(1200px, 100vw - ${\n    layoutPadding * 2\n  }px)) / 12 * ${columns})`;\n}\n","import {\n  FinancingSetup,\n  useGetOffers,\n  type CollectionMethod,\n  type Offer,\n} from '@finmid/tiger-webapp/queries';\nimport { useFormat } from '@finmid/translations';\nimport { Currency } from '@finmid/types';\nimport {\n  createContext,\n  Dispatch,\n  FunctionComponent,\n  PropsWithChildren,\n  SetStateAction,\n  useCallback,\n  useContext,\n  useEffect,\n  useState,\n} from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useTokenContext } from './TokenContext';\nimport { UseOfFunds } from './UseOfFundsSection';\nimport { formatRepaymentRate } from './utils';\n\nexport interface SelectedOfferContextValue {\n  selectOffer: (value: Offer, isSingle: boolean, currency: Currency) => void;\n  clearSelectedOffer: () => void;\n  selectedOffer: Offer | null;\n  isSingle: boolean | null;\n  currency: Currency | null;\n  financingSetup: FinancingSetup;\n  collectionMethod: CollectionMethod;\n  /**\n   * CSP-specific use of funds\n   */\n  useOfFunds: UseOfFunds;\n\n  /**\n   * Set CSP-specific use of funds\n   */\n  setUseOfFunds: Dispatch<SetStateAction<UseOfFunds>>;\n\n  offerGroupId: string | null;\n}\n\nexport const SelectedOfferContext = createContext<SelectedOfferContextValue>(\n  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion\n  null!,\n);\n\nexport const SelectedOfferProvider: FunctionComponent<PropsWithChildren> = ({\n  children,\n}) => {\n  const { token, ignoreAction } = useTokenContext();\n\n  const { i18n } = useTranslation();\n  const [isSingle, setIsSingle] = useState<boolean | null>(null);\n  const [currency, setCurrency] = useState<Currency | null>(null);\n\n  const { data } = useGetOffers({\n    token: token,\n    ignoreAction: ignoreAction,\n  });\n\n  const financingSetup =\n    data?.offerGroup?.financingSetup ??\n    data?.latestCredit?.financingSetup ??\n    /** Should always be loaded by this point */ 'CSP';\n\n  const collectionMethod: CollectionMethod =\n    data?.offerGroup?.collectionMethod ??\n    data?.latestCredit?.collectionMethod ??\n    'DIRECT_DEBIT';\n\n  const offerGroupId =\n    data?.offerGroup?.id ?? data?.latestCredit?.offerGroupId ?? null;\n\n  const [selectedOffer, setSelectedOffer] = useState<Offer | null>(null);\n\n  const [useOfFunds, setUseOfFunds] = useState<UseOfFunds>({\n    values: [],\n    comment: undefined,\n  });\n\n  const { money } = useFormat();\n\n  useEffect(() => {\n    // update default variables for translation interpolation when the selected offer changes\n    if (i18n.options.interpolation && selectedOffer) {\n      i18n.options.interpolation.defaultVariables = {\n        ...i18n.options.interpolation?.defaultVariables,\n        offerLimit: money(selectedOffer?.payoutAmount, currency ?? 'EUR', {\n          maximumFractionDigits: 0,\n        }),\n        offerMonths: selectedOffer?.estimatedPayoffMonths,\n        offerFee: selectedOffer?.fee,\n        offerRepaymentPercent:\n          'paymentPercentage' in selectedOffer &&\n          formatRepaymentRate(selectedOffer?.paymentPercentage),\n      };\n    }\n  }, [selectedOffer, i18n, money, currency]);\n\n  const selectOffer = useCallback(\n    (value: Offer, isSingle: boolean, currency: Currency) => {\n      setSelectedOffer(value);\n      setIsSingle(isSingle);\n      setCurrency(currency);\n    },\n    [],\n  );\n\n  const clearSelectedOffer = useCallback(() => {\n    setSelectedOffer(null);\n  }, []);\n\n  return (\n    <SelectedOfferContext.Provider\n      value={{\n        financingSetup,\n        isSingle,\n        currency,\n        offerGroupId,\n        collectionMethod,\n        selectedOffer,\n        selectOffer,\n        clearSelectedOffer,\n\n        useOfFunds,\n        setUseOfFunds,\n      }}\n    >\n      {children}\n    </SelectedOfferContext.Provider>\n  );\n};\n\nexport const useSelectedOffer = () => {\n  return useContext(SelectedOfferContext);\n};\n","import { zodResolver } from '@hookform/resolvers/zod';\nimport { useCallback, useMemo } from 'react';\nimport { useForm } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\nimport { z } from 'zod';\n\nimport { useSelectedOffer } from '../SelectedOfferContext';\n\nexport const toggles = [\n  'NEW_EQUIPMENT',\n  'RENOVATIONS',\n  'NEW_VENUE',\n  'MARKETING',\n  'BILLS',\n  'OTHER',\n] as const;\n\nexport type UseOfFundsToggle = (typeof toggles)[number];\n\nexport type UseOfFunds = {\n  values: UseOfFundsToggle[];\n  comment?: string;\n};\n\nexport const MAX_COMMENT_LENGTH = 500;\n\nexport const useUseOfFundsForm = () => {\n  const { setUseOfFunds, useOfFunds: defaultValues } = useSelectedOffer();\n  const { t, ready } = useTranslation('offers', {\n    keyPrefix: 'review.CSP.capitalSummary.useOfFunds',\n  });\n\n  const validationSchema = useMemo(\n    () =>\n      z.object({\n        values: z.array(z.enum(toggles)),\n        comment: z\n          .union([\n            z.string().max(\n              MAX_COMMENT_LENGTH,\n              t('comment.maxLength', {\n                defaultValue: `Comment cannot exceed ${MAX_COMMENT_LENGTH} characters`,\n                maxLength: MAX_COMMENT_LENGTH,\n              }),\n            ),\n            z.literal(''),\n          ])\n          .optional(),\n      }),\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n    [t, ready],\n  );\n\n  const form = useForm<UseOfFunds>({\n    resolver: zodResolver(validationSchema),\n    defaultValues: defaultValues ?? {\n      values: [],\n      comment: undefined,\n    },\n    mode: 'onChange',\n  });\n\n  const { watch, setValue, formState } = form;\n\n  const handleUseOfFundsChange = useCallback(\n    (toggle: UseOfFundsToggle) => {\n      const currentToggles = watch('values');\n      if (currentToggles.includes(toggle)) {\n        const newValues = currentToggles.filter((t) => t !== toggle);\n        setValue('values', newValues, { shouldValidate: true });\n        setUseOfFunds(({ comment }) => ({\n          values: newValues,\n          comment,\n        }));\n      } else {\n        const newValues = [...currentToggles, toggle];\n        setValue('values', newValues, { shouldValidate: true });\n        setUseOfFunds(({ comment }) => ({\n          values: newValues,\n          comment,\n        }));\n      }\n    },\n    [watch, setValue, setUseOfFunds],\n  );\n\n  const handleCommentChange = useCallback(\n    (comment: string) => {\n      setValue('comment', comment, { shouldValidate: true });\n\n      setUseOfFunds(({ values: useOfFunds }) => ({\n        values: useOfFunds,\n        comment,\n      }));\n    },\n    [setValue, setUseOfFunds],\n  );\n\n  return {\n    handleUseOfFundsChange,\n    handleCommentChange,\n    formState,\n    form,\n  };\n};\n","import { useSelectedOffer } from '../SelectedOfferContext';\nimport { MAX_COMMENT_LENGTH } from '../UseOfFundsSection/useUseOfFundsForm';\n\nexport const useIsValidUseOfFunds = () => {\n  const { useOfFunds, financingSetup } = useSelectedOffer();\n\n  if (financingSetup !== 'CSP') {\n    return true;\n  }\n\n  const commentLenght = useOfFunds.comment?.trim().length ?? 0;\n\n  if (commentLenght > MAX_COMMENT_LENGTH) {\n    return false;\n  }\n\n  const hasComment = commentLenght > 0;\n  const hasSelection = useOfFunds.values.length > 0;\n\n  return hasSelection || hasComment;\n};\n","import { usePlatform } from '@finmid/platforms';\nimport { useGetOffers } from '@finmid/tiger-webapp/queries';\n\nimport { useTokenContext } from '../TokenContext';\n\nexport const usePlatformSupportEmail = () => {\n  const { token } = useTokenContext();\n  const { data: offers } = useGetOffers({\n    token,\n    ignoreAction: true,\n  });\n\n  const { supportEmailConfiguration } = usePlatform();\n  const defaultSupportEmail =\n    supportEmailConfiguration?.defaultSupportEmail ?? '';\n\n  if (offers == null) return defaultSupportEmail;\n\n  const { country } = offers;\n\n  const countrySpecificSupportEmail =\n    supportEmailConfiguration?.marketConfigurations?.find(\n      (se) => se.market === country,\n    );\n\n  const supportEmail =\n    countrySpecificSupportEmail?.supportEmail ?? defaultSupportEmail;\n\n  return supportEmail;\n};\n","import memoize from '@emotion/memoize';\nimport styled from '@emotion/styled';\nimport { CircularProgress, CircularProgressProps } from '@mui/material';\nimport { palette, PaletteProps } from '@mui/system';\n\nexport type LoaderProps = {\n  className?: string;\n} & Omit<CircularProgressProps, 'color'> &\n  PaletteProps;\n\nconst shouldForwardProp = memoize((prop) => prop !== 'color');\n\nexport const LoaderCircle = styled(CircularProgress, {\n  shouldForwardProp,\n})<LoaderProps>`\n  ${palette}\n`;\n\nconst Wrapper = styled.span`\n  position: absolute;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n`;\n\nexport const Loader = (props: LoaderProps) => (\n  <Wrapper>\n    <LoaderCircle {...props} />\n  </Wrapper>\n);\n","import styled from '@emotion/styled';\n\nimport { Loader } from './Loader';\n\nconst Wrapper = styled.div({\n  height: '100vh',\n  width: '100vw',\n  position: 'relative',\n  display: 'flex',\n  alignItems: 'center',\n  justifyContent: 'center',\n});\n\nexport const FullPageLoader = () => (\n  <Wrapper>\n    <Loader />\n  </Wrapper>\n);\n","import { Theme } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { Typography as TypographyBase } from '@mui/material';\nimport merge from 'lodash/merge';\nimport { CSSProperties, PropsWithChildren } from 'react';\n\nimport { ColorVariables, TypographyVariables } from './PlatformSettings';\n\ntype BreakpointAwareProp<T> = T | [T /* mobile */, T /* desktop */];\n\ntype Props = {\n  [T in keyof Omit<\n    TypographyVariables,\n    'weight' | 'lineHeight' | 'family'\n  >]: BreakpointAwareProp<keyof TypographyVariables[T]>;\n} & {\n  /**\n   * @default 'grey900'\n   */\n  color?: keyof ColorVariables;\n\n  /**\n   * @default 'normal'\n   */\n  fontStyle?: CSSProperties['fontStyle'];\n\n  /**\n   * @default 'default'\n   */\n  weight?: BreakpointAwareProp<keyof TypographyVariables['weight']>;\n\n  /**\n   * @default Will be same as `size`\n   */\n  lineHeight?: BreakpointAwareProp<keyof TypographyVariables['lineHeight']>;\n\n  /**\n   * @default 'body'\n   */\n  family?: BreakpointAwareProp<keyof TypographyVariables['family']>;\n};\n\nexport const Typography = styled(\n  ({\n    children,\n    className,\n    component = 'p',\n  }: PropsWithChildren<{\n    className?: string;\n    component?: 'p' | 'span' | 'div' | 'h1';\n  }>) => (\n    <TypographyBase className={className} component={component}>\n      {children}\n    </TypographyBase>\n  ),\n)<Props>(\n  ({\n    size,\n    family = 'body',\n    lineHeight = size,\n    weight = 'default',\n    color = 'grey900',\n    fontStyle = 'normal',\n\n    theme,\n  }) => ({\n    color: theme.vars.components?.variables.colors[color],\n    fontStyle,\n\n    ...merge(\n      unwrapTypographyStyles(theme, 'size', size),\n      unwrapTypographyStyles(theme, 'family', family),\n      unwrapTypographyStyles(theme, 'lineHeight', lineHeight),\n      unwrapTypographyStyles(theme, 'weight', weight),\n    ),\n  }),\n);\n\nexport const unwrapTypographyStyles = <T extends keyof TypographyVariables>(\n  { breakpoints, vars: { components } }: Theme,\n  property: T,\n  values: BreakpointAwareProp<keyof TypographyVariables[T]>,\n) => {\n  const propertyMap = {\n    size: 'fontSize',\n    family: 'fontFamily',\n    lineHeight: 'lineHeight',\n    weight: 'fontWeight',\n  } as const;\n\n  return {\n    [propertyMap[property]]: Array.isArray(values)\n      ? components?.variables.typography.mobile[property][values[0]]\n      : components?.variables.typography.mobile[property][values],\n\n    [breakpoints.up('desktop')]: {\n      [propertyMap[property]]: Array.isArray(values)\n        ? components?.variables.typography.desktop[property][values[1]]\n        : components?.variables.typography.desktop[property][values],\n    },\n  };\n};\n","import { Theme } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport {\n  Button as ButtonBase,\n  ButtonProps,\n  buttonClasses,\n} from '@mui/material';\nimport type { NormalCssProperties } from '@mui/material/styles/createMixins';\nimport merge from 'lodash/merge';\n\nimport { Loader } from '../Loader';\nimport {\n  ButtonCustomizationTags,\n  usePlatformSettings,\n} from '../PlatformSettings';\nimport { unwrapTypographyStyles } from '../Typography';\nimport { customizeStyles } from '../customizeStyles';\nimport { useResponsive } from '../hooks';\n\nexport type ButtonSize = 'large' | 'medium' | 'small';\nexport type ButtonVariant = 'primary' | 'secondary' | 'invisible';\n\nexport const BUTTON_BORDER_WIDTH = 2;\n\nexport type TigerButtonProps = Omit<\n  ButtonProps,\n  'size' | 'variant' | 'color' | 'translate'\n> & {\n  loading?: boolean;\n  size?: ButtonSize;\n  variant: ButtonVariant;\n\n  nowrap?: true;\n};\n\nexport const Button = ({\n  customizationTags,\n  ...props\n}: TigerButtonProps & { customizationTags?: ButtonCustomizationTags[] }) => {\n  const { isMobile } = useResponsive();\n  const { customization } = usePlatformSettings();\n\n  const buttonProps = customization?.button?.props?.find((item) =>\n    item.tags.every((key) => customizationTags?.includes(key)),\n  );\n\n  return (\n    <StyledButton\n      {...props}\n      {...buttonProps?.mobile}\n      {...(!isMobile ? buttonProps?.desktop : {})}\n    />\n  );\n};\n\nconst StyledButton = styled(\n  ({\n    loading,\n    children,\n    size,\n    variant,\n    onClick,\n    disabled,\n    ...props\n  }: TigerButtonProps) => (\n    <ButtonBase\n      {...props}\n      translate=\"no\"\n      disableRipple\n      disableElevation\n      onClick={loading || disabled ? undefined : onClick}\n      disabled={disabled}\n    >\n      {loading && <Loader size={24} color={'currentColor' as 'primary'} />}\n      {typeof children === 'string' ? (\n        <span>\n          {\n            // When the children is a plain string, and user wants to translate it, we should wrap it with a span\n            children\n          }\n        </span>\n      ) : (\n        children\n      )}\n    </ButtonBase>\n  ),\n)(\n  ({\n    variant,\n    size = 'medium',\n    theme: {\n      vars: { components },\n    },\n    theme,\n    nowrap = false,\n  }) => ({\n    textTransform: 'none',\n    whiteSpace: nowrap ? 'nowrap' : 'break-spaces',\n    boxShadow: 'none',\n\n    borderRadius: components?.variables.radius?.button,\n\n    [`&.${buttonClasses.root}`]: {\n      ...(size === 'small' && {\n        padding:\n          variant === 'secondary'\n            ? // Since height is not defined, we need to subtract border width from vertical padding.\n              `calc(8px - ${BUTTON_BORDER_WIDTH}px) 16px`\n            : '8px 16px',\n        ...customizeStyles(theme, (c) => c?.button?.small?.default),\n      }),\n\n      ...(size === 'medium' && {\n        padding:\n          variant === 'secondary'\n            ? // Since height is not defined, we need to subtract border width from vertical padding.\n              // Here we also calculate button label padding + button padding with\n              // ${components?.variables.spacings.xs} + ${components?.variables.spacings.sm}\n              `calc(${components?.variables.spacings.xs} + ${components?.variables.spacings.sm} - ${BUTTON_BORDER_WIDTH}px) ${components?.variables.spacings.md}`\n            : `calc(${components?.variables.spacings.xs} + ${components?.variables.spacings.sm}) ${components?.variables.spacings.md}`,\n        ...customizeStyles(theme, (c) => c?.button?.medium?.default),\n      }),\n\n      ...(size === 'large' &&\n        components && {\n          padding:\n            variant === 'secondary'\n              ? // Since height is not defined, we need to subtract border width from vertical padding\n                `calc(${components?.variables.spacings.md} - ${BUTTON_BORDER_WIDTH}px) ${components?.variables.spacings.lg}`\n              : `${components?.variables.spacings.md} ${components?.variables.spacings.lg}`,\n          ...customizeStyles(theme, (c) => c?.button?.large?.default),\n        }),\n    },\n\n    ...merge(\n      unwrapTypographyStyles(\n        theme,\n        'size',\n        size === 'large' ? 'md' : size === 'small' ? 'xs' : 'sm',\n      ),\n      unwrapTypographyStyles(theme, 'family', 'body'),\n      unwrapTypographyStyles(\n        theme,\n        'lineHeight',\n        size === 'large' ? 'md' : size === 'small' ? 'xs' : 'sm',\n      ),\n      unwrapTypographyStyles(theme, 'weight', 'strong'),\n    ),\n\n    ...mixin('primary', theme, variant, {\n      base: {\n        backgroundColor: components?.variables.colors.primaryDefault,\n        color: components?.variables.colors.white,\n      },\n      hover: { backgroundColor: components?.variables.colors.primaryAccent },\n      focus: {\n        backgroundColor: components?.variables.colors.primaryAccent,\n      },\n      disabled: {\n        backgroundColor: components?.variables.colors.grey300,\n        color: components?.variables.colors.grey700,\n      },\n    }),\n\n    ...mixin('secondary', theme, variant, {\n      base: {\n        borderWidth: BUTTON_BORDER_WIDTH,\n        borderStyle: 'solid',\n        borderColor: components?.variables.colors.primaryDefault,\n\n        backgroundColor: components?.variables.colors.white,\n\n        color: components?.variables.colors.primaryDefault,\n      },\n      hover: {\n        backgroundColor: components?.variables.colors.grey100,\n      },\n      focus: {\n        backgroundColor: components?.variables.colors.grey100,\n      },\n      disabled: {\n        borderColor: components?.variables.colors.grey300,\n        backgroundColor: components?.variables.colors.grey300,\n        color: components?.variables.colors.grey700,\n      },\n    }),\n\n    ...mixin('invisible', theme, variant, {\n      base: {\n        backgroundColor: 'transparent',\n        color: components?.variables.colors.primaryDefault,\n      },\n      hover: {\n        backgroundColor: components?.variables.colors.grey100,\n      },\n      focus: {\n        backgroundColor: components?.variables.colors.grey100,\n      },\n      disabled: {\n        color: components?.variables.colors.grey700,\n      },\n    }),\n  }),\n);\n\nconst mixin = (\n  mixinVariant: ButtonVariant,\n  theme: Theme,\n  variant: ButtonVariant,\n  css: Record<'base' | 'hover' | 'focus' | 'disabled', NormalCssProperties>,\n) =>\n  variant === mixinVariant\n    ? {\n        ...css['base'],\n        ...customizeStyles(theme, (c) => c?.button?.[variant]?.default),\n\n        '&:hover, &[data-focus=\"true\"]': {\n          ...css['hover'],\n          ...customizeStyles(theme, (c) => c?.button?.[variant]?.hovered),\n        },\n\n        '&:focus-visible, &:focus, &[data-focus=\"true\"]': {\n          ...css['focus'],\n          ...customizeStyles(theme, (c) => c?.button?.[variant]?.focused),\n        },\n\n        [`&.${buttonClasses.disabled}`]: {\n          pointerEvents: 'auto',\n          cursor: 'not-allowed',\n\n          ...css['disabled'],\n          ...customizeStyles(theme, (c) => c?.button?.[variant]?.disabled),\n        },\n      }\n    : null;\n","import { useEffect, useState } from 'react';\n\nimport { Loader } from '../Loader';\nimport { ButtonCustomizationTags } from '../PlatformSettings';\n\nimport { Button } from './Button';\n\ninterface TimedButtonProps {\n  timeout: number;\n  loading: boolean;\n  text: string;\n  testId: string;\n  disabled?: boolean;\n  onClick?: () => void;\n  className?: string;\n  customizationTags?: ButtonCustomizationTags[];\n}\n\nexport const TimedButton = ({\n  timeout,\n  loading,\n  text,\n  testId,\n  onClick,\n  disabled,\n  className,\n  customizationTags,\n}: TimedButtonProps) => {\n  // TODO: standard TimedButton causes viewport bugs on small screens\n  const [time, setTime] = useState(0);\n\n  useEffect(() => {\n    setTime(timeout);\n  }, [timeout]);\n\n  useEffect(() => {\n    if (time > 0) {\n      const countdown = setTimeout(() => {\n        if (time > 0) {\n          setTime(time - 1);\n        }\n      }, 1000);\n\n      return () => clearTimeout(countdown);\n    }\n\n    return undefined;\n  }, [time]);\n\n  return (\n    <Button\n      fullWidth\n      variant=\"primary\"\n      size=\"large\"\n      type=\"submit\"\n      disabled={disabled || time > 0}\n      data-test-id={testId}\n      onClick={onClick}\n      className={className}\n      customizationTags={customizationTags}\n    >\n      {loading && <Loader size={24} color=\"gray.600\" />}\n      {text}\n      {time > 0 ? ` (00:${('00' + time).slice(-2)})` : null}\n    </Button>\n  );\n};\n","import styled from '@emotion/styled';\n\nimport { Flex } from '../../../Flex';\nimport { Typography } from '../../../Typography';\nimport { customizeStyles } from '../../../customizeStyles';\n\nexport const ActionBoxContainer = styled(Flex)(({ theme: { vars } }) => ({\n  width: '100%',\n  flexDirection: 'column',\n  justifyContent: 'space-between',\n  alignItems: 'flex-start',\n  rowGap: vars.components?.variables.spacings.xl,\n}));\n\nexport const DescriptionContainer = styled(Flex)(({ theme: { vars } }) => ({\n  flexDirection: 'column',\n  alignItems: 'flex-start',\n  rowGap: vars.components?.variables.spacings.xs,\n}));\n\nexport const Title = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(\n    theme,\n    (customizations) => customizations?.backToOffers?.actionBox?.title,\n  ),\n}));\n\nexport const Subtitle = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(\n    theme,\n    (customizations) => customizations?.backToOffers?.actionBox?.subtitle,\n  ),\n}));\n","import { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { Button } from '../../../Button';\n\nimport {\n  ActionBoxContainer,\n  DescriptionContainer,\n  Subtitle,\n  Title,\n} from './ActionBox.styled';\n\ntype ActionBoxProps = {\n  to: string;\n};\n\nexport const ActionBox = ({ to }: ActionBoxProps) => {\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'components.backToOffers',\n  });\n  const navigate = useNavigate() as (to: string) => void;\n\n  const navigateToOffers = () => {\n    navigate(to);\n  };\n\n  return (\n    <ActionBoxContainer>\n      <DescriptionContainer>\n        <Title size=\"md\" weight=\"strong\">\n          {t('ready', { defaultValue: 'Ready?' })}\n        </Title>\n        <Subtitle size=\"sm\">\n          {t('title', { defaultValue: 'Get to your offers now' })}\n        </Subtitle>\n      </DescriptionContainer>\n      <Button variant=\"primary\" onClick={navigateToOffers} size=\"large\">\n        {t('cta', { defaultValue: 'Back to offers' })}\n      </Button>\n    </ActionBoxContainer>\n  );\n};\n","import styled from '@emotion/styled';\n\nimport { Flex } from '../../../../Flex';\n\nexport const Wrapper = styled(Flex)(({ theme: { vars, breakpoints } }) => ({\n  flexDirection: 'column',\n  width: '100%',\n  height: 180,\n  alignItems: 'flex-start',\n  borderRadius: 12,\n  border: '7.5px solid #3D3D3D',\n  background: vars.components?.variables.colors.white,\n  boxShadow:\n    '0px 0px 0px 0.75px #7A7A7A, 0px 0px 0px 1.5px #000, 0px 3px 12px 0px rgba(0, 0, 0, 0.64), 0px 3px 27px 0px rgba(0, 0, 0, 0.24)',\n  overflow: 'hidden',\n\n  [breakpoints.down('desktop')]: {\n    width: 283,\n    height: 262,\n  },\n}));\n\nexport const Container = styled(Flex)(({ theme: { vars } }) => ({\n  width: '100%',\n  height: '100%',\n  paddingBlockStart: '12px',\n  paddingInline: 0,\n  flexDirection: 'column',\n  justifyContent: 'flex-start',\n  alignItems: 'flex-start',\n  gap: '10px',\n  borderRadius: 6,\n  border: `1px solid ${vars.components?.variables.colors.grey300}`,\n  background: vars.components?.variables.colors.white,\n}));\n\nexport const InnerContainer = styled(Flex)`\n 