\n    textOverflow: 'ellipsis',\n\n    [breakpoints.down('desktop')]: {\n      padding: 0,\n    },\n\n    ...customizeStyles({ vars, breakpoints }, (customizations) => ({\n      ...(disabled\n        ? customizations?.backToOffers?.visual?.placeholderButton?.disabled\n        : customizations?.backToOffers?.visual?.placeholderButton?.default),\n    })),\n  }),\n);\n\nexport const PlaceholderButtonLabel = styled('p')<{ disabled?: boolean }>(\n  ({ theme: { vars, breakpoints }, disabled }) => ({\n    margin: 0,\n    color: disabled\n      ? vars.components?.variables.colors.grey700\n      : vars.components?.variables.colors.primaryDefault,\n    fontSize: '11.25px',\n    lineHeight: '17.25px',\n    fontWeight: vars.components?.variables.typography.mobile.weight.strong,\n\n    ...customizeStyles({ vars, breakpoints }, (customizations) => ({\n      ...(disabled\n        ? customizations?.backToOffers?.visual?.placeholderButtonLabel?.disabled\n        : customizations?.backToOffers?.visual?.placeholderButtonLabel\n            ?.default),\n    })),\n  }),\n);\n\nexport const CursorIcon = styled(Icons.PointingCursorIcon)`\n  position: absolute;\n  bottom: 0;\n  right: 0;\n  width: 22;\n  height: 23;\n  transform: translate3d(0, 50%, 0);\n`;\n\nexport const PlaceholderBottom = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    flexDirection: 'column',\n    alignItems: 'flex-start',\n    gap: '6px',\n    alignSelf: 'stretch',\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (customizations) =>\n        customizations?.backToOffers?.visual?.placeholderBottom,\n    ),\n  }),\n);\n\nexport const PlaceholderBulletPoint = styled(Flex)`\n  align-items: flex-start;\n  justify-content: flex-start;\n  gap: 6px;\n  align-self: stretch;\n`;\n\nexport const PlaceholderBox = styled('div')<{\n  width?: number;\n  grow?: boolean;\n  height: number;\n}>(({ theme: { vars, breakpoints }, grow, width, height }) => ({\n  width,\n  height,\n  flexGrow: grow ? 1 : 0,\n  borderRadius: vars.components?.variables.radius.md,\n  background: vars.components?.variables.colors.grey300,\n\n  ...customizeStyles(\n    { vars, breakpoints },\n    (customizations) => customizations?.backToOffers?.visual?.placeholderBox,\n  ),\n}));\n","import { useTranslation } from 'react-i18next';\n\nimport {\n  CursorIcon,\n  OfferCard,\n  PlaceholderBottom,\n  PlaceholderBox,\n  PlaceholderTop,\n  PlaceholderButton,\n  PlaceholderButtonLabel,\n  PlaceholderBulletPoint,\n  PlaceholderButtonContainer,\n} from './OfferCardPlaceholder.styled';\n\nexport const OfferCardPlaceholder = ({\n  disabled = false,\n}: {\n  disabled?: boolean;\n}) => {\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'educationalPopup.selectOffer',\n  });\n  return (\n    <OfferCard>\n      <PlaceholderTop>\n        <PlaceholderBox width={24} height={12} />\n        <PlaceholderBox width={72} height={18} />\n      </PlaceholderTop>\n      <PlaceholderButtonContainer>\n        <PlaceholderButton disabled={disabled}>\n          <PlaceholderButtonLabel disabled={disabled}>\n            {t('explorePlan', 'Explore plan')}\n          </PlaceholderButtonLabel>\n          {disabled ? null : <CursorIcon width={22} height={22} />}\n        </PlaceholderButton>\n      </PlaceholderButtonContainer>\n      <PlaceholderBottom>\n        <PlaceholderBulletPoint>\n          <PlaceholderBox width={12} height={12} />\n          <PlaceholderBox width={62.3} height={12} />\n        </PlaceholderBulletPoint>\n        <PlaceholderBulletPoint>\n          <PlaceholderBox width={12} height={12} />\n          <PlaceholderBox width={62.3} height={12} />\n        </PlaceholderBulletPoint>\n      </PlaceholderBottom>\n    </OfferCard>\n  );\n};\n","import { Container, InnerContainer, Wrapper } from './NoCodeVisual.styled';\nimport { OfferCardPlaceholder } from './OfferCardPlaceholder';\n\nexport const NoCodeVisual = () => {\n  return (\n    <Wrapper>\n      <Container>\n        <InnerContainer>\n         