er,\n    ),\n  }),\n);\n\ntype BackToOffersWidgetProps = {\n  to: string;\n};\n\nconst DefaultBackToOffersWidget = ({ to }: BackToOffersWidgetProps) => {\n  return (\n    <BackToOffersWidgetContainer>\n      <ActionBox to={to} />\n      <WidgetVisual />\n    </BackToOffersWidgetContainer>\n  );\n};\n\nexport const BackToOffersWidget = ({ to }: BackToOffersWidgetProps) => {\n  const { hasCurrentCredit } = useOfferStatus();\n\n  if (hasCurrentCredit) {\n    return null;\n  }\n\n  return (\n    <CustomisationSlot\n      slot={'backToOffers.widget' as never}\n      props={{ to } as never}\n      fallback={<DefaultBackToOffersWidget to={to} />}\n    />\n  );\n};\n","import styled from '@emotion/styled';\nimport { CircularProgress } from '@mui/material';\nimport { useTranslation } from 'react-i18next';\n\nexport const LoadingBank = () => {\n  const { t } = useTranslation('turnkey');\n  return (\n    <Wrapper>\n      <CircularProgress />\n      <div>{t('connectBank.loadingBank')}</div>\n    </Wrapper>\n  );\n};\n\nconst Wrapper = styled.div({\n  height: '100%',\n  width: '100%',\n  position: 'relative',\n  display: 'flex',\n  alignItems: 'center',\n  justifyContent: 'center',\n  flexDirection: 'column',\n  gap: '16px',\n  padding: '80px 0',\n});\n","import styled from '@emotion/styled';\n\nimport { Typography } from '../Typography';\nimport { customized, customizeStyles } from '../customizeStyles';\n\nexport const Container = styled('div')(({ theme: { breakpoints, vars } }) => ({\n  borderRadius: vars.components?.variables.radius.sm,\n  background: vars.components?.variables.colors?.grey100,\n  padding: vars.components?.variables.spacings.sm,\n  display: 'flex',\n  width: '100%',\n  alignItems: 'flex-start',\n  gap: vars.components?.variables.spacings.sm,\n\n  '& svg': {\n    minWidth: 20,\n    width: 20,\n    height: 20,\n  },\n\n  ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.bank?.faqBanner),\n}));\n\nexport const Label = customized(\n  Typography,\n  (customizations) => customizations?.plus?.bank?.faqLabel,\n);\n","import { useTheme } from '@emotion/react';\nimport { FC, ReactElement } from 'react';\nimport { Trans } from 'react-i18next';\n\nimport { ColorVariables } from '../';\nimport { Icons } from '../Icons';\n\nimport { Container, Label } from './Callout.styled';\n\ntype CalloutProps = {\n  iconColor?: keyof ColorVariables;\n  labelKey: string;\n  labelComponents?: Record<string, ReactElement>;\n};\nexport const Callout: FC<CalloutProps> = ({\n  iconColor = 'grey900',\n  labelKey,\n  labelComponents,\n}) => {\n  const { vars } = useTheme();\n  return (\n    <Container>\n      <Icons.InfoIcon color={vars.components?.variables.colors?.[iconColor]} />\n      <Label size=\"xs\">\n        <Trans i18nKey={labelKey} components={labelComponents} />\n      </Label>\n    </Container>\n  );\n};\n","import { useGetOffers } from '@finmid/tiger-webapp/queries';\nimport { FC } from 'react';\n\nimport { Callout } from '../Callout';\nimport { usePlatformSettings } from '../PlatformSettings';\nimport { useTokenContext } from '../TokenContext';\n\nexport const BusinessAgeCallout: FC = () => {\n  const { token, ignoreAction } = useTokenContext();\n  const { data } = useGetOffers({ token, ignoreAction });\n  const { experiments } = usePlatformSettings();\n\n  const isBusinessAgeCalloutExperimentEnabled =\n    data?.country && experiments?.businessAgeCallout?.includes(data?.country);\n  if (isBusinessAgeCalloutExperimentEnabled) {\n    return <Callout labelKey=\"plus.aisp.businessAge\" iconColor=\"warning\" />;\n  }\n\n  return null;\n};\n","import styled from '@emotion/styled';\nimport { CSSProperties } from 'react';\n\n/**\n * Section title, styled as \"subtitle1\" MUI Typography component\n */\nexport const SectionTitle = styled('p' /* subtitle1 */)(\n  ({\n    theme: {\n      breakpoints,\n      vars: { palette },\n      vars,\n    },\n  }) => ({\n    fontFamily: 'var(--mui-components-fonts-neutral)',\n    color: palette.primary[700],\n    textTransform: 'uppercase',\n    lineHeight: 1.2,\n    fontSize: 14,\n    fontWeight: 400,\n    letterSpacing: '3px',\n    margin: 0,\n\n    ...(vars.components?.typography?.subtitle1 as CSSProperties),\n  }),\n);\n","import styled from '@emotion/styled';\n\nimport { SpacingVariables } from '../PlatformSettings';\nimport { SectionTitle as SectionTitleBase } from '../SectionTitle';\nimport { customizeStyles } from '../customizeStyles';\n\nexport const Card = styled.div(({ theme }) => ({\n  display: 'flex',\n  flex: 1,\n  flexDirection: 'column',\n  width: '100%',\n  overflow: 'auto',\n\n  background: theme.vars.components?.variables.colors.white,\n  border: `1px solid ${theme.vars.components?.variables.colors.grey300}`,\n  borderRadius: theme.vars.components?.variables.radius.md,\n\n  padding: theme.vars.components?.variables.spacings.md,\n\n  ...customizeStyles(theme, (c) => c?.card?.container),\n}));\n\nexport const CardHeader = styled(SectionTitleBase)(({ theme }) => ({\n  padding: theme.vars.components?.variables.spacings.md,\n\n  ...customizeStyles(theme, (c) => c?.card?.header),\n}));\n\nexport const CardFooter = styled('div')(({ theme }) => ({\n  padding: '16px',\n\n  ...customizeStyles(theme, (c) => c?.card?.footer),\n}));\n\nexport const CardBleed = styled('div')(({ theme }) => ({\n  width: `calc(100% + (2 * ${theme.vars.components?.variables.spacings.md}))`,\n  marginLeft: `calc(-1 * ${theme.vars.components?.variables.spacings.md})`,\n  marginRight: `calc(-1 * ${theme.vars.components?.variables.spacings.md})`,\n\n  ...customizeStyles(theme, (c) => c?.card?.bleed),\n}));\n\nexport const CardSeparator = styled('div', {\n  shouldForwardProp: (p) => p !== 'gap',\n})<{\n  gap: '0' | keyof SpacingVariables;\n}>(({ theme, gap }) => ({\n  width: '100%',\n  borderBottom: `1px solid ${theme.vars.components?.variables.colors.grey300}`,\n\n  marginTop:\n    gap === '0' ? undefined : theme.vars.components?.variables.spacings[gap],\n  marginBottom:\n    gap === '0' ? undefined : theme.vars.components?.variables.spacings[gap],\n\n  ...customizeStyles(theme, (c) => c?.card?.separator),\n}));\n","import {\n  Card as CardBase,\n  CardBleed,\n  CardFooter,\n  CardHeader,\n  CardSeparator,\n} from './Card';\n\ntype Card = typeof CardBase & {\n  Card: typeof CardBase;\n  Header: typeof CardHeader;\n  Footer: typeof CardFooter;\n  Bleed: typeof CardBleed;\n  Separator: typeof CardSeparator;\n};\n\nconst Card: Card = CardBase as Card;\n\nCard.Card = CardBase;\nCard.Header = CardHeader;\nCard.Footer = CardFooter;\nCard.Bleed = CardBleed;\nCard.Separator = CardSeparator;\n\nexport { Card };\n","import styled from '@emotion/styled';\nimport { Modal } from '@mui/material';\nimport { PropsWithChildren } from 'react';\n\nconst DesktopPopup = styled('div')(({ theme }) => ({\n  position: 'fixed',\n  zIndex: 2000,\n\n  display: 'flex',\n  justifyContent: 'space-between',\n  alignItems: 'center',\n  flexDirection: 'row',\n\n  left: theme.vars.components?.variables.spacings.xxl,\n  right: theme.vars.components?.variables.spacings.xxl,\n  bottom: theme.vars.components?.variables.spacings.xxl,\n\n  padding: theme.vars.components?.variables.spacings.lg,\n  gap: theme.vars.components?.variables.spacings.xl,\n  backgroundColor: theme.vars.components?.variables.colors.white,\n  borderRadius: theme.vars.components?.variables.radius.lg,\n}));\n\nexport const DesktopModal = styled(\n  ({ children, ...props }: PropsWithChildren) => (\n    <Modal\n      open\n      {...props}\n      slotProps={{\n        root: {\n          style: {\n            outline: 'none',\n          },\n        },\n      }}\n    >\n      <DesktopPopup\n        data-test-id={\n          'data-test-id' in props ? props['data-test-id'] : undefined\n        }\n      >\n        {children}\n      </DesktopPopup>\n    </Modal>\n  ),\n)();\n\nexport const Popup = styled('div')(({ theme }) => ({\n  position: 'fixed',\n  bottom: 0,\n  display: 'flex',\n  justifyContent: 'space-between',\n  alignItems: 'center',\n  zIndex: 2000,\n  flexDirection: 'column',\n\n  [theme.breakpoints.up('desktop')]: {\n    flexDirection: 'row',\n  },\n\n  margin: theme.vars.components?.variables.spacings.md,\n  padding: theme.vars.components?.variables.spacings.lg,\n  gap: theme.vars.components?.variables.spacings.md,\n\n  borderRadius: theme.vars.components?.variables.radius.lg,\n  borderWidth: 1,\n  borderStyle: 'solid',\n  borderColor: theme.vars.components?.variables.colors.grey300,\n\n  backgroundColor: theme.vars.components?.variables.colors.white,\n  boxShadow:\n    '0px 0px 4px 0px rgba(0, 0, 0, 0.06), 0px 4px 24px 0px rgba(0, 0, 0, 0.24)',\n}));\n\nexport const PdfLink = styled('a')(({ theme }) => ({\n  color: theme.vars.components?.variables.colors.grey900,\n  whiteSpace: 'nowrap',\n}));\n","import { ENVIRONMENT } from '@finmid/environment';\nimport {\n  ConsentState,\n  useGetConsent,\n  usePutConsent,\n} from '@finmid/tiger-webapp/queries';\nimport {\n  FunctionComponent,\n  PropsWithChildren,\n  createContext,\n  useCallback,\n  useContext,\n  useEffect,\n  useState,\n} from 'react';\nimport { useLocalStorage } from 'react-use';\n\nimport { usePlatformSettings } from '../PlatformSettings';\nimport { useTokenContext } from '../TokenContext';\n\nexport interface ConsentContextValue {\n  consentState: ConsentState | undefined;\n  changeConsent: (state: ConsentState) => void;\n  isLoading: boolean;\n}\n\n// eslint-disable-next-line @typescript-eslint/no-non-null-assertion\nexport const ConsentContext = createContext<ConsentContextValue>(null!);\n\nexport const ConsentContextProvider: FunctionComponent<PropsWithChildren> = ({\n  children,\n}) => {\n  const { experiments } = usePlatformSettings();\n\n  const [consentProvidedOverride] = useLocalStorage<ConsentState | undefined>(\n    'consentProvidedOverride',\n  );\n\n  const [consentState, setConsentState] = useState<ConsentState>();\n\n  const { token } = useTokenContext();\n  const { mutateAsync: updateConsent, isPending: loadingPut } = usePutConsent();\n  const { data: consent, isLoading: loadingGet } = useGetConsent({ token });\n\n  const onConsentChange = useCallback(\n    async (state: ConsentState) => {\n      if (state === 'MISSING') {\n        setConsentState('MISSING');\n        return;\n      }\n\n      await updateConsent({\n        action: state === 'ACTIVE' ? 'GRANT' : 'REVOKE',\n        token,\n      });\n      setConsentState(state);\n    },\n    [token, updateConsent],\n  );\n\n  useEffect(() => {\n    if (consent?.state == null) return;\n\n    if (experiments?.autoAcceptConsent && consent.state === 'MISSING') {\n      onConsentChange('ACTIVE');\n    } else {\n      setConsentState(consent.state);\n    }\n  }, [consent?.state, experiments?.autoAcceptConsent, onConsentChange]);\n\n  return (\n    <ConsentContext.Provider\n      value={{\n        consentState:\n          ENVIRONMENT !== 'live' && consentProvidedOverride\n            ? consentProvidedOverride\n            : consentState,\n        changeConsent: onConsentChange,\n        isLoading: loadingGet || loadingPut,\n      }}\n    >\n      {children}\n    </ConsentContext.Provider>\n  );\n};\n\nexport const useConsentContext = () => {\n  const context = useContext(ConsentContext);\n\n  if (context === null) {\n    console.warn('useConsentContext called outside of ConsentContextProvider');\n    return {\n      consentState: undefined,\n      changeConsent: () => {},\n      isLoading: false,\n    };\n  }\n\n  return context;\n};\n","import { useTheme } from '@emotion/react';\nimport { useMediaQuery } from '@mui/material';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { Button } from '../Button/Button';\nimport { Flex } from '../Flex';\nimport { usePlatformSettings } from '../PlatformSettings';\nimport { Typography } from '../Typography';\nimport { getLngFromLocale } from '../utils';\n\nimport { DesktopModal, PdfLink, Popup } from './ConsentBanner.styled';\nimport { useConsentContext } from './ConsentContext';\n\nexport const ConsentBanner = () => {\n  const {\n    t,\n    i18n: { language },\n  } = useTranslation('turnkey', {\n    keyPrefix: 'consentBanner',\n  });\n  const { consentState, changeConsent, isLoading } = useConsentContext();\n  const { resourcesPath } = usePlatformSettings();\n  const { experiments } = usePlatformSettings();\n\n  const { breakpoints } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('tablet'));\n\n  const open = consentState === 'MISSING';\n\n  if (!open) return null;\n\n  const Wrapper =\n    isMobile || experiments?.desktopConsentPopup ? Popup : DesktopModal;\n\n  return (\n    <Wrapper\n      data-test-id=\"consent-banner\"\n      style={{\n        outline: 'none',\n      }}\n    >\n      <Typography size=\"md\">\n        <Trans\n          t={t}\n          i18nKey=\"text\"\n          components={{\n            ref: (\n              <PdfLink\n                href={`${resourcesPath}CookiePolicy.${\n                  getLngFromLocale(language) || 'en'\n                }.pdf`}\n                target=\"_blank\"\n              />\n            ),\n          }}\n        />\n      </Typography>\n      <Flex gap=\"sm\" flexDirection=\"row\" width={['100%', 'unset']}>\n        <Button\n          variant=\"secondary\" // Legal team asked to make these buttons the same color -- see https://app.campsite.com/finmid/posts/5hmeqqdq8cof#comment-dolviomgxboi\n          fullWidth={isMobile}\n          loading={isLoading}\n          onClick={() => changeConsent('REJECTED')}\n          data-test-id=\"reject-button\"\n          nowrap\n        >\n          {t('declineButton')}\n        </Button>\n        <Button\n          variant=\"secondary\" // Legal team asked to make these buttons the same color -- see https://app.campsite.com/finmid/posts/5hmeqqdq8cof#comment-dolviomgxboi\n          fullWidth={isMobile}\n          loading={isLoading}\n          onClick={() => changeConsent('ACTIVE')}\n          data-test-id=\"accept-button\"\n          nowrap\n        >\n          {t('acceptButton')}\n        </Button>\n      </Flex>\n    </Wrapper>\n  );\n};\n","import styled from '@emotion/styled';\nimport { IconButton as MuiIconButton } from '@mui/material';\nimport { useEffect, useState } from 'react';\nimport { useCopyToClipboard } from 'react-use';\n\nimport { Icons } from '../Icons';\nimport { usePlatformSupportEmail } from '../hooks';\n\nconst IconButton = styled(MuiIconButton)(({ theme: { vars } }) => ({\n  borderRadius: vars.components?.variables.radius.md,\n  color: vars.components?.variables.colors.primaryDefault,\n}));\n\nexport const CopyEmailButton = () => {\n  const supportEmail = usePlatformSupportEmail();\n  const [, copyToClipboard] = useCopyToClipboard();\n\n  const [showCopied, setShowCopied] = useState(false);\n\n  useEffect(() => {\n    if (showCopied) {\n      const timeout = setTimeout(() => {\n        setShowCopied(false);\n      }, 3000);\n      return () => clearTimeout(timeout);\n    }\n  }, [showCopied]);\n\n  const copySupportEmail = () => {\n    copyToClipboard(supportEmail);\n    setShowCopied(true);\n  };\n\n  const iconSize = { width: 26, height: 26 };\n\n  const icon = showCopied ? (\n    <Icons.CheckIcon {...iconSize} />\n  ) : (\n    <Icons.FileCopyIcon {...iconSize} />\n  );\n\n  return <IconButton onClick={copySupportEmail}>{icon}</IconButton>;\n};\n","import styled from '@emotion/styled';\nimport { PropsWithChildren } from 'react';\nimport { useNavigate } from 'react-router-dom';\n\nimport { Typography } from '../Typography';\nimport { customizeStyles } from '../customizeStyles';\nimport { NavigationRoutes } from '../routes';\n\nexport const Link = styled.a(({ theme }) => ({\n  textDecoration: 'underline',\n  color: theme.vars.components?.variables.colors.grey900,\n\n  ...customizeStyles(theme, (c) => c?.link),\n}));\n\nconst LinkButton = styled.button(({ theme: { vars } }) => ({\n  border: 0,\n  outline: 0,\n  appearance: 'none',\n  background: 'transparent',\n  cursor: 'pointer',\n  padding: `calc(${vars.components?.variables.spacings.xs} + ${vars.components?.variables.spacings.sm}) 0`,\n\n  '&:hover .MuiTypography-root': {\n    color: vars.components?.variables.colors?.primaryAccent,\n  },\n}));\n\nexport const LinkButtonLabel = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(theme, (c) => c?.linkButton?.label),\n}));\n\ntype StandaloneLinkProps = (\n  | { to: NavigationRoutes; onClick?: never }\n  | { onClick: () => void; to?: never }\n) & {\n  testId?: string;\n};\nexport const StandaloneLink = styled(\n  ({\n    children,\n    onClick,\n    to,\n    testId,\n  }: PropsWithChildren<StandaloneLinkProps>) => {\n    const navigate = useNavigate();\n\n    const handleClick = () => {\n      if (to) {\n        navigate(to);\n      } else if (onClick) {\n        onClick();\n      }\n    };\n\n    return (\n      <LinkButton onClick={handleClick} data-test-id={testId}>\n        <LinkButtonLabel size=\"sm\" weight=\"strong\" color=\"primaryDefault\">\n          {children}\n        </LinkButtonLabel>\n      </LinkButton>\n    );\n  },\n)();\n","import styled from '@emotion/styled';\nimport { useEffect, useState } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useCopyToClipboard } from 'react-use';\n\nimport { Link } from '../Link';\nimport { usePlatformSupportEmail } from '../hooks';\n\nconst StyledLink = styled(Link)(({ theme: { vars } }) => ({\n  color: vars.components?.variables.colors?.primaryDefault,\n  cursor: 'pointer',\n}));\n\nexport const CopyEmailLink = () => {\n  const { t } = useTranslation('components', {\n    keyPrefix: 'support.copyEmailLink',\n  });\n\n  const supportEmail = usePlatformSupportEmail();\n  const [, copyToClipboard] = useCopyToClipboard();\n\n  const [showCopied, setShowCopied] = useState(false);\n\n  useEffect(() => {\n    if (showCopied) {\n      const timeout = setTimeout(() => {\n        setShowCopied(false);\n      }, 3000);\n      return () => clearTimeout(timeout);\n    }\n  }, [showCopied]);\n\n  const copySupportEmail = () => {\n    copyToClipboard(supportEmail);\n    setShowCopied(true);\n  };\n\n  const icon = showCopied\n    ? t('copied', 'Copied email')\n    : t('copy', 'Copy email');\n\n  return <StyledLink onClick={copySupportEmail}>{icon}</StyledLink>;\n};\n","import styled from '@emotion/styled';\n\nimport { Flex } from '../Flex';\nimport { Typography } from '../Typography';\n\nexport const Label = styled(Typography)`\n  text-align: left;\n`;\n\nexport const StyledParagraph = styled(Typography)(({ theme }) => ({\n  color: theme.vars.components?.variables.colors.grey900,\n  textDecoration: 'underline',\n  display: 'inline-block',\n}));\n\nexport const Container = styled(Flex)(({ theme: { vars } }) => ({\n  width: '100%',\n  alignItems: 'center',\n  justifyContent: 'space-between',\n}));\n","import { Trans, useTranslation } from 'react-i18next';\n\nimport { CopyEmailButton } from '../CopyEmail';\nimport { CustomisationSlot } from '../PlatformSettings';\nimport { usePlatformSupportEmail } from '../hooks';\n\nimport { Container, Label, StyledParagraph } from './ContactSupport.styled';\n\ntype ContactSupportProps = {\n  size?: 'xs' | 'sm' | 'md';\n};\n\nexport const ContactSupport = ({ size = 'sm' }: ContactSupportProps) => {\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'twoFactorModal.verifyPhone',\n  });\n  const supportEmail = usePlatformSupportEmail();\n\n  return (\n    <Container>\n      <Label size={size}>\n        <Trans\n          t={t}\n          i18nKey=\"contactSupport\"\n          components={{\n            span: <StyledParagraph size={size} component=\"span\" />,\n          }}\n          values={{ email: supportEmail }}\n          defaultValue={`Contact support at ${supportEmail}`}\n        />\n      </Label>\n      <CustomisationSlot\n        slot=\"copy.email\"\n        props={{}}\n        fallback={<CopyEmailButton />}\n      />\n    </Container>\n  );\n};\n","import styled from '@emotion/styled';\nimport { Box } from '@mui/material';\n\nimport { customizeStyles } from '../customizeStyles';\n\nexport const DepositDestination = styled(Box)(({ theme }) => ({\n  width: '100%',\n\n  backgroundColor: theme.vars.components?.variables.colors.white,\n  padding: theme.vars.components?.variables.spacings.md,\n  borderRadius: theme.vars.components?.variables.radius.md,\n  border: `1px solid ${theme.vars.components?.variables.colors.grey300}`,\n\n  ...customizeStyles(theme, (c) => c?.review?.depositDestination?.root),\n}));\n","import styled from '@emotion/styled';\nimport { Typography } from '@mui/material';\n\nimport { customizeStyles } from '../customizeStyles';\n\nexport const DepositDestinationDescription = styled(Typography)(\n  ({ theme }) => ({\n    color: theme.vars.components?.variables.colors.grey900,\n    fontFamily: theme.vars.components?.variables.typography.mobile.family.body,\n    fontSize: theme.vars.components?.variables.typography.mobile.size.sm,\n    lineHeight:\n      theme.vars.components?.variables.typography.mobile.lineHeight.sm,\n    fontWeight: 400,\n    marginBottom: theme.vars.components?.variables.spacings.md,\n\n    [theme.breakpoints.up('tablet')]: {\n      color: theme.vars.components?.variables.colors.grey700,\n      fontFamily:\n        theme.vars.components?.variables.typography.desktop.family.body,\n      fontSize: theme.vars.components?.variables.typography.desktop.size.sm,\n      lineHeight:\n        theme.vars.components?.variables.typography.desktop.lineHeight.sm,\n    },\n\n    ...customizeStyles(\n      theme,\n      (c) => c?.review?.depositDestination?.description,\n    ),\n  }),\n);\n","import styled from '@emotion/styled';\nimport { Box } from '@mui/material';\n\nimport { customizeStyles } from '../customizeStyles';\n\nexport const DepositDestinationHeader = styled(Box)(({ theme }) => ({\n  marginBottom: theme.vars.components?.variables.spacings.sm,\n  color: theme.vars.components?.variables.colors.grey900,\n  fontFamily: theme.vars.components?.variables.typography.mobile.family.body,\n  fontSize: theme.vars.components?.variables.typography.mobile.size.md,\n  lineHeight: theme.vars.components?.variables.typography.mobile.lineHeight.md,\n  fontStyle: 'normal',\n  fontWeight: 700,\n\n  [theme.breakpoints.up('tablet')]: {\n    fontFamily: theme.vars.components?.variables.typography.desktop.family.body,\n    fontSize: theme.vars.components?.variables.typography.desktop.size.md,\n    lineHeight:\n      theme.vars.components?.variables.typography.desktop.lineHeight.md,\n  },\n\n  ...customizeStyles(theme, (c) => c?.review?.depositDestination?.header),\n}));\n","import styled from '@emotion/styled';\n\nimport { customizeStyles } from '../customizeStyles';\n\nexport const DepositDestinationHelpLine = styled('div')(({ theme }) => ({\n  color: theme.vars.components?.variables.colors.grey900,\n  fontFamily: theme.vars.components?.variables.typography.mobile.family.body,\n  fontSize: theme.vars.components?.variables.typography.mobile.size.sm,\n  lineHeight: theme.vars.components?.variables.typography.mobile.lineHeight.sm,\n\n  [theme.breakpoints.up('tablet')]: {\n    color: theme.vars.components?.variables.colors.grey700,\n    fontFamily: theme.vars.components?.variables.typography.desktop.family.body,\n    fontSize: theme.vars.components?.variables.typography.desktop.size.sm,\n    lineHeight:\n      theme.vars.components?.variables.typography.desktop.lineHeight.sm,\n  },\n\n  ...customizeStyles(theme, (c) => c?.review?.depositDestination?.helpLine),\n}));\n","import styled from '@emotion/styled';\nimport { FunctionComponent, PropsWithChildren } from 'react';\n\nimport { Flex } from '../Flex';\nimport { Icons } from '../Icons';\nimport { typographySize } from '../PlatformSettings';\nimport { customizeStyles } from '../customizeStyles';\n\nexport const Zone = styled('div')(({ theme: { breakpoints, vars } }) => ({\n  width: '100%',\n  padding: vars.components?.variables.spacings.md,\n  borderRadius: vars.components?.variables.radius.sm,\n  gap: vars.components?.variables.spacings.md,\n\n  background: vars.components?.variables.colors.grey100,\n\n  display: 'flex',\n  flexDirection: 'column',\n  alignItems: 'center',\n  border: `1px dashed ${vars.components?.variables.colors.grey300}`,\n  cursor: 'pointer',\n\n  '& .icon-container': {\n    padding: vars.components?.variables.spacings.md,\n    borderRadius: vars.components?.variables.radius.pill,\n    background: vars.components?.variables.colors.white,\n    border: `1px solid ${vars.components?.variables.colors.grey300}`,\n    display: 'flex',\n  },\n\n  '& svg': {\n    color: vars.components?.variables.colors.grey900,\n    height: '24px',\n  },\n\n  ...customizeStyles({ breakpoints, vars }, (c) => c?.dropzone?.zone),\n}));\n\nexport const DropzoneTitle = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    fontFamily: vars.components?.variables?.typography.desktop.family.body,\n\n    display: 'flex',\n    textAlign: 'center',\n\n    ...typographySize({ breakpoints, vars }, 'sm'),\n\n    ...customizeStyles({ breakpoints, vars }, (c) => c?.dropzone?.title),\n  }),\n);\n\nexport const DropzoneDescription = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    fontWeight: vars.components?.variables?.typography.desktop.weight.default,\n    color: vars.components?.variables?.colors.grey900,\n    textAlign: 'center',\n\n    strong: {\n      fontWeight: vars.components?.variables?.typography.desktop.weight.default,\n      textDecoration: 'underline',\n    },\n\n    ...typographySize({ breakpoints, vars }, 'xs'),\n\n    ...customizeStyles({ breakpoints, vars }, (c) => c?.dropzone?.description),\n  }),\n);\n\nconst StyledNote = styled('div')(({ theme: { breakpoints, vars } }) => ({\n  display: 'flex',\n\n  width: '100%',\n\n  fontWeight: vars.components?.variables.typography.desktop.weight.default,\n  color: vars.components?.variables.colors.grey900,\n\n  padding: vars.components?.variables.spacings.sm,\n  borderRadius: vars.components?.variables.radius.sm,\n  gap: vars.components?.variables.spacings.sm,\n\n  background: vars.components?.variables.colors.grey100,\n\n  ...typographySize({ breakpoints, vars }, 'xs'),\n\n  '& svg': {\n    color: vars.components?.variables.colors.grey900,\n    fontSize: '20px',\n    minWidth: 20,\n    width: 20,\n    height: 20,\n  },\n\n  '& ul': {\n    margin: 0,\n    paddingInlineStart: '24px',\n  },\n\n  ...customizeStyles(\n    { breakpoints, vars },\n    (c) => c?.dropzone?.goodToKnowNotice,\n  ),\n}));\n\nexport const GoodToKnowNotice: FunctionComponent<PropsWithChildren> = ({\n  children,\n}) => (\n  <StyledNote>\n    <Icons.InfoIcon />\n    <div>{children}</div>\n  </StyledNote>\n);\n\nexport const ErrorBanner = styled(StyledNote)(\n  ({ theme: { breakpoints, vars } }) => ({\n    display: 'flex',\n    width: '100%',\n\n    '& svg': {\n      color: vars.components?.variables.colors.error,\n      fontSize: '20px',\n    },\n\n    ...customizeStyles({ breakpoints, vars }, (c) => c?.dropzone?.errorBanner),\n  }),\n);\n\nexport const DocumentDropzoneCard = styled(Flex)(\n  ({ theme: { breakpoints, vars } }) => ({\n    flexDirection: 'column',\n    width: '100%',\n\n    borderStyle: 'solid',\n    borderWidth: '1px',\n    borderColor: vars.components?.variables.colors.grey300,\n    borderRadius: vars.components?.variables.radius.md,\n\n    padding: vars.components?.variables.spacings.md,\n    gap: vars.components?.variables.spacings.md,\n\n    ...customizeStyles({ breakpoints, vars }, (c) => c?.dropzone?.root),\n  }),\n);\n\nexport const HeaderSeparator = styled(Flex)(\n  ({ theme: { breakpoints, vars } }) => ({\n    width: `calc(100% + 2 * ${vars.components?.variables.spacings.md})`,\n\n    borderStyle: 'solid',\n    borderWidth: 0,\n    borderColor: vars.components?.variables.colors.grey300,\n    borderBottomWidth: 1,\n\n    marginLeft: `calc(-1 * ${vars.components?.variables.spacings.md})`,\n    marginRight: `calc(-1 * ${vars.components?.variables.spacings.md})`,\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.dropzone?.headerSeparator,\n    ),\n  }),\n);\n","import ReactDropzone from 'react-dropzone';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { Flex } from '../Flex';\nimport { Icons } from '../Icons';\n\nimport {\n  DropzoneDescription,\n  DropzoneTitle,\n  Zone,\n} from './DocumentDropzone.styled';\n\n/**\n * Props for the Dropzone component\n */\ninterface Props {\n  /**\n   * Callback fired when files are dropped\n   * @param files - Array of dropped files (limited to single file)\n   */\n  onDrop: (files: File[]) => void;\n}\n\n/**\n * Part of `DocumentDropzone` component group.\n *\n * Dropzone - Interactive file upload area with drag-and-drop support\n *\n * Features:\n * - Drag-and-drop file selection\n * - Click to browse file selection\n * - Single file upload only (multiple=false)\n * - Visual feedback with upload icon\n * - Internationalized text content\n *\n * @example\n * <Dropzone onDrop={(files) => {\n *   console.log('File selected:', files[0]);\n * }} />\n */\nexport const Dropzone = ({ onDrop }: Props) => {\n  const { t } = useTranslation('components', { keyPrefix: 'dropzone' });\n\n  return (\n    <ReactDropzone onDrop={onDrop}>\n      {({ getRootProps, getInputProps }) => (\n        <Zone {...getRootProps()}>\n          <input {...getInputProps()} multiple={false} />\n          <div className={'icon-container'}>\n            <Icons.UploadFileIcon />\n          </div>\n\n          <Flex gap={'xs'} flexDirection={'column'} alignItems={'center'}>\n            <DropzoneTitle>{t('title')}</DropzoneTitle>\n            <DropzoneDescription>\n              <Trans\n                t={t}\n                i18nKey={'description'}\n                components={{ strong: <strong />, u: <span /> }}\n              />\n            </DropzoneDescription>\n          </Flex>\n        </Zone>\n      )}\n    </ReactDropzone>\n  );\n};\n","import { Trans, useTranslation } from 'react-i18next';\n\nimport { ContactSupport } from '../ContactSupport';\nimport { Flex } from '../Flex';\nimport { Icons } from '../Icons';\nimport { Typography } from '../Typography';\nimport { useResponsive } from '../hooks/useResponsive';\n\nimport { ErrorBanner as StyledErrorBanner } from './DocumentDropzone.styled';\n\n/**\n * Props for the ErrorBanner component\n */\ninterface Props {\n  /** The i18n translation key for the error message */\n  i18nKey: string;\n  /** Optional translation namespace (defaults to 'components') */\n  namespace?: string;\n  /** Optional translation key prefix (defaults to 'dropzone') */\n  keyPrefix?: string;\n}\n\n/**\n * Part of `DocumentDropzone` component group.\n *\n * ErrorBanner - Displays error messages with contact support link\n *\n * Features:\n * - Error icon display\n * - Internationalized error messages\n * - Integrated ContactSupport component\n * - Responsive text sizing\n *\n * Common error keys:\n * - 'uploadError' - Generic upload failure\n * - 'uploadErrorSameFile' - Duplicate file upload attempt\n * - 'deleteError' - File deletion failure\n *\n * @example\n * <ErrorBanner\n *   i18nKey=\"uploadError\"\n *   namespace=\"components\"\n *   keyPrefix=\"dropzone\"\n * />\n */\nexport const ErrorBanner = ({ i18nKey, namespace, keyPrefix }: Props) => {\n  const { t } = useTranslation(namespace ?? 'components', {\n    keyPrefix: keyPrefix ?? 'dropzone',\n  });\n\n  const { isMobile } = useResponsive();\n\n  return (\n    <StyledErrorBanner>\n      <Icons.ErrorIcon />\n      <Flex\n        flexDirection=\"column\"\n        rowGap={2}\n        width=\"100%\"\n        alignItems=\"flex-start\"\n      >\n        <Typography size={isMobile ? 'xs' : 'sm'}>\n          <Trans t={t} i18nKey={i18nKey} components={{ u: <span /> }} />\n        </Typography>\n        <ContactSupport size={isMobile ? 'xs' : 'sm'} />\n      </Flex>\n    </StyledErrorBanner>\n  );\n};\n","import { keyframes } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { CircularProgress } from '@mui/material';\n\nimport { Button } from '../Button';\nimport { Flex } from '../Flex';\nimport { Icons } from '../Icons';\nimport { typographySize } from '../PlatformSettings';\nimport { customizeStyles } from '../customizeStyles';\n\nexport const ScanningIcon = () => (\n  <IconContainer>\n    <ScanLineWrapper>\n      <Icons.ContractIcon />\n    </ScanLineWrapper>\n  </IconContainer>\n);\n\nexport const DeleteIcon = ({ onClick }: { onClick: () => void }) => (\n  <Button onClick={onClick} variant={'invisible'}>\n    <Icons.DeleteIcon />\n  </Button>\n);\n\nexport const DeletingIcon = () => (\n  <IconContainer>\n    <CircularProgress size=\"18px\" />\n  </IconContainer>\n);\n\nexport const IconContainer = styled(Flex)`\n  min-width: 64px;\n  padding: ${({ theme }) =>\n    `0 ${theme.vars.components?.variables.spacings.md}`};\n`;\n\nconst scanningAnimation = keyframes`\n  0% { top: 0; }\n  50% { top: 100%; }\n  100% { top: 0; }\n`;\n\nexport const ScanLineWrapper = styled('div')(({ theme: { vars } }) => ({\n  position: 'relative',\n  height: 20,\n\n  '&::after': {\n    content: '\"\"',\n    position: 'absolute',\n    top: 0,\n    left: 0,\n    height: 2,\n    width: 24,\n    borderRadius: 2,\n    backgroundColor: vars.components?.variables.colors.primaryDefault,\n    boxShadow: `0 0 4px 0 ${vars.components?.variables.colors.primaryDefault}`,\n    animationName: scanningAnimation,\n    animationDuration: '1.8s',\n    animationTimingFunction: 'ease-in-out',\n    animationDelay: '1ms',\n    animationIterationCount: 'infinite',\n  },\n}));\n\nexport const StyledUploadedFile = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    display: 'flex',\n    width: '100%',\n    gap: vars.components?.variables.spacings.md,\n    padding: vars.components?.variables.spacings.md,\n\n    border: `1px solid ${vars.components?.variables.colors.grey300}`,\n    borderRadius: vars.components?.variables.radius.sm,\n\n    fontSize: vars.components?.variables.typography.desktop.size.xs,\n    lineHeight: '16px',\n    alignItems: 'center',\n\n    '& button': {\n      width: 44,\n      height: 44,\n\n      '& svg': {\n        color: vars.components?.variables.colors.grey900,\n        height: 23,\n        width: 23,\n        minWidth: 23,\n      },\n      border: 'none',\n      cursor: 'pointer',\n      padding: '8px',\n      borderRadius: '8px',\n    },\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.dropzone?.uploadedFile?.root,\n    ),\n  }),\n);\n\nexport const NameAndMetadata = styled('div')(\n  ({ theme: { vars, breakpoints } }) => ({\n    display: 'flex',\n    flexDirection: 'column',\n    flexGrow: 1,\n    gap: vars.components?.variables.spacings.xs,\n    overflow: 'hidden',\n    color: vars.components?.variables.colors.grey700,\n\n    ...typographySize({ breakpoints, vars }, 'xs'),\n  }),\n);\n\nexport const UploadedFileName = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    fontWeight: 700,\n    display: 'block',\n    textOverflow: 'ellipsis',\n    overflow: 'hidden',\n    color: vars.components?.variables.colors.grey900,\n\n    ...typographySize({ breakpoints, vars }, 'sm'),\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.dropzone?.uploadedFile?.fileName,\n    ),\n  }),\n);\n","import { BusinessDocument } from '@finmid/tiger-webapp/queries';\nimport { useState } from 'react';\n\nimport { humanReadableFileSize } from '../utils';\n\nimport {\n  DeleteIcon,\n  DeletingIcon,\n  NameAndMetadata,\n  ScanningIcon,\n  StyledUploadedFile,\n  UploadedFileName,\n} from './UploadedFile.styled';\n\n/**\n * Props for the UploadedFile component\n */\ninterface Props {\n  /** The uploaded document to display */\n  file: BusinessDocument;\n  /**\n   * Callback fired when delete button is clicked\n   * @param id - The document ID to delete\n   */\n  onDelete: (id: string) => void;\n  /** Whether to show scanning animation instead of delete button */\n  isScanning?: boolean;\n}\n\n/**\n * Part of `DocumentDropzone` component group.\n *\n * UploadedFile - Displays an uploaded document with metadata and actions\n *\n * Features:\n * - File name with ellipsis for long names\n * - File extension and human-readable size display\n * - Delete button with loading state\n * - Optional scanning animation\n * - Format: \"[EXTENSION] • [SIZE]\"\n *\n * @example\n * <UploadedFile\n *   file={{\n *     id: '123',\n *     name: 'passport.pdf',\n *     extension: 'pdf',\n *     size: 2048576\n *   }}\n *   onDelete={(id) => deleteFile(id)}\n *   isScanning={false}\n * />\n */\nexport const UploadedFile = ({ file, onDelete, isScanning }: Props) => {\n  const [deleting, setDeleting] = useState(false);\n\n  return (\n    <StyledUploadedFile>\n      <NameAndMetadata>\n        <UploadedFileName title={file.name}>{file.name}</UploadedFileName>\n        <div>{`${file.extension?.toUpperCase()}  •  ${humanReadableFileSize(\n          file.size,\n        )}`}</div>\n      </NameAndMetadata>\n      {isScanning ? (\n        <ScanningIcon />\n      ) : deleting ? (\n        <DeletingIcon />\n      ) : (\n        <DeleteIcon\n          onClick={() => {\n            setDeleting(true);\n            onDelete(file.id);\n          }}\n        />\n      )}\n    </StyledUploadedFile>\n  );\n};\n","import {\n  BusinessDocument,\n  BusinessDocumentValidationResult,\n  DocumentAttachmentLevel,\n  DocumentAttachmentLevelOptions,\n  DocumentType,\n  useFileDelete,\n  useFileUpload,\n  useGetUploadedDocuments,\n} from '@finmid/tiger-webapp/queries';\nimport { AxiosError } from 'axios';\nimport {\n  ReactElement,\n  ReactNode,\n  useCallback,\n  useEffect,\n  useState,\n} from 'react';\n\nimport { useTokenContext } from '../TokenContext';\nimport { useCapturePosthogEvent } from '../utils';\n\nimport {\n  DocumentDropzoneCard,\n  GoodToKnowNotice,\n  HeaderSeparator,\n} from './DocumentDropzone.styled';\nimport { Dropzone } from './Dropzone';\nimport { ErrorBanner } from './ErrorBanner';\nimport { UploadedFile } from './UploadedFile';\n\n/**\n * Props for the DocumentDropzone component\n * @template TLevel - The document attachment level type\n */\ntype Props<TLevel extends DocumentAttachmentLevel> = {\n  /** Optional slots for header and footer content */\n  slots?: {\n    /** React element to display above the dropzone */\n    header?: ReactElement;\n\n    /** If passed, will be shown in a callout message under the dropzone and uploaded files */\n    infoMessage?: ReactNode;\n  };\n  /** The type of document being uploaded */\n  documentType: DocumentType;\n  /**\n   * Callback fired when documents change or errors occur\n   * @param documents - Array of uploaded documents\n   * @param hasError - Whether an error is currently active\n   */\n  onChange: (documents: BusinessDocument[], hasError: boolean) => void;\n  /** Interval of docs refetching, useful for checking async validation results. */\n  refetchInterval?: number;\n  /** Document attachment scope configuration */\n  level: {\n    /** The attachment scope type (e.g., 'BUSINESS', 'OFFER') */\n    type: TLevel;\n    /** Scope-specific options (e.g., `{ offerGroupId }` or just empty object) */\n    options: DocumentAttachmentLevelOptions[TLevel];\n  };\n};\n\n/**\n * DocumentDropzone - Main component for document upload functionality\n *\n * Provides a complete document upload experience including:\n * - Drag-and-drop file upload\n * - Display of uploaded documents\n * - File deletion capability\n * - Error handling\n * - Analytics tracking via PostHog\n *\n * @template TLevel - The document attachment level type\n *\n * @example\n * <DocumentDropzone\n *   level={{ type: 'OFFER', options: { offerGroupId: '123' } }}\n *   documentType={\"CAPITAL_MAX\"}\n *   onChange={(docs, hasError) => {\n *     console.log('Documents updated:', docs);\n *   }}\n * />\n */\nexport function DocumentDropzone<TLevel extends DocumentAttachmentLevel>({\n  level,\n  documentType,\n  onChange,\n  refetchInterval,\n  slots = {},\n}: Props<TLevel>): ReactElement | null {\n  const { header = null, infoMessage } = slots;\n\n  const [errorMessageKey, setErrorMessageKey] = useState<string | null>(null);\n  const capturePosthogEvent = useCapturePosthogEvent();\n\n  const { token } = useTokenContext();\n\n  const { mutateAsync: uploadFile } = useFileUpload<TLevel>(\n    level.type,\n    documentType,\n  );\n  const { mutateAsync: deleteFile } = useFileDelete(documentType);\n\n  const levelOptionsDependency = Object.values(level.options).join(';');\n\n  const { data } = useGetUploadedDocuments<TLevel>({\n    token,\n    documentType,\n    level,\n    refetchInterval,\n  });\n\n  const invalidDocumentErrorKey = `${documentType}.invalidDocument`;\n\n  const onDrop = useCallback(\n    async (acceptedFiles: File[]) => {\n      setErrorMessageKey(null);\n      try {\n        await uploadFile({ token, files: acceptedFiles, ...level.options });\n        capturePosthogEvent('User uploaded a document successfully');\n      } catch (err) {\n        capturePosthogEvent('User failed to upload a document');\n        if (err instanceof AxiosError && err.status === 409) {\n          setErrorMessageKey('uploadErrorSameFile');\n        } else {\n          setErrorMessageKey('uploadError');\n        }\n      }\n    },\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n    [\n      uploadFile,\n      token,\n      capturePosthogEvent,\n      setErrorMessageKey,\n      levelOptionsDependency,\n    ],\n  );\n\n  const onDelete = useCallback(\n    async (id: string) => {\n      setErrorMessageKey(null);\n      try {\n        await deleteFile({ token, id });\n      } catch {\n        setErrorMessageKey('deleteError');\n      }\n    },\n    [deleteFile, token, setErrorMessageKey],\n  );\n\n  useEffect(() => {\n    onChange(data?.documents ?? [], errorMessageKey != null);\n\n    if (\n      data?.documents.find(\n        (document) =>\n          document.validationResult ===\n          BusinessDocumentValidationResult.INVALID,\n      )\n    ) {\n      setErrorMessageKey(invalidDocumentErrorKey);\n    } else {\n      if (errorMessageKey === invalidDocumentErrorKey) {\n        setErrorMessageKey(null);\n      }\n    }\n  }, [data?.documents, errorMessageKey, onChange, invalidDocumentErrorKey]);\n\n  return (\n    <DocumentDropzoneCard data-test-id=\"document-dropzone-card\">\n      {header && (\n        <>\n          {header}\n          <HeaderSeparator />\n        </>\n      )}\n      <Dropzone onDrop={onDrop} data-test-id=\"document-dropzone-dropzone\" />\n      {data?.documents.map((file) => (\n        <UploadedFile\n          file={file}\n          onDelete={onDelete}\n          key={file.id}\n          data-test-id=\"document-dropzone-uploaded-file\"\n          isScanning={\n            file.validationResult === BusinessDocumentValidationResult.PENDING\n          }\n        />\n      ))}\n      {errorMessageKey && (\n        <ErrorBanner\n          i18nKey={errorMessageKey}\n          data-test-id=\"document-dropzone-error-banner\"\n        />\n      )}\n      {infoMessage && <GoodToKnowNotice>{infoMessage}</GoodToKnowNotice>}\n    </DocumentDropzoneCard>\n  );\n}\n","import styled from '@emotion/styled';\n\nimport { Flex } from '../Flex';\nimport { typographySize } from '../PlatformSettings';\nimport { customizeStyles } from '../customizeStyles';\n\nconst BareButton = styled('button')(() => ({\n  display: 'flex',\n  outline: 0,\n  border: 0,\n  padding: 0,\n  background: 'transparent',\n  cursor: 'pointer',\n}));\n\nexport const PopperButton = styled(BareButton)<{ isOpen: boolean }>(\n  ({ theme: { breakpoints, vars }, isOpen }) => ({\n    width: 24,\n    color: '#767676',\n\n    ...customizeStyles({ breakpoints, vars }, (c) => c?.tooltip?.trigger),\n\n    ...(isOpen && { color: vars.components?.colors?.primary }),\n  }),\n);\n\nexport const PopperContainer = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    width: 350,\n    padding: vars.components?.variables.spacings.md,\n    background: vars.components?.variables.colors.white,\n    borderRadius: vars.components?.variables.radius.md,\n    border: `1px solid ${vars.components?.variables.colors.grey300}`,\n    gap: vars.components?.variables.spacings.md,\n    boxShadow: `0px 4px 12px 0px rgba(0, 0, 0, 0.10), 0px 1px 3px 0px rgba(0, 0, 0, 0.06)`,\n\n    ...typographySize({ breakpoints, vars }, 'sm'),\n  }),\n);\n\nexport const StrongBlock = styled('strong')({\n  display: 'block',\n});\n\nexport const List = styled('ul')(({ theme: { vars, breakpoints } }) => ({\n  paddingLeft: 20,\n  margin: 0,\n  color: vars.components?.variables.colors.grey900,\n\n  ...typographySize({ breakpoints, vars }, 'xs'),\n}));\n\nexport const Subtitle = styled('span')(({ theme: { vars, breakpoints } }) => ({\n  color: vars.components?.variables.colors.primaryDefault,\n  ...typographySize({ breakpoints, vars }, 'sm'),\n}));\n\nexport const ArrowContainer = styled('span')({\n  position: 'absolute',\n  width: '11px',\n  height: '18px',\n  boxSizing: 'border-box',\n  right: -10, // width of SVG arrow -1, so it blends in well on zoom as well\n});\n","import { useTheme } from '@emotion/react';\nimport { ClickAwayListener, useMediaQuery } from '@mui/material';\nimport Popper from '@mui/material/Popper';\nimport { TFunction } from 'i18next';\nimport React, { FunctionComponent } from 'react';\nimport { Trans } from 'react-i18next';\n\nimport { Flex } from '../Flex';\nimport { Icons } from '../Icons';\n\nimport {\n  List,\n  PopperButton,\n  PopperContainer,\n  StrongBlock,\n  Subtitle,\n} from './DocumentsPopover.styled';\n\ninterface Props {\n  t: TFunction;\n  titleKey: string;\n  textListKey: string;\n}\n\nexport const DocumentsPopover: FunctionComponent<Props> = ({\n  t,\n  textListKey,\n  titleKey,\n}) => {\n  const [anchorEl, setAnchorEl] = React.useState<null | HTMLElement>(null);\n  const theme = useTheme();\n  const isMobile = useMediaQuery(theme.breakpoints.down('desktop'));\n\n  const handleClick = (event: React.MouseEvent<HTMLElement>) => {\n    setAnchorEl(anchorEl ? null : event.currentTarget);\n  };\n\n  const handleLeave = () => {\n    setAnchorEl(null);\n  };\n\n  const isOpen = Boolean(anchorEl);\n  const id = isOpen ? 'simple-popper' : undefined;\n\n  return (\n    <div>\n      <ClickAwayListener onClickAway={handleLeave}>\n        <PopperButton\n          aria-describedby={id}\n          type=\"button\"\n          onClick={handleClick}\n          isOpen={isOpen}\n        >\n          <Icons.InfoIcon\n            style={{\n              color: theme.vars.components?.variables.colors.primaryDefault,\n            }}\n          />\n        </PopperButton>\n      </ClickAwayListener>\n      <Popper\n        id={id}\n        open={isOpen}\n        anchorEl={anchorEl}\n        placement={isMobile ? 'bottom' : 'left-start'}\n        modifiers={[\n          {\n            name: 'arrow',\n            options: {\n              element: null,\n            },\n          },\n          {\n            name: 'offset',\n            options: {\n              offset: [0, 18],\n            },\n          },\n        ]}\n      >\n        <Flex alignItems=\"flex-start\">\n          <PopperContainer flexDirection=\"column\" rowGap=\"8px\">\n            <Flex\n              justifyContent=\"space-between\"\n              alignItems=\"flex-start\"\n              width=\"100%\"\n            >\n              <div>\n                <Trans\n                  t={t}\n                  i18nKey={titleKey}\n                  components={{\n                    strong: <strong />,\n                    br: <br />,\n                    emp: <Subtitle />,\n                  }}\n                  values={{ year: new Date().getFullYear() - 1 }}\n                />\n              </div>\n            </Flex>\n            <Flex>\n              <Trans\n                t={t}\n                i18nKey={textListKey}\n                components={{\n                  strong: <StrongBlock />,\n                  ul: <List />,\n                  li: <li />,\n                }}\n              />\n            </Flex>\n          </PopperContainer>\n        </Flex>\n      </Popper>\n    </div>\n  );\n};\n","import {\n  useDocumentProps,\n  useFileSubmit,\n  useGetUploadedDocuments,\n} from '@finmid/tiger-webapp/queries';\n\nimport { DocumentDropzone as DocumentDropzoneBase } from './DocumentDropzone';\nimport {\n  DocumentDropzoneCard,\n  GoodToKnowNotice,\n} from './DocumentDropzone.styled';\nimport { DocumentsPopover } from './DocumentsPopover';\nimport { Dropzone } from './Dropzone';\nimport { ErrorBanner } from './ErrorBanner';\nimport { UploadedFile } from './UploadedFile';\n\nexport { GoodToKnowNotice } from './DocumentDropzone.styled';\n\n/**\n * DocumentDropzone compound component type definition\n * Combines the main component with sub-components and hooks\n */\ntype DocumentDropzone = typeof DocumentDropzoneBase & {\n  /** Styled container card component for the dropzone */\n  Card: typeof DocumentDropzoneCard;\n  /** Error banner component for displaying upload/delete errors */\n  ErrorBanner: typeof ErrorBanner;\n  /** Information notice component with icon */\n  GoodToKnowNotice: typeof GoodToKnowNotice;\n  /** Component for displaying uploaded files */\n  UploadedFile: typeof UploadedFile;\n  /** Drag-and-drop zone component */\n  Dropzone: typeof Dropzone;\n  /** Styled popover component */\n  Popover: typeof DocumentsPopover;\n\n  /** A helper-hook for initializing document dropzone props */\n  useProps: typeof useDocumentProps;\n  /** Hook for submitting files */\n  useSubmit: typeof useFileSubmit;\n  /** Hook for fetching uploaded documents */\n  useDocuments: typeof useGetUploadedDocuments;\n};\n\n/**\n * `DocumentDropzone` - Compound component for document upload functionality\n *\n * Main export providing:\n * - Core upload/delete functionality\n * - Sub-components for custom layouts\n * - Hooks for advanced use cases\n *\n * @example\n * // Basic usage\n * const props = DocumentDropzone.useProps(\"OFFER\", \"CAPITAL_MAX\", { offerGroupId: '123' })\n *\n * <DocumentDropzone\n *   onChange={(docs, hasError) => console.log(docs)}\n *   {...props}\n * />\n *\n * @example\n * // Using slots for custom header\n * <DocumentDropzone\n *   level={{ type: 'BUSINESS', options: {} }}\n *   documentType=\"IDENTITY_VERIFICATION\"\n *   onChange={(docs, hasError) => {\n *     setDocuments(docs);\n *     setHasErrors(hasError);\n *   }}\n *   slots={{\n *     header: (\n *       <Flex alignItems=\"center\" gap=\"sm\">\n *         <Icons.DocumentIcon />\n *         <Typography variant=\"h3\">Identity Documents</Typography>\n *       </Flex>\n *     )\n *   }}\n * />\n *\n * @example\n * // Custom layout with sub-components\n * <DocumentDropzone.Card>\n *   <h3>Upload Documents</h3>\n *   <DocumentDropzone.Dropzone onDrop={handleDrop} />\n *   {documents.map(doc => (\n *     <DocumentDropzone.UploadedFile\n *       key={doc.id}\n *       file={doc}\n *       onDelete={handleDelete}\n *     />\n *   ))}\n *   <DocumentDropzone.ErrorBanner i18nKey=\"uploadError\" />\n * </DocumentDropzone.Card>\n *\n */\nconst DocumentDropzone: DocumentDropzone =\n  DocumentDropzoneBase as DocumentDropzone;\n\nDocumentDropzone.Card = DocumentDropzoneCard;\nDocumentDropzone.ErrorBanner = ErrorBanner;\nDocumentDropzone.GoodToKnowNotice = GoodToKnowNotice;\nDocumentDropzone.UploadedFile = UploadedFile;\nDocumentDropzone.Dropzone = Dropzone;\nDocumentDropzone.Popover = DocumentsPopover;\n\nDocumentDropzone.useProps = useDocumentProps;\nDocumentDropzone.useSubmit = useFileSubmit;\nDocumentDropzone.useDocuments = useGetUploadedDocuments;\n\nexport { DocumentDropzone };\n","import { ENVIRONMENT } from '@finmid/environment';\n\nimport { Bridge } from './type';\n\nexport const debugBridge: Bridge = {\n  postMessage: (message) => {\n    if (ENVIRONMENT !== 'localhost') return;\n\n    console.log(\n      '%c[Debug Messenger Bridge]%c %o',\n      'background-color: #0066cc; font-weight: bold; color: white; border-radius: 4px; padding: 2px',\n      'color: inherit;',\n      message,\n    );\n  },\n};\n","import { ENVIRONMENT } from '@finmid/environment';\n\nimport { debugBridge } from './debugBridge';\nimport { Bridge, Message } from './type';\n\nconst androidBridge =\n  window.finmidBridge != null\n    ? {\n        postMessage: (message: Message) => {\n          window.finmidBridge?.postMessage(JSON.stringify(message));\n        },\n      }\n    : null;\n\nconst appleBridge = window.webkit?.messageHandlers?.finmidBridge;\n\nexport function discoverBridge(): {\n  bridge: Bridge | null;\n  isAndroid: boolean;\n  isApple: boolean;\n} {\n  if (ENVIRONMENT === 'localhost')\n    return { bridge: debugBridge, isAndroid: false, isApple: false };\n\n  return {\n    bridge: androidBridge ?? appleBridge ?? null,\n    isAndroid: androidBridge != null,\n    isApple: appleBridge != null,\n  };\n}\n","import { useOverrides } from '@finmid/tiger-webapp/overrides-manager';\nimport {\n  FunctionComponent,\n  PropsWithChildren,\n  createContext,\n  useCallback,\n  useContext,\n  useEffect,\n} from 'react';\n\nimport { usePlatformSettings } from '../PlatformSettings';\n\nimport { discoverBridge } from './discoverBridge';\nimport type { Message } from './type';\n\nexport type MessengerContextValue = {\n  sendMessage: (message: Message) => void;\n  isEmbedded: boolean;\n};\n\nexport const MessengerContext = createContext<MessengerContextValue>({\n  sendMessage: () => {},\n  isEmbedded: true,\n});\n\nconst { bridge, isAndroid, isApple } = discoverBridge();\n\nconst isEmbeddedInMobile = isAndroid || isApple;\nconst isEmbeddedInWeb = window.parent !== window;\n\nconst sentMessages: Message[] = [];\n\nexport const MessengerProvider: FunctionComponent<PropsWithChildren> = ({\n  children,\n}) => {\n  const { embedding } = usePlatformSettings();\n\n  const frameTargetOrigin = embedding?.frameTargetOrigin ?? null;\n  const alwaysEmbed = embedding?.alwaysEmbed ?? false;\n\n  const { overrides } = useOverrides();\n\n  const isEmbedded = alwaysEmbed\n    ? true\n    : overrides?.simulateEmbedding ?? (isEmbeddedInWeb || isEmbeddedInMobile);\n\n  const sendMessage = useCallback(\n    (message: Message) => {\n      if (sentMessages.find((m) => m.type === message.type) != null) return;\n\n      sentMessages.push(message);\n\n      if (isEmbeddedInWeb && frameTargetOrigin != null)\n        window.parent.postMessage(message, frameTargetOrigin);\n\n      bridge?.postMessage(message);\n    },\n    [frameTargetOrigin],\n  );\n\n  useEffect(() => {\n    if (frameTargetOrigin == null) return;\n\n    sendMessage({\n      type: 'INITIALIZED',\n    });\n  }, [frameTargetOrigin, sendMessage]);\n\n  return (\n    <MessengerContext.Provider\n      value={{\n        sendMessage,\n        isEmbedded,\n      }}\n    >\n      {children}\n    </MessengerContext.Provider>\n  );\n};\n\nexport const useMessenger = () => {\n  return useContext(MessengerContext);\n};\n\nexport const useSendFrameMessage = (message: Message) => {\n  const { sendMessage } = useMessenger();\n\n  useEffect(() => {\n    sendMessage(message);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [message.type, sendMessage]);\n};\n","import styled from '@emotion/styled';\nimport { Button, buttonClasses } from '@mui/material';\nimport merge from 'lodash/merge';\n\nimport { unwrapTypographyStyles } from '../Typography';\n\nexport const HeaderButton = styled(Button)(\n  ({\n    theme,\n    theme: {\n      vars: { components },\n      breakpoints,\n    },\n  }) => ({\n    textTransform: 'none',\n    display: 'flex',\n    justifyContent: 'space-between',\n\n    padding: components?.variables.spacings.sm,\n    borderRadius: components?.variables.radius.md,\n    color: components?.variables.colors.grey900,\n\n    [`& .${buttonClasses.endIcon}`]: {\n      margin: 0,\n    },\n\n    ...merge(\n      unwrapTypographyStyles(theme, 'family', 'body'),\n      unwrapTypographyStyles(theme, 'size', 'sm'),\n      unwrapTypographyStyles(theme, 'lineHeight', 'sm'),\n      unwrapTypographyStyles(theme, 'weight', 'default'),\n    ),\n\n    [breakpoints.only('mobile')]: {\n      width: '100%',\n\n      ...merge(\n        unwrapTypographyStyles(theme, 'weight', 'strong'),\n        unwrapTypographyStyles(theme, 'size', 'md'),\n        unwrapTypographyStyles(theme, 'lineHeight', 'md'),\n      ),\n    },\n  }),\n);\n","import { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useLocation } from 'react-router-dom';\n\nimport { HeaderButton } from '../../HeaderButton';\n\ninterface Props {\n  onHelpAndFaqsClick: () => void;\n}\n\nexport const HelpCenterPopupMenu: FunctionComponent<Props> = ({\n  onHelpAndFaqsClick,\n}) => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'header' });\n  const { pathname } = useLocation();\n\n  const isOnDashboard = pathname.startsWith('/dashboard');\n  const isOnHelpCenterPage = pathname.startsWith('/help-and-faqs');\n\n  if (isOnDashboard || isOnHelpCenterPage) {\n    return null;\n  }\n\n  return (\n    <HeaderButton variant=\"text\" disableElevation onClick={onHelpAndFaqsClick}>\n      {t('helpCenterButton', 'Help Center')}\n    </HeaderButton>\n  );\n};\n","import styled from '@emotion/styled';\nimport Menu, { MenuProps, menuClasses } from '@mui/material/Menu';\nimport { FC, PropsWithChildren, ReactNode, useState } from 'react';\n\nimport { Icons } from '../../../Icons';\nimport { HeaderButton } from '../../HeaderButton';\n\nexport const StyledMenu = styled((props: MenuProps) => (\n  <Menu\n    elevation={0}\n    disableScrollLock={true}\n    anchorOrigin={{\n      vertical: 'bottom',\n      horizontal: 'right',\n    }}\n    transformOrigin={{\n      vertical: 'top',\n      horizontal: 'right',\n    }}\n    {...props}\n  />\n))(({ theme }) => ({\n  '& .MuiPaper-root': {\n    minWidth: 240,\n\n    borderRadius: theme.vars.components?.variables.radius?.md,\n    borderWidth: 1,\n    borderStyle: 'solid',\n    borderColor: theme.vars.components?.variables?.colors?.grey300,\n\n    marginTop: theme.vars.components?.variables.spacings.sm,\n    padding: theme.vars.components?.variables.spacings.sm,\n    color: theme.vars.components?.variables?.colors.grey900,\n    backgroundColor: theme.vars.components?.variables?.colors?.white,\n\n    boxShadow:\n      '0px 4px 12px 0px rgba(0, 0, 0, 0.10), 0px 1px 3px 0px rgba(0, 0, 0, 0.06)',\n\n    [`& .${menuClasses.list}`]: {\n      padding: 0,\n      gap: 0,\n      display: 'flex',\n      flexDirection: 'column',\n    },\n  },\n}));\n\ninterface PopupMenuProps {\n  buttonLabel: string;\n  buttonIcon?: ReactNode;\n}\n\nexport const PopupMenu: FC<PropsWithChildren<PopupMenuProps>> = ({\n  buttonLabel,\n  buttonIcon,\n  children,\n}) => {\n  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);\n  const handleClose = () => {\n    setAnchorEl(null);\n  };\n\n  return (\n    <>\n      <HeaderButton\n        variant=\"text\"\n        disableElevation\n        onClick={(event) => setAnchorEl(event.currentTarget)}\n        startIcon={buttonIcon}\n        endIcon={<Icons.ChevronDownIcon />}\n      >\n        {buttonLabel}\n      </HeaderButton>\n      <StyledMenu\n        anchorEl={anchorEl}\n        open={anchorEl != null}\n        onClose={handleClose}\n      >\n        {children}\n      </StyledMenu>\n    </>\n  );\n};\n","import styled from '@emotion/styled';\n\nimport { Flex } from '../../../Flex';\nimport { HeaderButton } from '../../../Header/HeaderButton';\nimport { Icons } from '../../../Icons';\n\nexport const StyledHeaderButton = styled(HeaderButton)(\n  ({ theme: { breakpoints } }) => ({\n    [breakpoints.down('desktop')]: {\n      padding: 0,\n    },\n  }),\n);\n\nexport const OptionContainer = styled(Flex)(({ theme: { vars } }) => ({\n  width: '100%',\n  justifyContent: 'space-between',\n  columnGap: vars.components?.variables.spacings.sm,\n}));\n\nexport const Container = styled(Flex)(({ theme: { vars } }) => ({\n  flexGrow: 1,\n  textAlign: 'left',\n  display: 'inline',\n  padding: vars.components?.variables.spacings.xs,\n}));\n\nexport const LanguageFullName = styled('span')(\n  ({ theme: { vars, breakpoints } }) => ({\n    color: vars.components?.variables.colors.grey900,\n\n    [breakpoints.down('desktop')]: {\n      fontWeight: 400,\n      fontFamily: vars.components?.variables.typography.mobile.family.body,\n      fontSize: vars.components?.variables.typography.mobile.size.md,\n      lineHeight: vars.components?.variables.typography.mobile.lineHeight.md,\n    },\n  }),\n);\n\nexport const StyledCheck = styled(Icons.CheckIcon)<{\n  selected: boolean | 'never';\n}>(({ theme: { breakpoints }, selected }) => ({\n  color: selected ? 'inherit' : 'transparent',\n  width: '17px',\n  height: '17px',\n\n  [breakpoints.down('desktop')]: {\n    width: '26px',\n    height: '26px',\n  },\n}));\n","import { getCountry } from '@finmid/countries';\nimport { LanguageOption } from '@finmid/translations';\nimport { FC, MouseEventHandler, useMemo } from 'react';\n\nimport { Flex } from '../../../Flex';\nimport { Icons } from '../../../Icons';\nimport { Typography } from '../../../Typography';\n\nimport {\n  Container,\n  LanguageFullName,\n  StyledCheck,\n  OptionContainer,\n  StyledHeaderButton,\n} from './LanguageButton.styled';\n\ninterface Props {\n  onClick: MouseEventHandler<HTMLButtonElement>;\n  language: LanguageOption | null;\n  loading?: boolean;\n  dropdown?: true;\n  testId?: string;\n  selected?: boolean | 'never';\n}\n\nexport const LanguageButton: FC<Props> = ({\n  language,\n  testId,\n  dropdown,\n  onClick,\n  loading: loadingProp = false,\n  selected = false,\n}) => {\n  const loading = loadingProp || language == null;\n\n  const flag = useMemo(() => {\n    if (language?.localeCode == null) return null;\n    return getCountry(language.localeCode)?.flag;\n  }, [language?.localeCode]);\n\n  const name = language?.name ?? '';\n\n  return (\n    <StyledHeaderButton\n      onClick={onClick}\n      disabled={loading}\n      variant=\"text\"\n      data-test-id={testId}\n      fullWidth\n    >\n      <OptionContainer data-test-id=\"option-container\">\n        <Flex gap=\"8px\">\n          {selected === 'never' ? null : <StyledCheck selected={selected} />}\n          <Container>\n            <LanguageFullName>\n              {name[0].toUpperCase() + name.substring(1)}\n            </LanguageFullName>\n          </Container>\n        </Flex>\n        <Flex gap=\"sm\">\n          {name === 'cimode'\n            ? '🤖'\n            : flag ?? (\n                <Typography size=\"sm\">\n                  {language?.localeCode.toUpperCase()}\n                </Typography>\n              )}\n          {dropdown && <Icons.ChevronDownIcon />}\n        </Flex>\n      </OptionContainer>\n    </StyledHeaderButton>\n  );\n};\n","import { ENVIRONMENT } from '@finmid/environment';\nimport { useLanguages } from '@finmid/translations';\nimport {\n  FunctionComponent,\n  MouseEventHandler,\n  useCallback,\n  useMemo,\n  useState,\n} from 'react';\n\nimport { StyledMenu } from '../Header/DesktopMenu/components';\nimport { usePlatformSettings } from '../PlatformSettings';\n\nimport { LanguageButton } from './components';\n\nexport const LanguageSwitcher: FunctionComponent = () => {\n  const { localization } = usePlatformSettings();\n\n  const { languages, selectedLanguage } = useLanguages(\n    localization.allowedLocales,\n    localization.allowCimode || ENVIRONMENT === 'localhost',\n  );\n\n  const [anchorEl, setAnchorEl] = useState<HTMLButtonElement | null>(null);\n  const [loading, setLoading] = useState(false);\n\n  const handleClick: MouseEventHandler<HTMLButtonElement> = useCallback(\n    (event) => {\n      setAnchorEl(event.currentTarget);\n    },\n    [],\n  );\n\n  const handleClose = () => {\n    setAnchorEl(null);\n  };\n\n  const menuItems = useMemo(\n    () =>\n      languages.map((language) => ({\n        itemTestId: `${language.name.toLowerCase()}-button`,\n        onClick: async () => {\n          setLoading(true);\n          handleClose();\n          await language.selectLanguage();\n          setLoading(false);\n        },\n        language,\n      })),\n    [languages],\n  );\n\n  return (\n    <>\n      <LanguageButton\n        language={selectedLanguage ?? null}\n        onClick={handleClick}\n        data-test-id=\"lang-switcher-button\"\n        loading={loading}\n        dropdown\n        selected=\"never\"\n      />\n      <StyledMenu\n        anchorEl={anchorEl}\n        open={anchorEl != null}\n        onClose={handleClose}\n      >\n        {menuItems.map((props) => (\n          <LanguageButton\n            selected={selectedLanguage === props.language}\n            key={props.language.localeAndLanguage}\n            {...props}\n          />\n        ))}\n      </StyledMenu>\n    </>\n  );\n};\n","import styled from '@emotion/styled';\nimport { Accordion as AccordionBase, accordionClasses } from '@mui/material';\n\nexport const Accordion = styled(AccordionBase)(({ theme: { vars } }) => ({\n  width: '100%',\n  backgroundColor: 'transparent',\n\n  [`&.${accordionClasses.root}`]: {\n    boxShadow: 'none',\n    margin: 0,\n    paddingInline: 0,\n    paddingBlock: vars.components?.variables.spacings.md,\n  },\n\n  [`& .MuiButtonBase-root.MuiAccordionSummary-root`]: {\n    minHeight: 'auto',\n  },\n}));\n","import styled from '@emotion/styled';\nimport {\n  AccordionSummary as AccordionSummaryBase,\n  accordionSummaryClasses,\n} from '@mui/material';\n\nexport const AccordionSummary = styled(AccordionSummaryBase)(({ theme }) => ({\n  padding: 0,\n  height: 'auto',\n\n  [`& .${accordionSummaryClasses.content}`]: {\n    margin: 0,\n  },\n\n  [`& .${accordionSummaryClasses.expandIconWrapper}`]: {\n    color: theme.vars.components?.variables.colors?.grey900,\n\n    [`&.${accordionSummaryClasses.expanded}`]: {\n      transform: 'rotate(90deg)',\n    },\n  },\n}));\n","import styled from '@emotion/styled';\n\nimport { Flex } from '../../Flex';\n\nexport const LanguageButtonsWrapper = styled(Flex)(\n  ({ theme: { breakpoints, vars } }) => ({\n    [breakpoints.down('desktop')]: {\n      flexDirection: 'column',\n      rowGap: vars.components?.variables.spacings.lg,\n      marginBlockStart: vars.components?.variables.spacings.lg,\n    },\n  }),\n);\n","import { getCountry } from '@finmid/countries';\nimport { ENVIRONMENT } from '@finmid/environment';\nimport { useLanguages } from '@finmid/translations';\nimport { FunctionComponent, useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { Flex } from '../../Flex';\nimport { Icons } from '../../Icons';\nimport { usePlatformSettings } from '../../PlatformSettings';\nimport { Typography } from '../../Typography';\nimport { LanguageButton } from '../components';\n\nimport { Accordion } from './Accordion.styled';\nimport { AccordionSummary } from './AccordionSummary.styled';\nimport { LanguageButtonsWrapper } from './LanguageButtonsWrapper.styled';\n\nexport const MobileLanguageSwitcher: FunctionComponent = () => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'header.menu.mobile' });\n\n  const { localization } = usePlatformSettings();\n\n  const { languages, selectedLanguage } = useLanguages(\n    localization.allowedLocales,\n    localization.allowCimode || ENVIRONMENT === 'localhost',\n  );\n\n  const flag = useMemo(() => {\n    if (selectedLanguage?.localeCode == null) return null;\n\n    return getCountry(selectedLanguage.localeCode)?.flag;\n  }, [selectedLanguage?.localeCode]);\n\n  const name = selectedLanguage?.name ?? '';\n  const languageName = name[0].toUpperCase() + name.substring(1);\n\n  const menuItems = useMemo(\n    () =>\n      languages.map((language) => ({\n        itemTestId: `${language.name.toLowerCase()}-button`,\n        onClick: async () => {\n          await language.selectLanguage();\n        },\n        language,\n      })),\n    [languages],\n  );\n\n  return (\n    <Accordion disableGutters slotProps={{ transition: { timeout: 0 } }}>\n      <AccordionSummary\n        expandIcon={<Icons.ChevronRightIcon />}\n        aria-controls=\"panel1-content\"\n        id=\"panel1-header\"\n      >\n        <Flex\n          justifyContent=\"space-between\"\n          flexWrap=\"nowrap\"\n          style={{ width: 'calc(100% - 8px)' }}\n        >\n          <Typography size=\"md\" weight=\"default\">\n            {t('language', {\n              default: 'Language: {{language}}',\n              language: languageName,\n            })}{' '}\n          </Typography>\n          <div>{flag}</div>\n        </Flex>\n      </AccordionSummary>\n      <LanguageButtonsWrapper>\n        {menuItems.map((props) => (\n          <LanguageButton\n            selected={props.language === selectedLanguage}\n            key={props.language.localeAndLanguage}\n            testId={props.language.languageCode}\n            {...props}\n          />\n        ))}\n      </LanguageButtonsWrapper>\n    </Accordion>\n  );\n};\n","import styled from '@emotion/styled';\n\nimport { HeaderButton } from '../HeaderButton';\n\nexport const ButtonContent = styled('span')(\n  ({ theme: { vars, breakpoints } }) => ({\n    flexGrow: 1,\n    textAlign: 'left',\n    display: 'inline',\n    color: vars.components?.variables.colors.grey900,\n    paddingInline: vars.components?.variables.spacings.xs,\n\n    [breakpoints.down('desktop')]: {\n      fontWeight: 400,\n      fontFamily: vars.components?.variables.typography.mobile.family.body,\n      fontSize: vars.components?.variables.typography.mobile.size.md,\n      lineHeight: vars.components?.variables.typography.mobile.lineHeight.md,\n      paddingInline: 0,\n    },\n  }),\n);\n\nexport const Button = styled(HeaderButton)({\n  whiteSpace: 'nowrap',\n  fontWeight: 400,\n});\n","import { useTranslation } from 'react-i18next';\n\nimport { useConsentContext } from '../../ConsentBanner';\n\nimport { Button, ButtonContent } from './HeaderMenuButton.styled';\n\nexport const HeaderConsentButton = () => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'header' });\n  const { changeConsent } = useConsentContext();\n\n  return (\n    <Button variant=\"text\" onClick={() => changeConsent('MISSING')}>\n      <ButtonContent>\n        {t('cookiePreferencesButon', 'Cookie preferences')}\n      </ButtonContent>\n    </Button>\n  );\n};\n","import { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { Button, ButtonContent } from './HeaderMenuButton.styled';\n\ninterface Props {\n  onClick: () => void;\n}\n\nexport const HelpAndFaqsButton: FunctionComponent<Props> = ({ onClick }) => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'header' });\n  return (\n    <Button variant=\"text\" onClick={onClick}>\n      <ButtonContent>{t('helpCenterButton', 'Help Center')}</ButtonContent>\n    </Button>\n  );\n};\n","import { useTranslation } from 'react-i18next';\n\nimport { LanguageSwitcher } from '../../../LanguageSwitcher';\nimport { HeaderConsentButton } from '../../components';\n\nimport { PopupMenu } from './PopupMenu';\n\nexport const SettingsPopupMenu = () => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'header' });\n\n  return (\n    <PopupMenu buttonLabel={t('settingsButton', 'Settings')}>\n      <LanguageSwitcher />\n      <HeaderConsentButton />\n    </PopupMenu>\n  );\n};\n","import { ENVIRONMENT } from '@finmid/environment';\nimport { useGetOffers } from '@finmid/tiger-webapp/queries';\nimport { copyTextToClipboard } from '@finmid/utils';\n\nimport { Flex } from '../../../Flex';\nimport { useTokenContext } from '../../../TokenContext';\nimport { Typography } from '../../../Typography';\nimport { Button } from '../../components/HeaderMenuButton.styled';\n\nimport { PopupMenu } from './PopupMenu';\n\nexport const DebugMenu = () => {\n  const { token, businessId, ignoreAction, platformId } = useTokenContext();\n\n  const { data: offers } = useGetOffers({\n    token,\n    ignoreAction,\n  });\n\n  const externalBusinessId = offers?.externalBusinessId;\n\n  if (ENVIRONMENT === 'live') return null;\n\n  return (\n    <PopupMenu buttonLabel={'Staging menu'}>\n      <Button variant=\"text\" onClick={() => copyTextToClipboard(businessId)}>\n        <Flex flexGrow={1} justifyContent=\"space-between\" gap=\"md\">\n          <Typography size=\"sm\">Internal business ID:</Typography>\n          <Typography size=\"sm\">{businessId}</Typography>\n        </Flex>\n      </Button>\n      {externalBusinessId != null && (\n        <Button\n          variant=\"text\"\n          onClick={() => copyTextToClipboard(externalBusinessId)}\n        >\n          <Flex flexGrow={1} justifyContent=\"space-between\" gap=\"md\">\n            <Typography size=\"sm\">External business ID:</Typography>\n            <Typography size=\"sm\">{externalBusinessId}</Typography>\n          </Flex>\n        </Button>\n      )}\n      <Button variant=\"text\" onClick={() => copyTextToClipboard(platformId)}>\n        <Flex flexGrow={1} justifyContent=\"space-between\" gap=\"md\">\n          <Typography size=\"sm\">Platform ID:</Typography>\n          <Typography size=\"sm\">{platformId}</Typography>\n        </Flex>\n      </Button>\n    </PopupMenu>\n  );\n};\n","import { ENVIRONMENT } from '@finmid/environment';\nimport { FunctionComponent } from 'react';\n\nimport { Flex } from '../../Flex';\n\nimport { HelpCenterPopupMenu, SettingsPopupMenu } from './components';\nimport { DebugMenu } from './components/DebugMenu';\n\ninterface Props {\n  standalone?: boolean;\n  onFaqClick: () => void;\n  onHelpAndFeedbackClick: () => void;\n  onHelpAndFaqsClick: () => void;\n}\n\nexport const DesktopMenu: FunctionComponent<Props> = ({\n  standalone,\n  ...props\n}) => {\n  return (\n    <Flex>\n      {ENVIRONMENT !== 'live' && <DebugMenu />}\n      {standalone ? null : <HelpCenterPopupMenu {...props} />}\n      <SettingsPopupMenu />\n    </Flex>\n  );\n};\n","import styled from '@emotion/styled';\n\nimport { Flex } from '../../../Flex';\n\nexport const MenuItems = styled(Flex)(\n  ({\n    theme: {\n      vars: { components },\n    },\n  }) => ({\n    width: '100%',\n    alignItems: 'flex-start',\n    justifyContent: 'flex-start',\n    flexDirection: 'column',\n    '& > button': {\n      width: '100%',\n      borderBottom: `1px solid ${components?.variables.colors.grey300}`,\n      padding: 0,\n      paddingTop: components?.variables.spacings.md,\n      paddingBottom: components?.variables.spacings.md,\n      borderRadius: 0,\n    },\n  }),\n);\n","import styled from '@emotion/styled';\n\nexport const StyledBurger = styled.div<{ open: boolean }>(\n  ({\n    open,\n    theme: {\n      vars: { components },\n    },\n  }) => ({\n    top: '5%',\n    left: '2rem',\n    display: 'flex',\n    flexDirection: 'column',\n    justifyContent: 'space-between',\n    width: 20,\n    height: 18,\n    padding: 0,\n    zIndex: 10,\n\n    '&:focus': {\n      outline: 'none',\n    },\n\n    div: {\n      width: '100%',\n      height: 2,\n      backgroundColor: components?.variables.colors.grey900,\n      borderRadius: 10,\n      transition: 'all 0.3s ease-out',\n      position: 'relative',\n      transformOrigin: '1px',\n\n      ':nth-of-type(1)': {\n        transform: open\n          ? 'translateY(1.5px) rotate(45deg)'\n          : 'translateY(2px) rotate(0)',\n      },\n\n      ':nth-of-type(2)': {\n        opacity: open ? 0 : 1,\n      },\n\n      ':nth-of-type(3)': {\n        transform: open\n          ? 'translateY(-1.5px) rotate(-45deg)'\n          : 'translateY(-2px) rotate(0)',\n      },\n    },\n  }),\n);\n","import styled from '@emotion/styled';\n\nexport const StyledBurgerButton = styled.button({\n  padding: 12,