>\n      <StyledBurgerButton onClick={() => setOpen((o) => !o)}>\n        <StyledBurger open={open}>\n          <div />\n          <div />\n          <div />\n        </StyledBurger>\n      </StyledBurgerButton>\n\n      <StyledMenu open={open}>\n        <Flex gap=\"xl\" flexDirection=\"column\" width=\"100%\" alignItems=\"start\">\n          <Typography size=\"xl\" weight=\"strong\" family=\"title\">\n            {t('title', 'Menu')}\n          </Typography>\n\n          <MenuItems>\n            <HeaderConsentButton />\n            {standalone ? null : helpRoutes}\n            <MobileLanguageSwitcher />\n          </MenuItems>\n        </Flex>\n      </StyledMenu>\n    </Flex>\n  );\n};\n","import styled from '@emotion/styled';\nimport { usePlatform } from '@finmid/platforms';\nimport { useOverrides } from '@finmid/tiger-webapp/overrides-manager';\nimport type { FunctionComponent } from 'react';\nimport { useNavigate } from 'react-router-dom';\n\nimport { Flex } from '../Flex';\nimport { usePlatformSettings } from '../PlatformSettings';\nimport { customizeStyles } from '../customizeStyles';\nimport { useCountrySettings, useResponsive } from '../hooks';\n\nimport { DesktopMenu } from './DesktopMenu';\nimport { MobileMenu } from './MobileMenu';\n\nexport const MOBILE_HEADER_HEIGHT = 60;\nexport const DESKTOP_HEADER_HEIGHT = 88;\nexport const MODAL_MAX_WIDTH = 608;\n\nconst HeaderContainer = styled('div')(({ theme: { breakpoints, vars } }) => ({\n  height: DESKTOP_HEADER_HEIGHT,\n  minHeight: DESKTOP_HEADER_HEIGHT,\n  borderBottom: '#DCDCDC 1px solid',\n  paddingRight: 104,\n  paddingLeft: 104,\n  display: 'flex',\n  justifyContent: 'center',\n\n  position: 'sticky',\n  top: 0,\n  background: 'white',\n  zIndex: 1000,\n\n  [breakpoints.down('desktop')]: {\n    height: MOBILE_HEADER_HEIGHT,\n    minHeight: 'unset',\n\n    paddingTop: vars.components?.variables.spacings.sm,\n    paddingBottom: vars.components?.variables.spacings.sm,\n    paddingRight: vars.components?.variables.spacings.lg,\n    paddingLeft: vars.components?.variables.spacings.lg,\n  },\n}));\n\nconst HeaderContent = styled(Flex)(() => ({\n  maxWidth: 1200,\n  width: '100%',\n  alignItems: 'center',\n  justifyContent: 'space-between',\n}));\n\nconst Logo = styled('div')<{ url: string }>(({ url, theme }) => ({\n  width: 120,\n  height: 44,\n  backgroundImage: `url(${url})`,\n  backgroundSize: 'contain',\n  backgroundRepeat: 'no-repeat',\n  backgroundPosition: 'center',\n\n  cursor: 'pointer',\n\n  ...customizeStyles(theme, (c) => c?.header?.logo),\n}));\n\ninterface Props {\n  standalone?: boolean;\n  onFaqClick?: () => void;\n  onHelpAndFeedbackClick?: () => void;\n  onHelpAndFaqsClick?: () => void;\n}\n\nexport const Header: FunctionComponent<Props> = ({ standalone, ...props }) => {\n  const { resourcesPath } = usePlatformSettings();\n  const { countrySettings } = useCountrySettings();\n  const platform = usePlatform();\n  const { overrides } = useOverrides();\n  const websiteLogo =\n    overrides?.websiteLogo ??\n    (countrySettings?.logo\n      ? `${resourcesPath}${countrySettings.logo}`\n      : platform.websiteLogo);\n\n  const { isMobile } = useResponsive();\n\n  const navigate = useNavigate();\n\n  const navigationProps = {\n    standalone,\n    onFaqClick: () => navigate('/help-and-faqs'),\n    onHelpAndFeedbackClick: () => navigate('/help-and-feedback'),\n    onHelpAndFaqsClick: () => navigate('/help-and-faqs'),\n    ...props,\n  };\n\n  const logoNavigateProps = standalone\n    ? {}\n    : {\n        onClick: () => navigate('/'),\n      };\n\n  return (\n    <HeaderContainer data-test-id=\"header\">\n      <HeaderContent>\n        <Logo url={websiteLogo} {...logoNavigateProps} />\n\n        {isMobile ? (\n          <MobileMenu {...navigationProps} />\n        ) : (\n          <DesktopMenu {...navigationProps} />\n        )}\n      </HeaderContent>\n    </HeaderContainer>\n  );\n};\n","import styled, { CSSObject } from '@emotion/styled';\nimport {\n  CSS