\n\nimport { Flex } from '../Flex';\nimport { TextField } from '../TextField';\nimport { useTokenContext } from '../TokenContext/TokenContext';\n\nimport { FeedbackTitle } from './FeedbackTitle';\nimport {\n  GradeText,\n  StarButton,\n  StarButtonsContainer,\n  Badge,\n  FeedbackQuestionContainer,\n  FeedbackQuestionBackground,\n  SubmitButton,\n} from './FeedbackWidget.styled';\nimport { OtherIcon } from './OtherIcon';\nimport { FeedbackState } from './useFeedback';\n\nconst useOfFundsSuggestions = [\n  { id: 'NEW_EQUIPMENT', label: 'New equipment' },\n  { id: 'RENOVATIONS', label: 'Renovations' },\n  { id: 'NEW_VENUE', label: 'New venue' },\n  { id: 'MARKETING', label: 'Marketing' },\n  { id: 'BILLS', label: 'Bills' },\n  { id: 'OTHER', label: 'Other' },\n] as const;\n\nexport type SuggestionId = (typeof useOfFundsSuggestions)[number]['id'];\n\ninterface Props {\n  onFeedbackSent: () => void;\n  offerId: string;\n  question: QuestionType;\n  index: [number, number];\n  handleOnTitleClick: () => void;\n  isExpanded: boolean;\n  feedbackState: FeedbackState;\n}\n\nexport const FeedbackQuestion: FunctionComponent<Props> = ({\n  onFeedbackSent,\n  offerId,\n  question,\n  index,\n  handleOnTitleClick,\n  isExpanded,\n  feedbackState,\n}) => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'feedbackWidget' });\n  const { vars } = useTheme();\n  const {\n    comment,\n    setComment,\n    selectedRating,\n    setSelectedRating,\n    selectedSuggestions,\n    setSelectedSuggestions,\n    composeComment,\n  } = feedbackState;\n\n  const { token } = useTokenContext();\n  const { mutateAsync: sendFeedback, isPending: isLoading } = usePostFeedback({\n    token,\n    offerId,\n  });\n\n  const [hoverMap, { setAll: setHovers, reset: resetHovers }] = useMap({\n    '1': false,\n    '2': false,\n    '3': false,\n    '4': false,\n    '5': false,\n  });\n\n  const doSendFeedback = useCallback(\n    async (rating: 1 | 2 | 3 | 4 | 5) => {\n      resetHovers();\n      await sendFeedback({\n        rating,\n        type: question,\n        comment: question === 'USE_OF_FUNDS' ? composeComment() : undefined,\n      });\n      onFeedbackSent();\n      setSelectedRating(0);\n    },\n    [\n      onFeedbackSent,\n      question,\n      resetHovers,\n      sendFeedback,\n      composeComment,\n      setSelectedRating,\n    ],\n  );\n\n  const onRate = useCallback(\n    async (rating: 1 | 2 | 3 | 4 | 5) => {\n      if (rating != null) setSelectedRating(rating);\n      setHovers({\n        '1': rating >= 1,\n        '2': rating >= 2,\n        '3': rating >= 3,\n        '4': rating >= 4,\n        '5': rating >= 5,\n      });\n    },\n    [setHovers, setSelectedRating],\n  );\n\n  const getStarProps = useCallback(\n    (rating: 1 | 2 | 3 | 4 | 5) => ({\n      onClick: () => onRate(rating),\n      checked: selectedRating >= rating || hoverMap[rating],\n      onHover: (isHovered: boolean) =>\n        isHovered\n          ? setHovers({\n              '1': rating >= 1 || selectedRating >= 1,\n              '2': rating >= 2 || selectedRating >= 2,\n              '3': rating >= 3 || selectedRating >= 3,\n              '4': rating >= 4 || selectedRating >= 4,\n              '5': rating >= 5 || selectedRating >= 5,\n            })\n          : resetHovers(),\n    }),\n    [hoverMap, onRate, resetHovers, selectedRating, setHovers],\n  );\n\n  const onSuggestionClick = useCallback(\n    (suggestionId: SuggestionId) =>\n      setSelectedSuggestions((old) =>\n        old.includes(suggestionId)\n          ? old.filter((id) => id !== suggestionId)\n          : [...old, suggestionId],\n      ),\n    [setSelectedSuggestions],\n  );\n\n  const isDisabled = useMemo(() => {\n    const noSuggestionsSelected = selectedSuggestions.length === 0;\n    const commentWithoutOtherAndNoSelections =\n      comment?.length > 0 &&\n      !selectedSuggestions.includes('OTHER') &&\n      noSuggestionsSelected;\n\n    return (\n      isLoading || noSuggestionsSelected || commentWithoutOtherAndNoSelections\n    );\n  }, [isLoading, selectedSuggestions, comment]);\n\n  return (\n    <FeedbackQuestionBackground>\n      <FeedbackTitle\n        handleClick={handleOnTitleClick}\n        title={t(`question.${question}.title`)}\n        isExpanded={isExpanded}\n      />\n      {question === 'USE_OF_FUNDS' ? (\n        <FeedbackQuestionContainer flexDirection={'column'}>\n          <Flex justifyContent={'flex-start'} gap=\"sm\" flexWrap={'wrap'}>\n            {useOfFundsSuggestions.map(({ id, label }) => {\n              const isActive = selectedSuggestions.includes(id);\n              return (\n                <Badge\n                  key={id}\n                  onClick={() => onSuggestionClick(id)}\n                  isActive={isActive}\n                >\n                  {t(`suggestion.${id}`, label)}\n                  {id === 'OTHER' ? <OtherIcon isActive={isActive} /> : null}\n                </Badge>\n              );\n            })}\n          </Flex>\n          {selectedSuggestions.includes('OTHER') ? (\n            <TextField\n              autoComplete={'off'}\n              placeholder={t(`tellUsMore`)}\n              text={comment ?? ''}\n              id=\"use-of-funds\"\n              onChange={(v) => setComment(v)}\n              fullWidth\n              sx={{\n                marginTop: vars.components?.variables.spacings.xl,\n                '& input': {\n                  paddingTop: '12px !important',\n                  paddingBottom: '12px !important',\n                },\n              }}\n            />\n          ) : null}\n          <Flex\n            justifyContent={'flex-start'}\n            width={'100%'}\n            pt={vars.components?.variables.spacings.xl}\n          >\n            <SubmitButton\n              variant=\"secondary\"\n              onClick={() => doSendFeedback(5)}\n              disabled={isDisabled}\n              loading={isLoading}\n            >\n              <span>\n                {t('question.USE_OF_FUNDS.buttonText')}\n                {index && (\n                  <>\n                    {' '}\n                    ({index[0]}/{index[1]})\n                  </>\n                )}\n              </span>\n            </SubmitButton>\n          </Flex>\n        </FeedbackQuestionContainer>\n      ) : (\n        <FeedbackQuestionContainer\n          flexDirection={'column'}\n          sx={{ width: '100%' }}\n        >\n          <StarButtonsContainer onMouseLeave={resetHovers}>\n            <StarButton {...getStarProps(1)} />\n            <StarButton {...getStarProps(2)} />\n            <StarButton {...getStarProps(3)} />\n            <StarButton {...getStarProps(4)} />\n            <StarButton {...getStarProps(5)} />\n          </StarButtonsContainer>\n\n          <Flex flexDirection=\"row\" justifyContent=\"space-between\" width=\"100%\">\n            <GradeText>\n              {t(`question.${question}.lowGrade`, 'Not satisfied')}\n            </GradeText>\n            <GradeText>\n              {t(`question.${question}.highGrade`, 'Very satisfied')}\n            </GradeText>\n          </Flex>\n          <Flex\n            justifyContent={'flex-start'}\n            width={'100%'}\n            pt={vars.components?.variables.spacings.xl}\n          >\n            <SubmitButton\n              variant=\"secondary\"\n              disabled={selectedRating === 0 || isLoading}\n              loading={isLoading}\n              onClick={() => {\n                if (selectedRating > 0) {\n                  doSendFeedback(selectedRating as 1 | 2 | 3 | 4 | 5);\n                }\n              }}\n            >\n              <span>\n                {t(`question.USE_OF_FUNDS.buttonText`)}\n                {index && (\n                  <>\n                    {' '}\n                    ({index[0]}/{index[1]})\n                  </>\n                )}\n              </span>\n            </SubmitButton>\n          </Flex>\n        </FeedbackQuestionContainer>\n      )}\n    </FeedbackQuestionBackground>\n  );\n};\n","import { QuestionType } from '@finmid/tiger-webapp/queries';\n\nexport const feedbackQuestions: QuestionType[] = [\n  'NPS',\n  'AMOUNT_OF_CAPITAL_SATISFACTION',\n  'OVERALL_EXPERIENCE',\n];\n","import { useGetFeedback, useGetOffers } from '@finmid/tiger-webapp/queries';\nimport { sanitizeString } from '@finmid/utils/sanitizeString';\nimport { Dispatch, SetStateAction, useCallback, useState } from 'react';\n\nimport { useTokenContext } from '../TokenContext';\n\nimport { SuggestionId } from './FeedbackQuestion';\nimport { feedbackQuestions } from './feedbackQuestions';\n\ninterface Options {\n  offerId: string;\n}\n\nexport const useFeedback = ({ offerId }: Options) => {\n  const { token, ignoreAction } = useTokenContext();\n\n  const { data } = useGetOffers({ token, ignoreAction });\n  const latestCreditFinancingSetup =\n    data?.latestCredit?.financingSetup ?? 'MCA';\n\n  const totalQuestions = latestCreditFinancingSetup === 'CSP' ? 3 : 4;\n\n  const { data: answeredFeedback, isLoading } = useGetFeedback({\n    offerId,\n    token,\n  });\n\n  const unansweredQuestions = answeredFeedback?.missingTypes ?? [];\n\n  const answeredQuestions = feedbackQuestions.filter(\n    (q) => !unansweredQuestions.includes(q),\n  );\n\n  return {\n    answeredQuestions,\n    unansweredQuestions,\n    isLoading,\n    totalQuestions,\n  };\n};\n\nexport type FeedbackState = {\n  selectedRating: number;\n  comment: string;\n  selectedSuggestions: SuggestionId[];\n  setSelectedRating: Dispatch<SetStateAction<number>>;\n  setComment: Dispatch<SetStateAction<string>>;\n  setSelectedSuggestions: Dispatch<SetStateAction<SuggestionId[]>>;\n  composeComment: () => string;\n};\nexport const useFeedbackState = (): FeedbackState => {\n  const [selectedRating, setSelectedRating] = useState(0);\n  const [comment, setComment] = useState<string>('');\n  const [selectedSuggestions, setSelectedSuggestions] = useState<\n    SuggestionId[]\n  >([]);\n\n  const composeComment = useCallback(() => {\n    const sanitizedComment = comment?.trim() ? sanitizeString(comment) : '';\n\n    return `${selectedSuggestions\n      .map((suggestion) =>\n        suggestion === 'OTHER' && sanitizedComment\n          ? `OTHER: ${sanitizedComment}`\n          : suggestion,\n      )\n      .join(', ')}`;\n  }, [selectedSuggestions, comment]);\n\n  return {\n    selectedRating,\n    setSelectedRating,\n    comment,\n    setComment,\n    selectedSuggestions,\n    setSelectedSuggestions,\n    composeComment,\n  };\n};\n","import { useTheme } from '@emotion/react';\nimport { TaskAlt } from '@mui/icons-material';\nimport { FunctionComponent, PropsWithChildren } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useLocalStorage } from 'react-use';\n\nimport { Flex } from '../Flex';\nimport { Loader } from '../Loader';\nimport { CustomisationSlot } from '../PlatformSettings';\n\nimport { FeedbackBlockContainer } from './FeedbackBlock.styled';\nimport { FeedbackQuestion } from './FeedbackQuestion';\nimport { FeedbackTitle } from './FeedbackTitle';\nimport { SuccessScreen, SuccessText, Title } from './FeedbackWidget.styled';\nimport { feedbackQuestions } from './feedbackQuestions';\nimport { useFeedback, useFeedbackState } from './useFeedback';\n\nconst defaultQuestion = feedbackQuestions[feedbackQuestions.length - 1];\n\ninterface Props {\n  offerId: string;\n  onAllFeedbackSent?: () => void;\n}\n\nexport const FeedbackBlock: FunctionComponent<PropsWithChildren<Props>> = ({\n  offerId,\n  onAllFeedbackSent,\n  children,\n}) => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'feedbackWidget' });\n  const { vars } = useTheme();\n\n  const [isExpanded, setIsExpanded] = useLocalStorage(\n    'feedback-popup-open',\n    true,\n  );\n\n  const feedbackState = useFeedbackState();\n\n  const { unansweredQuestions, isLoading, totalQuestions } = useFeedback({\n    offerId,\n  });\n\n  const currentQuestion = unansweredQuestions[0];\n  const allFeedbackSent =\n    unansweredQuestions && unansweredQuestions.length === 0;\n\n  const toggleExpanded = () => setIsExpanded(!isExpanded);\n\n  if (isLoading) {\n    return (\n      <FeedbackBlockContainer>\n        <Flex p={2}>\n          <Loader />\n        </Flex>\n      </FeedbackBlockContainer>\n    );\n  }\n\n  if (allFeedbackSent) {\n    onAllFeedbackSent?.();\n    return (\n      <FeedbackBlockContainer>\n        <SuccessScreen>\n          <CustomisationSlot\n            slot={'feedbackWidget.successImage'}\n            props={{}}\n            fallback={\n              <TaskAlt\n                sx={{ fill: vars.components?.variables.colors?.primaryDefault }}\n              />\n            }\n          />\n          <Flex flexDirection={'column'} alignItems={'flex-start'} gap=\"sm\">\n            <Title>\n              {t('thankingTitle', 'Thank you for sharing your feedback!')}\n            </Title>\n            <SuccessText>\n              {t('thankingNote', 'Your response has been recorded.')}\n            </SuccessText>\n          </Flex>\n        </SuccessScreen>\n      </FeedbackBlockContainer>\n    );\n  }\n\n  return (\n    <FeedbackBlockContainer>\n      {isExpanded ? (\n        <FeedbackQuestion\n          offerId={offerId}\n          onFeedbackSent={() => {\n            if (unansweredQuestions.length === 1) {\n              onAllFeedbackSent?.();\n            }\n          }}\n          key={currentQuestion ?? defaultQuestion}\n          question={currentQuestion ?? defaultQuestion}\n          index={[\n            totalQuestions + 1 - unansweredQuestions.length,\n            totalQuestions,\n          ]}\n          handleOnTitleClick={toggleExpanded}\n          isExpanded={isExpanded}\n          feedbackState={feedbackState}\n        />\n      ) : (\n        <FeedbackTitle\n          handleClick={toggleExpanded}\n          title={t(`yourFeedbackMatters`)}\n          isExpanded={!!isExpanded}\n        />\n      )}\n      {children}\n    </FeedbackBlockContainer>\n  );\n};\n","import styled from '@emotion/styled';\nimport { FunctionComponent, useEffect, useState } from 'react';\n\nimport { customizeStyles } from '../customizeStyles';\n\nimport { FeedbackBlock } from './FeedbackBlock';\nimport { useFeedback } from './useFeedback';\n\ninterface Props {\n  offerId: string;\n  revealPopup?: boolean;\n}\n\nconst PopupWrapper = styled('div')(({ theme: { vars, breakpoints } }) => ({\n  position: 'fixed',\n  bottom: vars.components?.variables.spacings.md,\n  right: vars.components?.variables.spacings.md,\n  zIndex: 10,\n  transition: 'opacity .5s ease-in-out',\n  width: 412,\n\n  [breakpoints.down('tablet')]: {\n    left: vars.components?.variables.spacings.md,\n    width: 'unset',\n  },\n\n  ...customizeStyles(\n    {\n      breakpoints,\n      vars,\n    },\n    (c) => c?.feedbackWidget?.popupWrapper,\n  ),\n}));\n\nconst MobileSpacer = styled('div')(({ theme: { breakpoints } }) => ({\n  display: 'none',\n  width: '100%',\n  // Only add space on mobile/tablet sizes\n  [breakpoints.down('tablet')]: {\n    display: 'block',\n  },\n}));\n\nexport const FeedbackPopup: FunctionComponent<Props> = ({\n  offerId,\n  revealPopup,\n}) => {\n  const { unansweredQuestions } = useFeedback({ offerId });\n  const haveUnanswered = unansweredQuestions.length !== 0;\n\n  const [open, setOpen] = useState(revealPopup || haveUnanswered);\n  const [finished, setFinished] = useState(false);\n\n  useEffect(() => {\n    if (haveUnanswered) {\n      setOpen(true);\n    }\n  }, [haveUnanswered]);\n\n  useEffect(() => {\n    if (finished) {\n      setTimeout(() => setOpen(false), 5000);\n    }\n  }, [finished]);\n\n  if (!open) return null;\n\n  return (\n    <>\n      <PopupWrapper style={{ opacity: finished ? 0 : 1 }}>\n        <FeedbackBlock\n          offerId={offerId}\n          onAllFeedbackSent={() => setTimeout(() => setFinished(true), 4500)}\n        />\n      </PopupWrapper>\n      {/* Spacer to ensure page content isn't covered on mobile when popup is open */}\n      <MobileSpacer style={{ height: 30 }} />\n    </>\n  );\n};\n","import {\n  createContext,\n  FunctionComponent,\n  PropsWithChildren,\n  useContext,\n  useMemo,\n} from 'react';\n\nimport {\n  FlowSettings,\n  getFlowSettings,\n  FlowType,\n} from '../TokenContext/flowSettings';\n\ninterface FlowContextValue {\n  flow: FlowType | null;\n  isCapitalMaxFlow: boolean;\n  isSignatureFlow: boolean;\n  settings: FlowSettings | null;\n}\n\nconst FlowContext = createContext<FlowContextValue>({\n  flow: null,\n  isCapitalMaxFlow: false,\n  isSignatureFlow: false,\n  settings: null,\n});\n\nexport const FlowProvider: FunctionComponent<PropsWithChildren> = ({\n  children,\n}) => {\n  const value = useMemo(() => {\n    const settings = getFlowSettings();\n    return {\n      flow: settings?.flow ?? null,\n      isCapitalMaxFlow: settings?.flow === 'CAPITAL_MAX',\n      isSignatureFlow: settings?.flow === 'SIGNATURE',\n      settings,\n    };\n  }, []);\n\n  return <FlowContext.Provider value={value}>{children}</FlowContext.Provider>;\n};\n\nexport const useFlowSettings = () => useContext(FlowContext);\n","import { useTheme } from '@emotion/react';\n\nimport { ColorVariables } from '../PlatformSettings';\n\ninterface PathProps {\n  d?: string;\n  strokeWidth?: string;\n}\n\nexport const WhitePath = (props: PathProps) => {\n  const { vars } = useTheme();\n  return <path {...props} stroke={vars.components?.variables.colors.white} />;\n};\n\ntype PlaceholderProps = {\n  x?: string;\n  y?: string;\n  width?: string;\n  height?: string;\n  rx?: string;\n  ry?: string;\n  transform?: string;\n  variant: keyof ColorVariables;\n};\n\nexport const Placeholder = ({ variant, ...props }: PlaceholderProps) => {\n  const { vars } = useTheme();\n  return <rect {...props} fill={vars.components?.variables.colors[variant]} />;\n};\n\nexport interface RectangleProps {\n  x?: string;\n  y?: string;\n  width?: string;\n  height?: str