xport const GetCapitalNoCodeVisual = () => {\n  return (\n    <ImageWrapper data-test-id=\"image-wrapper\">\n      <StyledVisualSvg />\n    </ImageWrapper>\n  );\n};\n","interface Options {\n  to: string;\n  subject: string;\n  body: string;\n}\n\nexport function mailTo({ body, subject, to }: Options): void {\n  window.location.href = `mailto:${to}?subject=${encodeURIComponent(\n    subject,\n  )}&body=${encodeURIComponent(body)}`;\n}\n","import { useTheme } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { buttonClasses, useMediaQuery } from '@mui/material';\nimport { PropsWithChildren, ReactElement } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { Button, BUTTON_BORDER_WIDTH, ButtonVariant } from './Button';\nimport { Flex } from './Flex';\nimport { Icons } from './Icons';\n\nimport { customizeStyles, MOBILE_HEADER_HEIGHT } from './';\n\ninterface Props {\n  onContinue: () => void;\n  continueText?: string;\n  continueButtonVariant?: ButtonVariant;\n  continueButtonTestId?: string;\n\n  hideBackButton?: boolean;\n  onBack?: () => void;\n\n  isSubmitButton?: boolean;\n  topComponent?: ReactElement;\n  isLoading?: boolean;\n  isDisabled?: boolean;\n  isFullHeight?: boolean;\n  fullHeaderHeight?: boolean;\n}\n\nexport const MobileStickyNavigation = ({\n  onBack,\n  onContinue,\n  continueText,\n  continueButtonVariant = 'primary',\n  children,\n  isSubmitButton,\n  hideBackButton,\n  topComponent,\n  isLoading,\n  isDisabled,\n  isFullHeight,\n  continueButtonTestId = 'continue-button',\n  fullHeaderHeight = true,\n}: PropsWithChildren<Props>) => {\n  const navigate = useNavigate();\n  const { breakpoints } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n  const { t } = useTranslation('turnkey');\n\n  const handleClickBackButton = () => {\n    if (onBack != null) {\n      onBack();\n    } else {\n      navigate(-1);\n    }\n  };\n\n  if (!isMobile) {\n    return children;\n  }\n\n  return (\n    <Wrapper isFullHeight={isFullHeight} fullHeaderHeight={fullHeaderHeight}>\n      {children}\n      <BarContainer data-test-id=\"mobile-sticky-navigation\">\n        {topComponent}\n        <Flex justifyContent={'space-between'} width={'100%'} gap=\"md\">\n          {hideBackButton ? null : (\n            <BackButton variant=\"secondary\" onClick={handleClickBackButton}>\n              <Icons.ArrowBackIcon width={22} height={22} />\n            </BackButton>\n          )}\n          <ContinueButton\n            variant={continueButtonVariant}\n            onClick={onContinue}\n            type={isSubmitButton ? 'submit' : 'button'}\n            loading={isLoading}\n            disabled={isLoading || isDisabled}\n            data-test-id={continueButtonTestId}\n          >\n            {continueText ?? t('continue')}\n          </ContinueButton>\n        </Flex>\n      </BarContainer>\n    </Wrapper>\n  );\n};\n\nconst Wrapper = styled.div<{\n  isFullHeight?: boolean;\n  fullHeaderHeight?: boolean;\n}>(({ theme: { breakpoints, vars }, isFullHeight, fullHeaderHeight }) => ({\n  width: '100%',\n  display: 'flex',\n  flexDirection: 'column',\n  position: 'relative',\n  justifyContent: 'space-between',\n  alignItems: 'center',\n  height: `calc(100vh - ${MOBILE_HEADER_HEIGHT}px)`,\n\n  ...customizeStyles(\n    { breakpoints, vars },\n    (c) => c?.mobileNavigation?.wrapper?.default,\n  ),\n\n  ...(!fullHeaderHeight &&\n    customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.mobileNavigation?.wrapper?.reducedHeight,\n    )),\n\n  ...(isFullHeight && {\n    [breakpoints.down('desktop')]: {\n      height: '100vh',\n    },\n  }),\n}));\n\nconst BarContainer = styled.div(({ theme: { breakpoints, vars } }) => ({\n  width: '100%',\n  display: 'flex',\n  flexDirection: 'column',\n  position: 'sticky',\n  bottom: 0,\n  zIndex: 10,\n\n  background: vars.components?.variables.colors.white,\n\n  borderTopWidth: 1,\n  borderTopStyle: 'solid',\n  borderColor: vars.components?.variables.colors.grey300,\n\n  padding: vars.components?.variables.spacings.lg,\n  gap: vars.components?.variables.spacings.md,\n\n  ...customizeStyles(\n    { breakpoints, vars },\n    (c) => c?.mobileNavigation?.background,\n  ),\n}));\n\nconst BackButton = styled(Button)(({ theme: { breakpoints, vars } }) => ({\n  color: vars.components?.variables.colors.primaryDefault,\n  minWidth: 'unset',\n\n  [`&.${buttonClasses.root}`]: {\n    padding: `calc(${vars.components?.variables.spacings.xs} + ${vars.components?.variables.spacings.sm} - ${BUTTON_BORDER_WIDTH}px)`,\n  },\n\n  ...customizeStyles(\n    { breakpoints, vars },\n    (c) => c?.mobileNavigation?.backButton,\n  ),\n}));\n\nconst ContinueButton = styled(Button)(({ theme: { breakpoints, vars } }) => ({\n  display: 'flex',\n  flexGrow: 1,\n\n  ...customizeStyles(\n    { breakpoints, vars },\n    (c) => c?.mobileNavigation?.continueButton,\n  ),\n}));\n","import styled from '@emotion/styled';\nimport { Box } from '@mui/material';\n\nimport { Flex } from '../Flex';\nimport { customizeStyles } from '../customizeStyles';\nimport { cssDesktopColumns } from '../utils';\n\nexport const HelpCenterLayoutBackground = styled(Box)(({ theme }) => ({\n  display: 'flex',\n  flex: 1,\n  flexDirection: 'column',\n  alignItems: 'center',\n  backgroundColor: theme.vars.components?.variables.colors?.grey100,\n\n  padding: theme.vars.components?.variables.spacings.lg,\n\n  [theme.breakpoints.up('desktop')]: {\n    padding: 0,\n    paddingTop: theme.vars.components?.variables.spacings.xxl,\n    paddingBottom: theme.vars.components?.variables.spacings.xxl,\n  },\n\n  ...customizeStyles(theme, (c) => c?.helpCenter?.layout),\n}));\n\nexport const Container = styled(Flex)(({ theme }) => ({\n  gap: theme.vars.components?.variables.spacings.xl,\n\n  display: 'flex',\n  flexDirection: 'column',\n  alignItems: 'start',\n\n  [theme.breakpoints.up('desktop')]: {\n    maxWidth: cssDesktopColumns(6),\n  },\n\n  ...customizeStyles(theme, (c) => c?.helpCenter?.container),\n}));\n","import { useTheme } from '@emotion/react';\nimport { useMediaQuery } from '@mui/material';\nimport { FC, PropsWithChildren } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { Button } from '../Button';\nimport { Card } from '../Card';\nimport { MobileStickyNavigation } from '../MobileStickyNavigation';\nimport { Typography } from '../Typography';\n\nimport { Container, HelpCenterLayoutBackground } from './HelpPageLayout.styled';\n\ninterface HelpCenterLayoutProps {\n  className?: string;\n  title: string;\n}\n\nexport const HelpCenterLayout: FC<PropsWithChildren<HelpCenterLayoutProps>> = ({\n  className,\n  title,\n  children,\n}) => {\n  const { t } = useTranslation('turnkey');\n  const navigate = useNavigate();\n\n  const { breakpoints } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n\n  return (\n    <MobileStickyNavigation\n      hideBackButton\n      onContinue={() => navigate(-1)}\n      continueText={t('returnToOffer', 'Return to my offer')}\n      continueButtonVariant=\"secondary\"\n    >\n      <HelpCenterLayoutBackground\n        data-test-id=\"help-center-layout\"\n        className={className}\n      >\n        <Container className=\"help-center-body\">\n          <Typography size=\"xl\" family=\"title\" weight=\"strong\">\n            {title}\n          </Typography>\n          <Card className=\"help-center-questions\">{children}</Card>\n          {!isMobile ? (\n            <Button\n              variant=\"secondary\"\n              size=\"large\"\n              fullWidth\n              onClick={() => navigate(-1)}\n            >\n              {t('returnToOffer', 'Return to my offer')}\n            </Button>\n          ) : null}\n        </Container>\n      </HelpCenterLayoutBackground>\n    </MobileStickyNavigation>\n  );\n};\n","import { Trans, useTranslation } from 'react-i18next';\n\nimport { Flex } from '../Flex';\nimport { Link } from '../Link';\nimport { useNullableTokenContext } from '../TokenContext';\nimport { Typography } from '../Typography';\nimport { customized } from '../customizeStyles';\nimport { usePlatformSupportEmail } from '../hooks';\nimport { mailTo } from '../mailTo';\n\nimport { HelpCenterLayout } from './HelpPageLayout';\n\nconst ContactSupport = customized(Typography, (c) => c?.helpAndFeedback?.title);\n\ninterface Props {\n  faqLink?: string;\n}\n\nexport const HelpAndFeedback = ({ faqLink }: Props) => {\n  const supportEmail = usePlatformSupportEmail();\n  const { businessId, platformId } = useNullableTokenContext() ?? {\n    businessId: 'Not set',\n    platformId: 'Financing',\n  };\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'helpAndFeedback',\n  });\n\n  return (\n    <HelpCenterLayout title={t('title', 'Help and feedback')}>\n      <Flex alignItems={'flex-start'} flexDirection={'column'} gap=\"sm\">\n        <ContactSupport size=\"md\" weight=\"strong\">\n          {t('contactSupport', 'Contact support')}\n        </ContactSupport>\n        <Typography size=\"sm\">\n          <Trans\n            t={t}\n            i18nKey={'description'}\n            components={{ a: <Link href={faqLink || '/help-and-faqs'} /> }}\n          />\n        </Typography>\n        <Typography size=\"sm\">\n          <Trans\n            t={t}\n            i18nKey={'contactUsAt'}\n            components={{\n              a: (\n                <Link\n                  href=\"#\"\n                  onClick={(e) => {\n                    e.preventDefault();\n                    mailTo({\n                      subject: t('helpMailto.subject', {\n                        defaultValue: '[{{platform}}] Support request',\n                      }),\n                      body: t('helpMailto.body', {\n                        defaultValue: `\\n\\nPlatform: {{platformId}}\\nBusiness: {{businessId}}`,\n                        platformId,\n                        businessId,\n                      }),\n                      to: supportEmail,\n                    });\n                  }}\n                />\n              ),\n            }}\n            values={{ email: supportEmail.replace(/-/g, '\\u2011') }}\n          />\n        </Typography>\n      </Flex>\n    </HelpCenterLayout>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { Backdrop, Button, Modal as ModalBase } from '@mui/material';\nimport Fade from '@mui/material/Fade';\nimport React, {\n  CSSProperties,\n  forwardRef,\n  FunctionComponent,\n  PropsWithChildren,\n  ReactElement,\n  useEffect,\n  useRef,\n} from 'react';\n\nimport { Icons } from './Icons';\nimport { customizeStyles } from './customizeStyles';\n\nexport const MODAL_CONTENT_ID = 'modal-content';\n\nexport const scrollModalToTop = (): void => {\n  const modalBlock = document.getElementById(MODAL_CONTENT_ID);\n  if (modalBlock) {\n    modalBlock.scrollTop = 0;\n  }\n};\n\ntype ModalContainerProps = { noBlur?: boolean; blurRadius?: number };\nconst ModalContainer = styled(ModalBase, {\n  shouldForwardProp: (p) =>\n    !['noBlur', 'blurRadius', 'dontScrollToTop', 'justifyContent'].includes(p),\n})<{ noBlur?: boolean; blurRadius?: number; dontScrollToTop?: boolean }>(\n  ({\n    theme: { vars, breakpoints },\n    noBlur = false,\n    blurRadius = 5,\n    dontScrollToTop,\n  }) => ({\n    position: dontScrollToTop ? 'fixed' : 'absolute',\n    inset: 0,\n    display: 'flex',\n    alignItems: 'center',\n    justifyContent: 'center',\n    backdropFilter: noBlur ? undefined : `blur(${blurRadius}px)`,\n    backgroundColor: 'rgba(22, 23, 23, 0.24)',\n\n    '& .MuiModal-backdrop': {\n      backgroundColor: 'transparent',\n    },\n\n    ':focus-visible': {\n      outline: 'none',\n    },\n\n    ...customizeStyles({ vars, breakpoints }, (c) => c?.modal?.container),\n  }),\n);\n\ntype ModalBlockProps = {\n  maxWidth?: number;\n  grow?: '1' | '0';\n  justifyContent?: 'flex-start' | 'center' | 'normal';\n  isMobileFullScreen?: boolean;\n};\nconst ModalBlock = styled('div', {\n  shouldForwardProp: (p) =>\n    !['maxWidth', 'grow', 'isMobileFullScreen', 'justifyContent'].includes(p),\n})<ModalBlockProps>(\n  ({\n    maxWidth = 608,\n    theme: { vars, breakpoints },\n    grow = '1',\n    justifyContent = 'normal',\n    isMobileFullScreen,\n  }) => ({\n    position: 'relative',\n    flexGrow: grow,\n    maxWidth,\n    backgroundColor: 'white',\n    display: 'flex',\n    flexDirection: 'column',\n    alignItems: 'center',\n\n    maxHeight: `calc(100% - ${vars.components?.variables.spacings.xxl} * 2)`,\n    overflow: 'auto',\n    justifyContent: justifyContent,\n\n    color: vars.components?.variables.colors?.grey900,\n    borderRadius: vars.components?.variables.radius.md,\n\n    boxShadow:\n      '0px 0px 4px 0px rgba(0, 0, 0, 0.06), 0px 4px 24px 0px rgba(0, 0, 0, 0.24)',\n\n    ':focus-visible': {\n      outline: 'none',\n    },\n\n    [breakpoints.down('tablet')]: {\n      height: isMobileFullScreen ? '100%' : 'auto',\n      ...(!isMobileFullScreen && {\n        margin: vars.components?.variables.spacings.md,\n      }),\n      maxHeight: 'unset',\n    },\n\n    ...customizeStyles({ vars, breakpoints }, (c) => c?.modal?.block),\n  }),\n);\n\nexport const CloseButton = styled(\n  (props: Parameters<typeof Button>[0] & { isRelative?: boolean }) => (\n    <Button variant=\"text\" {...props} />\n  ),\n  {\n    shouldForwardProp: (p) => p !== 'isRelative',\n  },\n)(({ theme: { spacing, vars }, isRelative }) => ({\n  padding: spacing(2),\n  backgroundColor: 'transparent',\n  position: isRelative ? 'relative' : 'absolute',\n  top: 0,\n  right: 0,\n  minWidth: 'auto',\n  border: 'none',\n  color: vars.components?.variables.colors?.grey700,\n}));\n\nconst OptionalFade = forwardRef<\n  HTMLDivElement,\n  {\n    enabled: boolean;\n    children: ReactElement;\n    open: boolean;\n  }\n>(({ enabled, children, open }, ref) =>\n  enabled ? (\n    <Fade in={open}>{React.cloneElement(children, { ref })}</Fade>\n  ) : (\n    React.cloneElement(children, { ref })\n  ),\n);\n\ntype Props = {\n  open?: boolean;\n  onClose?: () => void;\n  paperStyles?: CSSProperties;\n  withCloseButton?: boolean;\n  getModalRef?: (ref: HTMLDivElement | null) => void;\n  dontScrollToTop?: boolean;\n  isWithFade?: boolean;\n} & ModalContainerProps &\n  ModalBlockProps;\n\nexport const Modal: FunctionComponent<PropsWithChildren<Props>> = ({\n  children,\n  maxWidth,\n  open = true,\n  onClose,\n  paperStyles = {},\n  noBlur = false,\n  blurRadius = 6,\n  withCloseButton,\n  grow,\n  isMobileFullScreen = true,\n  dontScrollToTop = false,\n  isWithFade = false,\n  justifyContent,\n  getModalRef,\n}) => {\n  const ref = useRef<HTMLDivElement>(null);\n  const theme = useTheme();\n\n  useEffect(() => {\n    if (open && !dontScrollToTop)\n      window.scrollTo({\n        top: 0,\n      });\n  }, [open, dontScrollToTop]);\n\n  useEffect(() => {\n    if (getModalRef) {\n      getModalRef(ref.current);\n    }\n  }, [getModalRef]);\n\n  return (\n    <ModalContainer\n      open={open}\n      onClose={onClose}\n      noBlur={noBlur}\n      blurRadius={blurRadius}\n      data-test-id=\"modal-container\"\n      dontScrollToTop={dontScrollToTop}\n      slots={{ backdrop: Backdrop }}\n      slotProps={{\n        backdrop: {\n          timeout: 300,\n        },\n      }}\n    >\n      <OptionalFade enabled={isWithFade} open={open}>\n        <ModalBlock\n          ref={ref}\n          maxWidth={maxWidth}\n          style={paperStyles}\n          grow={grow}\n          justifyContent={justifyContent}\n          isMobileFullScreen={isMobileFullScreen}\n          data-test-id=\"modal-block\"\n          id={MODAL_CONTENT_ID}\n        >\n          {children}\n          {withCloseButton && (\n            <CloseButton onClick={onClose}>\n              <Icons.CloseIcon\n                style={{\n                  fontSize: 16,\n                  color: theme.vars.components?.variables.colors.grey700,\n                }}\n              />\n            </CloseButton>\n          )}\n        </ModalBlock>\n      </OptionalFade>\n    </ModalContainer>\n  );\n};\n","import { useTranslation } from 'react-i18next';\n\nimport { Button } from '../../../Button';\n\nexport const BackButton = ({ onClick }: { onClick: () => void }) => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'educationalPopup' });\n  return (\n    <Button\n      variant=\"secondary\"\n      size=\"medium\"\n      style={{ alignSelf: 'center' }}\n      onClick={onClick}\n    >\n      {t('goBackBtn', { defaultValue: 'Back' })}\n    </Button>\n  );\n};\n","import styled from '@emotion/styled';\n\nimport { Flex } from '../../../Flex';\nimport { Typography } from '../../../Typography';\nimport { customized, customizeStyles } from '../../../customizeStyles';\n\nexport const OuterContainer = styled(Flex)(({ theme }) => ({\n  justifyContent: 'flex-start',\n  alignSelf: 'stretch',\n  width: '100%',\n\n  ...customizeStyles(\n    theme,\n    (c) => c?.howPaymentWorks?.description?.outerContainer,\n  ),\n}));\n\nexport const Container = styled(Flex)(({ theme: { vars } }) => ({\n  flexDirection: 'column',\n  rowGap: vars.components?.variables.spacings.sm,\n  alignItems: 'flex-start',\n}));\n\nexport const Title = customized(\n  Typography,\n  (c) => c?.howPaymentWorks?.description?.title,\n);\n\nexport const Content = customized(\n  Typography,\n  (c) => c?.howPaymentWorks?.description?.content,\n);\n\nexport const StyledUl = styled('ul')(({ theme }) => ({\n  display: 'flex',\n  flexDirection: 'column',\n  rowGap: theme.vars.components?.variables.spacings.sm,\n  paddingInlineStart: '26px', // TODO pure guessing as there is no specs\n  marginBlock: 0,\n\n  ...customizeStyles(theme, (c) => c?.howPaymentWorks?.description?.list),\n}));\n","import { useTranslation } from 'react-i18next';\n\nimport { useSelectedOffer } from '../../../SelectedOfferContext';\n\nimport {\n  Container,\n  Content,\n  OuterContainer,\n  StyledUl,\n  Title,\n} from './HowPaymentsWorkDescription.styled';\n\n// TODO no specs for distance between \"li\"?\n\nexport const HowPaymentsWorkDescription = () => {\n  const { collectionMethod } = useSelectedOffer();\n  const { t } = useTranslation('offers', {\n    keyPrefix: `educationalPopup.howPaymentsWork.${collectionMethod}`,\n  });\n\n  return (\n    <OuterContainer>\n      <Container>\n        <Title size=\"lg\" family=\"title\">\n          {t('title', { defaultValue: 'How payments work' })}\n        </Title>\n        <StyledUl>\n          <li>\n            <Content size=\"md\">\n              {t('fixedPercentage', {\n                defaultValue:\n                  'We take a fixed percentage from your {{platform}} sales.',\n              })}\n            </Content>\n          </li>\n          <li>\n            <Content size=\"md\">\n              {t('amountPayout', {\n                defaultValue:\n                  'This amount is automatically taken from your payouts.',\n              })}\n            </Content>\n          </li>\n          <li>\n            <Content size=\"md\">\n              {t('salesUp', {\n                defaultValue: 'If your sales go up, you pay more.',\n              })}\n            </Content>\n          </li>\n          <li>\n            <Content size=\"md\">\n              {t('salesDown', {\n                defaultValue: 'If your sales go down, you pay less.',\n              })}\n            </Content>\n          </li>\n          <li>\n            <Content size=\"md\">\n              {t('payFaster', {\n                defaultValue:\n                  'You can choose to pay more anytime to finish paying faster.',\n              })}\n            </Content>\n          </li>\n        </StyledUl>\n      </Container>\n    </OuterContainer>\n  );\n};\n","import styled from '@emotion/styled';\n\nimport { Flex } from '../../../Flex';\nimport { customizeStyles } from '../../../customizeStyles';\n\nexport const OuterContainer = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    width: '100%',\n    flexDirection: 'row',\n    alignSelf: 'stretch',\n    justifyContent: 'center',\n    alignItems: 'center',\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.howPaymentWorks?.visual?.outerContainer,\n    ),\n  }),\n);\n\nexport const Container = styled(Flex)(({ theme: { vars, breakpoints } }) => ({\n  flexDirection: 'column',\n  rowGap: vars.components?.variables.spacings.md,\n  alignSelf: 'stretch',\n  alignItems: 'flex-start',\n\n  width: '100%',\n\n  ...customizeStyles(\n    { vars, breakpoints },\n    (c) => c?.howPaymentWorks?.visual?.container,\n  ),\n}));\n\nexport const LegendsContainer = styled(Flex)(({ theme: { vars } }) => ({\n  flexDirection: 'column',\n  alignItems: 'flex-start',\n  rowGap: vars.components?.variables.spacings.sm,\n}));\n","import styled from '@emotion/styled';\n\nexport const Indicator = styled('sup')(({ theme: { vars } }) => ({\n  color: vars.components?.variables.colors.primaryDefault,\n  fontWeight: 700,\n}));\n","import styled from '@emotion/styled';\n\nimport { Typography } from '../../../../../Typography';\nimport { customizeStyles } from '../../../../../customizeStyles';\nimport { Indicator } from '../Indicator';\n\nconst Legend = styled('span')`\n  display: inline;\n  margin-inline-start: 8px;\n`;\n\nconst LegendWrapper = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(theme, (c) => c?.howPaymentWorks?.visual?.graph?.legend),\n}));\n\ntype VisualLegendProps = {\n  num: number;\n  legend: string;\n};\n\nexport const VisualLegend = ({ num, legend }: VisualLegendProps) => {\n  return (\n    <LegendWrapper size=\"sm\" weight=\"strong\">\n      <Indicator>{num}</Indicator>\n      <Legend>{legend}</Legend>\n    </LegendWrapper>\n  );\n};\n","import styled from '@emotion/styled';\nimport { Box } from '@mui/material';\n\nimport { Flex } from '../../../../../Flex';\nimport { customizeStyles } from '../../../../../customizeStyles';\n\nexport const VisualGraphContainer = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    width: '100%',\n    justifyContent: 'center',\n    borderRadius: '6px', // TODO variable?\n    border: `1px solid ${vars.components?.variables.colors.grey300}`,\n    backgroundColor: vars.components?.variables.colors.grey100,\n    paddingBlock: vars.components?.variables.spacings.xl,\n    columnGap: '8px',\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.howPaymentWorks?.visual?.graph?.container,\n    ),\n  }),\n);\n\nexport const PaymentsBlock = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  rowGap: '4px',\n}));\n\nexport const PaymentLine = styled(Box)(({ theme: { vars, breakpoints } }) => ({\n  width: 80,\n  height: 2,\n  backgroundColor: vars.components?.variables.colors.primaryDefault,\n}));\n\nexport const RemainingBlock = styled(Box)(\n  ({ theme: { vars, breakpoints } }) => ({\n    width: 80,\n    height: 118,\n    backgroundColor: vars.components?.variables.colors.primaryDefault,\n    marginBlockStart: 6,\n  }),\n);\n","import styled from '@emotion/styled';\n\nimport { Typography } from '../../../../../../Typography';\nimport { customizeStyles } from '../../../../../../customizeStyles';\nimport { useResponsive } from '../../../../../../hooks';\nimport { Indicator } from '../../Indicator';\n\nconst Legend = styled('span')(({ theme }) => ({\n  display: 'inline-block',\n  marginInlineEnd: '8px',\n\n  ...customizeStyles(\n    theme,\n    (c) => c?.howPaymentWorks?.visual?.bracketDescription?.description,\n  ),\n}));\n\ntype BracketDescriptionProps = {\n  num: number;\n  legend: string;\n};\n\nexport const BracketDescription = ({\n  num,\n  legend,\n}: BracketDescriptionProps) => {\n  const { isMobile } = useResponsive();\n\n  if (isMobile) {\n    return (\n      <Typography size=\"sm\" weight=\"strong\">\n        <Indicator>{num}</Indicator>\n      </Typography>\n    );\n  }\n\n  return (\n    <Typography size=\"sm\" weight=\"strong\">\n      <Legend>{legend}</Legend>\n      <Indicator>{num}</Indicator>\n    </Typography>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { useTranslation } from 'react-i18next';\n\nimport { Flex } from '../../../../../../Flex';\n\nimport { BracketDescription } from './BracketDescription';\n\nconst PaymentsBracketContainer = styled(Flex)(() => ({\n  alignSelf: 'start',\n  columnGap: '8px',\n}));\n\nexport const PaymentsBracket = () => {\n  const { vars } = useTheme();\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'educationalPopup.howPaymentsWork',\n  });\n\n  return (\n    <PaymentsBracketContainer>\n      <svg\n        xmlns=\"http://www.w3.org/2000/svg\"\n        width=\"14\"\n        height=\"32\"\n        viewBox=\"0 0 14 32\"\n        fill=\"none\"\n      >\n        <path\n          d=\"M0.5 1H8.5C10.7091 1 12.5 2.79086 12.5 5V27C12.5 29.2091 10.7091 31 8.5 31H0.5\"\n          stroke={vars.components?.variables.colors.grey900}\n          strokeWidth=\"2\"\n        />\n      </svg>\n      <BracketDescription\n        num={2}\n        legend={t('graphPayment', { defaultValue: 'Your payment' })}\n      />\n    </PaymentsBracketContainer>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { useTranslation } from 'react-i18next';\n\nimport { Flex } from '../../../../../../Flex';\n\nimport { BracketDescription } from './BracketDescription';\n\nconst SalesBracketContainer = styled(Flex)(({ theme: { breakpoints } }) => ({\n  columnGap: '23px',\n  alignSelf: 'start',\n\n  [breakpoints.down('desktop')]: {\n    columnGap: '8px',\n  },\n}));\n\nexport const SalesBracket = () => {\n  const { vars } = useTheme();\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'educationalPopup.howPaymentsWork',\n  });\n\n  return (\n    <SalesBracketContainer>\n      <BracketDescription\n        num={1}\n        legend={t('graphSales', { defaultValue: 'Your sales' })}\n      />\n      <svg\n        xmlns=\"http://www.w3.org/2000/svg\"\n        width=\"14\"\n        height=\"156\"\n        viewBox=\"0 0 14 156\"\n        fill=\"none\"\n      >\n        <path\n          d=\"M13.5 1H5.5C3.29086 1 1.5 2.79086 1.5 5V151C1.5 153.209 3.29086 155 5.5 155H13.5\"\n          stroke={vars.components?.variables.colors.grey900}\n          strokeWidth=\"2\"\n        />\n      </svg>\n    </SalesBracketContainer>\n  );\n};\n","import { Box } from '@mui/material';\n\nimport {\n  PaymentsBlock,\n  PaymentLine,\n  RemainingBlock,\n  VisualGraphContainer,\n} from './VisualGraph.styled';\nimport { PaymentsBracket, SalesBracket } from './components';\n\nexport const VisualGraph = () => {\n  return (\n    <VisualGraphContainer>\n      <SalesBracket />\n      <Box>\n        <PaymentsBlock>\n          {Array.from(Array(6)).map((_, index) => (\n            <PaymentLine key={index} />\n          ))}\n        </PaymentsBlock>\n        <RemainingBlock />\n      </Box>\n      <PaymentsBracket />\n    </VisualGraphContainer>\n  );\n};\n","import { useTranslation } from 'react-i18next';\n\nimport { useSelectedOffer } from '../../../SelectedOfferContext';\n\nimport {\n  Container,\n  LegendsContainer,\n  OuterContainer,\n} from './HowPaymentsWorkVisual.styled';\nimport { VisualGraph, VisualLegend } from './components';\n\nexport const HowPaymentsWorkVisual = () => {\n  const { collectionMethod } = useSelectedOffer();\n  const { t } = useTranslation('offers', {\n    keyPrefix: `educationalPopup.howPaymentsWork.${collectionMethod}`,\n  });\n\n  return (\n    <OuterContainer>\n      <Container>\n        <VisualGraph />\n        <LegendsContainer>\n          <VisualLegend\n            num={1}\n            legend={t('legendSales', {\n              defaultValue: 'Your sales on {{platform}}',\n            })}\n          />\n          <VisualLegend\n            num={2}\n            legend={t('legendPayment', {\n              defaultValue: 'Automated deduction based on payment rate',\n            })}\n          />\n        </LegendsContainer>\n      </Container>\n    </OuterContainer>\n  );\n};\n","import styled from '@emotion/styled';\nimport { Link } from 'react-router-dom';\n\nimport { Flex } from '../../../Flex';\nimport { customizeStyles } from '../../../customizeStyles';\n\nexport const OuterContainer = styled(Flex)(({ theme }) => ({\n  alignSelf: 'stretch',\n  justifyContent: 'flex-start',\n\n  ...customizeStyles(\n    theme,\n    (c) => c?.howPaymentWorks?.linkToFaqs?.outerContainer,\n  ),\n}));\n\nexport const StyledLink = styled(Link)(({ theme: { vars, breakpoints } }) => ({\n  color: vars.components?.variables.colors.primaryDefault,\n  textDecoration: 'none',\n  fontWeight: 700,\n  alignSelf: 'flex-start',\n\n  ...customizeStyles(\n    { vars, breakpoints },\n    (c) => c?.howPaymentWorks?.linkToFaqs?.link,\n  ),\n}));\n","import { useTranslation } from 'react-i18next';\n\nimport { OuterContainer, StyledLink } from './LinkToFaqs.styled';\n\nexport const LinkToFaqs = () => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'educationalPopup' });\n  return (\n    <OuterContainer>\n      <StyledLink to=\"/help-and-faqs\">\n        {t('faqLink', { defaultValue: 'Questions? Visit our FAQs' })}\n      </StyledLink>\n    </OuterContainer>\n  );\n};\n","import styled from '@emotion/styled';\n\nimport { Flex } from '../../Flex';\nimport { customizeStyles } from '../../customizeStyles';\n\nexport const OuterContainer = styled(Flex)(({ theme }) => ({\n  width: 700,\n  justifyContent: 'center',\n}));\n\nexport const ModalContainer = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    padding: vars.components?.variables.spacings.xl,\n    flexDirection: 'column',\n    alignItems: 'flex-start',\n\n    rowGap: vars.components?.variables.spacings.xxl,\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.howPaymentWorks?.container,\n    ),\n  }),\n);\n","import { PropsWithChildren } from 'react';\n\nimport { FakeModal } from '../../FakeModal';\nimport { Modal } from '../../Modal';\nimport { usePlatformSettings } from '../../PlatformSettings';\nimport {\n  BackButton,\n  HowPaymentsWorkDescription,\n  HowPaymentsWorkVisual,\n  LinkToFaqs,\n} from '../components';\n\nimport {\n  ModalContainer,\n  OuterContainer,\n} from './HowPaymentsWorkDesktop.styled';\n\ntype Props = {\n  onBackClick: () => void;\n};\n\nexport const HowPaymentsWorkDesktop = ({\n  onBackClick,\n  children,\n}: PropsWithChildren<Props>) => {\n  const { experiments } = usePlatformSettings();\n  const fullScreenModal = experiments?.fullScreenModal;\n\n  if (fullScreenModal) {\n    return (\n      <FakeModal>\n        <OuterContainer>\n          <ModalContainer>\n            <HowPaymentsWorkVisual />\n            <HowPaymentsWorkDescription />\n            <BackButton onClick={onBackClick} />\n            <LinkToFaqs />\n          </ModalContainer>\n        </OuterContainer>\n      </FakeModal>\n    );\n  }\n\n  return (\n    <>\n      {children}\n      <Modal\n        maxWidth={586}\n        isWithFade\n        open\n        onClose={onBackClick}\n        paperStyles={{ width: '586px' }}\n        withCloseButton\n      >\n        <ModalContainer>\n          <HowPaymentsWorkDescription />\n          <HowPaymentsWorkVisual />\n          <LinkToFaqs />\n        </ModalContainer>\n      </Modal>\n    </>\n  );\n};\n","import styled from '@emotion/styled';\n\nimport { Flex } from '../../Flex';\nimport { MOBILE_HEADER_HEIGHT, MODAL_MAX_WIDTH } from '../../Header';\nimport { customizeStyles } from '../../customizeStyles';\n\nexport const Container = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  justifyContent: 'flex-start',\n  marginTop: MOBILE_HEADER_HEIGHT,\n  rowGap: theme.vars.components?.variables.spacings.md,\n  padding: theme.vars.components?.variables.spacings.lg,\n  maxWidth: MODAL_MAX_WIDTH,\n\n  ...customizeStyles(theme, (c) => c?.howPaymentWorks?.wrapper),\n}));\n","import { PropsWithChildren } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { FakeModal } from '../../FakeModal';\nimport { MobileStickyNavigation } from '../../MobileStickyNavigation';\nimport { Modal } from '../../Modal';\nimport { usePlatformSettings } from '../../PlatformSettings';\nimport {\n  HowPaymentsWorkDescription,\n  HowPaymentsWorkVisual,\n  LinkToFaqs,\n} from '../components';\n\nimport { Container } from './HowPaymentsWorkMobile.styled';\n\ntype Props = {\n  onBackClick: () => void;\n};\n\nexport const HowPaymentsWorkMobile = ({\n  onBackClick,\n  children,\n}: PropsWithChildren<Props>) => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'educationalPopup' });\n  const { experiments } = usePlatformSettings();\n  const fullScreenModal = experiments?.fullScreenModal;\n\n  if (fullScreenModal) {\n    return (\n      <FakeModal>\n        <MobileStickyNavigation\n          hideBackButton\n          onContinue={onBackClick}\n          continueButtonVariant=\"secondary\"\n          continueText={t('goBackBtn', { defaultValue: 'Back' })}\n          isFullHeight\n        >\n          <Container>\n            <HowPaymentsWorkVisual />\n            <HowPaymentsWorkDescription />\n            <LinkToFaqs />\n          </Container>\n        </MobileStickyNavigation>\n      </FakeModal>\n    );\n  }\n\n  return (\n    <>\n      {children}\n      <Modal\n        paperStyles={{ maxWidth: '100%', borderRadius: 0 }}\n        withCloseButton\n        onClose={onBackClick}\n        open\n      >\n        <MobileStickyNavigation\n          hideBackButton\n          continueButtonVariant=\"secondary\"\n          continueText={t('goBackBtn', { defaultValue: 'Back' })}\n          onContinue={onBackClick}\n          isFullHeight\n        >\n          <Container>\n            <HowPaymentsWorkDescription />\n            <HowPaymentsWorkVisual />\n            <LinkToFaqs />\n          </Container>\n        </MobileStickyNavigation>\n      </Modal>\n    </>\n  );\n};\n","import { PropsWithChildren } from 'react';\n\nimport { useResponsive } from '../hooks';\n\nimport { HowPaymentsWorkDesktop } from './HowPaymentsWorkDesktop';\nimport { HowPaymentsWorkMobile } from './HowPaymentsWorkMobile';\n\ninterface Props {\n  onBack: () => void;\n}\n\nexport const HowPaymentsWork = ({\n  onBack,\n  children,\n}: PropsWithChildren<Props>) => {\n  const { isMobile } = useResponsive();\n\n  if (isMobile) {\n    return (\n      <HowPaymentsWorkMobile onBackClick={onBack}>\n        {children}\n      </HowPaymentsWorkMobile>\n    );\n  }\n\n  return (\n    <HowPaymentsWorkDesktop onBackClick={onBack}>\n      {children}\n    </HowPaymentsWorkDesktop>\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  Tooltip as MuiTooltip,\n  TooltipProps,\n  tooltipClasses,\n  Paper,\n} from '@mui/material';\n\nimport { customizeStyles } from '../customizeStyles';\n\nexport const TooltipStyled = styled(({ className, ...props }: TooltipProps) => (\n  <MuiTooltip {...props} classes={{ popper: className }} />\n))(({ theme }) => ({\n  [`& .${tooltipClasses.tooltip}`]: {\n    padding: 0,\n    margin: 0,\n    backgroundColor: 'transparent',\n\n    ...customizeStyles(\n      theme,\n      (c) => c?.overview?.flexibleRemittanceRate?.calculator?.plusPopover,\n    ),\n  },\n}));\n\nexport const ContainerStyled = styled(Paper)<{ placement: string }>(\n  ({ theme }) => ({\n    padding: '12px',\n    maxWidth: '300px',\n    zIndex: 1000,\n\n    ...customizeStyles(\n      theme,\n      (c) => c?.overview?.flexibleRemittanceRate?.calculator?.plusPopover,\n    ),\n  }),\n);\n\nexport const TriggerWrapper = styled('div')(() => ({\n  display: 'flex',\n  alignItems: 'center',\n}));\n","import { useTheme } from '@emotion/react';\nimport { Typography, useMediaQuery } from '@mui/material';\nimport { PropsWithChildren, ReactNode } from 'react';\n\nimport {\n  ContainerStyled,\n  TooltipStyled,\n  TriggerWrapper,\n} from './HtmlTooltip.styled';\n\ninterface Props {\n  content: string | ReactNode;\n  triggerComponent: ReactNode;\n  triggerWrapperClassName?: string;\n}\n\nexport const HtmlTooltip = ({\n  content,\n  triggerComponent,\n  triggerWrapperClassName,\n}: PropsWithChildren<Props>) => {\n  const { breakpoints } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n  const placement = isMobile ? 'bottom-end' : 'right';\n\n  return (\n    <TooltipStyled\n      arrow\n      title={\n        <ContainerStyled placement=\"right\">\n          {typeof content === 'string' ? (\n            <Typography>{content}</Typography>\n          ) : (\n            content\n          )}\n        </ContainerStyled>\n      }\n      enterTouchDelay={0}\n      disableFocusListener\n      placement={placement}\n      slotProps={{\n        popper: {\n          modifiers: [\n            {\n              name: 'offset',\n              options: {\n                offset: isMobile ? [0, -10] : 0,\n              },\n            },\n          ],\n        },\n        arrow: {\n          sx: {\n            color: 'inherit',\n            '::before': {\n              boxShadow: '0px 1px 2px rgba(203, 213, 224, 0.75)',\n            },\n          },\n        },\n      }}\n    >\n      <TriggerWrapper className={triggerWrapperClassName}>\n        {triggerComponent}\n      </TriggerWrapper>\n    </TooltipStyled>\n  );\n};\n","import styled from '@emotion/styled';\nimport { Link } from 'react-router-dom';\n\nimport { customizeStyles } from './customizeStyles';\n\nexport const InnerLink = styled(Link)(({ theme }) => ({\n  textDecoration: 'underline',\n  color: theme.vars.components?.variables.colors.grey900,\n\n  ...customizeStyles(theme, (c) => c?.link),\n}));\n","import styled from '@emotion/styled';\n\nimport { Flex } from '../../Flex';\nimport { customizeStyles } from '../../customizeStyles';\n\ntype Props = {\n  isChecked?: boolean;\n};\n\nexport const CheckboxBase = styled(Flex, {\n  shouldForwardProp: (p) => p !== 'isChecked',\n})<Props>(({ theme: { vars, breakpoints }, isChecked }) => ({\n  borderRadius: '4px',\n  border: `1px solid ${\n    isChecked\n      ? vars.components?.variables.colors.primaryDefault\n      : vars.components?.variables.colors.grey900\n  }`,\n  backgroundColor: vars.components?.variables.colors.white,\n  width: 16,\n  height: 16,\n  justifyContent: 'center',\n  alignItems: 'center',\n  marginInlineEnd: vars.components?.variables.spacings.md,\n\n  ...(isChecked\n    ? customizeStyles({ vars, breakpoints }, (c) => c?.checkbox?.checked)\n    : customizeStyles({ vars, breakpoints }, (c) => c?.checkbox?.default)),\n}));\n","import styled from '@emotion/styled';\n\nimport { customizeStyles } from '../../customizeStyles';\n\nimport { CheckboxBase } from './CheckboxBase';\n\nconst StyledCheckbox = styled(CheckboxBase)(({ theme }) => ({\n  color: theme.vars.components?.variables.colors.primaryDefault,\n\n  ...customizeStyles(theme, (c) => c?.checkbox?.path),\n}));\n\nexport const CheckboxChecked = () => {\n  return (\n    <StyledCheckbox isChecked>\n      <svg\n        xmlns=\"http://www.w3.org/2000/svg\"\n        width=\"16\"\n        height=\"16\"\n        viewBox=\"0 0 16 16\"\n        fill=\"none\"\n      >\n        <path\n          d=\"M6.36689 11.9999L2.56689 8.19994L3.51689 7.24994L6.36689 10.0999L12.4836 3.98328L13.4336 4.93328L6.36689 11.9999Z\"\n          fill=\"currentColor\"\n        />\n      </svg>\n    </StyledCheckbox>\n  );\n};\n","import styled from '@emotion/styled';\nimport { TextField as MaterialTextField } from '@mui/material';\n\nimport { customizeStyles } from '../../customizeStyles';\n\nexport const TextArea = styled(MaterialTextField)(\n  ({ theme: { vars, breakpoints } }) => ({\n    '& .MuiInputBase-root': {\n      borderRadius: '8px',\n      padding: 0,\n    },\n\n    '& textarea': {\n      padding: vars.components?.variables.spacings.md,\n      border: `1px solid ${vars.components?.variables.colors.grey300}`,\n      backgroundColor: 'white',\n      borderRadius: '8px',\n\n      '&::placeholder': {\n        color: vars.components?.variables.colors.grey700,\n        fontFamily: vars.components?.variables.typography.desktop.family.body,\n        fontSize: vars.components?.variables.typography.desktop.size.md,\n        lineHeight: vars.components?.variables.typography.desktop.lineHeight.md,\n      },\n    },\n\n    '& .Mui-focused textarea': {\n      borderColor: vars.components?.variables.colors.primaryDefault,\n    },\n\n    [breakpoints.down('desktop')]: {\n      '& textarea': {\n        '&::placeholder': {\n          color: vars.components?.variables.colors.grey700,\n          opacity: 1,\n          fontFamily: vars.components?.variables.typography.mobile.family.body,\n          fontSize: vars.components?.variables.typography.mobile.size.md,\n          lineHeight:\n            vars.components?.variables.typography.mobile.lineHeight.md,\n        },\n      },\n    },\n\n    ...customizeStyles({ vars, breakpoints }, (c) => c?.textArea),\n  }),\n);\n","import styled from '@emotion/styled';\nimport { TextField as MaterialTextField } from '@mui/material';\n\nimport { customizeStyles } from '../../customizeStyles';\n\nexport const TextInput = styled(MaterialTextField)(\n  ({ theme: { vars, breakpoints } }) => ({\n    width: '100%',\n\n    '& .MuiInputBase-root': {\n      borderRadius: vars.components?.variables.radius.sm,\n      padding: 0,\n\n      '& .MuiInputAdornment-root': {\n        margin: 0,\n        paddingInlineStart: vars.components?.variables.spacings.md,\n      },\n\n      '& .MuiOutlinedInput-notchedOutline': {\n        borderWidth: '1px !important',\n        borderColor: `${vars.components?.variables.colors.grey300} !important`,\n      },\n    },\n\n    '& input': {\n      padding: vars.components?.variables.spacings.md,\n      backgroundColor: 'white',\n      borderRadius: vars.components?.variables.radius.sm,\n      fontFamily: vars.components?.variables.typography.desktop.family.body,\n      fontSize: vars.components?.variables.typography.desktop.size.md,\n      lineHeight: vars.components?.variables.typography.desktop.lineHeight.md,\n\n      '&::placeholder': {\n        color: vars.components?.variables.colors.grey700,\n      },\n    },\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (customizations) => customizations?.faqs?.search?.input,\n    ),\n  }),\n);\n","import styled from '@emotion/styled';\nimport { keyframes } from '@mui/material';\n\nimport { Button } from '../Button';\nimport { Flex } from '../Flex';\nimport { Typography } from '../Typography';\nimport { customizeStyles } from '../customizeStyles';\n\nexport const Title = styled(Typography)(({ theme: { vars, breakpoints } }) => ({\n  width: '100%',\n  marginTop: vars.components?.variables.spacings.xxl,\n  marginBottom: vars.components?.variables.spacings.sm,\n\n  [breakpoints.down('desktop')]: {\n    fontSize: vars.components?.variables.typography.mobile.size.xl,\n    lineHeight: vars.components?.variables.typography.mobile.lineHeight.xl,\n    marginTop: 0,\n  },\n\n  ...customizeStyles({ vars, breakpoints }, (c) => c?.codeConfirmation?.title),\n}));\n\nexport const Subtitle = styled(Typography)(\n  ({ theme: { vars, breakpoints } }) => ({\n    marginBottom: vars.components?.variables.spacings.xxl,\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.codeConfirmation?.subtitle,\n    ),\n  }),\n);\n\nexport const CodeInputWrapper = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    flexDirection: 'column',\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.codeConfirmation?.codeInputWrapper,\n    ),\n  }),\n);\n\nexport const ButtonsWrapper = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    flexDirection: 'column',\n    width: '100%',\n    gap: vars.components?.variables.spacings?.md,\n    position: 'sticky',\n    bottom: vars.components?.variables.spacings.md,\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.codeConfirmation?.buttonsWrapper,\n    ),\n  }),\n);\n\nexport const SubmitCodeButton = styled(Button)(\n  ({ theme, theme: { vars, breakpoints } }) => ({\n    width: '100%',\n    textWrap: 'pretty',\n    marginBottom: vars.components?.variables.spacings.md,\n\n    [breakpoints.down('desktop')]: {\n      marginTop: 0,\n    },\n\n    ...customizeStyles(theme, (c) => c?.fakeModal?.submitCodeButton),\n  }),\n);\n\nexport const ResendCodeButton = styled(Button)(({ theme }) => ({\n  textWrap: 'pretty',\n  ...customizeStyles(theme, (c) => c?.fakeModal?.resendCodeButton),\n}));\n\nexport const invalid2faAnimation = keyframes`\nfrom, 20%, 60%, 80%, to {\n  transform: translate3d(0,0,0);\n}\n\n30%,70% {\n  transform: translate3d(-2px, 0, 0);\n}\n\n10%,50%,90% {\n  transform: translate3d(2px, 0, 0);\n}\n`;\n\nexport const Background = styled(Flex)(\n  ({ theme, theme: { vars, breakpoints } }) => ({\n    flexDirection: 'column',\n    flexGrow: 1,\n    padding: vars.components?.variables.spacings.lg,\n    justifyContent: 'flex-start',\n    alignItems: 'flex-start',\n    justifySelf: 'center',\n    maxWidth: 528,\n\n    [breakpoints.up('desktop')]: {\n      padding: vars.components?.variables.spacings.xl,\n      justifyContent: 'center',\n      alignItems: 'center',\n    },\n\n    ...customizeStyles(theme, (c) => c?.codeConfirmation?.background),\n  }),\n);\n\nexport const ResendCodeButtonWrapper = styled(Flex)({\n  width: '100%',\n});\n","import { padLeft } from '@finmid/utils';\nimport { CSSProperties, useEffect, useState } from 'react';\n\nimport { ButtonCustomizationTags } from './PlatformSettings';\nimport { ResendCodeButton } from './TwoFactor/VerifyCode.styled';\nimport { useCssVariable } from './readCssVariable';\n\nexport type ButtonProps = {\n  loading?: boolean;\n  loadingSpinnerSize?: number;\n  testId?: string;\n};\n\ntype TotalTime = {\n  seconds: string;\n  minutes: string;\n  total: number;\n};\n\ntype DisabledTextFunction = (time: TotalTime) => string;\n\ntype TimedButtonProps = {\n  onClick?: () => void;\n  enabledText: string;\n  disabledTextFn: DisabledTextFunction;\n  initialTime?: number;\n  disabledStyle?: CSSProperties;\n  testId?: string;\n  customizationTags?: ButtonCustomizationTags[];\n} & ButtonProps;\n\n/**\n * @deprecated Migrate to `TimedButton` from './Button' instead.\n */\nexport const LegacyTimedButton = ({\n  onClick = () => {\n    /* noop */\n  },\n  initialTime = 120,\n  enabledText,\n  disabledTextFn,\n  disabledStyle,\n  testId,\n  customizationTags,\n  ...props\n}: TimedButtonProps) => {\n  const [time, setTime] = useState(120);\n\n  const legacyTimedButtonVariant = useCssVariable(\n    'legacyTimedButton.variant',\n    (c) => c?.legacyTimedButton?.variant,\n    'invisible',\n  );\n\n  useEffect(() => {\n    setTime(initialTime);\n  }, [initialTime]);\n\n  const minutes = Math.floor(time / 60);\n  const seconds = time % 60;\n  const enabled = time <= 0;\n\n  useEffect(() => {\n    if (time > 0) {\n      const countdown = setTimeout(() => {\n        if (time > 0) {\n          setTime(time - 1);\n        }\n      }, 1000);\n\n      return () => clearTimeout(countdown);\n    }\n\n    return undefined;\n  });\n\n  return (\n    <ResendCodeButton\n      variant={legacyTimedButtonVariant}\n      size=\"large\"\n      fullWidth\n      onClick={onClick}\n      {...props}\n      disabled={!enabled}\n      data-test-id={testId}\n      data-chromatic=\"ignore\"\n      customizationTags={customizationTags}\n    >\n      {enabled\n        ? enabledText\n        : disabledTextFn({\n            seconds: padLeft(seconds),\n            minutes: padLeft(minutes),\n            total: time,\n          })}\n    </ResendCodeButton>\n  );\n};\n","import { PropsWithChildren } from 'react';\n\nexport const NoTranslateSpan = ({ children, ...props }: PropsWithChildren) => (\n  <span translate=\"no\" {...props}>\n    {children}\n  </span>\n);\n","import { getCountry } from '@finmid/countries';\n\nexport function detectCountry() {\n  const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;\n\n  if (timezone === '' || !timezone) {\n    return null;\n  }\n\n  const countryCode = timezones[timezone];\n  return countryCode ? getCountry(countryCode) : null;\n}\n\nconst timezones: Record<string, string> = {\n  'America/Anchorage': 'US',\n  'America/Araguaina': 'BR',\n  'America/Bahia': 'BR',\n  'America/Bahia_Banderas': 'MX',\n  'America/Belem': 'BR',\n  'America/Boa_Vista': 'BR',\n  'America/Boise': 'US',\n  'America/Campo_Grande': 'BR',\n  'America/Cancun': 'MX',\n  'America/Chicago': 'US',\n  'America/Chihuahua': 'MX',\n  'America/Cuiaba': 'BR',\n  'America/Denver': 'US',\n  'America/Detroit': 'US',\n  'America/Eirunepe': 'BR',\n  'America/Fortaleza': 'BR',\n  'America/Hermosillo': 'MX',\n  'America/Indiana/Indianapolis': 'US',\n  'America/Indiana/Knox': 'US',\n  'America/Indiana/Marengo': 'US',\n  'America/Indiana/Petersburg': 'US',\n  'America/Indiana/Tell_City': 'US',\n  'America/Indiana/Vevay': 'US',\n  'America/Indiana/Vincennes': 'US',\n  'America/Indiana/Winamac': 'US',\n  'America/Juneau': 'US',\n  'America/Kentucky/Louisville': 'US',\n  'America/Kentucky/Monticello': 'US',\n  'America/Los_Angeles': 'US',\n  'America/Maceio': 'BR',\n  'America/Manaus': 'BR',\n  'America/Matamoros': 'MX',\n  'America/Mazatlan': 'MX',\n  'America/Menominee': 'US',\n  'America/Merida': 'MX',\n  'America/Metlakatla': 'US',\n  'America/Mexico_City': 'MX',\n  'America/Monterrey': 'MX',\n  'America/New_York': 'US',\n  'America/Nome': 'US',\n  'America/Noronha': 'BR',\n  'America/North_Dakota/Beulah': 'US',\n  'America/North_Dakota/Center': 'US',\n  'America/North_Dakota/New_Salem': 'US',\n  'America/Ojinaga': 'MX',\n  'America/Phoenix': 'US',\n  'America/Porto_Velho': 'BR',\n  'America/Recife': 'BR',\n  'America/Rio_Branco': 'BR',\n  'America/Santarem': 'BR',\n  'America/Sao_Paulo': 'BR',\n  'America/Sitka': 'US',\n  'America/Tijuana': 'MX',\n  'America/Yakutat': 'US',\n  'Antarctica/Macquarie': 'AU',\n  'Asia/Anadyr': 'RU',\n  'Asia/Bangkok': 'TH',\n  'Asia/Barnaul': 'RU',\n  'Asia/Chita': 'RU',\n  'Asia/Dhaka': 'BD',\n  'Asia/Ho_Chi_Minh': 'VN',\n  'Asia/Irkutsk': 'RU',\n  'Asia/Jakarta': 'ID',\n  'Asia/Jayapura': 'ID',\n  'Asia/Kamchatka': 'RU',\n  'Asia/Karachi': 'PK',\n  'Asia/Khandyga': 'RU',\n  'Asia/Kolkata': 'IN',\n  'Asia/Krasnoyarsk': 'RU',\n  'Asia/Magadan': 'RU',\n  'Asia/Makassar': 'ID',\n  'Asia/Manila': 'PH',\n  'Asia/Novokuznetsk': 'RU',\n  'Asia/Novosibirsk': 'RU',\n  'Asia/Omsk': 'RU',\n  'Asia/Pontianak': 'ID',\n  'Asia/Sakhalin': 'RU',\n  'Asia/Seoul': 'KR',\n  'Asia/Shanghai': 'CN',\n  'Asia/Srednekolymsk': 'RU',\n  'Asia/Tokyo': 'JP',\n  'Asia/Tomsk': 'RU',\n  'Asia/Urumqi': 'CN',\n  'Asia/Ust-Nera': 'RU',\n  'Asia/Vladivostok': 'RU',\n  'Asia/Yakutsk': 'RU',\n  'Asia/Yekaterinburg': 'RU',\n  'Atlantic/Azores': 'PT',\n  'Atlantic/Canary': 'ES',\n  'Atlantic/Madeira': 'PT',\n  'Australia/Adelaide': 'AU',\n  'Australia/Brisbane': 'AU',\n  'Australia/Broken_Hill': 'AU',\n  'Australia/Darwin': 'AU',\n  'Australia/Eucla': 'AU',\n  'Australia/Hobart': 'AU',\n  'Australia/Lindeman': 'AU',\n  'Australia/Lord_Howe': 'AU',\n  'Australia/Melbourne': 'AU',\n  'Australia/Perth': 'AU',\n  'Australia/Sydney': 'AU',\n  'Europe/Amsterdam': 'NL',\n  'Europe/Astrakhan': 'RU',\n  'Europe/Athens': 'GR',\n  'Europe/Belfast': 'GB',\n  'Europe/Belgrade': 'RS',\n  'Europe/Berlin': 'DE',\n  'Europe/Bratislava': 'SK',\n  'Europe/Brussels': 'BE',\n  'Europe/Budapest': 'HU',\n  'Europe/Busingen': 'DE',\n  'Europe/Chisinau': 'MD',\n  'Europe/Copenhagen': 'DK',\n  'Europe/Dublin': 'IE',\n  'Europe/Helsinki': 'FI',\n  'Europe/Kaliningrad': 'RU',\n  'Europe/Kiev': 'UA',\n  'Europe/Kirov': 'RU',\n  'Europe/Lisbon': 'PT',\n  'Europe/Ljubljana': 'SI',\n  'Europe/London': 'GB',\n  'Europe/Madrid': 'ES',\n  'Europe/Minsk': 'BY',\n  'Europe/Moscow': 'RU',\n  'Europe/Oslo': 'NO',\n  'Europe/Paris': 'FR',\n  'Europe/Prague': 'CZ',\n  'Europe/Rome': 'IT',\n  'Europe/Samara': 'RU',\n  'Europe/Sarajevo': 'BA',\n  'Europe/Saratov': 'RU',\n  'Europe/Simferopol': 'RU',\n  'Europe/Sofia': 'BG',\n  'Europe/Stockholm': 'SE',\n  'Europe/Ulyanovsk': 'RU',\n  'Europe/Uzhgorod': 'UA',\n  'Europe/Vienna': 'AT',\n  'Europe/Vilnius': 'LT',\n  'Europe/Volgograd': 'RU',\n  'Europe/Warsaw': 'PL',\n  'Europe/Zagreb': 'HR',\n  'Europe/Zaporozhye': 'UA',\n  'Europe/Zurich': 'CH',\n  GB: 'GB',\n  'GB-Eire': 'GB',\n  'Pacific/Honolulu': 'US',\n  'US/Arizona': 'US',\n};\n","import 'react-international-phone/style.css';\n\nimport {\n  InputAdornment,\n  MenuItem,\n  Select,\n  TextField,\n  Typography,\n} from '@mui/material';\nimport { TextFieldProps } from '@mui/material/TextField/TextField';\nimport React, { ChangeEvent } from 'react';\nimport {\n  CountryData,\n  CountryIso2,\n  defaultCountries,\n  FlagImage,\n  parseCountry,\n  usePhoneInput,\n} from 'react-international-phone';\n\nimport { detectCountry } from './detect-country';\n\nconst countries: CountryData[] = defaultCountries.map((country) => {\n  const { iso2, name, dialCode } = parseCountry(country);\n\n  if (iso2 === 'fi') {\n    const newCountryAr: CountryData = [name, iso2, dialCode, '.. ... .. ...'];\n    return newCountryAr;\n  } else {\n    return country;\n  }\n});\n\ninterface Props extends TextFieldProps<'outlined'> {\n  testId?: string;\n  country?: CountryIso2;\n}\n\nexport const PhoneWithCountryInput = React.forwardRef(\n  (\n    { name, value, onChange, onBlur, testId, ...restProps }: Props,\n    ref: React.ForwardedRef<HTMLDivElement>,\n  ) => {\n    const {\n      inputValue,\n      handlePhoneValueChange,\n      inputRef,\n      country,\n      setCountry,\n    } = usePhoneInput({\n      defaultCountry: detectCountry()?.iso2code?.toLowerCase(),\n      value: typeof value === 'string' ? value : '',\n      countries,\n      onChange: (data) => {\n        onChange?.({\n          target: { name, value: data.phone },\n        } as unknown as ChangeEvent<HTMLTextAreaElement | HTMLInputElement>);\n      },\n    });\n\n    let val = inputValue;\n    // Override formatted value when it's masked\n    if (typeof value === 'string' && value?.startsWith('**')) {\n      val = value;\n    }\n\n    return (\n      <TextField\n        ref={ref}\n        value={val}\n        onChange={handlePhoneValueChange}\n        onBlur={handlePhoneValueChange}\n        type=\"tel\"\n        inputRef={inputRef}\n        name={name}\n        {...restProps}\n        slotProps={{\n          input: {\n            inputProps: {\n              'data-test-id': testId,\n            },\n            startAdornment: (\n              <InputAdornment\n                position=\"start\"\n                style={{ marginRight: '2px', marginLeft: '-8px' }}\n              >\n                <Select\n                  MenuProps={{\n                    style: {\n                      height: '300px',\n                      width: '360px',\n                      top: '10px',\n                      left: '-34px',\n                    },\n                    transformOrigin: {\n                      vertical: 'top',\n                      horizontal: 'left',\n                    },\n                  }}\n                  sx={{\n                    width: 'max-content',\n                    // Remove default outline (display only on focus)\n                    fieldset: {\n                      display: 'none',\n                    },\n                    '&.Mui-focused:has(div[aria-expanded=\"false\"])': {\n                      fieldset: {\n                        display: 'block',\n                      },\n                    },\n                    // Update default spacing\n                    '.MuiSelect-select': {\n                      padding: '8px',\n                      paddingRight: '24px !important',\n                    },\n                    svg: {\n                      right: 0,\n                    },\n                  }}\n                  value={country.iso2}\n                  disabled={restProps.disabled}\n                  onChange={(e) => setCountry(e.target.value as CountryIso2)}\n                  renderValue={(value) => (\n                    <FlagImage\n                      iso2={restProps.country ?? value}\n                      style={{ display: 'flex' }}\n                    />\n                  )}\n                >\n                  {defaultCountries.map((c) => {\n                    const country = parseCountry(c);\n                    return (\n                      <MenuItem key={country.iso2} value={country.iso2}>\n                        <FlagImage\n                          iso2={country.iso2}\n                          style={{ marginRight: '8px' }}\n                        />\n                        <Typography marginRight=\"8px\">\n                          {country.name}\n                        </Typography>\n                        <Typography color=\"gray\">\n                          +{country.dialCode}\n                        </Typography>\n                      </MenuItem>\n                    );\n                  })}\n                </Select>\n              </InputAdornment>\n            ),\n          },\n        }}\n      />\n    );\n  },\n);\n","import styled from '@emotion/styled';\nimport {\n  Accordion,\n  AccordionDetails,\n  AccordionSummary,\n  AccordionSummaryProps,\n  accordionClasses,\n  accordionSummaryClasses,\n} from '@mui/material';\n\nimport { Icons } from '../Icons';\nimport { customizeStyles } from '../customizeStyles';\n\nexport const QuestionAccordion = styled(Accordion)<{ isMyPos?: boolean }>(\n  ({ theme: { vars }, theme, isMyPos }) => ({\n    [`&.${accordionClasses.root}`]: {\n      borderBottom: `1px solid ${vars.components?.variables.colors?.grey300}`,\n      padding: vars.components?.variables.spacings.md,\n      width: '100%',\n\n      boxShadow: 'none',\n      margin: 0,\n\n      '&::before': {\n        display: 'none',\n      },\n\n      '&:last-of-type': {\n        border: 0,\n      },\n\n      ...(isMyPos && {\n        padding: '0 16px',\n      }),\n\n      ...customizeStyles(theme, (c) => c?.faq?.question?.accordion),\n    },\n  }),\n);\n\nexport const QuestionTitle = styled(\n  (props: AccordionSummaryProps & { isMyPos?: boolean }) => (\n    <AccordionSummary {...props} expandIcon={<Icons.ChevronRightIcon />} />\n  ),\n)<{ isMyPos?: boolean }>(({ theme, isMyPos }) => ({\n  fontFamily: theme.vars.components?.variables.typography?.desktop.family.body,\n\n  fontSize: theme.vars.components?.variables.typography?.desktop.size.md,\n  fontWeight:\n    theme.vars.components?.variables.typography?.desktop.weight?.strong,\n  lineHeight:\n    theme.vars.components?.variables.typography?.desktop.lineHeight.md,\n\n  display: 'flex',\n  flexDirection: 'row-reverse',\n  alignItems: 'center',\n  gap: theme.vars.components?.variables.spacings.sm,\n\n  ...(isMyPos && {\n    fontSize: '14px',\n    lineHeight: '22.4px',\n    flexDirection: 'row',\n  }),\n\n  [theme.breakpoints.only('mobile')]: {\n    fontSize: theme.vars.components?.variables.typography?.mobile.size.md,\n    fontWeight:\n      theme.vars.components?.variables.typography?.mobile.weight?.strong,\n    lineHeight:\n      theme.vars.components?.variables.typography?.mobile.lineHeight.md,\n\n    ...(isMyPos && {\n      fontSize: '14px',\n      lineHeight: '22.4px',\n    }),\n  },\n\n  [`&.${accordionSummaryClasses.root}`]: {\n    padding: 0,\n    minHeight: 'auto',\n  },\n\n  [`& > .${accordionSummaryClasses.content}`]: {\n    margin: '0',\n\n    [`&.${accordionSummaryClasses.expanded}`]: {\n      margin: '0',\n    },\n  },\n\n  [`& .${accordionSummaryClasses.expandIconWrapper}`]: {\n    alignSelf: 'flex-start',\n    marginTop: 2,\n\n    '& svg': {\n      fill: theme.vars.components?.variables.colors?.grey900,\n    },\n\n    ...customizeStyles(theme, (c) => c?.faq?.question?.summaryArrow?.default),\n\n    [`&.${accordionSummaryClasses.expanded}`]: {\n      transform: 'rotate(90deg)',\n\n      ...customizeStyles(\n        theme,\n        (c) => c?.faq?.question?.summaryArrow?.expanded,\n      ),\n    },\n  },\n  ...customizeStyles(theme, (c) => c?.faq?.question?.summary),\n}));\n\nexport const QuestionContent = styled(AccordionDetails)<{ isMyPos?: boolean }>(\n  ({ theme, isMyPos }) => ({\n    fontSize: theme.vars.components?.variables.typography?.desktop.size.sm,\n    lineHeight:\n      theme.vars.components?.variables.typography?.desktop.lineHeight?.sm,\n    padding: `${theme.vars.components?.variables.spacings.sm} 0 0 ${theme.vars.components?.variables.spacings.xl}`,\n\n    ...(isMyPos && {\n      fontSize: '14px',\n      lineHeight: '22.4px',\n      padding: `${theme.vars.components?.variables.spacings.sm} 0 0 0`,\n    }),\n\n    [theme.breakpoints.only('mobile')]: {\n      fontSize: theme.vars.components?.variables.typography?.mobile.size.sm,\n      lineHeight:\n        theme.vars.components?.variables.typography?.mobile.lineHeight?.sm,\n\n      ...(isMyPos && {\n        fontSize: '14px',\n        lineHeight: '22.4px',\n      }),\n    },\n\n    ...customizeStyles(theme, (c) => c?.faq?.question?.details),\n  }),\n);\n","import { TFunction } from 'i18next';\nimport { FunctionComponent } from 'react';\nimport { Trans } from 'react-i18next';\n\nimport {\n  QuestionAccordion,\n  QuestionContent,\n  QuestionTitle,\n} from './QuestionList.styled';\n\nexport interface Question {\n  title: string;\n  content: string;\n  category?: string[];\n  top?: boolean;\n}\n\ninterface Props {\n  questions: Question[];\n  isMyPos?: boolean;\n}\n\nexport const QuestionList: FunctionComponent<Props> = ({\n  questions,\n  isMyPos,\n}) => {\n  return (\n    <>\n      {questions.map(({ title, content }) => (\n        <QuestionAccordion\n          key={title}\n          data-test-id=\"question-accordion\"\n          isMyPos={isMyPos}\n        >\n          <QuestionTitle isMyPos={isMyPos}>{title}</QuestionTitle>\n          <QuestionContent isMyPos={isMyPos}>\n            <Trans\n              // custom t function that simply returns the key itself since \"content\" is already translated\n              t={((s: string) => s) as TFunction}\n              i18nKey={content}\n              components={{\n                ul: <ul />,\n                ol: <ol />,\n                li: <li />,\n                bold: <strong />,\n              }}\n            />\n          </QuestionContent>\n        </QuestionAccordion>\n      ))}\n    </>\n  );\n};\n","// Based on https://github.com/drac94/react-auth-code-input\nimport React, {\n  useRef,\n  useEffect,\n  useImperativeHandle,\n  forwardRef,\n} from 'react';\n\nconst allowedCharactersValues = ['alpha', 'numeric', 'alphanumeric'] as const;\n\nexport type AuthCodeProps = {\n  allowedCharacters?: (typeof allowedCharactersValues)[number];\n  ariaLabel?: string;\n  autoFocus?: boolean;\n  containerClassName?: string;\n  disabled?: boolean;\n  inputClassName?: string;\n  isPassword?: boolean;\n  length?: number;\n  placeholder?: string;\n  onChange: (res: string) => void;\n};\n\ntype InputMode = 'text' | 'numeric';\n\ntype InputType = 'text' | 'tel' | 'password';\n\ntype InputProps = {\n  type: InputType;\n  inputMode: InputMode;\n  pattern: string;\n  min?: string;\n  max?: string;\n};\n\nexport type AuthCodeRef = {\n  focus: () => void;\n  clear: () => void;\n};\n\nconst propsMap: { [key: string]: InputProps } = {\n  alpha: {\n    type: 'text',\n    inputMode: 'text',\n    pattern: '[a-zA-Z]{1}',\n  },\n\n  alphanumeric: {\n    type: 'text',\n    inputMode: 'text',\n    pattern: '[a-zA-Z0-9]{1}',\n  },\n\n  numeric: {\n    type: 'tel',\n    inputMode: 'numeric',\n    pattern: '[0-9]{1}',\n    min: '0',\n    max: '9',\n  },\n};\n\nconst AuthCode = forwardRef<AuthCodeRef, AuthCodeProps>(\n  (\n    {\n      allowedCharacters = 'alphanumeric',\n      ariaLabel,\n      autoFocus = true,\n      containerClassName,\n      disabled,\n      inputClassName,\n      isPassword = false,\n      length = 6,\n      placeholder,\n      onChange,\n    },\n    ref,\n  ) => {\n    if (isNaN(length) || length < 1) {\n      throw new Error('Length should be a number and greater than 0');\n    }\n\n    if (!allowedCharactersValues.some((value) => value === allowedCharacters)) {\n      throw new Error(\n        'Invalid value for allowedCharacters. Use alpha, numeric, or alphanumeric',\n      );\n    }\n\n    const inputsRef = useRef<Array<HTMLInputElement>>([]);\n    const inputProps = propsMap[allowedCharacters];\n\n    useImperativeHandle(ref, () => ({\n      focus: () => {\n        if (inputsRef.current) {\n          inputsRef.current[0].focus();\n        }\n      },\n      clear: () => {\n        if (inputsRef.current) {\n          for (let i = 0; i < inputsRef.current.length; i++) {\n            inputsRef.current[i].value = '';\n          }\n          inputsRef.current[0].focus();\n        }\n        sendResult();\n      },\n    }));\n\n    useEffect(() => {\n      if (autoFocus) {\n        inputsRef.current[0].focus();\n      }\n\n      inputsRef.current[0].addEventListener('input', (e) => {\n        if ('data' in e && typeof e.data === 'string') {\n          const input = e.data;\n\n          if (input.length > 1) {\n            // This happends when iOS injects 2FA code into the first OTP field\n            inputsRef.current[0].value = '';\n            handlePaste(input);\n            e.preventDefault();\n          }\n        }\n      });\n      // eslint-disable-next-line react-hooks/exhaustive-deps\n    }, []);\n\n    const sendResult = () => {\n      const res = inputsRef.current.map((input) => input.value).join('');\n      onChange && onChange(res);\n    };\n\n    const handleOnChange = (e: React.ChangeEvent<HTMLInputElement>) => {\n      const {\n        target: { value, nextElementSibling },\n      } = e;\n      if (value.length > 1) {\n        e.target.value = value.charAt(0);\n        if (nextElementSibling !== null) {\n          (nextElementSibling as HTMLInputElement).focus();\n        }\n      } else {\n        if (value.match(inputProps.pattern)) {\n          if (nextElementSibling !== null) {\n            (nextElementSibling as HTMLInputElement).focus();\n          }\n        } else {\n          e.target.value = '';\n        }\n      }\n      sendResult();\n    };\n\n    const handleOnKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {\n      const { key } = e;\n      const target = e.target as HTMLInputElement;\n      if (key === 'Backspace') {\n        if (target.value === '') {\n          if (target.previousElementSibling !== null) {\n            const t = target.previousElementSibling as HTMLInputElement;\n            t.value = '';\n            t.focus();\n            e.preventDefault();\n          }\n        } else {\n          target.value = '';\n        }\n        sendResult();\n      }\n    };\n\n    const handleOnFocus = (e: React.FocusEvent<HTMLInputElement>) => {\n      e.target.select();\n    };\n\n    const handlePaste = (pastedValue: string) => {\n      let currentInput = 0;\n\n      for (let i = 0; i < pastedValue.length; i++) {\n        const pastedCharacter = pastedValue.charAt(i);\n        const currentValue = inputsRef.current[currentInput].value;\n\n        if (pastedCharacter.match(inputProps.pattern)) {\n          if (!currentValue) {\n            inputsRef.current[currentInput].value = pastedCharacter;\n            if (inputsRef.current[currentInput].nextElementSibling !== null) {\n              (\n                inputsRef.current[currentInput]\n                  .nextElementSibling as HTMLInputElement\n              ).focus();\n            }\n            currentInput++;\n          }\n        }\n      }\n\n      sendResult();\n    };\n\n    const handleOnPaste = (e: React.ClipboardEvent<HTMLInputElement>) => {\n      const pastedValue = e.clipboardData.getData('Text');\n\n      handlePaste(pastedValue);\n\n      e.preventDefault();\n    };\n\n    const inputs = [];\n    for (let i = 0; i < length; i++) {\n      inputs.push(\n        <input\n          key={i}\n          onChange={handleOnChange}\n          onKeyDown={handleOnKeyDown}\n          onFocus={handleOnFocus}\n          onPaste={handleOnPaste}\n          {...inputProps}\n          type={isPassword ? 'password' : inputProps.type}\n          ref={(el: HTMLInputElement) => {\n            inputsRef.current[i] = el;\n          }}\n          maxLength={i === 0 ? 6 : 1}\n          className={inputClassName}\n          autoComplete={i === 0 ? 'one-time-code' : 'off'}\n          aria-label={\n            ariaLabel\n              ? `${ariaLabel}. Character ${i + 1}.`\n              : `Character ${i + 1}.`\n          }\n          disabled={disabled}\n          placeholder={placeholder}\n          data-lpignore=\"true\"\n          data-bwignore=\"true\"\n        />,\n      );\n    }\n\n    return <div className={containerClassName}>{inputs}</div>;\n  },\n);\n\nexport default AuthCode;\n","import styled from '@emotion/styled';\nimport { Box } from '@mui/material';\n\nimport { Flex } from '../Flex';\n\nexport const ReferralCodeBox = styled(Box)(\n  ({\n    theme: {\n      vars: { components },\n      breakpoints,\n    },\n  }) => ({\n    display: 'flex',\n    gap: components?.variables.spacings.lg,\n    backgroundColor: components?.variables.colors.white,\n    padding: components?.variables.spacings.md,\n    borderRadius: components?.variables.radius.md,\n    border: `1px solid ${components?.variables.colors.grey300}`,\n\n    [breakpoints.down('desktop')]: {\n      flexDirection: 'column',\n    },\n  }),\n);\n\nexport const RedeemCircle = styled(Flex)(\n  ({\n    theme: {\n      vars: { components },\n    },\n  }) => ({\n    flexShrink: 0,\n    width: 40,\n    height: 40,\n    background: components?.variables.colors.primaryDefault,\n    color: components?.variables.colors.white,\n    borderRadius: '50%',\n  }),\n);\n","import { useTheme } from '@emotion/react';\nimport styled from '@emotion/styled';\n\nimport { Flex } from '../Flex';\nimport { Icons } from '../Icons';\nimport { customizeStyles } from '../customizeStyles';\n\nconst ICON_DESKTOP_SIZE = '96px';\nconst ICON_MOBILE_SIZE = '64px';\n\nexport const RejectedImage = styled('div')<{ src: string }>(\n  ({ theme: { breakpoints, vars }, src }) => ({\n    backgroundImage: `url('${src}')`,\n    width: ICON_DESKTOP_SIZE,\n    height: ICON_DESKTOP_SIZE,\n    backgroundPosition: 'center',\n    backgroundRepeat: 'no-repeat',\n    backgroundSize: 'contain',\n    marginBlock: vars.components?.variables.spacings.lg,\n\n    [breakpoints.down('desktop')]: {\n      width: ICON_MOBILE_SIZE,\n      height: ICON_MOBILE_SIZE,\n    },\n\n    ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.rejected?.image),\n  }),\n);\n\nconst IconWrapper = styled(Flex)(({ theme: { breakpoints, vars } }) => ({\n  marginBlock: vars.components?.variables.spacings.lg,\n\n  '& svg': {\n    width: ICON_DESKTOP_SIZE,\n    height: ICON_DESKTOP_SIZE,\n  },\n\n  [breakpoints.down('desktop')]: {\n    '& svg': {\n      width: ICON_MOBILE_SIZE,\n      height: ICON_MOBILE_SIZE,\n    },\n  },\n\n  ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.rejected?.image),\n}));\n\nexport const NoCodeRejectedIcon = () => {\n  const { vars } = useTheme();\n  return (\n    <IconWrapper>\n      <Icons.ErrorIcon\n        style={{ color: vars.components?.variables.colors.error }}\n      />\n    </IconWrapper>\n  );\n};\n","import styled from '@emotion/styled';\nimport { CSSProperties, PropsWithChildren, ReactNode } from 'react';\n\nimport { Typography } from './Typography';\n\nconst MaybeSpanWithTestId = ({\n  testId,\n  children,\n}: {\n  testId?: string;\n  children: ReactNode;\n}) => (testId ? <span data-test-id={testId}>{children}</span> : children);\n\nexport const SectionH1 = styled(\n  ({\n    children,\n    dataTestId,\n    ...props\n  }: PropsWithChildren<{ dataTestId?: string }>) => (\n    <Typography\n      size=\"xl\"\n      family=\"title\"\n      weight=\"strong\"\n      color=\"grey900\"\n      component=\"h1\"\n      {...props}\n    >\n      <MaybeSpanWithTestId testId={dataTestId}>{children}</MaybeSpanWithTestId>\n    </Typography>\n  ),\n)(({ theme: { vars, breakpoints } }) => ({\n  marginTop: vars.components?.variables.spacings.sm,\n  marginBottom: 0,\n\n  [breakpoints.up('desktop')]: {\n    ...(vars.components?.typography?.h1 as CSSProperties),\n  },\n\n  ...(vars.components?.typography?.h1 as CSSProperties),\n}));\n","import styled from '@emotion/styled';\nimport { CSSProperties } from 'react';\n\nexport const SectionH2 = styled('h2')(({ theme: { vars } }) => ({\n  fontSize: 18,\n  lineHeight: 1.4,\n  marginBottom: 8,\n  marginTop: 8,\n\n  ...(vars.components?.typography?.h2 as CSSProperties),\n}));\n","import styled from '@emotion/styled';\nimport {\n  AccordionSummary,\n  AccordionSummaryProps,\n  accordionSummaryClasses,\n} from '@mui/material';\n\nimport { Icons } from '../Icons';\nimport { customizeStyles } from '../customizeStyles';\n\nexport const AccordionTitle = styled(\n  ({ expandIcon, ...props }: AccordionSummaryProps) => (\n    <AccordionSummary\n      {...props}\n      expandIcon={\n        expandIcon === null\n          ? undefined\n          : expandIcon ?? <Icons.ChevronRightIcon />\n      }\n    />\n  ),\n)(({ theme }) => ({\n  fontFamily: theme.vars.components?.variables.typography?.desktop.family.body,\n\n  fontSize: theme.vars.components?.variables.typography?.desktop.size.md,\n  fontWeight:\n    theme.vars.components?.variables.typography?.desktop.weight?.strong,\n  lineHeight:\n    theme.vars.components?.variables.typography?.desktop.lineHeight.md,\n\n  display: 'flex',\n  alignItems: 'center',\n  gap: theme.vars.components?.variables.spacings.xl,\n\n  [theme.breakpoints.only('mobile')]: {\n    fontSize: theme.vars.components?.variables.typography?.mobile.size.md,\n    fontWeight:\n      theme.vars.components?.variables.typography?.mobile.weight?.strong,\n    lineHeight:\n      theme.vars.components?.variables.typography?.mobile.lineHeight.md,\n  },\n\n  [`&.${accordionSummaryClasses.root}`]: {\n    padding: 0,\n    minHeight: 'auto',\n  },\n\n  [`& > .${accordionSummaryClasses.content}`]: {\n    margin: '0',\n\n    [`&.${accordionSummaryClasses.expanded}`]: {\n      margin: '0',\n    },\n  },\n\n  [`& .${accordionSummaryClasses.expandIconWrapper}`]: {\n    transform: 'rotate(90deg)',\n\n    alignSelf: 'flex-start',\n    marginTop: 2,\n\n    '& svg': {\n      fill: theme.vars.components?.variables.colors?.grey900,\n    },\n\n    ...customizeStyles(theme, (c) => c?.dropdown?.summaryArrow?.default),\n\n    [`&.${accordionSummaryClasses.expanded}`]: {\n      transform: 'rotate(-90deg)',\n\n      ...customizeStyles(theme, (c) => c?.dropdown?.summaryArrow?.expanded),\n    },\n  },\n  ...customizeStyles(theme, (c) => c?.dropdown?.summary),\n}));\n","import { styled } from '@mui/material';\n\nimport { Typography } from '../Typography';\n\nexport const SepaDisclaimer = styled(Typography)(({ theme: { vars } }) => ({\n  padding: vars.components?.variables.spacings.sm,\n  background: vars.components?.variables.colors.grey100,\n  borderRadius: vars.components?.variables.radius.sm,\n}));\n","import { Box, styled } from '@mui/material';\n\nconst SepaLogoContainer = styled(Box)(({ theme: { vars } }) => ({\n  borderRadius: vars.components?.variables.radius.sm,\n  border: `1px solid ${vars.components?.variables.colors.grey300}`,\n  background: vars.components?.variables.colors.white,\n\n  lineHeight: '0',\n\n  padding: `8px 12px`,\n}));\n\nexport const SepaLogo = () => {\n  return (\n    <SepaLogoContainer>\n      <Box\n        component=\"img\"\n        src={`${import.meta.env.BASE_URL}sepa.jpg`}\n        sx={{\n          width: 57,\n          height: 21,\n        }}\n      />\n    </SepaLogoContainer>\n  );\n};\n","import { friendlyFormatIBAN } from 'ibantools';\nimport { FunctionComponent, useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { Accordion } from '../Accordion';\nimport { Flex } from '../Flex';\nimport { Icons } from '../Icons';\nimport { Typography } from '../Typography';\n\nimport { AccordionTitle } from './AccordionTitle';\nimport { SepaDisclaimer } from './SepaDisclaimer';\nimport { SepaLogo } from './SepaLogo';\n\ntype SepaAccordionProps = {\n  iban: string;\n  subtitle: string;\n  description: string;\n  showLogo?: boolean;\n  showIbanLastFour?: boolean;\n  onClick: () => void;\n};\n\nexport const SepaAccordion: FunctionComponent<SepaAccordionProps> = ({\n  iban,\n  subtitle,\n  description,\n  showLogo = true,\n  showIbanLastFour,\n  onClick,\n}) => {\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: `features.bankConnection`,\n  });\n  const ibanLastFour = friendlyFormatIBAN(iban ?? 'XXXX')?.slice(-4);\n  const [expanded, setExpanded] = useState(false);\n\n  const handleClick = () => {\n    setExpanded((prev) => !prev);\n    onClick();\n  };\n\n  return (\n    <Accordion.Root expanded={expanded}>\n      <AccordionTitle onClick={handleClick} expandIcon={null}>\n        <Flex flexDirection=\"row\" alignItems=\"flex-start\" gap=\"xl\" width=\"100%\">\n          {showLogo ? <SepaLogo /> : null}\n          <Flex\n            flexDirection={'column'}\n            gap=\"lg\"\n            width=\"100%\"\n            alignItems=\"flex-start\"\n          >\n            <Flex flexDirection=\"column\" gap=\"sm\" alignItems=\"flex-start\">\n              <Flex flexDirection=\"row\" alignItems=\"center\" gap=\"sm\">\n                <Typography size=\"md\" weight=\"strong\">\n                  {t('sepaDirectDebit', 'SEPA Direct Debit')}\n                </Typography>\n                <Icons.ChevronRightIcon\n                  style={{\n                    transform: expanded ? 'rotate(-90deg)' : 'rotate(90deg)',\n                    transition: 'transform 0.2s',\n                  }}\n                />\n              </Flex>\n              <Typography size=\"sm\">{subtitle}</Typography>\n            </Flex>\n            {showIbanLastFour && (\n              <Flex\n                flexDirection=\"row\"\n                gap=\"sm\"\n                justifyContent=\"space-between\"\n                width=\"100%\"\n              >\n                <Typography size=\"md\" weight=\"strong\">\n                  {t('ibanLabel', 'IBAN ending on')}\n                </Typography>\n                <Typography size=\"md\" weight=\"strong\">\n                  {ibanLastFour}\n                </Typography>\n              </Flex>\n            )}\n          </Flex>\n        </Flex>\n      </AccordionTitle>\n      <Accordion.Content>\n        <SepaDisclaimer size=\"xs\">{description}</SepaDisclaimer>\n      </Accordion.Content>\n    </Accordion.Root>\n  );\n};\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport {\n  Slider as MaterialSlider,\n  SliderProps as MaterialSliderProps,\n  SliderThumb,\n} from '@mui/material';\n\nimport { customizeStyles } from '../customizeStyles';\n\ntype SliderCustomProps = {\n  thickness?: number;\n  extendRail?: boolean;\n};\n\ntype SliderProps = MaterialSliderProps & SliderCustomProps;\n\nconst StyledSlider = styled(MaterialSlider, {\n  shouldForwardProp: (prop) => !['thickness', 'extendRail'].includes(prop),\n})<SliderCustomProps>`\n  ${({ theme, thickness = 4, extendRail }) => css`\n    &.MuiSlider-root {\n      color: ${theme.vars.components?.variables.colors.grey900};\n      height: 3px;\n      padding: 13px 0;\n    }\n\n    & .MuiSlider-track {\n      height: ${thickness}px;\n      border-top-left-radius: 50px;\n      border-bottom-left-radius: 50px;\n    }\n\n    & .MuiSlider-rail {\n      border-radius: 50px;\n      color: ${theme.vars.components?.variables.colors?.grey300};\n      opacity: 1;\n      height: ${thickness}px;\n      width: ${extendRail ? 'calc(100% + 24px)' : '100%'};\n    }\n\n    & .MuiSlider-thumb {\n      height: 18px;\n      width: 18px;\n      background-color: ${theme.vars.components?.variables.colors?.grey900};\n      border: 2px solid ${theme.vars.components?.variables.colors?.white};\n\n      &.Mui-disabled {\n        background-color: ${theme.vars.components?.variables.colors?.grey300};\n      }\n    }\n\n    & .MuiSlider-valueLabel {\n      padding: ${`${theme.vars.components?.variables.spacings?.xs} ${theme.vars.components?.variables.spacings?.sm}`};\n      border-radius: ${theme.vars.components?.variables.radius?.sm};\n      border: 1px solid ${theme.vars.components?.variables.colors?.grey300};\n      background: ${theme.vars.components?.variables.colors?.white};\n      color: ${theme.vars.components?.variables.colors?.grey900};\n      font-family: ${\n        theme.vars.components?.variables.typography?.desktop.family?.title\n      };\n      font-weight: ${\n        theme.vars.components?.variables.typography?.desktop.weight?.strong\n      };\n      font-size: ${\n        theme.vars.components?.variables.typography?.desktop.size.xl\n      };\n      line-height: ${\n        theme.vars.components?.variables.typography?.desktop.lineHeight.xl\n      };\n\n      /* label arrow */\n      &::before {\n        display: none;\n      }\n\n      ${theme.breakpoints.down('desktop')} {\n        font-size: ${\n          theme.vars.components?.variables.typography?.mobile.size.xl\n        };\n        line-height: ${\n          theme.vars.components?.variables.typography?.mobile.lineHeight.xl\n        };\n      }\n    }\n\n    & .MuiSlider-mark {\n      display: none;\n    }\n\n    & .MuiSlider-markLabel {\n      font-size: ${\n        theme.vars.components?.variables.typography?.desktop.size?.sm\n      };inde\n    }\n  `}\n`;\n\nconst CustomizedSlider = styled(StyledSlider)(\n  ({ theme: { vars, breakpoints } }) => ({\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.overview?.flexibleRemittanceRate?.calculator?.slider,\n    ),\n  }),\n);\n\ntype ThumbProps = React.HTMLAttributes<unknown>;\n\nconst Thumb = (props: ThumbProps) => {\n  const { children, ...other } = props;\n\n  return <SliderThumb {...other}>{children}</SliderThumb>;\n};\n\nexport const Slider = (props: SliderProps) => (\n  <CustomizedSlider\n    slots={{\n      thumb: Thumb,\n    }}\n    {...props}\n  />\n);\n","import styled from '@emotion/styled';\nimport { buttonClasses } from '@mui/material';\nimport { CustomContentProps, SnackbarContent, useSnackbar } from 'notistack';\nimport { forwardRef } from 'react';\n\nimport { Button } from '../Button';\nimport { Flex } from '../Flex';\nimport { Icons } from '../Icons';\n\ntype Props = CustomContentProps;\n\nexport const DefaultNotification = forwardRef<HTMLDivElement, Props>(\n  (props, ref) => {\n    const { closeSnackbar } = useSnackbar();\n    const { message } = props;\n\n    return (\n      <SnackbarContent ref={ref} role=\"alert\">\n        <Wrapper>\n          <Flex\n            gap=\"xl\"\n            flexDirection=\"row\"\n            flex={1}\n            justifyContent=\"start\"\n            alignItems=\"start\"\n            width=\"100%\"\n          >\n            {message}\n            <CloseButton variant=\"invisible\" onClick={() => closeSnackbar()}>\n              <Icons.CloseIcon />\n            </CloseButton>\n          </Flex>\n        </Wrapper>\n      </SnackbarContent>\n    );\n  },\n);\n\nconst Wrapper = styled('div')(({ theme }) => ({\n  padding: theme.vars.components?.variables.spacings.md,\n  borderRadius: theme.vars.components?.variables.radius.lg,\n  boxShadow: `0 0 4px 0 rgba(0, 0, 0, 0.06), 0 4px 24px 0 rgba(0, 0, 0, 0.24);`,\n  background: theme.vars.components?.variables.colors.white,\n\n  width: '100%',\n\n  [theme.breakpoints.up('tablet')]: {\n    width: 'auto',\n    maxWidth: 454,\n  },\n}));\n\nconst CloseButton = styled(Button)(({ theme }) => ({\n  backgroundColor: 'transparent',\n  minWidth: 'auto',\n  border: 'none',\n  color: theme.vars.components?.variables.colors?.grey700,\n\n  [`&.${buttonClasses.root}`]: {\n    padding: 0,\n  },\n}));\n","import {\n  OptionsWithExtraProps,\n  SnackbarKey,\n  SnackbarMessage,\n  useSnackbar,\n} from 'notistack';\nimport {\n  createContext,\n  FunctionComponent,\n  PropsWithChildren,\n  useCallback,\n  useContext,\n  useState,\n} from 'react';\n\ntype NotificationStates = Record<SnackbarKey, 'visible' | 'closed'>;\n\nconst NotificationContext = createContext<{\n  states: NotificationStates;\n  updateState: (snackbarKey: SnackbarKey, state: 'visible' | 'closed') => void;\n}>({\n  states: {},\n  updateState: () => undefined,\n});\n\nexport const NotificationProvider: FunctionComponent<PropsWithChildren> = ({\n  children,\n}) => {\n  const [states, setStates] = useState<NotificationStates>({});\n\n  const updateState = useCallback(\n    (snackbarKey: SnackbarKey, state: 'visible' | 'closed') => {\n      setStates((s) => ({ ...s, [snackbarKey]: state }));\n    },\n    [],\n  );\n\n  return (\n    <NotificationContext.Provider\n      value={{\n        states,\n        updateState,\n      }}\n    >\n      {children}\n    </NotificationContext.Provider>\n  );\n};\n\nexport const useNotification = (snackbarKey: SnackbarKey) => {\n  const { states, updateState } = useContext(NotificationContext);\n\n  const state = states[snackbarKey] ?? 'closed';\n\n  const { enqueueSnackbar, closeSnackbar } = useSnackbar();\n\n  const enqueue = useCallback(\n    (message: SnackbarMessage, options?: OptionsWithExtraProps<'default'>) => {\n      if (state === 'visible') return;\n\n      updateState(snackbarKey, 'visible');\n\n      enqueueSnackbar(message, {\n        ...(options as unknown as object),\n        key: snackbarKey,\n      });\n    },\n    [enqueueSnackbar, snackbarKey, state, updateState],\n  );\n\n  const close = useCallback(() => {\n    if (state === 'closed') return;\n\n    closeSnackbar(snackbarKey);\n    updateState(snackbarKey, 'closed');\n  }, [closeSnackbar, snackbarKey, state, updateState]);\n\n  return {\n    state,\n    enqueue,\n    close,\n  };\n};\n","import { Slide } from '@mui/material';\nimport { SnackbarProvider as BaseSnackbarProvider } from 'notistack';\nimport { FunctionComponent, PropsWithChildren } from 'react';\n\nimport { DefaultNotification } from './DefaultNotification';\nimport { NotificationProvider } from './NotificationContext';\n\nexport const SnackbarProvider: FunctionComponent<PropsWithChildren> = ({\n  children,\n}) => (\n  <BaseSnackbarProvider\n    maxSnack={1}\n    anchorOrigin={{\n      vertical: 'bottom',\n      horizontal: 'center',\n    }}\n    TransitionComponent={Slide}\n    Components={{\n      default: DefaultNotification,\n    }}\n  >\n    <NotificationProvider>{children}</NotificationProvider>\n  </BaseSnackbarProvider>\n);\n","import { Box } from '@mui/system';\n\ntype MarginTop = Parameters<typeof Box>[0]['mt'];\ntype MarginRight = Parameters<typeof Box>[0]['mr'];\n\ntype Props = (\n  | {\n      /**\n       * Relative width in MUI-style units (similar to mt, mb, pt, etc.)\n       */\n      width?: MarginRight;\n      /**\n       * Relative height in MUI-style units (similar to mt, mb, pt, etc.)\n       */\n      height: MarginTop;\n    }\n  | {\n      /**\n       * Relative width in MUI-style units (similar to mt, mb, pt, etc.)\n       */\n      width: MarginRight;\n      /**\n       * Relative height in MUI-style units (similar to mt, mb, pt, etc.)\n       */\n      height?: MarginTop;\n    }\n) & {\n  flexGrow?: number;\n};\n\nexport const Spacer = ({ width, height, flexGrow }: Props) => (\n  <Box data-type=\"spacer\" mr={width} mt={height} flexGrow={flexGrow} />\n);\n","import {\n  FinancingSetup,\n  GetOffersResponse,\n  Offer,\n  TypedOffer,\n  useGetOffers,\n} from '@finmid/tiger-webapp/queries';\nimport { Currency } from '@finmid/types';\nimport sortBy from 'lodash/sortBy';\nimport { useMemo } from 'react';\n\nimport { useTokenContext } from '../TokenContext';\n\ntype RepaymentType = 'FIXED' | 'FLEXIBLE';\n\ninterface ResultBase {\n  data: GetOffersResponse | undefined;\n  loading: boolean;\n  stub: boolean | undefined;\n  currency: Currency;\n  isCapitalPlusAvailable: boolean;\n  maxOfferLimit: number | undefined;\n  financingSetup: FinancingSetup;\n}\n\ntype TypedOffersResult<\n  TFinancingSetup extends FinancingSetup,\n  TRepaymentType extends RepaymentType,\n> = ResultBase & {\n  offers: TypedOffer<TFinancingSetup, TRepaymentType>[] | undefined;\n  recommendedOffer: TypedOffer<TFinancingSetup, TRepaymentType> | null;\n  optimalFeeOffer: TypedOffer<TFinancingSetup, TRepaymentType> | null;\n  repaymentType: TRepaymentType;\n};\n\nexport type TailoredOffersResult =\n  | TypedOffersResult<'MCA', 'FLEXIBLE'>\n  | TypedOffersResult<'CSP', 'FIXED'>\n  | TypedOffersResult<'CSP', 'FLEXIBLE'>;\n\nexport const useTailoredOffersData = () => {\n  const { token, ignoreAction } = useTokenContext();\n  const { data } = useGetOffers({ token, ignoreAction });\n\n  const loading = data == null;\n\n  const repaymentType: RepaymentType =\n    data?.offerGroup?.repaymentType ?? 'FLEXIBLE';\n\n  const financingSetup: FinancingSetup =\n    data?.offerGroup?.financingSetup ?? 'MCA';\n\n  const offers =\n    data?.offerGroup == null\n      ? undefined\n      : data.offerGroup.financingSetup === 'MCA'\n      ? data.offerGroup.flexibleOffers\n      : data?.offerGroup?.repaymentType === 'FLEXIBLE'\n      ? data?.offerGroup?.flexibleOffers\n      : data?.offerGroup?.fixedOffers;\n\n  const currency = data?.currency ?? 'EUR';\n\n  const sortedOffers = useMemo(\n    () =>\n      offers == null\n        ? null\n        : sortBy(\n            offers as Offer[],\n            (o) => o.payoutAmount,\n            (o) => o.estimatedPayoffMonths,\n          ).reverse(),\n    [offers],\n  );\n\n  const recommendedOffer = useMemo(\n    () =>\n      sortedOffers == null || sortedOffers.length === 0\n        ? null\n        : sortedOffers[0],\n    [sortedOffers],\n  );\n\n  const optimalFeeOffer = useMemo(() => {\n    if (sortedOffers == null || sortedOffers.length <= 1) return null;\n\n    const maxPayoutOffer = sortedOffers[0];\n    const maxPayout = maxPayoutOffer.payoutAmount;\n    const targetPayout = maxPayout / 2;\n\n    const targetOffer = sortedOffers.reduce(\n      (targetOffer, current) =>\n        current.payoutAmount < maxPayout &&\n        current.payoutAmount >= targetPayout &&\n        current.fee < targetOffer.fee\n          ? current\n          : targetOffer,\n      maxPayoutOffer,\n    );\n\n    return targetOffer;\n  }, [sortedOffers]);\n\n  const isCapitalPlusAvailable =\n    data?.capitalPlus?.logicalStatus === 'AVAILABLE';\n\n  const maxOfferLimit = data?.capitalPlus?.maxRequestedLimit;\n\n  const value: TailoredOffersResult = {\n    data,\n\n    // TODO: -> could be duplicating info in `offers`\n    loading,\n\n    // TODO: user has no offers -> could be duplicating info in `offers`\n    stub: data?.stub,\n\n    currency,\n    offers,\n    recommendedOffer,\n    optimalFeeOffer,\n    isCapitalPlusAvailable,\n    maxOfferLimit,\n\n    repaymentType,\n    financingSetup,\n  } as TailoredOffersResult;\n\n  return value;\n};\n","import { createContext, useContext, useState } from 'react';\n\nimport { useTailoredOffersData } from './useTailoredOffersData';\n\ntype SelectedOffer = 'recommended' | 'optimal-fee' | 'boost' | 'custom';\n\ninterface ContextValue {\n  selected: SelectedOffer;\n  setSelected: (selected: SelectedOffer) => void;\n}\n\nconst TailoredOffersContext = createContext<ContextValue | undefined>(\n  undefined,\n);\n\nexport const TailoredOffersProvider = ({\n  children,\n}: {\n  children: React.ReactNode;\n}) => {\n  const [selected, setSelected] = useState<SelectedOffer>('recommended');\n\n  return (\n    <TailoredOffersContext.Provider value={{ selected, setSelected }}>\n      {children}\n