 display: 'block',\n      fontSize: '24px',\n      lineHeight: '32px',\n      fontWeight: 500,\n    },\n  },\n  palette: {\n    primary: colors.violet as PaletteColorOptions,\n    text: {\n      primary: colors.gray[900],\n      secondary: colors.gray[600],\n    },\n    ...colors,\n    white: '#fff',\n  },\n  components: {\n    MuiDivider: {\n      styleOverrides: {\n        root: {\n          backgroundColor: colors.gray[200],\n          borderColor: colors.gray[100],\n        },\n      },\n    },\n\n    MuiDialog: {\n      styleOverrides: {\n        paper: {\n          backgroundColor: 'white',\n          border: 'none',\n          borderRadius: 12,\n        },\n      },\n    },\n\n    MuiDialogTitle: {\n      styleOverrides: {\n        root: {\n          padding: 24,\n        },\n      },\n    },\n\n    MuiDialogContent: {\n      styleOverrides: {\n        root: {\n          padding: '40px 48px 48px',\n        },\n      },\n    },\n\n    MuiDialogActions: {\n      styleOverrides: {\n        root: {\n          padding: '0 48px 48px',\n        },\n      },\n    },\n\n    MuiCssBaseline: {\n      styleOverrides: {\n        '@global': {\n          '*, *:after, *:before': {\n            boxSizing: 'border-box',\n          },\n          body: {\n            backgroundColor: 'white',\n            fontFamily: \"'Inter', sans-serif\",\n            maxWidth: '100%',\n            overflowX: 'hidden',\n          },\n\n          'ul, ol': {\n            listStyle: 'none',\n            paddingLeft: 0,\n            margin: 0,\n          },\n\n          svg: {\n            verticalAlign: 'bottom',\n          },\n        },\n      },\n    },\n\n    MuiToggleButtonGroup: {\n      styleOverrides: {\n        root: {\n          backgroundColor: colors.gray[100],\n          flexGrow: 1,\n          padding: 2,\n          borderRadius: 8,\n\n          '&$groupedHorizontal:not(:last-child)': {\n            borderRadius: 8,\n          },\n          '& > $groupedHorizontal': {\n            '&.MuiToggleButton-root': {\n              borderRadius: 8,\n            },\n            borderRadius: 8,\n            borderColor: 'transparent',\n            borderSize: 2,\n          },\n        },\n      },\n    },\n\n    MuiToggleButton: {\n      styleOverrides: {\n        root: {\n          textTransform: 'none',\n          flexGrow: 1,\n          borderRadius: 8,\n          borderColor: 'transparent',\n          '&.Mui-selected': {\n            backgroundColor: '#fff',\n            color: colors.gray[900],\n          },\n        },\n      },\n    },\n\n    MuiListSubheader: {\n      styleOverrides: {\n        root: {\n          backgroundColor: 'transparent',\n        },\n      },\n    },\n\n    MuiAccordion: {\n      defaultProps: {\n        disableGutters: true,\n        elevation: 0,\n      },\n      styleOverrides: {\n        root: {\n          padding: 0,\n          '&:before': {\n            display: 'none',\n          },\n        },\n      },\n    },\n\n    MuiAccordionSummary: {\n      defaultProps: {\n        expandIcon: <ChevronDownIcon sx={{ fontSize: 12 }} />,\n      },\n      styleOverrides: {\n        root: {\n          padding: 0,\n          minHeight: 0,\n        },\n        content: {\n          margin: 0,\n        },\n      },\n    },\n\n    MuiAccordionDetails: {\n      styleOverrides: {\n        root: {\n          padding: '24px 0 0 0',\n        },\n      },\n    },\n\n    MuiTypography: {\n      variants: [\n        {\n          props: { variant: 'monospace' },\n          style: {\n            fontFamily: monospaceFontFamily,\n            fontWeight: 600,\n          },\n        },\n      ],\n    },\n  },\n\n  customShadows: shadows,\n\n  shadows: materialShadows,\n\n  borders,\n};\n\nexport type CustomThemeOptions = typeof themeTemplate;\n","import { ThemeProvider as EmotionThemeProvider } from '@emotion/react';\nimport { PlatformData } from '@finmid/api/internal/platform';\nimport {\n  ThemeProvider as MaterialThemeProvider,\n  PaletteColorOptions,\n  ThemeOptions,\n  createTheme,\n  Theme,\n} from '@mui/material';\nimport { PropsWithChildren } from 'react';\n\nimport {\n  CustomThemeOptions,\n  buttonStyles,\n  finmidBrandColors,\n  themeTemplate,\n} from './themeTemplate';\ndeclare module '@mui/material/styles' {\n  // eslint-disable-next-line @typescript-eslint/no-empty-object-type\n  type DefaultTheme = Theme\n\n  interface BreakpointOverrides {\n    mobile: true;\n    tablet: true;\n    desktop: true;\n    xl: true;\n\n    // Unused, but can't be removed until all grids are using this theme file\n    xs: false;\n    sm: false;\n    md: false;\n    lg: false;\n  }\n}\n\n/**\n * Module augmentation so that we can use our own colors object inside the\n * theme.palette object.\n *\n * More info:\n *  https://material-ui.com/customization/palette/#adding-new-colors\n *  https://material-ui.com/guides/typescript/#customization-of-theme\n */\n\n// createTheme() will populate the theme object with Material-UI's nice\n// defaults. The object we pass as parameter will override those defaults.\n// More info: https://material-ui.com/customization/theming/\n//\n// The EmotionThemeProvider is there so we can access that theme inside\n// the css prop or styled api.\n// More info: https://emotion.sh/docs/theming`\n\nconst buildPalette = (brandColors: string[]): PaletteColorOptions => {\n  const keys = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900];\n\n  return keys\n    .map((key, index): [number, string | null] => [\n      key,\n      brandColors[index] || null,\n    ])\n    .reduce((acc, tuple) => {\n      const [key, color] = tuple;\n      const newObj = { ...acc };\n\n      if (color) {\n        newObj[key as keyof PaletteColorOptions] = color;\n      }\n\n      return newObj;\n    }, {} as PaletteColorOptions);\n};\n\nexport const createFinmidTheme = (\n  brandColors: PlatformData['brandColors'] = finmidBrandColors,\n) => {\n  const palette = buildPalette(brandColors);\n\n  const themeOptions: CustomThemeOptions = {\n    ...themeTemplate,\n    palette: {\n      ...themeTemplate.palette,\n      primary: palette,\n    },\n  };\n\n  const themeWithOverridenComponents = {\n    ...themeOptions,\n    components: {\n      ...themeOptions.components,\n\n      ...buttonStyles(themeOptions),\n    },\n    typography: {\n      ...themeOptions.typography,\n    },\n  } as ThemeOptions;\n\n  return createTheme(themeWithOverridenComponents);\n};\n\ntype ThemeProviderProps = PropsWithChildren<{\n  brandColors: PlatformData['brandColors'];\n  distributorName?: PlatformData['name'];\n}>;\n\nexport const ThemeProvider = ({\n  children,\n  brandColors,\n}: ThemeProviderProps) => {\n  const theme = createFinmidTheme(brandColors);\n\n  return (\n    <MaterialThemeProvider theme={theme}>\n      <EmotionThemeProvider theme={theme}>{children}</EmotionThemeProvider>\n    </MaterialThemeProvider>\n  );\n};\n","import { style, compose } from '@mui/system';\n\nexport type TextColorProps = {\n  textcolor?: string;\n};\n\nexport const textColor = style({\n  prop: 'textcolor',\n  cssProperty: 'color',\n  themeKey: 'palette',\n});\n\nexport type BgColorProps = {\n  bgColor?: string;\n};\n\nexport const bgColor = style({\n  prop: 'bgColor',\n  cssProperty: 'backgroundColor',\n  themeKey: 'palette',\n});\n\nexport type PaletteProps = TextColorProps & BgColorProps;\n\nexport const palette = compose(textColor, bgColor);\n","import { style } from '@mui/system';\n\nimport { ShadowsType } from '../themeTemplate';\n\nexport type ShadowProps = {\n  shadow?: ShadowsType;\n};\n\nexport const shadow = style({\n  prop: 'shadow',\n  cssProperty: 'box-shadow',\n  themeKey: 'customShadows',\n});\n","import { ENVIRONMENT } from '@finmid/environment';\nimport type { DeepPartial } from 'react-hook-form';\n\nimport {\n  PlatformCustomization,\n  Variables,\n  colors,\n  radius,\n  spacings,\n  typographySizes,\n} from '../PlatformSettings';\n\nexport const composeVariables = (\n  customization: PlatformCustomization | undefined,\n  variables: Variables | null,\n): PlatformCustomization => {\n  const validatedVariables = validateVariables(\n    variables as DeepPartial<Variables>,\n  );\n\n  if (validatedVariables == null) {\n    return customization ?? ({} as PlatformCustomization);\n  }\n\n  const components =\n    customization != null\n      ? {\n          ...customization,\n          // Always prefer customizations from code\n          variables: customization.variables ?? variables,\n        }\n      : ({\n          variables,\n        } as PlatformCustomization);\n\n  return components;\n};\n\nfunction validateVariables(\n  variables: DeepPartial<Variables>,\n): Variables | null {\n  let result: Variables | null = variables as Variables;\n\n  if (variables == null) {\n    return null;\n  }\n\n  // Validate colors\n  colors\n    .filter((c) => c !== 'secondaryAccent' && c !== 'secondaryDefault')\n    .forEach((key) => {\n      const isValid = validateHtmlColor(\n        variables.colors?.[key],\n        `colors.${key}`,\n      );\n      if (!isValid) {\n        result = null;\n      }\n    });\n\n  // Validate radius values\n  radius.forEach((key) => {\n    const isValid = validateCssValue(variables.radius?.[key], `radius.${key}`);\n    if (!isValid) {\n      result = null;\n    }\n  });\n\n  // Validate spacing values\n  spacings.forEach((key) => {\n    const isValid = validateCssValue(\n      variables.spacings?.[key],\n      `spacings.${key}`,\n    );\n    if (!isValid) {\n      result = null;\n    }\n  });\n\n  // Validate typography\n  (['mobile', 'desktop'] as const).forEach((device) => {\n    const typography = variables.typography?.[device];\n\n    if (\n      !validateFontFamily(\n        typography?.family?.title,\n        `typography?.${device}.family.title`,\n      )\n    ) {\n      result = null;\n    }\n    if (\n      !validateFontFamily(\n        typography?.family?.body,\n        `typography?.${device}.family.body`,\n      )\n    ) {\n      result = null;\n    }\n\n    if (\n      !validateFontWeight(\n        typography?.weight?.default,\n        `typography?.${device}.weight.default`,\n      )\n    ) {\n      result = null;\n    }\n\n    if (\n      !validateFontWeight(\n        typography?.weight?.strong,\n        `typography?.${device}.weight.strong`,\n      )\n    ) {\n      result = null;\n    }\n\n    // Validate size\n    typographySizes.forEach((sizeKey) => {\n      const isValid = validateCssValue(\n        typography?.size?.[sizeKey],\n        `typography?.${device}.size.${sizeKey}`,\n      );\n      if (!isValid) {\n        result = null;\n      }\n    });\n\n    // Validate lineHeight\n    typographySizes.forEach((sizeKey) => {\n      const isValid = validateCssValue(\n        typography?.lineHeight?.[sizeKey],\n        `typography?.${device}.lineHeight.${sizeKey}`,\n      );\n      if (!isValid) {\n        result = null;\n      }\n    });\n  });\n\n  return result;\n}\n\nfunction validateHtmlColor(color: string | undefined, path: string): boolean {\n  if (color?.startsWith('#')) {\n    return true;\n  }\n\n  warn(`Invalid HTML color: ${color} at ${path}`);\n  return false;\n}\n\nconst validCssValuePattern = /^(0|(\\d+(\\.\\d+)?)(px|%|em|rem))$/;\n\nfunction validateCssValue(\n  value: number | string | undefined,\n  path: string,\n): boolean {\n  if (value != null && typeof value === 'number' && !isNaN(value)) {\n    return true;\n  }\n\n  if (value != null && validCssValuePattern.test(value.toString())) {\n    return true;\n  }\n\n  warn(`Invalid CSS value: ${value} at ${path}`);\n  return false;\n}\n\nfunction validateFontFamily(value: string | undefined, path: string): boolean {\n  if (typeof value === 'string' && value.length > 0) {\n    return true;\n  }\n\n  warn(`Invalid string: ${value} at ${path}`);\n  return false;\n}\n\nconst allowedFontWeights = [\n  'normal',\n  'bold',\n  '400',\n  '500',\n  '600',\n  '700',\n  '800',\n  '900',\n];\n\nfunction validateFontWeight(\n  value: string | number | undefined,\n  path: string,\n): boolean {\n  if (value == null) {\n    warn(`Invalid font weight: ${value} at ${path}`);\n    return false;\n  }\n\n  const stringValue = value.toString();\n\n  if (allowedFontWeights.includes(stringValue)) {\n    return true;\n  }\n\n  warn(`Invalid font weight: ${value} at ${path}`);\n  return false;\n}\n\nconst warn = (message: string) => {\n  if (ENVIRONMENT !== 'live') {\n    console.log(`%c${message}`, 'color: yellow; font-weight: bold;');\n  }\n};\n","import { createFinmidTheme } from '@finmid/ui/theme';\nimport { CssVarsThemeOptions } from '@mui/material';\nimport { extendTheme } from '@mui/material/styles';\n\nimport { PlatformCustomization, Variables } from '../PlatformSettings';\n\nimport { composeVariables } from './composeVariables';\n\nconst legacyTheme = createFinmidTheme([\n  '#000',\n  '#000',\n  '#000',\n  '#000',\n  '#000',\n  '#000',\n  '#000',\n  '#000',\n  '#000',\n  '#000',\n]);\n\nexport const defaultTheme = extendTheme({\n  ...legacyTheme,\n\n  colorSchemes: {\n    light: {\n      palette: legacyTheme.palette,\n      components: {} as PlatformCustomization,\n    },\n  },\n});\n\nexport const createCssTheme = (\n  customization: PlatformCustomization | undefined,\n  variables: Variables | null,\n  brandColors?: [\n    string,\n    string,\n    string,\n    string,\n    string,\n    string,\n    string,\n    string,\n    string,\n    string,\n  ],\n) => {\n  const legacyTheme = createFinmidTheme(brandColors); // TODO: probably redundant\n\n  const components = composeVariables(customization, variables);\n\n  const themeTemplate: CssVarsThemeOptions = {\n    ...legacyTheme,\n\n    colorSchemes: {\n      light: {\n        palette: legacyTheme.palette,\n        components,\n      },\n    },\n\n    typography: {\n      fontFamily: [\n        // TODO: remove the legacy fallback\n        customization?.variables?.typography?.desktop?.family?.body ??\n          variables?.typography?.desktop?.family?.body,\n        'sans-serif',\n      ].join(','),\n    },\n  };\n\n  const theme = extendTheme(themeTemplate);\n\n  // eslint-disable-next-line @typescript-eslint/ban-ts-comment\n  // @ts-ignore\n  delete theme.colorSchemes.dark;\n\n  cleanupUnsupportedCharsFromVars(theme.vars.components);\n\n  return theme;\n};\n\n// eslint-disable-next-line @typescript-eslint/no-explicit-any\nfunction cleanupUnsupportedCharsFromVars(obj?: any) {\n  if (!obj || typeof obj !== 'object') return;\n  Object.keys(obj).forEach((key) => {\n    if (obj[key] && typeof obj[key] === 'object')\n      cleanupUnsupportedCharsFromVars(obj[key]);\n    else {\n      const val = obj[key];\n      if (val && typeof val === 'string' && val.includes('var')) {\n        obj[key] = val.replace(/--mui-components[^,]*,/, cleanVarName);\n      }\n    }\n  });\n}\n\nfunction cleanVarName(name: string) {\n  return name.replace(/[.&>)(: ]/gm, '');\n}\n\ndeclare module '@mui/material/styles' {\n  interface ColorSystemOptions {\n    components: PlatformCustomization;\n  }\n\n  interface ThemeVars {\n    components?: PlatformCustomization;\n  }\n}\n\nexport function hexToChannel(hexValue: string) {\n  // Remove hash\n  const hex = hexValue.slice(1);\n\n  // Split to four channels\n  const splitHex = hex.match(/.{1,2}/g);\n\n  const toDecimals = function (v: string) {\n    return parseInt(v, 16);\n  };\n\n  return splitHex?.map(toDecimals).join(' ');\n}\n","import { Overrides } from '@finmid/tiger-webapp/overrides-manager';\n\nimport { ColorVariables, PlatformCustomization } from '../../PlatformSettings';\n\ntype Props = {\n  customization?: PlatformCustomization;\n  overrides?: Overrides;\n};\n\nexport const overrideThemeColors = ({ customization, overrides }: Props) => {\n  const colorsAreOverriden =\n    overrides?.colors && Object.keys(overrides?.colors ?? {}).length > 0;\n\n  if (customization && colorsAreOverriden) {\n    Object.entries(overrides?.colors ?? {}).forEach(([key, value]) => {\n      if (value != null) {\n        customization.variables.colors[key as keyof ColorVariables] = value;\n      }\n    });\n  }\n};\n","import { PlatformProvider } from '@finmid/platforms';\nimport { useOverrides } from '@finmid/tiger-webapp/overrides-manager';\nimport { useGetPlatformData } from '@finmid/tiger-webapp/queries';\nimport { setFavicon } from '@finmid/utils';\nimport { extendTheme } from '@mui/material/styles';\nimport { FunctionComponent, PropsWithChildren, useEffect } from 'react';\n\nimport { usePlatformSettings, Variables } from '../PlatformSettings';\nimport { useTokenContext } from '../TokenContext';\n\nimport { createCssTheme } from './theme';\nimport { overrideThemeColors } from './utils';\n\ninterface Props {\n  ready: boolean;\n  onLoaded: (theme: ReturnType<typeof extendTheme>) => void;\n}\n\nexport const PlatformThemeProvider: FunctionComponent<\n  PropsWithChildren<Props>\n> = ({ children, onLoaded, ready }) => {\n  const { platformId } = useTokenContext();\n  const { overrides } = useOverrides();\n  const { customization } = usePlatformSettings();\n\n  const { data: platformData } = useGetPlatformData(platformId);\n\n  overrideThemeColors({ customization, overrides });\n\n  useEffect(() => {\n    if (platformData == null) return;\n\n    setFavicon(platformData.favicon);\n\n    const variables = platformData.payablesCustomizations as Variables | null;\n\n    const theme = createCssTheme(\n      customization,\n      variables,\n      platformData.brandColors,\n    );\n\n    onLoaded(theme);\n  }, [platformData, customization, onLoaded]);\n\n  if (platformData == null || !ready) return null;\n\n  if (overrides?.name) {\n    platformData.name = overrides.name;\n  }\n  if (overrides?.websiteLogo) {\n    platformData.websiteLogo = overrides.websiteLogo;\n  }\n\n  return <PlatformProvider value={platformData}>{children}</PlatformProvider>;\n};\n","import { ThemeProvider as EmotionThemeProvider } from '@emotion/react';\nimport { CssBaseline } from '@mui/material';\nimport {\n  ThemeProvider as CssVarsProvider,\n  extendTheme,\n} from '@mui/material/styles';\nimport { FunctionComponent, Suspense, useState } from 'react';\n\nimport { FullPageLoader } from '../Loader';\n\nimport { defaultTheme } from './theme';\n\nexport const ThemeProvider: FunctionComponent<{\n  children: (options: {\n    themeChanged: boolean;\n    setTheme: (theme: ReturnType<typeof extendTheme>) => void;\n  }) => JSX.Element | JSX.Element[];\n}> = ({ children }) => {\n  const [theme, setTheme] = useState(defaultTheme);\n\n  return (\n    <CssVarsProvider theme={theme}>\n      <EmotionThemeProvider theme={theme}>\n        <CssBaseline />\n        <Suspense fallback={<FullPageLoader />}>\n          {children({ themeChanged: theme !== defaultTheme, setTheme })}\n        </Suspense>\n      </EmotionThemeProvider>\n    </CssVarsProvider>\n  );\n};\n","import { Theme } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport {\n  Button as ButtonBase,\n  ButtonProps,\n  buttonClasses,\n} from '@mui/material';\nimport type { NormalCssProperties } from '@mui/material/styles/createMixins';\nimport merge from 'lodash/merge';\nimport { ComponentProps } from 'react';\n\nimport { unwrapTypographyStyles } from '../Typography';\nimport { customizeStyles } from '../customizeStyles';\n\nexport type ToggleState = 'on' | 'off';\n\nexport const TOGGLE_BORDER_WIDTH = 1;\n\nexport type ToggleProps = ComponentProps<typeof Toggle>;\n\nexport const Toggle = styled(\n  ({\n    children,\n    onClick,\n    disabled,\n    ...props\n  }: Omit<\n    ButtonProps,\n    'size' | 'variant' | 'color' | 'translate' | 'loading'\n  > & {\n    state: ToggleState;\n  }) => (\n    <ButtonBase\n      {...props}\n      translate=\"no\"\n      disableRipple\n      disableElevation\n      onClick={disabled ? undefined : onClick}\n      disabled={disabled}\n    >\n      {typeof children === 'string' ? (\n        <span>\n          {\n            // When the children is a plain string, and user wants to translate it, we should wrap it with a span\n            children\n          }\n        </span>\n      ) : (\n        children\n      )}\n    </ButtonBase>\n  ),\n)(\n  ({\n    state,\n    theme: {\n      vars: { components },\n    },\n    theme,\n  }) => ({\n    textTransform: 'none',\n    whiteSpace: 'nowrap',\n    boxShadow: 'none',\n    width: 'fit-content',\n\n    borderRadius: components?.variables.radius?.md,\n\n    flexShrink: 0,\n\n    [`&.${buttonClasses.root}`]: {\n      ...{\n        // Since height is not defined, we need to subtract border width from vertical padding.\n        // Here we also calculate button label padding + button padding with\n        // ${components?.variables.spacings.xs} + ${components?.variables.spacings.sm}\n        padding: `calc(${components?.variables.spacings.xs} + ${components?.variables.spacings.sm} - ${TOGGLE_BORDER_WIDTH}px)`,\n        ...customizeStyles(theme, (c) => c?.toggle?.base?.default),\n      },\n    },\n\n    ...merge(\n      unwrapTypographyStyles(theme, 'size', 'sm'),\n      unwrapTypographyStyles(theme, 'family', 'body'),\n      unwrapTypographyStyles(theme, 'lineHeight', 'sm'),\n      unwrapTypographyStyles(theme, 'weight', 'default'),\n    ),\n\n    ...mixin('on', theme, state, {\n      base: {\n        borderWidth: TOGGLE_BORDER_WIDTH,\n        borderStyle: 'solid',\n        borderColor: components?.variables.colors.primaryDefault,\n\n        backgroundColor: components?.variables.colors.primaryDefault,\n        color: components?.variables.colors.white,\n      },\n      hover: {\n        backgroundColor: components?.variables.colors.primaryAccent,\n      },\n      focus: {\n        borderColor: components?.variables.colors.primaryAccent,\n      },\n      disabled: {\n        borderColor: components?.variables.colors.grey300,\n        backgroundColor: components?.variables.colors.grey300,\n        color: components?.variables.colors.grey700,\n      },\n    }),\n\n    ...mixin('off', theme, state, {\n      base: {\n        borderWidth: TOGGLE_BORDER_WIDTH,\n        borderStyle: 'solid',\n        borderColor: components?.variables.colors.grey300,\n\n        backgroundColor: components?.variables.colors.grey100,\n\n        color: components?.variables.colors.grey900,\n      },\n      hover: {\n        backgroundColor: components?.variables.colors.grey100,\n        borderColor: components?.variables.colors.primaryDefault,\n      },\n      focus: {\n        backgroundColor: components?.variables.colors.grey100,\n        borderColor: components?.variables.colors.primaryDefault,\n      },\n      disabled: {\n        borderColor: components?.variables.colors.grey300,\n        backgroundColor: components?.variables.colors.grey300,\n        color: components?.variables.colors.grey700,\n      },\n    }),\n  }),\n);\n\nconst mixin = (\n  mixinVariant: ToggleState,\n  theme: Theme,\n  variant: ToggleState,\n  css: Record<'base' | 'hover' | 'focus' | 'disabled', NormalCssProperties>,\n) =>\n  variant === mixinVariant\n    ? {\n        ...css['base'],\n        ...customizeStyles(theme, (c) => c?.toggle?.[variant]?.default),\n\n        '&:hover, &[data-focus=\"true\"]': {\n          ...css['hover'],\n          ...customizeStyles(theme, (c) => c?.toggle?.[variant]?.hovered),\n        },\n\n        '&:focus-visible, &:focus, &[data-focus=\"true\"]': {\n          ...css['focus'],\n          ...customizeStyles(theme, (c) => c?.toggle?.[variant]?.focused),\n        },\n\n        [`&.${buttonClasses.disabled}`]: {\n          pointerEvents: 'auto',\n          cursor: 'not-allowed',\n\n          ...css['disabled'],\n          ...customizeStyles(theme, (c) => c?.toggle?.[variant]?.disabled),\n        },\n      }\n    : null;\n","import { useTheme } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { Tooltip as TooltipBase, tooltipClasses } from '@mui/material';\nimport { Except } from 'type-fest';\n\nimport { customizeStyles } from './customizeStyles';\n\ntype Props = Exce