} from 'date-fns/locale/sk';\nimport { sl } from 'date-fns/locale/sl';\nimport { sv } from 'date-fns/locale/sv';\nimport { createInstance, PostProcessorModule } from 'i18next';\nimport { FunctionComponent, PropsWithChildren } from 'react';\nimport { I18nextProvider } from 'react-i18next';\nimport { useAsync } from 'react-use';\n\nimport { FullPageLoader } from './Loader';\nimport { usePlatformSettings } from './PlatformSettings';\nimport type { LocalizationVariables } from './PlatformSettings/PlatformSettings';\nimport { useCountrySettings, usePlatformSupportEmail } from './hooks';\n\nexport const allowedLanguages: SupportedLocales = {\n  en: enGB,\n  'en-GB': enGB,\n\n  'bg-BG': bg,\n  'cs-CZ': cs,\n  'da-DK': da,\n  'de-DE': de,\n  'el-GR': el,\n  'es-ES': es,\n  'et-EE': et,\n  'fi-FI': fi,\n  'fr-FR': fr,\n  'hr-HR': hr,\n  'hu-HU': hu,\n  'it-IT': it,\n  'lt-LT': lt,\n  'lv-LV': lv,\n  'pl-PL': pl,\n  'pt-PT': pt,\n  'ro-RO': ro,\n  'sk-SK': sk,\n  'sl-SI': sl,\n  'sv-SE': sv,\n\n  'ru-RU': ru, // Useful for testing experimental version of Locize\n};\n\ninterface TranslationsProviderProps {\n  postProcess?: PostProcessorModule;\n}\n\nexport const TranslationsProvider: FunctionComponent<\n  PropsWithChildren<TranslationsProviderProps>\n> = ({ children, postProcess }) => {\n  const { localization } = usePlatformSettings();\n\n  const { overrides } = useOverrides();\n  const experimentalTranslations = overrides?.experimentalTranslations ?? false;\n\n  if (\n    experimentalTranslations &&\n    !localization?.allowedLocales?.includes('ru-RU')\n  ) {\n    // Push a test locale to the allowed locales\n    localization?.allowedLocales?.push('ru-RU');\n  }\n\n  const { countrySettings } = useCountrySettings();\n  const { name: platform } = usePlatform();\n  const supportEmail = usePlatformSupportEmail();\n\n  const { value: i18nInstance } = useAsync(async () => {\n    if (localization.project == null) return null;\n\n    const supportedLocalesPerPlatform = {\n      ...(ENVIRONMENT !== 'live' ? { cimode: enGB } : {}),\n      ...(!localization.allowedLocales\n        ? allowedLanguages\n        : localization.allowedLocales.reduce<SupportedLocales>(\n            (result, key) => {\n              result[key] = allowedLanguages[key];\n              return result;\n            },\n            {},\n          )),\n    };\n\n    const platformName = countrySettings?.platformName ?? platform;\n\n    const defaultVariables: LocalizationVariables = {\n      platform: platformName,\n      productName: 'Capital',\n      fullProductName: `${platformName} Capital`,\n\n      supportEmail,\n      ...localization.defaultVariables,\n    };\n\n    const instance = await initializeTranslations(\n      {\n        locizeOptions: {\n          projectId: localization.project,\n          apiKey: fromEnvironment('LOCIZE_API_KEY', { required: false }),\n          referenceLng: 'en',\n          enableInContextEditing: false, // Do not enable for Staging, iframe-tester see the odd borders\n          version:\n            ENVIRONMENT === 'live'\n              ? 'latest'\n              : experimentalTranslations\n              ? 'experimental'\n              : 'latest',\n        },\n        useSuspense: true,\n        fallbackLng: {\n          default: ['en'],\n        },\n        detectorOptions: {\n          convertDetectedLanguage: detectedLanguageConverter(\n            supportedLocalesPerPlatform,\n          ),\n        },\n        defaultVariables,\n        postProcess,\n      },\n      createInstance(),\n      supportedLocalesPerPlatform,\n    );\n\n    return instance;\n  }, [localization.project, localization.allowedLocales]);\n\n  if (i18nInstance == null) return <FullPageLoader />;\n\n  return (\n    <I18nextProvider i18n={i18nInstance} defaultNS=\"turnkey\">\n      {children}\n    </I18nextProvider>\n  );\n};\n","import styled from '@emotion/styled';\nimport { useTranslation } from 'react-i18next';\n\nimport { Typography } from '../../Typography';\n\nconst StyledMessage = styled(Typography)(({ theme: { vars } }) => ({\n  color: vars.components?.variables.colors.error,\n  alignSelf: 'flex-start',\n}));\n\ntype Props = {\n  error: string;\n};\n\nexport const ErrorMessage = ({ error }: Props) => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'twoFactorModal' });\n\n  const message =\n    error === 'VALIDATION_FAILED'\n      ? t('verifyCode.invalidCode', {\n          defaultValue: 'Please check your code and input again',\n        })\n      : t('verifyCode.defaultError', {\n          defaultValue:\n            'Something went wrong. Please try again by refreshing the page.',\n        });\n\n  return <StyledMessage size=\"xs\">{message}</StyledMessage>;\n};\n","import { ClassNames, useTheme } from '@emotion/react';\nimport {\n  useRequest2FaChallenge,\n  useSecondsTillNext2FaChallenge,\n} from '@finmid/tiger-webapp/queries';\nimport { Box, InputLabel, useMediaQuery } from '@mui/material';\nimport { captureException } from '@sentry/react';\nimport classNames from 'classnames';\nimport { FunctionComponent, useCallback, useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport {\n  ContactSupport,\n  CustomisationSlot,\n  Flex,\n  LegacyTimedButton,\n  MobileStickyNavigation,\n  NocodeShieldIcon,\n  StickyFooterWithBorder,\n  Typography,\n  useAnimation,\n  useCapturePosthogEvent,\n  useCapturePosthogViewed,\n  useTokenContext,\n} from '..';\n\nimport AuthCode from './AuthCode';\nimport {\n  Background,\n  ButtonsWrapper,\n  CodeInputWrapper,\n  invalid2faAnimation,\n  ResendCodeButtonWrapper,\n  SubmitCodeButton,\n  Subtitle,\n  Title,\n} from './VerifyCode.styled';\nimport { ErrorMessage } from './components';\n\ntype VerifyCodeOfferAcceptProps = {\n  onCodeVerifiedError?: string | null;\n  verifyCode: (challenge: string) => Promise<boolean>;\n  onCodeVerified: () => void;\n  phone: string;\n  type: 'OFFER_ACCEPT';\n};\n\ntype VerifyCodeHistoryAccessProps = {\n  onCodeVerifiedError?: string | null;\n  verifyCode: (challenge: string) => Promise<boolean>;\n  onCodeVerified: () => Promise<void>;\n  type: 'HISTORY_ACCESS';\n};\n\ntype VerifyCodeProps =\n  | VerifyCodeOfferAcceptProps\n  | VerifyCodeHistoryAccessProps;\n\nexport const VerifyCode: FunctionComponent<VerifyCodeProps> = ({\n  onCodeVerifiedError,\n  onCodeVerified,\n  verifyCode,\n  ...props\n}) => {\n  const posthogEventCategory =\n    props.type === 'OFFER_ACCEPT' ? 'offers' : 'dashboard';\n\n  useCapturePosthogViewed(`${posthogEventCategory}:verify_code_step_view`);\n\n  const capturePosthogEvent = useCapturePosthogEvent();\n  const {\n    t,\n    i18n: { language },\n  } = useTranslation('turnkey', {\n    keyPrefix: 'twoFactorModal.verifyCode',\n  });\n\n  const [inputKey, setInputKey] = useState(new Date());\n  const [code, setCode] = useState('');\n  const handleOnChange = (res: string) => {\n    setCode(res);\n  };\n\n  const [isValid, setIsValid] = useState(true);\n  const [isLoading, setIsLoading] = useState(false);\n  const [codeVerificationServiceError, setCodeVerificationServiceError] =\n    useState(false);\n  const { breakpoints, vars } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n\n  const [animation, animateValidation] = useAnimation(invalid2faAnimation);\n\n  const { token } = useTokenContext();\n\n  const sendChallenge = useRequest2FaChallenge({\n    token,\n    locale: language,\n    ...props,\n  });\n\n  const secondsTillNext2FaChallenge = useSecondsTillNext2FaChallenge();\n\n  const animateInvalidCode = () => {\n    animateValidation();\n    setIsValid(false);\n  };\n\n  const onSubmit = useCallback(async () => {\n    capturePosthogEvent(\n      `${posthogEventCategory}:identity_verification_code_send`,\n    );\n\n    if (code.length !== 6) {\n      animateInvalidCode();\n      return;\n    }\n    setIsLoading(true);\n    setCodeVerificationServiceError(false);\n\n    try {\n      const isValidCode = await verifyCode(code);\n      if (isValidCode) {\n        capturePosthogEvent(\n          `${posthogEventCategory}:identity_verification_code_submit`,\n        );\n\n        await onCodeVerified();\n      } else {\n        capturePosthogEvent(\n          `${posthogEventCategory}:identity_verification_code_fail`,\n        );\n\n        animateInvalidCode();\n      }\n    } catch (error) {\n      animateInvalidCode();\n      setCodeVerificationServiceError(true);\n      captureException(error);\n    }\n\n    setIsLoading(false);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [animateValidation, code, onCodeVerified, verifyCode]);\n\n  const timedButton = (\n    <LegacyTimedButton\n      onClick={() => {\n        sendChallenge.mutate();\n        setInputKey(new Date());\n        setIsValid(true);\n      }}\n      initialTime={secondsTillNext2FaChallenge}\n      disabledTextFn={({ minutes, seconds }) =>\n        t('resendButtonDisabled', {\n          defaultValue: 'Resend available in {{minutes}}:{{seconds}}',\n          minutes,\n          seconds,\n        })\n      }\n      enabledText={t('resendButton', 'Resend code')}\n      customizationTags={['verifyCode', 'resend']}\n    />\n  );\n\n  return (\n    <form\n      data-test-id=\"verify-code\"\n      onSubmit={(e) => {\n        e.preventDefault();\n        void onSubmit();\n        return false;\n      }}\n      css={{ width: '100%' }}\n    >\n      <MobileStickyNavigation\n        onContinue={() => null}\n        continueText={t(`submitCodeButton.${props.type}`, 'Submit code')}\n        isSubmitButton\n        hideBackButton\n        topComponent={timedButton}\n        continueButtonTestId=\"send-button\"\n        fullHeaderHeight={false}\n      >\n        <Background>\n          <CustomisationSlot\n            slot=\"verify.code.icon\"\n            props={{}}\n            fallback={<NocodeShieldIcon />}\n          />\n          <Title size=\"lg\" family=\"title\" weight=\"strong\">\n            {t(`title.${props.type}`, 'Enter the code')}\n          </Title>\n          <Subtitle size=\"md\">\n            {t(\n              'subtitle',\n              'Please enter the 6-digit code sent to the phone number on your account.',\n            )}\n          </Subtitle>\n\n          <CodeInputWrapper>\n            <Flex\n              alignItems=\"flex-start\"\n              flexDirection=\"column\"\n              width=\"100%\"\n              gap=\"xs\"\n            >\n              <InputLabel>\n                <Typography size=\"xs\">Code</Typography>\n              </InputLabel>\n              <ClassNames>\n                {({\n                  css,\n                  theme: {\n                    vars: { components },\n                    breakpoints,\n                  },\n                }) => (\n                  <AuthCode\n                    allowedCharacters=\"numeric\"\n                    onChange={handleOnChange}\n                    autoFocus\n                    containerClassName={css({\n                      display: 'flex',\n                      justifyContent: 'space-between',\n                      gap: vars.components?.variables.spacings.md,\n                      width: '100%',\n\n                      [breakpoints.down('tablet')]: {\n                        gap: vars.components?.variables.spacings.sm,\n                      },\n                    })}\n                    inputClassName={classNames(\n                      css({\n                        boxSizing: 'border-box',\n\n                        display: 'flex',\n                        alignItems: 'center',\n                        justifyContent: 'center',\n                        textAlign: 'center',\n                        borderColor: isValid\n                          ? components?.codeConfirmation?.input?.borderColor ??\n                            vars.components?.variables.colors.grey300\n                          : `color-mix(in srgb, ${components?.variables.colors.error} 5%, transparent)`,\n                        borderWidth: 1,\n                        borderStyle: 'solid',\n                        borderRadius: vars.components?.variables.radius.sm,\n                        aspectRatio: 0.9,\n                        width: '15%',\n                        backgroundColor: isValid\n                          ? 'white'\n                          : `color-mix(in srgb, ${components?.variables.colors.error} 5%, transparent)`,\n                        color: isValid\n                          ? components?.codeConfirmation?.input?.color ??\n                            vars.components?.variables.colors.grey900\n                          : vars.components?.variables.colors.error,\n\n                        fontSize: `max(${\n                          components?.codeConfirmation?.input?.fontSize ??\n                          vars.components?.variables.typography.desktop.size\n                            ?.xxl ??\n                          '16px'\n                        }, 16px)`,\n\n                        fontWeight:\n                          components?.codeConfirmation?.input?.fontWeight ??\n                          vars.components?.variables.typography.desktop.weight\n                            ?.strong,\n\n                        [breakpoints.down('tablet')]: {\n                          fontSize: `max(${\n                            components?.codeConfirmation?.mobile?.input\n                              ?.fontSize ??\n                            vars.components?.variables.typography.mobile.size\n                              ?.sm ??\n                            '16px'\n                          }, 16px)`,\n\n                          fontWeight:\n                            vars.components?.variables.typography.mobile.weight\n                              ?.default,\n                          padding: 0,\n                          maxWidth: 49,\n                        },\n\n                        ...animation,\n\n                        ':focus': {\n                          borderColor: isValid\n                            ? components?.codeConfirmation?.input?.color ??\n                              vars.components?.variables.colors.primaryDefault\n                            : vars.components?.variables.colors.error,\n                          outline: 'none',\n                        },\n                      }),\n                    )}\n                    key={inputKey.toISOString()}\n                  />\n                )}\n              </ClassNames>\n            </Flex>\n\n            {codeVerificationServiceError ? (\n              <ErrorMessage error=\"UNKNOWN_ERROR\" />\n            ) : null}\n            {onCodeVerifiedError ? (\n              <ErrorMessage error={onCodeVerifiedError} />\n            ) : null}\n\n            <Box\n              mt={vars.components?.variables.spacings.md}\n              mb={vars.components?.variables.spacings.xxl}\n              width=\"100%\"\n            >\n              <ContactSupport />\n            </Box>\n          </CodeInputWrapper>\n\n          {!isMobile ? (\n            <>\n              <StickyFooterWithBorder buttons={2} />\n              <ButtonsWrapper>\n                <ResendCodeButtonWrapper\n                  data-test-id=\"resend-code-button\"\n                  translate=\"no\"\n                >\n                  {timedButton}\n                </ResendCodeButtonWrapper>\n\n                <SubmitCodeButton\n                  variant=\"primary\"\n                  size=\"large\"\n                  type=\"submit\"\n                  fullWidth\n                  loading={isLoading}\n                  data-test-id=\"send-button\"\n                  customizationTags={['verifyCode', 'submit']}\n                >\n                  {t(`submitCodeButton.${props.type}`, 'Submit code')}\n                </SubmitCodeButton>\n              </ButtonsWrapper>\n            </>\n          ) : null}\n        </Background>\n      </MobileStickyNavigation>\n    </form>\n  );\n};\n","import styled from '@emotion/styled';\n\nimport { customizeStyles } from '../customizeStyles';\n\n// The Mask component is hiding the border if there is no scroll\nconst Mask = styled('div')(({ theme: { vars, breakpoints } }) => ({\n  position: 'relative',\n  width: `calc(100% + ${vars?.components?.variables.spacings.xl} * 2)`,\n  height: 1,\n  bottom: 1, // Shifting it up a pixel to hide StickyBackgroundWithBorder's border\n  background: vars?.components?.variables.colors.white,\n\n  ...customizeStyles(\n    { vars, breakpoints },\n    (c) => c?.modal?.twoFactor?.stickyBackgroundWithBorder?.mask,\n  ),\n}));\n\n// This component is sticky as per name, and it goes up with the modal bottom,\n// while the Mask is going down being relative,\n// revealing the border in ::after pseudo-element\nconst StickyBackgroundWithBorder = styled('div')<{ buttons: number }>(\n  ({ theme: { vars, breakpoints }, buttons }) => {\n    const buttonHeight = `calc(${vars?.components?.variables.typography.desktop.lineHeight.md} + ${vars?.components?.variables.spacings.md} * 2)`;\n    return {\n      position: 'sticky',\n      bottom: `calc(${buttonHeight} * ${buttons} + ${vars?.components?.variables.spacings.md} * 2 * ${buttons})`,\n      width: '100%',\n      height: 1,\n      ...customizeStyles(\n        { vars, breakpoints },\n        (c) => c?.modal?.twoFactor?.stickyBackgroundWithBorder?.element,\n      ),\n\n      '::after': {\n        content: '\"\"',\n        position: 'absolute',\n        top: 0,\n        left: `calc(-1 *  ${vars?.components?.variables.spacings.xl})`,\n        display: 'block',\n        width: `calc(100% + ${vars?.components?.variables.spacings.xl} * 2)`,\n        height: `calc(1px + ${buttonHeight} * ${buttons} + ${vars?.components?.variables.spacings.md} * 2 * ${buttons})`,\n        background: vars?.components?.variables.colors.white,\n        borderTop: `1px solid ${vars?.components?.variables.colors.grey300}`,\n\n        ...customizeStyles(\n          { vars, breakpoints },\n          (c) => c?.modal?.twoFactor?.stickyBackgroundWithBorder?.after,\n        ),\n      },\n    };\n  },\n);\n\n/*\n * This is a floating sticky footer to be placed before the CTA in modal.\n * */\nexport const StickyFooterWithBorder = ({\n  buttons = 1,\n}: {\n  buttons?: number;\n}) => {\n  return (\n    <>\n      <StickyBackgroundWithBorder buttons={buttons} />\n      <Mask />\n    </>\n  );\n};\n","import styled from '@emotion/styled';\nimport { Box } from '@mui/material';\n\nimport { Flex } from '../Flex';\nimport { TextInput } from '../Inputs';\nimport { customized, customizeStyles } from '../customizeStyles';\n\nexport const UseOfFundsSectionTitle = styled(Box)(({ theme }) => ({\n  color: theme.vars.components?.variables.colors.grey900,\n  fontFamily: theme.vars.components?.variables.typography.mobile.family.body,\n  fontSize: theme.vars.components?.variables.typography.mobile.size.md,\n  lineHeight: theme.vars.components?.variables.typography.mobile.lineHeight.md,\n  fontStyle: 'normal',\n  fontWeight: 700,\n\n  [theme.breakpoints.up('tablet')]: {\n    fontFamily: theme.vars.components?.variables.typography.desktop.family.body,\n    fontSize: theme.vars.components?.variables.typography.desktop.size.md,\n    lineHeight:\n      theme.vars.components?.variables.typography.desktop.lineHeight.md,\n  },\n\n  ...customizeStyles(theme, (c) => c?.review?.useOfFunds?.title),\n}));\n\nexport const UseOfFundsSectionContainer = styled(Flex)(({ theme }) => ({\n  width: '100%',\n  flexDirection: 'column',\n  justifyContent: 'start',\n  alignItems: 'start',\n\n  gap: theme.vars.components?.variables.spacings.xl,\n\n  backgroundColor: theme.vars.components?.variables.colors.white,\n  padding: theme.vars.components?.variables.spacings.md,\n  borderRadius: theme.vars.components?.variables.radius.md,\n  border: `1px solid ${theme.vars.components?.variables.colors.grey300}`,\n\n  ...customizeStyles(theme, (c) => c?.review?.useOfFunds?.root),\n}));\n\nexport const UseOfFundsSectionTextInput = customized(\n  TextInput,\n  (c) => c?.review?.useOfFunds?.input,\n);\n","import { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { Flex } from '../Flex';\nimport { CustomisationSlot } from '../PlatformSettings';\nimport { useSelectedOffer } from '../SelectedOfferContext';\nimport { Toggle } from '../Toggle';\n\nimport {\n  UseOfFundsSectionContainer,\n  UseOfFundsSectionTextInput,\n  UseOfFundsSectionTitle,\n} from './UseOfFundsSection.styled';\nimport {\n  MAX_COMMENT_LENGTH,\n  type UseOfFunds,\n  UseOfFundsToggle,\n  toggles,\n  useUseOfFundsForm,\n} from './useUseOfFundsForm';\n\nexport { UseOfFunds };\n\ninterface Props {\n  options?: UseOfFundsToggle[];\n}\n\nexport const UseOfFundsSection: FunctionComponent<Props> = ({\n  options = toggles,\n}) => {\n  const { t } = useTranslation('offers', {\n    keyPrefix: 'review.CSP.capitalSummary.useOfFunds',\n  });\n\n  const {\n    financingSetup,\n    useOfFunds: { values: useOfFunds, comment },\n  } = useSelectedOffer();\n\n  const { handleUseOfFundsChange, handleCommentChange, formState } =\n    useUseOfFundsForm();\n\n  const handleToggle = (toggle: UseOfFundsToggle) => {\n    handleUseOfFundsChange(toggle);\n  };\n\n  const commentError = formState.errors.comment?.message;\n\n  if (financingSetup !== 'CSP') {\n    return null;\n  }\n\n  const getProps = (toggle: UseOfFundsToggle) => ({\n    state: useOfFunds.includes(toggle) ? ('on' as const) : ('off' as const),\n    onClick: () => handleToggle(toggle),\n    children: t(`${toggle}`),\n  });\n\n  return (\n    <UseOfFundsSectionContainer data-test-id=\"use-of-funds\">\n      <UseOfFundsSectionTitle>{t('title')}</UseOfFundsSectionTitle>\n\n      <Flex gap=\"sm\" width=\"100%\" flexWrap=\"wrap\" justifyContent=\"start\">\n        {options.map((toggle) => (\n          <CustomisationSlot\n            slot=\"component.toggle\"\n            key={toggle}\n            props={getProps(toggle)}\n            fallback={\n              <Toggle\n                data-use-of-funds={toggle}\n                key={toggle}\n                {...getProps(toggle)}\n              />\n            }\n          />\n        ))}\n      </Flex>\n\n      <Flex width=\"100%\" flexDirection=\"column\" gap=\"xs\">\n        <UseOfFundsSectionTextInput\n          placeholder={t('other.placeholder', 'Tell us more')}\n          onChange={(e) => handleCommentChange(e.target.value)}\n          value={comment ?? ''}\n          error={commentError != null}\n          helperText={commentError}\n          slotProps={{\n            htmlInput: {\n              maxLength: MAX_COMMENT_LENGTH,\n            },\n          }}\n        />\n        {comment && !commentError && (\n          <Flex\n            width=\"100%\"\n            justifyContent=\"flex-end\"\n            style={{ fontSize: '12px', color: '#666' }}\n          >\n            {comment.length}/{MAX_COMMENT_LENGTH}\n          </Flex>\n        )}\n      </Flex>\n    </UseOfFundsSectionContainer>\n  );\n};\n","import { ENVIRONMENT, fromEnvironment } from '@finmid/environment';\nimport {\n  getUtmParams,\n  clearUtmParams,\n  useConsentContext,\n  useTokenContext,\n} from '@finmid/tiger-webapp/components';\nimport { useGetPlatformData } from '@finmid/tiger-webapp/queries';\nimport posthog from 'posthog-js';\nimport {\n  createContext,\n  PropsWithChildren,\n  useContext,\n  useEffect,\n  useState,\n} from 'react';\n\nconst testEnvironment = navigator.userAgent.startsWith('Playwright');\nconst posthogKey = fromEnvironment('POSTHOG_KEY', { required: false });\n\nexport type PostHog = typeof posthog;\n\ninterface Value {\n  client: PostHog | null;\n  initialized: boolean;\n}\n\nexport const PosthogContext = createContext<Value>({\n  client: null,\n  initialized: false,\n});\n\nexport const PosthogProvider = ({ children }: PropsWithChildren) => {\n  const { consentState } = useConsentContext() ?? { consentState: 'MISSING' };\n  const [initialized, setInitialized] = useState(false);\n  const [client, setClient] = useState<PostHog | null>(null);\n  const { businessId, platformId } = useTokenContext();\n  const { data: platformData } = useGetPlatformData(platformId);\n\n  useEffect(() => {\n    if (platformData == null) return;\n\n    if (consentState == null || consentState === 'MISSING') return;\n\n    if (testEnvironment) return;\n\n    if (ENVIRONMENT !== 'live' && ENVIRONMENT !== 'staging') return;\n\n    if (posthogKey == null) return;\n\n    if (businessId == null) return;\n\n    switch (consentState) {\n      case 'ACTIVE':\n        if (initialized) break;\n\n        posthog.init(posthogKey, {\n          api_host: 'https://eu.posthog.com',\n          persistence: 'memory',\n          bootstrap: {\n            distinctID: businessId,\n          },\n          sanitize_properties(properties) {\n            properties['$current_url'] =\n              window.location.origin + window.location.pathname;\n            return properties;\n          },\n          session_recording: {\n            maskNetworkRequestFn: (request) => {\n              request.url = request.url.split('?')[0];\n\n              return request;\n            },\n          },\n        });\n\n        posthog.identify(\n          businessId,\n          {\n            ...getUtmParams(),\n          },\n          {\n            platformId: platformData.id,\n            platformName: platformData.name,\n          },\n        );\n\n        clearUtmParams();\n\n        posthog.group('merchant', businessId);\n\n        if (ENVIRONMENT === 'live') {\n          // Capture group only for live platforms\n          posthog.group('platform', platformData.id, {\n            name: platformData.name,\n          });\n        } else {\n          // Stub on staging\n          posthog.group('platform', 'staging', {\n            name: 'Staging',\n          });\n        }\n\n        setClient(posthog);\n        setInitialized(true);\n        break;\n      case 'REJECTED':\n        if (initialized) window.location.reload();\n        break;\n    }\n  }, [businessId, consentState, initialized, platformData]);\n\n  return (\n    <PosthogContext.Provider value={{ client, initialized }}>\n      {children}\n    </PosthogContext.Provider>\n  );\n};\n\nexport const usePosthogContext = () => useContext(PosthogContext);\n","import { ENVIRONMENT } from '@finmid/environment';\nimport { useEffect, useState } from 'react';\n\nimport { usePosthogContext } from './PosthogProvider';\n\n// In-memory cache for feature flag results, keyed by flag\nconst featureFlagCache: Record<string, string | boolean | undefined> = {};\n\n/*\n * We should always use this hook instead of PostHog's useFeatureFlagVariantKey,\n * to make sure we are connecting to our initialised client\n * */\nexport function useCustomFeatureFlagVariantKey(\n  flag: string,\n): string | boolean | undefined {\n  const { client, initialized } = usePosthogContext();\n\n  const [featureFlagVariantKey, setFeatureFlagVariantKey] = useState<\n    string | boolean | undefined\n  >(() => featureFlagCache[flag]);\n\n  useEffect(() => {\n    if (\n      !initialized ||\n      client?.onFeatureFlags == null ||\n      client?.getFeatureFlag == null\n    ) {\n      return;\n    }\n\n    // On live set from cache if available\n    if (ENVIRONMENT === 'live' && featureFlagCache[flag] !== undefined) {\n      setFeatureFlagVariantKey(featureFlagCache[flag]);\n    } else {\n      client.onFeatureFlags(() => {\n        const value = client.getFeatureFlag(flag);\n        featureFlagCache[flag] = value;\n        setFeatureFlagVariantKey(value);\n      });\n    }\n  }, [initialized, flag, client]);\n\n  return featureFlagVariantKey;\n}\n","import { useFeatureFlags } from '@finmid/tiger-webapp/feature-flags';\n\nimport {\n  Experiment,\n  ExperimentFeatureToggle,\n  ExperimentVariants,\n} from './types';\nimport { useCustomFeatureFlagVariantKey } from './useCustomFeatureFlagVariantKey';\n\nexport const useExperimentEnabled = <TExperiment extends Experiment>(\n  experiment: TExperiment,\n  variant: ExperimentVariants[TExperiment],\n  featureToggle: ExperimentFeatureToggle<TExperiment>,\n) => {\n  const merchantVariant = useCustomFeatureFlagVariantKey(experiment);\n  const { isToggleEnabled } = useFeatureFlags();\n\n  const isVariantEnabled = merchantVariant === variant;\n  return isVariantEnabled || isToggleEnabled(featureToggle);\n};\n","import {\n  createContext,\n  FunctionComponent,\n  PropsWithChildren,\n  useContext,\n  useState,\n} from 'react';\n\ninterface WhatsAppContextType {\n  /**\n   * This context manages the lifecycle of a help banner that appears to guide users.\n   * The banner goes through several states during its lifecycle:\n   *\n   * **Lifecycle states**:\n   *\n   * 1. 'hidden' (Initial State)\n   *    - Banner is not visible and not displayed\n   *    - Default starting state\n   *    - Also the final state after closing animation completes\n   *\n   * 2. 'mounting' (Preparation Phase)\n   *    - Banner is being prepared to show but not yet visible, nor displayed\n   *    - Triggered when pageState changes to 'show'\n   *    - Lasts for openDelayMs (3000ms) before transitioning to 'opening'\n   *\n   * 3. 'opening' (Animation Start)\n   *    - Banner is being displayed, the space on page is occupied\n   *    - Banner begins its entrance animation\n   *    - Very brief state (0ms timeout) that immediately transitions to 'open'\n   *    - Allows for CSS animation triggering\n   *\n   * 4. 'open' (Fully Visible)\n   *    - Banner is fully visible and interactive\n   *    - Stable state where banner remains until user action or page change\n   *\n   * 5. 'closing' (Exit Animation)\n   *    - Banner is playing its exit animation\n   *    - Triggered when pageState changes to 'skip' while banner is visible\n   *    - Lasts for animationDurationMs before transitioning to 'hidden'\n   *\n   * 6. 'dismissed' (User Dismissed)\n   *    - Banner is not visible and not displayed\n   *    - Banner was explicitly dismissed by user interaction\n   *    - Terminal state - banner won't reappear during this session\n   *\n   * **Transition triggers**:\n   * - pageState 'show' → starts mounting sequence (hidden → mounting → opening → open)\n   * - pageState 'skip' → starts closing sequence (open/opening/mounting → closing → hidden)\n   * - User dismiss action → sets to 'dismissed'\n   */\n  needHelpMessage: {\n    state: 'hidden' | 'mounting' | 'opening' | 'open' | 'closing' | 'dismissed';\n    setState: (\n      state:\n        | 'hidden'\n        | 'mounting'\n        | 'opening'\n        | 'open'\n        | 'closing'\n        | 'dismissed',\n    ) => void;\n  };\n  floatingDialog: {\n    state: 'open' | 'closed';\n    setState: (state: 'open' | 'closed') => void;\n  };\n}\n\nconst WhatsAppContext = createContext<WhatsAppContextType>({\n  needHelpMessage: {\n    state: 'hidden',\n    setState: () => {},\n  },\n  floatingDialog: {\n    state: 'closed',\n    setState: () => {},\n  },\n});\n\nexport const WhatsAppContextProvider: FunctionComponent<PropsWithChildren> = ({\n  children,\n}) => {\n  const [needHelpMessageState, setNeedHelpMessageState] = useState<\n    'hidden' | 'mounting' | 'opening' | 'open' | 'closing' | 'dismissed'\n  >('hidden');\n  const [floatingDialogState, setFloatingDialogState] = useState<\n    'open' | 'closed'\n  >('closed');\n\n  return (\n    <WhatsAppContext.Provider\n      value={{\n        needHelpMessage: {\n          state: needHelpMessageState,\n          setState: setNeedHelpMessageState,\n        },\n        floatingDialog: {\n          state: floatingDialogState,\n          setState: setFloatingDialogState,\n        },\n      }}\n    >\n      {children}\n    </WhatsAppContext.Provider>\n  );\n};\n\nexport const useWhatsApp = () => {\n  const context = useContext(WhatsAppContext);\n  if (!context) {\n    throw new Error(\n      'useWhatsApp must be used within a WhatsAppContextProvider',\n    );\n  }\n  return context;\n};\n","import { SVGProps, memo } from 'react';\n\nconst SvgComponent = (props: SVGProps<SVGSVGElement>) => (\n  <svg\n    xmlns=\"http://www.w3.org/2000/svg\"\n    width={26}\n    height={26}\n    viewBox=\"0 0 26 26\"\n    fill=\"none\"\n    {...props}\n  >\n    <path\n      fill=\"#fff\"\n      d=\"M18.058 15.177c-.218-.108-1.633-.757-1.85-.865-.218-.108-.436-.108-.654.108-.217.216-.653.866-.87 1.082-.11.216-.327.216-.544.108a8.903 8.903 0 0 1-2.177-1.298 12.468 12.468 0 0 1-1.524-1.84c-.11-.216 0-.432.109-.54.108-.109.217-.325.435-.433.109-.109.218-.325.218-.433a.328.328 0 0 0 0-.433c-.11-.108-.653-1.407-.871-1.948-.109-.757-.327-.757-.544-.757H9.24c-.217 0-.544.216-.653.325-.653.649-.98 1.406-.98 2.272.11.974.436 1.947 1.09 2.813 1.197 1.731 2.72 3.138 4.57 4.003.545.217.98.433 1.524.541.545.217 1.089.217 1.742.108.762-.108 1.415-.649 1.85-1.298.218-.433.218-.866.11-1.298l-.436-.217Zm2.72-9.846c-4.244-4.22-11.101-4.22-15.346 0-3.483 3.463-4.136 8.764-1.742 12.984l-1.523 5.518 5.768-1.515c1.633.866 3.375 1.299 5.116 1.299 5.986 0 10.775-4.761 10.775-10.712.11-2.813-1.088-5.518-3.047-7.574ZM17.84 20.48c-1.415.866-3.047 1.407-4.789 1.407-1.633 0-3.156-.433-4.571-1.19l-.327-.217-3.374.866.87-3.246-.217-.325C2.82 13.446 4.126 8.036 8.371 5.331s9.687-1.298 12.299 2.813c2.612 4.22 1.415 9.738-2.83 12.335Z\"\n    />\n  </svg>\n);\n\nconst Memo = memo(SvgComponent);\nexport default Memo;\n","import styled from '@emotion/styled';\nimport {\n  Flex,\n  CloseButton as CloseButtonBase,\n  customizeStyles,\n  Typography,\n  customized,\n} from '@finmid/tiger-webapp/components';\n\nexport const animationDurationMs = 300;\n\nexport const Card = styled(Flex, {\n  shouldForwardProp: (prop) => prop !== 'invisible' && prop !== 'rendered',\n})<{ invisible: boolean; rendered: boolean }>(\n  ({ theme, invisible, rendered }) => ({\n    flexDirection: 'row',\n    display: rendered ? 'flex' : 'none',\n\n    justifyContent: 'space-between',\n\n    width: '100%',\n\n    gap: theme.vars.components?.variables.spacings.xl,\n    borderRadius: theme.vars.components?.variables.radius?.lg,\n    padding: theme.vars.components?.variables.spacings.md,\n    border: `1px solid ${theme.vars.components?.variables?.colors?.grey300}`,\n    boxShadow:\n      '0px 0px 4px 0px rgba(0, 0, 0, 0.06), 0px 4px 24px 0px rgba(0, 0, 0, 0.24)',\n    backgroundColor: '#ffffff',\n\n    transition: `opacity ${animationDurationMs}ms ease, transform ${animationDurationMs}ms ease`,\n\n    transform: `translateY(${invisible ? '100%' : '0%'})`,\n\n    opacity: invisible ? 0 : 1,\n    pointerEvents: invisible ? 'none' : 'auto',\n\n    marginTop: theme.vars.components?.variables.spacings.md,\n\n    [theme.breakpoints.up('desktop')]: {\n      width: 'auto',\n    },\n\n    ...customizeStyles(theme, (c) => c?.whatsApp?.needHelpMessage?.card),\n  }),\n);\n\nexport const WhatsAppIconWrapper = styled(Flex)(({ theme }) => ({\n  position: 'relative',\n  display: 'none',\n\n  backgroundColor: '#25D366',\n  borderRadius: '50%',\n  padding: theme.vars.components?.variables.spacings.sm,\n\n  [theme.breakpoints.up('desktop')]: {\n    display: 'flex',\n  },\n\n  ...customizeStyles(theme, (c) => c?.whatsApp?.needHelpMessage?.icon),\n}));\n\nexport const CloseButton = styled(CloseButtonBase)(({ theme }) => ({\n  padding: 0,\n\n  ...customizeStyles(theme, (c) => c?.whatsApp?.needHelpMessage?.closeButton),\n}));\n\nexport const FaviconContainer = styled(Flex)(({ theme }) => ({\n  position: 'absolute',\n  right: -6,\n  bottom: -6,\n\n  backgroundColor: '#ffffff',\n  border: `1px solid #ffffff`,\n  borderRadius: theme.vars.components?.variables.radius?.sm,\n  boxShadow:\n    '0px 0px 12px 0px rgba(0, 0, 0, 0.06), 0px 0px 2px 0px rgba(0, 0, 0, 0.24)',\n\n  width: 24,\n  height: 24,\n}));\n\nexport const Title = customized(\n  Typography,\n  (c) => c?.whatsApp?.needHelpMessage?.title,\n);\n\nexport const Description = customized(\n  Typography,\n  (c) => c?.whatsApp?.needHelpMessage?.description,\n);\n","import { useEffect } from 'react';\n\nimport { useWhatsApp } from '../WhatsAppContext';\n\nimport { animationDurationMs } from './NeedHelpMessage.styled';\n\n/**\n * NeedHelpMessage Banner Lifecycle Hook\n *\n * This hook orchestrates the banner lifecycle based on page state changes.\n * It manages automatic showing/hiding of the help banner with proper animations.\n *\n * LIFECYCLE FLOW:\n *\n * SHOWING SEQUENCE (pageState: 'show'):\n * When user enters a page where banner should be shown:\n * 1. hidden → mounting (immediate)\n * 2. mounting → opening (after 3000ms delay)\n * 3. opening → open (immediately, triggers CSS animation)\n *\n * HIDING SEQUENCE (pageState: 'skip'):\n * When user leaves a page or banner should be hidden:\n * 1. open/opening/mounting → closing (immediate)\n * 2. closing → hidden (after animation completes)\n *\n * TIMING CONSTANTS:\n * - openDelayMs: 3000ms - Delay before banner starts appearing\n * - animationDurationMs: From styled component - Duration of show/hide animations\n *\n * STATE PROTECTION:\n * - Won't restart if banner is already dismissed by user\n * - Won't interfere with ongoing animations\n * - Gracefully handles rapid page state changes\n */\n\ninterface Options {\n  pageState: 'show' | 'skip';\n}\n\nconst openDelayMs = 3000;\n\nexport const useNeedHelpMessage = ({ pageState }: Options) => {\n  const {\n    needHelpMessage: { state: contextState, setState: setContextState },\n  } = useWhatsApp();\n\n  useEffect(() => {\n    // HIDING LOGIC: Handle graceful exit when leaving banner-enabled pages\n    if (\n      contextState === 'open' ||\n      contextState === 'opening' ||\n      contextState === 'mounting'\n    ) {\n      if (pageState === 'skip') {\n        // When the merchant leaves the banner-enabled page, we gracefully hide the banner\n        // Start closing animation immediately\n        setContextState('closing');\n        setTimeout(() => {\n          // After animation completes, fully hide the banner\n          setContextState('hidden');\n        }, animationDurationMs);\n        return;\n      }\n    }\n\n    // PROTECTION: Don't interfere with dismissed banners or ongoing processes\n    if (contextState !== 'hidden') {\n      // Don't do anything if the banner is already dismissed, mounting, open or opening\n      return;\n    }\n\n    // SHOWING LOGIC: Handle banner appearance on banner-enabled pages\n    if (pageState === 'show') {\n      // When the merchant enters the page with the banner enabled, we show the banner\n\n      // Step 1: Start mounting phase (preparation)\n      setContextState('mounting');\n      setTimeout(() => {\n        // Step 2: After delay, begin opening animation\n        setContextState('opening');\n        setTimeout(() => {\n          // Step 3: Immediately transition to fully open state\n          // This 0ms timeout ensures proper CSS animation triggering\n          setContextState('open');\n        }, 0);\n      }, openDelayMs);\n    }\n  }, [contextState, pageState, setContextState]);\n\n  return {\n    state: contextState,\n    setState: setContextState,\n  };\n};\n","import { usePlatform } from '@finmid/platforms';\nimport { Flex, Icons, useResponsive } from '@finmid/tiger-webapp/components';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useWhatsApp } from '../WhatsAppContext';\nimport WhatsAppIcon from '../WhatsAppIcon';\n\nimport { useNeedHelpMessage } from './NeedHelpMessage.hook';\nimport {\n  animationDurationMs,\n  Card,\n  CloseButton,\n  Description,\n  FaviconContainer,\n  Title,\n  WhatsAppIconWrapper,\n} from './NeedHelpMessage.styled';\n\ninterface Props {\n  pageState: 'show' | 'skip';\n}\n\nexport const NeedHelpMessage: FunctionComponent<Props> = ({ pageState }) => {\n  const { t } = useTranslation('whatsApp', {\n    keyPrefix: 'needHelpBanner',\n  });\n\n  const { favicon } = usePlatform();\n\n  const {\n    floatingDialog: { state: floatingDialogState },\n  } = useWhatsApp();\n\n  const { state, setState } = useNeedHelpMessage({ pageState });\n\n  const { isMobile } = useResponsive();\n\n  const rendered =\n    state === 'open' || state === 'opening' || state === 'closing';\n\n  return (\n    <Card\n      invisible={state !== 'open' || floatingDialogState === 'open'}\n      rendered={rendered}\n    >\n      <WhatsAppIconWrapper>\n        <WhatsAppIcon />\n        <FaviconContainer>\n          <img src={favicon} width={20} height={20} alt=\"platform icon\" />\n        </FaviconContainer>\n      </WhatsAppIconWrapper>\n      <Flex\n        flexDirection=\"column\"\n        gap=\"xs\"\n        justifyContent=\"start\"\n        alignItems=\"start\"\n      >\n        <Title size={isMobile ? 'sm' : 'md'} weight=\"strong\">\n          {t('title', 'Need help?')}\n        </Title>\n        <Description size={isMobile ? 'sm' : 'md'}>\n          {t('description', \"We're a WhatsApp message away.\")}\n        </Description>\n      </Flex>\n      <Flex alignSelf=\"start\">\n        <CloseButton\n          isRelative\n          onClick={() => {\n            setState('closing');\n            setTimeout(() => {\n              setState('dismissed');\n            }, animationDurationMs);\n          }}\n        >\n          <Icons.CloseIcon\n            style={{\n              fontSize: 24,\n            }}\n          />\n        </CloseButton>\n      </Flex>\n    </Card>\n  );\n};\n","import styled from '@emotion/styled';\nimport { Flex } from '@finmid/tiger-webapp/components';\n\nexport const Container = styled(Flex, {\n  shouldForwardProp: (prop) =>\n    prop !== 'hide' && prop !== 'overStickyNavigation',\n})<{ hide: boolean; overStickyNavigation: boolean }>(\n  ({ theme, overStickyNavigation, hide }) => ({\n    flexDirection: 'column',\n    alignItems: 'end',\n    justifyContent: 'center',\n\n    position: 'fixed',\n    bottom: 0,\n    right: 0,\n    left: 0,\n\n    marginBottom: overStickyNavigation ? '96px' : '0px',\n\n    padding: theme.vars.components?.variables.spacings.md,\n\n    transition: 'opacity 0.3s ease',\n    opacity: hide ? 0 : 1,\n    pointerEvents: 'none',\n\n    gap: theme.vars.components?.variables.spacings.md,\n\n    [theme.breakpoints.up('desktop')]: {\n      flexDirection: 'row-reverse',\n      justifyContent: 'space-between',\n    },\n  }),\n);\n\nexport const Button = styled.button(({ theme }) => ({\n  aspectRatio: 1,\n  height: 58,\n  display: 'flex',\n  alignItems: 'center',\n  justifyContent: 'center',\n  backgroundColor: '#25D366',\n  border: 'none',\n  padding: theme.vars.components?.variables.spacings.sm,\n  borderRadius: theme.vars.components?.variables.radius.md,\n  boxShadow:\n    '0px 12px 36px 0px rgba(0, 0, 0, 0.30), 0px 3px 9px 0px rgba(0, 0, 0, 0.18)',\n\n  cursor: 'pointer',\n  pointerEvents: 'auto',\n\n  '&:hover': {\n    backgroundColor: '#128C00',\n    transition: 'background-color 0.3s ease',\n  },\n}));\n\nexport const IconWrapper = styled.div(({ theme }) => ({\n  padding: theme.vars.components?.variables.spacings.sm,\n  display: 'flex',\n  alignItems: 'center',\n  justifyContent: 'center',\n}));\n","import {\n  customized,\n  useCapturePosthogEvent,\n  useCssVariable,\n  usePlatformSettings,\n} from '@finmid/tiger-webapp/components';\nimport { useExperimentEnabled } from '@finmid/tiger-webapp/posthog';\nimport { FunctionComponent } from 'react';\n\nimport { useWhatsApp } from './WhatsAppContext';\nimport {\n  Button as ButtonBase,\n  IconWrapper,\n} from './WhatsAppFloatingButton.styled';\nimport WhatsAppIcon from './WhatsAppIcon';\n\nconst Button = customized(ButtonBase, (c) => c?.whatsApp?.floatingButton);\n\nexport const OpenWhatsAppDialogButton: FunctionComponent = () => {\n  const {\n    floatingDialog: { setState: setFloatingDialogState },\n  } = useWhatsApp();\n\n  const capturePosthogEvent = useCapturePosthogEvent();\n\n  const isWhatsAppExperimentEnabled = useExperimentEnabled(\n    'whatsapp-support',\n    'whatsapp-enabled',\n    null,\n  );\n\n  const iconSize = useCssVariable(\n    'whatsApp.iconSize',\n    (c) => c?.whatsApp?.iconSize,\n    '26px',\n  ).replace('px', '');\n\n  const { experiments } = usePlatformSettings();\n\n  const isWhatsAppEnabled =\n    isWhatsAppExperimentEnabled && experiments?.whatsApp != null;\n\n  if (!isWhatsAppEnabled) {\n    return null;\n  }\n\n  return (\n    <Button\n      onClick={() => {\n        capturePosthogEvent('floating_whatsapp_button_clicked');\n        setFloatingDialogState('open');\n      }}\n    >\n      <IconWrapper>\n        <WhatsAppIcon width={iconSize} height={iconSize} />\n      </IconWrapper>\n    </Button>\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  customized,\n  customizeStyles,\n  Flex,\n  Typography,\n} from '@finmid/tiger-webapp/components';\n\nexport const Modal = styled(Flex)(({ theme }) => ({\n  position: 'fixed',\n\n  left: theme.vars.components?.variables.spacings.md,\n  bottom: theme.vars.components?.variables.spacings.md,\n  right: theme.vars.components?.variables.spacings.md,\n\n  padding: theme.vars.components?.variables.spacings.lg,\n\n  borderRadius: theme.vars.components?.variables.radius.lg,\n  boxShadow:\n    '0px 0px 4px 0px rgba(0, 0, 0, 0.06), 0px 4px 24px 0px rgba(0, 0, 0, 0.24)',\n  backgroundColor: theme.vars.components?.variables.colors?.white,\n\n  zIndex: 1000,\n  overflow: 'hidden',\n  flexDirection: 'column',\n\n  gap: theme.vars.components?.variables.spacings.xl,\n\n  [theme.breakpoints.up('desktop')]: {\n    left: 'unset',\n    maxWidth: 343,\n  },\n\n  ...customizeStyles(theme, (c) => c?.whatsApp?.chatContainer?.root),\n}));\n\nexport const Header = styled(Flex)(({ theme }) => ({\n  alignItems: 'flex-start',\n  justifyContent: 'space-between',\n  width: '100%',\n  gap: theme.vars.components?.variables.spacings.md,\n}));\n\nexport const WhatsAppIconWrapper = styled(Flex)(({ theme }) => ({\n  backgroundColor: '#25D366',\n  borderRadius: theme.vars.components?.variables.radius.sm,\n}));\n\nexport const TitleWithCloseButton = styled(Flex)(({ theme }) => ({\n  position: 'relative',\n  gap: theme.vars.components?.variables.spacings.sm,\n  alignItems: 'flex-start',\n}));\n\nexport const IconWrapper = styled.div(({ theme }) => ({\n  color: theme.vars.components?.variables.colors?.grey900,\n  fontSize: 16,\n}));\n\nexport const ActionSection = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  gap: theme.vars.components?.variables.spacings.md,\n  width: '100%',\n}));\n\nexport const QRSection = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  alignItems: 'center',\n  background: theme.vars.components?.variables.colors?.grey100,\n\n  borderRadius: theme.vars.components?.variables.radius.lg,\n  padding: theme.vars.components?.variables.spacings.lg,\n\n  gap: theme.vars.components?.variables.spacings.md,\n\n  width: '100%',\n\n  ...customizeStyles(theme, (c) => c?.whatsApp?.chatContainer?.qrCode),\n}));\n\nexport const QRPlaceholder = styled.div({\n  // width: 120,\n  background: '#e0e0e0',\n  borderRadius: 8,\n\n  display: 'flex',\n  alignItems: 'center',\n  justifyContent: 'center',\n  color: '#888',\n});\n\nexport const Footer = styled(Flex)(({ theme }) => ({\n  width: '100%',\n  gap: theme.vars.components?.variables.spacings.sm,\n  justifyContent: 'space-between',\n}));\n\nexport const Title = customized(\n  Typography,\n  (c) => c?.whatsApp?.chatContainer?.title,\n);\n\nexport const SupportText = customized(\n  Typography,\n  (c) => c?.whatsApp?.chatContainer?.supportText,\n);\n","import { Typography, useResponsive } from '@finmid/tiger-webapp/components';\nimport QRCode from 'qrcode';\nimport { FunctionComponent, useEffect, useRef } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { QRPlaceholder, QRSection } from './ChatContainer.styled';\n\ninterface Props {\n  url: URL;\n}\n\nexport const QrCode: FunctionComponent<Props> = ({ url }) => {\n  const { t } = useTranslation('whatsApp');\n\n  const qrCodeRef = useRef<HTMLCanvasElement>(null);\n  const { isMobile } = useResponsive();\n\n  useEffect(() => {\n    if (qrCodeRef.current != null) {\n      QRCode.toCanvas(qrCodeRef.current, url.toString(), {\n        width: 200,\n        margin: 1,\n        errorCorrectionLevel: 'H',\n        color: {\n          light: '#F5F5F6',\n        },\n      });\n    }\n  }, [url, /* to refresh the QR code when the screen size changes */ isMobile]);\n\n  return (\n    <QRSection data-test-id=\"qr-code\">\n      <QRPlaceholder>\n        <canvas ref={qrCodeRef} />\n      </QRPlaceholder>\n      <Typography family=\"body\" size=\"sm\" weight=\"strong\">\n        {t('qrCodeWhatsAppMobile', 'WhatsApp Mobile')}\n      </Typography>\n    </QRSection>\n  );\n};\n","import {\n  Button,\n  useTokenContext,\n  useResponsive,\n  useCapturePosthogEvent,\n  usePlatformSettings,\n} from '@finmid/tiger-webapp/components';\nimport { useGetOffers } from '@finmid/tiger-webapp/queries';\nimport QRCode from 'qrcode';\nimport { useEffect, useMemo, useRef } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { ActionSection } from './ChatContainer.styled';\nimport { QrCode } from './QrCode';\n\nexport const Actions = () => {\n  const capturePosthogEvent = useCapturePosthogEvent();\n\n  const { t } = useTranslation('whatsApp');\n\n  const { experiments } = usePlatformSettings();\n\n  const { token, ignoreAction } = useTokenContext();\n  const { data } = useGetOffers({ token, ignoreAction });\n\n  const url = useMemo(() => {\n    const url = new URL(`https://wa.me/${experiments?.whatsApp?.number}`);\n    url.searchParams.append(\n      'text',\n      t('qrCodeText', {\n        defaultValue:\n          \"[Do not remove] Support request: {{ externalBusinessId }}\\n\\nHi, I'm interested in a cash advance.\",\n        externalBusinessId: data?.externalBusinessId,\n      }),\n    );\n    return url;\n  }, [data?.externalBusinessId, experiments?.whatsApp?.number, t]);\n\n  const qrCodeRef = useRef<HTMLCanvasElement>(null);\n\n  useEffect(() => {\n    if (qrCodeRef.current != null) {\n      QRCode.toCanvas(qrCodeRef.current, url.toString(), {\n        width: 200,\n        margin: 1,\n        errorCorrectionLevel: 'H',\n        color: {\n          light: '#F5F5F6',\n        },\n      });\n    }\n  }, [url]);\n\n  const { isMobile } = useResponsive();\n\n  if (experiments?.whatsApp == null) {\n    return null;\n  }\n\n  return (\n    <ActionSection data-test-id=\"actions\">\n      {isMobile ? null : <QrCode url={url} />}\n\n      <Button\n        fullWidth\n        variant=\"primary\"\n        onClick={() => {\n          capturePosthogEvent('whatsapp_chat_opened');\n          window.open(url, '_blank');\n        }}\n      >\n        {isMobile\n          ? t('openMobileButton', 'Open WhatsApp')\n          : t('openWebButton', 'WhatsApp Web')}\n      </Button>\n    </ActionSection>\n  );\n};\n","import {\n  Button,\n  CopyEmailButton,\n  CustomisationSlot,\n  Icons,\n  usePlatformSupportEmail,\n} from '@finmid/tiger-webapp/components';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { Actions } from './Actions';\nimport {\n  Footer,\n  Header,\n  IconWrapper,\n  Modal,\n  SupportText,\n  Title,\n  TitleWithCloseButton,\n  WhatsAppIconWrapper,\n} from './ChatContainer.styled';\nimport { useWhatsApp } from './WhatsAppContext';\nimport WhatsAppIcon from './WhatsAppIcon';\n\nexport const ChatContainer: FunctionComponent = () => {\n  const {\n    floatingDialog: {\n      state: floatingDialogState,\n      setState: setFloatingDialogState,\n    },\n  } = useWhatsApp();\n\n  const { t } = useTranslation('whatsApp');\n\n  const supportEmail = usePlatformSupportEmail();\n\n  if (floatingDialogState === 'closed') {\n    return null;\n  }\n\n  return (\n    <Modal data-test-id=\"whatsapp-chat-container\">\n      <Header data-test-id=\"header\">\n        <WhatsAppIconWrapper>\n          <WhatsAppIcon />\n        </WhatsAppIconWrapper>\n        <TitleWithCloseButton>\n          <Title family=\"body\" size=\"md\" weight=\"strong\">\n            {t('title', 'Chat with our support via WhatsApp')}\n          </Title>\n\n          <CustomisationSlot\n            slot=\"whatsapp.chat-container.close-button\"\n            props={{}}\n            fallback={\n              <Button\n                variant=\"invisible\"\n                onClick={() => setFloatingDialogState('closed')}\n                aria-label=\"Close\"\n                style={{ padding: 0, maxWidth: 26, minWidth: 26 }}\n              >\n                <IconWrapper>\n                  <Icons.ChevronDownIcon />\n                </IconWrapper>\n              </Button>\n            }\n          />\n        </TitleWithCloseButton>\n      </Header>\n\n      <Actions />\n\n      <Footer>\n        <SupportText family=\"body\" size=\"sm\" weight=\"strong\">\n          {t('footer', {\n            defaultValue: 'Or send us an email at {{ supportEmail }}.',\n            supportEmail,\n          })}\n        </SupportText>\n\n        <CopyEmailButton />\n      </Footer>\n    </Modal>\n  );\n};\n","import { Spacer, useResponsive } from '@finmid/tiger-webapp/components';\nimport { FunctionComponent } from 'react';\n\nimport { ChatContainer } from './ChatContainer';\nimport { NeedHelpMessage } from './NeedHelpMessage';\nimport { OpenWhatsAppDialogButton } from './OpenWhatsAppDialogButton';\nimport { useWhatsApp } from './WhatsAppContext';\nimport { Container } from './WhatsAppFloatingButton.styled';\n\ninterface Props {\n  overStickyNavigation?: boolean;\n  withSpacerOnMobile?: boolean;\n  withNeedHelpMessage?: boolean;\n}\n\nexport const WhatsAppFloatingButtonSlot: FunctionComponent<Props> = ({\n  overStickyNavigation: overStickyNavigationProp = false,\n  withSpacerOnMobile = true,\n  withNeedHelpMessage = false,\n}) => {\n  const { isMobile } = useResponsive();\n  const {\n    floatingDialog: { state: floatingDialogState },\n  } = useWhatsApp();\n\n  const overStickyNavigation = overStickyNavigationProp && isMobile;\n\n  return (\n    <>\n      <Container\n        hide={floatingDialogState === 'open'}\n        overStickyNavigation={overStickyNavigation}\n      >\n        <OpenWhatsAppDialogButton />\n        <NeedHelpMessage pageState={withNeedHelpMessage ? 'show' : 'skip'} />\n        {isMobile ? null : <div style={{ width: '58px' }} />}\n      </Container>\n      <ChatContainer />\n      {withSpacerOnMobile && <Spacer height={10} />}\n    </>\n  );\n};\n","import {\n  CustomisationSlot,\n  usePlatformSettings,\n  useResponsive,\n} from '@finmid/tiger-webapp/components';\nimport { useExperimentEnabled } from '@finmid/tiger-webapp/posthog';\nimport { FunctionComponent } from 'react';\n\nimport { WhatsAppFloatingButtonSlot } from './WhatsAppFloatingButtonSlot';\n\ninterface Props {\n  overStickyNavigation?: boolean;\n  withSpacerOnMobile?: boolean;\n  withNeedHelpMessage?: boolean;\n}\n\nexport const WhatsAppFloatingButton: FunctionComponent<Props> = ({\n  overStickyNavigation: overStickyNavigationProp = false,\n  withSpacerOnMobile = true,\n  withNeedHelpMessage = false,\n}) => {\n  const { isMobile } = useResponsive();\n\n  const isWhatsAppExperimentEnabled = useExperimentEnabled(\n    'whatsapp-support',\n    'whatsapp-enabled',\n    null,\n  );\n\n  const { experiments } = usePlatformSettings();\n\n  const isWhatsAppEnabled =\n    isWhatsAppExperimentEnabled && experiments?.whatsApp != null;\n\n  if (!isWhatsAppEnabled) {\n    return null;\n  }\n\n  const overStickyNavigation = overStickyNavigationProp && isMobile;\n\n  const props = {\n    overStickyNavigation,\n    withSpacerOnMobile,\n    withNeedHelpMessage,\n  };\n\n  return (\n    <CustomisationSlot\n      slot=\"whatsapp.floating-button\"\n      fallback={<WhatsAppFloatingButtonSlot {...props} />}\n      props={props}\n    />\n  );\n};\n","import {\n  createContext,\n  FunctionComponent,\n  PropsWithChildren,\n  useContext,\n  useState,\n  useCallback,\n  useEffect,\n  useRef,\n  useMemo,\n} from 'react';\n\ninterface WhatsAppFloatingButtonConfig {\n  overStickyNavigation?: boolean;\n  withSpacerOnMobile?: boolean;\n  withNeedHelpMessage?: boolean;\n}\n\ninterface WhatsAppFloatingButtonContextType {\n  isVisible: boolean;\n  config: WhatsAppFloatingButtonConfig;\n  show: (config?: WhatsAppFloatingButtonConfig) => () => void;\n  hide: () => void;\n}\n\nconst WhatsAppFloatingButtonContext =\n  createContext<WhatsAppFloatingButtonContextType>({\n    isVisible: false,\n    config: {},\n    show: () => () => {},\n    hide: () => {},\n  });\n\nexport const WhatsAppFloatingButtonProvider: FunctionComponent<\n  PropsWithChildren\n> = ({ children }) => {\n  const [isVisible, setIsVisible] = useState(false);\n  const [config, setConfig] = useState<WhatsAppFloatingButtonConfig>({});\n  const activeComponentsRef = useRef<Set<string>>(new Set());\n\n  const show = useCallback((newConfig: WhatsAppFloatingButtonConfig = {}) => {\n    const componentId = Date.now().toString() + Math.random().toString(36);\n\n    activeComponentsRef.current.add(componentId);\n\n    // Update config with new values, keeping existing ones as defaults\n    setConfig((prevConfig) => {\n      const nextConfig = {\n        withSpacerOnMobile: true, // default value\n        ...prevConfig,\n        ...newConfig,\n      };\n\n      // Only update if the config has actually changed\n      if (JSON.stringify(prevConfig) === JSON.stringify(nextConfig)) {\n        return prevConfig;\n      }\n\n      return nextConfig;\n    });\n\n    setIsVisible(true);\n\n    // Return cleanup function that removes this component from active set\n    return () => {\n      activeComponentsRef.current.delete(componentId);\n\n      // Only hide if no other components are using the button\n      if (activeComponentsRef.current.size === 0) {\n        setIsVisible(false);\n        setConfig({});\n      }\n    };\n  }, []);\n\n  const hide = useCallback(() => {\n    activeComponentsRef.current.clear();\n    setIsVisible(false);\n    setConfig({});\n  }, []);\n\n  return (\n    <WhatsAppFloatingButtonContext.Provider\n      value={{\n        isVisible,\n        config,\n        show,\n        hide,\n      }}\n    >\n      {children}\n    </WhatsAppFloatingButtonContext.Provider>\n  );\n};\n\nexport const useWhatsAppFloatingButton = () => {\n  const context = useContext(WhatsAppFloatingButtonContext);\n  if (!context) {\n    throw new Error(\n      'useWhatsAppFloatingButton must be used within a WhatsAppFloatingButtonProvider',\n    );\n  }\n  return context;\n};\n\n/**\n * Hook to show the WhatsApp floating button with specific configuration.\n * Automatically hides the button when the component unmounts.\n */\nexport const useWhatsAppButton = (\n  config: WhatsAppFloatingButtonConfig = {},\n  enabled = true,\n) => {\n  const { show } = useWhatsAppFloatingButton();\n\n  // Destructure config properties to use in dependency array\n  const { overStickyNavigation, withSpacerOnMobile, withNeedHelpMessage } =\n    config;\n\n  // Memoize the config to prevent unnecessary re-renders\n  const memoizedConfig = useMemo(\n    () => ({ overStickyNavigation, withSpacerOnMobile, withNeedHelpMessage }),\n    [overStickyNavigation, withSpacerOnMobile, withNeedHelpMessage],\n  );\n\n  useEffect(() => {\n    if (!enabled) return;\n\n    const cleanup = show(memoizedConfig);\n\n    return cleanup;\n  }, [show, memoizedConfig, enabled]);\n};\n","import { FunctionComponent } from 'react';\n\nimport { WhatsAppFloatingButton } from './WhatsAppFloatingButton';\nimport { useWhatsAppFloatingButton } from './WhatsAppFloatingButtonContext';\n\n/**\n * Root-level component that renders the WhatsApp floating button\n * based on the context state. This should be placed at the App level.\n */\nexport const WhatsAppFloatingButtonRoot: FunctionComponent = () => {\n  const { isVisible, config } = useWhatsAppFloatingButton();\n\n  if (!isVisible) {\n    return null;\n  }\n\n  return <WhatsAppFloatingButton {...config} />;\n};\n","import { Flex, SectionH1 } from '@finmid/tiger-webapp/components';\nimport { useTranslation } from 'react-i18next';\n\nexport const Page401 = () => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'errorPage' });\n  return (\n    <Flex height=\"100%\" data-test-id=\"page-401\">\n      <SectionH1 dataTestId=\"title\">\n        {t('invalidLink.title', 'The link is invalid')}\n      </SectionH1>\n    </Flex>\n  );\n};\n","import { FinancingSetup } from '@finmid/tiger-webapp/queries';\n\nimport { FaqCategory, Question } from '../../types';\n\nexport const generateFinancingSetupQuestions = (\n  financingSetup: FinancingSetup,\n  categories: Record<FinancingSetup, FaqCategory>,\n  questions: Omit<Question, 'categoryLabelKey'>[],\n): Question[] => {\n  return questions.map<Question>((question) => ({\n    key: question.key,\n    titleKey: `question.${financingSetup}.${question.titleKey}`,\n    contentKey: `question.${financingSetup}.${question.contentKey}`,\n    keywordKeys: question.keywordKeys?.map(\n      (keyword) => `keyword.${financingSetup}.${keyword}`,\n    ),\n    route: question.route,\n    categoryLabelKey: categories[financingSetup].titleKey,\n  }));\n};\n","import { useTokenContext } from '@finmid/tiger-webapp/components';\nimport {\n  FinancingSetup,\n  GetRepaymentHistoryResponse,\n  RepaymentFrequency,\n  useGetOffers,\n} from '@finmid/tiger-webapp/queries';\nimport { useQueryClient } from '@tanstack/react-query';\nimport { useMatch } from 'react-router-dom';\n\ntype Setup =\n  | {\n      financingSetup: 'CSP';\n      repaymentType: 'FIXED';\n      repaymentFrequency: RepaymentFrequency;\n    }\n  | {\n      financingSetup: FinancingSetup;\n      repaymentType: 'FLEXIBLE';\n    };\n\nexport const useFinancingSetup = (): Setup => {\n  const { token, ignoreAction } = useTokenContext();\n  const { data: availableOffers } = useGetOffers({\n    token,\n    ignoreAction,\n  });\n\n  const latestCredit = useLatestCreditFromCache();\n\n  const target = useHelpTarget();\n\n  // We're \"cutting\" types here as the caller should not care if it's an `Offer` object or `Credit`\n  if (target === 'fromCredit' && latestCredit != null) return latestCredit;\n\n  const offerGroup = availableOffers?.offerGroup;\n\n  if (offerGroup == null) {\n    return {\n      financingSetup: 'MCA',\n      repaymentType: 'FLEXIBLE',\n    };\n  } else {\n    const offerExample =\n      offerGroup.repaymentType === 'FIXED'\n        ? offerGroup.fixedOffers[0]\n        : offerGroup.flexibleOffers[0];\n\n    // We're \"cutting\" types here as the caller should not care if it's an `Offer` object or `Credit`\n    return offerExample;\n  }\n};\n\n/**\n * @returns The latest credit from the cache, or null if there is no cache.\n *\n * This is needed to try getting full financing setup from the credit without making a 2FA request.\n * If the user is on the dashboard, they've went through 2FA by this point.\n * Otherwise, returning null.\n *\n */\nconst useLatestCreditFromCache = () => {\n  const queryClient = useQueryClient();\n\n  const credits = queryClient\n    .getQueryCache()\n    .findAll({\n      queryKey: ['repaymentHistory'],\n    })\n    ?.map((query) => query.state.data as GetRepaymentHistoryResponse)\n    .map((r) => r.credit)\n    .sort(\n      (a, b) => Number(new Date(b.acceptedAt)) - Number(new Date(a.acceptedAt)),\n    );\n\n  if (credits == null || credits.length === 0) {\n    return null;\n  }\n\n  return credits[0];\n};\n\nconst useHelpTarget = () => {\n  const matchDashboard = useMatch('/dashboard');\n  return matchDashboard ? 'fromCredit' : 'fromAvailableOffers';\n};\n","import { Icons } from '@finmid/tiger-webapp/components';\nimport { FinancingSetup } from '@finmid/tiger-webapp/queries';\n\nimport { FaqCategory, Question } from '../../types';\n\nimport { generateFinancingSetupQuestions } from './generateFinancingSetupQuestions';\nimport { useFinancingSetup } from './useFinancingSetup';\n\nconst route = 'costs-and-terms';\n\nconst categories: Record<FinancingSetup, FaqCategory> = {\n  CSP: {\n    titleKey: 'category.CSP.costs.label',\n    descriptionKey: 'category.CSP.costs.description',\n    Icon: Icons.ContractIcon,\n    route,\n  },\n  MCA: {\n    titleKey: 'category.MCA.costs.label',\n    descriptionKey: 'category.MCA.costs.description',\n    Icon: Icons.ContractIcon,\n    route,\n  },\n};\n\nconst questions: Omit<Question, 'categoryLabelKey'>[] = [\n  {\n    key: 'whatAreCosts', // #12\n    titleKey: 'whatAreCosts.title',\n    contentKey: 'whatAreCosts.content',\n    route,\n  },\n  {\n    key: 'willThereBeInterests', // #13\n    titleKey: 'willThereBeInterests.title',\n    contentKey: 'willThereBeInterests.content',\n    route,\n  },\n  {\n    key: 'doesItAffectCreditScore', // #15\n    titleKey: 'doesItAffectCreditScore.title',\n    contentKey: 'doesItAffectCreditScore.content',\n    route,\n  },\n];\n\nconst financingSetupQuestions: Record<FinancingSetup, Question[]> = {\n  CSP: generateFinancingSetupQuestions('CSP', categories, questions),\n  MCA: generateFinancingSetupQuestions('MCA', categories, questions),\n};\n\nexport const useCostAndTermsCategory = () => {\n  const { financingSetup } = useFinancingSetup();\n  return categories[financingSetup] ?? categories.MCA;\n};\n\nexport const useCostAndTermsQuestions = () => {\n  const { financingSetup } = useFinancingSetup();\n  return financingSetupQuestions[financingSetup] ?? financingSetupQuestions.MCA;\n};\n","import { Icons } from '@finmid/tiger-webapp/components';\nimport { FinancingSetup } from '@finmid/tiger-webapp/queries';\n\nimport { FaqCategory, Question } from '../../types';\n\nimport { generateFinancingSetupQuestions } from './generateFinancingSetupQuestions';\nimport { useFinancingSetup } from './useFinancingSetup';\n\nconst route = 'eligibility-and-application';\n\nconst categories: Record<FinancingSetup, FaqCategory> = {\n  CSP: {\n    titleKey: 'category.CSP.eligibility.label',\n    descriptionKey: 'category.CSP.eligibility.description',\n    Icon: Icons.CheckIcon,\n    route,\n  },\n  MCA: {\n    titleKey: 'category.MCA.eligibility.label',\n    descriptionKey: 'category.MCA.eligibility.description',\n    Icon: Icons.CheckIcon,\n    route,\n  },\n};\n\nconst questions: Omit<Question, 'categoryLabelKey'>[] = [\n  {\n    key: 'whatAreRequirements', // #4\n    titleKey: 'whatAreRequirements.title',\n    contentKey: 'whatAreRequirements.content',\n    route,\n  },\n  {\n    key: 'amIPreApproved', // #5\n    titleKey: 'amIPreApproved.title',\n    contentKey: 'amIPreApproved.content',\n    route,\n  },\n];\n\nconst financingSetupQuestions: Record<FinancingSetup, Question[]> = {\n  CSP: generateFinancingSetupQuestions('CSP', categories, questions),\n  MCA: generateFinancingSetupQuestions('MCA', categories, questions),\n};\n\nexport const useEligibilityCategory = () => {\n  const { financingSetup } = useFinancingSetup();\n  return categories[financingSetup] ?? categories.MCA;\n};\n\nexport const useEligibilityQuestions = () => {\n  const { financingSetup } = useFinancingSetup();\n  return financingSetupQuestions[financingSetup] ?? financingSetupQuestions.MCA;\n};\n","import { Icons } from '@finmid/tiger-webapp/components';\nimport { FinancingSetup } from '@finmid/tiger-webapp/queries';\n\nimport { FaqCategory, Question } from '../../types';\n\nimport { generateFinancingSetupQuestions } from './generateFinancingSetupQuestions';\nimport { useFinancingSetup } from './useFinancingSetup';\n\nconst route = 'funding-and-usage';\n\nconst categories: Record<FinancingSetup, FaqCategory> = {\n  CSP: {\n    titleKey: 'category.CSP.funding.label',\n    descriptionKey: 'category.CSP.funding.description',\n    Icon: Icons.PaymentsIcon,\n    route,\n  },\n  MCA: {\n    titleKey: 'category.MCA.funding.label',\n    descriptionKey: 'category.MCA.funding.description',\n    Icon: Icons.PaymentsIcon,\n    route,\n  },\n};\n\nconst questions: Omit<Question, 'categoryLabelKey'>[] = [\n  {\n    key: 'howMuchCapital', // #6\n    titleKey: 'howMuchCapital.title',\n    contentKey: 'howMuchCapital.content',\n    route,\n  },\n  {\n    key: 'howLongBeforeDeposit', // #7\n    titleKey: 'howLongBeforeDeposit.title',\n    contentKey: 'howLongBeforeDeposit.content',\n    route,\n  },\n  {\n    key: 'canIApplyWithExistingLoans', // #8\n    titleKey: 'canIApplyWithExistingLoans.title',\n    contentKey: 'canIApplyWithExistingLoans.content',\n    route,\n  },\n  {\n    key: 'canIRequestAdditional', // #9\n    titleKey: 'canIRequestAdditional.title',\n    contentKey: 'canIRequestAdditional.content',\n    route,\n  },\n  {\n    key: 'canMyOfferExpire', // #10\n    titleKey: 'canMyOfferExpire.title',\n    contentKey: 'canMyOfferExpire.content',\n    route,\n  },\n  {\n    key: 'whatCanFundsBeUsedFor', // #11\n    titleKey: 'whatCanFundsBeUsedFor.title',\n    contentKey: 'whatCanFundsBeUsedFor.content',\n    route,\n  },\n];\n\nconst financingSetupQuestions: Record<FinancingSetup, Question[]> = {\n  CSP: generateFinancingSetupQuestions('CSP', categories, questions),\n  MCA: generateFinancingSetupQuestions('MCA', categories, questions),\n};\n\nexport const useFundingCategory = () => {\n  const { financingSetup } = useFinancingSetup();\n  return categories[financingSetup] ?? categories.MCA;\n};\n\nexport const useFundingQuestions = () => {\n  const { financingSetup } = useFinancingSetup();\n  return financingSetupQuestions[financingSetup] ?? financingSetupQuestions.MCA;\n};\n","import { Icons } from '@finmid/tiger-webapp/components';\nimport { FinancingSetup, RepaymentType } from '@finmid/tiger-webapp/queries';\n\nimport { FaqCategory, Question } from '../../types';\n\nimport { generateFinancingSetupQuestions } from './generateFinancingSetupQuestions';\nimport { useFinancingSetup } from './useFinancingSetup';\n\nconst route = 'overview';\n\nconst categories: Record<FinancingSetup, FaqCategory> = {\n  CSP: {\n    titleKey: 'category.CSP.overview.label',\n    descriptionKey: 'category.CSP.overview.description',\n    Icon: Icons.InfoIcon,\n    route,\n  },\n  MCA: {\n    titleKey: 'category.MCA.overview.label',\n    descriptionKey: 'category.MCA.overview.description',\n    Icon: Icons.InfoIcon,\n    route,\n  },\n};\n\nconst getQuestions: (\n  repaymentType: RepaymentType,\n) => Omit<Question, 'categoryLabelKey'>[] = (repaymentType) => [\n  {\n    key: 'whatIsPlatformCapital', // #1\n    titleKey: 'whatIsPlatformCapital.title',\n    contentKey:\n      repaymentType === 'FIXED'\n        ? `${repaymentType}.whatIsPlatformCapital.content`\n        : 'whatIsPlatformCapital.content',\n    route,\n  },\n  {\n    key: 'whyShouldIUseIt', // #2\n    titleKey: 'whyShouldIUseIt.title',\n    contentKey:\n      repaymentType === 'FIXED'\n        ? `${repaymentType}.whyShouldIUseIt.content`\n        : 'whyShouldIUseIt.content',\n    route,\n  },\n  {\n    key: 'howDoesItWork', // #3\n    titleKey: 'howDoesItWork.title',\n    contentKey:\n      repaymentType === 'FIXED'\n        ? `${repaymentType}.howDoesItWork.content`\n        : 'howDoesItWork.content',\n    route,\n  },\n  {\n    key: 'howDifferentFromCapital', // #14\n    titleKey: 'howDifferentFromCapital.title',\n    contentKey: 'howDifferentFromCapital.content',\n    route,\n  },\n];\n\ntype CachedQuestions = {\n  CSP: {\n    FLEXIBLE: Question[];\n    FIXED: Question[];\n  };\n  MCA: {\n    FLEXIBLE: Question[];\n  };\n};\n\nconst financingSetupQuestions: CachedQuestions = {\n  CSP: {\n    FIXED: generateFinancingSetupQuestions(\n      'CSP',\n      categories,\n      getQuestions('FIXED'),\n    ),\n    FLEXIBLE: generateFinancingSetupQuestions(\n      'CSP',\n      categories,\n      getQuestions('FLEXIBLE'),\n    ),\n  },\n  MCA: {\n    FLEXIBLE: generateFinancingSetupQuestions(\n      'MCA',\n      categories,\n      getQuestions('FLEXIBLE'),\n    ),\n  },\n};\n\nexport const useOverviewCategory = () => {\n  const { financingSetup } = useFinancingSetup();\n  return categories[financingSetup] ?? categories.MCA;\n};\n\nexport const useOverviewQuestions = (): Question[] => {\n  const setup = useFinancingSetup();\n\n  if (setup.repaymentType === 'FIXED') {\n    return financingSetupQuestions[setup.financingSetup]['FIXED'];\n  }\n\n  return financingSetupQuestions[setup.financingSetup][setup.repaymentType];\n};\n","import { Icons } from '@finmid/tiger-webapp/components';\nimport {\n  FinancingSetup,\n  CollectionMethod,\n  RepaymentFrequency,\n} from '@finmid/tiger-webapp/queries';\n\nimport { FaqCategory, Question } from '../../types';\n\nimport { generateFinancingSetupQuestions } from './generateFinancingSetupQuestions';\n\ntype QuestionWithoutCategory = Omit<Question, 'categoryLabelKey'>;\n\nconst route = 'payment-process';\n\nexport const categories: Record<FinancingSetup, FaqCategory> = {\n  CSP: {\n    titleKey: 'category.CSP.process.label',\n    descriptionKey: 'category.CSP.process.description',\n    Icon: Icons.ResetPercentIcon,\n    route,\n  },\n  MCA: {\n    titleKey: 'category.MCA.process.label',\n    descriptionKey: 'category.MCA.process.description',\n    Icon: Icons.ResetPercentIcon,\n    route,\n  },\n};\n\nconst keywordKeys = ['repay', 'repayment'];\n\nconst flexibleQuestions: (\n  collectionMethod: CollectionMethod,\n) => QuestionWithoutCategory[] = (collectionMethod) => [\n  {\n    key: 'howProcessWorks',\n    titleKey: 'howProcessWorks.title',\n    contentKey: `${collectionMethod}.howProcessWorks.content`,\n    keywordKeys,\n    route,\n  },\n  {\n    key: 'howOftenCollected',\n    titleKey: 'howOftenCollected.title',\n    contentKey: 'howOftenCollected.content',\n    keywordKeys,\n    route,\n  },\n  {\n    key: 'howMonitorActivity',\n    titleKey: 'howMonitorActivity.title',\n    contentKey: 'howMonitorActivity.content',\n    keywordKeys,\n    route,\n  },\n  {\n    key: 'whatHappensLessRevenue',\n    titleKey: 'whatHappensLessRevenue.title',\n    contentKey: 'whatHappensLessRevenue.content',\n    keywordKeys,\n    route,\n  },\n  {\n    key: 'isThereMinimumPayment',\n    titleKey: 'isThereMinimumPayment.title',\n    contentKey: 'isThereMinimumPayment.content',\n    keywordKeys,\n    route,\n  },\n  {\n    key: 'howLongPaymentProcess',\n    titleKey: 'howLongPaymentProcess.title',\n    contentKey: 'howLongPaymentProcess.content',\n    keywordKeys,\n    route,\n  },\n  {\n    key: 'canIPayEarly',\n    titleKey: 'canIPayEarly.title',\n    contentKey: 'canIPayEarly.content',\n    keywordKeys,\n    route,\n  },\n  {\n    key: 'isThereCollateral',\n    titleKey: 'isThereCollateral.title',\n    contentKey: 'isThereCollateral.content',\n    keywordKeys,\n    route,\n  },\n  {\n    key: 'canIDeactivate',\n    titleKey: 'canIDeactivate.title',\n    contentKey: 'canIDeactivate.content',\n    keywordKeys,\n    route,\n  },\n];\n\nconst getFixedQuestions: (\n  repaymentFrequency: RepaymentFrequency,\n  collectionMethod: CollectionMethod,\n) => QuestionWithoutCategory[] = (repaymentFrequency, collectionMethod) => [\n  {\n    key: 'howProcessWorks',\n    titleKey: 'howProcessWorks.title',\n    contentKey: `FIXED.${collectionMethod}.howProcessWorks.${repaymentFrequency}.content`,\n    keywordKeys,\n    route,\n  },\n  {\n    key: 'howOftenCollected',\n    titleKey: `howOftenCollected.title`,\n    contentKey: `FIXED.howOftenCollected.${repaymentFrequency}.content`,\n    keywordKeys,\n    route,\n  },\n  {\n    key: 'howMonitorActivity',\n    titleKey: 'howMonitorActivity.title',\n    contentKey: 'howMonitorActivity.content',\n    keywordKeys,\n    route,\n  },\n  {\n    key: 'whatHappensLessRevenue',\n    titleKey: 'whatHappensLessRevenue.title',\n    contentKey: `FIXED.whatHappensLessRevenue.${repaymentFrequency}.content`,\n    keywordKeys,\n    route,\n  },\n  {\n    key: 'howLongPaymentProcess',\n    titleKey: 'howLongPaymentProcess.title',\n    contentKey: 'FIXED.howLongPaymentProcess.content',\n    keywordKeys,\n    route,\n  },\n  {\n    key: 'canIPayEarly',\n    titleKey: 'canIPayEarly.title',\n    contentKey: 'canIPayEarly.content',\n    keywordKeys,\n    route,\n  },\n  {\n    key: 'isThereCollateral',\n    titleKey: 'isThereCollateral.title',\n    contentKey: 'FIXED.isThereCollateral.content',\n    keywordKeys,\n    route,\n  },\n  {\n    key: 'canIDeactivate',\n    titleKey: 'canIDeactivate.title',\n    contentKey: 'canIDeactivate.content',\n    keywordKeys,\n    route,\n  },\n];\n\nconst cacheCspQuestions = (collectionMethod: CollectionMethod) => {\n  return {\n    FIXED: {\n      MONTHLY: generateFinancingSetupQuestions(\n        'CSP',\n        categories,\n        getFixedQuestions('MONTHLY', collectionMethod),\n      ),\n      WEEKLY: generateFinancingSetupQuestions(\n        'CSP',\n        categories,\n        getFixedQuestions('WEEKLY', collectionMethod),\n      ),\n    },\n    FLEXIBLE: generateFinancingSetupQuestions(\n      'CSP',\n      categories,\n      flexibleQuestions(collectionMethod),\n    ),\n  };\n};\n\ntype CachedQuestions = {\n  CSP: {\n    PAY_BY_INVOICE: CSPCachedQuestions;\n    DIRECT_DEBIT: CSPCachedQuestions;\n    PLATFORM_TRANSFER: CSPCachedQuestions;\n    STANDING_ORDER: CSPCachedQuestions;\n  };\n  MCA: {\n    PAY_BY_INVOICE: {\n      FLEXIBLE: Question[];\n    };\n    DIRECT_DEBIT: {\n      FLEXIBLE: Question[];\n    };\n    PLATFORM_TRANSFER: {\n      FLEXIBLE: Question[];\n    };\n    STANDING_ORDER: {\n      FLEXIBLE: Question[];\n    };\n  };\n};\n\ntype CSPCachedQuestions = {\n  FIXED: {\n    MONTHLY: Question[];\n    WEEKLY: Question[];\n  };\n  FLEXIBLE: Question[];\n};\n\nexport const paymentProcessCategoryQuestions: CachedQuestions = {\n  CSP: {\n    PAY_BY_INVOICE: cacheCspQuestions('PAY_BY_INVOICE'),\n    DIRECT_DEBIT: cacheCspQuestions('DIRECT_DEBIT'),\n    PLATFORM_TRANSFER: cacheCspQuestions('PLATFORM_TRANSFER'),\n    STANDING_ORDER: cacheCspQuestions('STANDING_ORDER'),\n  },\n  MCA: {\n    PAY_BY_INVOICE: {\n      FLEXIBLE: generateFinancingSetupQuestions(\n        'MCA',\n        categories,\n        flexibleQuestions('PAY_BY_INVOICE'),\n      ),\n    },\n    DIRECT_DEBIT: {\n      FLEXIBLE: generateFinancingSetupQuestions(\n        'MCA',\n        categories,\n        flexibleQuestions('DIRECT_DEBIT'),\n      ),\n    },\n    PLATFORM_TRANSFER: {\n      FLEXIBLE: generateFinancingSetupQuestions(\n        'MCA',\n        categories,\n        flexibleQuestions('PLATFORM_TRANSFER'),\n      ),\n    },\n    STANDING_ORDER: {\n      FLEXIBLE: generateFinancingSetupQuestions(\n        'MCA',\n        categories,\n        flexibleQuestions('STANDING_ORDER'),\n      ),\n    },\n  },\n};\n","import { useTokenContext } from '@finmid/tiger-webapp/components';\nimport { useGetOffers } from '@finmid/tiger-webapp/queries';\n\nexport const useCollectionMethod = () => {\n  const { token, ignoreAction } = useTokenContext();\n  const { data: availableOffers } = useGetOffers({\n    token,\n    ignoreAction,\n  });\n\n  return (\n    availableOffers?.offerGroup?.collectionMethod ??\n    availableOffers?.latestCredit?.collectionMethod ??\n    'DIRECT_DEBIT'\n  );\n};\n","import { Question } from '../../types';\n\nimport {\n  categories,\n  paymentProcessCategoryQuestions,\n} from './paymentProcessCategoryQuestions';\nimport { useCollectionMethod } from './useCollectionMethod';\nimport { useFinancingSetup } from './useFinancingSetup';\n\nexport const usePaymentProcessCategory = () => {\n  const { financingSetup } = useFinancingSetup();\n  return categories[financingSetup] ?? categories.MCA;\n};\n\nexport const usePaymentProcessQuestions = (): Question[] => {\n  const setup = useFinancingSetup();\n  const collectionMethod = useCollectionMethod();\n\n  if (setup.repaymentType === 'FIXED') {\n    return paymentProcessCategoryQuestions[setup.financingSetup][\n      collectionMethod\n    ]['FIXED'][setup.repaymentFrequency];\n  }\n\n  return (\n    paymentProcessCategoryQuestions[setup.financingSetup][collectionMethod][\n      setup.repaymentType\n    ] ?? paymentProcessCategoryQuestions.MCA[collectionMethod].FLEXIBLE\n  );\n};\n","import { Icons } from '@finmid/tiger-webapp/components';\nimport { FinancingSetup } from '@finmid/tiger-webapp/queries';\n\nimport { FaqCategory, Question } from '../../types';\n\nimport { generateFinancingSetupQuestions } from './generateFinancingSetupQuestions';\nimport { useFinancingSetup } from './useFinancingSetup';\n\nconst route = 'privacy-and-partners';\n\nconst categories: Record<FinancingSetup, FaqCategory> = {\n  CSP: {\n    titleKey: 'category.CSP.partners.label',\n    descriptionKey: 'category.CSP.partners.description',\n    Icon: Icons.LockIcon,\n    route,\n  },\n  MCA: {\n    titleKey: 'category.MCA.partners.label',\n    descriptionKey: 'category.MCA.partners.description',\n    Icon: Icons.LockIcon,\n    route,\n  },\n};\n\nconst questions: Omit<Question, 'categoryLabelKey'>[] = [\n  {\n    key: 'canIOptOut', // #26\n    titleKey: 'canIOptOut.title',\n    contentKey: 'canIOptOut.content',\n    route,\n  },\n  {\n    key: 'whoArePartners', // #27\n    titleKey: 'whoArePartners.title',\n    contentKey: 'whoArePartners.content',\n    route,\n  },\n];\n\nconst financingSetupQuestions: Record<FinancingSetup, Question[]> = {\n  CSP: generateFinancingSetupQuestions('CSP', categories, questions),\n  MCA: generateFinancingSetupQuestions('MCA', categories, questions),\n};\n\nexport const usePrivacyAndPartnersCategory = () => {\n  const { financingSetup } = useFinancingSetup();\n  return categories[financingSetup] ?? categories.MCA;\n};\n\nexport const usePrivacyAndPartnersQuestions = () => {\n  const { financingSetup } = useFinancingSetup();\n  return financingSetupQuestions[financingSetup] ?? financingSetupQuestions.MCA;\n};\n","import { FaqCategory } from '../types';\n\nimport {\n  useCostAndTermsCategory,\n  useEligibilityCategory,\n  useFundingCategory,\n  useOverviewCategory,\n  usePaymentProcessCategory,\n  usePrivacyAndPartnersCategory,\n} from './categories';\n\nexport const useFaqCategories = () => {\n  const overviewCategory = useOverviewCategory();\n  const fundingAndUsageCategory = useFundingCategory();\n  const eligibilityCategory = useEligibilityCategory();\n  const costAndTermsCategory = useCostAndTermsCategory();\n  const paymentProcessCategory = usePaymentProcessCategory();\n  const privacyAndPartnersCategory = usePrivacyAndPartnersCategory();\n\n  const categories: FaqCategory[] = [\n    overviewCategory,\n    eligibilityCategory,\n    fundingAndUsageCategory,\n    costAndTermsCategory,\n    paymentProcessCategory,\n    privacyAndPartnersCategory,\n  ];\n\n  return categories;\n};\n","import { Question } from '../types';\n\nimport {\n  useCostAndTermsQuestions,\n  useEligibilityQuestions,\n  useFundingQuestions,\n  useOverviewQuestions,\n  usePaymentProcessQuestions,\n  usePrivacyAndPartnersQuestions,\n} from './categories';\n\nexport const useFaqQuestions = () => {\n  const overviewQuestions = useOverviewQuestions();\n  const eligibilityQuestions = useEligibilityQuestions();\n  const fundingQuestions = useFundingQuestions();\n  const paymentProcessQuestions = usePaymentProcessQuestions();\n  const costAndTermsQuestions = useCostAndTermsQuestions();\n  const privacyAndPartnersQuestions = usePrivacyAndPartnersQuestions();\n\n  const questions: Question[] = [\n    ...overviewQuestions,\n    ...eligibilityQuestions,\n    ...fundingQuestions,\n    ...costAndTermsQuestions,\n    ...paymentProcessQuestions,\n    ...privacyAndPartnersQuestions,\n  ];\n\n  return questions;\n};\n","import { useTranslation } from 'react-i18next';\n\nexport const useFaqTranslations = () => useTranslation('helpCenter');\n","import groupBy from 'lodash/groupBy';\nimport { useMemo } from 'react';\nimport { useParams } from 'react-router-dom';\n\nimport { useFaqTranslations } from '../hooks';\nimport { useFaqQuestions } from '../hooks';\nimport { FaqCategoryRoute } from '../types';\n\nexport const useFaqsCategoryPage = () => {\n  const { t } = useFaqTranslations();\n\n  const { category } = useParams<{ category: string }>();\n  const questions = useFaqQuestions();\n\n  const list = useMemo(\n    () => groupBy(questions, 'route')[category as FaqCategoryRoute],\n    [questions, category],\n  );\n\n  const label = t(list[0].categoryLabelKey);\n\n  return {\n    category,\n    label,\n    list,\n  };\n};\n","import styled from '@emotion/styled';\nimport { customizeStyles, Flex } from '@finmid/tiger-webapp/components';\n\nexport const FaqsCategoryPageLayout = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    width: '100%',\n    flexDirection: 'column',\n    justifyContent: 'flex-start',\n    alignItems: 'center',\n    flex: 1,\n    padding: vars.components?.variables.spacings.lg,\n\n    [breakpoints.up('desktop')]: {\n      paddingBlock: vars.components?.variables.spacings.xxl,\n\n      justifyContent: 'stretch',\n    },\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (customizations) => customizations?.faqs?.outerLayout,\n    ),\n  }),\n);\n\nexport const FaqsCategoryInnerLayout = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    width: '100%',\n    maxWidth: 792,\n    flexDirection: 'column',\n    alignItems: 'flex-start',\n    rowGap: vars.components?.variables.spacings.xxxl,\n\n    [breakpoints.down('desktop')]: {\n      flexGrow: 1,\n      justifyContent: 'space-between',\n    },\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (customizations) => customizations?.faqs?.layout,\n    ),\n  }),\n);\n","import styled from '@emotion/styled';\nimport {\n  Flex,\n  Typography,\n  useOfferStatus,\n  usePlatformSettings,\n  customizeStyles,\n} from '@finmid/tiger-webapp/components';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nexport const Container = styled(Flex)`\n  flex-direction: column;\n  align-items: flex-start;\n`;\n\nconst StyledButton = styled.button(({ theme }) => ({\n  border: 0,\n  outline: 0,\n  appearance: 'none',\n  background: 'transparent',\n  cursor: 'pointer',\n  paddingBlock: '8px',\n  paddingInline: 0,\n\n  ...customizeStyles(theme, (c) => c?.faqs?.intro?.backButton),\n}));\n\nconst StyledButtonLabel = styled(Typography)``;\n\nexport const BackToAllFaqs = () => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'helpAndFaq' });\n  const navigate = useNavigate();\n  const { hasCurrentCredit } = useOfferStatus();\n  const { slots } = usePlatformSettings();\n\n  const hasCustomBackToOffersWidget = !!slots?.['backToOffers.widget'];\n  const to = hasCurrentCredit ? '/dashboard/help-center' : '/help-and-faqs';\n\n  if (!hasCustomBackToOffersWidget) {\n    return null;\n  }\n\n  return (\n    <StyledButton onClick={() => navigate(to)}>\n      <StyledButtonLabel size=\"sm\" weight=\"strong\" color=\"primaryDefault\">\n        {t('backToAllFaqs', { defaultValue: 'Back to all FAQs' })}\n      </StyledButtonLabel>\n    </StyledButton>\n  );\n};\n","import { Typography } from '@finmid/tiger-webapp/components';\n\nimport { BackToAllFaqs, Container } from './IntroSection.styled';\n\ntype IntroSectionProps = {\n  title: string;\n};\n\nexport const IntroSection = ({ title }: IntroSectionProps) => (\n  <Container>\n    <BackToAllFaqs />\n    <Typography size=\"xxl\" family=\"title\" weight=\"strong\">\n      {title}\n    </Typography>\n  </Container>\n);\n","import { useParams } from 'react-router-dom';\n\nimport { useFaqCategories } from '../../../../../hooks';\nimport { FaqCategory } from '../../../../../types';\n\ntype GetSiblingsCategoriesProps = {\n  categories: FaqCategory[];\n  currentIndex: number;\n};\n\nconst getSiblingsCategories = ({\n  categories,\n  currentIndex,\n}: GetSiblingsCategoriesProps) => {\n  const previous = currentIndex === 0 ? null : categories[currentIndex - 1];\n  const next =\n    currentIndex === categories.length - 1\n      ? null\n      : categories[currentIndex + 1];\n\n  return {\n    previous,\n    next,\n  };\n};\n\nexport const useCategoryNavigation = () => {\n  const { category } = useParams<{ category: string }>();\n  const categories = useFaqCategories();\n  const currentIndex = categories.findIndex((c) => c.route === category);\n  const siblings = getSiblingsCategories({ categories, currentIndex });\n  return siblings;\n};\n","import { Button, Icons, useResponsive } from '@finmid/tiger-webapp/components';\nimport { useNavigate } from 'react-router-dom';\n\nimport { useFaqTranslations } from '../../../../../hooks';\nimport { FaqCategory } from '../../../../../types';\n\ntype Props = {\n  toCategory: FaqCategory | null;\n  direction: 'previous' | 'next';\n};\n\nexport const NavigationButton = ({ direction, toCategory }: Props) => {\n  const { t } = useFaqTranslations();\n\n  const navigate = useNavigate();\n  const { isMobile } = useResponsive();\n\n  if (toCategory == null) {\n    return null;\n  }\n\n  return (\n    <Button\n      variant=\"invisible\"\n      onClick={() => navigate(`/help-and-faqs/${toCategory.route}`)}\n      startIcon={direction === 'previous' && <Icons.ArrowBackIcon />}\n      endIcon={direction === 'next' && <Icons.ArrowForwardIcon />}\n    >\n      {isMobile ? null : t(toCategory.titleKey)}\n    </Button>\n  );\n};\n","import styled from '@emotion/styled';\nimport { Flex } from '@finmid/tiger-webapp/components';\n\nimport { FaqCategory } from '../../../../../types';\n\nimport { useCategoryNavigation } from './CategoryNavigation.hook';\nimport { NavigationButton } from './NavigationButton';\n\nconst Container = styled(Flex)<{ previous: FaqCategory | null }>(\n  ({ previous }) => ({\n    width: '100%',\n    justifyContent: previous == null ? 'flex-end' : 'space-between',\n  }),\n);\n\nexport const CategoryNavigation = () => {\n  const siblings = useCategoryNavigation();\n  return (\n    <Container previous={siblings.previous}>\n      <NavigationButton direction=\"previous\" toCategory={siblings.previous} />\n      <NavigationButton direction=\"next\" toCategory={siblings.next} />\n    </Container>\n  );\n};\n","import styled from '@emotion/styled';\nimport { customizeStyles, Icons } from '@finmid/tiger-webapp/components';\nimport {\n  Accordion,\n  AccordionDetails,\n  AccordionSummary,\n  AccordionSummaryProps,\n  accordionClasses,\n  accordionSummaryClasses,\n} from '@mui/material';\n\nexport const QuestionListWrapper = styled.div(\n  ({ theme: { vars, breakpoints } }) => ({\n    border: `1px solid ${vars.components?.variables.colors.grey300}`,\n    borderRadius: vars.components?.variables.radius.md,\n    overflow: 'hidden',\n\n    ...customizeStyles({ vars, breakpoints }, (c) => c?.faqs?.questionList),\n  }),\n);\n\nexport const QuestionAccordion = styled(Accordion)(\n  ({ theme: { vars, breakpoints } }) => ({\n    [`&.${accordionClasses.root}`]: {\n      borderBottom: `1px solid ${vars.components?.variables.colors?.grey300}`,\n      padding: vars.components?.variables.spacings.md,\n      width: '100%',\n\n      boxShadow: 'none',\n      margin: 0,\n\n      '&::before': {\n        display: 'none',\n      },\n\n      '&:last-of-type': {\n        border: 0,\n      },\n\n      ...customizeStyles(\n        { vars, breakpoints },\n        (c) => c?.faqs?.question?.container,\n      ),\n    },\n  }),\n);\n\nexport const QuestionTitle = styled((props: AccordionSummaryProps) => (\n  <AccordionSummary\n    {...props}\n    expandIcon={<Icons.ChevronRightIcon height={26} width={26} />}\n  />\n))(({ theme }) => ({\n  fontFamily: theme.vars.components?.variables.typography?.desktop.family.body,\n\n  fontSize: theme.vars.components?.variables.typography?.desktop.size.md,\n  fontWeight:\n    theme.vars.components?.variables.typography?.desktop.weight?.strong,\n  lineHeight:\n    theme.vars.components?.variables.typography?.desktop.lineHeight.md,\n\n  display: 'flex',\n  flexDirection: 'row-reverse',\n  alignItems: 'center',\n  gap: theme.vars.components?.variables.spacings.sm,\n\n  [theme.breakpoints.only('mobile')]: {\n    fontSize: theme.vars.components?.variables.typography?.mobile.size.md,\n    fontWeight:\n      theme.vars.components?.variables.typography?.mobile.weight?.strong,\n    lineHeight:\n      theme.vars.components?.variables.typography?.mobile.lineHeight.md,\n  },\n\n  [`&.${accordionSummaryClasses.root}`]: {\n    padding: 0,\n    minHeight: 'auto',\n  },\n\n  [`& > .${accordionSummaryClasses.content}`]: {\n    margin: '0',\n\n    [`&.${accordionSummaryClasses.expanded}`]: {\n      margin: '0',\n    },\n  },\n\n  [`& .${accordionSummaryClasses.expandIconWrapper}`]: {\n    alignSelf: 'flex-start',\n\n    '& svg': {\n      color: theme.vars.components?.variables.colors?.grey900,\n    },\n\n    [`&.${accordionSummaryClasses.expanded}`]: {\n      transform: 'rotate(90deg)',\n    },\n\n    ...customizeStyles(theme, (c) => c?.faqs?.question?.expandIcon),\n  },\n\n  ...customizeStyles(theme, (c) => c?.faqs?.question?.title),\n}));\n\nexport const QuestionContent = styled(AccordionDetails)(({ theme }) => ({\n  fontSize: theme.vars.components?.variables.typography?.desktop.size.sm,\n  lineHeight:\n    theme.vars.components?.variables.typography?.desktop.lineHeight?.sm,\n  padding: `${theme.vars.components?.variables.spacings.sm} 0 0 ${theme.vars.components?.variables.spacings.xl}`,\n\n  [theme.breakpoints.only('mobile')]: {\n    fontSize: theme.vars.components?.variables.typography?.mobile.size.sm,\n    lineHeight:\n      theme.vars.components?.variables.typography?.mobile.lineHeight?.sm,\n  },\n\n  '> ol': {\n    paddingInlineStart: '24px',\n  },\n\n  ...customizeStyles(theme, (c) => c?.faqs?.question?.content),\n}));\n\nexport const UnstyledLink = styled('a')(({ theme: { vars } }) => ({\n  textDecoration: 'none',\n  color: vars.components?.variables.colors.grey900,\n}));\n","import styled from '@emotion/styled';\nimport {\n  customizeStyles,\n  Flex,\n  Typography,\n} from '@finmid/tiger-webapp/components';\n\nexport const Container = styled(Flex)(({ theme: { vars, breakpoints } }) => ({\n  flexDirection: 'column',\n  alignItems: 'flex-start',\n  rowGap: vars.components?.variables.spacings.md,\n  width: '100%',\n  maxWidth: 384,\n\n  ...customizeStyles(\n    { vars, breakpoints },\n    (customizations) => customizations?.faqs?.question?.feedback?.container,\n  ),\n}));\n\nexport const ButtonsContainer = styled(Flex)(({ theme: { vars } }) => ({\n  justifyContent: 'flex-start',\n  columnGap: vars.components?.variables.spacings.sm,\n\n  '& button': {\n    flex: '1 1 0',\n  },\n}));\n\nexport const Title = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(theme, (c) => c?.faqs?.question?.title),\n}));\n","import { Button } from '@finmid/tiger-webapp/components';\nimport { useTranslation } from 'react-i18next';\n\nimport { ProvideFeedbackFn } from './FeedbackSection.hook';\nimport { ButtonsContainer, Container, Title } from './FeedbackSection.styled';\n\ntype FeedbackSectionProps = {\n  questionKey: string;\n  isAnswered: boolean;\n  provideFeedback: ProvideFeedbackFn;\n};\n\nexport const FeedbackSection = ({\n  isAnswered,\n  questionKey,\n  provideFeedback,\n}: FeedbackSectionProps) => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'helpAndFaq.feedback' });\n\n  if (isAnswered) {\n    return (\n      <Title size=\"sm\" weight=\"strong\">\n        {t('sent', { defaultValue: 'Thank you for your feedback.' })}\n      </Title>\n    );\n  }\n\n  return (\n    <Container>\n      <Title size=\"sm\" weight=\"strong\">\n        {t('title', { defaultValue: 'Was this answer helpful?' })}\n      </Title>\n      <ButtonsContainer>\n        <Button\n          variant=\"secondary\"\n          onClick={() => provideFeedback({ questionKey, useful: true })}\n        >\n          {t('useful', { defaultValue: 'Yes' })}\n        </Button>\n        <Button\n          variant=\"secondary\"\n          onClick={() => provideFeedback({ questionKey, useful: false })}\n        >\n          {t('notUseful', { defaultValue: 'No' })}\n        </Button>\n      </ButtonsContainer>\n    </Container>\n  );\n};\n","import { useCapturePosthogEvent } from '@finmid/tiger-webapp/components';\nimport { useCallback } from 'react';\nimport { useSessionStorage } from 'react-use';\n\nexport type FeedbackStorage = Record<string, boolean>;\n\ntype FeedbackFnProps = { questionKey: string; useful: boolean };\nexport type ProvideFeedbackFn = (props: FeedbackFnProps) => void;\n\nexport const useProvideFaqFeedback = () => {\n  const capturePosthogEvent = useCapturePosthogEvent();\n  const [faqFeedback, setFaqFeedback] = useSessionStorage<FeedbackStorage>(\n    'faq-feedback',\n    {},\n  );\n\n  const storeFeedback: ProvideFeedbackFn = useCallback(\n    ({ questionKey, useful }) => {\n      const updatedFeedback: FeedbackStorage = {\n        ...faqFeedback,\n        [questionKey]: useful,\n      };\n      setFaqFeedback(updatedFeedback);\n    },\n    [faqFeedback, setFaqFeedback],\n  );\n\n  const recordFeedback = useCallback(\n    ({ questionKey, useful }: FeedbackFnProps) => {\n      capturePosthogEvent('User submitted faq feedback', {\n        questionKey,\n        useful,\n      });\n    },\n    [capturePosthogEvent],\n  );\n\n  const provideFaqFeedback: ProvideFeedbackFn = useCallback(\n    (props) => {\n      recordFeedback(props);\n      storeFeedback(props);\n    },\n    [recordFeedback, storeFeedback],\n  );\n\n  return { faqFeedback, provideFaqFeedback };\n};\n","import { useTheme } from '@emotion/react';\nimport {\n  Spacer,\n  useCapturePosthogEvent,\n} from '@finmid/tiger-webapp/components';\nimport { TFunction } from 'i18next';\nimport { SyntheticEvent, useEffect, useRef } from 'react';\nimport { Trans } from 'react-i18next';\nimport { useLocation } from 'react-router-dom';\n\nimport {\n  QuestionAccordion,\n  QuestionTitle,\n  QuestionContent,\n  UnstyledLink,\n} from './QuestionsList.styled';\nimport { FeedbackSection, type ProvideFeedbackFn } from './components';\n\ntype QuestionProps = {\n  content: string;\n  id: string;\n  title: string;\n  isAnswered: boolean;\n  provideFeedback: ProvideFeedbackFn;\n};\n\nexport const Question = ({\n  content,\n  id,\n  isAnswered,\n  title,\n  provideFeedback,\n}: QuestionProps) => {\n  const capturePosthogEvent = useCapturePosthogEvent();\n  const { vars } = useTheme();\n  const { hash } = useLocation();\n\n  const questionRef = useRef<HTMLDivElement>(null);\n\n  useEffect(() => {\n    if (hash.endsWith(id) && questionRef.current != null) {\n      questionRef.current.scrollIntoView(false);\n    }\n  }, [hash, id]);\n\n  const captureOpenQuestionEvent = (\n    _: SyntheticEvent<Element, Event>,\n    expanded: boolean,\n  ) => {\n    if (expanded) {\n      capturePosthogEvent('User opened FAQ', { id });\n    }\n  };\n\n  return (\n    <QuestionAccordion\n      ref={questionRef}\n      id={id}\n      defaultExpanded={hash.endsWith(id)}\n      onChange={captureOpenQuestionEvent}\n    >\n      <QuestionTitle>{title}</QuestionTitle>\n      <QuestionContent>\n        <Trans\n          t={((s: string) => s) as TFunction}\n          i18nKey={content}\n          components={{\n            br: <br />,\n            ul: <ul />,\n            ol: <ol />,\n            li: <li />,\n            bold: <strong />,\n            a: <UnstyledLink />,\n          }}\n        />\n        <Spacer height={vars.components?.variables.spacings.xl} />\n        <FeedbackSection\n          isAnswered={isAnswered}\n          questionKey={id}\n          provideFeedback={provideFeedback}\n        />\n      </QuestionContent>\n    </QuestionAccordion>\n  );\n};\n","import { useFaqTranslations } from '../../../../../hooks';\nimport { Question as QuestionType } from '../../../../../types';\n\nimport { Question } from './Question';\nimport { QuestionListWrapper } from './QuestionsList.styled';\nimport { useProvideFaqFeedback } from './components';\n\ntype QuestionsListProps = {\n  questions: QuestionType[];\n};\n\nexport const QuestionsList = ({ questions }: QuestionsListProps) => {\n  const { t } = useFaqTranslations();\n\n  const { faqFeedback, provideFaqFeedback } = useProvideFaqFeedback();\n\n  return (\n    <QuestionListWrapper>\n      {questions.map(({ key, contentKey, titleKey }) => (\n        <Question\n          key={key}\n          id={key}\n          content={t(contentKey)}\n          title={t(titleKey)}\n          provideFeedback={provideFaqFeedback}\n          isAnswered={faqFeedback?.[key] != null}\n        />\n      ))}\n    </QuestionListWrapper>\n  );\n};\n","import styled from '@emotion/styled';\nimport { Flex } from '@finmid/tiger-webapp/components';\n\nimport { Question } from '../../../types';\n\nimport { CategoryNavigation, QuestionsList } from './components';\n\nconst Container = styled(Flex)(({ theme: { vars } }) => ({\n  flexDirection: 'column',\n  rowGap: vars.components?.variables.spacings.xl,\n}));\n\ntype QuestionsSectionProps = {\n  questions: Question[];\n};\n\nexport const QuestionsSection = ({ questions }: QuestionsSectionProps) => {\n  return (\n    <Container>\n      <QuestionsList questions={questions} />\n      <CategoryNavigation />\n    </Container>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport {\n  CustomisationSlot,\n  Flex,\n  Spacer,\n  useMessenger,\n  useResponsive,\n} from '@finmid/tiger-webapp/components';\n\nimport { useFaqsCategoryPage } from '../../FaqsCategoryPage.hook';\nimport { IntroSection } from '../IntroSection';\nimport { QuestionsSection } from '../QuestionsSection';\n\nconst Container = styled(Flex)(({ theme: { vars } }) => ({\n  flexDirection: 'column',\n  rowGap: vars.components?.variables.spacings.xxl,\n  alignItems: 'flex-start',\n}));\n\nexport const QuestionsListSection = () => {\n  const { isMobile } = useResponsive();\n  const { isEmbedded } = useMessenger();\n  const { vars } = useTheme();\n  const { label, list } = useFaqsCategoryPage();\n\n  return (\n    <Container>\n      <CustomisationSlot\n        slot=\"faqs.introSection\"\n        props={{}}\n        fallback={<IntroSection title={label} />}\n      />\n      <QuestionsSection questions={list} />\n      {isMobile || isEmbedded ? null : (\n        <Spacer height={vars.components?.variables.spacings.xxxl} />\n      )}\n    </Container>\n  );\n};\n","import {\n  BackToOffersWidget,\n  useResponsive,\n} from '@finmid/tiger-webapp/components';\nimport { Navigate } from 'react-router-dom';\n\nimport { useFaqsCategoryPage } from './FaqsCategoryPage.hook';\nimport {\n  FaqsCategoryPageLayout,\n  FaqsCategoryInnerLayout,\n} from './FaqsCategoryPage.styled';\nimport { QuestionsListSection } from './components';\n\nexport const FaqsCategoryPageInner = () => {\n  const { isMobile } = useResponsive();\n  const offersRoute = isMobile ? '/overview?step=selectOffer' : '/overview';\n\n  return (\n    <FaqsCategoryPageLayout>\n      <FaqsCategoryInnerLayout>\n        <QuestionsListSection />\n        <BackToOffersWidget to={offersRoute} />\n      </FaqsCategoryInnerLayout>\n    </FaqsCategoryPageLayout>\n  );\n};\n\nexport const FaqsCategoryPage = () => {\n  const { category, label, list } = useFaqsCategoryPage();\n\n  if (category == null || list == null || label == null) {\n    return <Navigate to=\"/help-and-faqs\" replace />;\n  }\n\n  return <FaqsCategoryPageInner />;\n};\n","import styled from '@emotion/styled';\nimport { customizeStyles, Flex } from '@finmid/tiger-webapp/components';\n\nexport const HelpAndFaqPageLayout = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    width: '100%',\n    flexDirection: 'column',\n    justifyContent: 'flex-start',\n    alignItems: 'center',\n    flex: 1,\n    padding: vars.components?.variables.spacings.lg,\n\n    [breakpoints.up('desktop')]: {\n      paddingBlock: vars.components?.variables.spacings.xxl,\n    },\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (customizations) => customizations?.faqs?.outerLayout,\n    ),\n  }),\n);\n\nexport const HelpAndFaqInnerLayout = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    width: '100%',\n    maxWidth: 792,\n    flexDirection: 'column',\n    alignItems: 'flex-start',\n    rowGap: vars.components?.variables.spacings.xxxl,\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (customizations) => customizations?.faqs?.layout,\n    ),\n  }),\n);\n","import styled from '@emotion/styled';\nimport { customizeStyles } from '@finmid/tiger-webapp/components';\nimport { Box } from '@mui/material';\n\nexport const CategoriesContainer = styled(Box)(\n  ({ theme: { vars, breakpoints } }) => ({\n    width: '100%',\n    display: 'grid',\n    gridTemplateColumns: '1fr 1fr 1fr',\n    gap: vars.components?.variables.spacings.md,\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (customizations) => customizations?.faqs?.categoriesContainer,\n    ),\n  }),\n);\n","import styled from '@emotion/styled';\nimport {\n  customizeStyles,\n  Flex,\n  Typography,\n} from '@finmid/tiger-webapp/components';\n\nexport const Card = styled(Flex)<{ reversed: boolean }>(\n  ({ theme: { vars, breakpoints }, reversed }) => ({\n    flexDirection: 'column',\n    justifyContent: 'flex-start',\n    alignItems: 'flex-start',\n    rowGap: vars.components?.variables.spacings.md,\n    padding: vars.components?.variables.spacings.md,\n    borderRadius: vars.components?.variables.radius.md,\n    border: `1px solid ${vars.components?.variables.colors.grey300}`,\n    backgroundColor: reversed\n      ? vars.components?.variables.colors.white\n      : vars.components?.variables.colors.grey100,\n\n    '&:hover': {\n      cursor: 'pointer',\n    },\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (customizations) => customizations?.faqs?.categories?.card,\n    ),\n  }),\n);\n\nexport const CardDescriptionContainer = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    flexDirection: 'column',\n    alignItems: 'flex-start',\n    rowGap: vars.components?.variables.spacings.xs,\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (customizations) =>\n        customizations?.faqs?.categories?.cardDescriptionContainer,\n    ),\n  }),\n);\n\nexport const CardTitle = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(\n    theme,\n    (customizations) => customizations?.faqs?.categories?.cardTitle,\n  ),\n}));\n\nexport const CardDescription = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(\n    theme,\n    (customizations) => customizations?.faqs?.categories?.cardDescription,\n  ),\n}));\n\nexport const IconWrapper = styled(Flex)<{ reversed: boolean }>(\n  ({ theme: { vars }, reversed }) => {\n    const iw = vars.components?.faqs?.categories?.iconWrapper;\n    const iconColor = String(\n      iw?.desktop?.color ??\n        iw?.mobile?.color ??\n        vars.components?.variables.colors.primaryDefault,\n    );\n    const defaultBorderColor = reversed\n      ? vars.components?.variables.colors.primaryDefault\n      : vars.components?.variables.colors.white;\n\n    return {\n      placeContent: 'center',\n      width: 48,\n      height: 48,\n      backgroundColor: vars.components?.variables.colors.white,\n      borderRadius: vars.components?.variables.radius.md,\n      color: iconColor,\n      padding: 12,\n      borderColor: String(\n        iw?.desktop?.borderColor ??\n          iw?.mobile?.borderColor ??\n          defaultBorderColor,\n      ),\n      borderStyle: 'solid',\n      borderWidth: '1px',\n    };\n  },\n);\n","import { CustomisationSlot } from '@finmid/tiger-webapp/components';\nimport { useNavigate } from 'react-router-dom';\n\nimport { useFaqTranslations } from '../../../../../../hooks';\nimport { FaqCategory } from '../../../../../../types';\n\nimport {\n  Card,\n  CardDescription,\n  CardDescriptionContainer,\n  CardTitle,\n  IconWrapper,\n} from './QuestionCategoryDesktop.styled';\n\ntype QuestionCategoryDesktopProps = FaqCategory & {\n  reversed?: boolean;\n};\n\nexport const QuestionCategoryDesktop = ({\n  titleKey,\n  descriptionKey,\n  route,\n  Icon,\n  reversed = false,\n}: QuestionCategoryDesktopProps) => {\n  const { t } = useFaqTranslations();\n\n  const navigate = useNavigate();\n  const navigateToCategory = () => {\n    navigate(`/help-and-faqs/${route}`);\n  };\n\n  return (\n    <Card onClick={navigateToCategory} reversed={reversed}>\n      <IconWrapper reversed={reversed}>\n        <CustomisationSlot\n          slot=\"faqs.categories.card.icon\"\n          props={{}}\n          fallback={<Icon width={24} height={24} color=\"currentColor\" />}\n        />\n      </IconWrapper>\n      <CardDescriptionContainer>\n        <CardTitle size=\"md\" weight=\"strong\">\n          {t(titleKey)}\n        </CardTitle>\n        <CardDescription size=\"sm\">{t(descriptionKey)}</CardDescription>\n      </CardDescriptionContainer>\n    </Card>\n  );\n};\n","import { useFaqCategories } from '../../../../../hooks';\n\nimport { CategoriesContainer } from './QuestionsCategoriesDesktop.styled';\nimport { QuestionCategoryDesktop } from './components';\n\ntype QuestionsCategoriesDeskopProps = {\n  reversed?: boolean;\n};\n\nexport const QuestionsCategoriesDesktop = ({\n  reversed,\n}: QuestionsCategoriesDeskopProps) => {\n  const categories = useFaqCategories();\n  return (\n    <CategoriesContainer>\n      {categories.map((category, index) => (\n        <QuestionCategoryDesktop\n          {...category}\n          reversed={reversed}\n          key={index}\n        />\n      ))}\n    </CategoriesContainer>\n  );\n};\n","import styled from '@emotion/styled';\nimport { Flex } from '@finmid/tiger-webapp/components';\n\nexport const CategoriesContainer = styled(Flex)(({ theme: { vars } }) => ({\n  flexDirection: 'column',\n  alignItems: 'flex-start',\n  rowGap: vars.components?.variables.spacings.md,\n}));\n","import styled from '@emotion/styled';\nimport {\n  customizeStyles,\n  Flex,\n  Typography,\n} from '@finmid/tiger-webapp/components';\n\nexport const Card = styled(Flex)(({ theme: { vars, breakpoints } }) => ({\n  columnGap: vars.components?.variables.spacings.md,\n  width: '100%',\n  justifyContent: 'flex-start',\n\n  ...customizeStyles(\n    { vars, breakpoints },\n    (customizations) => customizations?.faqs?.categories?.card,\n  ),\n}));\n\nexport const CardDescriptionContainer = styled(Flex)(({ theme: { vars } }) => ({\n  flexDirection: 'column',\n  alignItems: 'flex-start',\n  rowGap: vars.components?.variables.spacings.xs,\n  flexGrow: 1,\n}));\n\nexport const CardTitle = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(\n    theme,\n    (customizations) => customizations?.faqs?.categories?.cardTitle,\n  ),\n}));\n\nexport const CardDescription = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(\n    theme,\n    (customizations) => customizations?.faqs?.categories?.cardDescription,\n  ),\n}));\n\nexport const IconWrapper = styled(Flex)(({ theme: { vars, breakpoints } }) => {\n  const iw = vars.components?.faqs?.categories?.iconWrapper;\n  const iconColor = String(\n    iw?.mobile?.color ?? vars.components?.variables.colors.primaryDefault,\n  );\n\n  return {\n    alignSelf: 'flex-start',\n    width: 32,\n    height: 32,\n    placeContent: 'center',\n    borderRadius: '8px',\n    backgroundColor: vars.components?.variables.colors.grey100,\n    color: iconColor,\n    padding: 8,\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (customizations) => customizations?.faqs?.categories?.iconWrapper,\n    ),\n  };\n});\n","import {\n  Button,\n  Icons,\n  useCapturePosthogEvent,\n  useMessenger,\n} from '@finmid/tiger-webapp/components';\nimport { useNavigate } from 'react-router-dom';\n\nimport { useFaqTranslations } from '../../../../../../hooks';\nimport { FaqCategory } from '../../../../../../types';\n\nimport {\n  Card,\n  CardDescription,\n  CardDescriptionContainer,\n  CardTitle,\n  IconWrapper,\n} from './QuestionCategoryMobile.styled';\n\nexport const QuestionCategoryMobile = ({\n  titleKey,\n  descriptionKey,\n  Icon,\n  route,\n}: FaqCategory) => {\n  const { t } = useFaqTranslations();\n\n  const capturePosthogEvent = useCapturePosthogEvent();\n  const navigate = useNavigate();\n  const navigateToCategory = () => {\n    capturePosthogEvent('User navigated to FAQs detail page', { route });\n    navigate(`/help-and-faqs/${route}`);\n  };\n  const { isEmbedded } = useMessenger();\n\n  return (\n    <Card onClick={navigateToCategory}>\n      <IconWrapper data-test-id=\"icon-wrapper\">\n        <Icon width={16} height={16} color=\"currentColor\" />\n      </IconWrapper>\n      <CardDescriptionContainer>\n        <CardTitle size=\"md\" weight=\"strong\">\n          {t(titleKey)}\n        </CardTitle>\n        <CardDescription size=\"sm\">{t(descriptionKey)}</CardDescription>\n      </CardDescriptionContainer>\n      <Button variant=\"invisible\" size=\"medium\">\n        {isEmbedded ? (\n          <Icons.IconLeft width={20} height={20} />\n        ) : (\n          <Icons.ChevronRightIcon width={23} height={23} />\n        )}\n      </Button>\n    </Card>\n  );\n};\n","import { useFaqCategories } from '../../../../../hooks';\n\nimport { CategoriesContainer } from './QuestionsCategoriesMobile.styled';\nimport { QuestionCategoryMobile } from './components';\n\nexport const QuestionsCategoriesMobile = () => {\n  const categories = useFaqCategories();\n  return (\n    <CategoriesContainer>\n      {categories.map((category, index) => (\n        <QuestionCategoryMobile {...category} key={index} />\n      ))}\n    </CategoriesContainer>\n  );\n};\n","import { useResponsive } from '@finmid/tiger-webapp/components';\n\nimport {\n  QuestionsCategoriesDesktop,\n  QuestionsCategoriesMobile,\n} from './components';\n\ntype QuestionCategoriesProps = {\n  reversed?: boolean;\n};\n\nexport const QuestionCategories = ({ reversed }: QuestionCategoriesProps) => {\n  const { isMobile } = useResponsive();\n\n  return isMobile ? (\n    <QuestionsCategoriesMobile />\n  ) : (\n    <QuestionsCategoriesDesktop reversed={reversed} />\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  customizeStyles,\n  Flex,\n  Typography,\n} from '@finmid/tiger-webapp/components';\n\nexport const Container = styled(Flex)(({ theme: { vars, breakpoints } }) => ({\n  width: '100%',\n  maxWidth: 588,\n  flexDirection: 'column',\n  alignItems: 'flex-start',\n  alignSelf: 'flex-start',\n  rowGap: vars.components?.variables.spacings.md,\n\n  ...customizeStyles(\n    { vars, breakpoints },\n    (customizations) => customizations?.faqs?.search?.container,\n  ),\n}));\n\nexport const Title = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(\n    theme,\n    (customizations) => customizations?.faqs?.search?.title,\n  ),\n}));\n","import { useCapturePosthogEvent } from '@finmid/tiger-webapp/components';\nimport Fuse from 'fuse.js';\nimport groupBy from 'lodash/groupBy';\nimport { useMemo, useState } from 'react';\nimport { useNavigate } from 'react-router-dom';\n\nimport { useFaqQuestions, useFaqTranslations } from '../../../../../hooks';\n\nimport { type Results } from './SearchResults';\n\nexport const useSearchFaqs = () => {\n  const questions = useFaqQuestions();\n  const {\n    t,\n    i18n: { language },\n  } = useFaqTranslations();\n\n  const translatedQuestions = useMemo(\n    () =>\n      questions.map((question) => ({\n        ...question,\n        title: t(question.titleKey),\n        content: t(question.contentKey),\n        categoryLabel: t(question.categoryLabelKey),\n        keywords: question.keywordKeys?.map((keywordKey) => t(keywordKey)),\n        language,\n      })),\n    [questions, t, language],\n  );\n\n  const keys: Array<keyof (typeof translatedQuestions)[0]> = [\n    'title',\n    'keywords',\n  ];\n\n  const fuse = new Fuse(translatedQuestions, {\n    keys: keys,\n    threshold: 0.3, // TODO adjust level?\n  });\n  const allQuestionsSorted = groupBy(translatedQuestions, 'category');\n\n  return { fuse, allQuestionsSorted };\n};\n\nexport const useKeyboardNavigation = ({ results }: { results: Results }) => {\n  const capturePosthogEvent = useCapturePosthogEvent();\n  const [focusedIndex, setFocusedIndex] = useState<number>(-1);\n  const navigate = useNavigate();\n\n  const titles = useMemo(() => Object.values(results).flat(), [results]);\n\n  const handleKeyDown = (e: React.KeyboardEvent) => {\n    if (!titles.length) return;\n\n    switch (e.key) {\n      case 'ArrowDown':\n        e.preventDefault();\n        setFocusedIndex((prev) => (prev + 1) % titles.length);\n        break;\n      case 'ArrowUp':\n        e.preventDefault();\n        setFocusedIndex((prev) => (prev - 1 + titles.length) % titles.length);\n        break;\n      case 'Enter':\n        if (focusedIndex >= 0) {\n          const question = titles[focusedIndex];\n          capturePosthogEvent('User selected question', { id: question.key });\n          navigate(`/help-and-faqs/${question.route}#${question.key}`);\n        }\n        break;\n      default:\n    }\n  };\n\n  return {\n    focusedIndex,\n    handleKeyDown,\n    setFocusedIndex,\n  };\n};\n","import styled from '@emotion/styled';\nimport { customizeStyles } from '@finmid/tiger-webapp/components';\nimport { Popper } from '@mui/material';\n\nexport const StyledPopper = styled(Popper)(({ theme }) => ({\n  width: '100%',\n  maxWidth: 588,\n\n  ...customizeStyles(\n    theme,\n    (customizations) => customizations?.faqs?.search?.results?.container,\n  ),\n}));\n","import styled from '@emotion/styled';\nimport {\n  customizeStyles,\n  Flex,\n  Typography,\n} from '@finmid/tiger-webapp/components';\nimport { Box } from '@mui/material';\nimport { Link } from 'react-router-dom';\n\nexport const Container = styled(Box)(({ theme: { vars, breakpoints } }) => ({\n  flexDirection: 'column',\n  background: vars.components?.variables.colors.white,\n  border: `1px solid ${vars.components?.variables.colors.grey300}`,\n  borderRadius: vars.components?.variables.radius.md,\n  boxShadow:\n    '0px 4px 12px 0px rgba(0, 0, 0, 0.10), 0px 1px 3px 0px rgba(0, 0, 0, 0.06)',\n  overflow: 'scroll',\n  marginTop: '8px',\n  maxHeight: 588,\n\n  [breakpoints.down('desktop')]: {\n    width: `calc(100% - ${vars.components?.variables.spacings.lg} - ${vars.components?.variables.spacings.lg})`,\n    marginInlineStart: vars.components?.variables.spacings.lg,\n    maxHeight: 486,\n  },\n\n  ...customizeStyles(\n    { vars, breakpoints },\n    (customizations) => customizations?.faqs?.search?.results?.container,\n  ),\n}));\n\nexport const CategoryContainer = styled(Flex)<{ isLast: boolean }>(\n  ({ theme: { vars, breakpoints }, isLast }) => ({\n    width: '100%',\n    flexDirection: 'column',\n    alignItems: 'stretch',\n    rowGap: vars.components?.variables.spacings.md,\n    borderBottom: isLast\n      ? 'none'\n      : `1px solid ${vars.components?.variables.colors.grey300}`,\n    padding: vars.components?.variables.spacings.md,\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (customizations) =>\n        customizations?.faqs?.search?.results?.categoryContainer,\n    ),\n  }),\n);\n\nexport const TitlesContainer = styled(Flex)(({ theme: { vars } }) => ({\n  flexDirection: 'column',\n  alignItems: 'flex-start',\n  rowGap: vars.components?.variables.spacings.sm,\n}));\n\nexport const StyledLink = styled(Link)`\n  width: 100%;\n  text-decoration: none;\n`;\n\nexport const Title = styled(Typography)<{ isFocused: boolean }>(\n  ({ theme: { vars }, isFocused }) => ({\n    color: isFocused\n      ? vars.components?.variables.colors.primaryAccent\n      : vars.components?.variables.colors.grey900,\n  }),\n);\n\nexport const EmptyResults = styled(Flex)(({ theme: { vars } }) => ({\n  justifyContent: 'flex-start',\n  padding: vars.components?.variables.spacings.md,\n}));\n","import styled from '@emotion/styled';\nimport { customizeStyles, Typography } from '@finmid/tiger-webapp/components';\nimport { useTranslation } from 'react-i18next';\n\nimport { Container, EmptyResults } from './SearchResults.styled';\n\nconst StyledLabel = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(\n    theme,\n    (customizations) => customizations?.faqs?.search?.results?.empty,\n  ),\n}));\n\nexport const NoResults = () => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'helpAndFaq' });\n\n  return (\n    <Container>\n      <EmptyResults>\n        <StyledLabel size=\"xs\" weight=\"strong\">\n          {t('noResults', {\n            defaultValue:\n              'Sorry, we couldn’t find any questions related to your search.',\n          })}\n        </StyledLabel>\n      </EmptyResults>\n    </Container>\n  );\n};\n","import { useCapturePosthogEvent } from '@finmid/tiger-webapp/components';\nimport { Dispatch, SetStateAction } from 'react';\n\nimport { useFaqTranslations } from '../../../../../hooks';\nimport { Question } from '../../../../../types';\n\nimport { StyledLink, Title } from './SearchResults.styled';\n\nexport const TitleLink = ({\n  v,\n  i,\n  isFocused,\n  setFocusedIndex,\n}: {\n  v: Question;\n  i: number;\n  isFocused: boolean;\n  setFocusedIndex: Dispatch<SetStateAction<number>>;\n}) => {\n  const { t } = useFaqTranslations();\n  const capturePosthogEvent = useCapturePosthogEvent();\n  return (\n    <StyledLink\n      to={`/help-and-faqs/${v.route}#${v.key}`}\n      onMouseEnter={() => {\n        setFocusedIndex(i);\n      }}\n      onClick={() =>\n        capturePosthogEvent('User selected question', { id: v.key })\n      }\n    >\n      <Title size=\"sm\" isFocused={isFocused}>\n        {t(v.titleKey)}\n      </Title>\n    </StyledLink>\n  );\n};\n","import { Typography } from '@finmid/tiger-webapp/components';\nimport { Dispatch, SetStateAction } from 'react';\n\nimport { type Question } from '../../../../../types';\n\nimport { NoResults } from './NoResults';\nimport {\n  CategoryContainer,\n  Container,\n  TitlesContainer,\n} from './SearchResults.styled';\nimport { TitleLink } from './TitleLink';\n\nexport type Results = Record<string, Question[]>;\n\ntype SearchResultsProps = {\n  focusedIndex: number;\n  results: Results;\n  setFocusedIndex: Dispatch<SetStateAction<number>>;\n};\n\nexport const SearchResults = ({\n  focusedIndex,\n  results,\n  setFocusedIndex,\n}: SearchResultsProps) => {\n  if (Object.keys(results).length === 0) {\n    return <NoResults />;\n  }\n\n  let index = -1;\n  return (\n    <Container>\n      {Object.entries(results).map(([key, value], i) => {\n        const isLastCategory = i === Object.entries(results).length - 1;\n        return (\n          <CategoryContainer isLast={isLastCategory}>\n            <Typography size=\"xs\" weight=\"strong\">\n              {key}\n            </Typography>\n            <TitlesContainer>\n              {value.map((v) => {\n                index += 1;\n                const isFocused = index === focusedIndex;\n                return (\n                  <TitleLink\n                    isFocused={isFocused}\n                    v={v}\n                    i={index}\n                    setFocusedIndex={setFocusedIndex}\n                  />\n                );\n              })}\n            </TitlesContainer>\n          </CategoryContainer>\n        );\n      })}\n    </Container>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { Icons, TextInput } from '@finmid/tiger-webapp/components';\nimport { ClickAwayListener, InputAdornment } from '@mui/material';\nimport groupBy from 'lodash/groupBy';\nimport { ChangeEvent, FocusEvent, useRef, useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useKeyboardNavigation, useSearchFaqs } from './SearchInput.hook';\nimport { StyledPopper } from './SearchInput.styled';\nimport { SearchResults, type Results } from './SearchResults';\n\nconst SearchInputWrapper = styled('div')(({ theme: { vars, breakpoints } }) => {\n  const input = vars.components?.faqs?.search?.input;\n  if (!input?.mobile?.height && !input?.desktop?.height) {\n    return {\n      width: '100%',\n      background: vars.components?.variables.colors.white,\n      borderRadius: vars.components?.variables.radius.sm,\n    };\n  }\n\n  const mH = input.mobile?.height ?? 40;\n  const dH = input.desktop?.height ?? mH;\n  const mBg = input.mobile?.backgroundColor ?? 'white';\n  const dBg = input.desktop?.backgroundColor ?? mBg;\n  const mBorder = input.mobile?.border ?? 'none';\n  const dBorder = input.desktop?.border ?? mBorder;\n  const mRadius = input.mobile?.borderRadius ?? 8;\n  const dRadius = input.desktop?.borderRadius ?? mRadius;\n\n  return {\n    width: '100%',\n    background: 'transparent',\n\n    // Reset root MuiFormControl contamination from customizeStyles\n    '& .MuiFormControl-root': {\n      height: 'auto !important' as string,\n      maxHeight: 'none !important' as string,\n      backgroundColor: 'transparent !important' as string,\n      border: 'none !important' as string,\n      borderRadius: '0 !important' as string,\n    },\n\n    // The actual visible input container\n    '& .MuiInputBase-root.MuiOutlinedInput-root': {\n      height: `${mH}px !important` as string,\n      maxHeight: `${mH}px !important` as string,\n      minHeight: `${mH}px !important` as string,\n      boxSizing: 'border-box' as const,\n      backgroundColor: `${mBg} !important` as string,\n      border: `${mBorder} !important` as string,\n      borderRadius: `${mRadius}px !important` as string,\n      padding: '0 !important' as string,\n      alignItems: 'center',\n    },\n\n    // Kill the MUI outline border (has !important in base)\n    '& .MuiOutlinedInput-notchedOutline': {\n      display: 'none !important' as string,\n    },\n\n    // Constrain the native input to fit inside 40px\n    '& .MuiInputBase-input': {\n      padding: '8px 12px !important' as string,\n      height: 'auto !important' as string,\n      boxSizing: 'border-box' as const,\n      backgroundColor: 'transparent !important' as string,\n      borderRadius: 'inherit !important' as string,\n    },\n\n    '& .MuiInputAdornment-root': {\n      height: 'auto',\n      maxHeight: 'none',\n    },\n\n    [breakpoints.up('desktop')]: {\n      '& .MuiInputBase-root.MuiOutlinedInput-root': {\n        height: `${dH}px !important` as string,\n        maxHeight: `${dH}px !important` as string,\n        minHeight: `${dH}px !important` as string,\n        backgroundColor: `${dBg} !important` as string,\n        border: `${dBorder} !important` as string,\n        borderRadius: `${dRadius}px !important` as string,\n      },\n    },\n  };\n});\n\nexport const SearchInput = () => {\n  const { vars } = useTheme();\n  const { t } = useTranslation('turnkey', { keyPrefix: 'helpAndFaq' });\n  const [open, setOpen] = useState(false);\n  const inputRef = useRef<HTMLInputElement>(null);\n\n  const { fuse } = useSearchFaqs();\n  const [results, setResults] = useState<Results>({});\n  const { focusedIndex, handleKeyDown, setFocusedIndex } =\n    useKeyboardNavigation({ results });\n\n  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);\n\n  const handleSearch = (\n    event:\n      | ChangeEvent<HTMLInputElement>\n      | FocusEvent<HTMLInputElement | HTMLTextAreaElement, Element>,\n  ) => {\n    if (anchorEl == null) {\n      setAnchorEl(event.currentTarget.parentElement);\n    }\n    const { value } = event.target;\n    if (value) {\n      setOpen(true);\n      const searchResults = fuse.search(value).map((result) => result.item);\n      const sortedResults: Results = groupBy(searchResults, 'categoryLabel');\n      setResults(sortedResults);\n    } else {\n      setOpen(false);\n    }\n  };\n\n  const closePopper = () => {\n    setOpen(false);\n  };\n\n  return (\n    <ClickAwayListener onClickAway={closePopper}>\n      <SearchInputWrapper>\n        <TextInput\n          ref={inputRef}\n          placeholder={t('search')}\n          slotProps={{\n            input: {\n              startAdornment: (\n                <InputAdornment position=\"start\">\n                  <Icons.SearchIcon\n                    color={vars.components?.variables.colors.grey900}\n                  />\n                </InputAdornment>\n              ),\n            },\n          }}\n          onChange={handleSearch}\n          onFocus={handleSearch}\n          onKeyDown={handleKeyDown}\n          autoComplete=\"off\"\n        />\n        {open && anchorEl != null && (\n          <StyledPopper anchorEl={anchorEl} open placement=\"bottom-start\">\n            <SearchResults\n              results={results}\n              focusedIndex={focusedIndex}\n              setFocusedIndex={setFocusedIndex}\n            />\n          </StyledPopper>\n        )}\n      </SearchInputWrapper>\n    </ClickAwayListener>\n  );\n};\n","import { useTranslation } from 'react-i18next';\n\nimport { Container, Title } from './SearchWidget.styled';\nimport { SearchInput } from './components';\n\nexport const SearchWidget = () => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'helpAndFaq' });\n\n  return (\n    <Container>\n      <Title size=\"xxl\" weight=\"strong\" family=\"title\">\n        {t('title')}\n      </Title>\n      <SearchInput />\n    </Container>\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  customizeStyles,\n  Flex,\n  Typography,\n} from '@finmid/tiger-webapp/components';\n\nexport const Container = styled(Flex)(({ theme: { vars, breakpoints } }) => ({\n  width: '100%',\n  flexDirection: 'column',\n  rowGap: vars.components?.variables.spacings.md,\n  alignItems: 'flex-start',\n\n  ...customizeStyles(\n    { vars, breakpoints },\n    (customizations) => customizations?.faqs?.stillNeedHelp?.container,\n  ),\n}));\n\nexport const Title = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(\n    theme,\n    (customizations) => customizations?.faqs?.stillNeedHelp?.title,\n  ),\n}));\n\nexport const ContactContainer = styled(Flex)(({ theme: { vars } }) => ({\n  columnGap: vars.components?.variables.spacings.xs,\n}));\n\nexport const ContactLabel = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(\n    theme,\n    (customizations) => customizations?.faqs?.stillNeedHelp?.contactLabel,\n  ),\n}));\n\nexport const StyledParagraph = styled(Typography)(({ theme }) => ({\n  color: theme.vars.components?.variables.colors.grey900,\n  textDecoration: 'underline',\n  display: 'inline-block',\n\n  ...customizeStyles(\n    theme,\n    (customizations) => customizations?.faqs?.stillNeedHelp?.contactLabel,\n  ),\n}));\n","import {\n  CustomisationSlot,\n  CopyEmailButton,\n  usePlatformSupportEmail,\n} from '@finmid/tiger-webapp/components';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport {\n  Container,\n  ContactContainer,\n  ContactLabel,\n  StyledParagraph,\n  Title,\n} from './StillNeedHelp.styled';\n\nexport const StillNeedHelp = () => {\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'helpAndFaq',\n  });\n  const supportEmail = usePlatformSupportEmail();\n\n  return (\n    <Container>\n      <Title size=\"xxl\" weight=\"strong\" family=\"title\">\n        {t('stillNeedHelp')}\n      </Title>\n      <ContactContainer>\n        <ContactLabel size=\"md\">\n          <Trans\n            t={t}\n            i18nKey=\"contactSupport\"\n            components={{\n              span: <StyledParagraph size=\"md\" />,\n            }}\n            values={{ email: supportEmail }}\n            defaultValue={`Contact support at ${supportEmail}`}\n          />\n        </ContactLabel>\n        <CustomisationSlot\n          slot=\"copy.email\"\n          props={{}}\n          fallback={<CopyEmailButton />}\n        />\n      </ContactContainer>\n    </Container>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport {\n  BackToOffersWidget,\n  Spacer,\n  useCapturePosthogViewed,\n  useMessenger,\n  useResponsive,\n} from '@finmid/tiger-webapp/components';\n\nimport {\n  HelpAndFaqInnerLayout,\n  HelpAndFaqPageLayout,\n} from './HelpAndFaqPage.styled';\nimport { QuestionCategories, SearchWidget, StillNeedHelp } from './components';\n\nexport const HelpAndFaqPage = () => {\n  const { vars } = useTheme();\n  const { isMobile } = useResponsive();\n  const { isEmbedded } = useMessenger();\n  useCapturePosthogViewed('FAQs page viewed');\n\n  const offersRoute = isMobile ? '/overview?step=selectOffer' : '/overview';\n\n  return (\n    <HelpAndFaqPageLayout>\n      <HelpAndFaqInnerLayout>\n        <SearchWidget />\n        <QuestionCategories />\n        <StillNeedHelp />\n        {isMobile || isEmbedded ? null : (\n          <Spacer height={vars.components?.variables.spacings.xxxl} />\n        )}\n        <BackToOffersWidget to={offersRoute} />\n      </HelpAndFaqInnerLayout>\n    </HelpAndFaqPageLayout>\n  );\n};\n","import { HelpAndFeedback } from '@finmid/tiger-webapp/components';\n\ninterface Props {\n  faqLink?: string;\n}\n\nexport const HelpAndFeedbackPage = (props: Props) => (\n  <HelpAndFeedback {...props} />\n);\n","import { useTheme } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { Spacer, useResponsive } from '@finmid/tiger-webapp/components';\n\nimport { HelpAndFaqInnerLayout } from './HelpAndFaqPage/HelpAndFaqPage.styled';\nimport {\n  QuestionCategories,\n  SearchWidget,\n  StillNeedHelp,\n} from './HelpAndFaqPage/components';\n\nconst DashboardHelpLayout = styled(HelpAndFaqInnerLayout)(() => ({\n  maxWidth: '100%',\n  backgroundColor: 'transparent',\n  '--faq-card-bg': 'white',\n}));\n\nexport const DashboardHelpCenter = () => {\n  const { isMobile } = useResponsive();\n  const { vars } = useTheme();\n\n  return (\n    <DashboardHelpLayout>\n      <SearchWidget />\n      <QuestionCategories reversed />\n      <StillNeedHelp />\n      {isMobile && <Spacer height={vars.components?.variables.spacings.md} />}\n    </DashboardHelpLayout>\n  );\n};\n","import { useCountrySettings } from '@finmid/tiger-webapp/components';\nimport { AispProviderType } from '@finmid/tiger-webapp/queries';\n\nexport interface AispProviderProps {\n  isBankConnected: boolean;\n  startConnection: () => void;\n  waitingForAccountsAfterSuccess: boolean;\n  loading: boolean;\n  provider: AispProviderType;\n  name: string;\n}\n\nexport const useAispProvider = (): AispProviderType => {\n  const { countrySettings } = useCountrySettings();\n\n  const aisp = countrySettings?.aisp ?? 'off';\n\n  if (aisp === 'off') return 'FINAPI';\n\n  return aisp.provider;\n};\n","import { NavigationRoutes } from '@finmid/tiger-webapp/components';\nimport {\n  AispConnectionPurpose,\n  AispConnectionState,\n  StartAispConnectionResponse,\n} from '@finmid/tiger-webapp/queries';\nimport {\n  createContext,\n  FunctionComponent,\n  PropsWithChildren,\n  useCallback,\n  useContext,\n  useState,\n} from 'react';\n\nimport { useAispProvider } from './useAispProvider';\n\nexport interface AispState extends StartAispConnectionResponse {\n  connectionState: AispConnectionState;\n  bankName?: string;\n  bankLogoUrl?: string;\n  collectionIbanLastFour?: string;\n}\n\ninterface AispContextValue {\n  faqRoute: NavigationRoutes;\n  purpose?: AispConnectionPurpose;\n\n  aispState?: AispState;\n  setAispState: (\n    connectionState: AispConnectionState,\n    bankName?: string,\n    bankLogoUrl?: string,\n    collectionIbanLastFour?: string,\n  ) => void;\n}\n\nexport const AispContext = createContext<AispContextValue>(\n  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion\n  null!,\n);\n\nexport const AispProvider: FunctionComponent<\n  PropsWithChildren<{\n    faqRoute: NavigationRoutes;\n    purpose?: AispConnectionPurpose;\n    initialState?: AispState;\n  }>\n> = ({ faqRoute, purpose, initialState, children }) => {\n  const [aispState, setAispState] = useState<AispState | undefined>(\n    initialState,\n  );\n\n  const setConnectionState = useCallback(\n    (\n      connectionState: AispConnectionState,\n      bankName?: string,\n      bankLogoUrl?: string,\n      collectionIbanLastFour?: string,\n    ) => {\n      setAispState((state) => ({\n        ...state,\n        connectionState,\n        bankName,\n        bankLogoUrl,\n        collectionIbanLastFour,\n      }));\n    },\n    [setAispState],\n  );\n\n  return (\n    <AispContext.Provider\n      value={{\n        faqRoute,\n        purpose,\n        aispState,\n        setAispState: setConnectionState,\n      }}\n    >\n      {children}\n    </AispContext.Provider>\n  );\n};\n\nexport const useAisp = () => {\n  const state = useContext(AispContext);\n  const provider = useAispProvider();\n\n  return { ...state, provider };\n};\n","import styled from '@emotion/styled';\nimport {\n  customized,\n  customizeStyles,\n  Flex,\n  Typography,\n} from '@finmid/tiger-webapp/components';\nimport { Trans } from 'react-i18next';\n\nexport const Badge = styled(Flex)<{ intent?: 'success' }>(\n  ({ theme: { breakpoints, vars }, intent }) => ({\n    borderRadius: 100,\n    background: vars.components?.variables.colors.success,\n    color: vars.components?.variables.colors.white,\n    padding: `2px ${vars.components?.variables.spacings.sm}`,\n    whiteSpace: 'nowrap',\n    fontWeight: vars.components?.variables.typography.desktop?.weight.strong,\n    fontSize: vars.components?.variables.typography.desktop?.size.xs,\n    lineHeight: vars.components?.variables.typography.desktop?.lineHeight.xs,\n    gap: vars.components?.variables.spacings.xs,\n\n    [breakpoints.down('desktop')]: {\n      fontWeight: vars.components?.variables.typography.mobile?.weight.strong,\n      fontSize: vars.components?.variables.typography.mobile?.size.xs,\n      lineHeight: vars.components?.variables.typography.mobile?.lineHeight.xs,\n    },\n\n    '& svg': {\n      fontSize: '1rem',\n    },\n\n    ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.bank?.badge),\n\n    ...(intent === 'success' &&\n      customizeStyles(\n        { breakpoints, vars },\n        (c) => c?.plus?.bank?.badgeSuccess,\n      )),\n  }),\n);\n\nexport const BadgeLabel = customized(\n  Typography,\n  (customizations) => customizations?.plus?.bank?.badgeLabel,\n);\n\nexport const TitlesWrapper = styled(Flex)(\n  ({ theme: { breakpoints, vars } }) => ({\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.plus?.bank?.titlesWrapper,\n    ),\n  }),\n);\n\nexport const Title = ({\n  i18nKey,\n  i18nValues,\n  subtitleI18nKey,\n}: {\n  i18nKey: string;\n  i18nValues?: Record<string, string | number>;\n  subtitleI18nKey?: string;\n}) => {\n  return (\n    <StyledTitle>\n      <Trans\n        i18nKey={i18nKey}\n        components={{ emp: <span className={'title-emphasize'} /> }}\n        values={i18nValues}\n      />\n      {subtitleI18nKey ? (\n        <StyledSubtitle size=\"md\">\n          <Trans i18nKey={subtitleI18nKey} components={{ span: <span /> }} />\n        </StyledSubtitle>\n      ) : null}\n    </StyledTitle>\n  );\n};\n\nconst StyledTitle = styled('div')(({ theme: { breakpoints, vars } }) => ({\n  fontSize: vars.components?.variables.typography?.desktop.size?.xxl,\n  fontWeight: vars.components?.variables.typography?.desktop.weight?.strong,\n  fontFamily: vars.components?.variables.typography?.desktop.family?.title,\n  lineHeight: vars.components?.variables.typography?.desktop.lineHeight?.xxl,\n  paddingBottom: vars.components?.variables.spacings?.xxl,\n  gap: vars.components?.variables.spacings.sm,\n\n  [breakpoints.up('tablet')]: {\n    paddingBottom: vars.components?.variables.spacings?.xxl,\n  },\n\n  [breakpoints.down('desktop')]: {\n    paddingBottom: vars.components?.variables.spacings?.xl,\n    fontSize: vars.components?.variables.typography?.mobile.size?.xxl,\n    fontWeight: vars.components?.variables.typography?.mobile.weight?.strong,\n    lineHeight: vars.components?.variables.typography?.mobile.lineHeight?.xxl,\n  },\n\n  ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.title),\n}));\n\nconst StyledSubtitle = styled(Typography)(\n  ({ theme: { breakpoints, vars } }) => ({\n    marginTop: 8,\n\n    [breakpoints.down('desktop')]: {\n      maxWidth: '100%',\n      '& span': {\n        display: 'none',\n      },\n    },\n\n    ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.subtitle),\n  }),\n);\n\nexport const Container = styled('div')(({ theme: { breakpoints, vars } }) => ({\n  display: 'flex',\n  flexDirection: 'column',\n  gap: vars.components?.variables.spacings.md,\n  padding: `${vars.components?.variables.spacings?.xxl} ${vars.components?.variables.spacings?.lg}`,\n  width: 636, // 588 + spacings?.lg*2\n  margin: '0 auto',\n\n  [breakpoints.down('desktop')]: {\n    padding: 0,\n    maxWidth: '100%',\n  },\n\n  ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.container),\n}));\n\nexport const FooterSubtitle = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    display: 'flex',\n    flexDirection: 'column',\n    alignItems: 'center',\n    marginTop: 'auto',\n    padding: `${vars.components?.variables.spacings?.xl} 0 ${vars.components?.variables.spacings?.xxl}`,\n    color: vars.components?.variables.colors?.grey700,\n    maxWidth: 588,\n\n    '& p': {\n      margin: 0,\n    },\n\n    '& a': {\n      color: vars.components?.variables.colors?.grey700,\n    },\n\n    [breakpoints.down('desktop')]: {\n      paddingBottom: 0,\n    },\n\n    ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.footerSubtitle),\n  }),\n);\n\nexport const SecondaryTitle = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    fontSize: vars.components?.variables.typography?.desktop.size.md,\n    lineHeight: vars.components?.variables.typography?.desktop.lineHeight.md,\n    fontWeight: vars.components?.variables.typography?.desktop.weight?.strong,\n\n    [breakpoints.down('desktop')]: {\n      fontSize: vars.components?.variables.typography?.mobile.size.md,\n      lineHeight: vars.components?.variables.typography?.mobile.lineHeight.md,\n      fontWeight: vars.components?.variables.typography?.mobile.weight?.strong,\n    },\n\n    ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.secondaryTitle),\n  }),\n);\n","import styled from '@emotion/styled';\nimport {\n  customizeStyles,\n  Flex,\n  Typography,\n} from '@finmid/tiger-webapp/components';\nimport { PropsWithChildren } from 'react';\nimport { Trans } from 'react-i18next';\n\nimport { Container, FooterSubtitle } from './Components.styled';\n\nconst privacyPolicy = '/CapitalPlus-PrivacyPolicy.pdf';\n\nconst PrivacyFooter = () => (\n  <FooterSubtitle data-test-id=\"aisp-privacy-footer\">\n    <Typography size=\"xs\" color=\"grey700\">\n      <Trans\n        i18nKey={'plus.footer.subtitle'}\n        components={{\n          privacy: (\n            // eslint-disable-next-line jsx-a11y/anchor-has-content\n            <a href={privacyPolicy} target={'_blank'} rel=\"noreferrer\" />\n          ),\n          u: <u />,\n        }}\n      />\n    </Typography>\n  </FooterSubtitle>\n);\n\nexport const AispPageWrapper = ({\n  children,\n  hidePrivacyFooter = false,\n}: PropsWithChildren<{ hidePrivacyFooter?: boolean }>) => {\n  return (\n    <Wrapper data-test-id=\"aisp-page\">\n      <Container>{children}</Container>\n      {!hidePrivacyFooter && <PrivacyFooter />}\n    </Wrapper>\n  );\n};\n\nconst Wrapper = styled(Flex)(({ theme: { vars, breakpoints } }) => ({\n  flexDirection: 'column',\n  width: '100%',\n  alignItems: 'center',\n  justifyContent: 'flex-start',\n  flexGrow: 1,\n  padding: 0,\n\n  [breakpoints.down('desktop')]: {\n    padding: vars.components?.variables.spacings?.lg,\n  },\n\n  ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.wrapper),\n}));\n","import styled from '@emotion/styled';\nimport { customizeStyles, Flex } from '@finmid/tiger-webapp/components';\n\nexport const HeaderSubtitle = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    fontSize: vars.components?.variables.typography?.desktop.size?.sm,\n    fontWeight: vars.components?.variables.typography?.desktop.weight.default,\n    lineHeight: vars.components?.variables.typography?.desktop.lineHeight?.sm,\n\n    [breakpoints.down('desktop')]: {\n      fontSize: vars.components?.variables.typography?.mobile.size?.sm,\n      fontWeight: vars.components?.variables.typography?.mobile.weight.default,\n      lineHeight: vars.components?.variables.typography?.mobile.lineHeight?.sm,\n    },\n\n    ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.headerSubtitle),\n  }),\n);\n\n// TODO: temporarily isolate Card for Plus screens; move back to lib later\nexport const Card = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  alignItems: 'normal',\n  background: theme.vars.components?.variables.colors.white,\n  border: `1px solid ${theme.vars.components?.variables.colors.grey300}`,\n  borderRadius: theme.vars.components?.variables.radius.md,\n\n  ...customizeStyles(theme, (c) => c?.plus?.card?.container),\n}));\n\nexport const CardHeader = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  alignItems: 'flex-start',\n  gap: theme.vars.components?.variables.spacings.sm,\n  padding: theme.vars.components?.variables.spacings.md,\n  borderBottom: `1px solid ${theme.vars.components?.variables.colors.grey300}`,\n\n  ...customizeStyles(theme, (c) => c?.plus?.card?.header),\n}));\n\nexport const ButtonsWrapper = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  width: '100%',\n  gap: theme.vars.components?.variables.spacings.md,\n\n  ...customizeStyles(theme, (c) => c?.plus?.bank?.buttonsWrapper),\n}));\n","import { useTheme } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport {\n  customizeStyles,\n  Flex,\n  Icons,\n  Typography,\n} from '@finmid/tiger-webapp/components';\nimport { FunctionComponent, ReactNode } from 'react';\n\nexport const CalloutContainer = styled(Flex)<{ bgcolor: string }>(\n  ({ theme: { breakpoints, vars }, bgcolor }) => ({\n    borderRadius: vars.components?.variables.radius.sm,\n    background: bgcolor,\n    padding: vars.components?.variables.spacings.sm,\n    width: '100%',\n    alignItems: 'flex-start',\n    justifyContent: 'flex-start',\n    gap: vars.components?.variables.spacings.sm,\n\n    '& svg': {\n      minWidth: 20,\n      width: 20,\n      height: 20,\n    },\n\n    ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.bank?.faqBanner),\n  }),\n);\n\ntype PrimaryCalloutProps = {\n  title?: string;\n  subtitle: ReactNode;\n};\n\nexport const PrimaryCallout: FunctionComponent<PrimaryCalloutProps> = ({\n  title,\n  subtitle,\n}) => {\n  const { vars } = useTheme();\n  const bgcolor = `color-mix(in srgb, ${vars.components?.variables.colors.primaryDefault} 10%, transparent)`;\n\n  return (\n    <CalloutContainer bgcolor={bgcolor}>\n      <Icons.InfoIcon\n        color={vars.components?.variables.colors.primaryDefault}\n      />\n      <Flex flexDirection=\"column\" alignItems=\"flex-start\">\n        {title && (\n          <Typography\n            component=\"p\"\n            size=\"xs\"\n            weight=\"strong\"\n            color=\"primaryDefault\"\n          >\n            {title}\n          </Typography>\n        )}\n        <Typography component=\"p\" size=\"xs\" color=\"primaryDefault\">\n          {subtitle}\n        </Typography>\n      </Flex>\n    </CalloutContainer>\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  customized,\n  customizeStyles,\n  Flex,\n  Typography,\n} from '@finmid/tiger-webapp/components';\nimport { Modal } from '@mui/material';\n\nexport const BankConnectedContainer = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    padding: vars.components?.variables.spacings.md,\n    display: 'flex',\n    flexDirection: 'column',\n    gap: vars.components?.variables.spacings.md,\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.plus?.bank?.connectedContainer,\n    ),\n  }),\n);\n\nexport const BankName = styled('div')(({ theme: { breakpoints, vars } }) => ({\n  padding: vars.components?.variables.spacings.sm,\n  display: 'flex',\n  gap: vars.components?.variables.spacings.md,\n  border: `1px solid ${vars.components?.variables.colors?.grey300}`,\n  borderRadius: vars.components?.variables.radius?.sm,\n  justifyContent: 'space-between',\n  alignItems: 'center',\n\n  [breakpoints.down('desktop')]: {\n    flexDirection: 'column',\n    alignItems: 'flex-start',\n  },\n\n  ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.bank?.bankName),\n}));\n\nexport const EmojiContainer = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    display: 'flex',\n    alignItems: 'center',\n    justifyContent: 'center',\n    flexShrink: 0,\n    background: '#F5F5F5',\n    width: 25,\n    height: 25,\n    fontSize: vars.components?.variables.typography?.desktop.size.md,\n    borderRadius: vars.components?.variables.radius?.sm,\n\n    [breakpoints.down('desktop')]: {\n      width: 30,\n      height: 30,\n      fontSize: vars.components?.variables.typography?.mobile.size.md,\n    },\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.plus?.bank?.emojiContainer,\n    ),\n  }),\n);\n\nexport const ContainerWithGap = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  alignItems: 'flex-start',\n\n  ...customizeStyles(theme, (c) => c?.plus?.bank?.topicsContainer),\n}));\n\nexport const TopicTitle = customized(\n  Typography,\n  (customizations) => customizations?.plus?.bank?.topicTitle,\n);\n\nexport const TopicContent = customized(\n  Typography,\n  (customizations) => customizations?.plus?.bank?.topicContent,\n);\n\nexport const BlurryModal = styled(Modal)(\n  ({ theme: { breakpoints, vars } }) => ({\n    '& .MuiModal-backdrop': {\n      background: 'rgba(255, 255, 255, 0.8)',\n      backdropFilter: 'blur(6px)',\n    },\n\n    ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.bank?.modal),\n  }),\n);\n","import {\n  SepaAccordion,\n  Typography,\n  useCapturePosthogEvent,\n} from '@finmid/tiger-webapp/components';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useAisp } from '../AispContext';\n\nexport const RepaymentMethodSection: FunctionComponent = () => {\n  const capturePosthogEvent = useCapturePosthogEvent();\n  const { t } = useTranslation('turnkey', { keyPrefix: 'plus.aisp' });\n  const { t: tBankConnection } = useTranslation('turnkey', {\n    keyPrefix: 'features.bankConnection',\n  });\n  const { aispState, purpose } = useAisp();\n\n  if (purpose !== 'SDD_CONNECTION_OFFER_FLOW') {\n    return null;\n  }\n\n  return (\n    <>\n      <Typography size=\"md\" weight=\"strong\">\n        {t('repaymentMethod', 'Repayment method')}\n      </Typography>\n      <SepaAccordion\n        iban={aispState?.collectionIbanLastFour ?? 'XXXX'}\n        subtitle={tBankConnection(\n          'sepaTitle',\n          'We will automatically take repayments from your {{bankName}} account.',\n          { bankName: aispState?.bankName },\n        )}\n        description={tBankConnection(\n          'sepaDescription',\n          'By continuing, you are signing a mandate that authorizes MIR Lux Capital S.a.r.l., our Capital service provider, to send instructions to your bank to debit your account and your bank to debit your account in accordance with those instructions. You are entitled to a refund from your bank under the terms and conditions of your agreement with your bank. A refund must be claimed within 8 weeks starting from the date on which your account was debited.',\n        )}\n        showIbanLastFour\n        showLogo\n        onClick={() => capturePosthogEvent('aisp_sepa_accordion_clicked')}\n      />\n    </>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport {\n  Button,\n  CustomisationSlot,\n  Flex,\n  Icons,\n  LoadingBank,\n  Typography,\n  useCapturePosthogEvent,\n  useSelectedOffer,\n} from '@finmid/tiger-webapp/components';\nimport { useMediaQuery } from '@mui/material';\nimport { FunctionComponent } from 'react';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { useAisp } from '../AispContext';\nimport {\n  Badge,\n  Card,\n  CardHeader,\n  HeaderSubtitle,\n  SecondaryTitle,\n} from '../components';\n\nimport { BankConnectedContainer, BankName } from './ConnectBank.styled';\nimport { RepaymentMethodSection } from './RepaymentMethodSection';\n\ninterface Props {\n  waitingForAccountsAfterSuccess: boolean;\n  onNavigateToReview: () => void;\n}\n\nexport const BankConnected: FunctionComponent<Props> = ({\n  waitingForAccountsAfterSuccess,\n  onNavigateToReview,\n}) => {\n  const capturePosthogEvent = useCapturePosthogEvent();\n  const { t } = useTranslation('turnkey', { keyPrefix: 'plus.aisp' });\n  const { aispState } = useAisp();\n  const { breakpoints } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n  const { selectedOffer, currency } = useSelectedOffer();\n\n  const nextStep = () => {\n    capturePosthogEvent('User submitted CapitalMax request', {\n      features: { capitalPlus: true },\n      offer: selectedOffer,\n      currency,\n    });\n    onNavigateToReview();\n  };\n\n  if (waitingForAccountsAfterSuccess) {\n    return <LoadingBank />;\n  }\n\n  return (\n    <>\n      <Card>\n        <CardHeader>\n          <Flex\n            gap=\"sm\"\n            justifyContent={'space-between'}\n            alignItems={'flex-start'}\n            width={'100%'}\n            flexDirection={['column-reverse', 'row']}\n          >\n            <Flex flexDirection={'column'} alignItems={'flex-start'}>\n              <SecondaryTitle>{t('accountConnected.title')}</SecondaryTitle>\n              <HeaderSubtitle>\n                <Trans i18nKey={'plus.aisp.reviewBank'} />\n              </HeaderSubtitle>\n            </Flex>\n            <Badge>{t('recommendedByPlatform')}</Badge>\n          </Flex>\n        </CardHeader>\n        <BankConnectedContainer>\n          <Typography size=\"md\" weight=\"strong\">\n            {t('connectedBank')}\n          </Typography>\n          <BankName>\n            <Flex gap=\"md\" alignItems={'center'}>\n              {aispState?.bankLogoUrl ? (\n                <BankImage alt={'Bank logo'} src={aispState.bankLogoUrl} />\n              ) : (\n                <BankIcon>\n                  <Icons.AccountBalanceIcon />\n                </BankIcon>\n              )}\n              <Typography size=\"md\" weight=\"strong\">\n                {aispState?.bankName}\n              </Typography>\n            </Flex>\n\n            <Badge intent=\"success\">\n              <CustomisationSlot\n                slot=\"plus.bank.connectedIcon\"\n                props={{}}\n                fallback={undefined}\n              />\n              <div>{t('connected')}</div>\n            </Badge>\n          </BankName>\n        </BankConnectedContainer>\n      </Card>\n      <RepaymentMethodSection />\n      {!isMobile ? (\n        <Button\n          onClick={nextStep}\n          variant=\"primary\"\n          size=\"large\"\n          data-test-id=\"aisp-dialog-accept\"\n          customizationTags={['plus', 'bank', 'accept']}\n        >\n          {t('accept')}\n        </Button>\n      ) : null}\n    </>\n  );\n};\n\nconst BankIcon = styled('div')(({ theme }) => ({\n  width: '40px',\n  height: '40px',\n  display: 'flex',\n  justifyContent: 'center',\n  alignItems: 'center',\n  borderRadius: '50%',\n  background: '#EDEDEE',\n  color: theme.vars.components?.variables.colors.primaryDefault,\n}));\n\nconst BankImage = styled('img')(({ theme }) => ({\n  maxHeight: '40px',\n  maxWidth: '100px',\n}));\n","import { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { PrimaryCallout } from '../../components/PrimaryCallout';\n\nexport const SddConnectionCallout: FunctionComponent = () => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'plus.aisp' });\n\n  return (\n    <PrimaryCallout\n      title={t('sddCallout.title', 'Connect the right alternative account')}\n      subtitle={t(\n        'sddCallout.description',\n        'Connect the account that shows most of your business revenue.',\n      )}\n    />\n  );\n};\n","import {\n  Callout,\n  InnerLink,\n  Typography,\n} from '@finmid/tiger-webapp/components';\n\ntype SetupConnectionCalloutProps = {\n  faqRoute: string;\n};\n\nexport const SetupConnectionCallout = ({\n  faqRoute,\n}: SetupConnectionCalloutProps) => {\n  return (\n    <Callout\n      labelKey=\"plus.aisp.faqBanner\"\n      labelComponents={{\n        faq: (\n          <InnerLink to={faqRoute}>\n            <Typography size=\"xs\" component=\"span\" color=\"primaryDefault\" />\n          </InnerLink>\n        ),\n      }}\n    />\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport { Button, Card, Flex } from '@finmid/tiger-webapp/components';\nimport { useMediaQuery } from '@mui/material';\nimport { useTranslation } from 'react-i18next';\n\nimport { useAisp } from '../../AispContext';\nimport { ButtonsWrapper } from '../../components';\nimport {\n  ContainerWithGap,\n  EmojiContainer,\n  TopicContent,\n  TopicTitle,\n} from '../ConnectBank.styled';\n\nimport { SddConnectionCallout } from './SddConnectionCallout';\nimport { SetupConnectionCallout } from './SetupConnectionCallout';\n\nconst topicsConfig = [\n  {\n    emoji: '🔒',\n    topic: 'privacy',\n    ariaLabel: 'lock',\n  },\n  {\n    emoji: '🏦',\n    topic: 'nextSteps',\n    ariaLabel: 'bank',\n  },\n  {\n    emoji: '📄',\n    topic: 'whatYouNeed',\n    ariaLabel: 'page',\n  },\n];\n\ninterface Props {\n  Callout?: React.ReactNode;\n  providerName: string;\n  loading: boolean;\n  onNavigateBack: () => void;\n  startConnection: () => void;\n}\n\nexport const SetupConnection = ({\n  Callout,\n  providerName,\n  loading,\n  startConnection,\n  onNavigateBack,\n}: Props) => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'plus.aisp' });\n  const { breakpoints } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n\n  const { faqRoute, purpose } = useAisp();\n\n  return (\n    <>\n      <Flex flexDirection={'column'}>\n        <Card>\n          <ContainerWithGap gap=\"xl\">\n            <ContainerWithGap gap=\"xl\">\n              {topicsConfig.map(({ emoji, topic, ariaLabel }) => (\n                <Flex key={topic} gap=\"md\" alignItems={'baseline'}>\n                  <EmojiContainer>\n                    <span role=\"img\" aria-label={`${ariaLabel} emoji`}>\n                      {emoji}\n                    </span>\n                  </EmojiContainer>\n                  <Flex flexDirection=\"column\" alignItems=\"flex-start\" gap=\"sm\">\n                    <TopicTitle size=\"md\" weight=\"strong\">\n                      {t(`topics.title.${topic}`)}\n                    </TopicTitle>\n                    <TopicContent size=\"sm\">\n                      {t(`topics.content.${topic}`, { provider: providerName })}\n                    </TopicContent>\n                  </Flex>\n                </Flex>\n              ))}\n            </ContainerWithGap>\n            {purpose === 'SDD_CONNECTION_OFFER_FLOW' && (\n              <SddConnectionCallout />\n            )}\n            {Callout ?? <SetupConnectionCallout faqRoute={faqRoute} />}\n          </ContainerWithGap>\n        </Card>\n      </Flex>\n      {!isMobile ? (\n        <ButtonsWrapper flexDirection={'column'} width={'100%'}>\n          <Button\n            disabled={loading}\n            loading={loading}\n            onClick={startConnection}\n            variant=\"primary\"\n            size=\"large\"\n            data-test-id=\"aisp-dialog-submit\"\n            customizationTags={['plus', 'bank', 'start']}\n            fullWidth\n          >\n            {t('start', { provider: providerName })}\n          </Button>\n          <Button\n            onClick={onNavigateBack}\n            variant=\"secondary\"\n            size=\"large\"\n            data-test-id=\"navigate-to-doc-upload-button\"\n            customizationTags={['plus', 'bank', 'back']}\n            fullWidth\n          >\n            {t('back')}\n          </Button>\n        </ButtonsWrapper>\n      ) : null}\n    </>\n  );\n};\n","import {\n  MobileStickyNavigation,\n  useCapturePosthogEvent,\n} from '@finmid/tiger-webapp/components';\nimport { useWhatsAppButton } from '@finmid/tiger-webapp/whatsapp';\nimport { FunctionComponent, PropsWithChildren } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useAisp } from '../AispContext';\nimport { AispPageWrapper, Title } from '../components';\nimport { AispProviderProps } from '../useAispProvider';\n\nimport { BankConnected } from './BankConnected';\nimport { SetupConnection } from './SetupConnection';\n\ninterface ConnectAispPageProps extends AispProviderProps {\n  onNavigateToReview: () => void;\n  onNavigateBack: () => void;\n}\n\nexport const ConnectAispPage: FunctionComponent<\n  PropsWithChildren<ConnectAispPageProps>\n> = ({\n  isBankConnected,\n  startConnection,\n  waitingForAccountsAfterSuccess,\n  loading,\n  provider,\n  name,\n  children,\n  onNavigateToReview,\n  onNavigateBack,\n}) => {\n  const { purpose } = useAisp();\n  useWhatsAppButton({ overStickyNavigation: true });\n\n  const capturePosthogEvent = useCapturePosthogEvent();\n  const { t } = useTranslation('turnkey', { keyPrefix: 'plus' });\n\n  const onContinue = isBankConnected ? onNavigateToReview : startConnection;\n  const buttonLabel = isBankConnected ? 'confirm' : 'start.connection';\n\n  const captureBackToAispPage = () => {\n    capturePosthogEvent('User navigated to Aisp page', {\n      from: 'secure_bank',\n      provider,\n    });\n  };\n\n  const handleBack = () => {\n    captureBackToAispPage();\n    onNavigateBack();\n  };\n\n  return (\n    <MobileStickyNavigation\n      onBack={handleBack}\n      onContinue={onContinue}\n      isLoading={loading}\n      continueText={t(buttonLabel)}\n    >\n      <AispPageWrapper>\n        <Title\n          i18nKey={\n            isBankConnected\n              ? 'plus.aisp.successfulConnection'\n              : `plus.aisp.secureWith.${provider}`\n          }\n          subtitleI18nKey={\n            purpose === 'SDD_CONNECTION_OFFER_FLOW'\n              ? `plus.aisp.setUpSubtitleSddWith.${provider}`\n              : `plus.aisp.setUpSubtitleWith.${provider}`\n          }\n        />\n        {isBankConnected ? (\n          <BankConnected\n            waitingForAccountsAfterSuccess={waitingForAccountsAfterSuccess}\n            onNavigateToReview={onNavigateToReview}\n          />\n        ) : (\n          <SetupConnection\n            data-test-id=\"setup-connection\"\n            data-test-provider={name}\n            providerName={name}\n            loading={loading}\n            startConnection={startConnection}\n            onNavigateBack={handleBack}\n          />\n        )}\n        {children}\n      </AispPageWrapper>\n    </MobileStickyNavigation>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport { load, WebFormHandlers, WebFormLanguage } from '@finapi/web-form';\nimport { ENVIRONMENT } from '@finmid/environment';\nimport { Box } from '@mui/material';\nimport {\n  FunctionComponent,\n  useCallback,\n  useEffect,\n  useMemo,\n  useRef,\n  useState,\n} from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useAisp } from '../../AispContext';\n\nexport interface EmbeddedFinApiModalProps extends WebFormHandlers {\n  token: string | undefined;\n  handlers: WebFormHandlers;\n}\n\nexport const EmbeddedFinApiModal: FunctionComponent<\n  EmbeddedFinApiModalProps\n> = ({ token, handlers }) => {\n  const {\n    i18n: { language },\n  } = useTranslation();\n\n  const { faqRoute } = useAisp();\n\n  const [isLoaded, setIsLoaded] = useState(false);\n  const { vars } = useTheme();\n\n  const ref = useRef<HTMLDivElement | null>(null);\n\n  const modalLanguage: WebFormLanguage = useMemo(() => {\n    const lng = language?.split('-')[0] ?? 'en';\n\n    if (['cs', 'de', 'en', 'fr', 'nl', 'pl', 'sk', 'tr'].includes(lng)) {\n      return lng as WebFormLanguage;\n    }\n\n    return 'en';\n  }, [language]);\n\n  const createWebForm = useCallback(\n    async (target: HTMLElement) => {\n      if (token == null) return;\n\n      load(\n        target,\n        {\n          targetEnvironment: ENVIRONMENT === 'live' ? 'live' : 'sandbox',\n          token,\n          layoutConfig: 'xs',\n          customerSupportUrl: window.location.origin + faqRoute,\n          language: modalLanguage,\n        },\n        {\n          ...handlers,\n          onLoaded: () => {\n            handlers.onLoaded?.();\n            setIsLoaded(true);\n          },\n          onAbort: () => {\n            handlers.onAbort?.();\n            setIsLoaded(false);\n          },\n          onFail() {\n            handlers.onFail?.();\n            setIsLoaded(false);\n          },\n          onComplete() {\n            handlers.onComplete?.();\n            setIsLoaded(false);\n          },\n        },\n      );\n    },\n    [faqRoute, handlers, modalLanguage, token],\n  );\n\n  useEffect(() => {\n    if (ref.current) {\n      createWebForm(ref.current);\n    }\n  }, [createWebForm, ref]);\n\n  return (\n    <Box\n      height=\"100%\"\n      display=\"flex\"\n      justifyContent=\"center\"\n      alignItems=\"center\"\n      sx={{\n        transition: 'opacity 0.3s',\n        opacity: isLoaded ? 1 : 0,\n      }}\n    >\n      <Box\n        sx={{\n          width: 375,\n          maxWidth: '100%',\n          maxHeight: '100%',\n          backgroundColor: '#fff',\n          boxShadow:\n            '0px 0px 4px 0px rgba(0, 0, 0, 0.06), 0px 4px 24px 0px rgba(0, 0, 0, 0.24)',\n          borderRadius: vars.components?.variables.radius.lg,\n        }}\n        ref={ref}\n      />\n    </Box>\n  );\n};\n","import { AispConnectionPurpose } from '@finmid/tiger-webapp/queries';\n\nconst getAispConnectionStorageKey = (purpose: AispConnectionPurpose) =>\n  `aisp-connection-id:${purpose}`;\n\nexport const getSavedAispConnectionId = (\n  purpose: AispConnectionPurpose,\n): string | null => {\n  try {\n    return sessionStorage.getItem(getAispConnectionStorageKey(purpose));\n  } catch {\n    return null;\n  }\n};\n\nexport const saveAispConnectionId = (\n  purpose: AispConnectionPurpose,\n  connectionId: string,\n): void => {\n  try {\n    sessionStorage.setItem(getAispConnectionStorageKey(purpose), connectionId);\n  } catch {\n    // Silently fail if sessionStorage is unavailable\n  }\n};\n\nexport const clearAispConnectionId = (purpose: AispConnectionPurpose): void => {\n  try {\n    sessionStorage.removeItem(getAispConnectionStorageKey(purpose));\n  } catch {\n    // Silently fail if sessionStorage is unavailable\n  }\n};\n","import { WebFormHandlers } from '@finapi/web-form';\nimport {\n  useCapturePosthogEvent,\n  useTokenContext,\n} from '@finmid/tiger-webapp/components';\nimport {\n  useGetOffers,\n  usePollAispConnections,\n  UsePollAispConnectionsOptions,\n  usePostStartBusinessAispConnection,\n} from '@finmid/tiger-webapp/queries';\nimport { captureException } from '@sentry/react';\nimport { useCallback, useEffect, useMemo, useState } from 'react';\n\nimport { useAisp } from '../../AispContext';\nimport {\n  saveAispConnectionId,\n  clearAispConnectionId,\n} from '../../aispConnectionStorage';\nimport { AispProviderProps } from '../../useAispProvider';\n\nconst name = 'finAPI';\n\nexport const useFinApi = (): AispProviderProps & {\n  embeddedModalOpen: boolean;\n  token: string | undefined;\n  handlers: WebFormHandlers;\n} => {\n  const capturePosthogEvent = useCapturePosthogEvent();\n  const [embeddedModalOpen, setEmbeddedModalOpen] = useState(false);\n\n  const { token, ignoreAction } = useTokenContext();\n  const { data } = useGetOffers({\n    token,\n    ignoreAction,\n    refetchOnWindowFocus: true,\n  });\n\n  const { isPending, mutateAsync: initiateAispConnection } =\n    usePostStartBusinessAispConnection('FINAPI');\n\n  const { aispState, setAispState, purpose } = useAisp();\n\n  const [connectionId, setNewConnectionId] = useState<string>();\n  const [webFormUrl, setNewWebFormUrl] = useState<string>();\n  const [waitingForAccountsAfterSuccess, setWaitingForAccountsAfterSuccess] =\n    useState(false);\n\n  const loadAispConnection = useCallback(async () => {\n    if (!token || isPending) {\n      return;\n    }\n\n    try {\n      const { connectionId, finapiConnectionDetails } =\n        await initiateAispConnection({\n          token: token,\n          provider: 'FINAPI',\n          purpose,\n        });\n      setNewConnectionId(connectionId);\n      setNewWebFormUrl(finapiConnectionDetails.webFormUrl);\n      if (purpose) {\n        saveAispConnectionId(purpose, connectionId);\n      }\n    } catch (error) {\n      setAispState('ERROR');\n      captureException(error);\n      console.error(error);\n    }\n  }, [initiateAispConnection, isPending, purpose, setAispState, token]);\n\n  useEffect(() => {\n    if (aispState?.connectionState === 'READY') return;\n    loadAispConnection();\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  const onRequestSuccess: UsePollAispConnectionsOptions['onSuccess'] =\n    useCallback(\n      ({ status, bankName, bankLogoUrl, preselectedCollectionAccount }) => {\n        setAispState(\n          status,\n          bankName,\n          bankLogoUrl,\n          preselectedCollectionAccount?.ibanLastFour,\n        );\n        if (status !== 'PENDING') {\n          setWaitingForAccountsAfterSuccess(false);\n        }\n      },\n      [setAispState, setWaitingForAccountsAfterSuccess],\n    );\n\n  usePollAispConnections({\n    connectionId,\n    token,\n    enabled: waitingForAccountsAfterSuccess,\n    onSuccess: onRequestSuccess,\n  });\n\n  const startConnection = useCallback(async () => {\n    try {\n      if (connectionId == null || webFormUrl == null) {\n        throw new Error(`${name} connectionData missing`);\n      }\n      capturePosthogEvent('User entered bank connection process', {\n        provider: name,\n        features: {\n          capitalPlus: true,\n        },\n      });\n\n      setAispState('PENDING');\n\n      setEmbeddedModalOpen(true);\n    } catch (error) {\n      captureException(error);\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [connectionId, setAispState, webFormUrl]);\n\n  const isBankConnected =\n    aispState?.connectionState === 'READY' ||\n    data?.capitalPlus?.status === 'BANK_CONNECTED' ||\n    waitingForAccountsAfterSuccess;\n\n  const finApiToken = webFormUrl?.split('/').at(-1);\n\n  const handlers: WebFormHandlers = useMemo(\n    () => ({\n      onComplete: () => {\n        setWaitingForAccountsAfterSuccess(true);\n        setEmbeddedModalOpen(false);\n        capturePosthogEvent('AISP connected', {\n          provider: name,\n          features: {\n            capitalPlus: true,\n          },\n        });\n      },\n      onAbort: () => {\n        setEmbeddedModalOpen(false);\n        setAispState('ERROR');\n        if (purpose) clearAispConnectionId(purpose);\n        loadAispConnection();\n        capturePosthogEvent('AISP connection aborted', {\n          provider: name,\n          features: {\n            capitalPlus: true,\n          },\n        });\n      },\n      onFail: () => {\n        setEmbeddedModalOpen(false);\n        setAispState('ERROR');\n        if (purpose) clearAispConnectionId(purpose);\n        loadAispConnection();\n        capturePosthogEvent('AISP connection failed', {\n          provider: name,\n          features: {\n            capitalPlus: true,\n          },\n        });\n      },\n      onLoadError: () => {\n        setEmbeddedModalOpen(false);\n        setAispState('ERROR');\n        if (purpose) clearAispConnectionId(purpose);\n        loadAispConnection();\n        capturePosthogEvent('AISP connection failed to load', {\n          provider: name,\n          features: {\n            capitalPlus: true,\n          },\n        });\n      },\n    }),\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n    [setAispState, loadAispConnection],\n  );\n\n  return {\n    provider: 'FINAPI',\n    name,\n    loading:\n      aispState?.connectionState !== 'READY' &&\n      (isPending || connectionId == null || webFormUrl == null),\n    isBankConnected,\n    startConnection,\n    waitingForAccountsAfterSuccess,\n    embeddedModalOpen,\n    token: finApiToken,\n    handlers,\n  };\n};\n","import { FunctionComponent } from 'react';\n\nimport { ConnectAispPage } from '../ConnectAispPage';\nimport { BlurryModal } from '../ConnectBank.styled';\n\nimport { EmbeddedFinApiModal } from './EmbeddedFinApiModal';\nimport { useFinApi } from './useFinApi';\n\ninterface Props {\n  onNavigateToReview: () => void;\n  onNavigateBack: () => void;\n}\n\nexport const ConnectBankViaFinApi: FunctionComponent<Props> = (props) => {\n  const { embeddedModalOpen, handlers, token, ...providerProps } = useFinApi();\n\n  return (\n    <ConnectAispPage {...providerProps} {...props}>\n      <BlurryModal open={embeddedModalOpen} onClose={handlers.onAbort}>\n        <EmbeddedFinApiModal token={token} handlers={handlers} />\n      </BlurryModal>\n    </ConnectAispPage>\n  );\n};\n","import { ENVIRONMENT } from '@finmid/environment';\nimport {\n  useCapturePosthogEvent,\n  useTokenContext,\n} from '@finmid/tiger-webapp/components';\nimport {\n  useFinalizePlaidConnection,\n  useGetOffers,\n  usePollAispConnections,\n  UsePollAispConnectionsOptions,\n  usePostStartBusinessAispConnection,\n} from '@finmid/tiger-webapp/queries';\nimport { captureException } from '@sentry/react';\nimport { useCallback, useEffect, useState } from 'react';\nimport {\n  PlaidLinkError,\n  PlaidLinkOnEventMetadata,\n  PlaidLinkOnExitMetadata,\n  PlaidLinkOnSuccessMetadata,\n  usePlaidLink,\n} from 'react-plaid-link';\n\nimport { useAisp } from '../../AispContext';\nimport { AispProviderProps } from '../../useAispProvider';\n\nconst name = 'Plaid';\n\nexport const usePlaid = (): AispProviderProps & {\n  embeddedModalOpen: boolean;\n  onClose: () => void;\n} => {\n  const capturePosthogEvent = useCapturePosthogEvent();\n  const [embeddedModalOpen, setEmbeddedModalOpen] = useState(false);\n\n  const { token, ignoreAction } = useTokenContext();\n  const { data } = useGetOffers({\n    token,\n    ignoreAction,\n    refetchOnWindowFocus: true,\n  });\n\n  const { isPending, mutateAsync: initiateAispConnection } =\n    usePostStartBusinessAispConnection('PLAID');\n\n  const { mutateAsync: finalizePlaidConnection } = useFinalizePlaidConnection();\n\n  const { aispState, setAispState } = useAisp();\n\n  const [connectionId, setNewConnectionId] = useState<string>();\n  const [plaidLinkToken, setPlaidLinkToken] = useState<string | null>(null);\n  const [waitingForAccountsAfterSuccess, setWaitingForAccountsAfterSuccess] =\n    useState(false);\n\n  const loadAispConnection = useCallback(() => {\n    if (!token || isPending) {\n      return;\n    }\n\n    (async () => {\n      try {\n        const { connectionId, plaidConnectionDetails } =\n          await initiateAispConnection({ token, provider: 'PLAID' });\n        setNewConnectionId(connectionId);\n        setPlaidLinkToken(plaidConnectionDetails.plaidLinkToken);\n      } catch (error) {\n        setAispState('ERROR');\n        captureException(error);\n        console.error(error);\n      }\n    })();\n  }, [initiateAispConnection, isPending, setAispState, token]);\n\n  useEffect(() => {\n    loadAispConnection();\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  const onRequestSuccess: UsePollAispConnectionsOptions['onSuccess'] =\n    useCallback(\n      ({ status, bankName, bankLogoUrl, preselectedCollectionAccount }) => {\n        setAispState(\n          status,\n          bankName,\n          bankLogoUrl,\n          preselectedCollectionAccount?.ibanLastFour,\n        );\n        if (status !== 'PENDING') {\n          setWaitingForAccountsAfterSuccess(false);\n        }\n      },\n      [setAispState, setWaitingForAccountsAfterSuccess],\n    );\n\n  usePollAispConnections({\n    connectionId,\n    token,\n    enabled: waitingForAccountsAfterSuccess,\n    onSuccess: onRequestSuccess,\n  });\n\n  const onSuccess = useCallback(\n    (publicToken: string, metadata: PlaidLinkOnSuccessMetadata) => {\n      if (connectionId == null) {\n        throw new Error('Connection ID is null');\n      }\n\n      finalizePlaidConnection({\n        token,\n        plaidToken: publicToken,\n        connectionId,\n      });\n\n      setWaitingForAccountsAfterSuccess(true);\n      setEmbeddedModalOpen(false);\n      setPlaidLinkToken(null);\n      capturePosthogEvent('AISP connected', {\n        provider: name,\n        bankName: metadata.institution?.name,\n        features: {\n          capitalPlus: true,\n        },\n      });\n    },\n    [\n      setWaitingForAccountsAfterSuccess,\n      setEmbeddedModalOpen,\n      capturePosthogEvent,\n      setPlaidLinkToken,\n      finalizePlaidConnection,\n      connectionId,\n      token,\n    ],\n  );\n\n  const onExit = useCallback(\n    (error?: null | PlaidLinkError, metadata?: PlaidLinkOnExitMetadata) => {\n      setEmbeddedModalOpen(false);\n      setPlaidLinkToken(null);\n      setAispState('ERROR');\n      loadAispConnection();\n\n      capturePosthogEvent(\n        `AISP connection ${error != null ? 'failed' : 'aborted'}`,\n        {\n          provider: name,\n          bankName: metadata?.institution?.name,\n          error,\n          features: {\n            capitalPlus: true,\n          },\n        },\n      );\n    },\n    [\n      setEmbeddedModalOpen,\n      setAispState,\n      loadAispConnection,\n      capturePosthogEvent,\n      setPlaidLinkToken,\n    ],\n  );\n\n  const onEvent = useCallback(\n    (eventName: string, metadata: PlaidLinkOnEventMetadata) => {\n      capturePosthogEvent('Plaid event', {\n        eventName,\n        metadata,\n      });\n    },\n    [capturePosthogEvent],\n  );\n\n  const plaidHandler = usePlaidLink({\n    token: plaidLinkToken,\n    onSuccess,\n    onExit,\n    onEvent,\n    env: ENVIRONMENT === 'live' ? 'production' : 'sandbox',\n  });\n\n  const startConnection = useCallback(() => {\n    try {\n      if (connectionId == null || plaidLinkToken == null) {\n        throw new Error(`${name} connectionData missing`);\n      }\n      capturePosthogEvent('User entered bank connection process', {\n        provider: name,\n        features: {\n          capitalPlus: true,\n        },\n      });\n\n      plaidHandler.open();\n\n      setAispState('PENDING');\n      setEmbeddedModalOpen(true);\n    } catch (error) {\n      captureException(error);\n    }\n  }, [\n    connectionId,\n    plaidLinkToken,\n    capturePosthogEvent,\n    setAispState,\n    plaidHandler,\n  ]);\n\n  const isBankConnected =\n    aispState?.connectionState === 'READY' ||\n    data?.capitalPlus?.status === 'BANK_CONNECTED' ||\n    waitingForAccountsAfterSuccess;\n\n  useEffect(() => {\n    if (plaidHandler?.error != null) {\n      setEmbeddedModalOpen(false);\n      setPlaidLinkToken(null);\n      setAispState('ERROR');\n      loadAispConnection();\n      capturePosthogEvent('AISP connection failed', {\n        provider: name,\n        error: plaidHandler?.error,\n        features: {\n          capitalPlus: true,\n        },\n      });\n    }\n  }, [\n    capturePosthogEvent,\n    loadAispConnection,\n    plaidHandler?.error,\n    setAispState,\n    setPlaidLinkToken,\n  ]);\n\n  return {\n    provider: 'PLAID',\n    name,\n    loading: isPending || connectionId == null || plaidLinkToken == null,\n    isBankConnected,\n    startConnection,\n    waitingForAccountsAfterSuccess,\n    embeddedModalOpen,\n    onClose: onExit,\n  };\n};\n","import { FunctionComponent } from 'react';\n\nimport { ConnectAispPage } from '../ConnectAispPage';\nimport { BlurryModal } from '../ConnectBank.styled';\n\nimport { usePlaid } from './usePlaid';\n\ninterface Props {\n  onNavigateToReview: () => void;\n  onNavigateBack: () => void;\n}\n\nexport const ConnectBankViaPlaid: FunctionComponent<Props> = (props) => {\n  const { embeddedModalOpen, onClose, ...providerProps } = usePlaid();\n\n  return (\n    <ConnectAispPage {...providerProps} {...props}>\n      <BlurryModal open={embeddedModalOpen} onClose={onClose}>\n        <div />\n      </BlurryModal>\n    </ConnectAispPage>\n  );\n};\n","import { useCapturePosthogViewed } from '@finmid/tiger-webapp/components';\nimport { FunctionComponent } from 'react';\n\nimport { useAispProvider } from '../useAispProvider';\n\nimport { ConnectBankViaFinApi } from './FinApi/ConnectBankViaFinApi';\nimport { ConnectBankViaPlaid } from './Plaid/ConnectBankViaPlaid';\n\ninterface Props {\n  onNavigateToReview: () => void;\n  onNavigateBack: () => void;\n}\n\nexport const ConnectBankPage: FunctionComponent<Props> = (props) => {\n  const provider = useAispProvider();\n\n  useCapturePosthogViewed('Secure bank connection page viewed', {\n    provider,\n  });\n\n  switch (provider) {\n    case 'PLAID':\n      return <ConnectBankViaPlaid {...props} />;\n    case 'FINAPI':\n      return <ConnectBankViaFinApi {...props} />;\n    default:\n  }\n};\n","import { useTheme } from '@emotion/react';\nimport {\n  Button,\n  Callout,\n  CustomisationSlot,\n  Flex,\n  MobileStickyNavigation,\n  StandaloneLink,\n  useCapturePosthogEvent,\n  useCapturePosthogViewed,\n} from '@finmid/tiger-webapp/components';\nimport { useWhatsAppButton } from '@finmid/tiger-webapp/whatsapp';\nimport { useMediaQuery } from '@mui/material';\nimport { FunctionComponent, ReactElement } from 'react';\nimport { Trans, useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { useAisp } from '../AispContext';\nimport {\n  AispPageWrapper,\n  Badge,\n  BadgeLabel,\n  ButtonsWrapper,\n  Card,\n  CardHeader,\n  HeaderSubtitle,\n  SecondaryTitle,\n  Title,\n  TitlesWrapper,\n} from '../components';\n\ninterface Props {\n  onNavigateToBank: () => void;\n  onNavigateBack: () => void;\n  hideBackButton?: boolean;\n\n  slots?: {\n    title?: ReactElement;\n    secondaryButton?: ReactElement;\n  };\n\n  secondaryButton?: ReactElement;\n}\n\nexport const DetailsPage: FunctionComponent<Props> = ({\n  onNavigateToBank,\n  onNavigateBack,\n  hideBackButton = false,\n  slots = {},\n}) => {\n  useWhatsAppButton({ overStickyNavigation: true });\n\n  useCapturePosthogViewed('Aisp page viewed');\n  const { t } = useTranslation('turnkey', { keyPrefix: 'plus' });\n  const { breakpoints, vars } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n\n  const goToSetupConnection = () => {\n    onNavigateToBank();\n  };\n\n  const navigate = useNavigate();\n  const { faqRoute, purpose } = useAisp();\n  const capturePosthogEvent = useCapturePosthogEvent();\n\n  const openFaq = () => {\n    capturePosthogEvent('User navigated to bank connection FAQs');\n    navigate(faqRoute);\n  };\n\n  const handleBackOnMobile = () => {\n    onNavigateBack();\n  };\n\n  const { title = null, secondaryButton = null } = slots;\n\n  return (\n    <MobileStickyNavigation\n      hideBackButton={hideBackButton}\n      onBack={handleBackOnMobile}\n      onContinue={goToSetupConnection}\n      continueText={t('start.connection')}\n    >\n      <AispPageWrapper>\n        {title ?? (\n          <Title\n            i18nKey={\n              purpose === 'SDD_CONNECTION_OFFER_FLOW'\n                ? 'plus.aisp.additionalInfoSddConnection'\n                : 'plus.aisp.additionalInfo'\n            }\n          />\n        )}\n        <Flex\n          flexDirection=\"column\"\n          alignItems=\"flex-start\"\n          data-test-id=\"aisp-details\"\n        >\n          <Card width=\"100%\">\n            <CardHeader>\n              <Flex\n                gap=\"xl\"\n                justifyContent={'space-between'}\n                alignItems={'flex-start'}\n                width={'100%'}\n                flexDirection={['column-reverse', 'row']}\n              >\n                <TitlesWrapper\n                  flexDirection={'column'}\n                  alignItems={'flex-start'}\n                  gap=\"sm\"\n                >\n                  <SecondaryTitle>{t('aisp.secureTitle')}</SecondaryTitle>\n                  <HeaderSubtitle>\n                    <Trans i18nKey={'plus.aisp.dataSecured'} />\n                  </HeaderSubtitle>\n                </TitlesWrapper>\n                <Badge>\n                  <BadgeLabel size=\"xs\" weight=\"strong\" color=\"white\">\n                    {t('aisp.recommendedByPlatform')}\n                  </BadgeLabel>\n                </Badge>\n              </Flex>\n            </CardHeader>\n            <Flex\n              flexDirection={'column'}\n              alignItems={'flex-start'}\n              gap=\"sm\"\n              p={vars.components?.variables.spacings.md}\n            >\n              <CustomisationSlot\n                slot=\"plus.secureBankConnection.FAQs.button\"\n                props={{\n                  onClick: openFaq,\n                }}\n                fallback={\n                  <StandaloneLink onClick={openFaq}>\n                    <Trans i18nKey={'plus.aisp.bankFaq.link'} />\n                  </StandaloneLink>\n                }\n              />\n              <Callout labelKey=\"plus.aisp.connectPlatformAccount\" />\n            </Flex>\n          </Card>\n        </Flex>\n        <ButtonsWrapper>\n          {!isMobile ? (\n            <Button\n              onClick={goToSetupConnection}\n              variant=\"primary\"\n              size=\"large\"\n              data-test-id=\"aisp-dialog-submit\"\n              fullWidth\n              customizationTags={['plus', 'bank', 'continue']}\n            >\n              {t('aisp.continue')}\n            </Button>\n          ) : null}\n          {secondaryButton}\n        </ButtonsWrapper>\n      </AispPageWrapper>\n    </MobileStickyNavigation>\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  Button,\n  Card,\n  customizeStyles,\n  Flex,\n  Question,\n  QuestionAccordion,\n  QuestionContent,\n  QuestionTitle,\n  useCapturePosthogViewed,\n} from '@finmid/tiger-webapp/components';\nimport { Typography } from '@mui/material';\nimport { TFunction } from 'i18next';\nimport { FunctionComponent } from 'react';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { AispPageWrapper, Title } from '../components';\nimport { useAispProvider } from '../useAispProvider';\n\ninterface Props {\n  onNavigateBack: () => void;\n}\n\nexport const FaqPage: FunctionComponent<Props> = ({ onNavigateBack }) => {\n  const provider = useAispProvider();\n\n  useCapturePosthogViewed('Bank connection FAQs page viewed', {\n    provider,\n  });\n\n  const { t } = useTranslation('turnkey', { keyPrefix: 'plus.faqPage' });\n\n  const questionKeys = [\n    `whoIs.${provider}`,\n    'whyDoINeedToConnectMyBankAccount',\n    'canIConnectMyPersonalBankAccount',\n    'canIWithdrawTheBankingConnection',\n    'whereCanIGetHelp',\n    'whoCanAccessMyData',\n  ];\n\n  const questions: Question[] = questionKeys.map((key) => ({\n    title: t(`questions.${key}.question`),\n    content: t(`questions.${key}.answer`),\n  }));\n\n  if (!questions) return null;\n\n  return (\n    <AispPageWrapper>\n      <Flex\n        data-test-id=\"aisp-faq-page\"\n        flexDirection={'column'}\n        gap={'16px'}\n        maxWidth={'800px'}\n        mb={'auto'}\n      >\n        <Flex flexDirection={'column'} gap={1}>\n          <Typography\n            fontSize={'18px'}\n            fontWeight={700}\n            lineHeight={'130%'}\n            textAlign={'center'}\n          >\n            {t('title')}\n          </Typography>\n          <Title i18nKey={'plus.faqPage.weHaveAnswers'} />\n        </Flex>\n        <FAQCard>\n          <FAQuestionsContainer>\n            {questions.map(({ title, content }) => (\n              <QuestionAccordion key={title}>\n                <QuestionTitle>{title}</QuestionTitle>\n                <QuestionContent>\n                  <Trans\n                    // custom t function that simply returns the key itself since \"content\" is already translated\n                    t={((s: string) => s) as TFunction}\n                    i18nKey={content}\n                    components={{\n                      ul: <ul />,\n                      ol: <ol />,\n                      li: <li />,\n                      bold: <strong />,\n                      u: <u />,\n                    }}\n                  />\n                </QuestionContent>\n              </QuestionAccordion>\n            ))}\n          </FAQuestionsContainer>\n        </FAQCard>\n        <Button\n          onClick={onNavigateBack}\n          fullWidth\n          variant=\"primary\"\n          size=\"large\"\n          customizationTags={['plus', 'faq', 'back']}\n        >\n          {t('back')}\n        </Button>\n      </Flex>\n    </AispPageWrapper>\n  );\n};\n\nexport const FAQCard = styled(Card)(({ theme }) => ({\n  overflow: 'hidden',\n}));\n\nexport const FAQuestionsContainer = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    display: 'flex',\n    flexDirection: 'column',\n\n    // bleed in card\n    margin: `calc(-1 * ${vars.components?.variables.spacings.md})`,\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.plus?.bank?.faqContainer,\n    ),\n  }),\n);\n","import { BlurryModal, ConnectBankPage } from './ConnectBankPage';\nimport { DetailsPage } from './DetailsPage';\nimport { FaqPage } from './FaqPage';\nimport { AispPageWrapper } from './components';\n\nexport const Aisp = {\n  DetailsPage,\n  ConnectBankPage,\n  FaqPage,\n\n  BlurryModal,\n  AispPageWrapper,\n};\n","import { useCountrySettings } from '@finmid/tiger-webapp/components';\nimport { AispScope } from '@finmid/tiger-webapp/queries';\n\n/**\n * Checks if AISP (Account Information Service Provider) is enabled for a given scope\n * @param scope - The AISP scope to check (e.g., `ONBOARDING`, `CAPITAL_MAX`)\n * @returns `true` if AISP is enabled and the scope is allowed via platform settings, `false` otherwise\n */\nexport const useAispEnabled = (scope: AispScope) => {\n  const { countrySettings } = useCountrySettings();\n\n  const aisp = countrySettings?.aisp ?? 'off';\n\n  if (aisp === 'off') return false;\n\n  const allowedInScope = aisp.scopes.includes(scope);\n\n  return allowedInScope;\n};\n","import styled from '@emotion/styled';\nimport { customizeStyles } from '@finmid/tiger-webapp/components';\n\nexport const MainContainer = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    display: 'flex',\n    flexDirection: 'column',\n    padding: vars.components?.variables.spacings.md,\n    gap: vars.components?.variables.spacings.md,\n    alignItems: 'center',\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.plus?.boostLimit?.mainContainer,\n    ),\n  }),\n);\n\nexport const SliderContainer = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    display: 'flex',\n    width: '100%',\n    flexDirection: 'column',\n    padding: '28px 48px 0 28px',\n    alignItems: 'center',\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.plus?.boostLimit?.sliderContainer,\n    ),\n  }),\n);\n\nexport const AdjustAmount = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    display: 'flex',\n    gap: vars.components?.variables.spacings.sm,\n    alignItems: 'center',\n    fontSize: vars.components?.variables.typography?.desktop.size?.xs,\n    lineHeight: vars.components?.variables.typography?.desktop.lineHeight?.xs,\n    color: vars.components?.variables.colors?.grey700,\n\n    [breakpoints.down('desktop')]: {\n      display: 'none',\n    },\n\n    svg: {\n      width: 20,\n      height: 20,\n      color: vars.components?.variables.colors.grey700,\n    },\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.plus?.boostLimit?.adjustAmount,\n    ),\n  }),\n);\n","import { useTheme } from '@emotion/react';\nimport {\n  AispPageWrapper,\n  ButtonsWrapper,\n  useAispEnabled,\n} from '@finmid/tiger-webapp/aisp';\nimport {\n  Button,\n  Card,\n  Flex,\n  getLinkSetting,\n  Icons,\n  MobileStickyNavigation,\n  Slider,\n  Typography,\n  useCapturePosthogEvent,\n  useCapturePosthogViewed,\n  usePlatformSettings,\n  useTokenContext,\n} from '@finmid/tiger-webapp/components';\nimport { useGetOffers } from '@finmid/tiger-webapp/queries';\nimport { useWhatsAppButton } from '@finmid/tiger-webapp/whatsapp';\nimport { useFormat } from '@finmid/translations';\nimport { useMediaQuery } from '@mui/material';\nimport { useEffect, useState } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport {\n  AdjustAmount,\n  MainContainer,\n  SliderContainer,\n} from './ApplyPage.styled';\n\nexport const ApplyPage = () => {\n  useWhatsAppButton({ overStickyNavigation: true });\n  useCapturePosthogViewed('onboarding:apply_page_view');\n\n  const shouldSkip = getLinkSetting('onboarding.apply_page_skip');\n\n  const capturePosthogEvent = useCapturePosthogEvent();\n  const { t } = useTranslation('onboarding', { keyPrefix: 'applyPage' });\n  const { money } = useFormat();\n  const navigate = useNavigate();\n  const [newLimit, setNewLimit] = useState<number | null>(null);\n  const { breakpoints } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n\n  const { token, ignoreAction } = useTokenContext();\n  const { data } = useGetOffers({ token, ignoreAction });\n\n  const { options } = usePlatformSettings();\n\n  const minOfferLimit = options?.onboarding?.apply?.minAmount ?? 1_000;\n  const maxOfferLimit = options?.onboarding?.apply?.maxAmount ?? 30_000;\n\n  const marks = [\n    {\n      value: minOfferLimit,\n      label: money(minOfferLimit, data?.currency ?? 'EUR', {\n        maximumFractionDigits: 0,\n      }),\n    },\n    {\n      value: maxOfferLimit,\n      label: money(maxOfferLimit, data?.currency ?? 'EUR', {\n        maximumFractionDigits: 0,\n      }),\n    },\n  ];\n\n  const isAispEnabled = useAispEnabled('ONBOARDING');\n\n  const nextStep = () => {\n    if (newLimit != null) {\n      capturePosthogEvent('onboarding:apply_page_limit_update', {\n        newLimit,\n        minOfferLimit,\n        maxOfferLimit,\n      });\n    }\n\n    capturePosthogEvent('onboarding:apply_page_continue_click');\n\n    if (isAispEnabled) {\n      navigate('/onboarding/details');\n    }\n  };\n\n  useEffect(() => {\n    if (shouldSkip) navigate('/onboarding/details', { replace: true });\n  }, [shouldSkip, navigate]);\n\n  return (\n    <MobileStickyNavigation\n      onContinue={nextStep}\n      isDisabled={!isAispEnabled}\n      hideBackButton\n    >\n      <AispPageWrapper>\n        <Typography size=\"xl\" weight=\"strong\" family=\"title\">\n          {t('selectTitle')}\n        </Typography>\n\n        <Card style={{ overflow: 'visible' }} data-test-id=\"boost-limit\">\n          <Flex flexDirection=\"column\" alignItems=\"start\" gap=\"sm\">\n            <Typography size=\"md\" weight=\"strong\">\n              {t('selectAmountTitle')}\n            </Typography>\n            <Typography size=\"sm\">{t('description')}</Typography>\n          </Flex>\n\n          <Card.Bleed>\n            <Card.Separator gap=\"md\" />\n          </Card.Bleed>\n\n          <MainContainer>\n            <SliderContainer>\n              <Slider\n                key=\"boost=limit-slider\"\n                data-test-id=\"boost-limit-slider\"\n                thickness={8}\n                min={minOfferLimit}\n                max={maxOfferLimit}\n                marks={marks}\n                step={250}\n                value={newLimit ?? 0}\n                valueLabelDisplay=\"on\"\n                valueLabelFormat={(value) =>\n                  money(value, data?.currency ?? 'EUR', {\n                    maximumFractionDigits: 0,\n                  })\n                }\n                onChange={(_, selectedValue) => {\n                  setNewLimit(Number(selectedValue));\n                }}\n              />\n            </SliderContainer>\n            <AdjustAmount>\n              <Icons.ArrowBackIcon />\n              <span>{t('adjustAmount')}</span>\n              <Icons.ArrowForwardIcon />\n            </AdjustAmount>\n          </MainContainer>\n        </Card>\n\n        {!isMobile ? (\n          <ButtonsWrapper>\n            <Button\n              fullWidth\n              disabled={!isAispEnabled}\n              variant=\"primary\"\n              onClick={nextStep}\n              size=\"large\"\n            >\n              {t('continueButton')}\n            </Button>\n          </ButtonsWrapper>\n        ) : null}\n      </AispPageWrapper>\n    </MobileStickyNavigation>\n  );\n};\n","import { useTokenContext } from '@finmid/tiger-webapp/components';\nimport {\n  OnboardingState,\n  useGetOnboarding,\n} from '@finmid/tiger-webapp/queries';\nimport { useLocation } from 'react-router-dom';\n\ntype SuggestedAction = 'REDIRECT_TO_ONBOARDING' | 'REDIRECT_TO_OVERVIEW' | null;\n\ninterface OnboardingStateResult {\n  /**\n   * The current state of the onboarding process.\n   * - `null` indicates that the state is still being loaded.\n   * - `'NOT_FOUND'` indicates that there is no onboarding process found for the user.\n   * - Other values represent the various states of the onboarding process.\n   */\n  state: OnboardingState | null;\n  id: string;\n  suggestedAction: SuggestedAction;\n}\n\nexport const useOnboardingState = (): OnboardingStateResult => {\n  const { token } = useTokenContext();\n  const location = useLocation();\n  const { data, isLoading } = useGetOnboarding({\n    token,\n  });\n\n  const onboardingRouteActive = location.pathname.startsWith('/onboarding');\n\n  if (isLoading) {\n    return {\n      state: null,\n      id: '',\n      suggestedAction: null,\n    };\n  }\n\n  const state = data?.status ?? 'NOT_FOUND';\n\n  const shouldRedirectToOnboarding =\n    !onboardingRouteActive &&\n    state !== 'NOT_FOUND' &&\n    state !== 'APPROVED' &&\n    state !== 'EXPIRED';\n\n  const shouldRedirectFromOnboarding =\n    onboardingRouteActive && state === 'NOT_FOUND';\n\n  return {\n    state,\n    id: data?.id ?? '',\n    suggestedAction: shouldRedirectToOnboarding\n      ? 'REDIRECT_TO_ONBOARDING'\n      : shouldRedirectFromOnboarding\n      ? 'REDIRECT_TO_OVERVIEW'\n      : null,\n  };\n};\n","import { Aisp } from '@finmid/tiger-webapp/aisp';\nimport {\n  useCapturePosthogViewed,\n  useMessenger,\n  useTokenContext,\n} from '@finmid/tiger-webapp/components';\nimport { useSubmitOnboarding } from '@finmid/tiger-webapp/queries';\nimport { FunctionComponent } from 'react';\nimport { useNavigate } from 'react-router-dom';\n\nimport { useOnboardingState } from '../useOnboardingState';\n\nexport const ConnectBankPage: FunctionComponent = () => {\n  useCapturePosthogViewed('onboarding:connect_bank_page_view');\n\n  const navigate = useNavigate();\n  const { token } = useTokenContext();\n\n  const { mutateAsync: submitOnboarding } = useSubmitOnboarding();\n  const { id } = useOnboardingState();\n  const { sendMessage } = useMessenger();\n\n  const handleNavigateToReview = async () => {\n    await submitOnboarding({ token });\n\n    sendMessage({\n      type: 'ONBOARDING:SUBMITTED',\n      data: {\n        onboardingId: id,\n      },\n    });\n\n    navigate('/onboarding/review');\n  };\n\n  return (\n    <Aisp.ConnectBankPage\n      onNavigateToReview={handleNavigateToReview}\n      onNavigateBack={() => navigate('/onboarding/details')}\n    />\n  );\n};\n","import { Flex, Typography } from '@finmid/tiger-webapp/components';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nexport const TitleSection: FunctionComponent = () => {\n  const { t } = useTranslation('onboarding', { keyPrefix: 'detailsPage' });\n\n  return (\n    <Flex\n      flexDirection=\"column\"\n      gap=\"sm\"\n      alignItems=\"flex-start\"\n      justifyContent=\"flex-start\"\n      sx={({ vars }) => ({\n        paddingBottom: vars.components?.variables.spacings?.xl,\n      })}\n    >\n      <Typography size=\"xxl\" weight=\"strong\" family=\"title\">\n        {t('title')}\n      </Typography>\n      <Typography size=\"md\">{t('subtitle')}</Typography>\n    </Flex>\n  );\n};\n","import { Aisp } from '@finmid/tiger-webapp/aisp';\nimport {\n  getLinkSetting,\n  useCapturePosthogViewed,\n} from '@finmid/tiger-webapp/components';\nimport { FunctionComponent } from 'react';\nimport { useNavigate } from 'react-router-dom';\n\nimport { TitleSection } from './TitleSection';\n\nexport const DetailsPage: FunctionComponent = () => {\n  useCapturePosthogViewed('onboarding:details_page_view');\n\n  const applyPageSkipped = getLinkSetting('onboarding.apply_page_skip');\n\n  const navigate = useNavigate();\n\n  return (\n    <Aisp.DetailsPage\n      onNavigateBack={() => navigate('/onboarding')}\n      onNavigateToBank={() => navigate('/onboarding/bank')}\n      hideBackButton={applyPageSkipped}\n      slots={{\n        title: <TitleSection />,\n      }}\n    />\n  );\n};\n","import { Aisp } from '@finmid/tiger-webapp/aisp';\nimport { useCapturePosthogViewed } from '@finmid/tiger-webapp/components';\nimport { FunctionComponent } from 'react';\nimport { useNavigate } from 'react-router-dom';\n\nexport const FaqPage: FunctionComponent = () => {\n  useCapturePosthogViewed('onboarding:faq_page_view');\n\n  const navigate = useNavigate();\n\n  return (\n    <Aisp.FaqPage onNavigateBack={() => navigate('/onboarding/details')} />\n  );\n};\n","import { AispProvider } from '@finmid/tiger-webapp/aisp';\nimport { Loader, useMessenger } from '@finmid/tiger-webapp/components';\nimport { FunctionComponent, useEffect } from 'react';\nimport { Outlet, useNavigate } from 'react-router-dom';\n\nimport { useOnboardingState } from './useOnboardingState';\n\nexport const OnboardingLayout: FunctionComponent = () => {\n  const { state, id } = useOnboardingState();\n  const navigate = useNavigate();\n\n  const { sendMessage } = useMessenger();\n\n  useEffect(() => {\n    if (state == null) return;\n\n    sendMessage({\n      type: 'ONBOARDING:OPENED',\n      data: {\n        onboardingId: id,\n      },\n    });\n  }, [state, sendMessage, id]);\n\n  useEffect(() => {\n    if (state == null) return;\n\n    switch (state) {\n      case 'NOT_FOUND':\n        navigate('/');\n        return;\n      case 'IN_REVIEW':\n        navigate('/onboarding/review');\n        return;\n      case 'IN_PROGRESS':\n        // Keep as is\n        return;\n      case 'REJECTED':\n        // Not implemented\n        return;\n      case 'APPROVED':\n        // Not implemented\n        return;\n    }\n  }, [state, navigate]);\n\n  return (\n    <AispProvider faqRoute=\"/onboarding/faq\">\n      {state == null ? <Loader /> : <Outlet />}\n    </AispProvider>\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  Flex,\n  Typography,\n  customizeStyles,\n} from '@finmid/tiger-webapp/components';\n\nexport const Title = styled(Typography)(({ theme }) => ({\n  textAlign: 'left',\n  width: '100%',\n\n  ...customizeStyles(theme, (c) => c?.onboarding?.review?.title),\n}));\n\nexport const Description = styled(Typography)(({ theme }) => ({\n  textAlign: 'left',\n  width: '100%',\n\n  ...customizeStyles(theme, (c) => c?.onboarding?.review?.description),\n}));\n\nexport const Container = styled(Flex)(({ theme }) => ({\n  flex: 1,\n  height: '100%',\n  width: '100%',\n  alignItems: ['flex-start', 'stretch', 'stretch', 'stretch'],\n\n  ...customizeStyles(theme, (c) => c?.onboarding?.review?.root),\n}));\n\nexport const Content = styled(Flex)(({ theme: { vars, breakpoints } }) => ({\n  flexDirection: 'column',\n  justifyContent: 'center',\n  width: '50%',\n  // padding: '0 104px',\n\n  [breakpoints.down('desktop')]: {\n    width: '100%',\n    padding: vars.components?.variables.spacings.lg,\n    backgroundColor: vars.components?.variables.colors?.grey100,\n  },\n\n  ...customizeStyles(\n    { vars, breakpoints },\n    (c) => c?.onboarding?.review?.content,\n  ),\n}));\n\nexport const ContentInner = styled(Flex, {\n  shouldForwardProp: (prop) => prop !== 'centeredContent',\n})<{ centeredContent?: boolean }>(\n  ({ theme: { vars, breakpoints }, centeredContent = false }) => ({\n    flexDirection: 'column',\n    alignItems: 'flex-start',\n    justifyContent: centeredContent ? 'center' : 'flex-start',\n    flexGrow: 1,\n    textAlign: 'center',\n    maxWidth: '100%',\n\n    gap: vars.components?.variables.spacings?.xxxl,\n\n    paddingTop: vars.components?.variables.spacings?.xxl,\n\n    [breakpoints.down('desktop')]: {\n      justifyContent: 'flex-start',\n    },\n\n    [breakpoints.up('desktop')]: {\n      maxWidth: 588,\n    },\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.onboarding?.review?.contentInner,\n    ),\n  }),\n);\n\nexport const SuccessIcon = styled(Flex)(({ theme }) => ({\n  justifyContent: 'center',\n  alignItems: 'center',\n  width: '100%',\n\n  ...customizeStyles(theme, (c) => c?.onboarding?.review?.successIcon),\n}));\n","import { useTheme } from '@emotion/react';\nimport { ButtonsWrapper } from '@finmid/tiger-webapp/aisp';\nimport {\n  Button,\n  Flex,\n  Icons,\n  MobileStickyNavigation,\n  useCapturePosthogViewed,\n  useResponsive,\n} from '@finmid/tiger-webapp/components';\nimport { useWhatsAppButton } from '@finmid/tiger-webapp/whatsapp';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { useOnboardingState } from '../useOnboardingState';\n\nimport {\n  Container,\n  Content,\n  ContentInner,\n  Description,\n  SuccessIcon,\n  Title,\n} from './ReviewPage.styled';\n\nexport const ReviewPage: FunctionComponent = () => {\n  useWhatsAppButton({ overStickyNavigation: true });\n  useCapturePosthogViewed('onboarding:review_page_view');\n\n  const { state } = useOnboardingState();\n\n  const { t } = useTranslation('onboarding', { keyPrefix: 'reviewPage' });\n  const navigate = useNavigate();\n  const { isMobile } = useResponsive();\n\n  const handleContinueClick = () => {\n    navigate('/');\n  };\n\n  const enableButton = state === 'APPROVED';\n  const { vars } = useTheme();\n\n  return (\n    <MobileStickyNavigation\n      isDisabled={!enableButton}\n      onContinue={handleContinueClick}\n      hideBackButton\n    >\n      <Container data-test-id=\"offer-accepted-screens\">\n        <div data-test-id=\"offer-accepted-before\" />\n        <Content data-test-id=\"offer-accepted\">\n          <div className=\"offer-accepted-logo csp\" />\n          <ContentInner\n            data-test-id=\"offer-accepted-content\"\n            className=\"offer-accepted-content\"\n            centeredContent\n          >\n            <SuccessIcon>\n              <Icons.ScheduleSendIcon\n                color={vars.components?.variables.colors.primaryDefault}\n              />\n            </SuccessIcon>\n\n            <Flex flexDirection=\"column\" gap=\"xs\">\n              <Title size=\"xxl\" weight=\"strong\" family=\"title\" lineHeight=\"xxl\">\n                {t('title')}\n              </Title>\n              <Description size=\"md\" lineHeight=\"md\">\n                {t('subtitle')}\n              </Description>\n            </Flex>\n\n            {!isMobile && enableButton ? (\n              <ButtonsWrapper>\n                <Button\n                  variant=\"primary\"\n                  onClick={handleContinueClick}\n                  size=\"large\"\n                >\n                  {t('continueButton')}\n                </Button>\n              </ButtonsWrapper>\n            ) : null}\n          </ContentInner>\n        </Content>\n      </Container>\n    </MobileStickyNavigation>\n  );\n};\n","import { Route } from 'react-router-dom';\n\nimport { ApplyPage } from './ApplyPage';\nimport { ConnectBankPage } from './ConnectBankPage';\nimport { DetailsPage } from './DetailsPage';\nimport { FaqPage } from './FaqPage';\nimport { OnboardingLayout } from './OnboardingLayout';\nimport { ReviewPage } from './ReviewPage';\n\nexport const Routes = (\n  <Route element={<OnboardingLayout />}>\n    <Route index element={<ApplyPage />} />\n    <Route path=\"/onboarding/details\" element={<DetailsPage />} />\n    <Route path=\"/onboarding/faq\" element={<FaqPage />} />\n    <Route path=\"/onboarding/bank\" element={<ConnectBankPage />} />\n    <Route path=\"/onboarding/review\" element={<ReviewPage />} />\n  </Route>\n);\n","import styled from '@emotion/styled';\nimport { Flex } from '@finmid/tiger-webapp/components';\n\nexport const Container = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  alignItems: 'baseline',\n  maxWidth: '100%',\n  width: '100%',\n\n  gap: theme.vars?.components?.variables.spacings.md,\n\n  [theme.breakpoints.only('mobile')]: {},\n\n  [theme.breakpoints.up('tablet')]: {\n    flexDirection: 'row',\n  },\n}));\n\nexport const WidgetContainer = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  width: '100%',\n\n  gap: theme.vars?.components?.variables.spacings.md,\n\n  [theme.breakpoints.up('tablet')]: {\n    width: 'auto',\n  },\n}));\n","import styled from '@emotion/styled';\nimport {\n  cssDesktopColumns,\n  customized,\n  customizeStyles,\n  Typography,\n} from '@finmid/tiger-webapp/components';\nimport { FunctionComponent, PropsWithChildren } from 'react';\n\ninterface Props {\n  title?: string;\n  actions?: React.ReactNode;\n  grow?: number;\n  testId?: string;\n}\n\nexport const DashboardSection: FunctionComponent<PropsWithChildren<Props>> = ({\n  title,\n  actions,\n  grow,\n  children,\n  testId,\n}) => {\n  return (\n    <Container grow={grow} data-test-id={testId}>\n      {title && (\n        <HeaderContainer data-test-id={`${testId}-header`}>\n          <Header family=\"body\" size=\"md\" weight=\"strong\" component=\"div\">\n            {title}\n          </Header>\n          {actions}\n        </HeaderContainer>\n      )}\n      <Content>{children}</Content>\n    </Container>\n  );\n};\n\nexport const Container = styled('div')<{ grow?: number }>(\n  ({ theme, grow = 1 }) => ({\n    display: 'flex',\n    flexGrow: grow,\n    height: '100%',\n    width: '100%',\n    flexDirection: 'column',\n    overflow: 'hidden',\n\n    backgroundColor: theme.vars?.components?.variables.colors.white,\n    borderRadius: theme.vars?.components?.variables.radius.md,\n    border: `1px solid ${theme.vars?.components?.variables.colors.grey300}`,\n\n    [theme.breakpoints.up('desktop')]: {\n      minWidth: 300,\n      width: grow ? undefined : cssDesktopColumns(3),\n    },\n\n    ...customizeStyles(\n      theme,\n      (customizations) => customizations?.dashboard?.section?.container,\n    ),\n  }),\n);\n\nconst HeaderContainer = styled.div(({ theme }) => ({\n  width: '100%',\n  display: 'flex',\n  flexGrow: 1,\n  flexDirection: 'column',\n  justifyContent: 'center',\n  padding: theme.vars?.components?.variables.spacings.md,\n\n  borderBottom: `1px solid ${theme.vars?.components?.variables.colors.grey300}`,\n\n  ...customizeStyles(\n    theme,\n    (customizations) => customizations?.dashboard?.section?.headerContainer,\n  ),\n}));\n\nconst Header = customized(Typography, (c) => c?.dashboard?.section?.header);\n\nexport const Content = styled('div')(({ theme }) => ({\n  display: 'flex',\n  flexDirection: 'column',\n  flexGrow: 1,\n  height: '100%',\n\n  ...customizeStyles(\n    theme,\n    (customizations) => customizations?.dashboard?.section?.content,\n  ),\n}));\n","import styled from '@emotion/styled';\nimport { Button, customizeStyles } from '@finmid/tiger-webapp/components';\nimport {\n  TableCellProps,\n  TableCell as BaseTableCell,\n  TableContainer as BaseTableContainer,\n} from '@mui/material';\n\nexport const TableCell = styled(BaseTableCell, {\n  shouldForwardProp: (p) => p !== 'lastRow',\n})<TableCellProps & { lastRow?: boolean }>(\n  ({\n    theme: {\n      breakpoints,\n      vars: { components },\n    },\n    lastRow = false,\n  }) => ({\n    background: 'white',\n    borderColor: components?.variables?.colors.grey300,\n    borderLeftWidth: 0,\n    padding: components?.variables.spacings.md,\n\n    ':first-of-type': {\n      borderLeft: 'none',\n    },\n\n    borderLeftStyle: 'solid',\n\n    fontFamily: components?.variables?.typography.mobile.family.body,\n    fontSize: components?.variables?.typography.mobile.size.sm,\n    lineHeight: components?.variables?.typography.mobile.lineHeight.sm,\n    fontWeight: components?.variables?.typography.mobile.weight.default,\n\n    [breakpoints.up('desktop')]: {\n      fontFamily: components?.variables?.typography.desktop.family.body,\n      fontSize: components?.variables?.typography.desktop.size.sm,\n      lineHeight: components?.variables?.typography.desktop.lineHeight.sm,\n      fontWeight: components?.variables?.typography.desktop.weight.default,\n    },\n\n    '&.MuiTableCell-head': {\n      background: components?.variables?.colors.grey100,\n      color: components?.variables?.colors.grey700,\n\n      ':not(:first-of-type)': {\n        borderLeft: 'none',\n      },\n\n      padding: `${components?.variables.spacings.sm} ${components?.variables.spacings.md}`,\n\n      [breakpoints.only('mobile')]: {\n        padding: '12px 16px',\n      },\n\n      ...components?.table?.head,\n    },\n\n    whiteSpace: 'nowrap',\n\n    ...(components?.table?.cell == null\n      ? null\n      : {\n          ...components?.table?.cell,\n          [breakpoints.up('desktop')]: {\n            ...components?.table?.cell,\n          },\n        }),\n\n    ...(lastRow ? { borderBottom: 'none' } : {}),\n  }),\n);\n\nexport const TableContainer = styled(BaseTableContainer)(\n  ({ theme: { vars, breakpoints } }) => ({\n    borderRadius: 8,\n    borderStyle: 'solid',\n    borderWidth: 1,\n    borderColor: vars?.components?.variables?.colors.grey100,\n\n    borderTopLeftRadius: 0,\n    borderTopRightRadius: 0,\n\n    maxHeight: 800,\n\n    [breakpoints.only('tablet')]: {\n      maxHeight: 'calc(100vh - 180px)',\n    },\n\n    [breakpoints.only('mobile')]: {\n      maxHeight: 'calc(100vh - 150px)',\n    },\n\n    [breakpoints.down('tablet')]: {\n      maxHeight: '80vh',\n    },\n\n    ...customizeStyles({ breakpoints, vars }, (c) => c?.table?.container),\n  }),\n);\n\nexport const DownloadButton = styled(Button)(\n  ({ theme: { vars, breakpoints } }) => ({\n    alignSelf: 'flex-end',\n    position: 'absolute',\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.dashboard?.history?.downloadButton,\n    ),\n  }),\n);\n\nexport const HistorySeparator = styled(BaseTableCell)(({ theme }) => ({\n  padding: 4,\n  border: 'none',\n  backgroundColor: '#eeeeee',\n\n  ...customizeStyles(theme, (c) => c?.dashboard?.history?.separator),\n}));\n","import styled from '@emotion/styled';\nimport { Typography } from '@finmid/tiger-webapp/components';\nimport { PartialPayment } from '@finmid/tiger-webapp/queries';\nimport { useFormat } from '@finmid/translations';\nimport type { Currency } from '@finmid/types';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\ninterface PartialPaymentTooltipProps {\n  totalAmount: number;\n  outstandingAmount: number;\n  partialPayments: PartialPayment[];\n  currency: Currency;\n}\n\nconst Container = styled('div')({\n  display: 'flex',\n  flexDirection: 'column',\n  gap: 4,\n});\n\nconst Callout = styled('div')(({ theme: { vars } }) => ({\n  display: 'flex',\n  flexDirection: 'column',\n  gap: 4,\n  padding: 8,\n  backgroundColor: vars.components?.variables?.colors.grey100,\n  borderRadius: vars.components?.variables?.radius.sm,\n}));\n\nconst Row = styled('div')({\n  display: 'flex',\n  justifyContent: 'space-between',\n  gap: 32,\n});\n\nconst OutstandingCallout = styled('div', {\n  shouldForwardProp: (p) => p !== 'isFullyPaid',\n})<{ isFullyPaid: boolean }>(({ theme: { vars }, isFullyPaid }) => ({\n  display: 'flex',\n  justifyContent: 'space-between',\n  gap: 32,\n  padding: 8,\n  backgroundColor: vars.components?.variables?.colors.grey100,\n  borderRadius: vars.components?.variables?.radius.sm,\n  color: isFullyPaid\n    ? vars.components?.variables?.colors.success\n    : vars.components?.variables?.colors.warning,\n  fontWeight: 'bold',\n}));\n\nexport const PartialPaymentTooltip: FunctionComponent<\n  PartialPaymentTooltipProps\n> = ({ totalAmount, outstandingAmount, partialPayments, currency }) => {\n  const { money, shortDate } = useFormat();\n  const { t } = useTranslation('dashboard', {\n    keyPrefix: 'table.partialPayment',\n  });\n\n  const isFullyPaid = outstandingAmount <= 0;\n\n  return (\n    <Container>\n      <Typography weight=\"strong\" size=\"xs\">\n        {t('title', 'Partial payment')}\n      </Typography>\n      <Callout>\n        <Row>\n          <Typography size=\"xs\">{t('totalAmount', 'Total amount:')}</Typography>\n          <Typography size=\"xs\">{money(totalAmount, currency)}</Typography>\n        </Row>\n        {partialPayments.map((payment, index) => (\n          <Row key={index}>\n            <Typography size=\"xs\" component=\"span\">\n              {t('receivedOn', {\n                date: shortDate(new Date(payment.receivedAt)),\n                defaultValue: 'Received on {{date}}:',\n              })}\n            </Typography>\n            <Typography size=\"xs\" component=\"span\">\n              -{money(payment.amount, currency)}\n            </Typography>\n          </Row>\n        ))}\n      </Callout>\n      <OutstandingCallout isFullyPaid={isFullyPaid}>\n        <Typography\n          size=\"xs\"\n          weight=\"strong\"\n          color={isFullyPaid ? 'success' : 'warning'}\n        >\n          {t('outstanding', 'Outstanding:')}\n        </Typography>\n        <Typography\n          size=\"xs\"\n          weight=\"strong\"\n          color={isFullyPaid ? 'success' : 'warning'}\n        >\n          {money(outstandingAmount, currency)}\n        </Typography>\n      </OutstandingCallout>\n    </Container>\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  Icons,\n  Flex,\n  HtmlTooltip,\n  Typography,\n} from '@finmid/tiger-webapp/components';\nimport { PartialPayment } from '@finmid/tiger-webapp/queries';\nimport type { Currency } from '@finmid/types';\nimport { FunctionComponent, ReactNode } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { PartialPaymentTooltip } from './PartialPaymentTooltip';\n\ntype PaymentStatus = 'PENDING' | 'FAILED' | 'COMPLETED';\n\n// Status Badge Component\nconst StatusBadge = styled(Flex, {\n  shouldForwardProp: (p) => p !== 'status' && p !== 'partialStatus',\n})<{\n  status: PaymentStatus;\n  partialStatus?: 'partial' | 'full' | null;\n}>(({ status, partialStatus }) => ({\n  display: 'inline-flex',\n  alignItems: 'center',\n  justifyContent: 'center',\n  ...(status === 'FAILED' && {\n    color: 'var(--mui-components-variables-colors-error)',\n  }),\n  ...(status === 'PENDING' && {\n    color: 'var(--mui-components-variables-colors-grey900)',\n  }),\n  ...(partialStatus === 'partial' && {\n    color: 'var(--mui-components-variables-colors-warning)',\n  }),\n  ...(partialStatus === 'full' && {\n    color: 'var(--mui-components-variables-colors-success)',\n  }),\n}));\n\nconst getStatusIcon = (\n  status: PaymentStatus,\n  partialStatus?: 'partial' | 'full' | null,\n) => {\n  if (partialStatus === 'partial') {\n    return (\n      <Icons.PartialPaymentIcon style={{ width: '16px', height: '16px' }} />\n    );\n  }\n  if (partialStatus === 'full') {\n    return <Icons.FullPaymentIcon style={{ width: '16px', height: '16px' }} />;\n  }\n\n  switch (status) {\n    case 'PENDING':\n      return (\n        <Icons.SpinningIcon>\n          <Icons.LoadingCircleIcon style={{ width: '18px', height: '18px' }} />\n        </Icons.SpinningIcon>\n      );\n    case 'FAILED':\n      return <Icons.ErrorIcon style={{ width: '16px', height: '16px' }} />;\n    default:\n      return null;\n  }\n};\n\ninterface PaymentStatusBadgeProps {\n  status: PaymentStatus;\n  partialPayments?: PartialPayment[] | null;\n  repaymentAmount?: number;\n  currency?: Currency;\n  children?: ReactNode;\n}\n\nexport const PaymentStatusBadge: FunctionComponent<PaymentStatusBadgeProps> = ({\n  status,\n  partialPayments,\n  repaymentAmount,\n  currency,\n  children,\n}) => {\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'dashboard.table.status',\n  });\n\n  const hasPartialPayments =\n    partialPayments != null && partialPayments.length > 0;\n\n  const partialStatus = hasPartialPayments\n    ? getPartialPaymentStatus(repaymentAmount ?? 0, partialPayments)\n    : null;\n\n  // COMPLETED without partial payments — no badge\n  if (status === 'COMPLETED' && !hasPartialPayments) {\n    return null;\n  }\n\n  const getTooltipContent = () => {\n    if (hasPartialPayments && currency != null && repaymentAmount != null) {\n      const totalReceived = partialPayments.reduce(\n        (sum, p) => sum + p.amount,\n        0,\n      );\n      const outstanding = repaymentAmount - totalReceived;\n\n      return (\n        <PartialPaymentTooltip\n          totalAmount={repaymentAmount}\n          outstandingAmount={Math.max(outstanding, 0)}\n          partialPayments={partialPayments}\n          currency={currency}\n        />\n      );\n    }\n\n    if (status === 'PENDING' || status === 'FAILED') {\n      return (\n        <div>\n          <Typography weight=\"strong\" size=\"xs\">\n            {t('tooltip.title', { context: status })}\n          </Typography>\n          <Typography size=\"xs\">\n            {t('tooltip.description', { context: status })}\n          </Typography>\n        </div>\n      );\n    }\n\n    return null;\n  };\n\n  const statusBadge = (\n    <StatusBadge status={status} partialStatus={partialStatus}>\n      {getStatusIcon(status, partialStatus)}\n      {children}\n    </StatusBadge>\n  );\n\n  const tooltipContent = getTooltipContent();\n  if (tooltipContent) {\n    return (\n      <HtmlTooltip content={tooltipContent} triggerComponent={statusBadge} />\n    );\n  }\n\n  return statusBadge;\n};\n\nfunction getPartialPaymentStatus(\n  repaymentAmount: number,\n  partialPayments: PartialPayment[],\n): 'partial' | 'full' {\n  const totalReceived = partialPayments.reduce((sum, p) => sum + p.amount, 0);\n  return totalReceived >= repaymentAmount ? 'full' : 'partial';\n}\n","import styled from '@emotion/styled';\nimport { FunctionComponent, ReactNode } from 'react';\n\nimport { TableCell } from '../HistoryTable.styled';\n\ninterface PaymentCellProps {\n  status?: 'PENDING' | 'FAILED' | 'COMPLETED';\n  align?: 'left' | 'center' | 'right';\n  lastRow?: boolean;\n  children: ReactNode;\n}\n\nconst StyledTableCell = styled(TableCell, {\n  shouldForwardProp: (p) => p !== 'isFailed',\n})<{ isFailed: boolean }>(({ isFailed, theme: { breakpoints } }) => ({\n  ...(isFailed && {\n    color: 'var(--mui-components-variables-colors-grey700)',\n    textDecoration: 'line-through',\n\n    [breakpoints.up('desktop')]: {\n      color: 'var(--mui-components-variables-colors-grey700)',\n    },\n  }),\n}));\n\nexport const PaymentCell: FunctionComponent<PaymentCellProps> = ({\n  status,\n  align,\n  lastRow,\n  children,\n}) => {\n  const isFailed = status === 'FAILED';\n\n  return (\n    <StyledTableCell isFailed={isFailed} align={align} lastRow={lastRow}>\n      {children}\n    </StyledTableCell>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport { LoaderCircle, Flex } from '@finmid/tiger-webapp/components';\nimport {\n  AcceptedCredit,\n  RepaymentHistoryItem,\n} from '@finmid/tiger-webapp/queries';\nimport { useFormat } from '@finmid/translations';\nimport { TableRow, useMediaQuery } from '@mui/material';\nimport currencyJs from 'currency.js';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { HistorySeparator, TableCell } from '../HistoryTable.styled';\nimport { PaymentStatusBadge, PaymentCell } from '../components';\n\nexport interface BaseProps {\n  credit: AcceptedCredit;\n  data: RepaymentHistoryItem[];\n  rollingOutstandingBalance: number;\n  lastHistoryRow: boolean;\n}\n\nexport interface SetupSpecificProps {\n  showSalesAmount: boolean;\n  repaymentKey: 'REPAYMENT' | 'PAYMENT';\n}\n\ntype Props = BaseProps & SetupSpecificProps;\n\nexport const BaseCreditHistoryRows: FunctionComponent<Props> = ({\n  credit,\n  data,\n  rollingOutstandingBalance,\n  lastHistoryRow,\n  showSalesAmount,\n  repaymentKey,\n}) => {\n  const { t } = useTranslation('dashboard', { keyPrefix: 'table' });\n  const { money, shortDate } = useFormat();\n  const { breakpoints } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n\n  const { currency } = credit;\n\n  const { amount, fee } = credit.payout ?? {\n    fee: 0,\n    amount: 0,\n  };\n\n  return data == null ? (\n    <TableRow>\n      <TableCell align=\"center\">\n        <LoaderCircle />\n      </TableCell>\n    </TableRow>\n  ) : (\n    <>\n      {data.map(\n        ({\n          id,\n          batchDate,\n          remainingAmount,\n          repaymentAmount,\n          salesAmount,\n          status,\n          partialPayments,\n        }) => {\n          const hasPartialPayments =\n            partialPayments != null && partialPayments.length > 0;\n          const displayedAmount = hasPartialPayments\n            ? partialPayments.reduce((sum, p) => sum + p.amount, 0)\n            : repaymentAmount;\n\n          return (\n            <TableRow key={id}>\n              {!isMobile && (\n                <PaymentCell status={status}>\n                  <Flex\n                    alignItems=\"center\"\n                    justifyContent=\"flex-start\"\n                    gap=\"sm\"\n                  >\n                    <PaymentStatusBadge\n                      status={status}\n                      partialPayments={partialPayments}\n                      repaymentAmount={repaymentAmount}\n                      currency={currency}\n                    />\n                    <div>{t(`transactionType.${repaymentKey}`, 'Payment')}</div>\n                  </Flex>\n                </PaymentCell>\n              )}\n              <PaymentCell status={status}>\n                <Flex alignItems=\"center\" justifyContent=\"flex-start\" gap=\"sm\">\n                  {isMobile && (\n                    <PaymentStatusBadge\n                      status={status}\n                      partialPayments={partialPayments}\n                      repaymentAmount={repaymentAmount}\n                      currency={currency}\n                    />\n                  )}\n                  <div>{shortDate(new Date(batchDate))}</div>\n                </Flex>\n              </PaymentCell>\n              {showSalesAmount && (\n                <PaymentCell status={status} align=\"right\">\n                  {money(salesAmount, currency)}\n                </PaymentCell>\n              )}\n              <PaymentCell status={status} align=\"right\">\n                - {money(displayedAmount, currency)}\n              </PaymentCell>\n              {!isMobile && (\n                <PaymentCell status={status} align=\"right\">\n                  {money(remainingAmount, currency)}\n                </PaymentCell>\n              )}\n            </TableRow>\n          );\n        },\n      )}\n\n      <TableRow key={'payout'}>\n        {!isMobile && (\n          <TableCell>{t('transactionType.PAYOUT', 'Payout')}</TableCell>\n        )}\n        <TableCell>\n          {shortDate(new Date(credit.payout?.paidOutAt ?? credit.acceptedAt))}\n        </TableCell>\n        {showSalesAmount && <TableCell align=\"right\">---</TableCell>}\n        <TableCell align=\"right\">+ {money(amount, currency)}</TableCell>\n        {!isMobile && (\n          <TableCell align=\"right\">\n            {money(\n              currencyJs(rollingOutstandingBalance).add(fee).add(amount).value,\n              currency,\n            )}\n          </TableCell>\n        )}\n      </TableRow>\n\n      <TableRow key={'fee'}>\n        {!isMobile && (\n          <TableCell lastRow={lastHistoryRow}>\n            {t('transactionType.FEE', 'Fee')}\n          </TableCell>\n        )}\n        <TableCell lastRow={lastHistoryRow}>\n          {shortDate(new Date(credit.payout?.paidOutAt ?? credit.acceptedAt))}\n        </TableCell>\n        {showSalesAmount && (\n          <TableCell align=\"right\" lastRow={lastHistoryRow}>\n            ---\n          </TableCell>\n        )}\n        <TableCell align=\"right\" lastRow={lastHistoryRow}>\n          + {money(fee, currency)}\n        </TableCell>\n        {!isMobile && (\n          <TableCell align=\"right\" lastRow={lastHistoryRow}>\n            {money(\n              currencyJs(rollingOutstandingBalance).add(fee).value,\n              currency,\n            )}\n          </TableCell>\n        )}\n      </TableRow>\n\n      {!lastHistoryRow && (\n        <TableRow>\n          <HistorySeparator colSpan={100} />\n        </TableRow>\n      )}\n    </>\n  );\n};\n","import { FinancingSetup, RepaymentType } from '@finmid/tiger-webapp/queries';\nimport { FunctionComponent } from 'react';\n\nimport {\n  BaseCreditHistoryRows,\n  type SetupSpecificProps,\n  type BaseProps,\n} from './BaseCreditHistoryRows';\n\nconst components: Record<\n  FinancingSetup,\n  Record<RepaymentType, SetupSpecificProps | null>\n> = {\n  MCA: {\n    FLEXIBLE: {\n      showSalesAmount: true,\n      repaymentKey: 'PAYMENT',\n    },\n    FIXED: null,\n  },\n  CSP: {\n    FLEXIBLE: {\n      showSalesAmount: true,\n      repaymentKey: 'REPAYMENT',\n    },\n    FIXED: {\n      showSalesAmount: false,\n      repaymentKey: 'REPAYMENT',\n    },\n  },\n};\n\nexport const CreditHistoryRows: FunctionComponent<BaseProps> = ({\n  credit,\n  data,\n  rollingOutstandingBalance,\n  lastHistoryRow,\n}) => {\n  const props = components[credit.financingSetup][credit.repaymentType];\n\n  if (props == null) {\n    throw new Error(\n      `No history rows configuration found for financingSetup: ${credit.financingSetup}, repaymentType: ${credit.repaymentType}`,\n    );\n  }\n\n  return (\n    <BaseCreditHistoryRows\n      credit={credit}\n      data={data}\n      rollingOutstandingBalance={rollingOutstandingBalance}\n      lastHistoryRow={lastHistoryRow}\n      {...props}\n    />\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport { TableRow, useMediaQuery } from '@mui/material';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { TableCell } from '../HistoryTable.styled';\n\nexport interface SetupSpecificProps {\n  showDailySales: boolean;\n}\n\nexport const BaseTableHeaderRow: FunctionComponent<SetupSpecificProps> = ({\n  showDailySales,\n}) => {\n  const { t } = useTranslation('dashboard', { keyPrefix: 'table' });\n  const { breakpoints } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n\n  return (\n    <TableRow>\n      {!isMobile && (\n        <TableCell>{t('header.transactionType', 'Transaction type')}</TableCell>\n      )}\n      <TableCell>{t('header.date', 'Date')}</TableCell>\n      {showDailySales && (\n        <TableCell align=\"right\">\n          {t('header.dailySales', 'Daily sales')}\n        </TableCell>\n      )}\n      <TableCell align=\"right\">\n        {isMobile\n          ? t('header.repaymentAmountMobile', 'Remittance')\n          : t('header.repaymentAmount', 'Remittance amount')}\n      </TableCell>\n      {!isMobile && (\n        <TableCell align=\"right\">\n          {t('header.remainingAmount', 'Outstanding amount')}\n        </TableCell>\n      )}\n    </TableRow>\n  );\n};\n","import { FinancingSetup, RepaymentType } from '@finmid/tiger-webapp/queries';\nimport { FunctionComponent } from 'react';\n\nimport {\n  BaseTableHeaderRow,\n  type SetupSpecificProps,\n} from './BaseTableHeaderRow';\n\ninterface Props {\n  financingSetup: FinancingSetup;\n  repaymentType: RepaymentType;\n}\n\nconst headerComponents: Record<\n  FinancingSetup,\n  Record<RepaymentType, SetupSpecificProps | null>\n> = {\n  MCA: {\n    FLEXIBLE: {\n      showDailySales: true,\n    },\n    FIXED: null,\n  },\n  CSP: {\n    FLEXIBLE: {\n      showDailySales: true,\n    },\n    FIXED: {\n      showDailySales: false,\n    },\n  },\n};\n\nexport const TableHeaderRow: FunctionComponent<Props> = ({\n  financingSetup,\n  repaymentType,\n}) => {\n  const props = headerComponents[financingSetup][repaymentType];\n\n  if (props == null) {\n    throw new Error(\n      `No header component configuration found for financingSetup: ${financingSetup}, repaymentType: ${repaymentType}`,\n    );\n  }\n\n  return <BaseTableHeaderRow {...props} />;\n};\n","import { GetRepaymentHistoryResponse } from '@finmid/tiger-webapp/queries';\nimport currency from 'currency.js';\nimport orderBy from 'lodash/orderBy';\nimport { useMemo } from 'react';\n\ninterface Options {\n  creditList: GetRepaymentHistoryResponse[];\n}\n\nexport const useWithRollingOutstandingBalance = ({ creditList }: Options) => {\n  return useMemo(\n    () => calculateRollingOutstandingBalance({ creditList }),\n    [creditList],\n  );\n};\n\nexport const calculateRollingOutstandingBalance = ({ creditList }: Options) => {\n  const sortedCreditList = orderBy(creditList, (c) => c.credit.acceptedAt, [\n    'desc',\n  ]);\n\n  return sortedCreditList.map(({ credit, data }, index) => {\n    const rollingOutstandingBalance = sortedCreditList.slice(index + 1).reduce(\n      (acc, { credit, data }) =>\n        currency(credit.payout?.amount ?? 0)\n          .add(credit.payout?.fee ?? 0)\n          .subtract(\n            data.reduce(\n              (acc, { repaymentAmount }) => currency(acc).add(repaymentAmount),\n              currency(0),\n            ) ?? currency(0),\n          )\n          .add(acc),\n      currency(0),\n    ).value;\n\n    return {\n      credit,\n      data,\n      rollingOutstandingBalance,\n    };\n  });\n};\n","import { LoaderCircle } from '@finmid/tiger-webapp/components';\nimport { GetRepaymentHistoryResponse } from '@finmid/tiger-webapp/queries';\nimport {\n  Table as BaseTable,\n  TableBody,\n  TableHead,\n  TableRow,\n} from '@mui/material';\nimport { FunctionComponent } from 'react';\n\nimport { CreditHistoryRows } from './CreditHistoryRows';\nimport { TableCell, TableContainer } from './HistoryTable.styled';\nimport { TableHeaderRow } from './TableHeaderRow';\nimport { useWithRollingOutstandingBalance } from './useWithRollingOutstandingBalance';\n\ninterface Props {\n  creditList: GetRepaymentHistoryResponse[];\n}\n\nexport const HistoryTable: FunctionComponent<Props> = ({ creditList }) => {\n  const sortedCreditList = useWithRollingOutstandingBalance({ creditList });\n\n  const firstCredit = creditList.at(0)?.credit;\n\n  return (\n    <TableContainer>\n      <BaseTable stickyHeader>\n        <TableHead>\n          <TableHeaderRow\n            financingSetup={firstCredit?.financingSetup ?? 'MCA'}\n            repaymentType={firstCredit?.repaymentType ?? 'FLEXIBLE'}\n          />\n        </TableHead>\n        <TableBody>\n          {creditList == null || creditList.length === 0 ? (\n            <TableRow>\n              <TableCell align=\"center\">\n                <LoaderCircle />\n              </TableCell>\n            </TableRow>\n          ) : (\n            sortedCreditList.map(\n              ({ credit, data, rollingOutstandingBalance }, index) => (\n                <CreditHistoryRows\n                  key={credit.id}\n                  data={data}\n                  credit={credit}\n                  rollingOutstandingBalance={rollingOutstandingBalance}\n                  lastHistoryRow={index + 1 === sortedCreditList.length}\n                />\n              ),\n            )\n          )}\n        </TableBody>\n      </BaseTable>\n    </TableContainer>\n  );\n};\n","import type { RepaymentHistoryItem } from '@finmid/tiger-webapp/queries';\nimport { downloadCsvFile as downloadCsvFileBase } from '@finmid/utils';\nimport type { TFunction } from 'i18next';\n\nexport const downloadCsvFile = (\n  t: TFunction,\n  items: RepaymentHistoryItem[],\n) => {\n  downloadCsvFileBase(\n    [\n      t('header.id'),\n      t('header.status'),\n      t('header.date'),\n      t('header.dailySales'),\n      t('header.repaymentAmount'),\n      t('header.remainingAmount'),\n    ],\n    [\n      'id',\n      'status',\n      'batchDate',\n      'salesAmount',\n      'repaymentAmount',\n      'remainingAmount',\n    ],\n    items.map((i) => ({ ...i, batchDate: new Date(i.batchDate) })),\n    {\n      fileName: t('fileName', 'Remittance history.csv'),\n      separator: ';',\n    },\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  Button,\n  customized,\n  customizeStyles,\n  Typography,\n} from '@finmid/tiger-webapp/components';\n\nexport const Container = styled('div')(\n  ({\n    theme,\n    theme: {\n      vars: { components },\n    },\n  }) => ({\n    display: 'flex',\n    flexDirection: 'column',\n    justifyContent: 'space-between',\n    alignItems: 'start',\n    width: '100%',\n\n    gap: components?.variables?.spacings?.md,\n    padding: components?.variables?.spacings?.md,\n    borderRadius: components?.variables?.radius?.md,\n    border: `1px solid ${components?.variables?.colors?.grey300}`,\n    backgroundColor: components?.variables?.colors?.white,\n\n    [theme.breakpoints.up('desktop')]: {\n      gap: components?.variables?.spacings?.xl,\n      flexDirection: 'row',\n    },\n\n    ...customizeStyles(\n      theme,\n      (customizations) =>\n        customizations?.dashboard?.newOfferBanner?.full?.container,\n    ),\n  }),\n);\n\nexport const ContainerBannerSlot = styled('div')({\n  display: 'none',\n});\n\nexport const ContainerButtonGroup = styled('div')(\n  ({\n    theme,\n    theme: {\n      vars: { components },\n    },\n  }) => ({\n    display: 'flex',\n    flexDirection: 'row',\n    gap: components?.variables?.spacings?.md,\n\n    ...customizeStyles(\n      theme,\n      (customizations) =>\n        customizations?.dashboard?.newOfferBanner?.full?.buttonGroup,\n    ),\n  }),\n);\n\nexport const Title = customized(\n  Typography,\n  (c) => c?.dashboard?.newOfferBanner?.full?.title,\n);\n\nexport const Description = customized(\n  Typography,\n  (c) => c?.dashboard?.newOfferBanner?.full?.description,\n);\n\nexport const MiniContainer = styled('div')(({ theme }) => ({\n  display: 'flex',\n  padding: theme.vars?.components?.variables.spacings.md,\n  gap: '16px',\n  alignItems: 'start',\n  justifyContent: 'start',\n  width: '100%',\n\n  borderRadius: theme.vars?.components?.variables.radius.md,\n  border: `1px solid ${theme.vars?.components?.variables.colors.grey300}`,\n  backgroundColor: theme.vars?.components?.variables.colors.white,\n\n  ...customizeStyles(\n    theme,\n    (customizations) =>\n      customizations?.dashboard?.newOfferBanner?.mini?.container,\n  ),\n}));\n\nexport const FullDismissButton = styled(Button)(({ theme }) => ({\n  ...customizeStyles(\n    theme,\n    (customizations) =>\n      customizations?.dashboard?.newOfferBanner?.full?.dismissButton,\n  ),\n}));\n\nexport const FullCallToActionButton = styled(Button)(({ theme }) => ({\n  [theme.breakpoints.up('desktop')]: {\n    whiteSpace: 'nowrap',\n  },\n\n  ...customizeStyles(\n    theme,\n    (customizations) =>\n      customizations?.dashboard?.newOfferBanner?.full?.callToActionButton,\n  ),\n}));\n","import {\n  captureOfferEvent,\n  Flex,\n  StandaloneLink,\n  Typography,\n  useTailoredOffers,\n} from '@finmid/tiger-webapp/components';\nimport { useFormat } from '@finmid/translations';\nimport { useLocalStorageValue } from '@react-hookz/web';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport {\n  Container,\n  ContainerBannerSlot,\n  ContainerButtonGroup,\n  Description,\n  FullCallToActionButton,\n  FullDismissButton,\n  MiniContainer,\n  Title,\n} from './NewOfferBanner.styled';\n\ninterface Props {\n  variant: 'full' | 'mini';\n}\n\nexport const NewOfferBanner = ({ variant }: Props) => {\n  const { t } = useTranslation('turnkey');\n  const { money } = useFormat();\n\n  const { offers, currency } = useTailoredOffers();\n\n  const maxOffer =\n    offers?.length &&\n    offers?.reduce((prev, current) =>\n      prev.payoutAmount > current.payoutAmount ? prev : current,\n    );\n  const { value: dismissedOffers, set: setDismissedOffers } =\n    useLocalStorageValue<string[]>('capital.dismissedOffers', {\n      defaultValue: [],\n    });\n\n  const navigate = useNavigate();\n\n  if (!maxOffer) {\n    return null;\n  }\n\n  if (dismissedOffers?.includes(maxOffer.id)) {\n    if (variant === 'full') {\n      return null;\n    }\n    return (\n      <MiniContainer data-test-id=\"new-offer-mini-banner\">\n        <ContainerBannerSlot className=\"new-offer-mini-banner-slot\" />\n        <Flex flexDirection={'column'} gap=\"md\" alignItems={'flex-start'}>\n          <Typography size=\"sm\" weight=\"strong\">\n            {t('dashboard.newOfferMiniBanner.title', {\n              amount: money(maxOffer.payoutAmount, currency, {\n                maximumFractionDigits: 0,\n              }),\n              defaultValue:\n                \"You're approved for {{amount}} with a lower access fee\",\n            })}\n          </Typography>\n          <StandaloneLink\n            testId=\"accept-button\"\n            onClick={() => {\n              captureOfferEvent(\n                'Get more capital button clicked',\n                maxOffer,\n                currency,\n                {\n                  renewal: true,\n                },\n                { bannerVariant: 'mini' },\n              );\n              navigate('/renewal/overview');\n            }}\n          >\n            {t('dashboard.seeOffer')}\n          </StandaloneLink>\n        </Flex>\n      </MiniContainer>\n    );\n  } else if (variant === 'mini') {\n    return null;\n  }\n\n  return (\n    <Container data-test-id=\"new-offer-banner\">\n      <Flex flexDirection={['column', 'column', 'row']}>\n        <ContainerBannerSlot className=\"new-offer-banner-slot\" />\n        <Flex flexDirection={'column'} gap=\"sm\" alignItems={'flex-start'}>\n          <Title size=\"md\" weight=\"strong\">\n            {t('dashboard.newOfferBanner.title', {\n              amount: money(maxOffer.payoutAmount, currency, {\n                maximumFractionDigits: 0,\n              }),\n              defaultValue:\n                'New {{platform}} Capital offer available: {{amount}} with a lower access fee',\n            })}\n          </Title>\n          <Description size=\"sm\">\n            {t('dashboard.newOffer.description')}\n          </Description>\n        </Flex>\n      </Flex>\n\n      <ContainerButtonGroup>\n        <FullDismissButton\n          variant=\"secondary\"\n          data-test-id=\"dismiss-button\"\n          onClick={() => {\n            setDismissedOffers([...(dismissedOffers || []), maxOffer.id]);\n            captureOfferEvent('User dismissed offer', maxOffer, currency, {\n              renewal: true,\n            });\n          }}\n        >\n          {t('dashboard.dismiss')}\n        </FullDismissButton>\n        <FullCallToActionButton\n          variant=\"primary\"\n          data-test-id=\"accept-button\"\n          onClick={() => {\n            captureOfferEvent(\n              'Get more capital button clicked',\n              maxOffer,\n              currency,\n              {\n                renewal: true,\n              },\n              { bannerVariant: 'full' },\n            );\n            navigate('/renewal/overview');\n          }}\n        >\n          {t('dashboard.seeOffer')}\n        </FullCallToActionButton>\n      </ContainerButtonGroup>\n    </Container>\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  Flex,\n  customizeStyles,\n  Typography,\n} from '@finmid/tiger-webapp/components';\nimport { FunctionComponent } from 'react';\n\nexport const Wrapper = styled(Flex)(({ theme: { breakpoints } }) => ({\n  flexGrow: 1,\n  flexDirection: 'column',\n  alignItems: 'baseline',\n\n  [breakpoints.down('desktop')]: {\n    alignItems: 'center',\n    width: '100%',\n  },\n}));\n\nexport const DetailsContainer = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    width: '100%',\n\n    flexGrow: 1,\n    flexDirection: 'column',\n    alignItems: 'center',\n\n    [breakpoints.up('tablet')]: {\n      minWidth: 300,\n    },\n\n    ...customizeStyles({ breakpoints, vars }, (c) => c?.dashboard?.stats?.root),\n  }),\n);\n\nexport const Footer = styled(Flex)(({ theme: { vars, breakpoints } }) => ({\n  width: '100%',\n\n  padding: vars?.components?.variables.spacings.md,\n  backgroundColor: vars.components?.variables.colors.white,\n\n  ...customizeStyles(\n    { breakpoints, vars },\n    (c) => c?.dashboard?.stats?.details,\n  ),\n}));\n\nexport const DetailsWrapper = styled(Flex)(\n  ({ theme: { breakpoints, vars } }) => ({\n    width: '100%',\n    flexDirection: 'column',\n    justifyContent: 'flex-start',\n\n    backgroundColor: vars.components?.variables.colors.white,\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.dashboard?.stats?.details,\n    ),\n  }),\n);\n\nexport const DetailsLineWrapper = styled(Flex, {\n  shouldForwardProp: (prop) => prop !== 'gray',\n})<{ gray?: boolean }>(({ theme: { breakpoints, vars }, gray }) => ({\n  gap: 4,\n\n  width: '100%',\n  flexDirection: 'row',\n  justifyContent: 'space-between',\n  zIndex: 1,\n  whiteSpace: 'nowrap',\n  flexWrap: 'wrap',\n\n  padding: vars.components?.variables.spacings.md,\n  borderBottom: `1px solid ${vars.components?.variables.colors.grey300}`,\n\n  backgroundColor: gray ? vars.components?.variables.colors.grey100 : undefined,\n\n  '&:nth-last-of-type(1), &:nth-last-of-type(2)': {\n    backgroundColor: vars.components?.variables.colors.grey100,\n  },\n\n  ...customizeStyles(\n    { breakpoints, vars },\n    (c) => c?.dashboard?.stats?.detailsLine,\n  ),\n}));\n\ninterface DetailsLineProps {\n  title: string;\n  value: string;\n  bold?: boolean;\n  gray?: boolean;\n}\n\nconst DetailsLineTitle = styled(Typography)({});\n\nexport const DetailsLine: FunctionComponent<DetailsLineProps> = ({\n  title,\n  value,\n  gray,\n}) => (\n  <DetailsLineWrapper gray={gray}>\n    <DetailsLineTitle size=\"sm\" weight={['strong', 'default']}>\n      {title}\n    </DetailsLineTitle>\n    <Typography size=\"sm\" weight=\"strong\">\n      {value}\n    </Typography>\n  </DetailsLineWrapper>\n);\n\nexport const ViewDetailsButton = styled.button(\n  ({ theme: { breakpoints, vars } }) => ({\n    padding: 11,\n    cursor: 'pointer',\n    border: 'none',\n    background: 'none',\n    width: '100%',\n    height: '100%',\n\n    color: vars.components?.variables.colors.primaryDefault,\n\n    fontFamily: vars.components?.variables.typography.mobile.family.body,\n    fontSize: vars.components?.variables.typography.mobile.size.sm,\n    lineHeight: vars.components?.variables.typography.mobile.lineHeight.sm,\n    fontWeight: vars.components?.variables.typography.mobile.weight.strong,\n\n    [breakpoints.up('desktop')]: {\n      fontFamily: vars.components?.variables.typography.desktop.family.body,\n      fontSize: vars.components?.variables.typography.desktop.size.sm,\n      lineHeight: vars.components?.variables.typography.desktop.lineHeight.sm,\n      fontWeight: vars.components?.variables.typography.desktop.weight.strong,\n    },\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.dashboard?.stats?.detailsButton,\n    ),\n  }),\n);\n","import { useMessenger } from '@finmid/tiger-webapp/components';\nimport { AcceptedCredit } from '@finmid/tiger-webapp/queries';\nimport { useFormat } from '@finmid/translations';\nimport toCurrency from 'currency.js';\nimport capitalize from 'lodash/capitalize';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { DetailsLine, DetailsWrapper } from '../PlanDetails.styled';\n\ninterface Props {\n  credit: AcceptedCredit;\n}\n\nexport const CspFixedDetails: FunctionComponent<Props> = ({ credit }) => {\n  const { isEmbedded } = useMessenger();\n  const { t } = useTranslation('dashboard', {\n    keyPrefix: 'planDetails',\n  });\n  const { money, shortDate, months } = useFormat();\n\n  if (credit.financingSetup !== 'CSP' || credit.repaymentType !== 'FIXED') {\n    return null;\n  }\n\n  return (\n    <DetailsWrapper>\n      <DetailsLine\n        title={t('capitalRequested', 'Capital requested')}\n        value={money(credit.limit, credit.currency)}\n      />\n\n      <DetailsLine\n        title={t('fee', 'Fee')}\n        value={money(credit.fee, credit.currency)}\n      />\n\n      <DetailsLine\n        title={t(\n          `${credit.financingSetup}.totalRepaymentAmount`,\n          'Total repayment amount',\n        )}\n        value={money(\n          toCurrency(credit.fee).add(credit.limit).value,\n          credit.currency,\n        )}\n      />\n\n      {!isEmbedded && (\n        <DetailsLine\n          title={t('creditAcceptedAtDate', 'Credit date')}\n          value={shortDate(new Date(credit.acceptedAt))}\n        />\n      )}\n      <DetailsLine\n        gray\n        title={t(\n          `${credit.financingSetup}.estimatedPayoffTimeLabel`,\n          'Est. repayment time',\n        )}\n        value={months(credit.repaymentPeriodMonthsEstimation)}\n      />\n      <DetailsLine\n        gray\n        title={t(\n          `${credit.repaymentType}.repaymentFrequencyLabel`,\n          'Repayment frequency',\n        )}\n        value={t(\n          `${credit.repaymentType}.repaymentFrequency.${credit.repaymentFrequency}`,\n          {\n            defaultValue: capitalize(credit.repaymentFrequency),\n          },\n        )}\n      />\n      <DetailsLine\n        gray\n        title={t(\n          `${credit.repaymentType}.repaymentAmountLabel`,\n          'Repayment amount',\n        )}\n        value={t(\n          `${credit.repaymentType}.repaymentAmountValue.${credit.repaymentFrequency}`,\n          {\n            defaultValue: `{{amount}}/${credit.repaymentFrequency.toLowerCase()}`,\n            amount: money(credit.repaymentAmount, credit.currency),\n          },\n        )}\n      />\n    </DetailsWrapper>\n  );\n};\n","import { useMessenger } from '@finmid/tiger-webapp/components';\nimport { AcceptedCredit } from '@finmid/tiger-webapp/queries';\nimport { useFormat } from '@finmid/translations';\nimport toCurrency from 'currency.js';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { DetailsLine, DetailsWrapper } from '../PlanDetails.styled';\n\ninterface Props {\n  credit: AcceptedCredit;\n}\n\nexport const CspFlexibleDetails: FunctionComponent<Props> = ({ credit }) => {\n  const { isEmbedded } = useMessenger();\n  const { t } = useTranslation('dashboard', {\n    keyPrefix: 'planDetails',\n  });\n  const { money, shortDate, months } = useFormat();\n\n  if (credit.financingSetup !== 'CSP' || credit.repaymentType !== 'FLEXIBLE') {\n    return null;\n  }\n\n  return (\n    <DetailsWrapper>\n      <DetailsLine\n        title={t('capitalRequested', 'Capital requested')}\n        value={money(credit.limit, credit.currency)}\n      />\n\n      <DetailsLine\n        title={t('fee', 'Fee')}\n        value={money(credit.fee, credit.currency)}\n      />\n\n      <DetailsLine\n        title={t(\n          `${credit.financingSetup}.totalRepaymentAmount`,\n          'Total repayment amount',\n        )}\n        value={money(\n          toCurrency(credit.fee).add(credit.limit).value,\n          credit.currency,\n        )}\n      />\n\n      {!isEmbedded && (\n        <DetailsLine\n          title={t('creditAcceptedAtDate', 'Credit date')}\n          value={shortDate(new Date(credit.acceptedAt))}\n        />\n      )}\n      <DetailsLine\n        title={t('repaymentRate', 'Repayment rate')}\n        value={`${credit.repaymentPercentage}%`}\n      />\n      <DetailsLine\n        gray\n        title={t(\n          `${credit.financingSetup}.estimatedPayoffTimeLabel`,\n          'Est. payment time',\n        )}\n        value={months(credit.repaymentPeriodMonthsEstimation)}\n      />\n    </DetailsWrapper>\n  );\n};\n","import { useMessenger } from '@finmid/tiger-webapp/components';\nimport { AcceptedCredit } from '@finmid/tiger-webapp/queries';\nimport { useFormat } from '@finmid/translations';\nimport toCurrency from 'currency.js';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { DetailsLine, DetailsWrapper } from '../PlanDetails.styled';\n\ninterface Props {\n  credit: AcceptedCredit;\n}\n\nexport const McaFlexibleDetails: FunctionComponent<Props> = ({ credit }) => {\n  const { isEmbedded } = useMessenger();\n  const { t } = useTranslation('dashboard', {\n    keyPrefix: 'planDetails',\n  });\n  const { money, shortDate, months } = useFormat();\n\n  if (credit.financingSetup !== 'MCA' || credit.repaymentType !== 'FLEXIBLE') {\n    return null;\n  }\n\n  return (\n    <DetailsWrapper>\n      <DetailsLine\n        title={t('capitalRequested', 'Capital requested')}\n        value={money(credit.limit, credit.currency)}\n      />\n\n      <DetailsLine\n        title={t('fee', 'Fee')}\n        value={money(credit.fee, credit.currency)}\n      />\n\n      <DetailsLine\n        title={t(\n          `${credit.financingSetup}.totalRepaymentAmount`,\n          'Total repayment amount',\n        )}\n        value={money(\n          toCurrency(credit.fee).add(credit.limit).value,\n          credit.currency,\n        )}\n      />\n\n      {!isEmbedded && (\n        <DetailsLine\n          title={t('creditAcceptedAtDate', 'Credit date')}\n          value={shortDate(new Date(credit.acceptedAt))}\n        />\n      )}\n      <DetailsLine\n        title={t('repaymentRate', 'Repayment rate')}\n        value={`${credit.repaymentPercentage}%`}\n      />\n      <DetailsLine\n        gray\n        title={t(\n          `${credit.financingSetup}.estimatedPayoffTimeLabel`,\n          'Est. payment time',\n        )}\n        value={months(credit.repaymentPeriodMonthsEstimation)}\n      />\n    </DetailsWrapper>\n  );\n};\n","import { AcceptedCredit } from '@finmid/tiger-webapp/queries';\nimport { FunctionComponent } from 'react';\n\nimport { CspFixedDetails } from './CspFixedDetails';\nimport { CspFlexibleDetails } from './CspFlexibleDetails';\nimport { McaFlexibleDetails } from './McaFlexibleDetails';\n\ninterface Props {\n  credit: AcceptedCredit;\n}\n\nconst detailsComponents: Record<\n  string,\n  Record<string, FunctionComponent<Props>>\n> = {\n  MCA: {\n    FLEXIBLE: McaFlexibleDetails,\n  },\n  CSP: {\n    FLEXIBLE: CspFlexibleDetails,\n    FIXED: CspFixedDetails,\n  },\n};\n\nexport const Details: FunctionComponent<Props> = ({ credit }) => {\n  const Component =\n    detailsComponents[credit.financingSetup]?.[credit.repaymentType];\n\n  if (!Component) {\n    throw new Error(\n      `No details component found for financingSetup: ${credit.financingSetup}, repaymentType: ${credit.repaymentType}`,\n    );\n  }\n\n  return <Component credit={credit} />;\n};\n","import { useTheme } from '@emotion/react';\nimport { useCssVariable } from '@finmid/tiger-webapp/components';\nimport { FunctionComponent } from 'react';\nimport { Cell, Pie, PieChart } from 'recharts';\n\ninterface Props {\n  repaidAmount: number;\n  remainingAmount: number;\n}\n\nconst DEFAULT_INNER_RADIUS = 102;\nconst DEFAULT_OUTER_RADIUS = 110;\n\nexport const RepaymentPieChart: FunctionComponent<Props> = ({\n  remainingAmount,\n  repaidAmount,\n}) => {\n  const { vars } = useTheme();\n\n  const COLORS = [\n    vars.components?.dashboard?.stats?.pieChart?.emptyColor ??\n      vars.components?.variables.colors.grey300,\n    vars.components?.dashboard?.stats?.pieChart?.fillColor ??\n      vars.components?.variables.colors?.primaryDefault,\n  ];\n\n  const data = [\n    {\n      value: remainingAmount,\n    },\n    {\n      value: repaidAmount,\n    },\n  ];\n\n  const innerRadius = useCssVariable(\n    'dashboard.stats.pieChart.innerRadius',\n    (c) => c?.dashboard?.stats?.pieChart?.innerRadius,\n    `${DEFAULT_INNER_RADIUS}px`,\n  ).replace('px', '');\n\n  const outerRadius = useCssVariable(\n    'dashboard.stats.pieChart.outerRadius',\n    (c) => c?.dashboard?.stats?.pieChart?.outerRadius,\n    `${DEFAULT_OUTER_RADIUS}px`,\n  ).replace('px', '');\n\n  return (\n    <PieChart width={220} height={220}>\n      <Pie\n        data={data}\n        cx=\"50%\"\n        cy=\"50%\"\n        labelLine={false}\n        outerRadius={outerRadius || DEFAULT_OUTER_RADIUS}\n        innerRadius={innerRadius || DEFAULT_INNER_RADIUS}\n        fill=\"#8884d8\"\n        dataKey=\"value\"\n        startAngle={-270}\n        endAngle={90}\n        isAnimationActive={false}\n        cornerRadius={15}\n        paddingAngle={-5}\n        strokeWidth={0}\n      >\n        {data.map((_, index) => (\n          <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />\n        ))}\n      </Pie>\n    </PieChart>\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  Typography,\n  Flex,\n  customizeStyles,\n} from '@finmid/tiger-webapp/components';\nimport { useFormat } from '@finmid/translations';\nimport { Currency } from '@finmid/types';\nimport {} from '@mui/material';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { RepaymentPieChart } from './RepaymentPieChart';\n\ninterface Props {\n  remainingAmount: number;\n  repaidAmount: number;\n  hidden: boolean;\n  currency: Currency;\n}\n\nconst Wrapper = styled(Flex)(({ theme, theme: { vars } }) => ({\n  position: 'relative',\n  height: 220,\n  width: 220,\n  flexDirection: 'column',\n  justifyContent: 'center',\n  padding: '0 16px',\n  borderRadius: '50%',\n\n  backgroundColor: vars.components?.variables.colors.grey100,\n\n  ...customizeStyles(theme, (c) => c?.dashboard?.stats?.pieChart?.background),\n}));\n\nconst ChartContainer = styled.div({\n  position: 'absolute',\n  inset: 0,\n});\n\nconst Pill = styled(Typography)(({ theme: { vars, breakpoints } }) => ({\n  borderRadius: 160,\n  backgroundColor: vars.components?.variables.colors.success,\n  padding: '2px 8px',\n  marginBottom: vars.components?.variables.spacings.xs,\n\n  ...customizeStyles({ breakpoints, vars }, (c) => c?.dashboard?.stats?.pill),\n}));\n\nconst PieChartTitle = styled(Typography)(\n  ({ theme: { vars, breakpoints } }) => ({\n    fontWeight: 700,\n    fontSize: 20,\n    lineHeight: 1,\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.dashboard?.stats?.title,\n    ),\n  }),\n);\n\nexport const Stats: FunctionComponent<Props> = ({\n  remainingAmount,\n  repaidAmount,\n  hidden,\n  currency,\n}) => {\n  const { t } = useTranslation('dashboard', {\n    keyPrefix: 'planDetails.stats',\n  });\n  const { money } = useFormat();\n\n  const percentPaid = Math.round(\n    (repaidAmount / (repaidAmount + remainingAmount)) * 100,\n  );\n\n  return (\n    <Flex\n      display={hidden ? 'none' : 'flex'}\n      position={hidden ? 'relative' : 'absolute'}\n      data-test-id=\"remittance-stats\"\n      sx={({ vars }) => ({\n        inset: 0,\n        padding: vars.components?.variables?.spacings.md,\n        backgroundColor: 'white',\n        zIndex: 1,\n      })}\n    >\n      <Wrapper justifyContent=\"flex-start\">\n        <ChartContainer>\n          <RepaymentPieChart\n            remainingAmount={remainingAmount}\n            repaidAmount={repaidAmount}\n          />\n        </ChartContainer>\n\n        <Flex flexDirection=\"column\" gap=\"xs\">\n          <Pill size=\"xs\" weight=\"strong\" color=\"white\">\n            {t('percentPaid', {\n              defaultValue: '{{percent}}% paid',\n              percent: percentPaid,\n            })}\n          </Pill>\n          <PieChartTitle size=\"md\" weight=\"strong\">\n            {money(remainingAmount, currency, {\n              maximumFractionDigits: currency === 'EUR' ? 2 : 0,\n            })}\n          </PieChartTitle>\n          <Flex flexDirection=\"column\" gap=\"md\" textAlign=\"center\">\n            <Typography size=\"xs\">\n              {t('remainingAmount', 'Outstanding balance')}\n            </Typography>\n            <Typography size=\"xs\">\n              {t('repaidAmount', {\n                defaultValue: '{{amount}} paid',\n                amount: money(repaidAmount, currency),\n              })}\n            </Typography>\n          </Flex>\n        </Flex>\n      </Wrapper>\n    </Flex>\n  );\n};\n","import { Flex } from '@finmid/tiger-webapp/components';\nimport { AcceptedCredit } from '@finmid/tiger-webapp/queries';\nimport { forwardRef, useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { Details } from './Details';\nimport {\n  DetailsContainer,\n  Footer,\n  ViewDetailsButton,\n  Wrapper,\n} from './PlanDetails.styled';\nimport { Stats } from './Stats';\n\ninterface Props {\n  credit: AcceptedCredit;\n}\n\nexport const PlanDetails = forwardRef(({ credit }: Props, ref) => {\n  const { t } = useTranslation('dashboard', {\n    keyPrefix: 'planDetails',\n  });\n  const [showDetails, setShowDetails] = useState(false);\n\n  return (\n    <Wrapper data-test-id=\"plan-details\">\n      <DetailsContainer data-test-id=\"plan-details-container\">\n        <Flex flexDirection=\"column\" width=\"100%\" position=\"relative\">\n          <Details credit={credit} />\n          <Stats\n            currency={credit.currency}\n            remainingAmount={credit.remainingAmount}\n            repaidAmount={credit.repaidAmount}\n            hidden={showDetails}\n          />\n        </Flex>\n\n        <Footer>\n          <ViewDetailsButton onClick={() => setShowDetails((v) => !v)}>\n            {showDetails\n              ? t('hideDetails', 'Hide details')\n              : t('viewDetails', 'View details')}\n          </ViewDetailsButton>\n        </Footer>\n      </DetailsContainer>\n    </Wrapper>\n  );\n});\n","import { useTheme } from '@emotion/react';\nimport {\n  GetRepaymentHistoryResponse,\n  RepaymentHistoryItem,\n} from '@finmid/tiger-webapp/queries';\nimport { useMediaQuery } from '@mui/material';\nimport posthog from 'posthog-js';\nimport { FunctionComponent, useEffect, useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport {\n  Container as BalanceOverviewContainer,\n  WidgetContainer,\n} from './BalanceOverview.styled';\nimport { DashboardSection } from './DashboardSection';\nimport { HistoryTable } from './HistoryTable';\nimport { DownloadButton } from './HistoryTable/HistoryTable.styled';\nimport { downloadCsvFile } from './HistoryTable/downloadCsvFile';\nimport { NewOfferBanner } from './NewOfferBanner';\nimport { PlanDetails } from './PlanDetails';\n\ninterface Props {\n  creditList: GetRepaymentHistoryResponse[];\n}\n\nexport const BalanceOverview: FunctionComponent<Props> = ({ creditList }) => {\n  const { t } = useTranslation('dashboard');\n\n  const { breakpoints } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n\n  useEffect(() => {\n    posthog.capture('Balance overview viewed');\n  }, []);\n\n  const data: RepaymentHistoryItem[] = useMemo(\n    () =>\n      creditList.flatMap((resp) => {\n        return [\n          ...resp.data.map((rhi) => ({\n            ...rhi,\n            repaymentAmount: rhi.repaymentAmount * -1,\n          })),\n        ];\n      }),\n    [creditList],\n  );\n\n  const credit = creditList.at(0)?.credit;\n\n  return (\n    <BalanceOverviewContainer data-test-id=\"balance-overview\">\n      <WidgetContainer data-test-id=\"balance-overview-widget\">\n        <DashboardSection\n          testId=\"plan-details-section\"\n          title={t(\n            `planDetails.${credit?.financingSetup}.title`,\n            'Plan details',\n          )}\n          grow={isMobile ? 1 : 0}\n        >\n          {credit && <PlanDetails credit={credit} />}\n        </DashboardSection>\n        <NewOfferBanner variant={'mini'} />\n      </WidgetContainer>\n      <DashboardSection\n        testId=\"repayment-table\"\n        actions={\n          data?.length !== 0 && (\n            <DownloadButton\n              variant=\"invisible\"\n              onClick={() => downloadCsvFile(t, data ?? [])}\n            >\n              {isMobile\n                ? t('table.downloadCsvButtonMobile', 'CSV')\n                : t('table.downloadCsvButton', 'Download CSV')}\n            </DownloadButton>\n          )\n        }\n        title={t(`table.${credit?.financingSetup}.title`, 'Repayment details')}\n      >\n        <HistoryTable creditList={creditList} />\n      </DashboardSection>\n    </BalanceOverviewContainer>\n  );\n};\n","import styled from '@emotion/styled';\nimport { customizeStyles } from '@finmid/tiger-webapp/components';\nimport { ToggleButton } from '@mui/material';\nimport ToggleButtonGroup from '@mui/material/ToggleButtonGroup';\n\nexport const SubPageButton = styled(ToggleButton)(({ theme }) => ({\n  display: 'flex',\n  padding: `${theme.vars.components?.variables.spacings.sm} ${theme.vars.components?.variables.spacings.md}`,\n  justifyContent: 'center',\n  alignItems: 'center',\n  fontStyle: 'normal',\n  textAlign: 'center',\n  textTransform: 'none',\n\n  color: theme.vars.components?.variables.colors.grey900,\n\n  fontFamily: theme.vars.components?.variables.typography.mobile.family.body,\n  fontSize: theme.vars.components?.variables.typography.mobile.size.xs,\n  fontWeight: theme.vars.components?.variables.typography.mobile.weight.strong,\n  lineHeight: theme.vars.components?.variables.typography.mobile.lineHeight.xs,\n\n  borderRadius: theme.vars.components?.variables.radius.button,\n  border: 'none',\n\n  '&.Mui-selected': {\n    borderRadius: `${theme.vars.components?.variables.radius.button} !important`,\n\n    background: theme.vars.components?.variables.colors.white,\n    boxShadow:\n      '0px 3px 8px 0px rgba(0, 0, 0, 0.15), 0px 3px 1px 0px rgba(0, 0, 0, 0.06)',\n\n    '&:focus, &:focus-visible': {\n      background: theme.vars.components?.variables.colors.white,\n    },\n  },\n\n  [theme.breakpoints.up('desktop')]: {\n    fontFamily: theme.vars.components?.variables.typography.desktop.family.body,\n    fontSize: theme.vars.components?.variables.typography.desktop.size.xs,\n    fontStyle: 'normal',\n    fontWeight:\n      theme.vars.components?.variables.typography.desktop.weight.strong,\n    lineHeight:\n      theme.vars.components?.variables.typography.desktop.lineHeight.xs,\n  },\n\n  ...customizeStyles(theme, (c) => c?.dashboard?.subPage?.button),\n}));\n\nexport const SubPageButtonGroup = styled(ToggleButtonGroup)(({ theme }) => ({\n  width: 'fit-content',\n  padding: 2,\n  flexGrow: 0,\n  border: 'none',\n\n  borderRadius: theme.vars?.components?.variables?.radius?.button,\n  background: theme?.vars?.components?.variables?.colors?.grey300,\n\n  ...customizeStyles(theme, (c) => c?.dashboard?.subPage?.buttonGroup),\n}));\n","import { SubPageButton, SubPageButtonGroup } from './SubPageSelector.styled';\n\ninterface Props {\n  value: string;\n  onChange: (\n    event: React.MouseEvent<HTMLElement>,\n    newStep: string | null,\n  ) => void;\n  options: SubPageOption[];\n}\n\ninterface SubPageOption {\n  value: string;\n  label: string;\n}\n\nexport default function SubPageSelector({ value, onChange, options }: Props) {\n  return (\n    <SubPageButtonGroup\n      value={value}\n      exclusive\n      onChange={onChange}\n      aria-label=\"text alignment\"\n    >\n      {options.map((option) => (\n        <SubPageButton\n          key={option.value}\n          value={option.value}\n          aria-label={option.label}\n        >\n          <div>{option.label}</div>\n        </SubPageButton>\n      ))}\n    </SubPageButtonGroup>\n  );\n}\n","import { customizeStyles } from '@finmid/tiger-webapp/components';\nimport { Box } from '@mui/material';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate, useParams } from 'react-router-dom';\n\nimport { DashboardSteps } from './DashboardTemplate';\nimport SubPageSelector from './SubPageSelector';\n\nexport default function DashboardSubPageSelector() {\n  const { subPage = 'overview' } = useParams<{ subPage: DashboardSteps }>();\n  const navigate = useNavigate();\n  const { t } = useTranslation('dashboard', {\n    keyPrefix: 'layout.subPageSelector',\n  });\n\n  const handleChange = (\n    event: React.MouseEvent<HTMLElement>,\n    newStep: string | null,\n  ) => {\n    if (newStep === null) return;\n    navigate(`/dashboard/${newStep}`);\n  };\n\n  const options = [\n    { value: 'overview', label: t('balanceOverview') },\n    { value: 'documents', label: t('documents') },\n    { value: 'help-center', label: t('helpCenter') },\n  ];\n\n  return (\n    <Box\n      data-test-id=\"sub-page-selector\"\n      sx={({ vars, breakpoints }) => ({\n        padding: vars?.components?.variables?.spacings.lg,\n        alignSelf: 'start',\n\n        [breakpoints.up('desktop')]: {\n          padding: 0,\n          paddingTop: vars?.components?.variables?.spacings.xl,\n          paddingBottom: vars?.components?.variables?.spacings.xl,\n        },\n\n        ...customizeStyles(\n          { vars, breakpoints },\n          (c) => c?.dashboard?.subPage?.buttonGroupContainer,\n        ),\n      })}\n    >\n      <SubPageSelector\n        value={subPage}\n        onChange={handleChange}\n        options={options}\n      />\n    </Box>\n  );\n}\n","import styled from '@emotion/styled';\nimport { Flex, customizeStyles } from '@finmid/tiger-webapp/components';\n\nexport const Background = styled(Flex)(({ theme }) => ({\n  flexGrow: 1,\n  display: 'flex',\n  flexDirection: 'column',\n  justifyContent: 'start',\n  alignItems: 'center',\n\n  backgroundColor: theme.vars?.components?.variables?.colors.grey100,\n  paddingBottom: theme.vars?.components?.variables?.spacings.xl,\n\n  [theme.breakpoints.up('desktop')]: {\n    paddingLeft: '104px',\n    paddingRight: '104px',\n  },\n\n  ...customizeStyles(theme, (c) => c?.dashboard?.layout),\n}));\n\nexport const Content = styled(Flex)(({ theme: { vars, breakpoints } }) => ({\n  width: '100%',\n  alignItems: 'start',\n  justifyContent: 'space-between',\n  flexDirection: 'column',\n\n  maxWidth: `calc(min(1200px, 100%))`,\n\n  [breakpoints.up('desktop')]: {\n    padding: 0,\n  },\n\n  ...customizeStyles(\n    { vars, breakpoints },\n    (c) => c?.dashboard?.history?.container,\n  ),\n}));\n\nexport const RemittancePlanHeader = styled(Flex)(({ theme }) => ({\n  width: '100%',\n  justifyContent: 'center',\n  display: 'flex',\n  backgroundColor: theme.vars?.components?.variables?.colors.white,\n\n  paddingTop: theme.vars?.components?.variables?.spacings.md,\n  paddingBottom: theme.vars?.components?.variables?.spacings.md,\n\n  borderBottom: `1px solid ${theme.vars?.components?.variables?.colors.grey300}`,\n\n  [theme.breakpoints.down('desktop')]: {\n    display: 'none',\n  },\n\n  [theme.breakpoints.up('desktop')]: {\n    width: 'calc(100% + 208px)',\n    paddingLeft: '104px',\n    paddingRight: '104px',\n    marginLeft: '-104px',\n    marginRight: '-104px',\n  },\n}));\n\nexport const Description = styled(Flex)(({ theme }) => ({\n  width: '100%',\n  fontSize: '18px',\n  lineHeight: '24px',\n  padding: '16px 24px',\n  display: 'inline',\n\n  ...customizeStyles(theme, (c) => c?.dashboard?.subPage?.description),\n}));\n","import styled from '@emotion/styled';\nimport {\n  CopyEmailButton,\n  Flex,\n  Typography,\n} from '@finmid/tiger-webapp/components';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\ninterface Props {\n  title: string;\n  description: string;\n  maxWidth: 690 | 792;\n}\n\nexport const ContactDisclaimer: FunctionComponent<Props> = ({\n  title,\n  description,\n  maxWidth,\n}) => {\n  const { t } = useTranslation('turnkey');\n\n  return (\n    <Flex\n      flexDirection={'column'}\n      alignItems={'stretch'}\n      data-test-id=\"contact-disclaimer\"\n      gap=\"sm\"\n      maxWidth={maxWidth}\n    >\n      <Typography family=\"title\" size=\"xl\" weight=\"strong\">\n        {title}\n      </Typography>\n      {/* <CardHeader>{title}<CardHeader> */}\n\n      <Typography size=\"md\">\n        {description}{' '}\n        <SpanLikeLink>\n          {t('helpAndFeedback.contactSupport')}\n          <CopyEmailButton />\n        </SpanLikeLink>\n      </Typography>\n    </Flex>\n  );\n};\n\nconst SpanLikeLink = styled.span(({ theme: { vars } }) => ({\n  display: 'inline-flex',\n  alignItems: 'center',\n  columnGap: vars.components?.variables.spacings.xs,\n}));\n\nexport const Description = styled('div')(({ theme }) => ({\n  width: '100%',\n  fontSize: '18px',\n  lineHeight: '24px',\n  padding: '16px 24px',\n}));\n","import styled from '@emotion/styled';\nimport { customizeStyles, Flex } from '@finmid/tiger-webapp/components';\n\nexport const DocumentsPageContainer = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  gap: `calc(2 * ${theme.vars.components?.variables.spacings.lg})`,\n  alignItems: 'stretch',\n\n  [theme.breakpoints.up('desktop')]: {\n    gap: theme.vars.components?.variables.spacings.xl,\n  },\n\n  ...customizeStyles(theme, (c) => c?.dashboard?.documents?.container),\n}));\n\nexport const DocumentListContainer = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  width: '100%',\n\n  gap: theme.vars.components?.variables.spacings.md,\n\n  [theme.breakpoints.up('desktop')]: {\n    flexDirection: 'row',\n    flexWrap: 'wrap',\n    justifyContent: 'flex-start',\n    alignItems: 'flex-start',\n\n    gap: theme.vars.components?.variables.spacings.lg,\n  },\n\n  ...customizeStyles(\n    theme,\n    (c) => c?.dashboard?.documents?.documentCards?.list,\n  ),\n}));\n\nexport const DocumentCardContainer = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  background: 'white',\n  borderRadius: theme.vars.components?.variables.radius.md,\n  border: `1px solid ${theme.vars.components?.variables.colors.grey300}`,\n\n  width: '100%',\n\n  [theme.breakpoints.up('desktop')]: {\n    maxWidth: 327,\n    minWidth: 327,\n  },\n\n  ...customizeStyles(\n    theme,\n    (c) => c?.dashboard?.documents?.documentCards?.card,\n  ),\n}));\n","import styled from '@emotion/styled';\nimport {\n  Flex,\n  Typography,\n  customizeStyles,\n  customized,\n} from '@finmid/tiger-webapp/components';\n\ninterface WithDisabled {\n  disabled?: boolean;\n}\n\nexport const DocumentCardSection = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  alignItems: 'start',\n  padding: theme.vars.components?.variables.spacings.md,\n  width: '100%',\n\n  borderBottomWidth: 1,\n  borderBottomStyle: 'solid',\n  borderBottomColor: theme.vars.components?.variables.colors.grey300,\n\n  '&:last-of-type': {\n    borderBottomWidth: 0,\n  },\n\n  ...customizeStyles(\n    theme,\n    (customizations) => customizations?.dashboard?.documents?.section,\n  ),\n}));\n\nexport const DocumentLinkText = styled(Typography)<WithDisabled>(\n  ({ theme, disabled }) => ({\n    ...customizeStyles(\n      theme,\n      (customizations) => customizations?.dashboard?.documents?.link?.text,\n    ),\n\n    ...(disabled\n      ? customizeStyles(\n          theme,\n          (customizations) => customizations?.dashboard?.documents?.disabled,\n        )\n      : {}),\n  }),\n);\n\nexport const DocumentLink = styled('a')(({ theme }) => ({\n  display: 'flex',\n  justifyContent: 'space-between',\n  textDecoration: 'none',\n\n  width: '100%',\n  gap: theme.vars.components?.variables.spacings.sm,\n  padding: theme.vars.components?.variables.spacings.md,\n\n  borderTopWidth: 1,\n  borderTopStyle: 'solid',\n  borderTopColor: theme.vars.components?.variables.colors.grey300,\n\n  ...customizeStyles(\n    theme,\n    (customizations) => customizations?.dashboard?.documents?.link?.container,\n  ),\n}));\n\nexport const DocumentDownload = styled(Flex)<WithDisabled>(\n  ({ theme, disabled }) => ({\n    padding: '3px',\n    width: '23px',\n    height: '23px',\n\n    borderRadius: theme.vars.components?.variables.radius.pill,\n    color: theme.vars.components?.variables?.colors.white,\n    background: theme.vars.components?.variables?.colors.primaryDefault,\n\n    ...(disabled\n      ? {\n          background: theme.vars.components?.variables?.colors.grey300,\n        }\n      : {}),\n\n    ...customizeStyles(\n      theme,\n      (customizations) => customizations?.dashboard?.documents?.downloadIcon,\n    ),\n    ...(disabled\n      ? customizeStyles(\n          theme,\n          (customizations) => customizations?.dashboard?.documents?.disabled,\n        )\n      : {}),\n  }),\n);\n\nexport const Payout = customized(\n  Typography,\n  (customizations) => customizations?.dashboard?.documents?.payout,\n);\n\nexport const PayoutDate = customized(\n  Typography,\n  (customizations) => customizations?.dashboard?.documents?.payoutDate,\n);\n\nexport const Fee = customized(\n  Typography,\n  (customizations) => customizations?.dashboard?.documents?.fee,\n);\n\nexport const DocumentsLabel = customized(\n  Typography,\n  (customizations) => customizations?.dashboard?.documents?.documentsLabel,\n);\n","import styled from '@emotion/styled';\nimport { customizeStyles, Typography } from '@finmid/tiger-webapp/components';\nimport { AcceptedCredit } from '@finmid/tiger-webapp/queries';\nimport { useFormat } from '@finmid/translations';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\ninterface Props {\n  credit: AcceptedCredit;\n}\n\nexport const DocumentCardStatusTag: FunctionComponent<Props> = ({ credit }) => {\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'dashboard.documents.creditStatusTag',\n  });\n  const { date } = useFormat();\n\n  let status: 'ACTIVE' | 'PAID' = 'ACTIVE';\n  if (credit.paidAt) {\n    status = 'PAID';\n  }\n  return (\n    <Tag size=\"md\" color=\"white\" weight=\"strong\" status={status}>\n      {t(status, {\n        date: date(\n          new Date(\n            status === 'ACTIVE'\n              ? credit.acceptedAt\n              : credit.paidAt ?? credit.acceptedAt,\n          ),\n        ),\n      })}\n    </Tag>\n  );\n};\n\nexport const Tag = styled(Typography)<{ status: 'PAID' | 'ACTIVE' }>(\n  ({\n    theme,\n    theme: {\n      vars: { components },\n    },\n    status,\n  }) => ({\n    width: '100%',\n\n    borderTopLeftRadius: components?.variables?.radius.md,\n    borderTopRightRadius: components?.variables?.radius.md,\n\n    padding: components?.variables?.spacings.md,\n    backgroundColor:\n      status === 'ACTIVE'\n        ? components?.variables.colors.success\n        : components?.variables.colors.grey700,\n\n    ...customizeStyles(\n      theme,\n      (customizations) => customizations?.dashboard?.documents?.creditTag?.base,\n    ),\n\n    ...(status === 'ACTIVE'\n      ? customizeStyles(\n          theme,\n          (customizations) =>\n            customizations?.dashboard?.documents?.creditTag?.active,\n        )\n      : {}),\n    ...(status === 'PAID'\n      ? customizeStyles(\n          theme,\n          (customizations) =>\n            customizations?.dashboard?.documents?.creditTag?.paid,\n        )\n      : {}),\n  }),\n);\n","import { Icons, useTokenContext } from '@finmid/tiger-webapp/components';\nimport { AcceptedCredit, useGetCreditDoc } from '@finmid/tiger-webapp/queries';\nimport { Tooltip } from '@mui/material';\nimport { FC } from 'react';\n\nimport {\n  DocumentDownload,\n  DocumentLink,\n  DocumentLinkText,\n} from './DocumentCard.styled';\n\ninterface DocumentLinkItemProps {\n  credit: AcceptedCredit;\n  document: 'capital-summary' | 'invoice';\n  enabled: boolean;\n  label: string;\n  tooltip: string;\n}\n\nexport const DocumentLinkItem: FC<DocumentLinkItemProps> = ({\n  credit,\n  document,\n  enabled,\n  label,\n  tooltip,\n}) => {\n  const { token, twoFactorAuthMethods } = useTokenContext();\n\n  const skip2FA =\n    Array.isArray(twoFactorAuthMethods) && twoFactorAuthMethods.length === 0;\n\n  const { data: documentData } = useGetCreditDoc({\n    token,\n    creditId: credit.id,\n    document,\n    enabled,\n    skip2FA,\n  });\n\n  const link = (\n    <DocumentLink href={documentData?.url} target={'_blank'}>\n      <DocumentLinkText size=\"sm\" disabled={documentData?.url == null}>\n        {label}\n      </DocumentLinkText>\n      <DocumentDownload disabled={documentData?.url == null}>\n        <Icons.DownloadIcon />\n      </DocumentDownload>\n    </DocumentLink>\n  );\n\n  return documentData?.url != null ? (\n    link\n  ) : (\n    <Tooltip title={tooltip}>{link}</Tooltip>\n  );\n};\n","import { Icons } from '@finmid/tiger-webapp/components';\nimport { Tooltip } from '@mui/material';\nimport { FunctionComponent } from 'react';\n\nimport {\n  DocumentDownload,\n  DocumentLink,\n  DocumentLinkText,\n} from './DocumentCard.styled';\n\ninterface Props {\n  url?: string;\n  label: string;\n  tooltip: string;\n}\n\nexport const PdfLinkItem: FunctionComponent<Props> = ({\n  url,\n  label,\n  tooltip,\n}) => {\n  const link = (\n    <DocumentLink href={url} target={'_blank'}>\n      <DocumentLinkText size=\"sm\" disabled={url == null}>\n        {label}\n      </DocumentLinkText>\n      <DocumentDownload disabled={url == null}>\n        <Icons.DownloadIcon />\n      </DocumentDownload>\n    </DocumentLink>\n  );\n\n  return url != null ? link : <Tooltip title={tooltip}>{link}</Tooltip>;\n};\n","import {\n  useBindingLanguage,\n  useLoadDocuments,\n} from '@finmid/tiger-webapp/components';\nimport { AcceptedCredit } from '@finmid/tiger-webapp/queries';\nimport { useFormat } from '@finmid/translations';\nimport { useTranslation } from 'react-i18next';\n\nimport { DocumentCardContainer } from '../DocumentsPage.styled';\n\nimport {\n  DocumentCardSection,\n  DocumentsLabel,\n  Fee,\n  Payout,\n  PayoutDate,\n} from './DocumentCard.styled';\nimport { DocumentCardStatusTag } from './DocumentCardStatusTag';\nimport { DocumentLinkItem } from './DocumentLinkItem';\nimport { PdfLinkItem } from './PdfLinkItem';\n\ninterface Props {\n  credit: AcceptedCredit;\n}\n\nexport const DocumentCard = ({ credit }: Props) => {\n  const { t } = useTranslation('turnkey');\n  const { money, date } = useFormat();\n\n  const bindingLanguage = useBindingLanguage();\n\n  const { pdf: bindingPdf } = useLoadDocuments({\n    offerId: credit.offerId || null,\n    language: bindingLanguage,\n  });\n\n  return (\n    <DocumentCardContainer flex={1} data-test-id=\"document-card\">\n      <DocumentCardStatusTag credit={credit} />\n      <DocumentCardSection gap=\"xs\">\n        <PayoutDate size=\"xs\">\n          {credit.payout?.paidOutAt\n            ? t('dashboard.documents.payoutDate', {\n                date: date(new Date(credit.payout.paidOutAt)),\n              })\n            : t('dashboard.documents.payoutPending')}\n        </PayoutDate>\n        <Payout size=\"md\" weight=\"strong\">\n          {money(credit.payout?.amount ?? credit.limit, credit.currency)}\n        </Payout>\n        <Fee size=\"xs\">\n          {t('dashboard.documents.fee', {\n            fee: money(credit.payout?.fee ?? credit.fee, credit.currency, {\n              maximumFractionDigits: 0,\n            }),\n          })}\n        </Fee>\n      </DocumentCardSection>\n      <DocumentCardSection>\n        <DocumentsLabel size=\"md\" weight=\"strong\">\n          {t('dashboard.documents.documents')}\n        </DocumentsLabel>\n      </DocumentCardSection>\n      <DocumentLinkItem\n        credit={credit}\n        document=\"capital-summary\"\n        enabled={credit.payout?.paidOutAt != null}\n        label={t('dashboard.documents.link.onePager')}\n        tooltip={t('dashboard.documents.tooltip.onePager')}\n      />\n      <PdfLinkItem\n        url={bindingPdf?.url}\n        label={t('dashboard.documents.link.tnc')}\n        tooltip={t('dashboard.documents.tooltip.tnc')}\n      />\n      {credit.repaymentType === 'FLEXIBLE' && (\n        <DocumentLinkItem\n          credit={credit}\n          document=\"invoice\"\n          enabled={credit.paidAt != null}\n          label={t('dashboard.documents.link.invoice')}\n          tooltip={t('dashboard.documents.tooltip.invoice')}\n        />\n      )}\n    </DocumentCardContainer>\n  );\n};\n","import { CustomisationSlot } from '@finmid/tiger-webapp/components';\nimport { GetRepaymentHistoryResponse } from '@finmid/tiger-webapp/queries';\nimport posthog from 'posthog-js';\nimport { FunctionComponent, useEffect } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { ContactDisclaimer } from './ContactDisclaimer';\nimport { DocumentCard } from './DocumentCard';\nimport {\n  DocumentListContainer,\n  DocumentsPageContainer,\n} from './DocumentsPage.styled';\n\ninterface Props {\n  creditList: GetRepaymentHistoryResponse[];\n}\n\nexport const DocumentsPage: FunctionComponent<Props> = ({ creditList }) => {\n  const { t } = useTranslation('turnkey');\n\n  useEffect(() => {\n    posthog.capture('Documents page viewed');\n  }, []);\n\n  return (\n    <DocumentsPageContainer data-test-id=\"dashboard-documents\">\n      <CustomisationSlot\n        slot=\"dashboard.documents.contactsDisclaimer\"\n        props={{}}\n        fallback={\n          <ContactDisclaimer\n            title={t('dashboard.documents.disclaimer.title')}\n            description={t('dashboard.documents.contactUs')}\n            maxWidth={690}\n          />\n        }\n      />\n\n      <DocumentListContainer\n        flexWrap={'wrap'}\n        justifyContent={'flex-start'}\n        alignItems={'flex-start'}\n      >\n        {creditList.map((item) => (\n          <DocumentCard credit={item.credit} key={item.credit.id} />\n        ))}\n      </DocumentListContainer>\n    </DocumentsPageContainer>\n  );\n};\n","import {\n  FeedbackPopup,\n  Typography,\n  useMessenger,\n  useTailoredOffers,\n} from '@finmid/tiger-webapp/components';\nimport { DashboardHelpCenter } from '@finmid/tiger-webapp/help-center';\nimport {\n  FinancingSetup,\n  GetRepaymentHistoryResponse,\n} from '@finmid/tiger-webapp/queries';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useParams } from 'react-router-dom';\n\nimport { BalanceOverview } from './BalanceOverview';\nimport DashboardSubPageSelector from './DashboardSubPageSelector';\nimport {\n  Background,\n  Content,\n  RemittancePlanHeader,\n} from './DashboardTemplate.styled';\nimport { DocumentsPage } from './DocumentsPage';\nimport { NewOfferBanner } from './NewOfferBanner';\n\ninterface Props {\n  creditList: GetRepaymentHistoryResponse[];\n  financingSetup: FinancingSetup;\n}\n\nexport type DashboardSteps = 'overview' | 'documents' | 'help-center';\n\nexport const DashboardTemplate: FunctionComponent<Props> = ({\n  creditList,\n  financingSetup,\n}) => {\n  const { isEmbedded } = useMessenger();\n  const { t } = useTranslation('dashboard', {\n    keyPrefix: `layout.${financingSetup}`,\n  });\n  const { subPage = 'overview' } = useParams<{ subPage: DashboardSteps }>();\n\n  const { offers } = useTailoredOffers();\n\n  const credit = creditList.at(0);\n  const businessName = credit?.business.legalName;\n\n  let content = null;\n  switch (subPage) {\n    case 'overview':\n      content = <BalanceOverview creditList={creditList} />;\n      break;\n    case 'documents':\n      content = <DocumentsPage creditList={creditList} />;\n      break;\n    case 'help-center':\n      content = <DashboardHelpCenter />;\n      break;\n  }\n\n  return (\n    <Background data-test-id=\"dashboard-background\">\n      {isEmbedded ? null : (\n        <RemittancePlanHeader data-test-id=\"remittance-plan-header\">\n          <Content>\n            <Typography component=\"h1\" family=\"body\" size=\"md\" weight=\"strong\">\n              {businessName != null && businessName !== ''\n                ? t('title', {\n                    defaultValue: 'Capital Repayment Plan for {{name}}',\n                    name: businessName,\n                  })\n                : t('titleNoBusinessName', {\n                    defaultValue: 'Capital Repayment Plan',\n                  })}\n            </Typography>\n          </Content>\n        </RemittancePlanHeader>\n      )}\n\n      <Content>\n        <DashboardSubPageSelector />\n      </Content>\n\n      <Content\n        gap=\"md\"\n        sx={({ vars }) => ({\n          padding: vars?.components?.variables?.spacings.lg,\n        })}\n      >\n        {(offers ?? []).length > 0 && <NewOfferBanner variant={'full'} />}\n        {content}\n        {credit != null && <FeedbackPopup offerId={credit?.credit.offerId} />}\n      </Content>\n    </Background>\n  );\n};\n","import styled from '@emotion/styled';\nimport { customizeStyles } from '@finmid/tiger-webapp/components';\n\nexport const TwoFactorModalBlock = styled.div(\n  ({ theme: { vars, breakpoints } }) => ({\n    display: 'flex',\n    flexDirection: 'column',\n    alignItems: 'center',\n    justifyContent: 'center',\n    borderRadius: vars.components?.variables.radius?.md,\n    width: '100%',\n\n    [breakpoints.up('desktop')]: {\n      padding: 0,\n    },\n\n    ...customizeStyles({ vars, breakpoints }, (c) => c?.modal?.container),\n  }),\n);\n","import styled from '@emotion/styled';\nimport {\n  customizeStyles,\n  Flex,\n  Typography,\n} from '@finmid/tiger-webapp/components';\n\nexport const Title = styled(Typography)(({ theme: { vars, breakpoints } }) => ({\n  width: '100%',\n  marginTop: vars.components?.variables.spacings.xxl,\n  marginBottom: vars.components?.variables.spacings.sm,\n\n  [breakpoints.down('desktop')]: {\n    fontSize: vars.components?.variables.typography.mobile.size.xl,\n    lineHeight: vars.components?.variables.typography.mobile.lineHeight.xl,\n    marginTop: 0,\n    marginBottom: vars.components?.variables.spacings.sm,\n  },\n\n  ...customizeStyles({ vars, breakpoints }, (c) => c?.phoneVerification?.title),\n}));\n\nexport const Subtitle = styled(Typography)(\n  ({ theme: { vars, breakpoints } }) => ({\n    marginBottom: vars.components?.variables.spacings.xxl,\n    color: vars.components?.variables.colors?.grey700,\n\n    [breakpoints.down('desktop')]: {\n      color: vars.components?.variables.colors?.grey900,\n      marginBottom: vars.components?.variables.spacings.md,\n    },\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.phoneVerification?.subtitle,\n    ),\n  }),\n);\n\nexport const Background = styled(Flex)(\n  ({ theme, theme: { breakpoints, vars } }) => ({\n    flexDirection: 'column',\n    flexGrow: 1,\n    padding: vars.components?.variables.spacings.lg,\n    justifyContent: 'flex-start',\n    alignItems: 'flex-start',\n    justifySelf: 'center',\n    maxWidth: 528,\n\n    [breakpoints.up('desktop')]: {\n      padding: vars.components?.variables.spacings.xl,\n      justifyContent: 'center',\n      alignItems: 'center',\n    },\n\n    ...customizeStyles(theme, (c) => c?.phoneVerification?.background),\n  }),\n);\n\nexport const LastFourDigits = styled(Typography)(\n  ({ theme: { vars, breakpoints } }) => ({\n    display: 'flex',\n    justifyContent: 'space-between',\n    width: '100%',\n    marginBottom: vars.components?.variables.spacings?.xxl,\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.phoneVerification?.lastFourDigits,\n    ),\n  }),\n);\n\nexport const PhoneNumberWrapper = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    flexDirection: 'column',\n    width: '100%',\n    paddingBlockEnd: vars.components?.variables.spacings?.xxl,\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.phoneVerification?.phoneNumberWrapper,\n    ),\n  }),\n);\n\nexport const ButtonsWrapper = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    flexDirection: 'column',\n    width: '100%',\n    gap: vars.components?.variables.spacings?.md,\n    position: 'sticky',\n    bottom: vars.components?.variables.spacings.md,\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.phoneVerification?.buttonsWrapper,\n    ),\n  }),\n);\n","import styled from '@emotion/styled';\nimport {\n  customizeStyles,\n  Flex,\n  MODAL_MAX_WIDTH,\n  TimedButton,\n  Typography,\n} from '@finmid/tiger-webapp/components';\n\nexport const StyledTimedButton = styled(TimedButton)(\n  ({ theme, theme: { vars } }) => ({\n    position: 'sticky',\n    bottom: vars.components?.variables.spacings.md,\n\n    ...customizeStyles(\n      theme,\n      (c) => c?.fakeModal?.confirmPhoneAndSendCodeButton,\n    ),\n  }),\n);\n\nexport const Background = styled(Flex)(\n  ({ theme, theme: { breakpoints, vars } }) => ({\n    flex: 1,\n    flexDirection: 'column',\n    padding: vars.components?.variables.spacings.lg,\n    justifyContent: 'flex-start',\n    maxWidth: MODAL_MAX_WIDTH,\n    width: '100%',\n\n    [breakpoints.up('desktop')]: {\n      flex: 'auto',\n      alignItems: 'flex-start',\n      padding: vars.components?.variables.spacings.xl,\n    },\n\n    ...customizeStyles(theme, (c) => c?.phoneConfirmation?.background),\n  }),\n);\n\nexport const Title = styled(Typography)(({ theme: { vars, breakpoints } }) => ({\n  width: '100%',\n  marginTop: vars.components?.variables.spacings.xxl,\n  marginBottom: vars.components?.variables.spacings.sm,\n\n  [breakpoints.down('desktop')]: {\n    fontSize: vars.components?.variables.typography.mobile.size.xl,\n    lineHeight: vars.components?.variables.typography.mobile.lineHeight.xl,\n    marginTop: 0,\n  },\n\n  ...customizeStyles({ vars, breakpoints }, (c) => c?.phoneConfirmation?.title),\n}));\n\nexport const Subtitle = styled(Typography)(\n  ({ theme: { vars, breakpoints } }) => ({\n    marginBottom: vars.components?.variables.spacings.xxl,\n    color: vars.components?.variables.colors?.grey700,\n\n    [breakpoints.down('desktop')]: {\n      color: vars.components?.variables.colors?.grey900,\n      marginBottom: vars.components?.variables.spacings.md,\n    },\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.phoneConfirmation?.subtitle,\n    ),\n  }),\n);\n","import {\n  Flex,\n  PhoneWithCountryInput,\n  Typography,\n} from '@finmid/tiger-webapp/components';\nimport { InputLabel } from '@mui/material';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { CountryIso2 } from 'react-international-phone';\n\ninterface Props {\n  phoneLastFour?: string;\n  country?: CountryIso2;\n}\n\nexport const ReadOnlyPhoneInput: FunctionComponent<Props> = ({\n  phoneLastFour,\n  country,\n}) => {\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'twoFactorModal.confirmPhone',\n  });\n\n  return (\n    <Flex alignItems=\"flex-start\" flexDirection=\"column\" width=\"100%\" gap=\"xs\">\n      <InputLabel htmlFor=\"phone\">\n        <Typography size=\"xs\" component=\"span\">\n          {t('number', 'Phone number')}\n        </Typography>\n      </InputLabel>\n      <PhoneWithCountryInput\n        id=\"phone\"\n        variant=\"outlined\"\n        fullWidth\n        disabled\n        value={`** *******${phoneLastFour ?? '** ****'}`}\n        testId=\"phone\"\n        country={country}\n      />\n    </Flex>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport { getCountry } from '@finmid/countries';\nimport {\n  CustomisationSlot,\n  Flex,\n  MobileStickyNavigation,\n  NocodeShieldIcon,\n  useTokenContext,\n  ContactSupport,\n  StickyFooterWithBorder,\n} from '@finmid/tiger-webapp/components';\nimport {\n  useGetOffers,\n  useSecondsTillNext2FaChallenge,\n} from '@finmid/tiger-webapp/queries';\nimport { Box, useMediaQuery } from '@mui/material';\nimport { FunctionComponent, useMemo } from 'react';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { LastFourDigits } from '../../../Offer/Steps/GetFunds/TwoFactorModal/VerifyPhone.styled';\n\nimport {\n  StyledTimedButton,\n  Title,\n  Subtitle,\n  Background,\n} from './DashboardConfirmPhone.styled';\nimport { ReadOnlyPhoneInput } from './ReadOnlyPhoneInput';\n\ninterface Props {\n  loading: boolean;\n  onRequest2FA: () => void;\n}\n\nexport const DashboardConfirmPhone: FunctionComponent<Props> = ({\n  onRequest2FA,\n  loading,\n}) => {\n  const { vars } = useTheme();\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'twoFactorModal.confirmPhone',\n  });\n  const { breakpoints } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n\n  const { token, ignoreAction } = useTokenContext();\n\n  const { data: offers } = useGetOffers({ token, ignoreAction });\n  const lastFour = offers?.phoneLastFour;\n\n  const countryIso2 = useMemo(() => {\n    return getCountry(offers?.country ?? null)?.iso2code.toLowerCase();\n  }, [offers]);\n\n  const secondsTillNext2FaChallenge = useSecondsTillNext2FaChallenge();\n\n  return (\n    <MobileStickyNavigation\n      onContinue={onRequest2FA}\n      continueText={t('sendCodeButton', 'Confirm my phone number')}\n      hideBackButton\n      continueButtonTestId=\"send-button\"\n      isLoading={loading}\n      fullHeaderHeight={false}\n    >\n      <Background data-test-id=\"verify-phone\">\n        <CustomisationSlot\n          slot=\"shield.icon\"\n          props={{}}\n          fallback={<NocodeShieldIcon />}\n        />\n\n        <Title size=\"lg\" family=\"title\" weight=\"strong\">\n          {t('title', 'Welcome back!')}\n        </Title>\n        <Subtitle size=\"md\">\n          <Trans\n            t={t}\n            i18nKey={'subtitle'} /* This key uses components like <strong /> */\n            values={{\n              lastFour,\n            }}\n          />\n        </Subtitle>\n        <LastFourDigits size=\"md\" weight=\"strong\" component=\"div\">\n          <div>\n            <Trans i18nKey=\"twoFactorModal.phoneNumberEndingIn\" />\n          </div>\n          <div>{lastFour}</div>\n        </LastFourDigits>\n\n        <Flex flexDirection=\"column\" width=\"100%\">\n          <Flex justifyContent=\"flex-start\" gap=\"md\" width=\"100%\">\n            <ReadOnlyPhoneInput\n              phoneLastFour={offers?.phoneLastFour}\n              country={countryIso2}\n            />\n          </Flex>\n\n          <Box\n            mt={vars.components?.variables.spacings.md}\n            mb={vars.components?.variables.spacings.xxl}\n            width=\"100%\"\n          >\n            <ContactSupport />\n          </Box>\n\n          {!isMobile ? (\n            <>\n              <StickyFooterWithBorder />\n              <StyledTimedButton\n                loading={false}\n                testId=\"send-button\"\n                text={t('sendCodeButton', 'Confirm my phone number')}\n                timeout={secondsTillNext2FaChallenge}\n                onClick={onRequest2FA}\n              />\n            </>\n          ) : null}\n        </Flex>\n      </Background>\n    </MobileStickyNavigation>\n  );\n};\n","import { useTokenContext, VerifyCode } from '@finmid/tiger-webapp/components';\nimport {\n  getRepaymentHistory,\n  isGetRepaymentHistoryError,\n  useVerify2Fa,\n  type GetRepaymentHistoryErrorType,\n} from '@finmid/tiger-webapp/queries';\nimport { useState } from 'react';\n\ntype Props = {\n  creditId: string;\n  onSuccess: () => void;\n};\n\nexport const DashboardVerifyCode = ({ creditId, onSuccess }: Props) => {\n  const { token } = useTokenContext();\n  const [onCodeVerifiedError, setOnCodeVerifiedError] =\n    useState<null | GetRepaymentHistoryErrorType>(null);\n\n  const { mutateAsync: verify2Fa } = useVerify2Fa({\n    token: token,\n  });\n\n  const verifyCode = async (code: string) => {\n    const token = await verify2Fa({ code, type: 'HISTORY_ACCESS' });\n    const isValidCode = token != null;\n    return isValidCode;\n  };\n\n  const onCodeVerified = async () => {\n    try {\n      const result = await getRepaymentHistory({\n        token,\n        creditId,\n      });\n      if (isGetRepaymentHistoryError(result)) {\n        setOnCodeVerifiedError(result.error);\n      } else {\n        onSuccess();\n      }\n    } catch {\n      setOnCodeVerifiedError('UNKNOWN_ERROR');\n    }\n  };\n\n  return (\n    <VerifyCode\n      onCodeVerifiedError={onCodeVerifiedError}\n      verifyCode={verifyCode}\n      onCodeVerified={onCodeVerified}\n      type=\"HISTORY_ACCESS\"\n    />\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport {\n  useTokenContext,\n  FakeModal,\n  Modal,\n  usePlatformSettings,\n} from '@finmid/tiger-webapp/components';\nimport { useRequest2FaChallenge } from '@finmid/tiger-webapp/queries';\nimport { useMediaQuery } from '@mui/material';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { TwoFactorModalBlock } from './DashboardTwoFactorModal.styled';\nimport { DashboardConfirmPhone, DashboardVerifyCode } from './components';\n\ninterface Props {\n  creditId: string;\n  onSuccess: () => void;\n}\n\nexport const DashboardTwoFactorModal: FunctionComponent<Props> = ({\n  creditId,\n  onSuccess,\n}) => {\n  const { token } = useTokenContext();\n  const { experiments } = usePlatformSettings();\n  const fullScreenModal = experiments?.fullScreenModal;\n  const { breakpoints } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n\n  const {\n    i18n: { language },\n  } = useTranslation('turnkey');\n\n  const {\n    mutate: sendChallenge,\n    isPending,\n    isSuccess: requestSent,\n  } = useRequest2FaChallenge({\n    locale: language,\n    type: 'HISTORY_ACCESS',\n    token,\n  });\n\n  const content = (\n    <TwoFactorModalBlock>\n      {!requestSent ? (\n        <DashboardConfirmPhone\n          loading={isPending}\n          onRequest2FA={sendChallenge}\n        />\n      ) : (\n        <DashboardVerifyCode creditId={creditId} onSuccess={onSuccess} />\n      )}\n    </TwoFactorModalBlock>\n  );\n\n  if (fullScreenModal || isMobile)\n    return <FakeModal fullHeaderHeight={!isMobile}>{content}</FakeModal>;\n\n  return <Modal maxWidth={528}>{content}</Modal>;\n};\n","import {\n  FullPageLoader,\n  useSetPostHogData,\n  useTokenContext,\n} from '@finmid/tiger-webapp/components';\nimport {\n  useGetCreditIds,\n  useGetCredits,\n  useGetOffers,\n  GetRepaymentHistoryResponse,\n  CreditID,\n} from '@finmid/tiger-webapp/queries';\nimport { useState } from 'react';\nimport { Navigate } from 'react-router-dom';\n\nimport { Page401 } from '../Error/Page401';\n\nimport { DashboardTemplate } from './DashboardTemplate';\nimport { DashboardTwoFactorModal } from './PhoneVerification/DashboardTwoFactorModal';\n\nexport const Dashboard = () => {\n  const { token, ignoreAction, twoFactorAuthMethods } = useTokenContext();\n  const [tryCount, setTryCount] = useState(0);\n\n  const skip2FA =\n    Array.isArray(twoFactorAuthMethods) && twoFactorAuthMethods.length === 0;\n\n  const {\n    data: availableOffers,\n    isLoading,\n    isError: isOffersError,\n  } = useGetOffers({\n    token,\n    ignoreAction,\n  });\n  const { data: creditIds, isLoading: isLoadingCredits } = useGetCreditIds({\n    token,\n  });\n\n  const creditQueries = useGetCredits({\n    creditIds: creditIds?.credits?.map((credit: CreditID) => credit.id) ?? [],\n    tryCount,\n    token,\n    skip2FA,\n  });\n\n  useSetPostHogData();\n\n  const credits = creditQueries\n    .map((query) => query.data)\n    .filter(\n      (data): data is GetRepaymentHistoryResponse =>\n        data != null &&\n        'data' in data &&\n        'credit' in data &&\n        // Remove un-refinanced credits from the UI\n        data.credit.status !== 'REJECTED',\n    );\n\n  const historyForCreditsErrors = creditQueries\n    .map((query) => query.data)\n    .filter((data) => data != null && 'error' in data);\n\n  const historyForCreditsFetching = creditQueries.some(\n    (query) => query.isFetching,\n  );\n\n  if (isOffersError && availableOffers == null) {\n    return <Navigate to=\"/overview\" replace />;\n  }\n\n  if (\n    isLoading ||\n    isLoadingCredits ||\n    historyForCreditsFetching ||\n    availableOffers == null\n  ) {\n    return <FullPageLoader />;\n  }\n\n  // V2 API returns latestCredit only when in PENDING state.\n  // Absence of latestCredit indicates the payout was rejected/cancelled/completed.\n  if (availableOffers.latestCredit == null) {\n    return <Navigate to=\"/get-funds\" replace />;\n  }\n\n  if (!creditIds?.credits || !credits) return <Page401 />;\n\n  if (!skip2FA && historyForCreditsErrors.some(({ error }) => error != null)) {\n    return (\n      <DashboardTwoFactorModal\n        creditId={creditIds.credits[0].id}\n        onSuccess={() => {\n          setTryCount(tryCount + 1);\n        }}\n      />\n    );\n  }\n\n  return (\n    <DashboardTemplate\n      creditList={credits}\n      financingSetup={availableOffers.latestCredit.financingSetup ?? 'MCA'}\n    />\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  ConsentContext,\n  ContactSupport,\n  CustomisationSlot,\n  Flex,\n  Header,\n  SectionH1,\n  Spacer,\n  Typography,\n} from '@finmid/tiger-webapp/components';\nimport { useTranslation } from 'react-i18next';\n\nconst Background = styled(Flex)(() => ({\n  height: '100%',\n}));\n\nconst Card = styled(Flex)(\n  ({\n    theme: {\n      vars: { components },\n      breakpoints,\n    },\n  }) => ({\n    backgroundColor: 'white',\n    minHeight: 584,\n    width: 608,\n    flexDirection: 'column',\n    color: components?.variables.colors.grey900,\n\n    padding: '88px 58px 110px',\n    textAlign: 'center',\n\n    [breakpoints.down('desktop')]: {\n      padding: '40px 40px',\n\n      height: '100%',\n      width: '100%',\n    },\n  }),\n);\n\nexport const Page403 = () => {\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'errorPage.expiredLink',\n  });\n\n  return (\n    <ConsentContext.Provider\n      value={{\n        changeConsent: () => {},\n        consentState: 'REJECTED',\n        isLoading: false,\n      }}\n    >\n      <Header />\n      <Background data-test-id=\"page-403\">\n        <Card>\n          <div className=\"offer-expired-image\" />\n          <Spacer height={4.5} />\n          <Flex gap=\"sm\" flexDirection=\"column\">\n            <SectionH1 dataTestId=\"title\">\n              {t('title', 'Credit offer expired')}\n            </SectionH1>\n            <Typography size=\"md\">\n              {t(\n                'description',\n                'You can request a new offer below. If we’re able to make a new offer, you’ll be notified via email when it is ready for you to review.',\n              )}\n            </Typography>\n          </Flex>\n          <Spacer height={6} />\n          <CustomisationSlot\n            slot=\"expired.contactSupport\"\n            props={{}}\n            fallback={<ContactSupport size=\"md\" />}\n          />\n        </Card>\n      </Background>\n    </ConsentContext.Provider>\n  );\n};\n","import { useOnboardingState } from '@finmid/tiger-webapp/onboarding';\nimport { FunctionComponent } from 'react';\nimport { Navigate } from 'react-router-dom';\n\nexport const RouterMiddleware: FunctionComponent = () => {\n  const { suggestedAction: suggestedOnboardingAction } = useOnboardingState();\n\n  switch (suggestedOnboardingAction) {\n    case 'REDIRECT_TO_OVERVIEW':\n      return <Navigate to=\"/overview\" replace />;\n    case 'REDIRECT_TO_ONBOARDING':\n      return <Navigate to=\"/onboarding\" replace />;\n    default:\n      break;\n  }\n\n  return null;\n};\n","import {\n  CustomisationSlot,\n  Header,\n  SelectedOfferProvider,\n  TailoredOffersProvider,\n} from '@finmid/tiger-webapp/components';\nimport type { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { Outlet } from 'react-router-dom';\nimport { useTitle } from 'react-use';\n\nimport { RouterMiddleware } from '../app/RouterMiddleware';\n\nexport const Layout: FunctionComponent = () => {\n  const { t } = useTranslation('turnkey');\n  useTitle(t('appTitle', 'Financing offer'));\n\n  return (\n    <>\n      <RouterMiddleware />\n      <CustomisationSlot\n        slot={'layout.header'}\n        props={{}}\n        fallback={<Header />}\n      />\n      <TailoredOffersProvider>\n        <SelectedOfferProvider>\n          <Outlet />\n        </SelectedOfferProvider>\n      </TailoredOffersProvider>\n    </>\n  );\n};\n\nexport const LayoutStandalone: FunctionComponent = () => {\n  return (\n    <>\n      <CustomisationSlot\n        slot={'layout.header'}\n        props={{}}\n        fallback={<Header standalone />}\n      />\n      <Outlet />\n    </>\n  );\n};\n","import { CustomisationSlot } from '@finmid/tiger-webapp/components';\nimport type { FunctionComponent } from 'react';\nimport { Outlet } from 'react-router-dom';\n\nexport const OfferLayout: FunctionComponent = () => {\n  return (\n    <>\n      <CustomisationSlot slot={'offer.header'} props={{}} />\n      <Outlet />\n    </>\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  customizeStyles,\n  Flex,\n  MODAL_MAX_WIDTH,\n  Typography,\n} from '@finmid/tiger-webapp/components';\n\nexport const ExpiredModalContainer = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    flexDirection: 'column',\n    gap: vars.components?.variables.spacings.xxl,\n    padding: vars.components?.variables.spacings.xl,\n    maxWidth: MODAL_MAX_WIDTH,\n    width: '100%',\n\n    [breakpoints.down('desktop')]: {\n      gap: vars.components?.variables.spacings.xl,\n      padding: vars.components?.variables.spacings.lg,\n    },\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.expiredOffer?.container,\n    ),\n  }),\n);\n\nexport const ExpiredModalDescription = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    flexDirection: 'column',\n    alignItems: 'flex-start',\n    gap: vars.components?.variables.spacings.sm,\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.expiredOffer?.description,\n    ),\n  }),\n);\n\nexport const ExpiredModalTitle = styled(Typography)(\n  ({ theme: { vars, breakpoints } }) => ({\n    ...customizeStyles({ vars, breakpoints }, (c) => c?.expiredOffer?.title),\n  }),\n);\n\nexport const ExpiredModalSubtitle = styled(Typography)(\n  ({ theme: { vars, breakpoints } }) => ({\n    ...customizeStyles({ vars, breakpoints }, (c) => c?.expiredOffer?.subtitle),\n  }),\n);\n","import styled from '@emotion/styled';\nimport { Flex } from '@finmid/tiger-webapp/components';\n\nexport const Background = styled('div')(({ theme: { vars } }) => ({\n  position: 'relative',\n  borderRadius: vars.components?.variables.radius.lg,\n  overflow: 'hidden',\n  width: '100%',\n  height: 260,\n}));\n\nexport const VisualWrapper = styled('div')(({ theme: { breakpoints } }) => ({\n  width: '70%',\n  marginInline: 'auto',\n\n  [breakpoints.down('desktop')]: {\n    width: '100%',\n  },\n}));\n\nexport type OverlayOpacity = 'dark' | 'light';\n\nexport const Overlay = styled('div')<{ opacity: OverlayOpacity }>(\n  ({ opacity }) => ({\n    background:\n      opacity === 'dark' ? 'rgba(22, 23, 23, 0.12)' : 'rgba(22, 23, 23, 0.06)',\n    backdropFilter: 'blur(4px)',\n    position: 'absolute',\n    width: '100%',\n    height: '100%',\n    top: 0,\n  }),\n);\n\nexport const IconWrapper = styled(Flex)({\n  position: 'absolute',\n  width: '100%',\n  height: '100%',\n  top: 0,\n  justifyContent: 'center',\n  alignItems: 'center',\n});\n\nexport const IconBackground = styled('div')({\n  width: 96,\n  height: 96,\n  background: 'white',\n  borderRadius: '100%',\n});\n","import { useTheme } from '@emotion/react';\nimport { GetCapitalNoCodeVisual, Icons } from '@finmid/tiger-webapp/components';\nimport { PropsWithChildren } from 'react';\n\nimport {\n  Background,\n  Overlay,\n  type OverlayOpacity,\n  IconWrapper,\n  IconBackground,\n  VisualWrapper,\n} from './ExpiredModalVisual.styled';\n\ntype ExpiredModalVisualProps = PropsWithChildren<{\n  opacity: OverlayOpacity;\n}>;\n\nconst ExpiredModalVisual = ({ opacity, children }: ExpiredModalVisualProps) => {\n  return (\n    <Background>\n      <VisualWrapper>\n        <GetCapitalNoCodeVisual />\n      </VisualWrapper>\n      <Overlay opacity={opacity} />\n      <IconWrapper>\n        <IconBackground />\n      </IconWrapper>\n      <IconWrapper>{children}</IconWrapper>\n    </Background>\n  );\n};\n\nexport const ExpiredFirstStepNoCodeVisual = () => {\n  const { vars } = useTheme();\n  return (\n    <ExpiredModalVisual opacity=\"dark\">\n      <Icons.ErrorIcon\n        color={vars.components?.variables.colors.warning}\n        width={80}\n        height={80}\n        viewBox=\"2 2 20 20\"\n      />\n    </ExpiredModalVisual>\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  CustomisationSlot,\n  FakeModal,\n  Modal,\n  useCapturePosthogViewed,\n  usePlatformSettings,\n  useResponsive,\n} from '@finmid/tiger-webapp/components';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport {\n  ExpiredModalDescription,\n  ExpiredModalTitle,\n  ExpiredModalContainer,\n  ExpiredModalSubtitle,\n  ExpiredFirstStepNoCodeVisual,\n} from './components';\n\nconst ExpiredOfferContent = styled.div({\n  display: 'flex',\n  flexDirection: 'column',\n  alignItems: 'center',\n  justifyContent: 'center',\n  width: '100%',\n});\n\nexport const ExpiredModal: FunctionComponent = () => {\n  useCapturePosthogViewed('Expired offer screen viewed');\n  const { experiments } = usePlatformSettings();\n  const fullScreenModal = experiments?.fullScreenModal;\n  const { isMobile } = useResponsive();\n\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'expiredOffer',\n  });\n\n  const content = (\n    <ExpiredOfferContent data-test-id=\"expired-offer-content\">\n      <ExpiredModalContainer>\n        <CustomisationSlot\n          slot=\"expiredOffer.visual.request\"\n          props={{}}\n          fallback={<ExpiredFirstStepNoCodeVisual />}\n        />\n        <ExpiredModalDescription>\n          <ExpiredModalTitle size=\"lg\" weight=\"strong\" family=\"title\">\n            {t('title', 'This offer has expired')}\n          </ExpiredModalTitle>\n          <ExpiredModalSubtitle size=\"md\">\n            {t('description', 'Capital offers are valid for 30 days.')}\n          </ExpiredModalSubtitle>\n        </ExpiredModalDescription>\n      </ExpiredModalContainer>\n    </ExpiredOfferContent>\n  );\n\n  if (isMobile || fullScreenModal) {\n    return <FakeModal fullHeaderHeight={!isMobile}>{content}</FakeModal>;\n  }\n\n  return <Modal maxWidth={528}>{content}</Modal>;\n};\n","import { useLocalStorage } from 'react-use';\n\nexport const usePhoneUpdate = () => {\n  const [\n    isPhoneUpdateRequested,\n    setIsPhoneUpdateRequested,\n    resetIsPhoneUpdateRequested,\n  ] = useLocalStorage('phone-update', false);\n\n  return {\n    isPhoneUpdateRequested,\n    setIsPhoneUpdateRequested,\n    resetIsPhoneUpdateRequested,\n  };\n};\n","import {\n  CopyEmailLink,\n  Flex,\n  Typography,\n} from '@finmid/tiger-webapp/components';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nexport const PhoneUpdatedNotification: FunctionComponent = () => {\n  const { t } = useTranslation('offers', {\n    keyPrefix: 'phoneUpdatedPage.notification',\n  });\n\n  return (\n    <Flex\n      gap=\"xs\"\n      flexDirection=\"column\"\n      justifyContent=\"start\"\n      alignItems=\"start\"\n    >\n      <Typography size=\"md\" weight=\"strong\">\n        {t('title', 'Phone number change requested')}\n      </Typography>\n      <Flex\n        gap=\"sm\"\n        flexDirection=\"row\"\n        justifyContent=\"start\"\n        alignItems=\"start\"\n      >\n        <Typography size=\"md\" component=\"p\">\n          {t(\n            'description',\n            'We are reviewing it. Contact support if you have any questions.',\n          )}{' '}\n          <CopyEmailLink />\n        </Typography>\n      </Flex>\n    </Flex>\n  );\n};\n","import { useNotification } from '@finmid/tiger-webapp/components';\nimport { useCallback, useEffect } from 'react';\n\nimport { usePhoneUpdate } from '../usePhoneUpdate';\n\nimport { PhoneUpdatedNotification } from './PhoneUpdatedNotification';\n\nconst notificationKey = 'PHONE_UPDATED';\n\nexport const usePhoneUpdatedNotification = () => {\n  const { isPhoneUpdateRequested, resetIsPhoneUpdateRequested } =\n    usePhoneUpdate();\n\n  const { enqueue, close } = useNotification(notificationKey);\n\n  useEffect(() => {\n    if (isPhoneUpdateRequested) {\n      console.log('isPhoneUpdateRequested', isPhoneUpdateRequested);\n      enqueue(<PhoneUpdatedNotification />, {\n        persist: true,\n      });\n    }\n  }, [enqueue, isPhoneUpdateRequested]);\n\n  const closeNotification = useCallback(() => {\n    close();\n    resetIsPhoneUpdateRequested();\n  }, [close, resetIsPhoneUpdateRequested]);\n\n  return {\n    closeNotification,\n  };\n};\n","import styled from '@emotion/styled';\nimport { Button, customizeStyles, Flex } from '@finmid/tiger-webapp/components';\n\nexport const GradientBackground = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    padding: vars.components?.variables.spacings.md,\n    background: `\n    linear-gradient(${vars.components?.variables.colors.primaryDefault}, ${vars.components?.variables.colors.primaryDefault}) padding-box,\n    linear-gradient(${vars.components?.variables.colors.primaryDefault}, ${vars.components?.variables.colors.primaryAccent}) border-box\n  `,\n    border: '2px solid transparent',\n    borderRadius: vars.components?.variables.radius.md,\n    color: vars.components?.variables.colors.white,\n    boxShadow:\n      '0px 0px 4px 0px rgba(0, 0, 0, 0.06), 0px 4px 24px 0px rgba(0, 0, 0, 0.24)',\n\n    [breakpoints.down('desktop')]: {\n      marginBottom: vars.components?.variables.spacings.md,\n      cursor: 'pointer',\n    },\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.plus?.boostLimit?.banner,\n    ),\n  }),\n);\n\nexport const IconCircle = styled(Flex)(({ theme: { vars } }) => ({\n  backgroundColor: vars.components?.variables.colors.primaryAccent,\n  padding: vars.components?.variables.spacings.sm,\n  borderRadius: '50%',\n}));\n\nexport const BoostButton = styled(Button)(({ theme }) =>\n  customizeStyles(theme, (c) => c?.plus?.boostLimit?.bannerButton),\n);\n","import * as React from 'react';\nimport { SVGProps, memo } from 'react';\n\nconst SvgComponent = (props: SVGProps<SVGSVGElement>) => (\n  <svg\n    xmlns=\"http://www.w3.org/2000/svg\"\n    width={24}\n    height={24}\n    fill=\"none\"\n    viewBox=\"0 0 24 24\"\n    {...props}\n  >\n    <path\n      fill={props.fill ?? '#fff'}\n      d=\"m2.45 10.575 4.2-4.2c.233-.233.508-.4.825-.5.317-.1.