onst { t } = useTranslation('turnkey', { keyPrefix: 'plus' });\n  const { money } = useFormat();\n  const { selectedOffer } = useSelectedOffer();\n\n  const goToPlus = () => {\n    capturePosthogEvent('User navigated to boost offer', {\n      from: 'plus_banner',\n      offer: selectedOffer,\n      currency,\n      capitalPlus: true,\n    });\n    navigate('/plus');\n  };\n\n  return (\n    <GradientBackground\n      gap=\"md\"\n      width=\"100%\"\n      justifyContent=\"space-between\"\n      onClick={isMobile ? goToPlus : undefined}\n      data-test-id={isMobile ? 'capital-plus-offer' : undefined}\n    >\n      <Flex gap=\"md\" justifyContent=\"flex-start\">\n        <CustomisationSlot\n          slot=\"boostMyLimit.image\"\n          props={{}}\n          fallback={\n            <IconCircle>\n              <RocketIcon />\n            </IconCircle>\n          }\n        />\n        <Flex flexDirection=\"column\" gap=\"xs\" alignItems=\"flex-start\">\n          <Typography size=\"xs\" weight=\"strong\" color=\"white\">\n            {t('max', 'Capital Max')}\n          </Typography>\n          <Typography size=\"lg\" weight=\"strong\" color=\"white\" family=\"title\">\n            {t('modal.title', {\n              amount: money(maxOfferLimit, currency, {\n                maximumFractionDigits: 0,\n              }),\n            })}\n          </Typography>\n        </Flex>\n      </Flex>\n      {!isMobile ? (\n        <BoostButton\n          variant=\"secondary\"\n          onClick={goToPlus}\n          data-test-id=\"capital-plus-offer\"\n        >\n          {t('banner.boost', 'Boost my limit')}\n        </BoostButton>\n      ) : null}\n    </GradientBackground>\n  );\n};\n","import styled from '@emotion/styled';\n\nexport const ModalContent = styled.div(({ theme: { breakpoints, vars } }) => ({\n  display: 'flex',\n  flexDirection: 'column',\n  alignItems: 'stretch',\n  justifyContent: 'flex-start',\n  width: '100%',\n  height: '100%',\n  overflow: 'auto',\n\n  [breakpoints.down('desktop')]: {\n    border: 'none',\n  },\n}));\n","import styled from '@emotion/styled';\nimport {\n  Button as ButtonBase,\n  customized,\n  customizeStyles,\n  Typography,\n} from '@finmid/tiger-webapp/components';\nimport { FormControlLabel } from '@mui/material';\n\ninterface Props {\n  isSelected: boolean;\n}\n\nexport const OptionButton = styled(FormControlLabel)<Props>(\n  // @ts-expect-error todo: fix this\n  ({ theme, isSelected }) => ({\n    display: 'flex',\n    alignItems: 'flex-start',\n    width: '100%',\n    margin: 0,\n    backgroundColor: 'white',\n    borderWidth: 2,\n    borderStyle: 'solid',\n\n    borderColor: theme.vars.components?.variables.colors.grey300,\n    borderRadius: theme.vars.components?.variables.radius.md,\n\n    padding: theme.vars.components?.variables.spacings.md,\n    gap: theme.vars.components?.variables.spacings.md,\n\n    '& svg': {\n      fontSize: '18px',\n      marginTop: '3px',\n    },\n\n    ...theme.vars.components?.exitQuestModal?.optionButton?.default,\n\n    ...(isSelected\n      ? {\n          borderColor: theme.vars.components?.variables.colors.primaryDefault,\n          '& .MuiRadio-root': {\n            // padding: 0,\n          },\n\n          '& svg': {\n            color: theme.vars.components?.variables.colors.primaryDefault,\n            fontSize: '18px',\n            marginTop: '3px',\n          },\n          ...theme.vars.components?.exitQuestModal?.optionButton?.pressed,\n        }\n      : {}),\n\n    '&:hover': {\n      ...theme.vars.components?.exitQuestModal?.optionButton?.hovered,\n    },\n  }),\n);\nexport const SubmitButton = styled(ButtonBase)(({ theme }) => ({\n  width: '100%',\n}));\n\nexport const Title = styled(Typography)(({ theme }) => ({\n  width: '100%',\n  textAlign: 'left',\n  [theme.breakpoints.up('desktop')]: {\n    textAlign: 'center',\n  },\n\n  ...theme.vars.components?.exitQuestModal?.title,\n}));\n\nexport const Description = styled(Typography)(({ theme }) => ({\n  [theme.breakpoints.up('desktop')]: {\n    textAlign: 'center',\n  },\n\n  ...customizeStyles(theme, (c) => c?.exitQuestModal?.description),\n}));\n\nexport const Subtitle = customized(\n  Typography,\n  (c) => c?.exitQuestModal?.subtitle,\n);\n","import { useTheme } from '@emotion/react';\nimport {\n  Flex,\n  Link,\n  MobileStickyNavigation,\n  MODAL_MAX_WIDTH,\n  TextField,\n  Typography,\n  useTailoredOffers,\n} from '@finmid/tiger-webapp/components';\nimport { QuestionType } from '@finmid/tiger-webapp/queries';\nimport { useWhatsAppButton } from '@finmid/tiger-webapp/whatsapp';\nimport { Radio, RadioGroup, useMediaQuery } from '@mui/material';\nimport { FunctionComponent, useState } from 'react';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport {\n  Description,\n  OptionButton,\n  SubmitButton,\n  Title,\n} from './ExitQuestModalForm.styled';\n\ninterface FormProps {\n  onSubmit: (type: QuestionType, comment?: string) => void;\n}\n\nconst questOptions: QuestionType[] = [\n  'IMPROVE_OFFER_HIGHER_LIMIT',\n  'IMPROVE_OFFER_UNNEEDED',\n  'IMPROVE_OFFER_TRANSPARENT_FEE',\n  'IMPROVE_OFFER_LOW_FEE',\n  'IMPROVE_OFFER_OTHER',\n];\n\nexport const ExitQuestModalForm: FunctionComponent<FormProps> = ({\n  onSubmit,\n}) => {\n  useWhatsAppButton({ overStickyNavigation: true });\n\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'overview.calculator.exitQuestModal',\n  });\n  const { isCapitalPlusAvailable } = useTailoredOffers();\n\n  const [option, setOption] = useState<QuestionType | undefined>(\n    questOptions[0],\n  );\n  const [comment, setComment] = useState<string>();\n  const { breakpoints } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n\n  const handleChange = (event: React.ChangeEvent<HTMLInputElement>) => {\n    setOption((event.target as HTMLInputElement).value as QuestionType);\n  };\n\n  const typesWithPlus = ['IMPROVE_OFFER_HIGHER_LIMIT', 'IMPROVE_OFFER_LOW_FEE'];\n\n  return (\n    <MobileStickyNavigation\n      onContinue={() => option && onSubmit(option, comment)}\n      continueText={t('submit', 'Submit Feedback')}\n      hideBackButton\n      isFullHeight\n    >\n      <Flex\n        flexDirection={'column'}\n        flex={1}\n        justifyContent=\"flex-start\"\n        data-test-id=\"exitQuestModalForm\"\n        sx={({ vars, breakpoints }) => ({\n          padding: vars.components?.variables.spacings.lg,\n          width: '100%',\n          maxWidth: MODAL_MAX_WIDTH,\n          alignSelf: 'center',\n\n          [breakpoints.up('desktop')]: {\n            padding: vars.components?.variables.spacings.xl,\n          },\n        })}\n      >\n        <div className={'offer-feedback-image-slot'} />\n        <Flex\n          flexDirection={'column'}\n          justifyContent=\"flex-start\"\n          width={'100%'}\n          flex={1}\n          sx={({ vars, breakpoints }) => ({\n            gap: vars.components?.variables.spacings.md,\n            [breakpoints.up('desktop')]: {\n              gap: vars.components?.variables.spacings.xl,\n            },\n          })}\n        >\n          <Flex\n            flexDirection={'column'}\n            sx={({ vars, breakpoints }) => ({\n              gap: vars.components?.variables.spacings.sm,\n              [breakpoints.up('desktop')]: {\n                gap: vars.components?.variables.spacings.md,\n              },\n            })}\n          >\n            <Title size={'xl'} family={'title'} weight={'strong'}>\n              {t('title', 'What would make the offer better?')}\n            </Title>\n            <Description size={'md'}>\n              {t(\n                'subtitle',\n                'Please help us understand what would make the offer more attractive.',\n              )}\n            </Description>\n          </Flex>\n\n          <RadioGroup\n            value={option}\n            onChange={handleChange}\n            sx={{ width: '100%' }}\n          >\n            <Flex\n              flexDirection=\"column\"\n              width={'100%'}\n              sx={({ vars, breakpoints }) => ({\n                gap: vars.components?.variables.spacings.sm,\n                [breakpoints.up('desktop')]: {\n                  gap: vars.components?.variables.spacings.md,\n                },\n              })}\n            >\n              {questOptions.map((qo) => (\n                <OptionButton\n                  key={qo}\n                  value={qo}\n                  // @ts-expect-error todo: fix this\n                  isSelected={option === qo}\n                  control={<Radio sx={{ padding: 0 }} />}\n                  label={\n                    <Flex\n                      flexDirection={'column'}\n                      alignItems={'flex-start'}\n                      gap=\"sm\"\n                    >\n                      <Typography size=\"md\" weight=\"strong\">\n                        {t('option', { context: qo, defaultValue: qo })}\n                      </Typography>\n                      {isCapitalPlusAvailable &&\n                        qo === option &&\n                        typesWithPlus.includes(qo) && (\n                          <Typography size=\"md\">\n                            <Trans\n                              i18nKey={\n                                'overview.calculator.exitQuestModal.selected'\n                              }\n                              context={qo}\n                              defaultValue={qo}\n                              components={{\n                                plus: (\n                                  <Link\n                                    aria-label={'Link to Capital Plus'}\n                                    href={\n                                      qo === 'IMPROVE_OFFER_LOW_FEE'\n                                        ? '/plus/bank'\n                                        : '/plus'\n                                    }\n                                  />\n                                ),\n                              }}\n                            />\n                          </Typography>\n                        )}\n                    </Flex>\n                  }\n                />\n              ))}\n            </Flex>\n          </RadioGroup>\n\n          {option === 'IMPROVE_OFFER_OTHER' && (\n            <TextField\n              id=\"comment\"\n              fullWidth\n              multiline\n              text={comment || ''}\n              onChange={(v) => setComment(v)}\n              placeholder={t(\n                'comment.placeholder',\n                'Additional comments (optional)',\n              )}\n              testId=\"comment\"\n              sx={{\n                '& .MuiInputBase-root': {\n                  borderWidth: '1px !important',\n                },\n              }}\n            />\n          )}\n\n          {!isMobile ? (\n            <SubmitButton\n              variant=\"primary\"\n              size=\"large\"\n              disabled={!option}\n              onClick={() => option && onSubmit(option, comment)}\n            >\n              {t('submit', 'Submit Feedback')}\n            </SubmitButton>\n          ) : null}\n        </Flex>\n      </Flex>\n    </MobileStickyNavigation>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport {\n  Button,\n  CustomisationSlot,\n  Flex,\n  MobileStickyNavigation,\n} from '@finmid/tiger-webapp/components';\nimport { useWhatsAppButton } from '@finmid/tiger-webapp/whatsapp';\nimport { useMediaQuery } from '@mui/material';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { Subtitle, Title } from './ExitQuestModalForm.styled';\n\ninterface Props {\n  onClose: () => void;\n}\n\nexport const FeedbackSubmitted: FunctionComponent<Props> = ({ onClose }) => {\n  useWhatsAppButton({ overStickyNavigation: true });\n\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'overview.calculator.exitQuestModal.submitted',\n  });\n\n  const { breakpoints } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n\n  return (\n    <MobileStickyNavigation\n      onContinue={onClose}\n      continueText={t('closeButton', 'Return to my current offer')}\n      hideBackButton\n      isFullHeight\n    >\n      <Flex\n        flexDirection={'column'}\n        justifyContent=\"flex-start\"\n        gap=\"xl\"\n        sx={({ vars, breakpoints }) => ({\n          height: '100%',\n\n          padding: vars.components?.variables.spacings.lg,\n        })}\n      >\n        <CustomisationSlot slot=\"feedbackPopup.successImage\" props={{}} />\n\n        <Flex\n          flexDirection={'column'}\n          alignItems={'center'}\n          sx={({ vars, breakpoints }) => ({\n            gap: vars.components?.variables.spacings.sm,\n            [breakpoints.up('desktop')]: {\n              gap: vars.components?.variables.spacings.md,\n            },\n          })}\n        >\n          <Title size=\"xl\" family=\"title\" weight=\"strong\">\n            {t('title', 'Thank you!')}\n          </Title>\n          <Subtitle size=\"md\">\n            {t('subtitle', 'Your feedback has been registered successfully.')}\n          </Subtitle>\n        </Flex>\n\n        {!isMobile && (\n          <Button\n            fullWidth\n            variant=\"primary\"\n            size=\"large\"\n            onClick={onClose}\n            customizationTags={['exitQuestModal', 'close']}\n          >\n            {t('closeButton', 'Return to my current offer')}\n          </Button>\n        )}\n      </Flex>\n    </MobileStickyNavigation>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport {\n  Button,\n  FakeModal,\n  Flex,\n  Icons,\n  Modal,\n  useCapturePosthogEvent,\n  usePlatformSettings,\n  useTokenContext,\n} from '@finmid/tiger-webapp/components';\nimport { QuestionType, usePostFeedback } from '@finmid/tiger-webapp/queries';\nimport { buttonClasses, useMediaQuery } from '@mui/material';\nimport { FunctionComponent, useCallback } from 'react';\n\nimport { ModalContent } from './ExitQuestModal.styled';\nimport { ExitQuestModalForm } from './ExitQuestModalForm';\nimport { FeedbackSubmitted } from './FeedbackSubmitted';\n\ninterface Props {\n  closeModal: () => void;\n  offerId: string;\n}\n\nexport const ExitQuestModal: FunctionComponent<Props> = ({\n  closeModal,\n  offerId,\n}) => {\n  const capturePosthogEvent = useCapturePosthogEvent();\n  const { token } = useTokenContext();\n  const { experiments } = usePlatformSettings();\n  const fullScreenModal = experiments?.fullScreenModal;\n  const {\n    mutateAsync: sendFeedback,\n    isSuccess,\n    isError,\n  } = usePostFeedback({\n    token,\n    offerId,\n  });\n\n  const theme = useTheme();\n  const isMobile = useMediaQuery(theme.breakpoints.down('desktop'));\n\n  const onSubmit = useCallback(\n    async (type: QuestionType, comment?: string) => {\n      capturePosthogEvent('User provided reason for dislike offer', {\n        type,\n        comment,\n      });\n      await sendFeedback({\n        type,\n        comment,\n      });\n    },\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n    [sendFeedback],\n  );\n\n  const content = (\n    <ModalContent data-test-id=\"exit-questions-modal\">\n      {isSuccess || isError ? (\n        <FeedbackSubmitted onClose={closeModal} />\n      ) : (\n        <ExitQuestModalForm onSubmit={onSubmit} />\n      )}\n    </ModalContent>\n  );\n\n  if (fullScreenModal) {\n    return <FakeModal>{content}</FakeModal>;\n  }\n\n  const desktopSubmissionScreen = !isMobile && (isSuccess || isError);\n\n  return (\n    <Modal onClose={closeModal} grow={desktopSubmissionScreen ? '0' : '1'}>\n      {isMobile && (\n        <Flex\n          justifyContent=\"flex-end\"\n          width=\"100%\"\n          sx={({ vars }) => ({\n            padding: `${vars.components?.variables.spacings.md} ${vars.components?.variables.spacings.lg}`,\n          })}\n        >\n          <CloseButton variant=\"invisible\" onClick={closeModal}>\n            <Icons.CloseIcon\n              style={{ color: theme.vars.components?.variables.colors.grey700 }}\n            />\n          </CloseButton>\n        </Flex>\n      )}\n      {content}\n    </Modal>\n  );\n};\n\nconst CloseButton = styled(Button)(({ theme: { vars } }) => ({\n  backgroundColor: 'transparent',\n  minWidth: 'auto',\n  border: 'none',\n  color: vars.components?.variables.colors?.grey700,\n\n  [`&.${buttonClasses.root}`]: {\n    padding: 8,\n  },\n}));\n","import styled from '@emotion/styled';\nimport { customizeStyles } from '@finmid/tiger-webapp/components';\n\nexport const Background = styled('div')(({ theme: { breakpoints, vars } }) => ({\n  display: 'flex',\n  flexDirection: 'column',\n  alignItems: 'flex-start',\n  padding: vars.components?.variables.spacings.lg,\n\n  [breakpoints.only('tablet')]: {\n    alignItems: 'center',\n  },\n\n  ...customizeStyles(\n    { breakpoints, vars },\n    (c) => c?.overview?.getCapital?.tailoredOffer?.background,\n  ),\n}));\n","import styled from '@emotion/styled';\nimport { customizeStyles } from '@finmid/tiger-webapp/components';\n\nexport const Container = styled.div(({ theme: { vars, breakpoints } }) => ({\n  display: 'flex',\n  flexDirection: 'column',\n\n  ...customizeStyles(\n    { vars, breakpoints },\n    (c) => c?.overview?.getCapital?.tailoredOffer?.container,\n  ),\n}));\n","import styled from '@emotion/styled';\nimport { customizeStyles, Typography } from '@finmid/tiger-webapp/components';\n\nexport const Description = styled(Typography)(\n  ({ theme: { vars, breakpoints } }) => ({\n    marginBlockEnd: vars.components?.variables.spacings.xl,\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.overview?.getCapital?.tailoredOffer?.description,\n    ),\n  }),\n);\n","import styled from '@emotion/styled';\nimport { customizeStyles, Typography } from '@finmid/tiger-webapp/components';\n\nexport const Header = styled(Typography)(\n  ({ theme: { vars, breakpoints } }) => ({\n    marginBlockStart: 0,\n    marginBlockEnd: vars.components?.variables.spacings.sm,\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.overview?.getCapital?.tailoredOffer?.header,\n    ),\n  }),\n);\n","import styled from '@emotion/styled';\nimport {\n  customizeStyles,\n  NoTranslateSpan,\n} from '@finmid/tiger-webapp/components';\n\nexport const Limit = styled(NoTranslateSpan, {\n  shouldForwardProp: (prop) => prop !== 'isTailoredOffer',\n})(({ theme: { vars, breakpoints } }) => ({\n  display: 'inline-block',\n  marginTop: 0,\n\n  ...customizeStyles(\n    { vars, breakpoints },\n    (c) => c?.overview?.getCapital?.tailoredOffer?.limit,\n  ),\n}));\n","import {\n  Button,\n  CustomisationSlot,\n  GetCapitalNoCodeVisual,\n  useCapturePosthogEvent,\n  useTailoredOffers,\n  useTokenContext,\n} from '@finmid/tiger-webapp/components';\nimport { Offer, useGetOffers } from '@finmid/tiger-webapp/queries';\nimport { useFormat } from '@finmid/translations';\nimport maxBy from 'lodash/maxBy';\nimport { FunctionComponent } from 'react';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport {\n  Background,\n  Container,\n  Description,\n  Header,\n  Limit,\n} from './components';\n\ninterface GetCapitalProps {\n  setupOnClick: () => void;\n}\n\nexport const GetCapitalMobile: FunctionComponent<GetCapitalProps> = ({\n  setupOnClick,\n}) => {\n  const capturePosthogEvent = useCapturePosthogEvent();\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'flexibleRates',\n  });\n\n  const { money } = useFormat();\n\n  const { token, ignoreAction } = useTokenContext();\n  const { data } = useGetOffers({ token, ignoreAction });\n\n  const { offers } = useTailoredOffers();\n\n  const currency = data?.currency ?? 'EUR';\n\n  const maxOffer = maxBy(offers as Offer[], (o) => o.payoutAmount) ?? null;\n  const singleOffer = offers?.length === 1;\n\n  const limit =\n    maxOffer == null\n      ? '...'\n      : money(maxOffer.payoutAmount, currency, {\n          maximumFractionDigits: 0,\n        });\n\n  const onClick = () => {\n    capturePosthogEvent('User navigated to tailored offers', {\n      from: 'overview_page',\n    });\n    setupOnClick();\n  };\n\n  return (\n    <Background data-test-id=\"get-capital\" style={{ backgroundImage: 'none' }}>\n      <CustomisationSlot\n        slot=\"overview.mobile.visual\"\n        props={{}}\n        fallback={<GetCapitalNoCodeVisual />}\n      />\n      <Container>\n        <Header size=\"xxl\" family=\"title\" weight=\"strong\" color=\"grey900\">\n          {singleOffer ? (\n            t('sectionH1SingleOffer', {\n              defaultValue: 'You’re approved for {{limit}}',\n              limit,\n            })\n          ) : (\n            <Trans\n              t={t}\n              i18nKey={'sectionH1WithLimit'}\n              components={{\n                limit: <Limit />,\n              }}\n              values={{ limit }}\n            />\n          )}\n        </Header>\n\n        <Description size=\"md\">\n          {t(\n            'subtitle',\n            'Get easy access to financing with {{ platform }} {{ productName }}',\n          )}\n        </Description>\n\n        <Button\n          variant=\"primary\"\n          onClick={onClick}\n          fullWidth\n          data-test-id=\"setup-plan-button\"\n          data-chromatic=\"ignore\"\n          disabled={data?.stub}\n        >\n          <div className=\"gif-slot\" data-chromatic=\"ignore\" />\n          <span>{t('button')}</span>\n        </Button>\n      </Container>\n    </Background>\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  customizeStyles,\n  Flex,\n  Typography,\n} from '@finmid/tiger-webapp/components';\n\nconst Header = styled(Flex)(({ theme: { vars } }) => ({\n  flexDirection: 'column',\n  alignItems: 'flex-start',\n  rowGap: vars.components?.variables.spacings.sm,\n  alignSelf: 'stretch',\n}));\n\nconst Title = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(theme, (c) => c?.howItWorksMultiStep?.title),\n}));\n\nconst SubTitle = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(theme, (c) => c?.howItWorksMultiStep?.subTitle),\n}));\n\ntype Props = {\n  title: string;\n  subtitle: string;\n};\n\nexport const HowItWorksHeader = ({ title, subtitle }: Props) => {\n  return (\n    <Header>\n      <Title size=\"lg\" weight=\"strong\" family=\"title\">\n        {title}\n      </Title>\n      <SubTitle size=\"md\">{subtitle}</SubTitle>\n    </Header>\n  );\n};\n","import { StandaloneLink } from '@finmid/tiger-webapp/components';\nimport { useTranslation } from 'react-i18next';\n\nexport const LinkToFaqs = () => {\n  const { t } = useTranslation('turnkey', { keyPrefix: 'educationalPopup' });\n\n  return (\n    <StandaloneLink to=\"/help-and-faqs\">\n      {t('faqLink', 'Questions? Visit our FAQs')}\n    </StandaloneLink>\n  );\n};\n","import styled from '@emotion/styled';\nimport { customizeStyles, Flex } from '@finmid/tiger-webapp/components';\n\nexport const Background = styled(Flex)(({ theme: { vars, breakpoints } }) => ({\n  padding: vars.components?.variables.spacings.xl,\n  flexDirection: 'column',\n  justifyContent: 'center',\n  alignItems: 'center',\n  gap: vars.components?.variables.spacings.xl,\n  alignSelf: 'stretch',\n  borderRadius: vars.components?.variables.radius.md,\n  background: vars.components?.variables.colors.grey100,\n\n  ...customizeStyles(\n    { vars, breakpoints },\n    (c) => c?.howItWorksMultiStep?.visuals?.background,\n  ),\n}));\n\nexport const Wrapper = styled(Flex)(({ theme: { vars, breakpoints } }) => ({\n  flexDirection: 'column',\n  width: 340,\n  height: 260,\n  alignItems: 'flex-start',\n  borderRadius: 16,\n  border: '10px solid #3D3D3D',\n  background: vars.components?.variables.colors.white,\n  boxShadow:\n    '0px 0px 0px 1px #7A7A7A, 0px 0px 0px 2px #000, 0px 4px 16px 0px rgba(0, 0, 0, 0.64), 0px 4px 36px 0px rgba(0, 0, 0, 0.24)',\n  overflow: 'hidden',\n  justifyContent: 'flex-end',\n\n  [breakpoints.down('desktop')]: {\n    width: 283,\n    height: 262,\n  },\n\n  ...customizeStyles(\n    { vars, breakpoints },\n    (c) => c?.howItWorksMultiStep?.visuals?.wrapper,\n  ),\n}));\n\nexport const ButtonWrapper = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    width: '100%',\n    justifyContent: 'space-between',\n    gap: vars.components?.variables.spacings.md,\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.howItWorksMultiStep?.buttonWrapper,\n    ),\n  }),\n);\n\nexport const LinkToFaqsWrapper = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    alignSelf: 'flex-start',\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.howItWorksMultiStep?.linkToFaqsWrapper,\n    ),\n  }),\n);\n\nexport const IconWrapper = styled(Flex)(({ theme: { vars } }) => ({\n  padding: '25.6px',\n  alignItems: 'center',\n  alignSelf: 'center',\n\n  color: vars.components?.variables.colors.primaryDefault,\n}));\n","import styled from '@emotion/styled';\nimport {\n  customizeStyles,\n  Flex,\n  PhoneWithCountryInput,\n} from '@finmid/tiger-webapp/components';\n\nexport const Container = styled(Flex)(({ theme: { vars } }) => ({\n  flexDirection: 'column',\n  margin: vars.components?.variables.spacings.md,\n  marginBottom: 28.9,\n  alignSelf: 'center',\n}));\n\nexport const StyledPhoneWithCountryInput = styled(PhoneWithCountryInput)(\n  ({ theme: { vars, breakpoints } }) => ({\n    background: vars.components?.variables.colors.grey100,\n    alignSelf: 'center',\n    borderImageWidth: 0,\n    borderRadius: vars.components?.variables.radius.sm,\n    maxWidth: 181,\n\n    fieldset: {\n      border: 'none',\n    },\n\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.howItWorksMultiStep?.visuals?.confirmIdentity?.phoneInput,\n    ),\n  }),\n);\n","import { useTheme } from '@emotion/react';\nimport { getCountry } from '@finmid/countries';\nimport {\n  CustomisationSlot,\n  Icons,\n  useTokenContext,\n} from '@finmid/tiger-webapp/components';\nimport { useGetOffers } from '@finmid/tiger-webapp/queries';\nimport { useMemo } from 'react';\n\nimport { IconWrapper, Wrapper } from '../Visuals.styled';\n\nimport {\n  Container,\n  StyledPhoneWithCountryInput,\n} from './ConfirmIdentityVisual.styled';\n\nexport const ConfirmIdentityVisual = () => {\n  const { vars } = useTheme();\n  const { token, ignoreAction } = useTokenContext();\n\n  const { data: offers } = useGetOffers({ token, ignoreAction });\n\n  const countryIso2 = useMemo(() => {\n    return getCountry(offers?.country ?? null)?.iso2code.toLowerCase();\n  }, [offers]);\n\n  return (\n    <Wrapper>\n      <Container>\n        <IconWrapper>\n          <CustomisationSlot\n            slot=\"howItWorksMultiStep.visuals.confirmIdentity.image\"\n            props={{}}\n            fallback={\n              <Icons.ShieldIcon\n                color={vars.components?.variables.colors.primaryDefault}\n                width={76.8}\n                height={76.8}\n              />\n            }\n          />\n        </IconWrapper>\n        <StyledPhoneWithCountryInput\n          variant=\"outlined\"\n          disabled\n          value=\"** ********* ****\"\n          country={countryIso2}\n        />\n      </Container>\n    </Wrapper>\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  customizeStyles,\n  Flex,\n  Typography,\n} from '@finmid/tiger-webapp/components';\nimport { Box } from '@mui/material';\n\nexport const CardWrapper = styled(Flex)({\n  width: '100%',\n  height: '100%',\n  alignItems: 'flex-start',\n  justifyContent: 'stretch',\n  overflow: 'hidden',\n});\n\nexport const Card = styled.div(({ theme: { vars, breakpoints } }) => ({\n  height: '100%',\n  width: '100%',\n  margin: vars.components?.variables.spacings.md,\n  