oid;\n};\n\nexport const DesktopSubmitButton = ({ disabled, handleSubmit }: Props) => {\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'getFunds',\n  });\n  const { breakpoints } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n\n  if (isMobile) {\n    return null;\n  }\n\n  return (\n    <Container>\n      <Button\n        variant=\"primary\"\n        onClick={handleSubmit}\n        data-test-id=\"sole-proprietor-status-confirm-btn\"\n        fullWidth\n        disabled={disabled}\n        size=\"large\"\n      >\n        {t('confirmSoleProprietorStatus', 'Confirm and continue')}\n      </Button>\n    </Container>\n  );\n};\n\nconst Container = styled(Flex)(({ theme: { vars, breakpoints } }) => ({\n  width: '100%',\n\n  ...customizeStyles(\n    { breakpoints, vars },\n    (c) => c?.soleProprietor?.onItsWay?.question?.submitBtn,\n  ),\n}));\n","import styled from '@emotion/styled';\nimport { customizeStyles } from '@finmid/tiger-webapp/components';\nimport { FormControlLabel } from '@mui/material';\n\ninterface Props {\n  isSelected: boolean;\n}\n\nexport const OptionButton = styled(FormControlLabel)<Props>(\n  ({ theme: { vars, breakpoints }, isSelected }) => ({\n    display: 'flex',\n    alignItems: 'flex-start',\n    width: '100%',\n    margin: 0,\n    backgroundColor: 'white',\n    borderWidth: 1,\n    borderStyle: 'solid',\n    flexGrow: 1,\n    flexBasis: 0,\n\n    borderColor: vars.components?.variables.colors.grey300,\n    borderRadius: vars.components?.variables.radius.md,\n\n    padding: vars.components?.variables.spacings.md,\n    gap: vars.components?.variables.spacings.md,\n\n    '& svg': {\n      fontSize: '18px',\n      marginTop: '3px',\n    },\n\n    '& span': {\n      color: vars.components?.variables.colors.grey900,\n      fontFamily: vars.components?.variables.typography.desktop.family.body,\n      fontSize: vars.components?.variables.typography.desktop.size.sm,\n      lineHeight: vars.components?.variables.typography.desktop.lineHeight.sm,\n\n      [breakpoints.down('desktop')]: {\n        fontFamily: vars.components?.variables.typography.mobile.family.body,\n        fontSize: vars.components?.variables.typography.mobile.size.sm,\n        lineHeight: vars.components?.variables.typography.mobile.lineHeight.sm,\n      },\n    },\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.soleProprietor?.onItsWay?.question?.singleOption?.default,\n    ),\n\n    ...(isSelected\n      ? {\n          borderColor: vars.components?.variables.colors.primaryDefault,\n          '& svg': {\n            color: vars.components?.variables.colors.primaryDefault,\n            fontSize: '18px',\n            marginTop: '3px',\n          },\n          ...customizeStyles(\n            { breakpoints, vars },\n            (c) => c?.soleProprietor?.onItsWay?.question?.singleOption?.pressed,\n          ),\n        }\n      : {}),\n  }),\n);\n","import styled from '@emotion/styled';\nimport { customizeStyles } from '@finmid/tiger-webapp/components';\nimport { Radio, RadioGroup } from '@mui/material';\nimport { ChangeEvent } from 'react';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { OptionButton } from './OptionButton.styled';\n\nexport type OptionType = 'yes' | 'no';\n\ntype Props = {\n  option: OptionType | null;\n  handleSelectOption: (event: ChangeEvent<HTMLInputElement>) => void;\n};\n\nexport const SoleProprietorQuestion = ({\n  option,\n  handleSelectOption,\n}: Props) => {\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'getFunds',\n  });\n\n  return (\n    <OptionsContainer\n      value={option}\n      onChange={handleSelectOption}\n      data-test-id=\"radio-group\"\n    >\n      <OptionButton\n        value=\"no\"\n        isSelected={option === 'no'}\n        control={<Radio sx={{ padding: 0 }} />}\n        label={\n          <Trans\n            t={t}\n            i18nKey=\"optionNotSoleProprietor\"\n            components={{\n              strong: <StyledStrong />,\n            }}\n          />\n        }\n      />\n      <OptionButton\n        value=\"yes\"\n        isSelected={option === 'yes'}\n        control={<Radio sx={{ padding: 0 }} />}\n        label={\n          <Trans\n            t={t}\n            i18nKey=\"optionSoleProprietor\"\n            components={{\n              strong: <StyledStrong />,\n            }}\n          />\n        }\n      />\n    </OptionsContainer>\n  );\n};\n\nconst OptionsContainer = styled(RadioGroup)(\n  ({ theme: { vars, breakpoints } }) => ({\n    display: 'flex',\n    flexDirection: 'row',\n    gap: vars.components?.variables.spacings.md,\n\n    [breakpoints.down('desktop')]: {\n      flexDirection: 'column',\n    },\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.soleProprietor?.onItsWay?.question?.options,\n    ),\n  }),\n);\n\nconst StyledStrong = styled('span')(({ theme: { vars } }) => ({\n  fontWeight: vars.components?.variables.typography.desktop.weight.strong,\n}));\n","import styled from '@emotion/styled';\nimport { customizeStyles, Flex } from '@finmid/tiger-webapp/components';\n\nexport const Container = styled(Flex)(({ theme: { vars, breakpoints } }) => ({\n  flexDirection: 'column',\n  gap: vars.components?.variables.spacings.sm,\n  alignItems: 'flex-start',\n  rowGap: vars.components?.variables.spacings.xl,\n  paddingBlockEnd: vars.components?.variables.spacings.xl,\n\n  [breakpoints.down('desktop')]: {\n    padding: vars.components?.variables.spacings.lg,\n  },\n\n  ...customizeStyles(\n    { breakpoints, vars },\n    (c) => c?.soleProprietor?.onItsWay?.question?.container,\n  ),\n}));\n\nexport const DescriptionContainer = styled(Flex)(({ theme: { vars } }) => ({\n  flexDirection: 'column',\n  rowGap: vars.components?.variables.spacings.sm,\n  alignItems: 'flex-start',\n}));\n","import { ChangeEvent, Dispatch, SetStateAction } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { SubTitle, Title } from './Content.styled';\nimport { DesktopSubmitButton } from './DesktopSubmitButton';\nimport {\n  SoleProprietorQuestion,\n  type OptionType,\n} from './SoleProprietorQuestion';\nimport {\n  Container,\n  DescriptionContainer,\n} from './SoleProprietorSection.styled';\n\ntype Props = {\n  option: OptionType | null;\n  onSubmit: () => void;\n  setOption: Dispatch<SetStateAction<OptionType | null>>;\n};\n\nexport const SoleProprietorSection = ({\n  option,\n  onSubmit,\n  setOption,\n}: Props) => {\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'getFunds',\n  });\n\n  const handleSelectOption = (event: ChangeEvent<HTMLInputElement>) => {\n    setOption((event.target as HTMLInputElement).value as OptionType);\n  };\n\n  return (\n    <div>\n      <Container data-test-id=\"sole-proprietor-section\">\n        <DescriptionContainer>\n          <Title>\n            {t(\n              'soleProprietorTitle',\n              'Is your business operated as a sole proprietorship?',\n            )}\n          </Title>\n          <SubTitle>\n            {t(\n              'soleProprietorDescription',\n              'A sole proprietorship is a business owned by one person who is responsible for all decisions, profits, and debts.',\n            )}\n          </SubTitle>\n        </DescriptionContainer>\n        <SoleProprietorQuestion\n          option={option}\n          handleSelectOption={handleSelectOption}\n        />\n      </Container>\n      <DesktopSubmitButton disabled={option == null} handleSubmit={onSubmit} />\n    </div>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport {\n  CustomisationSlot,\n  Flex,\n  Icons,\n} from '@finmid/tiger-webapp/components';\nimport { useMediaQuery } from '@mui/material';\n\nconst NoCodeVisual = () => {\n  const { breakpoints, vars } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n\n  if (isMobile) {\n    return null;\n  }\n\n  return (\n    <Flex justifyContent=\"center\">\n      <Icons.ScheduleSendIcon\n        color={vars.components?.variables.colors.primaryDefault}\n      />\n    </Flex>\n  );\n};\n\nexport const Visual = () => {\n  return (\n    <CustomisationSlot\n      slot=\"soleProprietor.onItsWayVisual\"\n      props={{}}\n      fallback={<NoCodeVisual />}\n    />\n  );\n};\n","import {\n  MobileStickyNavigation,\n  useCapturePosthogEvent,\n  useCapturePosthogViewed,\n  useSelectedOffer,\n} from '@finmid/tiger-webapp/components';\nimport { useWhatsAppButton } from '@finmid/tiger-webapp/whatsapp';\nimport { Dispatch, SetStateAction, useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { FlowStep } from '../../types';\n\nimport {\n  Background,\n  Container,\n  DescriptionSection,\n  OptionType,\n  SoleProprietorSection,\n  Visual,\n} from './components';\n\ntype Props = {\n  setStep: Dispatch<SetStateAction<FlowStep>>;\n};\n\nexport const RequestOnItsWay = ({ setStep }: Props) => {\n  useWhatsAppButton({ overStickyNavigation: true });\n\n  useCapturePosthogViewed('Request on its way screen viewed');\n  const capturePosthogEvent = useCapturePosthogEvent();\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'getFunds',\n  });\n  const [option, setOption] = useState<OptionType | null>(null);\n  const { selectedOffer, currency } = useSelectedOffer();\n\n  const handleSubmitSoleProprietorAnswer = () => {\n    capturePosthogEvent('User completed sole proprietor step', {\n      isSoleProprietor: option,\n      offer: selectedOffer,\n      currency,\n    });\n    if (option === 'yes') {\n      setStep('upload-registration-documents');\n    } else {\n      setStep('in-review');\n    }\n  };\n\n  return (\n    <MobileStickyNavigation\n      onContinue={handleSubmitSoleProprietorAnswer}\n      continueText={t('confirmSoleProprietorStatus', 'Confirm and continue')}\n      hideBackButton\n    >\n      <Background data-test-id=\"request-on-its-way\">\n        <Container>\n          <Visual />\n          <DescriptionSection />\n          <SoleProprietorSection\n            option={option}\n            onSubmit={handleSubmitSoleProprietorAnswer}\n            setOption={setOption}\n          />\n        </Container>\n      </Background>\n    </MobileStickyNavigation>\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  customizeStyles,\n  Flex,\n  Typography,\n} from '@finmid/tiger-webapp/components';\n\nexport const Container = styled(Flex)(({ theme: { vars, breakpoints } }) => ({\n  flexDirection: 'column',\n  alignItems: 'normal',\n  gap: vars.components?.variables.spacings.xxxl,\n  width: 588,\n  margin: '0 auto',\n  padding: `${vars.components?.variables.spacings.xxl} 0`,\n\n  [breakpoints.down('desktop')]: {\n    width: '100%',\n    padding: vars.components?.variables.spacings.lg,\n    gap: vars.components?.variables.spacings.xxl,\n  },\n\n  ...customizeStyles(\n    { breakpoints, vars },\n    (c) => c?.soleProprietor?.upload?.container,\n  ),\n}));\n\nexport const DescriptionContainer = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  alignItems: 'flex-start',\n  gap: theme.vars.components?.variables.spacings.sm,\n  ...customizeStyles(\n    theme,\n    (c) => c?.soleProprietor?.upload?.description?.container,\n  ),\n}));\n\nexport const Title = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(\n    theme,\n    (c) => c?.soleProprietor?.upload?.description?.title,\n  ),\n}));\n\nexport const Subtitle = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(\n    theme,\n    (c) => c?.soleProprietor?.upload?.description?.subtitle,\n  ),\n}));\n\nexport const DropzoneCard = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  alignItems: 'normal',\n  gap: theme.vars.components?.variables.spacings.md,\n\n  ...customizeStyles(theme, (c) => c?.soleProprietor?.upload?.dropzone?.card),\n}));\n\nexport const DropzoneContainer = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  alignItems: 'normal',\n  width: '100%',\n  gap: theme.vars.components?.variables.spacings.xl,\n\n  ...customizeStyles(\n    theme,\n    (c) => c?.soleProprietor?.upload?.dropzone?.container,\n  ),\n}));\n","import styled from '@emotion/styled';\nimport { Button, Flex } from '@finmid/tiger-webapp/components';\nimport { useTranslation } from 'react-i18next';\n\ntype Props = {\n  disabled: boolean;\n  loading: boolean;\n  handleSubmit: () => void;\n};\n\nexport const SubmitButton = ({ disabled, loading, handleSubmit }: Props) => {\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'soleProprietor.uploadsDocs',\n  });\n\n  return (\n    <Container>\n      <Button\n        variant=\"primary\"\n        onClick={handleSubmit}\n        data-test-id=\"sole-proprietor-status-confirm-btn\"\n        fullWidth\n        disabled={disabled}\n        size=\"large\"\n        loading={loading}\n      >\n        {t('finalise', 'Finalise')}\n      </Button>\n    </Container>\n  );\n};\n\nconst Container = styled(Flex)(({ theme: { vars, breakpoints } }) => ({\n  width: '100%',\n\n  [breakpoints.down('desktop')]: {\n    paddingBlock: vars.components?.variables.spacings.md,\n    paddingInline: vars.components?.variables.spacings.lg,\n  },\n  [breakpoints.down('tablet')]: {\n    borderTop: `1px solid ${vars.components?.variables.colors.grey300}`,\n    borderBottom: `1px solid ${vars.components?.variables.colors.grey300}`,\n  },\n}));\n","import { useTheme } from '@emotion/react';\nimport {\n  CustomisationSlot,\n  Flex,\n  Icons,\n} from '@finmid/tiger-webapp/components';\nimport { useMediaQuery } from '@mui/material';\n\nconst NoCodeVisual = () => {\n  const { breakpoints, vars } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n\n  if (isMobile) {\n    return null;\n  }\n\n  return (\n    <Flex justifyContent=\"center\">\n      <Icons.UploadFileIcon\n        width={96}\n        height={96}\n        color={vars.components?.variables.colors?.primaryDefault}\n      />\n    </Flex>\n  );\n};\n\nexport const Visual = () => {\n  return (\n    <CustomisationSlot\n      slot=\"soleProprietor.uploadDocument\"\n      props={{}}\n      fallback={<NoCodeVisual />}\n    />\n  );\n};\n","import styled from '@emotion/styled';\nimport { Flex } from '@finmid/tiger-webapp/components';\n\nexport const Container = styled(Flex)(({ theme: { vars } }) => ({\n  gap: vars.components?.variables.spacings.xxxl,\n  padding: `0 ${vars.components?.variables.spacings.md}`,\n  backgroundColor: vars.components?.variables.colors.grey100,\n  borderRadius: vars.components?.variables.radius.md,\n  justifyContent: 'space-between',\n}));\n","import { useTheme } from '@emotion/react';\nimport {\n  Button,\n  CustomisationSlot,\n  Flex,\n  Modal,\n  Typography,\n} from '@finmid/tiger-webapp/components';\nimport { useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { Container } from './DocumentsNeededExample.styled';\n\nexport const DocumentsNeededExample = () => {\n  const theme = useTheme();\n  const { t } = useTranslation('offers', {\n    keyPrefix: 'soleProprietor.uploadsDocs',\n  });\n  const [isModalOpen, setIsModalOpen] = useState(false);\n\n  const handleOpenModal = () => setIsModalOpen(true);\n  const handleCloseModal = () => setIsModalOpen(false);\n\n  return (\n    <Container alignItems=\"flex-end\">\n      <Flex\n        flexDirection=\"column\"\n        gap=\"xxl\"\n        justifyContent=\"space-between\"\n        alignItems=\"flex-start\"\n        height=\"100%\"\n        paddingY={theme.vars.components?.variables.spacings.md}\n      >\n        <Flex flexDirection=\"column\" gap=\"xs\" alignItems=\"flex-start\">\n          <Typography size=\"md\" weight=\"strong\">\n            {t('documentsNeededExample', 'Documents needed')}\n          </Typography>\n          <Typography size=\"sm\">\n            {t('documentsNeededExampleDescription', 'Description')}\n          </Typography>\n        </Flex>\n        <Button variant=\"primary\" size=\"large\" onClick={handleOpenModal} nowrap>\n          {t('documentsNeededExampleButton', 'See examples')}\n        </Button>\n      </Flex>\n      <CustomisationSlot\n        slot=\"soleProprietor.uploadsDocs.documentsNeededExample\"\n        props={{}}\n      />\n      <Modal\n        open={isModalOpen}\n        onClose={handleCloseModal}\n        withCloseButton\n        maxWidth={636}\n      >\n        <CustomisationSlot\n          slot=\"soleProprietor.uploadsDocs.documentsNeededModal\"\n          props={{ onClose: handleCloseModal }}\n        />\n      </Modal>\n    </Container>\n  );\n};\n","import {\n  DocumentDropzone,\n  MobileStickyNavigation,\n  useCapturePosthogViewed,\n  useResponsive,\n  useTokenContext,\n} from '@finmid/tiger-webapp/components';\nimport {\n  BusinessDocument,\n  BusinessDocumentValidationResult,\n} from '@finmid/tiger-webapp/queries';\nimport { useWhatsAppButton } from '@finmid/tiger-webapp/whatsapp';\nimport { useState } from 'react';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport {\n  Container,\n  DescriptionContainer,\n  Subtitle,\n  Title,\n} from './UploadRegistrationDocuments.styled';\nimport { DocumentsNeededExample, SubmitButton, Visual } from './components';\n\ntype UploadRegistrationDocumentsProps = {\n  onContinue: () => void;\n};\n\nexport const UploadRegistrationDocuments = ({\n  onContinue,\n}: UploadRegistrationDocumentsProps) => {\n  const { token } = useTokenContext();\n  useWhatsAppButton({ overStickyNavigation: true });\n\n  useCapturePosthogViewed('Upload sole proprietor screen viewed');\n  const { isMobile } = useResponsive();\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'soleProprietor.uploadsDocs',\n  });\n\n  const [documents, setDocuments] = useState<BusinessDocument[]>([]);\n\n  const documentUploadProps = DocumentDropzone.useProps(\n    'BUSINESS',\n    'SOLE_PROPRIETOR',\n    {},\n  );\n\n  const { mutateAsync: submitDocuments, isPending } =\n    DocumentDropzone.useSubmit(\n      documentUploadProps.level.type,\n      documentUploadProps.documentType,\n    );\n\n  const onSubmit = async () => {\n    await submitDocuments({ token });\n    onContinue();\n  };\n\n  const isButtonDisabled =\n    documents.length === 0 ||\n    isPending ||\n    documents.some(\n      (document) =>\n        document.validationResult === BusinessDocumentValidationResult.PENDING,\n    );\n\n  return (\n    <MobileStickyNavigation\n      onContinue={onContinue}\n      continueText={t('finalise', 'Finalise')}\n      isDisabled={isButtonDisabled}\n      hideBackButton\n    >\n      <Container data-test-id=\"sole-proprietor-upload\">\n        <Visual />\n\n        <DescriptionContainer>\n          <Title size=\"xxl\" family=\"title\" weight=\"strong\">\n            {t('title')}\n          </Title>\n          <Subtitle size=\"md\">\n            <Trans i18nKey=\"soleProprietor.uploadsDocs.subtitle\" />\n          </Subtitle>\n        </DescriptionContainer>\n\n        <DocumentDropzone\n          {...documentUploadProps}\n          onChange={setDocuments}\n          refetchInterval={\n            documents.find(\n              (document) =>\n                document.validationResult ===\n                BusinessDocumentValidationResult.PENDING,\n            )\n              ? 1000\n              : undefined\n          }\n        />\n\n        {!isMobile ? (\n          <SubmitButton\n            disabled={isButtonDisabled}\n            handleSubmit={onSubmit}\n            loading={isPending}\n          />\n        ) : null}\n\n        <DocumentsNeededExample />\n      </Container>\n    </MobileStickyNavigation>\n  );\n};\n","import {\n  DocumentDropzone,\n  useTokenContext,\n} from '@finmid/tiger-webapp/components';\nimport {\n  useGetOffers,\n  useGetUploadedDocuments,\n} from '@finmid/tiger-webapp/queries';\nimport { useState } from 'react';\n\nimport { GetFunds } from '..';\n\nimport {\n  RequestInReview,\n  RequestOnItsWay,\n  UploadRegistrationDocuments,\n} from './components';\nimport { FlowStep } from './types';\n\nexport const SoleProprietorFlow = () => {\n  const { token, ignoreAction } = useTokenContext();\n  const { data } = useGetOffers({ token, ignoreAction });\n  const [step, setStep] = useState<FlowStep>('on-its-way');\n\n  const documentUploadProps = DocumentDropzone.useProps(\n    'BUSINESS',\n    'SOLE_PROPRIETOR',\n    {},\n  );\n\n  const { data: documentsData } = useGetUploadedDocuments<'BUSINESS'>({\n    token,\n    ...documentUploadProps,\n  });\n\n  if (documentsData?.isSubmitted && step !== 'in-review') {\n    setStep('in-review');\n  }\n\n  // V2 API returns latestCredit only when in PENDING state.\n  // Absence of latestCredit (when data has loaded) indicates the payout was rejected/cancelled/completed.\n  if (data != null && data.latestCredit == null) {\n    return <GetFunds />;\n  }\n\n  // Offer accepted by merchant\n  if (step === 'on-its-way') {\n    return <RequestOnItsWay setStep={setStep} />;\n  }\n\n  if (step === 'upload-registration-documents') {\n    return (\n      <UploadRegistrationDocuments onContinue={() => setStep('in-review')} />\n    );\n  }\n\n  if (step === 'in-review') {\n    return <RequestInReview />;\n  }\n};\n","import {\n  usePlatformSettings,\n  useTokenContext,\n} from '@finmid/tiger-webapp/components';\nimport { useGetOffers } from '@finmid/tiger-webapp/queries';\n\nexport const useSoleProprietorEnabled = () => {\n  const { token, ignoreAction } = useTokenContext();\n  const { data } = useGetOffers({ token, ignoreAction });\n  const { experiments } = usePlatformSettings();\n\n  const isExperimentEnabled =\n    data?.country &&\n    experiments?.soleProprietorEnabled?.includes(data?.country);\n\n  return isExperimentEnabled;\n};\n","import styled from '@emotion/styled';\nimport {\n  Flex,\n  Typography,\n  customizeStyles,\n} from '@finmid/tiger-webapp/components';\n\nexport const Title = styled(Typography)(({ theme }) => ({\n  textAlign: 'left',\n  zIndex: 1,\n\n  ...customizeStyles(\n    theme,\n    (c) => c?.offerConfirmation?.CSP?.speedUpTheProcessCallout?.title,\n  ),\n}));\n\nexport const Subtitle = styled(Typography)(({ theme }) => ({\n  textAlign: 'left',\n  zIndex: 1,\n\n  ...customizeStyles(\n    theme,\n    (c) => c?.offerConfirmation?.CSP?.speedUpTheProcessCallout?.subtitle,\n  ),\n}));\n\nexport const Container = styled(Flex)(({ theme }) => ({\n  width: '100%',\n  height: '190px',\n  flexDirection: 'column',\n  justifyContent: 'space-between',\n  alignItems: 'flex-start',\n  zIndex: 1,\n  position: 'relative',\n  overflow: 'hidden',\n\n  backgroundColor: theme.vars.components?.variables.colors?.grey100,\n  borderRadius: theme.vars.components?.variables.radius.md,\n\n  padding: theme.vars.components?.variables.spacings?.md,\n  gap: theme.vars.components?.variables.spacings?.xs,\n\n  ...customizeStyles(\n    theme,\n    (c) => c?.offerConfirmation?.CSP?.speedUpTheProcessCallout?.root,\n  ),\n}));\n","import {\n  Button,\n  DocumentDropzone,\n  Flex,\n  Icons,\n  useCssVariable,\n  useSelectedOffer,\n  useTokenContext,\n} from '@finmid/tiger-webapp/components';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { Container, Subtitle, Title } from './SpeedUpTheProcessCallout.styled';\n\nexport const SpeedUpTheProcessCallout: FunctionComponent = () => {\n  const { token } = useTokenContext();\n  const { financingSetup, offerGroupId } = useSelectedOffer();\n\n  const { t } = useTranslation('offers', {\n    keyPrefix: `getFunds.${financingSetup}.speedUpTheProcessCallout`,\n  });\n\n  const navigate = useNavigate();\n\n  const variant = useCssVariable(\n    'offerConfirmation.CSP.speedUpTheProcessCallout.continueButton.variant',\n    (c) =>\n      c?.offerConfirmation?.CSP?.speedUpTheProcessCallout?.continueButton\n        ?.variant,\n    'secondary',\n  );\n\n  const documentProps = DocumentDropzone.useProps(\n    'OFFER',\n    'CSP_FINANCIAL_DOCUMENT',\n    { offerGroupId: offerGroupId ?? '' },\n  );\n\n  const { data } = DocumentDropzone.useDocuments({\n    token,\n    ...documentProps,\n  });\n\n  if (offerGroupId == null || data == null || data.isSubmitted) {\n    return null;\n  }\n\n  return (\n    <Container data-test-id=\"speed-up-callout\">\n      <Flex\n        flexDirection=\"column\"\n        gap=\"xs\"\n        justifyContent=\"start\"\n        alignItems=\"start\"\n      >\n        <Title size=\"md\" weight=\"strong\">\n          {t('title', 'Speed up the process')}\n        </Title>\n        <Subtitle size=\"sm\">\n          {t(\n            'subtitle',\n            'Upload financial documents to make the approval process even faster. ',\n          )}\n        </Subtitle>\n      </Flex>\n\n      <Flex gap=\"sm\">\n        <Button\n          variant={variant}\n          sx={{ zIndex: 1 }}\n          onClick={() => {\n            navigate('/get-funds/speed-up');\n          }}\n        >\n          {t('continueButton', 'Continue to upload')}\n        </Button>\n        <div\n          className=\"speedup-process-icon\"\n          style={{ position: 'absolute', top: 20, right: -10, zIndex: 0 }}\n        >\n          <Icons.IconRightDashed />\n        </div>\n      </Flex>\n    </Container>\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  Flex,\n  Typography,\n  customizeStyles,\n} from '@finmid/tiger-webapp/components';\n\nexport const Page = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  justifyContent: 'space-between',\n  alignItems: 'flex-start',\n\n  marginLeft: 'auto',\n  marginRight: 'auto',\n\n  width: '100%',\n  maxWidth: 588,\n\n  gap: theme.vars.components?.variables.spacings?.xxxl,\n  paddingTop: theme.vars.components?.variables.spacings?.xxl,\n  paddingBottom: theme.vars.components?.variables.spacings?.xxl,\n\n  ...customizeStyles(\n    theme,\n    (c) => c?.offerConfirmation?.CSP?.speedUpTheProcessPage?.root,\n  ),\n}));\n\nexport const Title = styled(Typography)(({ theme }) => ({\n  width: '100%',\n  textAlign: 'left',\n\n  ...customizeStyles(\n    theme,\n    (c) => c?.offerConfirmation?.CSP?.speedUpTheProcessPage?.title,\n  ),\n}));\n\nexport const Subtitle = styled(Typography)(({ theme }) => ({\n  width: '100%',\n  textAlign: 'left',\n\n  ...customizeStyles(\n    theme,\n    (c) => c?.offerConfirmation?.CSP?.speedUpTheProcessPage?.subtitle,\n  ),\n}));\n","import { useTheme } from '@emotion/react';\nimport {\n  Button,\n  DocumentDropzone,\n  FeedbackPopup,\n  Flex,\n  Icons,\n  useSelectedOffer,\n  useTokenContext,\n} from '@finmid/tiger-webapp/components';\nimport { BusinessDocument } from '@finmid/tiger-webapp/queries';\nimport { FunctionComponent, useState } from 'react';\nimport { Trans, useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { Page, Subtitle, Title } from './SpeedUpTheProcessPage.styled';\n\nexport const SpeedUpTheProcessPage: FunctionComponent = () => {\n  const { token } = useTokenContext();\n  const { selectedOffer, offerGroupId } = useSelectedOffer();\n\n  const [documents, setDocuments] = useState<BusinessDocument[]>([]);\n\n  const { t } = useTranslation('offers', {\n    keyPrefix: 'getFunds.CSP.speedUpTheProcessPage',\n  });\n\n  const { t: tPopover } = useTranslation('turnkey', {\n    keyPrefix: 'plus.upload',\n  });\n\n  const navigate = useNavigate();\n\n  const { vars } = useTheme();\n\n  const documentUploadProps = DocumentDropzone.useProps(\n    'OFFER',\n    'CSP_FINANCIAL_DOCUMENT',\n    {\n      offerGroupId: offerGroupId ?? '',\n    },\n  );\n\n  const { mutateAsync: submitDocuments, isPending } =\n    DocumentDropzone.useSubmit(\n      documentUploadProps.level.type,\n      documentUploadProps.documentType,\n    );\n\n  const { data } = DocumentDropzone.useDocuments({\n    token,\n    ...documentUploadProps,\n  });\n\n  if (offerGroupId == null || data == null || data.isSubmitted) {\n    return null;\n  }\n\n  return (\n    <Page data-test-id=\"speed-up-the-process-page\">\n      <Flex justifyContent=\"center\" alignItems=\"center\" width=\"100%\">\n        <Icons.UploadFileIcon\n          width={96}\n          height={96}\n          color={vars.components?.variables.colors.primaryDefault}\n        />\n      </Flex>\n\n      <Flex flexDirection=\"column\" gap=\"xs\">\n        <Flex\n          width=\"100%\"\n          justifyContent=\"space-between\"\n          alignItems=\"center\"\n          gap=\"md\"\n        >\n          <Title size=\"lg\" weight=\"strong\">\n            {t('title', 'Upload financial documents')}\n          </Title>\n          <DocumentDropzone.Popover\n            t={tPopover}\n            titleKey=\"docsPopover.title\"\n            textListKey=\"docsPopover.textList\"\n          />\n        </Flex>\n        <Subtitle size=\"sm\">\n          <Trans t={t} i18nKey=\"subtitle\" components={{ b: <b /> }}>\n            Upload your most recent {'<b>'}profit and loss statement{'</b>'},{' '}\n            {'<b>'}cash flow statement{'</b>'}, {'<b>'}balance sheet{'</b>'},{' '}\n            {'<b>'}bank statements{'</b>'} and {'<b>'}any existing business loan\n            agreement{'</b>'} to help us learn more about your revenue outside\n            of {'{{'} platform {'}}'}.\n          </Trans>\n        </Subtitle>\n      </Flex>\n\n      <DocumentDropzone onChange={setDocuments} {...documentUploadProps} />\n\n      <Button\n        variant=\"primary\"\n        fullWidth\n        disabled={documents.length === 0}\n        loading={isPending}\n        onClick={async () => {\n          await submitDocuments({ token, offerGroupId });\n          navigate('/get-funds/speed-up/submitted');\n        }}\n      >\n        {t('finalizeButton', 'Finalize')}\n      </Button>\n\n      {selectedOffer && <FeedbackPopup offerId={selectedOffer.id} />}\n    </Page>\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  Flex,\n  Icons,\n  Typography,\n  customizeStyles,\n  customized,\n} from '@finmid/tiger-webapp/components';\nimport { ComponentProps, FunctionComponent } from 'react';\n\nexport const Page = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  justifyContent: 'space-between',\n  alignItems: 'flex-start',\n\n  marginLeft: 'auto',\n  marginRight: 'auto',\n\n  width: '100%',\n  maxWidth: 588,\n\n  gap: theme.vars.components?.variables.spacings?.xxxl,\n  paddingTop: theme.vars.components?.variables.spacings?.xxl,\n  paddingBottom: theme.vars.components?.variables.spacings?.xxl,\n\n  ...customizeStyles(\n    theme,\n    (c) => c?.offerConfirmation?.CSP?.documentsSubmittedPage?.root,\n  ),\n}));\n\nexport const Title = styled(Typography)(({ theme }) => ({\n  width: '100%',\n  textAlign: 'left',\n\n  ...customizeStyles(\n    theme,\n    (c) => c?.offerConfirmation?.CSP?.documentsSubmittedPage?.title,\n  ),\n}));\n\nexport const Subtitle = styled(Typography)(({ theme }) => ({\n  width: '100%',\n  textAlign: 'left',\n\n  ...customizeStyles(\n    theme,\n    (c) => c?.offerConfirmation?.CSP?.documentsSubmittedPage?.subtitle,\n  ),\n}));\n\nexport const Illustration = styled(Flex)(({ theme }) => ({\n  width: '100%',\n  height: '260px',\n\n  alignItems: 'flex-end',\n  justifyContent: 'center',\n\n  overflow: 'hidden',\n\n  backgroundColor: theme.vars.components?.variables.colors.grey100,\n  borderRadius: theme.vars.components?.variables.radius.lg,\n\n  ...customizeStyles(\n    theme,\n    (c) =>\n      c?.offerConfirmation?.CSP?.documentsSubmittedPage?.illustration?.root,\n  ),\n}));\n\nexport const StatsCard = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  alignItems: 'center',\n  justifyContent: 'center',\n\n  width: '256px',\n\n  borderRadius: '16px',\n  marginBottom: '-16px',\n\n  border: `10px solid #3D3D3D`,\n  background: theme.vars.components?.variables.colors.white,\n  boxShadow:\n    '0px 0px 0px 1px #7A7A7A, 0px 0px 0px 2px #000, 0px 4px 16px 0px rgba(0, 0, 0, 0.64), 0px 4px 36px 0px rgba(0, 0, 0, 0.24)',\n\n  boxSizing: 'border-box',\n\n  ...customizeStyles(\n    theme,\n    (c) =>\n      c?.offerConfirmation?.CSP?.documentsSubmittedPage?.illustration\n        ?.statsCard,\n  ),\n}));\n\nexport const StatsRow = styled(Flex)(({ theme }) => ({\n  flexDirection: 'row',\n  alignItems: 'center',\n  justifyContent: 'space-between',\n\n  width: '100%',\n\n  padding: `${theme.vars.components?.variables.spacings?.sm} ${theme.vars.components?.variables.spacings?.md}`,\n\n  borderBottom: `1px solid ${theme.vars.components?.variables.colors.grey300}`,\n\n  ...customizeStyles(\n    theme,\n    (c) =>\n      c?.offerConfirmation?.CSP?.documentsSubmittedPage?.illustration?.statsRow\n        ?.root,\n  ),\n}));\n\nexport const StatsRowLabel = customized(\n  Typography,\n  (c) =>\n    c?.offerConfirmation?.CSP?.documentsSubmittedPage?.illustration?.statsRow\n      ?.label,\n);\n\nconst StatsRowValue = customized(\n  Typography,\n  (c) =>\n    c?.offerConfirmation?.CSP?.documentsSubmittedPage?.illustration?.statsRow\n      ?.value,\n);\n\nconst Blur = styled('div')({\n  filter: 'blur(8px)',\n  userSelect: 'none',\n  pointerEvents: 'none',\n});\n\nexport const StatsRowValueBlurred: FunctionComponent<\n  ComponentProps<typeof StatsRowValue> & {\n    blur: boolean;\n    defaultValue: string;\n    children: React.ReactNode;\n  }\n> = ({ blur, children, defaultValue, ...props }) => {\n  if (blur)\n    return (\n      <Blur>\n        <StatsRowValue {...props}>{defaultValue}</StatsRowValue>\n      </Blur>\n    );\n\n  return <StatsRowValue {...props}>{children}</StatsRowValue>;\n};\n\nexport const StatsBadge = styled(Icons.TaskAltIcon)(({ theme }) => ({\n  flexDirection: 'row',\n  alignItems: 'center',\n  justifyContent: 'center',\n\n  position: 'absolute',\n\n  top: '-32px',\n  right: '-32px',\n\n  borderRadius: '50%',\n  padding: '11px',\n\n  width: 64,\n  height: 64,\n\n  color: theme.vars.components?.variables.colors.white,\n  backgroundColor: theme.vars.components?.variables.colors.primaryDefault,\n\n  boxShadow:\n    '2.667px -2.667px 5.333px 0px rgba(0, 0, 0, 0.24) inset, 2.667px -2.667px 0px 0px rgba(0, 0, 0, 0.12) inset, -2.667px 5.333px 10.667px 0px rgba(0, 0, 0, 0.25)',\n}));\n","import { Flex, useSelectedOffer } from '@finmid/tiger-webapp/components';\nimport { Offer, TypedOffer } from '@finmid/tiger-webapp/queries';\nimport { useFormat } from '@finmid/translations';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useLocalStorage } from 'react-use';\n\nimport {\n  StatsBadge,\n  StatsCard,\n  StatsRow,\n  StatsRowLabel,\n  StatsRowValueBlurred,\n} from './DocumentsSubmittedPage.styled';\n\nexport const AcceptedOfferCard: FunctionComponent = () => {\n  const {\n    selectedOffer,\n    financingSetup,\n    currency: selectedCurrency,\n  } = useSelectedOffer();\n\n  const [cachedOffer] = useLocalStorage('cached-accepted-offer', {\n    selectedOffer,\n    currency: selectedCurrency,\n  });\n\n  const fallbackOffer: TypedOffer<'CSP', 'FLEXIBLE'> = {\n    currentOutstandingAmount: 0,\n    estimatedPayoffMonths: 0,\n    fee: 0,\n    id: '',\n    paymentPercentage: 0,\n    payoutAmount: 0,\n    repaymentType: 'FLEXIBLE',\n    totalOutstandingAmount: 0,\n    financingSetup: 'CSP',\n  };\n\n  const offer: Offer = cachedOffer?.selectedOffer ?? fallbackOffer;\n\n  const currency = cachedOffer?.currency ?? 'EUR';\n\n  const { t } = useTranslation('offers', {\n    keyPrefix: `getFunds.${financingSetup}.documentsSubmittedPage`,\n  });\n\n  const { money, formatPercent, months } = useFormat();\n\n  const blur = offer.payoutAmount === 0;\n\n  return (\n    <Flex position=\"relative\">\n      <StatsBadge />\n      <StatsCard>\n        <StatsRow>\n          <StatsRowLabel size=\"xs\">\n            {t('payoutAmount', 'Payout amount')}\n          </StatsRowLabel>\n          <StatsRowValueBlurred\n            blur={blur}\n            defaultValue=\"hidden amount\"\n            size=\"xs\"\n          >\n            {money(offer.payoutAmount, currency)}\n          </StatsRowValueBlurred>\n        </StatsRow>\n        <StatsRow>\n          <StatsRowLabel size=\"xs\">\n            {t('capitalFee', 'Capital fee')}\n          </StatsRowLabel>\n          <StatsRowValueBlurred blur={blur} defaultValue=\"hidden fee\" size=\"xs\">\n            {money(offer.fee, currency)}\n          </StatsRowValueBlurred>\n        </StatsRow>\n        <StatsRow>\n          <StatsRowLabel size=\"xs\">\n            {t('repaymentTime', 'Repayment time')}\n          </StatsRowLabel>\n          <StatsRowValueBlurred\n            blur={blur}\n            defaultValue=\"hidden time\"\n            size=\"xs\"\n          >\n            {months(offer.estimatedPayoffMonths)}\n          </StatsRowValueBlurred>\n        </StatsRow>\n        {offer.repaymentType === 'FLEXIBLE' && (\n          <StatsRow>\n            <StatsRowLabel size=\"xs\">\n              {t('repaymentRate', 'Repayment rate')}\n            </StatsRowLabel>\n            <StatsRowValueBlurred blur={blur} defaultValue=\"percent\" size=\"xs\">\n              {formatPercent(offer.paymentPercentage)}\n            </StatsRowValueBlurred>\n          </StatsRow>\n        )}\n        <StatsRow>\n          <StatsRowLabel size=\"xs\" weight=\"strong\">\n            {t('totalAmount', 'Total amount')}\n          </StatsRowLabel>\n          <StatsRowValueBlurred\n            blur={blur}\n            defaultValue=\"hidden amount\"\n            size=\"xs\"\n            weight=\"strong\"\n          >\n            {money(offer.payoutAmount + offer.fee, currency)}\n          </StatsRowValueBlurred>\n        </StatsRow>\n      </StatsCard>\n    </Flex>\n  );\n};\n","import {\n  Flex,\n  useSelectedOffer,\n  useTokenContext,\n} from '@finmid/tiger-webapp/components';\nimport { useGetOffers } from '@finmid/tiger-webapp/queries';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { AcceptedOfferCard } from './AcceptedOfferCard';\nimport {\n  Illustration,\n  Page,\n  Subtitle,\n  Title,\n} from './DocumentsSubmittedPage.styled';\n\nexport const DocumentsSubmittedPage: FunctionComponent = () => {\n  const { financingSetup } = useSelectedOffer();\n\n  const { token, ignoreAction } = useTokenContext();\n  const { data } = useGetOffers({ token, ignoreAction });\n\n  const { t } = useTranslation('offers', {\n    keyPrefix: `getFunds.${financingSetup}.documentsSubmittedPage`,\n  });\n\n  return (\n    <Page data-test-id=\"documents-submitted-page\">\n      <Illustration>\n        <AcceptedOfferCard />\n      </Illustration>\n\n      <Flex flexDirection=\"column\" gap=\"xs\">\n        <Flex\n          width=\"100%\"\n          justifyContent=\"space-between\"\n          alignItems=\"center\"\n          gap=\"md\"\n        >\n          <Title size=\"xl\" weight=\"strong\">\n            {t('title', 'Your information has been successfully submitted.')}\n          </Title>\n        </Flex>\n        <Subtitle size=\"md\">\n          {t('subtitle', {\n            defaultValue:\n              'If approved, your funds will be transferred to the account with IBAN ending in {{ iban }} within 2 working days. You’ll receive a copy of the final agreement and plan information via email.',\n            iban: data?.maskedPayoutIban,\n          })}\n        </Subtitle>\n      </Flex>\n    </Page>\n  );\n};\n","import {\n  ContactSupport,\n  CustomisationSlot,\n  FeedbackPopup,\n  Flex,\n  useCapturePosthogViewed,\n  useSelectedOffer,\n  useTokenContext,\n} from '@finmid/tiger-webapp/components';\nimport { useOverrides } from '@finmid/tiger-webapp/overrides-manager';\nimport { useGetOffers } from '@finmid/tiger-webapp/queries';\nimport { useWhatsAppButton } from '@finmid/tiger-webapp/whatsapp';\nimport { friendlyFormatIBAN } from 'ibantools';\nimport { FunctionComponent, useEffect, useState } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { useCapitalPlusRequestStatus } from '../../hooks';\n\nimport { AnimatedStateIcon } from './AnimatedStateIcon';\nimport { FundingAmountAccordion } from './FundingAmountAccordion';\nimport {\n  Container,\n  Content,\n  ContentInner,\n  Description,\n  Title,\n} from './GetFunds.styled';\nimport { SeePaymentPlan } from './SeePaymentPlan';\nimport { SoleProprietorFlow } from './SoleProprietorFlow/SoleProprietorFlow';\nimport { useSoleProprietorEnabled } from './SoleProprietorFlow/useSoleProprietorEnabled';\nimport { SpeedUpTheProcessCallout } from './SpeedUpTheProcess';\n\ninterface Props {\n  capitalPlus?: true;\n}\n\nexport const GetFunds: FunctionComponent<Props> = ({ capitalPlus }) => {\n  const navigate = useNavigate();\n  useWhatsAppButton();\n\n  const { selectedOffer, financingSetup } = useSelectedOffer();\n  const { t } = useTranslation('offers', {\n    keyPrefix: `getFunds.${financingSetup}`,\n  });\n\n  const { token, ignoreAction } = useTokenContext();\n\n  const [refetchInterval, setRefetchInterval] = useState(\n    capitalPlus ? 500 : undefined,\n  );\n  const { data } = useGetOffers({\n    token,\n    ignoreAction,\n    refetchInterval,\n  });\n\n  const { overrides } = useOverrides();\n  const isSoleProprietorEnabled = useSoleProprietorEnabled();\n  const paymentReviewStatus = data?.latestCredit?.reviewStatus;\n  const hasNewOffers = data?.offerGroup != null;\n  const { capitalPlusRequestHasBeenGranted } = useCapitalPlusRequestStatus();\n\n  useCapturePosthogViewed('Offer accepted screen viewed', {\n    variant: selectedOffer == null ? 'Reviewing' : 'Accepted',\n    features: {\n      capitalPlus,\n      financingSetup,\n    },\n  });\n\n  useEffect(() => {\n    if (paymentReviewStatus === 'PAYOUT_SUCCESSFUL') {\n      navigate('/dashboard');\n    }\n  }, [paymentReviewStatus, navigate]);\n\n  useEffect(() => {\n    if (capitalPlusRequestHasBeenGranted) {\n      navigate(hasNewOffers ? '/renewal/overview' : '/dashboard');\n    }\n  }, [capitalPlusRequestHasBeenGranted, hasNewOffers, navigate]);\n\n  if (overrides?.soleProprietor || isSoleProprietorEnabled) {\n    return <SoleProprietorFlow />;\n  }\n\n  const iban = data?.maskedPayoutIban ?? 'XXXX';\n\n  let headerI18nKey = 'header';\n  let descriptionI18nKey = 'message';\n\n  if (selectedOffer == null) {\n    headerI18nKey = 'headerReviewing';\n  }\n\n  switch (paymentReviewStatus) {\n    case 'CREATED':\n      headerI18nKey = 'headerAccepted';\n      descriptionI18nKey = 'messageAccepted';\n      break;\n    case 'IN_REVIEW':\n      headerI18nKey = 'headerReviewing';\n      descriptionI18nKey = 'messageReviewing';\n      break;\n    case 'DETAILS_REQUIRED':\n      headerI18nKey = 'headerDetailsRequired';\n      descriptionI18nKey = 'messageDetailsRequired';\n      break;\n    case 'IN_PAYOUT':\n      headerI18nKey = 'headerInPayout';\n      descriptionI18nKey = 'messageInPayout';\n      break;\n    case 'PAYOUT_SUCCESSFUL':\n      headerI18nKey = 'headerPayoutSuccessful';\n      descriptionI18nKey = 'messagePayoutSuccessful';\n      break;\n    case 'REJECTED':\n      headerI18nKey = 'headerRejected';\n      descriptionI18nKey = 'messageRejected';\n      break;\n  }\n\n  if (capitalPlus) {\n    if (data?.capitalPlus?.logicalStatus !== 'AVAILABLE' && refetchInterval) {\n      setRefetchInterval(undefined);\n    }\n    headerI18nKey = 'headerCapitalPlus';\n    descriptionI18nKey = 'messageCapitalPlus';\n  }\n\n  const capitalPlusDocsShared = data?.capitalPlus?.status === 'DOCS_SHARED';\n\n  const hasLatestCreditPaidOut =\n    data?.latestCredit?.id != null ? data?.latestCredit.isPaidOut : false;\n\n  return (\n    <Container data-test-id=\"offer-accepted-screens\" plus={!!capitalPlus}>\n      <Content data-test-id=\"offer-accepted\">\n        <ContentInner\n          data-test-id=\"offer-accepted-content\"\n          className=\"offer-accepted-content\"\n          centeredContent\n        >\n          <CustomisationSlot\n            slot=\"getFunds.reviewStatusIcon\"\n            fallback={<AnimatedStateIcon status={paymentReviewStatus} />}\n            props={{\n              paymentReviewStatus: paymentReviewStatus ?? 'CREATED',\n            }}\n          />\n\n          <CustomisationSlot\n            slot=\"getFunds.statusText\"\n            fallback={\n              <Flex flexDirection=\"column\" gap=\"xs\">\n                <Title\n                  size=\"xxl\"\n                  weight=\"strong\"\n                  family=\"title\"\n                  lineHeight=\"xxl\"\n                >\n                  {t(headerI18nKey)}\n                </Title>\n                <Description size=\"md\" lineHeight=\"md\">\n                  {t(descriptionI18nKey, {\n                    iban: iban.length > 4 ? friendlyFormatIBAN(iban) : iban,\n                  })}\n                </Description>\n              </Flex>\n            }\n            props={{\n              paymentReviewStatus: paymentReviewStatus ?? 'CREATED',\n              iban: iban.length > 4 ? friendlyFormatIBAN(iban) ?? iban : iban,\n            }}\n          />\n\n          <Flex flexDirection=\"column\" gap=\"xl\" width=\"100%\">\n            {!capitalPlus && (\n              <FundingAmountAccordion\n                paymentReviewStatus={paymentReviewStatus}\n              />\n            )}\n            {paymentReviewStatus === 'REJECTED' && (\n              <CustomisationSlot\n                slot=\"more.questions\"\n                props={{}}\n                fallback={<ContactSupport size=\"md\" />}\n              />\n            )}\n          </Flex>\n\n          {paymentReviewStatus !== 'REJECTED' && (\n            <>\n              {capitalPlusDocsShared || financingSetup !== 'CSP' ? null : (\n                <SpeedUpTheProcessCallout />\n              )}\n              <CustomisationSlot\n                slot=\"getFunds.paymentPlanButton\"\n                fallback={\n                  <SeePaymentPlan\n                    hasLatestCreditPaidOut={hasLatestCreditPaidOut}\n                    financingSetup={financingSetup}\n                  />\n                }\n                props={{\n                  hasLatestCreditPaidOut,\n                  financingSetup,\n                }}\n              />\n              {selectedOffer && !capitalPlus && (\n                <FeedbackPopup offerId={selectedOffer.id} />\n              )}\n            </>\n          )}\n          <CustomisationSlot\n            slot=\"getFunds.belowPaymentPlanButton\"\n            props={{}}\n          />\n        </ContentInner>\n      </Content>\n    </Container>\n  );\n};\n","import styled from '@emotion/styled';\nimport { Flex, Typography } from '@finmid/tiger-webapp/components';\n\nexport const Title = styled(Typography)(() => ({\n  width: '100%',\n}));\n\nexport const Subtitle = styled(Typography)(() => ({}));\n\nexport const Page = styled(Flex)(({ theme: { breakpoints, vars } }) => ({\n  justifyContent: 'center',\n  alignItems: 'center',\n\n  padding: vars.components?.variables.spacings.lg,\n\n  [breakpoints.up('desktop')]: {\n    padding: 0,\n    paddingTop: vars.components?.variables.spacings.xxl,\n    paddingBottom: vars.components?.variables.spacings.xxl,\n  },\n}));\n\nexport const Content = styled(Flex)(({ theme: { breakpoints, vars } }) => ({\n  maxWidth: 588,\n  flexDirection: 'column',\n\n  [breakpoints.up('desktop')]: {\n    gap: vars.components?.variables.spacings.xxxl,\n  },\n}));\n\nexport const Illustration = styled(Flex)(({ theme: { vars } }) => ({\n  width: '100%',\n  padding: '58px 0',\n  justifyContent: 'center',\n  alignItems: 'center',\n\n  borderRadius: vars.components?.variables.radius.lg,\n  backgroundColor: vars.components?.variables.colors.grey100,\n}));\n\nexport const IconChip = styled(Flex)(({ theme: { vars } }) => ({\n  color: vars.components?.variables.colors.white,\n  width: 144,\n  height: 144,\n  padding: vars.components?.variables.spacings.lg,\n\n  borderRadius: '100%',\n  backgroundColor: vars.components?.variables.colors.primaryDefault,\n\n  boxShadow:\n    '2.667px -2.667px 5.333px 0 rgba(0, 0, 0, 0.24) inset, 2.667px -2.667px 0 0 rgba(0, 0, 0, 0.12) inset, -2.667px 5.333px 10.667px 0 rgba(0, 0, 0, 0.25)',\n}));\n\nexport const Section = styled(Flex)(({ theme: { breakpoints, vars } }) => ({\n  flexDirection: 'column',\n  gap: vars.components?.variables.spacings.xl,\n\n  [breakpoints.up('desktop')]: {\n    gap: vars.components?.variables.spacings.xxl,\n  },\n}));\n","import {\n  Button,\n  ContactSupport,\n  Flex,\n  Icons,\n  MobileStickyNavigation,\n  useCapturePosthogViewed,\n  useResponsive,\n} from '@finmid/tiger-webapp/components';\nimport { FunctionComponent, useEffect } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { usePhoneUpdatedNotification } from './PhoneUpdateNotification';\nimport {\n  Content,\n  IconChip,\n  Illustration,\n  Page,\n  Section,\n  Subtitle,\n  Title,\n} from './PhoneUpdatedPage.styled';\nimport { usePhoneUpdate } from './usePhoneUpdate';\n\nexport const PhoneUpdatedPage: FunctionComponent = () => {\n  useCapturePosthogViewed('offers:phone_updated_page_viewed');\n  const { t } = useTranslation('offers', {\n    keyPrefix: 'phoneUpdatedPage',\n  });\n\n  const { isPhoneUpdateRequested } = usePhoneUpdate();\n\n  const navigate = useNavigate();\n\n  const { isMobile } = useResponsive();\n\n  const handleContinue = () => navigate('/');\n  const continueText = t('viewOffersButton', 'View offers');\n\n  usePhoneUpdatedNotification();\n\n  useEffect(() => {\n    if (!isPhoneUpdateRequested) navigate('/');\n  }, [isPhoneUpdateRequested, navigate]);\n\n  return (\n    <MobileStickyNavigation\n      onContinue={handleContinue}\n      continueText={continueText}\n      continueButtonTestId=\"view-offers-button\"\n      hideBackButton\n    >\n      <Page>\n        <Content data-test-id=\"phone-updated-page\">\n          {isMobile ? null : (\n            <Illustration>\n              <IconChip>\n                <Icons.MobileLockIcon width={96} />\n              </IconChip>\n            </Illustration>\n          )}\n\n          <Section>\n            <Flex gap=\"sm\" flexDirection=\"column\">\n              <Title\n                size={isMobile ? 'xxl' : 'xl'}\n                family=\"title\"\n                weight=\"strong\"\n              >\n                {t('title', 'We are reviewing your updated phone number')}\n              </Title>\n              <Subtitle size=\"md\">\n                {t('subtitle', {\n                  defaultValue:\n                    'You requested to update your phone number and we are currently reviewing your request. We will get back to within the next business day via email. Once updated, you can complete your {{platform}} {{productName}} offer. ',\n                })}\n              </Subtitle>\n            </Flex>\n\n            <ContactSupport />\n          </Section>\n\n          {isMobile ? null : (\n            <Button\n              data-test-id=\"update-phone-button\"\n              customizationTags={['continue']}\n              variant=\"primary\"\n              onClick={handleContinue}\n              fullWidth\n            >\n              {continueText}\n            </Button>\n          )}\n        </Content>\n      </Page>\n    </MobileStickyNavigation>\n  );\n};\n","import styled from '@emotion/styled';\nimport { customizeStyles } from '@finmid/tiger-webapp/components';\n\nexport const MainContainer = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    display: 'flex',\n    flexDirection: 'column',\n    padding: vars.components?.variables.spacings.md,\n    gap: vars.components?.variables.spacings.md,\n    alignItems: 'center',\n    borderBottom: '1px solid',\n    borderBottomColor: 'inherit',\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.plus?.boostLimit?.mainContainer,\n    ),\n  }),\n);\nexport const SliderContainer = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    display: 'flex',\n    width: '100%',\n    flexDirection: 'column',\n    padding: '46px 48px 0 48px',\n    alignItems: 'center',\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.plus?.boostLimit?.sliderContainer,\n    ),\n  }),\n);\n\nexport const FeeDisclaimer = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    width: '100%',\n    textAlign: 'center',\n    padding: `0 ${vars.components?.variables.spacings.md}`,\n    color: vars.components?.variables.colors?.grey700,\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.plus?.boostLimit?.feeDisclaimer,\n    ),\n  }),\n);\n\nexport const AdjustAmount = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    display: 'flex',\n    gap: vars.components?.variables.spacings.sm,\n    alignItems: 'center',\n    fontSize: vars.components?.variables.typography?.desktop.size?.xs,\n    lineHeight: vars.components?.variables.typography?.desktop.lineHeight?.xs,\n    color: vars.components?.variables.colors?.grey700,\n\n    [breakpoints.down('desktop')]: {\n      display: 'none',\n    },\n\n    svg: {\n      width: 20,\n      height: 20,\n      color: vars.components?.variables.colors.grey700,\n    },\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.plus?.boostLimit?.adjustAmount,\n    ),\n  }),\n);\n","import {\n  createContext,\n  FunctionComponent,\n  PropsWithChildren,\n  useContext,\n  useState,\n} from 'react';\n\ninterface PlusContextValue {\n  newLimit: number | null;\n  setNewLimit: (newLimit: number) => void;\n}\n\nexport const PlusContext = createContext<PlusContextValue>(\n  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion\n  null!,\n);\n\nexport const PlusProvider: FunctionComponent<PropsWithChildren> = ({\n  children,\n}) => {\n  const [newLimit, setNewLimit] = useState<number | null>(null);\n\n  return (\n    <PlusContext.Provider\n      value={{\n        newLimit,\n        setNewLimit,\n      }}\n    >\n      {children}\n    </PlusContext.Provider>\n  );\n};\n\nexport const usePlus = () => {\n  return useContext(PlusContext);\n};\n","import styled from '@emotion/styled';\nimport { customizeStyles, Flex } from '@finmid/tiger-webapp/components';\n\nexport const HeaderSubtitle = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    fontSize: vars.components?.variables.typography?.desktop.size?.sm,\n    fontWeight: vars.components?.variables.typography?.desktop.weight.default,\n    lineHeight: vars.components?.variables.typography?.desktop.lineHeight?.sm,\n\n    [breakpoints.down('desktop')]: {\n      fontSize: vars.components?.variables.typography?.mobile.size?.sm,\n      fontWeight: vars.components?.variables.typography?.mobile.weight.default,\n      lineHeight: vars.components?.variables.typography?.mobile.lineHeight?.sm,\n    },\n\n    ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.headerSubtitle),\n  }),\n);\n\n// TODO: temporarily isolate Card for Plus screens; move back to lib later\nexport const Card = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  alignItems: 'normal',\n  background: theme.vars.components?.variables.colors.white,\n  border: `1px solid ${theme.vars.components?.variables.colors.grey300}`,\n  borderRadius: theme.vars.components?.variables.radius.md,\n  overflow: 'hidden',\n\n  ...customizeStyles(theme, (c) => c?.plus?.card?.container),\n}));\n\nexport const CardHeader = styled(Flex)(({ theme }) => ({\n  flexDirection: 'column',\n  alignItems: 'flex-start',\n  gap: theme.vars.components?.variables.spacings.sm,\n  padding: theme.vars.components?.variables.spacings.md,\n  borderBottom: `1px solid ${theme.vars.components?.variables.colors.grey300}`,\n\n  ...customizeStyles(theme, (c) => c?.plus?.card?.header),\n}));\n","import styled from '@emotion/styled';\nimport { customizeStyles, Typography } from '@finmid/tiger-webapp/components';\nimport { Trans } from 'react-i18next';\n\nexport const Title = ({\n  i18nKey,\n  i18nValues,\n  subtitleI18nKey,\n}: {\n  i18nKey: string;\n  i18nValues?: Record<string, string | number>;\n  subtitleI18nKey?: string;\n}) => {\n  return (\n    <StyledTitle>\n      <Trans\n        i18nKey={i18nKey}\n        components={{ emp: <span className={'title-emphasize'} /> }}\n        values={i18nValues}\n      />\n      {subtitleI18nKey ? (\n        <StyledSubtitle size=\"md\">\n          <Trans i18nKey={subtitleI18nKey} components={{ span: <span /> }} />\n        </StyledSubtitle>\n      ) : null}\n    </StyledTitle>\n  );\n};\n\nconst StyledTitle = styled('div')(({ theme: { breakpoints, vars } }) => ({\n  fontSize: vars.components?.variables.typography?.desktop.size?.xxl,\n  fontWeight: vars.components?.variables.typography?.desktop.weight?.strong,\n  fontFamily: vars.components?.variables.typography?.desktop.family?.title,\n  lineHeight: vars.components?.variables.typography?.desktop.lineHeight?.xxl,\n  paddingBottom: vars.components?.variables.spacings?.xxl,\n  gap: vars.components?.variables.spacings.sm,\n\n  [breakpoints.up('tablet')]: {\n    paddingBottom: vars.components?.variables.spacings?.xxl,\n  },\n\n  [breakpoints.down('desktop')]: {\n    paddingBottom: vars.components?.variables.spacings?.xl,\n    fontSize: vars.components?.variables.typography?.mobile.size?.xxl,\n    fontWeight: vars.components?.variables.typography?.mobile.weight?.strong,\n    lineHeight: vars.components?.variables.typography?.mobile.lineHeight?.xxl,\n  },\n\n  ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.title),\n}));\n\nconst StyledSubtitle = styled(Typography)(\n  ({ theme: { breakpoints, vars } }) => ({\n    marginTop: 8,\n\n    [breakpoints.down('desktop')]: {\n      maxWidth: '100%',\n      '& span': {\n        display: 'none',\n      },\n    },\n\n    ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.subtitle),\n  }),\n);\n\nexport const SecondaryTitle = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    fontSize: vars.components?.variables.typography?.desktop.size.md,\n    lineHeight: vars.components?.variables.typography?.desktop.lineHeight.md,\n    fontWeight: vars.components?.variables.typography?.desktop.weight?.strong,\n\n    [breakpoints.down('desktop')]: {\n      fontSize: vars.components?.variables.typography?.mobile.size.md,\n      lineHeight: vars.components?.variables.typography?.mobile.lineHeight.md,\n      fontWeight: vars.components?.variables.typography?.mobile.weight?.strong,\n    },\n\n    ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.secondaryTitle),\n  }),\n);\n","/**\n * Computes the 9–12 month indicative fee range for a Capital Max payout.\n *\n * `annualPercentageRate` arrives from the BE as a decimal fraction\n * (e.g. `0.055` for 5.5%) — the `/100` conversion is performed server-side so\n * every consumer gets a ready-to-use value. Formula per term:\n *\n *   fee(term) = annualPercentageRate × (term / 12) × amount\n *\n * Returns raw (un-rounded) numbers; formatting/rounding is the caller's\n * responsibility (see `IndicativeFeeRange` which uses `money({ maximumFractionDigits: 0 })`).\n *\n * Returns `null` when the APR is missing or the amount is non-positive, so\n * callers can short-circuit rendering with a single null check.\n */\nexport function calculateCapitalMaxFeeRange(\n  amount: number,\n  annualPercentageRate: number | null | undefined,\n): { low: number; high: number } | null {\n  if (annualPercentageRate == null) return null;\n  if (!Number.isFinite(amount) || amount <= 0) return null;\n\n  return {\n    low: annualPercentageRate * (9 / 12) * amount,\n    high: annualPercentageRate * (12 / 12) * amount,\n  };\n}\n","import styled from '@emotion/styled';\nimport {\n  CustomisationSlot,\n  customized,\n  customizeStyles,\n  Flex,\n  RadiusVariables,\n  Typography,\n} from '@finmid/tiger-webapp/components';\nimport { FunctionComponent, PropsWithChildren, ReactElement } from 'react';\n\nconst LineGroupContainer = customized(\n  Flex,\n  (c) => c?.review?.steps?.lineGroup?.container,\n);\nconst LineGroupCaption = customized(\n  Typography,\n  (c) => c?.review?.steps?.lineGroup?.caption,\n);\n\nexport const LineItemTitle = customized(\n  Typography,\n  (c) => c?.review?.steps?.lineGroup?.item?.title,\n);\nexport const LineItemValue = customized(\n  Typography,\n  (c) => c?.review?.steps?.lineGroup?.item?.value,\n);\nexport const LineItemDetails = customized(\n  Typography,\n  (c) => c?.review?.steps?.lineGroup?.item?.details,\n);\n\nexport const LineItemsContainer = styled('div', {\n  shouldForwardProp: (prop) => !['withShadow', 'radius'].includes(prop),\n})<{ withShadow: boolean; radius?: keyof RadiusVariables }>(\n  ({ theme: { breakpoints, vars }, withShadow, radius = 'sm' }) => ({\n    display: 'flex',\n    flexDirection: 'column',\n    width: '100%',\n    overflow: 'hidden',\n\n    boxShadow: withShadow\n      ? '0px 4px 8px 0px rgba(0, 0, 0, 0.12), 0px 0px 4px 0px rgba(0, 0, 0, 0.12)'\n      : undefined,\n    borderRadius: vars.components?.variables.radius[radius],\n    border: `1px solid ${vars.components?.variables.colors.grey300}`,\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.review?.steps?.lineGroup?.items,\n    ),\n  }),\n);\n\nexport const LineBlock = styled.div(({ theme: { breakpoints, vars } }) => ({\n  display: 'flex',\n  flexDirection: 'column',\n  width: '100%',\n  gap: vars.components?.variables.spacings.sm,\n  padding: vars.components?.variables.spacings.md,\n  backgroundColor: vars.components?.variables.colors.white,\n  overflow: 'hidden',\n\n  '&:not(:last-child)': {\n    borderBottom: `1px solid ${vars.components?.variables.colors.grey300}`,\n  },\n\n  ...customizeStyles(\n    { breakpoints, vars },\n    (c) => c?.review?.steps?.lineGroup?.item?.container,\n  ),\n}));\n\ninterface LineProps {\n  title: string;\n  value: string | ReactElement;\n  details?: string;\n  notice?: ReactElement;\n}\n\nconst DefaultLineItem: FunctionComponent<LineProps> = ({\n  title,\n  value,\n  details,\n  notice,\n}) => {\n  return (\n    <LineBlock data-test-id=\"line-block\">\n      <Flex flexDirection=\"row\" justifyContent=\"space-between\">\n        <LineItemTitle size=\"md\" weight=\"strong\">\n          {title}\n        </LineItemTitle>\n        {typeof value === 'string' ? (\n          <LineItemValue size=\"md\" weight=\"strong\">\n            {value}\n          </LineItemValue>\n        ) : (\n          value\n        )}\n      </Flex>\n      {details && (\n        <LineItemDetails size=\"sm\" weight=\"default\" component=\"div\">\n          <Flex\n            flexDirection=\"column\"\n            gap=\"sm\"\n            alignItems=\"flex-start\"\n            justifyContent=\"flex-start\"\n          >\n            {details}\n            {notice}\n          </Flex>\n        </LineItemDetails>\n      )}\n    </LineBlock>\n  );\n};\n\nexport const LineItem = (props: LineProps) => {\n  return (\n    <CustomisationSlot\n      slot=\"review.line-item\"\n      props={props}\n      fallback={<DefaultLineItem {...props} />}\n    />\n  );\n};\n\nexport const LineGroup: FunctionComponent<\n  PropsWithChildren<{\n    caption?: string;\n    withShadow?: true;\n    radius?: keyof RadiusVariables;\n  }>\n> = ({ children, caption, withShadow = false, radius = 'sm' }) => {\n  return (\n    <LineGroupContainer\n      flexDirection=\"column\"\n      gap=\"sm\"\n      alignItems=\"start\"\n      width=\"100%\"\n    >\n      {caption && (\n        <LineGroupCaption size=\"xs\" weight=\"strong\" color=\"grey700\">\n          {caption}\n        </LineGroupCaption>\n      )}\n      <LineItemsContainer\n        data-test-id=\"line-block\"\n        withShadow={withShadow}\n        radius={radius}\n      >\n        {children}\n      </LineItemsContainer>\n    </LineGroupContainer>\n  );\n};\n","import { useFormat } from '@finmid/translations';\nimport type { Currency } from '@finmid/types';\nimport { useTranslation } from 'react-i18next';\n\nimport { calculateCapitalMaxFeeRange } from './calculateCapitalMaxFeeRange';\n\ninterface UseFormattedCapitalMaxFeeRangeArgs {\n  amount: number;\n  annualPercentageRate: number | null | undefined;\n  currency: Currency;\n}\n\nexport const useFormattedCapitalMaxFeeRange = ({\n  amount,\n  annualPercentageRate,\n  currency,\n}: UseFormattedCapitalMaxFeeRangeArgs) => {\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'plus.boostLimit.indicativeFee',\n  });\n  const { money } = useFormat();\n\n  const range = calculateCapitalMaxFeeRange(amount, annualPercentageRate);\n  const formattedRange = range\n    ? t('range', {\n        defaultValue: '{{low}}-{{high}}',\n        low: money(range.low, currency, { maximumFractionDigits: 0 }),\n        high: money(range.high, currency, { maximumFractionDigits: 0 }),\n      })\n    : null;\n\n  return {\n    formattedRange,\n    title: t('title', { defaultValue: 'Estimated fee' }),\n    termHint: t('termHint', { defaultValue: 'for 9-12 month terms' }),\n    disclaimer: t('disclaimer', {\n      defaultValue:\n        'Please note these fees are estimates and your final terms will be confirmed for your review once your application is processed.',\n    }),\n  };\n};\n","import type { Currency } from '@finmid/types';\n\nimport { LineItem } from '../../../Steps/Review/components/LineItem';\n\nimport { useFormattedCapitalMaxFeeRange } from './useFormattedCapitalMaxFeeRange';\n\ninterface IndicativeFeeRangeProps {\n  amount: number;\n  annualPercentageRate: number | null;\n  currency: Currency;\n}\n\nexport const IndicativeFeeRange = ({\n  amount,\n  annualPercentageRate,\n  currency,\n}: IndicativeFeeRangeProps) => {\n  const { formattedRange, title, termHint } = useFormattedCapitalMaxFeeRange({\n    amount,\n    annualPercentageRate,\n    currency,\n  });\n\n  if (formattedRange == null) return null;\n\n  return (\n    <div aria-live=\"polite\" data-test-id=\"indicative-fee-range\">\n      <LineItem title={title} details={termHint} value={formattedRange} />\n    </div>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport {\n  AispPageWrapper,\n  ButtonsWrapper,\n  useAispEnabled,\n} from '@finmid/tiger-webapp/aisp';\nimport {\n  BusinessAgeCallout,\n  Button,\n  Icons,\n  MobileStickyNavigation,\n  Slider,\n  Typography,\n  useCapturePosthogEvent,\n  useCapturePosthogViewed,\n  useFlowSettings,\n  useTokenContext,\n} from '@finmid/tiger-webapp/components';\nimport {\n  useGetOffers,\n  usePostCapitalPlusRequest,\n} from '@finmid/tiger-webapp/queries';\nimport { useWhatsAppButton } from '@finmid/tiger-webapp/whatsapp';\nimport { useFormat } from '@finmid/translations';\nimport { useMediaQuery } from '@mui/material';\nimport { useLayoutEffect, useRef, useState } from 'react';\nimport { Trans, useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport {\n  AdjustAmount,\n  FeeDisclaimer,\n  MainContainer,\n  SliderContainer,\n} from './BoostLimit.styled';\nimport { usePlus } from './PlusContext';\nimport { Card, CardHeader, HeaderSubtitle } from './PlusPage.styled';\nimport { SecondaryTitle, Title } from './PlusSkeleton';\nimport {\n  IndicativeFeeRange,\n  useFormattedCapitalMaxFeeRange,\n} from './components/IndicativeFeeRange';\n\nexport const BoostLimit = () => {\n  useWhatsAppButton({ overStickyNavigation: true });\n\n  useCapturePosthogViewed('CapitalMax page viewed', {\n    features: {\n      capitalPlus: true,\n    },\n  });\n  const capturePosthogEvent = useCapturePosthogEvent();\n  const { t } = useTranslation('turnkey', { keyPrefix: 'plus.boostLimit' });\n  const { money } = useFormat();\n  const navigate = useNavigate();\n  const { newLimit, setNewLimit } = usePlus();\n  const { breakpoints } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n\n  const { token, ignoreAction } = useTokenContext();\n  const { data } = useGetOffers({ token, ignoreAction });\n\n  const { mutateAsync } = usePostCapitalPlusRequest();\n\n  const isAispEnabled = useAispEnabled('CAPITAL_MAX');\n  const { isCapitalMaxFlow } = useFlowSettings();\n\n  const minOfferLimit = data?.capitalPlus?.minRequestedLimit ?? 0;\n  const maxOfferLimit = data?.capitalPlus?.maxRequestedLimit ?? 0;\n  const annualPercentageRate =\n    data?.capitalPlus?.feeEstimate?.annualPercentageRate ?? null;\n  const currency = data?.currency ?? 'EUR';\n\n  // `committedLimit` updates only on slider release so the indicative fee\n  // doesn't flicker mid-drag; falls back to `minOfferLimit` on first paint.\n  const [committedLimit, setCommittedLimit] = useState<number | null>(null);\n  const indicativeFeeAmount = committedLimit ?? minOfferLimit;\n\n  const { disclaimer } = useFormattedCapitalMaxFeeRange({\n    amount: indicativeFeeAmount,\n    annualPercentageRate,\n    currency,\n  });\n\n  const EDGE_INSET = 16;\n  const sliderContainerRef = useRef<HTMLDivElement>(null);\n  useLayoutEffect(() => {\n    const container = sliderContainerRef.current;\n    if (!container) return;\n    const label = container.querySelector(\n      '.MuiSlider-valueLabel',\n    ) as HTMLElement;\n    if (!label) return;\n    label.style.marginLeft = '0px';\n    const containerRect = container.getBoundingClientRect();\n    const labelRect = label.getBoundingClientRect();\n    let offset = 0;\n    if (labelRect.left < containerRect.left + EDGE_INSET) {\n      offset = containerRect.left + EDGE_INSET - labelRect.left;\n    } else if (labelRect.right > containerRect.right - EDGE_INSET) {\n      offset = containerRect.right - EDGE_INSET - labelRect.right;\n    }\n    if (offset !== 0) {\n      label.style.marginLeft = `${offset}px`;\n    }\n  }, [newLimit, minOfferLimit, maxOfferLimit]);\n\n  const marks = [\n    {\n      value: minOfferLimit,\n      label: money(minOfferLimit, data?.currency ?? 'EUR', {\n        maximumFractionDigits: 0,\n      }),\n    },\n    {\n      value: maxOfferLimit,\n      label: money(maxOfferLimit, data?.currency ?? 'EUR', {\n        maximumFractionDigits: 0,\n      }),\n    },\n  ];\n\n  const captureBackToOverviewEvent = () => {\n    capturePosthogEvent('User navigated to tailored offers', {\n      from: 'capital_max',\n    });\n  };\n\n  const backToOffer = () => {\n    captureBackToOverviewEvent();\n    navigate('/overview');\n  };\n\n  const handleBackOnMobile = () => {\n    captureBackToOverviewEvent();\n    navigate('/overview?step=selectOffer');\n  };\n\n  const nextStep = () => {\n    if (newLimit != null) {\n      capturePosthogEvent('User adjusted CapitalMax limit', {\n        newLimit,\n        minOfferLimit,\n        maxOfferLimit,\n      });\n    } else {\n      capturePosthogEvent('User did not adjust CapitalMax limit', {\n        minOfferLimit,\n        maxOfferLimit,\n      });\n    }\n    mutateAsync({ token, newLimit: newLimit ?? minOfferLimit }).then(() => {\n      if (isAispEnabled) {\n        capturePosthogEvent('User navigated to Aisp page', {\n          from: 'capital_max',\n        });\n        navigate('/plus/aisp-details');\n      } else {\n        capturePosthogEvent('User navigated to CapitalMax upload documents', {\n          from: 'capital_max',\n        });\n        navigate('/plus/upload');\n      }\n    });\n  };\n\n  return (\n    <MobileStickyNavigation\n      onContinue={nextStep}\n      onBack={isCapitalMaxFlow ? undefined : handleBackOnMobile}\n    >\n      <AispPageWrapper hidePrivacyFooter>\n        <Title i18nKey={'plus.boostLimit.selectTitle'} />\n\n        <Card data-test-id=\"boost-limit\">\n          <CardHeader>\n            <SecondaryTitle>{t('selectAmountTitle')}</SecondaryTitle>\n            <HeaderSubtitle>\n              <Trans i18nKey={'plus.boostLimit.description'} />\n            </HeaderSubtitle>\n          </CardHeader>\n\n          <MainContainer>\n            <SliderContainer ref={sliderContainerRef}>\n              <Slider\n                key=\"boost=limit-slider\"\n                data-test-id=\"boost-limit-slider\"\n                thickness={8}\n                min={minOfferLimit}\n                max={maxOfferLimit}\n                marks={marks}\n                step={250}\n                value={newLimit ?? 0}\n                valueLabelDisplay=\"on\"\n                valueLabelFormat={(value) =>\n                  money(value, data?.currency ?? 'EUR', {\n                    maximumFractionDigits: 0,\n                  })\n                }\n                onChange={(_, selectedValue) => {\n                  setNewLimit(Number(selectedValue));\n                }}\n                onChangeCommitted={(_, selectedValue) => {\n                  setCommittedLimit(Number(selectedValue));\n                }}\n              />\n            </SliderContainer>\n            <AdjustAmount>\n              <Icons.ArrowBackIcon />\n              <span>{t('adjustAmount')}</span>\n              <Icons.ArrowForwardIcon />\n            </AdjustAmount>\n          </MainContainer>\n\n          <IndicativeFeeRange\n            amount={indicativeFeeAmount}\n            annualPercentageRate={annualPercentageRate}\n            currency={currency}\n          />\n        </Card>\n\n        {annualPercentageRate != null ? (\n          <FeeDisclaimer>\n            <Typography size=\"sm\" color=\"grey700\">\n              {disclaimer}\n            </Typography>\n          </FeeDisclaimer>\n        ) : null}\n\n        <BusinessAgeCallout />\n\n        {!isMobile ? (\n          <ButtonsWrapper>\n            <Button\n              fullWidth\n              variant=\"primary\"\n              onClick={nextStep}\n              size=\"large\"\n              customizationTags={['plus', 'boostLimit', 'nextStep']}\n            >\n              {t('continueButton')}\n            </Button>\n            {!isCapitalMaxFlow && (\n              <Button\n                fullWidth\n                variant=\"invisible\"\n                onClick={backToOffer}\n                size=\"large\"\n                customizationTags={['plus', 'boostLimit', 'backToOffer']}\n              >\n                {t('backButton')}\n              </Button>\n            )}\n          </ButtonsWrapper>\n        ) : null}\n      </AispPageWrapper>\n    </MobileStickyNavigation>\n  );\n};\n","import styled from '@emotion/styled';\nimport { customizeStyles } from '@finmid/tiger-webapp/components';\n\nexport const Container = styled('div')(({ theme: { breakpoints, vars } }) => ({\n  display: 'flex',\n  flexDirection: 'column',\n  alignItems: 'center',\n  maxWidth: 588,\n  height: '70vh',\n  justifyContent: 'flex-start',\n  margin: '0 auto',\n\n  ...customizeStyles(\n    { breakpoints, vars },\n    (c) => c?.plus?.rejected?.container,\n  ),\n}));\n","import styled from '@emotion/styled';\nimport { customizeStyles } from '@finmid/tiger-webapp/components';\n\nexport const Description = styled('div')(\n  ({ theme: { breakpoints, vars } }) => ({\n    color: vars.components?.variables.colors.grey900,\n    fontWeight: 400,\n    fontFamily: vars.components?.variables.typography.desktop.family.body,\n    fontSize: vars.components?.variables.typography.desktop.size.md,\n    lineHeight: vars.components?.variables.typography.desktop.lineHeight.md,\n\n    [breakpoints.down('desktop')]: {\n      fontFamily: vars.components?.variables.typography.mobile.family.body,\n      fontSize: vars.components?.variables.typography.mobile.size.md,\n      lineHeight: vars.components?.variables.typography.mobile.lineHeight.md,\n    },\n\n    ...customizeStyles(\n      { breakpoints, vars },\n      (c) => c?.plus?.rejected?.description,\n    ),\n  }),\n);\n","import styled from '@emotion/styled';\nimport { customizeStyles } from '@finmid/tiger-webapp/components';\n\nexport const Title = styled('div')(({ theme: { breakpoints, vars } }) => ({\n  width: '100%',\n  color: vars.components?.variables.colors.grey900,\n  fontStyle: 'normal',\n  fontWeight: 700,\n  fontFamily: vars.components?.variables.typography.desktop.family.title,\n  fontSize: vars.components?.variables.typography.desktop.size.xxl,\n  lineHeight: vars.components?.variables.typography.desktop.lineHeight.xxl,\n  marginTop: vars.components?.variables.spacings.xxxl,\n  marginBottom: vars.components?.variables.spacings.sm,\n\n  [breakpoints.down('desktop')]: {\n    fontFamily: vars.components?.variables.typography.mobile.family.title,\n    fontSize: vars.components?.variables.typography.mobile.size.xl,\n    lineHeight: vars.components?.variables.typography.mobile.lineHeight.xl,\n    marginTop: vars.components?.variables.spacings.xl,\n    marginBottom: vars.components?.variables.spacings.sm,\n  },\n\n  ...customizeStyles({ breakpoints, vars }, (c) => c?.plus?.rejected?.title),\n}));\n","import { useTheme } from '@emotion/react';\nimport { AispPageWrapper, useAisp } from '@finmid/tiger-webapp/aisp';\nimport {\n  Button,\n  ContactSupport,\n  CustomisationSlot,\n  NoCodeRejectedIcon,\n  Spacer,\n  useCapturePosthogViewed,\n  useOfferStatus,\n} from '@finmid/tiger-webapp/components';\nimport { FunctionComponent } from 'react';\nimport { Trans, useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { Container, Description, Title } from './components';\n\nconst NoCode = () => {\n  const { vars } = useTheme();\n  return (\n    <>\n      <Spacer height={vars.components?.variables.spacings.xxxl} />\n      <Description>\n        <Trans\n          i18nKey={'plus.rejected.message'}\n          components={{ support: <ContactSupport size=\"md\" /> }}\n        />\n      </Description>\n    </>\n  );\n};\n\nexport const PlusRejectedPage: FunctionComponent = () => {\n  const { provider } = useAisp();\n  const navigate = useNavigate();\n  const { hasCurrentCredit } = useOfferStatus();\n\n  useCapturePosthogViewed('CapitalMax rejected screen viewed', {\n    provider,\n  });\n\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'plus.rejected',\n  });\n\n  return (\n    <AispPageWrapper>\n      <Container id=\"container\" data-test-id=\"plus-rejected-page\">\n        <CustomisationSlot\n          slot=\"plus.rejected.image\"\n          props={{}}\n          fallback={<NoCodeRejectedIcon />}\n        />\n        <Title>{t('title')}</Title>\n        <Description>\n          <CustomisationSlot\n            slot=\"plus.rejected.message\"\n            props={{}}\n            fallback={<NoCode />}\n          />\n        </Description>\n        {hasCurrentCredit && (\n          <>\n            <Spacer height={10} />\n            <Button\n              variant=\"primary\"\n              size=\"large\"\n              fullWidth\n              onClick={() => navigate('/dashboard')}\n              data-test-id=\"back-to-dashboard-button\"\n            >\n              {t('backToDashboard', 'Back to dashboard')}\n            </Button>\n          </>\n        )}\n      </Container>\n    </AispPageWrapper>\n  );\n};\n","import { useMessenger } from '@finmid/tiger-webapp/components';\nimport { useRef, useState } from 'react';\nimport { useSearchParams } from 'react-router-dom';\n\nexport const useConnectingAppsFeedback = () => {\n  const { isEmbedded } = useMessenger();\n  const [thankYouModalIsOpen, setThankYouModalIsOpen] = useState(false);\n  const [hasAnsweredFeedback, setHasAnsweredFeedback] = useState(false);\n  const [searchParams, setSearchParams] = useSearchParams();\n\n  const exitQuestionnaireModal = () => {\n    setSearchParams({});\n  };\n\n  const navigateToQuestionnaireStep = () => {\n    setSearchParams({ appFeedbackModal: 'open' });\n  };\n\n  const navigateToThankYouStep = () => {\n    setSearchParams({});\n    setHasAnsweredFeedback(true);\n    setThankYouModalIsOpen(true);\n  };\n\n  const exitThankYouStep = () => {\n    setThankYouModalIsOpen(false);\n  };\n\n  const questionnaireModalIsOpen =\n    searchParams.get('appFeedbackModal') === 'open';\n\n  const hideMobileStickyNavigation =\n    questionnaireModalIsOpen || (thankYouModalIsOpen && isEmbedded);\n\n  const topRef = useRef<HTMLDivElement>(null);\n\n  return {\n    hasAnsweredFeedback,\n    hideMobileStickyNavigation,\n    questionnaireModalIsOpen,\n    thankYouModalIsOpen,\n    topRef,\n    exitQuestionnaireModal,\n    navigateToQuestionnaireStep,\n    navigateToThankYouStep,\n    exitThankYouStep,\n  };\n};\n","import {\n  usePlatformSettings,\n  useTokenContext,\n} from '@finmid/tiger-webapp/components';\nimport { useGetOffers } from '@finmid/tiger-webapp/queries';\n\nexport const useConnectingAppsFeedbackExperiment = () => {\n  const { token, ignoreAction } = useTokenContext();\n  const { data } = useGetOffers({ token, ignoreAction });\n  const { experiments } = usePlatformSettings();\n\n  const isExperimentEnabled =\n    data?.country &&\n    experiments?.connectingAppsFeedback?.includes(data?.country);\n\n  return isExperimentEnabled;\n};\n","import styled from '@emotion/styled';\nimport {\n  customizeStyles,\n  Flex,\n  Typography,\n} from '@finmid/tiger-webapp/components';\n\nexport const Container = styled(Flex)(({ theme: { vars, breakpoints } }) => ({\n  padding: vars.components?.variables.spacings.md,\n  columnGap: vars.components?.variables.spacings.lg,\n  justifyContent: 'space-between',\n  marginBottom: vars.components?.variables.spacings.md,\n  borderRadius: vars.components?.variables.radius.md,\n  border: `1px solid ${vars.components?.variables.colors.grey300}`,\n  boxShadow:\n    '0px 4px 8px 0px rgba(0, 0, 0, 0.12), 0px 0px 4px 0px rgba(0, 0, 0, 0.12)',\n\n  [breakpoints.down('desktop')]: {\n    flexDirection: 'column',\n    rowGap: vars.components?.variables.spacings.lg,\n    marginTop: vars.components?.variables.spacings.md,\n    marginBottom: 0,\n  },\n\n  ...customizeStyles(\n    { vars, breakpoints },\n    (c) => c?.plus?.upload?.connectingApps?.cta?.container,\n  ),\n}));\n\nexport const InnerContainer = styled(Flex)(\n  ({ theme: { vars, breakpoints } }) => ({\n    flexDirection: 'column',\n    alignItems: 'flex-start',\n    rowGap: vars.components?.variables.spacings.sm,\n\n    [breakpoints.down('desktop')]: {},\n    ...customizeStyles(\n      { vars, breakpoints },\n      (c) => c?.plus?.upload?.connectingApps?.cta?.innerContainer,\n    ),\n  }),\n);\n\nexport const Title = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(\n    theme,\n    (c) => c?.plus?.upload?.connectingApps?.cta?.containerTitle,\n  ),\n}));\n\nexport const SubTitle = styled(Typography)(({ theme }) => ({\n  ...customizeStyles(\n    theme,\n    (c) => c?.plus?.upload?.connectingApps?.cta?.containerSubTitle,\n  ),\n}));\n","import { useTheme } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { Button, customizeStyles } from '@finmid/tiger-webapp/components';\nimport { useMediaQuery } from '@mui/material';\nimport { useTranslation } from 'react-i18next';\n\nconst StyledTriggerButton = styled(Button)(({ theme }) => ({\n  ...customizeStyles(\n    theme,\n    (c) => c?.plus?.upload?.connectingApps?.cta?.containerButton,\n  ),\n}));\n\ntype Props = {\n  handleSubmit: () => void;\n};\n\nexport const TriggerButton = ({ handleSubmit }: Props) => {\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'plus.upload.connectingApps',\n  });\n  const { breakpoints } = useTheme();\n  const isMobile = useMediaQuery(breakpoints.down('desktop'));\n\n  return (\n    <StyledTriggerButton\n      onClick={handleSubmit}\n      variant=\"secondary\"\n      fullWidth={isMobile}\n    >\n      {t('ctaButton', 'Request')}\n    </StyledTriggerButton>\n  );\n};\n","import { useTranslation } from 'react-i18next';\n\nimport { useConnectingAppsFeedbackExperiment } from '../../../useConnectingAppsFeedbackExperiment';\n\nimport {\n  Container,\n  InnerContainer,\n  Title,\n  SubTitle,\n} from './ConnectingAppsFeedback.styled';\nimport { TriggerButton } from './TriggerButton';\n\nexport const ConnectingAppsFeedback = ({\n  hasAnsweredFeedback,\n  openModal,\n}: {\n  hasAnsweredFeedback: boolean;\n  openModal: () => void;\n}) => {\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'plus.upload.connectingApps',\n  });\n  const connectingAppsFeedbackEnabled = useConnectingAppsFeedbackExperiment();\n\n  if (hasAnsweredFeedback || !connectingAppsFeedbackEnabled) {\n    return null;\n  }\n\n  return (\n    <Container>\n      <InnerContainer>\n        <Title size=\"md\" weight=\"strong\">\n          {t('ctaTitle', 'Interested in connecting financial applications?')}\n        </Title>\n        <SubTitle size=\"sm\" color=\"grey700\">\n          {t('ctaSubtitle', 'Help us improve by sharing your preferences!')}\n        </SubTitle>\n      </InnerContainer>\n      <TriggerButton handleSubmit={openModal} />\n    </Container>\n  );\n};\n","import { Button } from '@finmid/tiger-webapp/components';\nimport { useTranslation } from 'react-i18next';\n\ntype BackToUploadPageButtonProps = {\n  handleSubmit: () => void;\n};\n\nexport const BackToUploadPageButton = ({\n  handleSubmit,\n}: BackToUploadPageButtonProps) => {\n  const { t } = useTranslation('turnkey', {\n    keyPrefix: 'plus.upload.connectingApps',\n  });\n  return (\n    <Button variant=\"primary\" onClick={handleSubmit}>\n      {t('returnToUpload', 'Return to upload')}\n    </Button>\n  );\n};\n","export const IconDinero = () => (\n  <svg\n    xmlns=\"http://www.w3.org/2000/svg\"\n    width=\"24\"\n    height=\"25\"\n    viewBox=\"0 0 24 25\"\n    fill=\"none\"\n  >\n    <g clipPath=\"url(#clip0_15612_3869)\">\n      <path\n        d=\"M22.3767 18.159C21.1279 20.3237 19.2225 22.0348 16.9365 23.0447C14.6505 24.0545 12.1025 24.3107 9.66117 23.7761C7.21989 23.2416 5.01206 21.944 3.35727 20.0712C1.70249 18.1984 0.686604 15.8476 0.456679 13.3591C0.226755 10.8706 0.794718 8.37344 2.07835 6.22917C3.36199 4.08489 5.2947 2.40474 7.59671 1.43192C9.89872 0.459097 12.4506 0.244081 14.8829 0.817995C17.3153 1.39191 19.5018 2.72497 21.1262 4.62423L14.2736 16.4979C13.726 